CREATE FUNCTION [dbo].[UDF_GET_LOWEST_ACTUALPRICE_DATA] (@ItemPriceID INT, @ItemCodeID INT, @CategoryID INT, @Mrp DECIMAL(18, 2), @SalePrice DECIMAL(18, 2))
RETURNS @LeastPrice TABLE (
		ITEMPRICID INT,
        OFFERNAME VARCHAR(100),
        ACTUALPRICE DECIMAL(18, 2)
    )
AS
BEGIN
    
	INSERT INTO @LeastPrice
	SELECT 
		TOP 1 @ItemPriceID, OFRPRICES.OFFERNAME
		, CASE 
			WHEN OFFERTYPECODE = 'DF' THEN @Mrp - OFFERVALUE
			WHEN OFFERTYPECODE = 'FR' THEN OFFERVALUE
			WHEN OFFERTYPECODE = 'DP' THEN @Mrp - (@Mrp * OFFERVALUE / 100)
			ELSE @SalePrice END
	FROM
		(
			SELECT ISNULL('BASE OFFER: ' + BOFR.OFFERNAME, 'OFFER: ' + OFR.OFFERNAME) OFFERNAME, OFRTYP.OFFERTYPECODE, OFR.OFFERVALUE
			FROM
				OFFERITEMMAP OFRITMMAP
				INNER JOIN OFFER OFR ON OFR.OFFERID = OFRITMMAP.OFFERID
				INNER JOIN OFFERTYPE OFRTYP ON OFRTYP.OFFERTYPEID = OFR.OFFERTYPEID				
				LEFT JOIN BASEOFFER BOFR ON BOFR.BASEOFFERID = OFR.BASEOFFERID
			WHERE
				OFRITMMAP.DELETEDBY IS NULL
				AND OFR.DELETEDDATE IS NULL
				AND ISNULL(ISNULL(OFR.ENDDATE, BOFR.ENDDATE), '2100-01-01') > GETDATE()
				AND OFR.OFFERTYPEID IN (1, 2, 3)
				AND OFR.APPLIESTOID = 1
				AND OFRITMMAP.ITEMCODEID = @ItemCodeID

			UNION ALL

			SELECT ISNULL('BASE OFFER: ' + BOFR.OFFERNAME, 'OFFER: ' + OFR.OFFERNAME) OFFERNAME, OFRTYP.OFFERTYPECODE, OFR.OFFERVALUE
			FROM
				OFFER OFR 
				INNER JOIN OFFERTYPE OFRTYP ON OFRTYP.OFFERTYPEID = OFR.OFFERTYPEID						
				LEFT JOIN BASEOFFER BOFR ON BOFR.BASEOFFERID = OFR.BASEOFFERID
			WHERE
				OFR.DELETEDDATE IS NULL
				AND ISNULL(ISNULL(OFR.ENDDATE, BOFR.ENDDATE), '2100-01-01') > GETDATE()
				AND OFR.OFFERTYPEID IN (1, 2, 3)
				AND OFR.APPLIESTOID = 3
				AND OFR.CATEGORYID = @CategoryID

			UNION ALL
			
			SELECT 'Sale Price', NULL, @SalePrice
		) OFRPRICES
	ORDER BY 3

	RETURN
END
GO
/****** Object:  UserDefinedFunction [dbo].[UDF_GET_LOWEST_ACTUALPRICE_DATA_OFFER]    Script Date: 17-10-2026 13:04:45 ******/
SET ANSI_NULLS ON
