CREATE FUNCTION [dbo].[UDF_GET_LOWEST_ACTUALPRICE_DATA_OFFER] (@ItemPriceID INT, @ItemCodeID INT, @CategoryID INT, @Mrp DECIMAL(18, 2), @SalePrice DECIMAL(18, 2))
RETURNS VARCHAR(200)
AS
BEGIN
	
	DECLARE @OfferName VARCHAR(200)

	SELECT @OfferName = OFFERNAME
	FROM
		dbo.UDF_GET_LOWEST_ACTUALPRICE_DATA(@ItemPriceID, @ItemCodeID, @CategoryID, @Mrp, @SalePrice)
		
	RETURN @OfferName

END
GO
/****** Object:  UserDefinedFunction [dbo].[UDF_GET_LOWEST_ACTUALPRICE_DATA_PRICE]    Script Date: 17-10-2026 13:04:45 ******/
SET ANSI_NULLS ON
