CREATE FUNCTION [dbo].[UDF_GET_LOWEST_ACTUALPRICE_DATA_PRICE] (@ItemPriceID INT, @ItemCodeID INT, @CategoryID INT, @Mrp DECIMAL(18, 2), @SalePrice DECIMAL(18, 2))
RETURNS DECIMAL(18, 2)
AS
BEGIN
	
	DECLARE @ActualPrice DECIMAL(18, 2)

	SELECT @ActualPrice = ACTUALPRICE
	FROM
		dbo.UDF_GET_LOWEST_ACTUALPRICE_DATA(@ItemPriceID, @ItemCodeID, @CategoryID, @Mrp, @SalePrice)
		
	RETURN @ActualPrice

END
