SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[UDF_GETOFFERS] (@ItemPriceID INT)   
RETURNS @Offer TABLE (ITEMPRICEID INT, OFFERID INT)  
AS  
BEGIN  
  
 DECLARE @ItemCodeID INT, @CategoryID INT, @MaxDate DATE, @OfferID INT, @DealID INT  
 SELECT @MaxDate = '2100-01-01'    
  
 SELECT @ItemCodeID = IC.ITEMCODEID, @CategoryID = I.CATEGORYID  
 FROM   
  ITEMPRICE IP  
  INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID  
  INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID  
 WHERE IP.ITEMPRICEID = @ItemPriceID  
  
 INSERT INTO @Offer  (ITEMPRICEID, OFFERID)
 SELECT @ItemPriceID, OFR.OFFERID
 FROM  
  OFFER OFR
  LEFT JOIN BASEOFFER BO ON OFR.BASEOFFERID = BO.BASEOFFERID
 WHERE   
  GETDATE() BETWEEN ISNULL(OFR.STARTDATE, BO.STARTDATE) AND ISNULL(ISNULL(OFR.ENDDATE, BO.ENDDATE), @MaxDate)  
  AND OFR.ISACTIVE = 1  
  AND OFR.DELETEDDATE IS NULL  
  AND   
   (  
		EXISTS (SELECT 1 FROM OFFERITEMMAP OFRIM WHERE OFRIM.OFFERID = OFR.OFFERID AND OFRIM.ITEMCODEID = @ItemCodeID AND OFRIM.DELETEDDATE IS NULL)  
		OR OFR.CATEGORYID = @CategoryID  
   )  
 ORDER BY OFFERID DESC  
 RETURN  
END
GO
/****** Object:  UserDefinedFunction [dbo].[UDF_ROUND_QTY_BY_CASE]    Script Date: 17-10-2026 13:04:45 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   FUNCTION [dbo].[UDF_ROUND_QTY_BY_CASE]
(
	@RequiredQty DECIMAL(18, 2)
	, @OuterCaseQty INT = NULL
	, @InnerCaseQty INT = NULL
)
RETURNS DECIMAL(18, 2) AS
BEGIN

	DECLARE @RemainderQty DECIMAL(18, 2), @OuterCases INT = 0, @InnerCases INT = 0, @QtyToAdd INT
	
	SELECT @RemainderQty = @RequiredQty

	IF ISNULL(@OuterCaseQty, 0) > 0 AND (@RemainderQty * 100 / @OuterCaseQty) > 80
	BEGIN
		SELECT @OuterCases = @RequiredQty / @OuterCaseQty
		SELECT @RemainderQty = @RequiredQty - (@OuterCases * @OuterCaseQty)
		SELECT @QtyToAdd = CASE WHEN @RemainderQty > 0 AND (@RemainderQty * 100 / @OuterCaseQty) > 80 THEN @OuterCaseQty ELSE 0 END
	END
	
	IF ISNULL(@InnerCaseQty, 0) > 0 AND @RemainderQty > 0 AND (@RemainderQty * 100 / @InnerCaseQty) > 80
	BEGIN
		SELECT @InnerCases = @RemainderQty / @InnerCaseQty
		SELECT @RemainderQty = @RemainderQty - (@InnerCases * @InnerCaseQty)
		SELECT @QtyToAdd = CASE WHEN @RemainderQty > 0 AND (@RemainderQty * 100 / @InnerCaseQty) > 80 THEN @InnerCaseQty ELSE 0 END
	END
		
	RETURN ISNULL(@OuterCases * @OuterCaseQty, 0) + ISNULL(@InnerCases * @InnerCaseQty, 0) + ISNULL(@QtyToAdd, 0)
END
GO
