CREATE VIEW [dbo].[IPICPView] AS  

SELECT IP.ITEMPRICEID, ICP.ITEMCOSTPRICEID, ICP.COSTPRICEWOT, ICP.COSTPRICEWT, ICP.GROSSCOSTPRICEWOT, ICP.GROSSCOSTPRICEWT, ICP.GSTID
FROM
	ITEMPRICE IP
	LEFT JOIN 
		(  
				SELECT ICPINNER.ITEMPRICEID, MAX(ICPINNER.ITEMCOSTPRICEID) AS LASTCOSTPRICEID  
				FROM ITEMCOSTPRICE ICPINNER  
				WHERE ICPINNER.DELETEDBY IS NULL AND ICPINNER.COSTPRICEWT <> 0
				GROUP BY ICPINNER.ITEMPRICEID  
		) LICP ON LICP.ITEMPRICEID = IP.ITEMPRICEID
	LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = LICP.LASTCOSTPRICEID
