/****** Object:  View [dbo].[ITEMCOSTPRICEVIEW]    Script Date: 17-10-2026 13:04:45 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [dbo].[ITEMCOSTPRICEVIEW] AS
	--SELECT  
	--LICP.ITEMCODEID, ICP.COSTPRICEWOT, ICP.COSTPRICEWT
	--FROM(
	--	SELECT ICINNER.ITEMCODEID, MAX(ICPINNER.ITEMCOSTPRICEID) AS LASTCOSTPRICEID
	--	FROM 
	--		ITEMCOSTPRICE ICPINNER
	--		INNER JOIN ITEMPRICE IPINNER ON IPINNER.ITEMPRICEID = ICPINNER.ITEMPRICEID
	--		INNER JOIN ITEMCODE ICINNER ON ICINNER.ITEMCODEID = IPINNER.ITEMCODEID
	--	WHERE
	--		ICPINNER.DELETEDDATE IS NULL AND IPINNER.DELETEDDATE IS NULL AND ICPINNER.COSTPRICEWT <> 0
	--	GROUP BY ICINNER.ITEMCODEID
	--) LICP LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = LICP.LASTCOSTPRICEID

	SELECT IC.ITEMCODEID
		, ICP.COSTPRICEWOT * CASE WHEN I.PARENTITEMID IS NULL THEN 1 ELSE ISNULL(UOM.MULTIPLIER, 1) END AS COSTPRICEWOT
		, ICP.COSTPRICEWT * CASE WHEN I.PARENTITEMID IS NULL THEN 1 ELSE ISNULL(UOM.MULTIPLIER, 1) END AS COSTPRICEWT
	FROM
		ITEMCODE IC 
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN UOM UOM ON UOM.UOMID = I.UOMID
		LEFT JOIN ITEMCODE PIC ON PIC.ITEMID = I.PARENTITEMID
		LEFT JOIN
			(
				SELECT IPINNER.ITEMCODEID, MAX(ICPINNER.ITEMCOSTPRICEID) AS LASTCOSTPRICEID
				FROM 
					ITEMCOSTPRICE ICPINNER
					INNER JOIN ITEMPRICE IPINNER ON IPINNER.ITEMPRICEID = ICPINNER.ITEMPRICEID
				WHERE
					ICPINNER.DELETEDDATE IS NULL AND IPINNER.DELETEDDATE IS NULL AND ICPINNER.COSTPRICEWT <> 0
				GROUP BY IPINNER.ITEMCODEID
			) ICPMAX ON ICPMAX.ITEMCODEID = CASE WHEN I.PARENTITEMID IS NULL THEN IC.ITEMCODEID ELSE PIC.ITEMCODEID END
		LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = ICPMAX.LASTCOSTPRICEID
GO
