CREATE VIEW [dbo].[ITEMPRICEVIEW] AS
SELECT ICINNER.ITEMCODEID, AVG(MRP) AS MRP,AVG(SALEPRICE) AS SALEPRICE
FROM 
	ITEMPRICE IP 
	INNER JOIN ITEMCODE ICINNER ON ICINNER.ITEMCODEID = IP.ITEMCODEID
WHERE IP.DELETEDDATE IS NULL
GROUP BY ICINNER.ITEMCODEID
