/****** Object:  StoredProcedure [dbo].[DEBUG_USP_PURCHASE_STOCKSUMMARY_RECON]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* ============================================================================
   USP_DEBUG_PURCHASE_STOCKSUMMARY_RECON
   ----------------------------------------------------------------------------
   Purpose : Debug WHY Purchase (Stock Entry) totals disagree with StockSummary
             updates (STOCKSUMMARYLOG, TTYPE = 'SE'), DATE-WISE.

             Compares, per day:
                 Stock Entry transactions  (STOCKENTRY / STOCKENTRYDETAIL)
                       vs
                 StockSummary updates      (STOCKSUMMARYLOG WHERE TTYPE = 'SE')

   Date window
        Upper bound : @ToDate (exclusive, same style as the reference procs).
        Lower bound : PER ITEM last counting date, derived exactly like the
                      item ledger in DEBUG_USP_SS_STOCKSUMMARYLOG_WH
                      (COUNTINGAPPROVAL -> item / subcategory / category,
                       floored to the financial-year start). Both the purchase
                       side and the stocksummary side use this same per-item
                       boundary, so the two sides are compared over the very
                       same range the ledger uses.

   Purchase side is dated by STOCKENTRY.UPDATEDATE (not CREATEDDATE); the
   stocksummary side is dated by STOCKSUMMARYLOG.CREATEDDATE.

   Business logic reused unchanged from:
        - USP_RPT_PURCHASES                 (purchase joins + open-item qty calc)
        - DEBUG_USP_SS_STOCKSUMMARYLOG_WH   (counting-date logic + SS change calc)

   Output : single date-wise result set with per-day deviations.
   ============================================================================ */
CREATE PROC [dbo].[DEBUG_USP_PURCHASE_STOCKSUMMARY_RECON]
(
	@ITEMID     INT  = 0       -- 0 = all items
    , @ToDate     DATE = NULL   -- defaults to today; used as exclusive upper bound
    , @BranchID   INT  = 45
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FinYearStartDate DATE = '2023-04-01';

    /* Exclusive upper bound, same handling as the reference procedures. */
    IF @ToDate IS NULL
        SET @ToDate = CAST(GETDATE() AS DATE);
    SET @ToDate = DATEADD(DAY, 1, @ToDate);

    IF OBJECT_ID('tempdb..#ItemBase')      IS NOT NULL DROP TABLE #ItemBase;
    IF OBJECT_ID('tempdb..#PurchaseByDate') IS NOT NULL DROP TABLE #PurchaseByDate;
    IF OBJECT_ID('tempdb..#SSByDate')       IS NOT NULL DROP TABLE #SSByDate;

    /* ========================================================================
       STEP 1  #ItemBase  -  PER ITEM last counting date
       (copied from DEBUG_USP_SS_STOCKSUMMARYLOG_WH, unchanged)
       ======================================================================== */
    SELECT
          I.ITEMID
        , I.SKUCODE
        , I.ITEMNAME
        , I.CATEGORYID
        , I.SUBCATEGORYID
        , ISNULL(I.ISOPENITEM, 0)          AS ISOPENITEM
        , CAST(NULL AS DATETIME)           AS LASTCOUNTINGDATE
    INTO #ItemBase
    FROM ITEM I
    WHERE I.ITEMID = @ITEMID OR @ITEMID = 0;

    /* item-level counting date */
    UPDATE IB
    SET IB.LASTCOUNTINGDATE = CAI.LASTCOUNTINGDATE
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT IC.ITEMID, MAX(CAI.CREATEDDATE) AS LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALITEM CAI
        INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
        INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CAI.ITEMPRICEID
        INNER JOIN ITEMCODE  IC ON IC.ITEMCODEID  = IP.ITEMCODEID
        WHERE CA.BRANCHID = @BranchID
          AND CAI.CREATEDDATE < @ToDate
        GROUP BY IC.ITEMID
    ) CAI ON CAI.ITEMID = IB.ITEMID;

    /* subcategory-level counting date */
    UPDATE IB
    SET IB.LASTCOUNTINGDATE =
        CASE WHEN CAC.LASTCOUNTINGDATE > ISNULL(IB.LASTCOUNTINGDATE, '1900-01-01')
             THEN CAC.LASTCOUNTINGDATE ELSE IB.LASTCOUNTINGDATE END
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT CAC.SUBCATEGORYID, MAX(CAC.CREATEDDATE) AS LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALCATEGORYMAP CAC
        INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
        WHERE CA.BRANCHID = @BranchID
          AND CAC.CREATEDDATE < @ToDate
          AND CAC.SUBCATEGORYID IS NOT NULL
        GROUP BY CAC.SUBCATEGORYID
    ) CAC ON CAC.SUBCATEGORYID = IB.SUBCATEGORYID;

    /* category-level counting date (only where still unset) */
    UPDATE IB
    SET IB.LASTCOUNTINGDATE = CAC.LASTCOUNTINGDATE
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT CAC.CATEGORYID, MAX(CAC.CREATEDDATE) AS LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALCATEGORYMAP CAC
        INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
        WHERE CA.BRANCHID = @BranchID
          AND CAC.CREATEDDATE < @ToDate
          AND CAC.CATEGORYID IS NOT NULL
        GROUP BY CAC.CATEGORYID
    ) CAC ON CAC.CATEGORYID = IB.CATEGORYID
    WHERE IB.LASTCOUNTINGDATE IS NULL;

    /* floor to a real date, then to financial-year start */
    UPDATE #ItemBase SET LASTCOUNTINGDATE = ISNULL(LASTCOUNTINGDATE, '1900-01-01');
    UPDATE #ItemBase SET LASTCOUNTINGDATE = @FinYearStartDate
    WHERE LASTCOUNTINGDATE < @FinYearStartDate;

    /* ========================================================================
       STEP 2  PURCHASE SIDE by date
       (joins + filters + open-item qty calc from USP_RPT_PURCHASES)
       lower bound = per-item LASTCOUNTINGDATE from #ItemBase
       ======================================================================== */
    SELECT
          CAST(SE.UPDATEDATE AS DATE)                                    AS TXNDATE
        , CAST(SUM(CASE WHEN IB.ISOPENITEM = 0
                        THEN ISNULL(SED.QUANTITY, 0)
                        ELSE ISNULL(SED.WEIGHTINKGS, 0) END)
               AS DECIMAL(18, 2))                                         AS PURCHASEQTY   -- open-item aware
        , CAST(SUM(ISNULL(SED.QUANTITY, 0))    AS DECIMAL(18, 2))         AS PURCHASERAWQTY
        , CAST(SUM(ISNULL(SED.WEIGHTINKGS, 0)) AS DECIMAL(18, 2))         AS PURCHASEWEIGHT
    INTO #PurchaseByDate
    FROM STOCKENTRYDETAIL SED WITH (NOLOCK)
        INNER JOIN STOCKENTRY    SE  WITH (NOLOCK) ON SE.STOCKENTRYID     = SED.STOCKENTRYID
        INNER JOIN ITEMCOSTPRICE ICP WITH (NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
        INNER JOIN ITEMPRICE     IP  WITH (NOLOCK) ON IP.ITEMPRICEID      = ICP.ITEMPRICEID
        INNER JOIN ITEMCODE      IC  WITH (NOLOCK) ON IC.ITEMCODEID       = IP.ITEMCODEID
        INNER JOIN #ItemBase     IB                ON IB.ITEMID           = IC.ITEMID
    WHERE SE.UPDATEDATE   > IB.LASTCOUNTINGDATE
      AND SE.UPDATEDATE   < @ToDate
      AND SED.DELETEDDATE IS NULL
      AND SE.STATUS       = 1
    GROUP BY CAST(SE.UPDATEDATE AS DATE);

    /* ========================================================================
       STEP 3  STOCKSUMMARY SIDE by date  (TTYPE = 'SE')
       (joins + change calc from DEBUG_USP_SS_STOCKSUMMARYLOG_WH)
       lower bound = same per-item LASTCOUNTINGDATE
       ======================================================================== */
    SELECT
          CAST(SSL.CREATEDDATE AS DATE)                                   AS TXNDATE
        , CAST(SUM(CASE WHEN IB.ISOPENITEM = 1
                        THEN ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0)
                        ELSE ISNULL(SSL.QUANTITY, 0)    - ISNULL(SSL.OLDQTY, 0) END)
               AS DECIMAL(18, 2))                                         AS SSQTY          -- open-item aware
        , CAST(SUM(ISNULL(SSL.QUANTITY, 0)   - ISNULL(SSL.OLDQTY, 0))    AS DECIMAL(18, 2)) AS SSRAWQTY
        , CAST(SUM(ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0)) AS DECIMAL(18, 2)) AS SSWEIGHT
    INTO #SSByDate
    FROM STOCKSUMMARY SS WITH (NOLOCK)
        INNER JOIN STOCKSUMMARYLOG SSL WITH (NOLOCK) ON SSL.STOCKSUMMARYID = SS.STOCKSUMMARYID
        INNER JOIN ITEMPRICE       IP  WITH (NOLOCK) ON IP.ITEMPRICEID     = SS.ITEMPRICEID
        INNER JOIN ITEMCODE        IC  WITH (NOLOCK) ON IC.ITEMCODEID      = IP.ITEMCODEID
        INNER JOIN #ItemBase       IB                ON IB.ITEMID          = IC.ITEMID
    WHERE SS.BRANCHID     = @BranchID
      AND SSL.TTYPE       = 'SE'
      AND SSL.CREATEDDATE > IB.LASTCOUNTINGDATE
      AND SSL.CREATEDDATE < @ToDate
    GROUP BY CAST(SSL.CREATEDDATE AS DATE);

    /* ========================================================================
       RESULT  -  DATE-WISE reconciliation
       FULL OUTER JOIN so a day present on only one side still shows.
       Order by date -> the first day with a non-zero difference is where the
       deviation occurs.
       ======================================================================== */
    SELECT
          COALESCE(P.TXNDATE, S.TXNDATE)                                  AS TxnDate
        , ISNULL(P.PURCHASEQTY, 0)                                        AS PurchaseQuantity
        , ISNULL(S.SSQTY, 0)                                              AS StockSummaryQuantity
        , CAST(ISNULL(P.PURCHASEQTY, 0) - ISNULL(S.SSQTY, 0) AS DECIMAL(18,2)) AS QuantityDifference
        , ISNULL(P.PURCHASEWEIGHT, 0)                                     AS PurchaseWeight
        , ISNULL(S.SSWEIGHT, 0)                                           AS StockSummaryWeight
        , CAST(ISNULL(P.PURCHASEWEIGHT, 0) - ISNULL(S.SSWEIGHT, 0) AS DECIMAL(18,2)) AS WeightDifference
    FROM #PurchaseByDate P
        FULL OUTER JOIN #SSByDate S ON S.TXNDATE = P.TXNDATE
    ORDER BY TxnDate;

END;
GO
/****** Object:  StoredProcedure [dbo].[DEBUG_USP_PURCHASE_STOCKSUMMARY_RECON_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* ============================================================================
   DEBUG_USP_PURCHASE_STOCKSUMMARY_RECON
   ----------------------------------------------------------------------------
   Purpose : Debug WHY Purchase (Stock Entry) totals disagree with StockSummary
             updates, DATE-WISE, and show EXACTLY what happened each day.

   Two result sets:
     RESULT 1  Date-wise SE-vs-Purchase comparison (the anchor / summary).
               StockSummary side = TTYPE = 'SE' only.

     RESULT 2  Per-day MOVEMENT LEDGER grouped by (date, TTYPE).
               ALL TTYPEs are shown (no SE-only filter), plus a synthetic
               'PURCHASE' line per day. This reveals reverts / branch returns
               etc. that make the SE column look wrong. Example: a day may show
               SE +93, a revert -10 and a branch return +10, reconciling to a
               purchase of 83.

   Date window
        Upper bound : @ToDate (exclusive, same style as the reference procs).
        Lower bound : PER ITEM last counting date, derived exactly like the
                      item ledger in DEBUG_USP_SS_STOCKSUMMARYLOG_WH.

   Purchase side is dated by STOCKENTRY.UPDATEDATE; the stocksummary side is
   dated by STOCKSUMMARYLOG.CREATEDDATE.

   Business logic reused unchanged from:
        - USP_RPT_PURCHASES                 (purchase joins + open-item qty calc)
        - DEBUG_USP_SS_STOCKSUMMARYLOG_WH   (counting-date logic + SS change calc
                                             + TTYPE buckets)
   ============================================================================ */
CREATE PROC [dbo].[DEBUG_USP_PURCHASE_STOCKSUMMARY_RECON_v2]
(
      @ITEMID     INT  = 0       -- 0 = all items
    , @ToDate     DATE = NULL    -- defaults to today; used as exclusive upper bound
    , @BranchID   INT  = 45
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FinYearStartDate DATE = '2023-04-01';

    /* Exclusive upper bound, same handling as the reference procedures. */
    IF @ToDate IS NULL
        SET @ToDate = CAST(GETDATE() AS DATE);
    SET @ToDate = DATEADD(DAY, 1, @ToDate);

    IF OBJECT_ID('tempdb..#ItemBase')       IS NOT NULL DROP TABLE #ItemBase;
    IF OBJECT_ID('tempdb..#PurchaseByDate')  IS NOT NULL DROP TABLE #PurchaseByDate;
    IF OBJECT_ID('tempdb..#SSByDate')        IS NOT NULL DROP TABLE #SSByDate;
    IF OBJECT_ID('tempdb..#SSMoveByDate')    IS NOT NULL DROP TABLE #SSMoveByDate;

    /* ========================================================================
       STEP 1  #ItemBase  -  PER ITEM last counting date
       (copied from DEBUG_USP_SS_STOCKSUMMARYLOG_WH, unchanged)
       ======================================================================== */
    SELECT
          I.ITEMID
        , I.SKUCODE
        , I.ITEMNAME
        , I.CATEGORYID
        , I.SUBCATEGORYID
        , ISNULL(I.ISOPENITEM, 0)          AS ISOPENITEM
        , CAST(NULL AS DATETIME)           AS LASTCOUNTINGDATE
    INTO #ItemBase
    FROM ITEM I
    WHERE I.ITEMID = @ITEMID OR @ITEMID = 0;

    /* item-level counting date */
    UPDATE IB
    SET IB.LASTCOUNTINGDATE = CAI.LASTCOUNTINGDATE
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT IC.ITEMID, MAX(CAI.CREATEDDATE) AS LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALITEM CAI
        INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
        INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CAI.ITEMPRICEID
        INNER JOIN ITEMCODE  IC ON IC.ITEMCODEID  = IP.ITEMCODEID
        WHERE CA.BRANCHID = @BranchID
          AND CAI.CREATEDDATE < @ToDate
        GROUP BY IC.ITEMID
    ) CAI ON CAI.ITEMID = IB.ITEMID;

    /* subcategory-level counting date */
    UPDATE IB
    SET IB.LASTCOUNTINGDATE =
        CASE WHEN CAC.LASTCOUNTINGDATE > ISNULL(IB.LASTCOUNTINGDATE, '1900-01-01')
             THEN CAC.LASTCOUNTINGDATE ELSE IB.LASTCOUNTINGDATE END
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT CAC.SUBCATEGORYID, MAX(CAC.CREATEDDATE) AS LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALCATEGORYMAP CAC
        INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
        WHERE CA.BRANCHID = @BranchID
          AND CAC.CREATEDDATE < @ToDate
          AND CAC.SUBCATEGORYID IS NOT NULL
        GROUP BY CAC.SUBCATEGORYID
    ) CAC ON CAC.SUBCATEGORYID = IB.SUBCATEGORYID;

    /* category-level counting date (only where still unset) */
    UPDATE IB
    SET IB.LASTCOUNTINGDATE = CAC.LASTCOUNTINGDATE
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT CAC.CATEGORYID, MAX(CAC.CREATEDDATE) AS LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALCATEGORYMAP CAC
        INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
        WHERE CA.BRANCHID = @BranchID
          AND CAC.CREATEDDATE < @ToDate
          AND CAC.CATEGORYID IS NOT NULL
        GROUP BY CAC.CATEGORYID
    ) CAC ON CAC.CATEGORYID = IB.CATEGORYID
    WHERE IB.LASTCOUNTINGDATE IS NULL;

    /* floor to a real date, then to financial-year start */
    UPDATE #ItemBase SET LASTCOUNTINGDATE = ISNULL(LASTCOUNTINGDATE, '1900-01-01');
    UPDATE #ItemBase SET LASTCOUNTINGDATE = @FinYearStartDate
    WHERE LASTCOUNTINGDATE < @FinYearStartDate;

    /* ========================================================================
       STEP 2  PURCHASE SIDE by date  (dated by STOCKENTRY.UPDATEDATE)
       (joins + filters + open-item qty calc from USP_RPT_PURCHASES)
       ======================================================================== */
    SELECT
          CAST(SE.UPDATEDATE AS DATE)                                    AS TXNDATE
        , CAST(SUM(CASE WHEN IB.ISOPENITEM = 0
                        THEN ISNULL(SED.QUANTITY, 0)
                        ELSE ISNULL(SED.WEIGHTINKGS, 0) END)
               AS DECIMAL(18, 2))                                         AS PURCHASEQTY   -- open-item aware
        , CAST(SUM(ISNULL(SED.WEIGHTINKGS, 0)) AS DECIMAL(18, 2))         AS PURCHASEWEIGHT
        , COUNT(DISTINCT SE.STOCKENTRYID)                                 AS ENTRYCOUNT
        , COUNT(1)                                                        AS DETAILCOUNT
    INTO #PurchaseByDate
    FROM STOCKENTRYDETAIL SED WITH (NOLOCK)
        INNER JOIN STOCKENTRY    SE  WITH (NOLOCK) ON SE.STOCKENTRYID     = SED.STOCKENTRYID
        INNER JOIN ITEMCOSTPRICE ICP WITH (NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
        INNER JOIN ITEMPRICE     IP  WITH (NOLOCK) ON IP.ITEMPRICEID      = ICP.ITEMPRICEID
        INNER JOIN ITEMCODE      IC  WITH (NOLOCK) ON IC.ITEMCODEID       = IP.ITEMCODEID
        INNER JOIN #ItemBase     IB                ON IB.ITEMID           = IC.ITEMID
    WHERE SE.UPDATEDATE   > IB.LASTCOUNTINGDATE
      AND SE.UPDATEDATE   < @ToDate
      AND SED.DELETEDDATE IS NULL
      AND SE.STATUS       = 1
    GROUP BY CAST(SE.UPDATEDATE AS DATE);

    /* ========================================================================
       STEP 3  STOCKSUMMARY SIDE by date  (TTYPE = 'SE' only)  -> RESULT 1 anchor
       ======================================================================== */
    SELECT
          CAST(SSL.CREATEDDATE AS DATE)                                   AS TXNDATE
        , CAST(SUM(CASE WHEN IB.ISOPENITEM = 1
                        THEN ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0)
                        ELSE ISNULL(SSL.QUANTITY, 0)    - ISNULL(SSL.OLDQTY, 0) END)
               AS DECIMAL(18, 2))                                         AS SSQTY          -- open-item aware
        , CAST(SUM(ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0)) AS DECIMAL(18, 2)) AS SSWEIGHT
    INTO #SSByDate
    FROM STOCKSUMMARY SS WITH (NOLOCK)
        INNER JOIN STOCKSUMMARYLOG SSL WITH (NOLOCK) ON SSL.STOCKSUMMARYID = SS.STOCKSUMMARYID
        INNER JOIN ITEMPRICE       IP  WITH (NOLOCK) ON IP.ITEMPRICEID     = SS.ITEMPRICEID
        INNER JOIN ITEMCODE        IC  WITH (NOLOCK) ON IC.ITEMCODEID      = IP.ITEMCODEID
        INNER JOIN #ItemBase       IB                ON IB.ITEMID          = IC.ITEMID
    WHERE SS.BRANCHID     = @BranchID
      AND SSL.TTYPE       = 'SE'
      AND SSL.CREATEDDATE > IB.LASTCOUNTINGDATE
      AND SSL.CREATEDDATE < @ToDate
    GROUP BY CAST(SSL.CREATEDDATE AS DATE);

    /* ========================================================================
       STEP 4  STOCKSUMMARY SIDE by (date, TTYPE)  -  ALL TTYPEs  -> RESULT 2
       Same joins / open-item change calc, but grouped per TTYPE so every
       movement that touched these items each day is visible.
       ======================================================================== */
    SELECT
          CAST(SSL.CREATEDDATE AS DATE)                                   AS TXNDATE
        , SSL.TTYPE                                                       AS TTYPE
        , CAST(SUM(CASE WHEN IB.ISOPENITEM = 1
                        THEN ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0)
                        ELSE ISNULL(SSL.QUANTITY, 0)    - ISNULL(SSL.OLDQTY, 0) END)
               AS DECIMAL(18, 2))                                         AS QTY            -- open-item aware
        , CAST(SUM(ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0)) AS DECIMAL(18, 2)) AS WEIGHT
        , COUNT(1)                                                        AS LOGCOUNT
    INTO #SSMoveByDate
    FROM STOCKSUMMARY SS WITH (NOLOCK)
        INNER JOIN STOCKSUMMARYLOG SSL WITH (NOLOCK) ON SSL.STOCKSUMMARYID = SS.STOCKSUMMARYID
        INNER JOIN ITEMPRICE       IP  WITH (NOLOCK) ON IP.ITEMPRICEID     = SS.ITEMPRICEID
        INNER JOIN ITEMCODE        IC  WITH (NOLOCK) ON IC.ITEMCODEID      = IP.ITEMCODEID
        INNER JOIN #ItemBase       IB                ON IB.ITEMID          = IC.ITEMID
    WHERE SS.BRANCHID     = @BranchID
      AND SSL.CREATEDDATE > IB.LASTCOUNTINGDATE
      AND SSL.CREATEDDATE < @ToDate
    GROUP BY CAST(SSL.CREATEDDATE AS DATE), SSL.TTYPE;

    /* ========================================================================
       RESULT 1  -  DATE-WISE SE vs PURCHASE (anchor)
       ======================================================================== */
    SELECT
          COALESCE(P.TXNDATE, S.TXNDATE)                                  AS TxnDate
        , ISNULL(P.PURCHASEQTY, 0)                                        AS PurchaseQuantity
        , ISNULL(S.SSQTY, 0)                                              AS StockSummaryQuantity
        , CAST(ISNULL(P.PURCHASEQTY, 0) - ISNULL(S.SSQTY, 0) AS DECIMAL(18,2)) AS QuantityDifference
        , ISNULL(P.PURCHASEWEIGHT, 0)                                     AS PurchaseWeight
        , ISNULL(S.SSWEIGHT, 0)                                           AS StockSummaryWeight
        , CAST(ISNULL(P.PURCHASEWEIGHT, 0) - ISNULL(S.SSWEIGHT, 0) AS DECIMAL(18,2)) AS WeightDifference
    FROM #PurchaseByDate P
        FULL OUTER JOIN #SSByDate S ON S.TXNDATE = P.TXNDATE
    ORDER BY TxnDate;

    /* ========================================================================
       RESULT 2  -  PER-DAY MOVEMENT LEDGER  (purchase line + every TTYPE)
       Read a single day top-to-bottom to see exactly what happened:
         PURCHASE, SE, then reverts / branch returns / etc.
       ======================================================================== */
    ;WITH MOVEMENTS AS
    (
        /* synthetic purchase line */
        SELECT
              P.TXNDATE                                 AS TxnDate
            , 'PURCHASE'                                AS Source
            , 'PURCHASE'                                AS TType
            , CAST('Purchase (active stock entries)' AS VARCHAR(40)) AS MovementDesc
            , P.PURCHASEQTY                             AS Quantity
            , P.PURCHASEWEIGHT                          AS Weight
            , P.DETAILCOUNT                             AS RecordCount
            , 0                                         AS SORTKEY
        FROM #PurchaseByDate P

        UNION ALL

        /* every stocksummary movement type */
        SELECT
              M.TXNDATE
            , 'STOCKSUMMARY'
            , M.TTYPE
            , CAST(CASE M.TTYPE
                       WHEN 'SE' THEN 'Stock Entry'
                       WHEN 'SC' THEN 'Stock Counting'
                       WHEN 'SD' THEN 'Stock Dispatch'
                       WHEN 'DR' THEN 'Dispatch Revert'
                       WHEN 'BR' THEN 'Branch Refund / Return'
                       WHEN 'SR' THEN 'Supplier Returns'
                       ELSE 'Other (' + ISNULL(M.TTYPE, 'NULL') + ')'
                   END AS VARCHAR(40))
            , M.QTY
            , M.WEIGHT
            , M.LOGCOUNT
            , CASE M.TTYPE
                  WHEN 'SE' THEN 1
                  WHEN 'DR' THEN 2
                  WHEN 'BR' THEN 3
                  WHEN 'SR' THEN 4
                  WHEN 'SD' THEN 5
                  WHEN 'SC' THEN 6
                  ELSE 9
              END
        FROM #SSMoveByDate M
    )
    SELECT
          TxnDate
        , Source
        , TType
        , MovementDesc
        , Quantity
        , Weight
        , RecordCount
    FROM MOVEMENTS
    ORDER BY TxnDate, SORTKEY, TType;

END;
GO
/****** Object:  StoredProcedure [dbo].[DEBUG_USP_SS_IL_NOTMATCHING_BRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[DEBUG_USP_SS_IL_NOTMATCHING_BRANCH]
@BranchID int
AS 
BEGIN

		--drop table COUNTINGBASELINE
		--DROP TABLE CALCULATEDSTOCK

		DELETE FROM COUNTINGBASELINE WHERE BRANCHID = @BranchID
		DELETE FROM CALCULATEDSTOCK WHERE BRANCHID = @BranchID

		INSERT INTO COUNTINGBASELINE
		SELECT SC.BRANCHID, I.CATEGORYID, MAX(SC.STOCKACCEPTEDDATE) COUNTINGDATE		
		--INTO COUNTINGBASELINE
		FROM
			STOCKCOUNTING SC
			INNER JOIN STOCKCOUNTINGDETAIL SCD ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SCD.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		WHERE
			ISNULL(SC.STATUS, 0) NOT IN (0, 1)
			AND SC.DELETEDDATE IS NULL
			AND SCD.DELETEDDATE IS NULL
			AND SC.STOCKACCEPTEDDATE IS NOT NULL
			AND SC.BRANCHID NOT IN (45, 91, 92, 97, 100)
			and sc.BRANCHID = @BranchID
		GROUP BY SC.BRANCHID, I.CATEGORYID
		ORDER BY SC.BRANCHID, I.CATEGORYID

		INSERT INTO COUNTINGBASELINE
		SELECT B.BRANCHID, CAT.CATEGORYID, B.CREATEDDATE
		FROM
			 BRANCH B
			 CROSS APPLY TBLCATEGORY CAT
		WHERE
			NOT EXISTS
				(
					SELECT 1 FROM COUNTINGBASELINE CBL WHERE CBL.BRANCHID = B.BRANCHID AND CBL.CATEGORYID = CAT.CATEGORYID		
				)
			AND B.DELETEDDATE IS NULL 
			AND CAT.DELETEDDATE IS NULL
			AND CAT.CATEGORYID NOT IN (13)
			AND B.BRANCHID NOT IN (45, 91, 92, 97, 100)
			and b.BRANCHID = @BranchID

		
		INSERT INTO CALCULATEDSTOCK
		SELECT CBL.BRANCHID, IP.ITEMPRICEID, CBL.CATEGORYID, CBL.COUNTINGDATE, I.ISOPENITEM, CAST(0.00 AS DECIMAL(18,2)) AS OPENINGSTOCK
			, CAST(0.00 AS DECIMAL(18,2)) AS STOCKDISPATCH, CAST(0.00 AS DECIMAL(18,2)) AS STOCKDISPATCHOUT , CAST(0.00 AS DECIMAL(18,2))  AS SALE
			, CAST(0.00 AS DECIMAL(18,2)) CUSTOMERREFUND, CAST(0.00 AS DECIMAL(18,2)) AS BRANCHREFUND, 
			CAST(0.00 AS DECIMAL(18,2)) STOCKADJUSTMENT, CAST(0.00 AS DECIMAL(18,2)) STOCKSUMMARY
			, CAST(0.00 AS DECIMAL(18,2)) LEDGERSUMMARY, IP.STOCKMOVETOID
		--INTO CALCULATEDSTOCK
		FROM 
			COUNTINGBASELINE CBL
			INNER JOIN ITEM I ON I.CATEGORYID = CBL.CATEGORYID
			INNER JOIN ITEMCODE IC ON IC.ITEMID = I.ITEMID
			INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
		WHERE CBL.BRANCHID = @BranchID AND I.ISOPENITEM = 0
		--WHERE IP.DELETEDDATE IS NULL
		


		UPDATE CSMAIN
		SET CSMAIN.STOCKDISPATCH = CSJOIN.DISPATCHQTY
		FROM
			CALCULATEDSTOCK CSMAIN
			INNER JOIN
				(
					SELECT SD.TOBRANCHID AS BRANCHID,ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID) AS ITEMPRICEID, 
					SUM(CASE WHEN CSINNER.ISOPENITEM = 0 THEN SDD.DISPATCHQUANTITY ELSE SDD.WEIGHTINKGS END) DISPATCHQTY
					FROM
						STOCKDISPATCHDETAIL SDD 
						INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID
						INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
						INNER JOIN CALCULATEDSTOCK CSINNER ON SD.TOBRANCHID = CSINNER.BRANCHID AND CSINNER.ITEMPRICEID = IP.ITEMPRICEID
						
					WHERE 
						SD.TOBRANCHID = @BranchID
						AND SD.STATUS = 2
						AND ISNULL(SDD.ISACCEPTED,0) = 1
						AND SDD.DELETEDDATE IS NULL
						AND SD.DELETEDDATE IS NULL
						AND SD.CREATEDDATE > CSINNER.COUNTINGDATE
					GROUP BY SD.TOBRANCHID,ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID)
				) CSJOIN ON CSJOIN.BRANCHID = CSMAIN.BRANCHID AND CSJOIN.ITEMPRICEID = CSMAIN.ITEMPRICEID

		UPDATE CSMAIN  
		SET CSMAIN.STOCKDISPATCHOUT = CSJOIN.DISPATCHQTY  
		FROM  
		 CALCULATEDSTOCK CSMAIN  
		 INNER JOIN  
		  (  
		   SELECT SD.FROMBRANCHID AS BRANCHID, ISNULL(IP.STOCKMOVETOID,IP.ITEMPRICEID) AS ITEMPRICEID, 
				SUM(CASE WHEN CBL.ISOPENITEM = 0 THEN SCD.DISPATCHQUANTITY ELSE SCD.WEIGHTINKGS END) DISPATCHQTY  
		   FROM  
		   STOCKDISPATCHDETAIL SCD 
		   INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
		   INNER JOIN STOCKDISPATCH SD ON SCD.STOCKDISPATCHID = SD.STOCKDISPATCHID 
		   INNER JOIN CALCULATEDSTOCK CBL ON SD.FROMBRANCHID = CBL.BRANCHID AND CBL.ITEMPRICEID = IP.ITEMPRICEID
		   WHERE   
			SD.FROMBRANCHID = @BranchID
			AND SD.STATUS <> 0  
			AND SCD.DELETEDDATE IS NULL  
			AND SD.DELETEDDATE IS NULL  
			AND SD.CREATEDDATE > CBL.COUNTINGDATE  
		   GROUP BY SD.FROMBRANCHID, ISNULL(IP.STOCKMOVETOID,IP.ITEMPRICEID)
		  ) CSJOIN ON CSJOIN.BRANCHID = CSMAIN.BRANCHID AND CSJOIN.ITEMPRICEID = CSMAIN.ITEMPRICEID  

		--DROP TABLE #SALE

		SELECT BC.BRANCHID,ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID) AS ITEMPRICEID , 
		(CASE WHEN CSINNER.ISOPENITEM = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END) SALEQTY, PBD.BRANCHCOUNTERID, PBD.BILLDETAILID
		INTO #SALE
		FROM
			POS_BILLDETAIL PBD
			INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN BRANCHCOUNTER BC ON PBD.BRANCHCOUNTERID = BC.COUNTERID 
			INNER JOIN CALCULATEDSTOCK CSINNER ON CSINNER.BRANCHID  = BC.BRANCHID AND CSINNER.ITEMPRICEID = IP.ITEMPRICEID
		WHERE
			BC.BRANCHID = @BranchID
			AND PBD.DELETEDDATE IS NULL
			AND PB.BILLSTATUS = 1
			AND PB.DAYCLOSUREID = PBD.DAYCLOSUREID
			AND PBD.CREATEDDATE > CSINNER.COUNTINGDATE

		UPDATE CSMAIN
		SET CSMAIN.SALE = CSJOIN.SALEQTY
		FROM
			CALCULATEDSTOCK CSMAIN
			INNER JOIN
				(
					SELECT CSINNER.BRANCHID, CSINNER.ITEMPRICEID, SUM(SALE.SALEQTY) SALEQTY
					FROM
						CALCULATEDSTOCK CSINNER 
						INNER JOIN #SALE SALE ON SALE.BRANCHID = CSINNER.BRANCHID AND SALE.ITEMPRICEID = CSINNER.ITEMPRICEID
					GROUP BY CSINNER.BRANCHID, CSINNER.ITEMPRICEID
				) CSJOIN ON CSJOIN.BRANCHID = CSMAIN.BRANCHID AND CSJOIN.ITEMPRICEID = CSMAIN.ITEMPRICEID

		--DROP TABLE #CREFUNDS

			--SELECT BC.BRANCHID, PBD.ITEMPRICEID, CASE WHEN CSINNER.ISOPENITEM = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END REFUNDQTY
			--INTO #CREFUNDS
			--FROM
			--	POS_CREFUND CR
			--	INNER JOIN #SALE PBD ON PBD.BRANCHCOUNTERID = CR.COUNTERID and PBD.BILLDETAILID = CR.BILLDETAILID
			--	INNER JOIN BRANCHCOUNTER BC ON  PBD.BRANCHCOUNTERID = BC.COUNTERID 
			--	INNER JOIN CALCULATEDSTOCK CSINNER ON BC.BRANCHID = CSINNER.BRANCHID AND CSINNER.ITEMPRICEID = PBD.ITEMPRICEID
			--WHERE
			--	CR.DELETEDDATE IS NULL
			--	AND CR.DAYCLOSUREID IS NOT NULL
			--	AND CR.CREATEDDATE > CSINNER.COUNTINGDATE

		SELECT BC.BRANCHID, PBD.ITEMPRICEID, CASE WHEN CSINNER.ISOPENITEM = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END REFUNDQTY
			INTO #CREFUNDS
			FROM
				POS_CREFUND CR
				INNER JOIN BRANCHCOUNTER BC ON  CR.COUNTERID = BC.COUNTERID 
				INNER JOIN POS_BILLDETAIL PBD ON PBD.BRANCHCOUNTERID = CR.COUNTERID AND PBD.BILLDETAILID = CR.BILLDETAILID
				INNER JOIN CALCULATEDSTOCK CSINNER ON BC.BRANCHID = CSINNER.BRANCHID AND CSINNER.ITEMPRICEID = PBD.ITEMPRICEID
			WHERE
				BC.BRANCHID = @BranchID
				AND CR.DELETEDDATE IS NULL
				AND CR.DAYCLOSUREID IS NOT NULL
				AND CR.CREATEDDATE > CSINNER.COUNTINGDATE

			

		UPDATE CSMAIN
		SET CSMAIN.CUSTOMERREFUND = CSJOIN.REFUNDQTY
		FROM
			CALCULATEDSTOCK CSMAIN
			INNER JOIN
				(
					SELECT CR.BRANCHID, CR.ITEMPRICEID, SUM(CR.REFUNDQTY) REFUNDQTY
					FROM
						CALCULATEDSTOCK CSINNER 
						INNER JOIN #CREFUNDS CR ON CR.BRANCHID = CSINNER.BRANCHID AND CR.ITEMPRICEID = CSINNER.ITEMPRICEID
					GROUP BY CR.BRANCHID, CR.ITEMPRICEID
				) CSJOIN ON CSJOIN.BRANCHID = CSMAIN.BRANCHID AND CSJOIN.ITEMPRICEID = CSMAIN.ITEMPRICEID


		--DROP TABLE #BREFUNDS

			SELECT BR.BRANCHID, ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID) AS ITEMPRICEID, 
			CASE WHEN CSINNER.ISOPENITEM = 0 THEN BRD.QUANTITY ELSE BRD.WEIGHTINKGS END BRQUANTITY
			INTO #BREFUNDS
			FROM
				POS_BREFUNDDETAIL BRD 
				INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN POS_BREFUND BR ON BR.BRID = BRD.BRID
				INNER JOIN CALCULATEDSTOCK CSINNER ON BR.BRANCHID = CSINNER.BRANCHID AND BRD.ITEMPRICEID = CSINNER.ITEMPRICEID
			WHERE
				BR.BRANCHID = @BranchID
				AND BRD.DELETEDDATE IS NULL
				AND BR.DELETEDDATE IS NULL
				--AND BR.IsAccepted = 1
				AND BR.STATUS = 1
				AND ISNULL(BR.ACCEPTEDDATE, BR.UPDATEDDATE) > CSINNER.COUNTINGDATE
				AND REASONID <> 5


		UPDATE CSMAIN
		SET CSMAIN.BRANCHREFUND = CSJOIN.BRQUANTITY
		FROM
			CALCULATEDSTOCK CSMAIN
			INNER JOIN
				(
					SELECT CSINNER.BRANCHID, CSINNER.ITEMPRICEID, SUM(BRD.BRQUANTITY) BRQUANTITY
					FROM
						CALCULATEDSTOCK CSINNER 
						INNER JOIN #BREFUNDS BRD ON BRD.ITEMPRICEID = CSINNER.ITEMPRICEID AND CSINNER.BRANCHID = BRD.BRANCHID
					GROUP BY CSINNER.BRANCHID, CSINNER.ITEMPRICEID
				) CSJOIN ON CSJOIN.BRANCHID = CSMAIN.BRANCHID AND CSJOIN.ITEMPRICEID = CSMAIN.ITEMPRICEID


		UPDATE CSMAIN
		SET CSMAIN.STOCKADJUSTMENT = CSJOIN.ADJUSTMENTQTY
		FROM
			CALCULATEDSTOCK CSMAIN
			INNER JOIN
				(
					SELECT SA.BRANCHID, ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID) AS ITEMPRICEID, 
					SUM(CASE WHEN CSINNER.ISOPENITEM = 0 THEN SA.QUANTITY - SA.PREVQUANTITY ELSE SA.WEIGHTINKGS - SA.PREVWEIGHTINKGS END) ADJUSTMENTQTY
					FROM
						STOCKADJUSTMENT SA 
						INNER JOIN ITEMPRICE IP ON SA.ITEMPRICEID = IP.ITEMPRICEID
						INNER JOIN CALCULATEDSTOCK CSINNER  ON SA.BRANCHID = CSINNER.BRANCHID AND CSINNER.ITEMPRICEID = IP.ITEMPRICEID
					WHERE
						SA.BRANCHID = @BranchID
						AND SA.CREATEDDATE > CSINNER.COUNTINGDATE
					GROUP BY SA.BRANCHID, ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID)
				) CSJOIN ON CSJOIN.BRANCHID = CSMAIN.BRANCHID AND CSJOIN.ITEMPRICEID = CSMAIN.ITEMPRICEID


		UPDATE CSMAIN
		SET CSMAIN.OPENINGSTOCK = CASE WHEN CSMAIN.ISOPENITEM = 0 THEN CSJOIN.QUANTITY ELSE CSJOIN.WEIGHTINKGS END
		FROM
			CALCULATEDSTOCK CSMAIN
			INNER JOIN
				(
					SELECT SC.BRANCHID, ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID) AS ITEMPRICEID, SUM(SCD.QUANTITY) AS QUANTITY, SUM(SCD.WEIGHTINKGS) WEIGHTINKGS
					FROM
						STOCKCOUNTINGDETAIL SCD 
						INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
						INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
						INNER JOIN CALCULATEDSTOCK CSINNER  ON CSINNER.BRANCHID = SC.BRANCHID AND CSINNER.ITEMPRICEID = IP.ITEMPRICEID
					WHERE
						SC.BRANCHID = @BranchID
						AND SCD.DELETEDDATE IS NULL
						AND SC.DELETEDDATE IS NULL
						AND SC.STOCKACCEPTEDDATE >= CSINNER.COUNTINGDATE
					GROUP BY SC.BRANCHID, ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID)
				) CSJOIN ON CSJOIN.BRANCHID = CSMAIN.BRANCHID AND CSJOIN.ITEMPRICEID = CSMAIN.ITEMPRICEID

		UPDATE CS
		SET CS.STOCKSUMMARY = CASE WHEN CS.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END
		FROM
			CALCULATEDSTOCK CS
			INNER JOIN STOCKSUMMARY SS ON SS.BRANCHID = CS.BRANCHID AND SS.ITEMPRICEID = CS.ITEMPRICEID
		WHERE CS.BRANCHID = @BranchID


		UPDATE CSPARENT
		SET CSPARENT.SALE = CSPARENT.SALE + CSMAIN.SALE
			, CSPARENT.CUSTOMERREFUND = CSPARENT.CUSTOMERREFUND + CSMAIN.CUSTOMERREFUND
			, CSPARENT.BRANCHREFUND = CSPARENT.BRANCHREFUND + CSMAIN.BRANCHREFUND
			, CSPARENT.STOCKADJUSTMENT = CSPARENT.STOCKADJUSTMENT + CSMAIN.STOCKADJUSTMENT
		FROM
			CALCULATEDSTOCK CSMAIN
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CSMAIN.ITEMPRICEID AND IP.BRANCHID = CSMAIN.BRANCHID
			INNER JOIN CALCULATEDSTOCK CSPARENT ON CSPARENT.ITEMPRICEID = IP.PARENTITEMPRICEID  AND CSPARENT.BRANCHID = CSMAIN.BRANCHID
		WHERE
			CSMAIN.BRANCHID = @BranchID
		
		DELETE CSMAIN
		FROM
			CALCULATEDSTOCK CSMAIN  
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CSMAIN.ITEMPRICEID AND IP.BRANCHID = CSMAIN.BRANCHID  
		WHERE IP.PARENTITEMPRICEID IS NOT NULL AND CSMAIN.BRANCHID = @BranchID

		UPDATE CALCULATEDSTOCK
		SET LEDGERSUMMARY = OPENINGSTOCK + STOCKDISPATCH - STOCKDISPATCHOUT - SALE + CUSTOMERREFUND - BRANCHREFUND + STOCKADJUSTMENT
		WHERE BRANCHID = @BranchID

		UPDATE CS
		SET 
			--CS.STOCKSUMMARY = CS.STOCKSUMMARY + CSSM.STOCKSUMMARY,
			CS.LEDGERSUMMARY = CS.LEDGERSUMMARY + CSSM.LEDGERSUMMARY
		FROM 
			CALCULATEDSTOCK CS
			INNER JOIN
				(
					SELECT 
						SUM(CSINNER.STOCKSUMMARY) STOCKSUMMARY
						, SUM(CSINNER.LEDGERSUMMARY) LEDGERSUMMARY
						, CSINNER.STOCKMOVETOID ITEMPRICEID
					FROM CALCULATEDSTOCK CSINNER
					WHERE CSINNER.STOCKMOVETOID IS NOT NULL
					GROUP BY CSINNER.STOCKMOVETOID
				) CSSM ON CSSM.ITEMPRICEID = CS.ITEMPRICEID
		WHERE CS.BRANCHID = @BranchID
	
	

		UPDATE CS
		SET 
			CS.LEDGERSUMMARY = 0, CS.STOCKSUMMARY = 0
		FROM CALCULATEDSTOCK CS
		WHERE CS.STOCKMOVETOID IS NOT NULL AND CS.BRANCHID = @BranchID

		--SELECT * FROM CALCULATEDSTOCK CS WHERE CS.STOCKSUMMARY <> CS.LEDGERSUMMARY


		------------UPDATE SS 
		------------SET SS.QUANTITY = CASE WHEN CS.ISOPENITEM = 0 THEN CAST(CS.LEDGERSUMMARY AS INT) ELSE SS.QUANTITY END
		------------	, SS.WEIGHTINKGS = CASE WHEN CS.ISOPENITEM = 1 THEN CS.LEDGERSUMMARY ELSE SS.WEIGHTINKGS END
		------------	, SS.TTYPE = 'MU'
		------------FROM 
		------------	CALCULATEDSTOCK CS 
		------------	INNER JOIN STOCKSUMMARY SS ON SS.BRANCHID = CS.BRANCHID AND SS.ITEMPRICEID = CS.ITEMPRICEID 
		------------WHERE CS.STOCKSUMMARY <> CS.LEDGERSUMMARY



		--INSERT INTO CALCULATEDSTOCKDIFF(BRANCHID,ITEMPRICEID,CATEGORYID,COUNTINGDATE,ISOPENITEM,OPENINGSTOCK
		--,STOCKDISPATCH,STOCKDISPATCHOUT,SALE,CUSTOMERREFUND,BRANCHREFUND,STOCKADJUSTMENT,STOCKSUMMARY,LEDGERSUMMARY)
		--SELECT * FROM CALCULATEDSTOCK  WHERE STOCKSUMMARY <> LEDGERSUMMARY

		--SELECT * FROM CALCULATEDSTOCK WHERE STOCKSUMMARY = LEDGERSUMMARY AND STOCKSUMMARY <> 0

		--SELECT 
		--	IC.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUM(CS.OPENINGSTOCK) OPENINGSTOCK, SUM(CS.STOCKDISPATCH) STOCKDISPATCHIN
		--	, SUM(CS.CUSTOMERREFUND) CUSTOMERREFUND, SUM(CS.BRANCHREFUND) BRANCHREFUND, SUM(CS.STOCKDISPATCHOUT) STOCKDISPATCHOUT, SUM(CS.SALE) SALE
		--	, SUM(CS.STOCKADJUSTMENT) STOCKADJUSTMENT, SUM(CS.STOCKSUMMARY) STOCKSUMMARY, SUM(CS.LEDGERSUMMARY) LEDGERSUMMARY
		--	, SUM(CS.STOCKSUMMARY) - SUM(CS.LEDGERSUMMARY)
		--FROM 
		--	CALCULATEDSTOCK CS
		--	INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CS.ITEMPRICEID
		--	INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		--	INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		--	INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		--GROUP BY CAT.CATEGORYNAME, IC.ITEMID, I.SKUCODE, I.ITEMNAME
		--HAVING SUM(CS.STOCKSUMMARY) <> SUM(CS.LEDGERSUMMARY)
		--ORDER BY CAT.CATEGORYNAME, SUM(CS.STOCKSUMMARY) - SUM(CS.LEDGERSUMMARY) DESC

	--SELECT 
	--	B.BRANCHNAME, CAT.CATEGORYNAME, IC.ITEMID, I.SKUCODE, I.ITEMNAME, CS.OPENINGSTOCK, CS.STOCKDISPATCH
	--	, CS.CUSTOMERREFUND, CS.BRANCHREFUND, CS.STOCKDISPATCHOUT, CS.SALE, CS.STOCKADJUSTMENT
	--	, SS.QUANTITY, CS.LEDGERSUMMARY, SS.QUANTITY - CS.LEDGERSUMMARY STOCKDIFF
	--FROM 
	--	CALCULATEDSTOCK CS
	--	INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CS.ITEMPRICEID
	--	INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	--	INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	--	INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
	--	INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = CS.ITEMPRICEID AND SS.BRANCHID = CS.BRANCHID
	--	INNER JOIN BRANCH B ON B.BRANCHID = CS.BRANCHID
	--WHERE SS.QUANTITY <> CS.LEDGERSUMMARY AND CS.BRANCHID = @BranchID
	----GROUP BY CAT.CATEGORYNAME, IC.ITEMID, I.SKUCODE, I.ITEMNAME
	----HAVING (CS.STOCKMARY) <> (CS.LEDGERMARY)
	--ORDER BY B.BRANCHNAME, CAT.CATEGORYNAME, I.SKUCODE

END
GO
/****** Object:  StoredProcedure [dbo].[DEBUG_USP_SS_IL_NOTMATCHING_WH_BY_ITEM]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[DEBUG_USP_SS_IL_NOTMATCHING_WH_BY_ITEM] 
    @ITEMID INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    ------------------------------------------------------------------------------------------
    -- Parameters (kept exactly as V2)
    ------------------------------------------------------------------------------------------
    DECLARE @BranchID         INT      = 45;
    DECLARE @WHId             INT      = 45;
    DECLARE @ToDate           DATETIME = DATEADD(DAY, 1, CAST(GETDATE() AS DATE));
    DECLARE @FinYearStartDate DATE     = '2023-04-01';

    ------------------------------------------------------------------------------------------
    -- Clean up
    ------------------------------------------------------------------------------------------
    IF OBJECT_ID('tempdb..#Calc')      IS NOT NULL DROP TABLE #Calc;
    IF OBJECT_ID('tempdb..#Map')       IS NOT NULL DROP TABLE #Map;
    IF OBJECT_ID('tempdb..#CntItem')   IS NOT NULL DROP TABLE #CntItem;
    IF OBJECT_ID('tempdb..#CatMapRaw') IS NOT NULL DROP TABLE #CatMapRaw;
    IF OBJECT_ID('tempdb..#CntSub')    IS NOT NULL DROP TABLE #CntSub;
    IF OBJECT_ID('tempdb..#CntCat')    IS NOT NULL DROP TABLE #CntCat;
    IF OBJECT_ID('tempdb..#SS')        IS NOT NULL DROP TABLE #SS;
    IF OBJECT_ID('tempdb..#CntOpen')   IS NOT NULL DROP TABLE #CntOpen;
    IF OBJECT_ID('tempdb..#SALE')      IS NOT NULL DROP TABLE #SALE;

    -- ==========================================================================================
    -- 1. DRIVING TABLE (item grain) : one row per item, zeroed ledger columns
    -- ==========================================================================================
    SELECT
        I.ITEMID,
        I.SKUCODE,
        I.ITEMNAME,
        I.CATEGORYID,
        I.SUBCATEGORYID,
        ISNULL(I.ISOPENITEM, 0)   AS ISOPENITEM,
        ISNULL(I.PARENTITEMID, 0) AS PARENTITEMID,
        CAST(NULL AS DATETIME)     AS CASCADEDATE,        -- working: resolved counting date (pre-default)
        CAST(NULL AS DATETIME)     AS LASTCOUNTINGDATE,   -- final counting date used by all txns
        CAST(0.00 AS DECIMAL(18,2)) AS OPENINGBALANCE,
        CAST(NULL AS DECIMAL(18,2)) AS FYOPENING,         -- working: financial-year opening
        CAST(0.00 AS DECIMAL(18,2)) AS STOCKENTRY,
        CAST(0.00 AS DECIMAL(18,2)) AS STOCKDISPATCHOUT,
        CAST(0.00 AS DECIMAL(18,2)) AS BRANCHREFUND,
        CAST(0.00 AS DECIMAL(18,2)) AS SUPPLIERREFUND,
        CAST(0.00 AS DECIMAL(18,2)) AS STOCKADJUSTMENT,   -- signed (credit - debit)
        CAST(0.00 AS DECIMAL(18,2)) AS SALE,
        CAST(0.00 AS DECIMAL(18,2)) AS CUSTOMERREFUND
    INTO #Calc
    FROM ITEM I
    WHERE I.ITEMID = @ITEMID OR @ITEMID = 0
    OPTION (RECOMPILE);

    CREATE UNIQUE CLUSTERED INDEX IX_Calc ON #Calc(ITEMID);

    -- ==========================================================================================
    -- 2. MATERIALIZE ITEM -> ITEMCODE -> ITEMPRICE ONCE
    --    Every downstream aggregation joins through this instead of re-joining the 3 tables.
    -- ==========================================================================================
    SELECT
        C.ITEMID,
        C.ISOPENITEM,
        CAST(NULL AS DATETIME) AS LASTCOUNTINGDATE,   -- filled after the date cascade
        IC.ITEMCODEID,
        IP.ITEMPRICEID
    INTO #Map
    FROM #Calc C
    JOIN ITEMCODE  IC ON IC.ITEMID     = C.ITEMID
    JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
    OPTION (RECOMPILE);

    CREATE UNIQUE CLUSTERED INDEX IX_Map_IP   ON #Map(ITEMPRICEID);
    CREATE NONCLUSTERED INDEX     IX_Map_Item ON #Map(ITEMID)
        INCLUDE (ISOPENITEM, LASTCOUNTINGDATE, ITEMPRICEID);

    -- ==========================================================================================
    -- 3. LAST COUNTING DATE : resolve the 3 sources, then combine in ONE set-based UPDATE
    --    (replaces V2's 3 sequential UPDATE statements while preserving exact precedence)
    --      a) item-level    counting date  (highest priority)
    --      b) sub-category  counting date  (max with item-level)
    --      c) category      counting date  (only fills rows still NULL)
    -- ==========================================================================================

    -- 3a. Item-level date (reuses #Map for the itemprice -> item link)
    SELECT M.ITEMID, MAX(CAI.CREATEDDATE) AS ITEMDATE
    INTO #CntItem
    FROM COUNTINGAPPROVALITEM CAI
    JOIN COUNTINGAPPROVAL     CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
    JOIN #Map                 M  ON M.ITEMPRICEID         = CAI.ITEMPRICEID
    WHERE CA.BRANCHID = @BranchID
      AND CAI.CREATEDDATE < @ToDate
    GROUP BY M.ITEMID
    OPTION (RECOMPILE);
    CREATE UNIQUE CLUSTERED INDEX IX_CntItem ON #CntItem(ITEMID);

    -- Read COUNTINGAPPROVALCATEGORYMAP ONCE (branch + date filtered), then derive both maps
    SELECT CAC.SUBCATEGORYID, CAC.CATEGORYID, CAC.CREATEDDATE
    INTO #CatMapRaw
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
    JOIN COUNTINGAPPROVAL            CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
    WHERE CA.BRANCHID = @BranchID
      AND CAC.CREATEDDATE < @ToDate
    OPTION (RECOMPILE);

    -- 3b. Sub-category date
    SELECT SUBCATEGORYID, MAX(CREATEDDATE) AS SUBDATE
    INTO #CntSub
    FROM #CatMapRaw
    WHERE SUBCATEGORYID IS NOT NULL
    GROUP BY SUBCATEGORYID;
    CREATE UNIQUE CLUSTERED INDEX IX_CntSub ON #CntSub(SUBCATEGORYID);

    -- 3c. Category date
    SELECT CATEGORYID, MAX(CREATEDDATE) AS CATDATE
    INTO #CntCat
    FROM #CatMapRaw
    WHERE CATEGORYID IS NOT NULL
    GROUP BY CATEGORYID;
    CREATE UNIQUE CLUSTERED INDEX IX_CntCat ON #CntCat(CATEGORYID);

    -- Combine in ONE pass (exact V2 precedence):
    --   L2 = item vs sub  : if sub present and (item null or sub > item) -> sub else item
    --   CASCADEDATE = COALESCE(L2, category)   (category only used when L2 is NULL)
    UPDATE C
    SET C.CASCADEDATE =
        COALESCE(
            CASE
                WHEN s.SUBDATE IS NOT NULL AND (i.ITEMDATE IS NULL OR s.SUBDATE > i.ITEMDATE)
                    THEN s.SUBDATE
                ELSE i.ITEMDATE
            END,
            cat.CATDATE
        )
    FROM #Calc C
    LEFT JOIN #CntItem i   ON i.ITEMID        = C.ITEMID
    LEFT JOIN #CntSub  s   ON s.SUBCATEGORYID = C.SUBCATEGORYID
    LEFT JOIN #CntCat  cat ON cat.CATEGORYID  = C.CATEGORYID
    OPTION (RECOMPILE);

    -- ==========================================================================================
    -- 4. STOCKSUMMARY : ONE scan feeds BOTH the FY opening balance AND the closing stock
    -- ==========================================================================================
    SELECT
        M.ITEMID,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN SS.FYOPENINGWEIGHTINKGS ELSE SS.FYOPENINGQUANTITY END) AS FYOPENING,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN SS.WEIGHTINKGS          ELSE SS.QUANTITY           END) AS STOCKSUMMARY
    INTO #SS
    FROM STOCKSUMMARY SS
    JOIN #Map M ON M.ITEMPRICEID = SS.ITEMPRICEID
    WHERE SS.BRANCHID = @BranchID
    GROUP BY M.ITEMID, M.ISOPENITEM
    OPTION (RECOMPILE);
    CREATE UNIQUE CLUSTERED INDEX IX_SS ON #SS(ITEMID);

    -- push FY opening onto the driver (rounded to (18,2) exactly like V2's OPENINGBALANCE store)
    UPDATE C
    SET C.FYOPENING = ss.FYOPENING
    FROM #Calc C
    JOIN #SS ss ON ss.ITEMID = C.ITEMID;

    -- ==========================================================================================
    -- 5. STOCK COUNTING opening balance (ONE scan) -- only for items with a resolved date
    --    date-level comparison, exactly as V2's CAST(... AS DATE) >= CAST(... AS DATE)
    -- ==========================================================================================
    SELECT
        C.ITEMID,
SUM(CASE WHEN C.ISOPENITEM = 1 THEN SCD.WEIGHTINKGS ELSE SCD.QUANTITY END) AS OB
    INTO #CntOpen
    FROM #Calc C
    JOIN #Map               M   ON M.ITEMID          = C.ITEMID
    JOIN STOCKCOUNTINGDETAIL SCD ON SCD.ITEMPRICEID   = M.ITEMPRICEID
    JOIN STOCKCOUNTING       SC  ON SC.STOCKCOUNTINGID = SCD.STOCKCOUNTINGID
    WHERE C.CASCADEDATE IS NOT NULL
      AND SCD.DELETEDDATE IS NULL
      AND SC.BRANCHID = @BranchID
      AND (SC.STATUS = 2 OR SC.STATUS = 3)
      AND CAST(SC.STOCKACCEPTEDDATE AS DATE) >= CAST(C.CASCADEDATE AS DATE)
    GROUP BY C.ITEMID, C.ISOPENITEM
    OPTION (RECOMPILE);
    CREATE UNIQUE CLUSTERED INDEX IX_CntOpen ON #CntOpen(ITEMID);

    -- ==========================================================================================
    -- 6. FINALISE OpeningBalance + LastCountingDate in ONE UPDATE (replaces V2 2d + 2e)
    --      counting date >= FY start  -> keep counting date, use counting-detail opening
    --      otherwise (incl. NULL)     -> reset to FY start, use FY opening
    -- ==========================================================================================
    UPDATE C
    SET
        C.LASTCOUNTINGDATE =
            CASE WHEN C.CASCADEDATE IS NOT NULL AND C.CASCADEDATE >= @FinYearStartDate
                 THEN C.CASCADEDATE
                 ELSE CAST(@FinYearStartDate AS DATETIME) END,
        C.OPENINGBALANCE =
            CASE WHEN C.CASCADEDATE IS NOT NULL AND C.CASCADEDATE >= @FinYearStartDate
                 THEN ISNULL(co.OB, 0)
                 ELSE ISNULL(C.FYOPENING, 0) END
    FROM #Calc C
    LEFT JOIN #CntOpen co ON co.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    -- push the FINAL date onto the map so all transaction aggregations read it locally
    UPDATE M
    SET M.LASTCOUNTINGDATE = C.LASTCOUNTINGDATE
    FROM #Map M
    JOIN #Calc C ON C.ITEMID = M.ITEMID;

    -- ==========================================================================================
    -- 7. OPENING BALANCE -> ledger driver
    -- ==========================================================================================
    -- (already stored in #Calc.OPENINGBALANCE; nothing further needed)

    -- ==========================================================================================
    -- 8. TRANSACTION AGGREGATIONS -- each source table scanned ONCE, UPDATE...JOIN into columns
    -- ==========================================================================================

    ------------------------------------------------------------------ Stock Entry (credit)
    UPDATE C
    SET C.STOCKENTRY = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1 THEN SUM(SED.WEIGHTINKGS) ELSE SUM(SED.QUANTITY) END AS VAL
        FROM #Map M
        JOIN ITEMCOSTPRICE     ICP ON ICP.ITEMPRICEID     = M.ITEMPRICEID
        JOIN STOCKENTRYDETAIL  SED ON SED.ITEMCOSTPRICEID  = ICP.ITEMCOSTPRICEID
        JOIN STOCKENTRY        SE  ON SE.STOCKENTRYID      = SED.STOCKENTRYID
        WHERE SED.DELETEDDATE IS NULL
          AND SE.STATUS = 1
          AND SE.CREATEDDATE > M.LASTCOUNTINGDATE
          AND SE.CREATEDDATE < @ToDate
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Stock Dispatch-Out (debit)
    UPDATE C
    SET C.STOCKDISPATCHOUT = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1 THEN SUM(SDD.WEIGHTINKGS) ELSE SUM(SDD.DISPATCHQUANTITY) END AS VAL
        FROM #Map M
        JOIN STOCKDISPATCHDETAIL SDD ON SDD.ITEMPRICEID    = M.ITEMPRICEID
        JOIN STOCKDISPATCH       SD  ON SD.STOCKDISPATCHID  = SDD.STOCKDISPATCHID
        WHERE SDD.DELETEDDATE IS NULL
          AND SD.DELETEDDATE  IS NULL
          AND SD.STATUS <> 0
          AND SD.CREATEDDATE > M.LASTCOUNTINGDATE
          AND SD.CREATEDDATE < @ToDate
          AND SD.FROMBRANCHID = @BranchID
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Branch Refund (credit)
    -- open + non-open collapsed into ONE scan; the open flag selects date column + measure
    UPDATE C
    SET C.BRANCHREFUND = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               SUM(CASE WHEN M.ISOPENITEM = 1 THEN BRD.WEIGHTINKGS ELSE BRD.QUANTITY END) AS VAL
        FROM #Map M
        JOIN POS_BREFUNDDETAIL BRD ON BRD.ITEMPRICEID = M.ITEMPRICEID
        JOIN POS_BREFUND       BD  ON BD.BRID         = BRD.BRID
        JOIN REASONFORREFUND   ROR ON ROR.REASONID    = BRD.REASONID
        WHERE BRD.DELETEDDATE IS NULL
          AND BD.DELETEDDATE  IS NULL
          AND BD.IsAccepted = 1
          AND ROR.LOCATIONTOMOVESTOCK = @WHId
          AND (
                (M.ISOPENITEM = 0 AND BD.ACCEPTEDDATE > M.LASTCOUNTINGDATE AND BD.ACCEPTEDDATE < @ToDate)
             OR (M.ISOPENITEM = 1 AND BD.UPDATEDDATE  > M.LASTCOUNTINGDATE AND BD.UPDATEDDATE  < @ToDate)
              )
        GROUP BY M.ITEMID
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Supplier Refund (debit)
    UPDATE C
    SET C.SUPPLIERREFUND = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1 THEN SUM(SRD.WEIGHTINKGS) ELSE SUM(SRD.QUANTITY) END AS VAL
        FROM #Map M
        JOIN ITEMCOSTPRICE          ICP ON ICP.ITEMPRICEID       = M.ITEMPRICEID
        JOIN SUPPLIERRETURNSDETAIL  SRD ON SRD.ITEMCOSTPRICEID    = ICP.ITEMCOSTPRICEID
        JOIN SUPPLIERRETURNS        SR  ON SR.SUPPLIERRETURNSID   = SRD.SUPPLIERRETURNSID
        WHERE SRD.DELETEDDATE IS NULL
          AND SR.DELETEDDATE  IS NULL
          AND SR.BRANCHID = @BranchID
          AND SR.STATUS = 1
          AND ISNULL(SRD.RETURNSTATUS, 0) = 1
          AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) > M.LASTCOUNTINGDATE
          AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) < @ToDate
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Stock Adjustment (signed)
    -- store credit-debit as a single signed value; totals split it back out in the final SELECT
    UPDATE C
    SET C.STOCKADJUSTMENT = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1
                    THEN SUM(SA.WEIGHTINKGS - SA.PREVWEIGHTINKGS)
                    ELSE SUM(SA.QUANTITY    - SA.PREVQUANTITY) END AS VAL
        FROM #Map M
        JOIN STOCKADJUSTMENT     SA  ON SA.ITEMPRICEID          = M.ITEMPRICEID
        JOIN STOCKADJUSTMENTTYPE SAT ON SAT.STOCKADJUSTMENTTYPEID = SA.STOCKADJUSTMENTTYPEID
        WHERE SA.CREATEDDATE > M.LASTCOUNTINGDATE
          AND SA.CREATEDDATE < @ToDate
          AND SA.BRANCHID = @BranchID
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ #SALE : POS_BILLDETAIL ONCE
    -- built without the per-item date filter so it can serve BOTH Sale and Customer Refund
    SELECT
        M.ITEMID,
        M.ISOPENITEM,
        M.LASTCOUNTINGDATE,
        PBD.BILLDETAILID,
        PBD.BRANCHCOUNTERID,
        PBD.CREATEDDATE,
        PBD.QUANTITY,
        PBD.WEIGHTINKGS
    INTO #SALE
    FROM #Map M
    JOIN POS_BILLDETAIL PBD ON PBD.ITEMPRICEID     = M.ITEMPRICEID
    JOIN POS_BILL       PB  ON PB.BILLID           = PBD.BILLID
                           AND PB.BRANCHCOUNTERID  = PBD.BRANCHCOUNTERID
    JOIN BRANCHCOUNTER  BC  ON BC.COUNTERID        = PB.BRANCHCOUNTERID
    WHERE BC.BRANCHID = @BranchID
      AND PBD.DELETEDDATE IS NULL
      AND PB.DELETEDDATE  IS NULL
      AND PB.BILLSTATUS = 1
	  AND PB.DAYCLOSUREID IS NOT NULL
	  AND PBD.DAYCLOSUREID IS NOT NULL
    OPTION (RECOMPILE);

    CREATE CLUSTERED INDEX IX_SALE     ON #SALE(BILLDETAILID, BRANCHCOUNTERID);
    CREATE NONCLUSTERED INDEX IX_SALE_I ON #SALE(ITEMID);

    ------------------------------------------------------------------ Sale (debit)
    UPDATE C
    SET C.SALE = x.VAL
    FROM #Calc C
    JOIN (
        SELECT S.ITEMID,
               CASE WHEN S.ISOPENITEM = 1 THEN SUM(S.WEIGHTINKGS) ELSE SUM(S.QUANTITY) END AS VAL
        FROM #SALE S
        WHERE S.CREATEDDATE > S.LASTCOUNTINGDATE
          AND S.CREATEDDATE < @ToDate
        GROUP BY S.ITEMID, S.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Customer Refund (credit)
    UPDATE C
    SET C.CUSTOMERREFUND = x.VAL
    FROM #Calc C
    JOIN (
        SELECT S.ITEMID,
               CASE WHEN S.ISOPENITEM = 1 THEN SUM(CRF.REFUNDWEIGHTINKGS) ELSE SUM(CRF.REFUNDQUANTITY) END AS VAL
        FROM #SALE S
        JOIN POS_CREFUND CRF ON CRF.BILLDETAILID = S.BILLDETAILID
                            AND CRF.COUNTERID    = S.BRANCHCOUNTERID
        WHERE CRF.DELETEDDATE IS NULL
          AND CRF.CREATEDDATE > S.LASTCOUNTINGDATE
          AND CRF.CREATEDDATE < @ToDate
        GROUP BY S.ITEMID, S.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    -- ==========================================================================================
    -- 9. FINAL RESULT (identical columns / order / filter / sort to V2)
    --    LedgerSummary, TotalCredit, TotalDebit reconstructed from the column values.
    -- ==========================================================================================
    ;WITH L AS
    (
        SELECT
            C.*,
            ( C.OPENINGBALANCE + C.STOCKENTRY - C.STOCKDISPATCHOUT + C.BRANCHREFUND
              - C.SUPPLIERREFUND + C.STOCKADJUSTMENT - C.SALE + C.CUSTOMERREFUND ) AS LEDGERSUMMARY_C,
            ( C.OPENINGBALANCE + C.STOCKENTRY + C.BRANCHREFUND + C.CUSTOMERREFUND
              + CASE WHEN C.STOCKADJUSTMENT > 0 THEN C.STOCKADJUSTMENT ELSE 0 END ) AS TOTALCREDIT_C,
            ( C.STOCKDISPATCHOUT + C.SUPPLIERREFUND + C.SALE
              + CASE WHEN C.STOCKADJUSTMENT > 0 THEN 0 ELSE -C.STOCKADJUSTMENT END ) AS TOTALDEBIT_C
        FROM #Calc C
    )
    SELECT
        L.ITEMID,
        L.SKUCODE,
        L.ITEMNAME,
        L.CATEGORYID,
        L.SUBCATEGORYID,
        L.ISOPENITEM,
        L.LASTCOUNTINGDATE,
        L.OPENINGBALANCE,
        L.STOCKENTRY,
        L.STOCKDISPATCHOUT,
        L.BRANCHREFUND,
        L.SUPPLIERREFUND,
        L.STOCKADJUSTMENT,
        L.SALE,
        L.CUSTOMERREFUND,
        ISNULL(SS.STOCKSUMMARY, 0)                        AS STOCKSUMMARY,
        L.LEDGERSUMMARY_C                                 AS LEDGERSUMMARY,
        ISNULL(SS.STOCKSUMMARY, 0) - L.LEDGERSUMMARY_C    AS DIFFERENCE,
        L.TOTALCREDIT_C                                   AS TOTALCREDIT,
        L.TOTALDEBIT_C                                    AS TOTALDEBIT
    FROM L
    LEFT JOIN #SS SS ON SS.ITEMID = L.ITEMID
    WHERE ISNULL(SS.STOCKSUMMARY, 0) <> L.LEDGERSUMMARY_C
    ORDER BY L.ITEMNAME
    OPTION (RECOMPILE);

END
GO
/****** Object:  StoredProcedure [dbo].[DEBUG_USP_SS_IL_NOTMATCHING_WH_BY_ITEMPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[DEBUG_USP_SS_IL_NOTMATCHING_WH_BY_ITEMPRICE] 
    @ITEMID INT = 0
AS
BEGIN
    SET NOCOUNT ON;

    ------------------------------------------------------------------------------------------
    -- Parameters (kept exactly as V2)
    ------------------------------------------------------------------------------------------
    DECLARE @BranchID         INT      = 45;
    DECLARE @WHId             INT      = 45;
    DECLARE @ToDate           DATETIME = DATEADD(DAY, 1, CAST(GETDATE() AS DATE));
    DECLARE @FinYearStartDate DATE     = '2023-04-01';

    ------------------------------------------------------------------------------------------
    -- Clean up
    ------------------------------------------------------------------------------------------
    IF OBJECT_ID('tempdb..#Calc')      IS NOT NULL DROP TABLE #Calc;
    IF OBJECT_ID('tempdb..#Map')       IS NOT NULL DROP TABLE #Map;
    IF OBJECT_ID('tempdb..#CntItem')   IS NOT NULL DROP TABLE #CntItem;
    IF OBJECT_ID('tempdb..#CatMapRaw') IS NOT NULL DROP TABLE #CatMapRaw;
    IF OBJECT_ID('tempdb..#CntSub')    IS NOT NULL DROP TABLE #CntSub;
    IF OBJECT_ID('tempdb..#CntCat')    IS NOT NULL DROP TABLE #CntCat;
    IF OBJECT_ID('tempdb..#SS')        IS NOT NULL DROP TABLE #SS;
    IF OBJECT_ID('tempdb..#CntOpen')   IS NOT NULL DROP TABLE #CntOpen;
    IF OBJECT_ID('tempdb..#SALE')      IS NOT NULL DROP TABLE #SALE;

    -- ==========================================================================================
    -- 1. DRIVING TABLE (item grain) : one row per item, zeroed ledger columns
    -- ==========================================================================================
    SELECT
        I.ITEMID,
        I.SKUCODE,
        I.ITEMNAME,
        I.CATEGORYID,
        I.SUBCATEGORYID,
        ISNULL(I.ISOPENITEM, 0)   AS ISOPENITEM,
        ISNULL(I.PARENTITEMID, 0) AS PARENTITEMID,
        CAST(NULL AS DATETIME)     AS CASCADEDATE,        -- working: resolved counting date (pre-default)
        CAST(NULL AS DATETIME)     AS LASTCOUNTINGDATE,   -- final counting date used by all txns
        CAST(0.00 AS DECIMAL(18,2)) AS OPENINGBALANCE,
        CAST(NULL AS DECIMAL(18,2)) AS FYOPENING,         -- working: financial-year opening
        CAST(0.00 AS DECIMAL(18,2)) AS STOCKENTRY,
        CAST(0.00 AS DECIMAL(18,2)) AS STOCKDISPATCHOUT,
        CAST(0.00 AS DECIMAL(18,2)) AS BRANCHREFUND,
        CAST(0.00 AS DECIMAL(18,2)) AS SUPPLIERREFUND,
        CAST(0.00 AS DECIMAL(18,2)) AS STOCKADJUSTMENT,   -- signed (credit - debit)
        CAST(0.00 AS DECIMAL(18,2)) AS SALE,
        CAST(0.00 AS DECIMAL(18,2)) AS CUSTOMERREFUND
    INTO #Calc
    FROM ITEM I
    WHERE I.ITEMID = @ITEMID OR @ITEMID = 0
    OPTION (RECOMPILE);

    CREATE UNIQUE CLUSTERED INDEX IX_Calc ON #Calc(ITEMID);

    -- ==========================================================================================
    -- 2. MATERIALIZE ITEM -> ITEMCODE -> ITEMPRICE ONCE
    --    Every downstream aggregation joins through this instead of re-joining the 3 tables.
    -- ==========================================================================================
    SELECT
        C.ITEMID,
        C.ISOPENITEM,
        CAST(NULL AS DATETIME) AS LASTCOUNTINGDATE,   -- filled after the date cascade
        IC.ITEMCODEID,
        IP.ITEMPRICEID
    INTO #Map
    FROM #Calc C
    JOIN ITEMCODE  IC ON IC.ITEMID     = C.ITEMID
    JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
    OPTION (RECOMPILE);

    CREATE UNIQUE CLUSTERED INDEX IX_Map_IP   ON #Map(ITEMPRICEID);
    CREATE NONCLUSTERED INDEX     IX_Map_Item ON #Map(ITEMID)
        INCLUDE (ISOPENITEM, LASTCOUNTINGDATE, ITEMPRICEID);

    -- ==========================================================================================
    -- 3. LAST COUNTING DATE : resolve the 3 sources, then combine in ONE set-based UPDATE
    --    (replaces V2's 3 sequential UPDATE statements while preserving exact precedence)
    --      a) item-level    counting date  (highest priority)
    --      b) sub-category  counting date  (max with item-level)
    --      c) category      counting date  (only fills rows still NULL)
    -- ==========================================================================================

    -- 3a. Item-level date (reuses #Map for the itemprice -> item link)
    SELECT M.ITEMID, MAX(CAI.CREATEDDATE) AS ITEMDATE
    INTO #CntItem
    FROM COUNTINGAPPROVALITEM CAI
    JOIN COUNTINGAPPROVAL     CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
    JOIN #Map                 M  ON M.ITEMPRICEID         = CAI.ITEMPRICEID
    WHERE CA.BRANCHID = @BranchID
      AND CAI.CREATEDDATE < @ToDate
    GROUP BY M.ITEMID
    OPTION (RECOMPILE);
    CREATE UNIQUE CLUSTERED INDEX IX_CntItem ON #CntItem(ITEMID);

    -- Read COUNTINGAPPROVALCATEGORYMAP ONCE (branch + date filtered), then derive both maps
    SELECT CAC.SUBCATEGORYID, CAC.CATEGORYID, CAC.CREATEDDATE
    INTO #CatMapRaw
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
    JOIN COUNTINGAPPROVAL            CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
    WHERE CA.BRANCHID = @BranchID
      AND CAC.CREATEDDATE < @ToDate
    OPTION (RECOMPILE);

    -- 3b. Sub-category date
    SELECT SUBCATEGORYID, MAX(CREATEDDATE) AS SUBDATE
    INTO #CntSub
    FROM #CatMapRaw
    WHERE SUBCATEGORYID IS NOT NULL
    GROUP BY SUBCATEGORYID;
    CREATE UNIQUE CLUSTERED INDEX IX_CntSub ON #CntSub(SUBCATEGORYID);

    -- 3c. Category date
    SELECT CATEGORYID, MAX(CREATEDDATE) AS CATDATE
    INTO #CntCat
    FROM #CatMapRaw
    WHERE CATEGORYID IS NOT NULL
    GROUP BY CATEGORYID;
    CREATE UNIQUE CLUSTERED INDEX IX_CntCat ON #CntCat(CATEGORYID);

    -- Combine in ONE pass (exact V2 precedence):
    --   L2 = item vs sub  : if sub present and (item null or sub > item) -> sub else item
    --   CASCADEDATE = COALESCE(L2, category)   (category only used when L2 is NULL)
    UPDATE C
    SET C.CASCADEDATE =
        COALESCE(
            CASE
                WHEN s.SUBDATE IS NOT NULL AND (i.ITEMDATE IS NULL OR s.SUBDATE > i.ITEMDATE)
                    THEN s.SUBDATE
                ELSE i.ITEMDATE
            END,
            cat.CATDATE
        )
    FROM #Calc C
    LEFT JOIN #CntItem i   ON i.ITEMID        = C.ITEMID
    LEFT JOIN #CntSub  s   ON s.SUBCATEGORYID = C.SUBCATEGORYID
    LEFT JOIN #CntCat  cat ON cat.CATEGORYID  = C.CATEGORYID
    OPTION (RECOMPILE);

    -- ==========================================================================================
    -- 4. STOCKSUMMARY : ONE scan feeds BOTH the FY opening balance AND the closing stock
    -- ==========================================================================================
    SELECT
        M.ITEMID,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN SS.FYOPENINGWEIGHTINKGS ELSE SS.FYOPENINGQUANTITY END) AS FYOPENING,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN SS.WEIGHTINKGS          ELSE SS.QUANTITY           END) AS STOCKSUMMARY
    INTO #SS
    FROM STOCKSUMMARY SS
    JOIN #Map M ON M.ITEMPRICEID = SS.ITEMPRICEID
    WHERE SS.BRANCHID = @BranchID
    GROUP BY M.ITEMID, M.ISOPENITEM
    OPTION (RECOMPILE);
    CREATE UNIQUE CLUSTERED INDEX IX_SS ON #SS(ITEMID);

    -- push FY opening onto the driver (rounded to (18,2) exactly like V2's OPENINGBALANCE store)
    UPDATE C
    SET C.FYOPENING = ss.FYOPENING
    FROM #Calc C
    JOIN #SS ss ON ss.ITEMID = C.ITEMID;

    -- ==========================================================================================
    -- 5. STOCK COUNTING opening balance (ONE scan) -- only for items with a resolved date
    --    date-level comparison, exactly as V2's CAST(... AS DATE) >= CAST(... AS DATE)
    -- ==========================================================================================
    SELECT
        C.ITEMID,
SUM(CASE WHEN C.ISOPENITEM = 1 THEN SCD.WEIGHTINKGS ELSE SCD.QUANTITY END) AS OB
    INTO #CntOpen
    FROM #Calc C
    JOIN #Map               M   ON M.ITEMID          = C.ITEMID
    JOIN STOCKCOUNTINGDETAIL SCD ON SCD.ITEMPRICEID   = M.ITEMPRICEID
    JOIN STOCKCOUNTING       SC  ON SC.STOCKCOUNTINGID = SCD.STOCKCOUNTINGID
    WHERE C.CASCADEDATE IS NOT NULL
      AND SCD.DELETEDDATE IS NULL
      AND SC.BRANCHID = @BranchID
      AND (SC.STATUS = 2 OR SC.STATUS = 3)
      AND CAST(SC.STOCKACCEPTEDDATE AS DATE) >= CAST(C.CASCADEDATE AS DATE)
    GROUP BY C.ITEMID, C.ISOPENITEM
    OPTION (RECOMPILE);
    CREATE UNIQUE CLUSTERED INDEX IX_CntOpen ON #CntOpen(ITEMID);

    -- ==========================================================================================
    -- 6. FINALISE OpeningBalance + LastCountingDate in ONE UPDATE (replaces V2 2d + 2e)
    --      counting date >= FY start  -> keep counting date, use counting-detail opening
    --      otherwise (incl. NULL)     -> reset to FY start, use FY opening
    -- ==========================================================================================
    UPDATE C
    SET
        C.LASTCOUNTINGDATE =
            CASE WHEN C.CASCADEDATE IS NOT NULL AND C.CASCADEDATE >= @FinYearStartDate
                 THEN C.CASCADEDATE
                 ELSE CAST(@FinYearStartDate AS DATETIME) END,
        C.OPENINGBALANCE =
            CASE WHEN C.CASCADEDATE IS NOT NULL AND C.CASCADEDATE >= @FinYearStartDate
                 THEN ISNULL(co.OB, 0)
                 ELSE ISNULL(C.FYOPENING, 0) END
    FROM #Calc C
    LEFT JOIN #CntOpen co ON co.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    -- push the FINAL date onto the map so all transaction aggregations read it locally
    UPDATE M
    SET M.LASTCOUNTINGDATE = C.LASTCOUNTINGDATE
    FROM #Map M
    JOIN #Calc C ON C.ITEMID = M.ITEMID;

    -- ==========================================================================================
    -- 7. OPENING BALANCE -> ledger driver
    -- ==========================================================================================
    -- (already stored in #Calc.OPENINGBALANCE; nothing further needed)

    -- ==========================================================================================
    -- 8. TRANSACTION AGGREGATIONS -- each source table scanned ONCE, UPDATE...JOIN into columns
    -- ==========================================================================================

    ------------------------------------------------------------------ Stock Entry (credit)
    UPDATE C
    SET C.STOCKENTRY = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1 THEN SUM(SED.WEIGHTINKGS) ELSE SUM(SED.QUANTITY) END AS VAL
        FROM #Map M
        JOIN ITEMCOSTPRICE     ICP ON ICP.ITEMPRICEID     = M.ITEMPRICEID
        JOIN STOCKENTRYDETAIL  SED ON SED.ITEMCOSTPRICEID  = ICP.ITEMCOSTPRICEID
        JOIN STOCKENTRY        SE  ON SE.STOCKENTRYID      = SED.STOCKENTRYID
        WHERE SED.DELETEDDATE IS NULL
          AND SE.STATUS = 1
          AND SE.CREATEDDATE > M.LASTCOUNTINGDATE
          AND SE.CREATEDDATE < @ToDate
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Stock Dispatch-Out (debit)
    UPDATE C
    SET C.STOCKDISPATCHOUT = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1 THEN SUM(SDD.WEIGHTINKGS) ELSE SUM(SDD.DISPATCHQUANTITY) END AS VAL
        FROM #Map M
        JOIN STOCKDISPATCHDETAIL SDD ON SDD.ITEMPRICEID    = M.ITEMPRICEID
        JOIN STOCKDISPATCH       SD  ON SD.STOCKDISPATCHID  = SDD.STOCKDISPATCHID
        WHERE SDD.DELETEDDATE IS NULL
          AND SD.DELETEDDATE  IS NULL
          AND SD.STATUS <> 0
          AND SD.CREATEDDATE > M.LASTCOUNTINGDATE
          AND SD.CREATEDDATE < @ToDate
          AND SD.FROMBRANCHID = @BranchID
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Branch Refund (credit)
    -- open + non-open collapsed into ONE scan; the open flag selects date column + measure
    UPDATE C
    SET C.BRANCHREFUND = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               SUM(CASE WHEN M.ISOPENITEM = 1 THEN BRD.WEIGHTINKGS ELSE BRD.QUANTITY END) AS VAL
        FROM #Map M
        JOIN POS_BREFUNDDETAIL BRD ON BRD.ITEMPRICEID = M.ITEMPRICEID
        JOIN POS_BREFUND       BD  ON BD.BRID         = BRD.BRID
        JOIN REASONFORREFUND   ROR ON ROR.REASONID    = BRD.REASONID
        WHERE BRD.DELETEDDATE IS NULL
          AND BD.DELETEDDATE  IS NULL
          AND BD.IsAccepted = 1
          AND ROR.LOCATIONTOMOVESTOCK = @WHId
          AND (
                (M.ISOPENITEM = 0 AND BD.ACCEPTEDDATE > M.LASTCOUNTINGDATE AND BD.ACCEPTEDDATE < @ToDate)
             OR (M.ISOPENITEM = 1 AND BD.UPDATEDDATE  > M.LASTCOUNTINGDATE AND BD.UPDATEDDATE  < @ToDate)
              )
        GROUP BY M.ITEMID
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Supplier Refund (debit)
    UPDATE C
    SET C.SUPPLIERREFUND = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1 THEN SUM(SRD.WEIGHTINKGS) ELSE SUM(SRD.QUANTITY) END AS VAL
        FROM #Map M
        JOIN ITEMCOSTPRICE          ICP ON ICP.ITEMPRICEID       = M.ITEMPRICEID
        JOIN SUPPLIERRETURNSDETAIL  SRD ON SRD.ITEMCOSTPRICEID    = ICP.ITEMCOSTPRICEID
        JOIN SUPPLIERRETURNS        SR  ON SR.SUPPLIERRETURNSID   = SRD.SUPPLIERRETURNSID
        WHERE SRD.DELETEDDATE IS NULL
          AND SR.DELETEDDATE  IS NULL
          AND SR.BRANCHID = @BranchID
          AND SR.STATUS = 1
          AND ISNULL(SRD.RETURNSTATUS, 0) = 1
          AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) > M.LASTCOUNTINGDATE
          AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) < @ToDate
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Stock Adjustment (signed)
    -- store credit-debit as a single signed value; totals split it back out in the final SELECT
    UPDATE C
    SET C.STOCKADJUSTMENT = x.VAL
    FROM #Calc C
    JOIN (
        SELECT M.ITEMID,
               CASE WHEN M.ISOPENITEM = 1
                    THEN SUM(SA.WEIGHTINKGS - SA.PREVWEIGHTINKGS)
                    ELSE SUM(SA.QUANTITY    - SA.PREVQUANTITY) END AS VAL
        FROM #Map M
        JOIN STOCKADJUSTMENT     SA  ON SA.ITEMPRICEID          = M.ITEMPRICEID
        JOIN STOCKADJUSTMENTTYPE SAT ON SAT.STOCKADJUSTMENTTYPEID = SA.STOCKADJUSTMENTTYPEID
        WHERE SA.CREATEDDATE > M.LASTCOUNTINGDATE
          AND SA.CREATEDDATE < @ToDate
          AND SA.BRANCHID = @BranchID
        GROUP BY M.ITEMID, M.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ #SALE : POS_BILLDETAIL ONCE
    -- built without the per-item date filter so it can serve BOTH Sale and Customer Refund
    SELECT
        M.ITEMID,
        M.ISOPENITEM,
        M.LASTCOUNTINGDATE,
        PBD.BILLDETAILID,
        PBD.BRANCHCOUNTERID,
        PBD.CREATEDDATE,
        PBD.QUANTITY,
        PBD.WEIGHTINKGS
    INTO #SALE
    FROM #Map M
    JOIN POS_BILLDETAIL PBD ON PBD.ITEMPRICEID     = M.ITEMPRICEID
    JOIN POS_BILL       PB  ON PB.BILLID           = PBD.BILLID
                           AND PB.BRANCHCOUNTERID  = PBD.BRANCHCOUNTERID
    JOIN BRANCHCOUNTER  BC  ON BC.COUNTERID        = PB.BRANCHCOUNTERID
    WHERE BC.BRANCHID = @BranchID
      AND PBD.DELETEDDATE IS NULL
      AND PB.DELETEDDATE  IS NULL
      AND PB.BILLSTATUS = 1
	  AND PB.DAYCLOSUREID IS NOT NULL
	  AND PBD.DAYCLOSUREID IS NOT NULL
    OPTION (RECOMPILE);

    CREATE CLUSTERED INDEX IX_SALE     ON #SALE(BILLDETAILID, BRANCHCOUNTERID);
    CREATE NONCLUSTERED INDEX IX_SALE_I ON #SALE(ITEMID);

    ------------------------------------------------------------------ Sale (debit)
    UPDATE C
    SET C.SALE = x.VAL
    FROM #Calc C
    JOIN (
        SELECT S.ITEMID,
               CASE WHEN S.ISOPENITEM = 1 THEN SUM(S.WEIGHTINKGS) ELSE SUM(S.QUANTITY) END AS VAL
        FROM #SALE S
        WHERE S.CREATEDDATE > S.LASTCOUNTINGDATE
          AND S.CREATEDDATE < @ToDate
        GROUP BY S.ITEMID, S.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    ------------------------------------------------------------------ Customer Refund (credit)
    UPDATE C
    SET C.CUSTOMERREFUND = x.VAL
    FROM #Calc C
    JOIN (
        SELECT S.ITEMID,
               CASE WHEN S.ISOPENITEM = 1 THEN SUM(CRF.REFUNDWEIGHTINKGS) ELSE SUM(CRF.REFUNDQUANTITY) END AS VAL
        FROM #SALE S
        JOIN POS_CREFUND CRF ON CRF.BILLDETAILID = S.BILLDETAILID
                            AND CRF.COUNTERID    = S.BRANCHCOUNTERID
        WHERE CRF.DELETEDDATE IS NULL
          AND CRF.CREATEDDATE > S.LASTCOUNTINGDATE
          AND CRF.CREATEDDATE < @ToDate
        GROUP BY S.ITEMID, S.ISOPENITEM
    ) x ON x.ITEMID = C.ITEMID
    OPTION (RECOMPILE);

    -- ==========================================================================================
    -- 9. FINAL RESULT (identical columns / order / filter / sort to V2)
    --    LedgerSummary, TotalCredit, TotalDebit reconstructed from the column values.
    -- ==========================================================================================
    ;WITH L AS
    (
        SELECT
            C.*,
            ( C.OPENINGBALANCE + C.STOCKENTRY - C.STOCKDISPATCHOUT + C.BRANCHREFUND
              - C.SUPPLIERREFUND + C.STOCKADJUSTMENT - C.SALE + C.CUSTOMERREFUND ) AS LEDGERSUMMARY_C,
            ( C.OPENINGBALANCE + C.STOCKENTRY + C.BRANCHREFUND + C.CUSTOMERREFUND
              + CASE WHEN C.STOCKADJUSTMENT > 0 THEN C.STOCKADJUSTMENT ELSE 0 END ) AS TOTALCREDIT_C,
            ( C.STOCKDISPATCHOUT + C.SUPPLIERREFUND + C.SALE
              + CASE WHEN C.STOCKADJUSTMENT > 0 THEN 0 ELSE -C.STOCKADJUSTMENT END ) AS TOTALDEBIT_C
        FROM #Calc C
    )
    SELECT
        L.ITEMID,
        L.SKUCODE,
        L.ITEMNAME,
        L.CATEGORYID,
        L.SUBCATEGORYID,
        L.ISOPENITEM,
        L.LASTCOUNTINGDATE,
        L.OPENINGBALANCE,
        L.STOCKENTRY,
        L.STOCKDISPATCHOUT,
        L.BRANCHREFUND,
        L.SUPPLIERREFUND,
        L.STOCKADJUSTMENT,
        L.SALE,
        L.CUSTOMERREFUND,
        ISNULL(SS.STOCKSUMMARY, 0)                        AS STOCKSUMMARY,
        L.LEDGERSUMMARY_C                                 AS LEDGERSUMMARY,
        ISNULL(SS.STOCKSUMMARY, 0) - L.LEDGERSUMMARY_C    AS DIFFERENCE,
        L.TOTALCREDIT_C                                   AS TOTALCREDIT,
        L.TOTALDEBIT_C                                    AS TOTALDEBIT
    FROM L
    LEFT JOIN #SS SS ON SS.ITEMID = L.ITEMID
    WHERE ISNULL(SS.STOCKSUMMARY, 0) <> L.LEDGERSUMMARY_C
    ORDER BY L.ITEMNAME
    OPTION (RECOMPILE);

END
GO
/****** Object:  StoredProcedure [dbo].[DEBUG_USP_SS_STOCKSUMMARYLOG_BY_ITEM_BRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[DEBUG_USP_SS_STOCKSUMMARYLOG_BY_ITEM_BRANCH]
(
      @ITEMID   INT
    , @BRANCHID INT = 45
    , @ToDate   DATE = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @FinYearStartDate DATE = '2023-04-01';

    IF @ToDate IS NULL
        SET @ToDate = CAST(GETDATE() AS DATE);

    -- Exclusive upper bound
    SET @ToDate = DATEADD(DAY, 1, @ToDate);

    IF OBJECT_ID('tempdb..#ItemBase') IS NOT NULL
        DROP TABLE #ItemBase;

    -----------------------------------------------------------------------
    -- Build ItemBase exactly like DEBUG_USP_SS_STOCKSUMMARYLOG_WH
    -----------------------------------------------------------------------

    SELECT
          I.ITEMID
        , I.SKUCODE
        , I.ITEMNAME
        , I.CATEGORYID
        , I.SUBCATEGORYID
        , ISNULL(I.ISOPENITEM,0) AS ISOPENITEM
        , CAST(NULL AS DATETIME) AS LASTCOUNTINGDATE
    INTO #ItemBase
    FROM ITEM I
    WHERE I.ITEMID = @ITEMID;

    /* Item Counting Date */
    UPDATE IB
    SET LASTCOUNTINGDATE = CAI.LASTCOUNTINGDATE
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT
              IC.ITEMID
            , MAX(CAI.CREATEDDATE) LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALITEM CAI
        INNER JOIN COUNTINGAPPROVAL CA
            ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
        INNER JOIN ITEMPRICE IP
            ON IP.ITEMPRICEID = CAI.ITEMPRICEID
        INNER JOIN ITEMCODE IC
            ON IC.ITEMCODEID = IP.ITEMCODEID
        WHERE CA.BRANCHID = @BRANCHID
          AND CAI.CREATEDDATE < @ToDate
        GROUP BY IC.ITEMID
    ) CAI
        ON CAI.ITEMID = IB.ITEMID;

    /* SubCategory Counting Date */
    UPDATE IB
    SET LASTCOUNTINGDATE =
        CASE
            WHEN CAC.LASTCOUNTINGDATE > ISNULL(IB.LASTCOUNTINGDATE,'1900-01-01')
            THEN CAC.LASTCOUNTINGDATE
            ELSE IB.LASTCOUNTINGDATE
        END
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT
              CAC.SUBCATEGORYID
            , MAX(CAC.CREATEDDATE) LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALCATEGORYMAP CAC
        INNER JOIN COUNTINGAPPROVAL CA
            ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
        WHERE CA.BRANCHID = @BRANCHID
          AND CAC.CREATEDDATE < @ToDate
          AND CAC.SUBCATEGORYID IS NOT NULL
        GROUP BY CAC.SUBCATEGORYID
    ) CAC
        ON CAC.SUBCATEGORYID = IB.SUBCATEGORYID;

    /* Category Counting Date */
    UPDATE IB
    SET LASTCOUNTINGDATE = CAC.LASTCOUNTINGDATE
    FROM #ItemBase IB
    INNER JOIN
    (
        SELECT
              CAC.CATEGORYID
            , MAX(CAC.CREATEDDATE) LASTCOUNTINGDATE
        FROM COUNTINGAPPROVALCATEGORYMAP CAC
        INNER JOIN COUNTINGAPPROVAL CA
            ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
        WHERE CA.BRANCHID = @BRANCHID
          AND CAC.CREATEDDATE < @ToDate
          AND CAC.CATEGORYID IS NOT NULL
        GROUP BY CAC.CATEGORYID
    ) CAC
        ON CAC.CATEGORYID = IB.CATEGORYID
    WHERE IB.LASTCOUNTINGDATE IS NULL;

    UPDATE #ItemBase
    SET LASTCOUNTINGDATE = ISNULL(LASTCOUNTINGDATE,'1900-01-01');

    UPDATE #ItemBase
    SET LASTCOUNTINGDATE = @FinYearStartDate
    WHERE LASTCOUNTINGDATE < @FinYearStartDate;

    -----------------------------------------------------------------------
    -- Stock Summary Log
    -----------------------------------------------------------------------

    SELECT
          SSL.CREATEDDATE
        , SSL.TTYPE
        , SSL.STOCKSUMMARYLOGID
        , IC.ITEMID
        , IC.SKUCODE
        , SS.BRANCHID
        , SS.ITEMPRICEID
        , SSL.OLDQTY
        , SSL.QUANTITY
        , SSL.QUANTITY - SSL.OLDQTY AS QTYCHANGE
        , SSL.OLDWEIGHT
        , SSL.WEIGHTINKGS
        , SSL.WEIGHTINKGS - SSL.OLDWEIGHT AS WEIGHTCHANGE
        , SSL.CREATEDBY
        , SSL.*
    FROM STOCKSUMMARYLOG SSL
    INNER JOIN STOCKSUMMARY SS
        ON SSL.STOCKSUMMARYID = SS.STOCKSUMMARYID
    INNER JOIN ITEMPRICE IP
        ON SS.ITEMPRICEID = IP.ITEMPRICEID
    INNER JOIN ITEMCODE IC
        ON IP.ITEMCODEID = IC.ITEMCODEID
    INNER JOIN #ItemBase IB
        ON IB.ITEMID = IC.ITEMID
    WHERE SS.BRANCHID = @BRANCHID
      AND SSL.CREATEDDATE > IB.LASTCOUNTINGDATE
      AND SSL.CREATEDDATE < @ToDate
    ORDER BY SSL.CREATEDDATE,
             SSL.STOCKSUMMARYLOGID;

END;
GO
/****** Object:  StoredProcedure [dbo].[DEBUG_USP_SS_STOCKSUMMARYLOG_WH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[DEBUG_USP_SS_STOCKSUMMARYLOG_WH]
	@ITEMID INT = 0
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE
		@BranchID INT = 45,
		@ToDate DATE = DATEADD(DAY, 1, CAST(GETDATE() AS DATE)),
		@FinYearStartDate DATE = '2023-04-01';

	IF OBJECT_ID('tempdb..#ItemBase') IS NOT NULL DROP TABLE #ItemBase;
	IF OBJECT_ID('tempdb..#StockSummaryLog') IS NOT NULL DROP TABLE #StockSummaryLog;
	IF OBJECT_ID('tempdb..#StockSummaryCurrent') IS NOT NULL DROP TABLE #StockSummaryCurrent;

	SELECT
		I.ITEMID,
		I.SKUCODE,
		I.ITEMNAME,
		I.CATEGORYID,
		I.SUBCATEGORYID,
		ISNULL(I.ISOPENITEM, 0) AS ISOPENITEM,
		CAST(NULL AS DATETIME) AS LASTCOUNTINGDATE
	INTO #ItemBase
	FROM ITEM I
	WHERE I.ITEMID = @ITEMID OR @ITEMID = 0;

	UPDATE IB
	SET IB.LASTCOUNTINGDATE = CAI.LASTCOUNTINGDATE
	FROM #ItemBase IB
	INNER JOIN
	(
		SELECT
			IC.ITEMID,
			MAX(CAI.CREATEDDATE) AS LASTCOUNTINGDATE
		FROM COUNTINGAPPROVALITEM CAI
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CAI.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		WHERE CA.BRANCHID = @BranchID
			AND CAI.CREATEDDATE < @ToDate
		GROUP BY IC.ITEMID
	) CAI ON CAI.ITEMID = IB.ITEMID;

	UPDATE IB
	SET IB.LASTCOUNTINGDATE =
		CASE
			WHEN CAC.LASTCOUNTINGDATE > ISNULL(IB.LASTCOUNTINGDATE, '1900-01-01') THEN CAC.LASTCOUNTINGDATE
			ELSE IB.LASTCOUNTINGDATE
		END
	FROM #ItemBase IB
	INNER JOIN
	(
		SELECT
			CAC.SUBCATEGORYID,
			MAX(CAC.CREATEDDATE) AS LASTCOUNTINGDATE
		FROM COUNTINGAPPROVALCATEGORYMAP CAC
		INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
		WHERE CA.BRANCHID = @BranchID
			AND CAC.CREATEDDATE < @ToDate
			AND CAC.SUBCATEGORYID IS NOT NULL
		GROUP BY CAC.SUBCATEGORYID
	) CAC ON CAC.SUBCATEGORYID = IB.SUBCATEGORYID;

	UPDATE IB
	SET IB.LASTCOUNTINGDATE = CAC.LASTCOUNTINGDATE
	FROM #ItemBase IB
	INNER JOIN
	(
		SELECT
			CAC.CATEGORYID,
			MAX(CAC.CREATEDDATE) AS LASTCOUNTINGDATE
		FROM COUNTINGAPPROVALCATEGORYMAP CAC
		INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
		WHERE CA.BRANCHID = @BranchID
			AND CAC.CREATEDDATE < @ToDate
			AND CAC.CATEGORYID IS NOT NULL
		GROUP BY CAC.CATEGORYID
	) CAC ON CAC.CATEGORYID = IB.CATEGORYID
	WHERE IB.LASTCOUNTINGDATE IS NULL;

	UPDATE #ItemBase
	SET LASTCOUNTINGDATE = ISNULL(LASTCOUNTINGDATE, '1900-01-01');

	UPDATE #ItemBase
	SET LASTCOUNTINGDATE = @FinYearStartDate
	WHERE LASTCOUNTINGDATE < @FinYearStartDate;

	SELECT
		IB.ITEMID,
		IB.SKUCODE,
		IB.ITEMNAME,
		IB.CATEGORYID,
		IB.SUBCATEGORYID,
		IB.ISOPENITEM,
		IB.LASTCOUNTINGDATE,
		SS.STOCKSUMMARYID,
		SS.ITEMPRICEID,
		SSL.STOCKSUMMARYLOGID,
		SSL.CREATEDDATE,
		SSL.TTYPE,
		ISNULL(SSL.OLDQTY, 0) AS OLDQTY,
		ISNULL(SSL.QUANTITY, 0) AS QUANTITY,
		ISNULL(SSL.OLDWEIGHT, 0) AS OLDWEIGHT,
		ISNULL(SSL.WEIGHTINKGS, 0) AS WEIGHTINKGS,
		CAST(ISNULL(SSL.QUANTITY, 0) - ISNULL(SSL.OLDQTY, 0) AS DECIMAL(18, 2)) AS QTYCHANGE,
		CAST(ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0) AS DECIMAL(18, 2)) AS WEIGHTCHANGE,
		CAST(
			CASE
				WHEN IB.ISOPENITEM = 1 THEN ISNULL(SSL.WEIGHTINKGS, 0) - ISNULL(SSL.OLDWEIGHT, 0)
				ELSE ISNULL(SSL.QUANTITY, 0) - ISNULL(SSL.OLDQTY, 0)
			END
			AS DECIMAL(18, 2)
		) AS STOCKCHANGE
	INTO #StockSummaryLog
	FROM #ItemBase IB
	INNER JOIN ITEMCODE IC ON IC.ITEMID = IB.ITEMID
	INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
	INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID AND SS.BRANCHID = @BranchID
	INNER JOIN STOCKSUMMARYLOG SSL ON SSL.STOCKSUMMARYID = SS.STOCKSUMMARYID
	WHERE SSL.CREATEDDATE > IB.LASTCOUNTINGDATE
		AND SSL.CREATEDDATE < @ToDate;

	SELECT
		IB.ITEMID,
		SUM(CASE WHEN IB.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) AS CURRENTSTOCKSUMMARY
	INTO #StockSummaryCurrent
	FROM #ItemBase IB
	INNER JOIN ITEMCODE IC ON IC.ITEMID = IB.ITEMID
	INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
	INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID AND SS.BRANCHID = @BranchID
	GROUP BY IB.ITEMID;

	SELECT
		SL.ITEMID,
		SL.SKUCODE,
		SL.ITEMNAME,
		SL.CATEGORYID,
		SL.SUBCATEGORYID,
		SL.ISOPENITEM,
		SL.LASTCOUNTINGDATE,
		ISNULL(SSC.CURRENTSTOCKSUMMARY, 0) AS CURRENTSTOCKSUMMARY,
		SUM(CASE WHEN SL.TTYPE = 'SC' THEN SL.STOCKCHANGE ELSE 0 END) AS SC_STOCKCOUNTING,
		SUM(CASE WHEN SL.TTYPE = 'SE' THEN SL.STOCKCHANGE ELSE 0 END) AS SE_STOCKENTRY,
		SUM(CASE WHEN SL.TTYPE = 'SD' THEN SL.STOCKCHANGE ELSE 0 END) AS SD_STOCKDISPATCH,
		SUM(CASE WHEN SL.TTYPE = 'DR' THEN SL.STOCKCHANGE ELSE 0 END) AS DR_DISPATCHREVERT,
		SUM(CASE WHEN SL.TTYPE = 'BR' THEN SL.STOCKCHANGE ELSE 0 END) AS BR_BRANCHREFUND,
		SUM(CASE WHEN SL.TTYPE = 'SR' THEN SL.STOCKCHANGE ELSE 0 END) AS SR_SUPPLIERRETURNS,
		SUM(CASE WHEN SL.TTYPE NOT IN ('SC', 'SE', 'SD', 'DR', 'BR', 'SR') OR SL.TTYPE IS NULL THEN SL.STOCKCHANGE ELSE 0 END) AS OTHERCHANGE,
		SUM(SL.STOCKCHANGE) AS TOTALLOGCHANGE,
		COUNT(1) AS LOGCOUNT,
		MIN(SL.CREATEDDATE) AS FIRSTLOGDATE,
		MAX(SL.CREATEDDATE) AS LASTLOGDATE
	FROM #StockSummaryLog SL
	LEFT JOIN #StockSummaryCurrent SSC ON SSC.ITEMID = SL.ITEMID
	GROUP BY
		SL.ITEMID,
		SL.SKUCODE,
		SL.ITEMNAME,
		SL.CATEGORYID,
		SL.SUBCATEGORYID,
		SL.ISOPENITEM,
		SL.LASTCOUNTINGDATE,
		SSC.CURRENTSTOCKSUMMARY
	ORDER BY ABS(ISNULL(SSC.CURRENTSTOCKSUMMARY, 0)) DESC, SL.ITEMNAME;

	SELECT
		ITEMID,
		SKUCODE,
		ITEMNAME,
		STOCKSUMMARYID,
		ITEMPRICEID,
		STOCKSUMMARYLOGID,
		CREATEDDATE,
		TTYPE,
		OLDQTY,
		QUANTITY,
		QTYCHANGE,
		OLDWEIGHT,
		WEIGHTINKGS,
		WEIGHTCHANGE,
		STOCKCHANGE
	FROM #StockSummaryLog
	WHERE TTYPE = 'SE'
	ORDER BY ITEMNAME, ITEMID, CREATEDDATE, STOCKSUMMARYLOGID;
END;
GO
/****** Object:  StoredProcedure [dbo].[P_R_FINDITEMPRICEININOIVCE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[P_R_FINDITEMPRICEININOIVCE]
@STOCKENTRYID INT,
@ITEMPRICEID INT
AS
BEGIN

SELECT                           
		SE.STOCKENTRYDETAILID,I.ITEMID,I.ISOPENITEM,IC.ITEMCODEID,IP.ITEMPRICEID,
		I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,ICP.COSTPRICEWT,ICP.COSTPRICEWOT,    
		ICP.GSTID,IP.MRP,IP.SALEPRICE,SE.QUANTITY,SE.WEIGHTINKGS, SE.FREEQUANTITY,
		SE.DISCOUNTFLAT, SE.DISCOUNTPERCENTAGE, SE.SCHEMEPERCENTAGE, SE.SCHEMEFLAT, 
		SE.TOTALPRICEWT, SE.TOTALPRICEWOT, SE.APPLIEDDISCOUNT, SE.APPLIEDSCHEME, 
		G.GSTCODE, SE.APPLIEDDGST, SE.FINALPRICE,SE.CGST,SE.SGST,SE.IGST,SE.CESS,
		IC.HSNCODE
	FROM STOCKENTRYDETAIL SE                           
		LEFT JOIN ITEMCOSTPRICE ICP ON SE.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID            
		LEFT JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID            
		LEFT JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID            
		LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID            
		LEFT JOIN GSTDETAIL G ON IP.GSTID = G.GSTID            
	WHERE STOCKENTRYID = @STOCKENTRYID AND IP.ITEMPRICEID = @ITEMPRICEID
		AND SE.DELETEDDATE IS NULL  
	ORDER BY STOCKENTRYDETAILID DESC

END
GO
/****** Object:  StoredProcedure [dbo].[P_RPT_UNCLOSEDDAYCLOSURES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[P_RPT_UNCLOSEDDAYCLOSURES]    
AS    
BEGIN    
 select     
 distinct BRANCHCOUNTERID,bc.COUNTERNAME ,CAST(pb.CREATEDDATE as date)    
 from POS_BILL pb    
 inner join BRANCHCOUNTER bc on pb.BRANCHCOUNTERID = bc.COUNTERID    
 where pb.DAYCLOSUREID is null     
  and BILLSTATUS = 1     
  and bc.BRANCHID <> 92    
  and CAST(pb.CREATEDDATE as date) <> CAST(GETDATE() as date)
  order by 3 Desc  
END
GO
/****** Object:  StoredProcedure [dbo].[POS_USP_CU_BREFUND_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[POS_USP_CU_BREFUND_1]
@USERID INT,
@BRANCHID INT,
@CATEGORYID INT,
@BRID INT = 0 OUT,
@STOCKDISPATCHID INT = 0
AS                  
BEGIN                  

	DECLARE @BREFUNDNUMBER NVARCHAR(50)

	SELECT 
		@BRID = ISNULL(BREFUNDID,0),                
		@BREFUNDNUMBER = BREFUNDNUMBER 
	FROM POS_BREFUND                   
	WHERE BRANCHID = @BRANCHID
		AND CREATEDBY = @USERID 
		AND STATUS = 0 
		AND DELETEDDATE IS NULL 
		AND CATEGORYID IS NULL
                
	IF(ISNULL(@BRID,0) = 0)                
	BEGIN
         
		DECLARE @SNO INT
		SELECT @SNO = ISNULL(MAX(SNO),0) + 1 FROM POS_BREFUND WHERE BRANCHID = @BRANCHID

		SELECT @BREFUNDNUMBER =                 
			'BR-' + B.BRANCHCODE + '/' + REPLACE(CAST(CONVERT(date,GETDATE(),10) AS VARCHAR(15)),'-','') + '/' + RIGHT('00000' + CAST(@SNO AS varchar(10)) , 5)            
		FROM BRANCH B 
		WHERE B.BRANCHID = @BRANCHID
		 
		INSERT INTO POS_BREFUND
		(
			BRANCHID,
			BREFUNDNUMBER,
			CREATEDBY,
			CREATEDATE,
			STATUS,
			CATEGORYID,
			AUTOGENERATED, 
			REFID, 
			SOURCEENTITYID,
			SNO
		)                
		SELECT 
			@BRANCHID,
			@BREFUNDNUMBER,
			@USERID,
			GETDATE(),
			0, 
			@CATEGORYID, 
			CASE WHEN @STOCKDISPATCHID > 0 THEN 1 ELSE 0 END, 
			@STOCKDISPATCHID, 
			CASE WHEN @STOCKDISPATCHID > 0 THEN 1 ELSE 0 END,
			@SNO

		SET @BRID = SCOPE_IDENTITY()
                
	END                
                
	SELECT @BRID AS BRID, @BREFUNDNUMBER AS BREFUNDNUMBER, @CATEGORYID AS CATEGORYID
                  
END 
GO
/****** Object:  StoredProcedure [dbo].[POS_USP_CU_BREFUNDDETAIL_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
