CREATE PROCEDURE [dbo].[POS_USP_CU_BREFUNDDETAIL_1]          
@BRDID INT,          
@BRID INT,          
@ITEMPRICEID INT,          
@QUANTITY INT,          
@WEIGHTINKGS DECIMAL(10,2),        
@SNO INT,    
@TRAYNUMBER INT ,
@REASONID INT,
@REFUNDDESCRIPTION NVARCHAR(MAX)
          
AS          
BEGIN          

	IF NOT EXISTS
	(
		SELECT 1 FROM POS_BREFUND WHERE ISNULL(STATUS, 0) = 0 AND BRID = @BRID
	)
	BEGIN
		SELECT 'Refund sheet already completed'
		RETURN
	END

	IF(@BRDID > 0)          
	BEGIN          
          
		UPDATE POS_BREFUNDDETAIL 
		SET 
			QUANTITY = @QUANTITY,          
			WEIGHTINKGS = @WEIGHTINKGS ,
			UPDATEDDATE = GETDATE(),
			REASONID = @REASONID,
			REFUNDDESCRIPTION = @REFUNDDESCRIPTION
		WHERE BRDID = @BRDID          
          
	END          
	ELSE          
	BEGIN          

		INSERT INTO POS_BREFUNDDETAIL(BRID,ITEMPRICEID,QUANTITY,WEIGHTINKGS,CREATEDDATE,SNO,TRAYNUMBER,REASONID,REFUNDDESCRIPTION)
		SELECT @BRID,@ITEMPRICEID,@QUANTITY,@WEIGHTINKGS,GETDATE(),@SNO,@TRAYNUMBER ,@REASONID, @REFUNDDESCRIPTION

		SET @BRDID = SCOPE_IDENTITY()

	END          
          
	SELECT @BRDID
          
END
GO
