/****** Object:  StoredProcedure [dbo].[POS_USP_FINISH_STOCKIN]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[POS_USP_FINISH_STOCKIN]    
(    
	@UserID INT, 
	@StockDispatchID INT, 
	@DispatchDetails POS_FINSIH_STOCKDISPATCHDETAIL READONLY, 
	@COUNTERID INT = 0
)    
AS    
BEGIN 

	IF EXISTS ( SELECT 1 FROM STOCKDISPATCH SD WHERE SD.STOCKDISPATCHID = @StockDispatchID AND STATUS = 2 )
	BEGIN
		SELECT 'Stock-in already completed, the operation cannot proceed'
		RETURN
	END

	DECLARE @TOBRANCHID INT,  @BRANCHINDENTID INT = 0
	SELECT @TOBRANCHID = TOBRANCHID, @BRANCHINDENTID = BRANCHINDENTID FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @StockDispatchID

	 UPDATE STOCKDISPATCH    
	 SET     
	  STATUS = 2    
	  , STATUSAPPROVEDBY = @UserID    
	  , STATUSAPPROVEDDATE = GETDATE()    
	 WHERE STOCKDISPATCHID = @StockDispatchID    
    
	 UPDATE SDD    
	 SET    
	  SDD.RECEIVEDQUANTITY = USDD.RECEIVEDQUANTITY
	  ,SDD.ISACCEPTED = 1
	 FROM    
	  STOCKDISPATCHDETAIL SDD     
	  INNER JOIN @DispatchDetails USDD ON USDD.STOCKDISPATCHDETAILID = SDD.STOCKDISPATCHDETAILID    
	 WHERE SDD.DELETEDDATE IS NULL

	--Adding stock to branch                
	UPDATE SS SET   
		SS.QUANTITY = ISNULL(SS.QUANTITY,0) + SDD.QUANTITY,        
		SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS,0) + SDD.WEIGHTINKGS,  
		SS.TTYPE = 'SD', 
		SS.MODIFIEDDATE = GETDATE()    
	FROM STOCKSUMMARY SS        
		INNER JOIN          
		(  
			SELECT ISNULL(IP.STOCKMOVETOID,IP.ITEMPRICEID) AS ITEMPRICEID,
				SUM(DISPATCHQUANTITY) AS QUANTITY,   
				SUM(WEIGHTINKGS) AS WEIGHTINKGS         
			FROM STOCKDISPATCHDETAIL SDD
				INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID
			WHERE SDD.STOCKDISPATCHID = @StockDispatchID
				AND SDD.DELETEDDATE IS NULL
			GROUP BY ISNULL(IP.STOCKMOVETOID,IP.ITEMPRICEID)
		) SDD ON SS.ITEMPRICEID = SDD.ITEMPRICEID  
	WHERE SS.BRANCHID = @TOBRANCHID

	IF(@BRANCHINDENTID > 0)
	BEGIN
		UPDATE BRANCHINDENT SET ISCOMPLETED = 1 WHERE BRANCHINDENTID = @BRANCHINDENTID
	END

	--New dispatch has to be created for diff quantity
	EXEC USP_P_AUTOGENERATEDISPATCH @StockDispatchID, @UserID

	--New BR sheet need to be created for diff quantity
	EXEC USP_P_AUTOGENERATEBREFUND @StockDispatchID, @COUNTERID, @UserID

END
GO
/****** Object:  StoredProcedure [dbo].[POS_USP_FINISH_STOCKIN_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[POS_USP_FINISH_STOCKIN_v2]    
(    
	@StockDispatchID INT, 
	@UserID INT
)    
AS    
BEGIN 

	IF EXISTS ( SELECT 1 FROM STOCKDISPATCH SD WHERE SD.STOCKDISPATCHID = @StockDispatchID AND STATUS = 2 )
	BEGIN
		SELECT 'Dispatch receive already completed, the operation cannot proceed'
		RETURN
	END

	IF EXISTS(SELECT 1 FROM TRAYINFO WHERE STOCKDISPATCHID = @StockDispatchID AND ISACCEPTED = 0 AND DELETEDDATE IS NULL)
	BEGIN
		SELECT 'Few trays in selected dispatch are not verified, please complete them to proceed!'
		RETURN
	END

	DECLARE @TOBRANCHID INT, @COUNTERID INT = 0, @BRANCHINDENTID INT = 0
	SELECT @TOBRANCHID = TOBRANCHID, @BRANCHINDENTID = BRANCHINDENTID FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @StockDispatchID
	SELECT TOP(1) @COUNTERID = COUNTERID FROM BRANCHCOUNTER WHERE BRANCHID = @TOBRANCHID AND DELETEDDATE IS NULL ORDER BY CREATEDDATE DESC

	IF (@COUNTERID = 0)
	BEGIN
		SELECT 'Counters not mapped to this branch'
		RETURNn
	END

	 UPDATE STOCKDISPATCH    
	 SET STATUS = 2, 
		STATUSAPPROVEDBY = @UserID, 
		STATUSAPPROVEDDATE = GETDATE()    
	 WHERE STOCKDISPATCHID = @StockDispatchID    
    
	 UPDATE SDD    
	 SET SDD.ISACCEPTED = 1
	 FROM STOCKDISPATCHDETAIL SDD     
	 WHERE SDD.STOCKDISPATCHID = @StockDispatchID 
		AND SDD.DELETEDDATE IS NULL

	--Adding stock to branch                
	UPDATE SS SET   
		SS.QUANTITY = ISNULL(SS.QUANTITY,0) + SDD.QUANTITY,        
		SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS,0) + SDD.WEIGHTINKGS,  
		SS.TTYPE = 'SD', 
		SS.MODIFIEDDATE = GETDATE()    
	FROM STOCKSUMMARY SS        
		INNER JOIN          
		(  
			SELECT ISNULL(IP.STOCKMOVETOID,IP.ITEMPRICEID) AS ITEMPRICEID,
				SUM(DISPATCHQUANTITY) AS QUANTITY,   
				SUM(WEIGHTINKGS) AS WEIGHTINKGS         
			FROM STOCKDISPATCHDETAIL SDD
				INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID
			WHERE SDD.STOCKDISPATCHID = @StockDispatchID
				AND SDD.DELETEDDATE IS NULL
			GROUP BY ISNULL(IP.STOCKMOVETOID,IP.ITEMPRICEID)
		) SDD ON SS.ITEMPRICEID = SDD.ITEMPRICEID  
	WHERE SS.BRANCHID = @TOBRANCHID

	IF(@BRANCHINDENTID > 0)
	BEGIN
		UPDATE BRANCHINDENT SET ISCOMPLETED = 1 WHERE BRANCHINDENTID = @BRANCHINDENTID
	END

	--New dispatch has to be created for diff quantity
	EXEC USP_P_AUTOGENERATEDISPATCH @StockDispatchID, @UserID

	--New BR sheet need to be created for diff quantity
	EXEC USP_P_AUTOGENERATEBREFUND @StockDispatchID, @COUNTERID, @UserID

END
GO
/****** Object:  StoredProcedure [dbo].[POS_USP_FINISHBREFUND_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[POS_USP_FINISHBREFUND_1]    
@BRID INT = 0,
@FROMBRANCHID INT,
@TOBRANCHID INT = 0
AS    
BEGIN    

	IF NOT EXISTS
	(
		SELECT 1 FROM POS_BREFUND WHERE ISNULL(STATUS, 0) = 0 AND BRID = @BRID
	)
	BEGIN
		SELECT 'Refund sheet already completed'
		RETURN
	END

	IF NOT EXISTS(SELECT 1 FROM POS_BREFUNDDETAIL WHERE BRID = @BRID AND DELETEDDATE IS NULL)
	BEGIN
		SELECT 'No Items exists in current sheet to submit'
		RETURN
	END

	DECLARE @CURENTDATE DATETIME = GETDATE()

	DECLARE @BRANCHID INT, @SNO INT
	SELECT @BRANCHID = BRANCHID, @SNO = SNO FROM POS_BREFUND WHERE BRID = @BRID

	IF (@SNO IS NULL)
	BEGIN
		SELECT @SNO = ISNULL(MAX(SNO),0) + 1 FROM POS_BREFUND WHERE BRANCHID = @BRANCHID
	END

	DECLARE @BREFUNDNUMBER NVARCHAR(50)

	SELECT @BREFUNDNUMBER = 'BR-' + B.BRANCHCODE + '/' + 
		REPLACE(CAST(CONVERT(date,@CURENTDATE,10) AS VARCHAR(15)),'-','') + '/' +          
		RIGHT('00000' + CAST(@SNO AS varchar(10)) , 5)          
	FROM BRANCH B WHERE B.BRANCHID = @BRANCHID

	UPDATE POS_BREFUND  SET 
		SNO = @SNO,
		BREFUNDNUMBER = @BREFUNDNUMBER,
		STATUS = 1,  
		UPDATEDBY = CREATEDBY,
		UPDATEDDATE = @CURENTDATE,
		CREATEDATE = @CURENTDATE
	WHERE BRID = @BRID

	--Deducting refund quantity and weight in Kgs from branch stock

	UPDATE SS 
		SET 
			SS.QUANTITY = SS.QUANTITY - UBRD.REFUNDQUANTITY,    
			SS.WEIGHTINKGS = SS.WEIGHTINKGS - UBRD.REFUNDWEIGHTINKGS,
			SS.TTYPE =  'BR', SS.MODIFIEDDATE = @CURENTDATE
		FROM STOCKSUMMARY SS 
			INNER JOIN 
			(
				SELECT ISNULL(PIP.STOCKMOVETOID, PIP.ITEMPRICEID) AS ITEMPRICEID
					, SUM(BRD.QUANTITY) AS REFUNDQUANTITY
					, SUM(BRD.WEIGHTINKGS) AS REFUNDWEIGHTINKGS
				FROM 
					POS_BREFUNDDETAIL BRD 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
					INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
				WHERE BRD.BRID = @BRID AND BRD.DELETEDDATE IS NULL
				GROUP BY ISNULL(PIP.STOCKMOVETOID, PIP.ITEMPRICEID)
			) UBRD ON SS.ITEMPRICEID = UBRD.ITEMPRICEID
		WHERE SS.BRANCHID = @FROMBRANCHID

	SELECT @BREFUNDNUMBER
    
END 
GO
/****** Object:  StoredProcedure [dbo].[POS_USP_I_GATEWAYPAYMENTPOSTING]    Script Date: 17-10-2026 13:04:47 ******/
