CREATE PROCEDURE [dbo].[POS_USP_I_GATEWAYPAYMENTPOSTING]
(
    @PAYMENTGATEWAYINFOID INT,
    @BILLNUMBER VARCHAR(100),
    @RAWDATA VARCHAR(MAX)
)
AS
BEGIN

    DECLARE
        @BRANCHCOUNTERID INT,
        @COUNTERID INT,
        @COUNTERCODE VARCHAR(50);

    SET @COUNTERCODE =
        LEFT(@BILLNUMBER, CHARINDEX('/', @BILLNUMBER) - 1);

    SELECT
        @COUNTERID = COUNTERID
    FROM BRANCHCOUNTER
    WHERE COUNTERNAME = @COUNTERCODE;

    INSERT INTO GATEWAYPAYMENTPOSTING
    (
        PAYMENTGATEWAYINFOID,
        COUNTERID,
        BILLNUMBER,
        RAWDATA
    )
    VALUES
    (
        @PAYMENTGATEWAYINFOID,
        @COUNTERID,
        @BILLNUMBER,
        @RAWDATA
    );

END
