/****** Object:  StoredProcedure [dbo].[POS_USP_R_BREFUND_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[POS_USP_R_BREFUND_1]                  
@USERID INT,                
@BRANCHID INT
AS                  
BEGIN                  

	SELECT 
		ISNULL(BRID,0) AS BRID , 
		BREFUNDNUMBER, 
		CATEGORYID 
	FROM POS_BREFUND                   
	WHERE BRANCHID = @BRANCHID
		AND CREATEDBY = @USERID 
		AND STATUS = 0 
		AND CATEGORYID IS NOT NULL 
		AND CATEGORYID <> 13
		AND DELETEDDATE IS NULL
                
	SELECT                   
		BD.BRDID, BD.BRID, IP.ITEMPRICEID,                                
		BD.SNO, I.ITEMNAME, IC.ITEMCODE, ISNULL(IC.HSNCODE,'') AS HSNCODE,
		IP.MRP, IP.SALEPRICE, BD.QUANTITY,                                
		BD.WEIGHTINKGS, ISNULL(I.ISOPENITEM,0) AS ISOPENITEM,      
		BD.TRAYNUMBER,BD.REASONID,RFR.REASONNAME, 
		BR.CATEGORYID, BD.REFUNDDESCRIPTION
	FROM POS_BREFUNDDETAIL BD                  
		INNER JOIN POS_BREFUND BR ON BD.BRID = BR.BRID
		INNER JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID                  
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID                  
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID                  
		LEFT JOIN REASONFORREFUND RFR ON BD.REASONID = RFR.REASONID  
	WHERE BR.BRANCHID = @BRANCHID
		AND BR.CREATEDBY = @USERID 
		AND BD.DELETEDDATE IS NULL 
		AND BR.STATUS = 0 
		AND BR.DELETEDDATE IS NULL 
		AND BR.CATEGORYID IS NOT NULL
		AND BR.CATEGORYID <> 13
	ORDER BY BD.SNO                  
                  
END
GO
