CREATE PROCEDURE [dbo].[POS_USP_R_ITEMCODES]  
@CATEGORYID INT = 0
AS  
BEGIN  
	SELECT   
	IC.ITEMCODEID  
	, IC.ITEMCODE  
	, I.ITEMNAME  
	, IC.FREEITEMCODEID  
	, IC.HSNCODE  
	, ISNULL(I.ISOPENITEM,0) as  ISOPENITEM
	, I.SKUCODE
	, I.ITEMID
	, I.CATEGORYID
	, I.SUBCATEGORYID
	FROM ITEMCODE IC   
	INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID  
	WHERE (I.CATEGORYID = @CATEGORYID OR @CATEGORYID = 0) AND IC.DELETEDDATE IS NULL  
END
