CREATE PROC [dbo].[POS_USP_R_ITEMMRPLIST]  
@ItemCodeID INT,
@FilterMRPByStock bit = 0
AS  
BEGIN 

	SELECT  
		IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, GST.GSTID, GST.GSTCODE, GST.SGST, GST.CGST, GST.IGST, GST.CESS
	FROM
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID  
		LEFT JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = IP.PARENTITEMPRICEID
	WHERE 
		IP.ITEMCODEID = @ItemCodeID 
		AND IP.DELETEDDATE IS NULL 
		AND PIP.DELETEDDATE IS NULL
	ORDER BY IP.ITEMPRICEID DESC

END
