/****** Object:  StoredProcedure [dbo].[POS_USP_R_STOCKDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[POS_USP_R_STOCKDISPATCH]
(
	@BranchID INT
)
AS
BEGIN

	SELECT 
		SD.STOCKDISPATCHID
		, SD.CATEGORYID
		, SD.DISPATCHNUMBER
		, CAT.CATEGORYNAME
		, SCAT.SUBCATEGORYNAME
		, AU.FULLNAME AS STATUSAPPROVEDBY
		, SD.STATUSAPPROVEDDATE
		, SD.CREATEDDATE
		, SD.STATUS
		, CASE WHEN SD.STATUS = 1 THEN 'In-Transit' WHEN SD.STATUS = 2 THEN 'Accepted' ELSE 'Unknown' END AS STATUSTEXT
	FROM 
		STOCKDISPATCH SD
		LEFT JOIN TBLCATEGORY CAT ON SD.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT ON SD.SUBCATEGORYID = SCAT.SUBCATEGORYID
		LEFT JOIN TBLUSER AU ON SD.STATUSAPPROVEDBY = AU.USERID
	WHERE 
		SD.TOBRANCHID = @BranchID
		AND ISNULL(SD.STATUS, 0) <> 0
		AND SD.DELETEDBY IS NULL
	ORDER BY SD.CREATEDDATE DESC
		
END
GO
/****** Object:  StoredProcedure [dbo].[POS_USP_R_STOCKDISPATCH_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[POS_USP_R_STOCKDISPATCH_v2]
(
	@BranchID INT
)
AS
BEGIN

	IF NOT EXISTS(SELECT 1 FROM STOCKDISPATCH SD 
					WHERE TOBRANCHID = @BranchID AND STATUS = 1 AND DELETEDDATE IS NULL)
				BEGIN
					SELECT 'No dispatches exists'
					RETURN
				END


	SELECT 
		SD.STOCKDISPATCHID
		, SD.CATEGORYID
		, SD.DISPATCHNUMBER
		, CAT.CATEGORYNAME
		, SCAT.SUBCATEGORYNAME
		, AU.FULLNAME AS STATUSAPPROVEDBY
		, SD.STATUSAPPROVEDDATE
		, SD.CREATEDDATE AS DISPATCHDATE
		, SD.STATUS
		, CASE WHEN SD.STATUS = 1 THEN 'In-Transit' WHEN SD.STATUS = 2 THEN 'Accepted' ELSE 'Unknown' END AS STATUSTEXT
		, ISNULL(TI.TOTALCOUNT,0) AS TOTALTRAYS
		, ISNULL(TI.PENDINGCOUNT,0) AS PENDINGTRAYS
	INTO #SD
	FROM 
		STOCKDISPATCH SD
		LEFT JOIN 
		(
			SELECT SDOUTER.STOCKDISPATCHID, 
				COUNT(*) AS TOTALCOUNT, 
				SUM(CASE WHEN ISACCEPTED = 0 THEN 1 ELSE 0 END) AS PENDINGCOUNT 
			FROM TRAYINFO TIINNER
			INNER JOIN
			(
				SELECT DISTINCT SDINNER.STOCKDISPATCHID, SDD.TRAYINFOID, SDD.TRAYNUMBER
				FROM STOCKDISPATCH SDINNER
					INNER JOIN STOCKDISPATCHDETAIL SDD ON SDINNER.STOCKDISPATCHID = SDD.STOCKDISPATCHID
				WHERE SDINNER.TOBRANCHID = @BranchID 
					AND ISNULL(SDINNER.STATUS, 0) = 1
					AND SDINNER.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
			) SDOUTER ON TIINNER.TRAYINFOID = SDOUTER.TRAYINFOID AND TIINNER.DELETEDDATE IS NULL
			GROUP BY SDOUTER.STOCKDISPATCHID
		) AS TI ON SD.STOCKDISPATCHID = TI.STOCKDISPATCHID
		LEFT JOIN TBLCATEGORY CAT ON SD.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT ON SD.SUBCATEGORYID = SCAT.SUBCATEGORYID
		LEFT JOIN TBLUSER AU ON SD.STATUSAPPROVEDBY = AU.USERID
	WHERE 
		SD.TOBRANCHID = @BranchID
		AND ISNULL(SD.STATUS, 0) = 1
		AND SD.DELETEDBY IS NULL
	ORDER BY SD.CREATEDDATE DESC

	SELECT 1 AS PARENTID

	SELECT 1 AS PARENTID, SD.* FROM #SD SD
		
END
GO
