CREATE PROC [dbo].[POS_USP_R_STOCKDISPATCHDETAIL]  
(  
	@StockDispatchID INT
)  
AS  
BEGIN  

	SELECT   
		0 AS STOCKSUMMARYTRANSITID
		, SDD.STOCKDISPATCHDETAILID  
		, I.ITEMNAME  
		, IC.ITEMCODE  
		, IP.MRP 
		, IP.SALEPRICE
		, GST.GSTCODE  
		, SDD.TRAYNUMBER  
		, SDD.DISPATCHQUANTITY AS DISPATCHQUANTITY
		, SDD.RECEIVEDQUANTITY AS RECEIVEDQUANTITY
		, SDD.WEIGHTINKGS 
		, I.ISOPENITEM
	FROM STOCKDISPATCHDETAIL SDD
		INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATChID = SDD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID  
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID  
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID  
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID  
	WHERE SDD.STOCKDISPATCHID = @StockDispatchID
		AND ISNULL(SD.STATUS, 0) <> 0
		AND SDD.DELETEDDATE IS NULL
	ORDER BY SDD.STOCKDISPATCHDETAILID ASC
END
GO
/****** Object:  StoredProcedure [dbo].[POS_USP_R_STOCKDISPATCHDETAIL_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[POS_USP_R_STOCKDISPATCHDETAIL_v2]  
(  
	@BRANCHID INT  ,
	@TRAYNUMBER INT = 0
)  
AS  
BEGIN  

	IF NOT EXISTS
	(
		SELECT 1 FROM STOCKDISPATCH SD
			INNER JOIN TRAYINFO TI ON SD.STOCKDISPATCHID = TI.STOCKDISPATCHID
		WHERE SD.TOBRANCHID = @BRANCHID 
			AND SD.STATUS = 1
			AND TI.TRAYNUMBER = @TRAYNUMBER 
			AND SD.DELETEDDATE IS NULL 
			AND TI.DELETEDDATE IS NULL
	)
	BEGIN
		SELECT 'Tray does not exists!'
		RETURN
	END

	IF EXISTS
	(
		SELECT 1 FROM STOCKDISPATCH SD
			INNER JOIN TRAYINFO TI ON SD.STOCKDISPATCHID = TI.STOCKDISPATCHID
		WHERE SD.TOBRANCHID = @BRANCHID 
			AND SD.STATUS = 1
			AND TI.TRAYNUMBER = @TRAYNUMBER 
			AND TI.ISACCEPTED = 1
			AND SD.DELETEDDATE IS NULL 
			AND TI.DELETEDDATE IS NULL
	)
	BEGIN
		SELECT 'Selected tray is already verfired'
		RETURN
	END

	SELECT 1 AS PARENTID, SD.STOCKDISPATCHID, SD.DISPATCHNUMBER, TI.TRAYNUMBER
	FROM 
		STOCKDISPATCH SD
		INNER JOIN TRAYINFO TI ON SD.STOCKDISPATCHID = TI.STOCKDISPATCHID
	WHERE 
		SD.TOBRANCHID = @BRANCHID 
		AND SD.STATUS = 1
		AND TI.TRAYNUMBER = @TRAYNUMBER 
		AND SD.DELETEDDATE IS NULL 
		AND TI.DELETEDDATE IS NULL

	SELECT   
		1 AS PARENTID
		, SDD.STOCKDISPATCHID
		, SDD.STOCKDISPATCHDETAILID  
		, I.ITEMNAME  
		, I.SKUCODE
		, IC.ITEMCODE  
		, IP.MRP 
		, IP.SALEPRICE
		, SDD.DISPATCHQUANTITY AS DISPATCHQUANTITY
		, SDD.RECEIVEDQUANTITY AS RECEIVEDQUANTITY
		, SDD.WEIGHTINKGS 
		, I.ISOPENITEM
		, ISNULL(SDD.ISVERIFIED,0) AS ISVERIFIED
	FROM STOCKDISPATCHDETAIL SDD
		INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATChID = SDD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID  
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID  
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID  
	WHERE SD.TOBRANCHID = @BRANCHID
		AND ISNULL(SD.STATUS, 0) = 1
		AND SDD.DELETEDDATE IS NULL
		AND SDD.TRAYNUMBER = @TRAYNUMBER
	ORDER BY SDD.STOCKDISPATCHDETAILID ASC
END
GO
