/****** Object:  StoredProcedure [dbo].[USP_C_BULKPROCESSING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_C_BULKPROCESSING]
(
	@ItemPriceID INT,
	@Quantity INT,
	@UserID INT
)
AS
BEGIN

	DECLARE @ParentItemPriceID INT, @WarehouseID INT = 45, @WeightToDeduct DECIMAL(18, 2), @StockAdjustmentTypeID INT

	SELECT @StockAdjustmentTypeID = STOCKADJUSTMENTTYPEID FROM STOCKADJUSTMENTTYPE WHERE STOCKADJUSTMENTTYPE = 'Processing'

	SELECT
		@ParentItemPriceID = PIP.ITEMPRICEID
		, @WeightToDeduct = UOM.MULTIPLIER * @Quantity
	FROM
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID
		INNER JOIN ITEMCODE PIC ON PIC.ITEMID = PITEM.ITEMID
		INNER JOIN ITEMPRICE PIP ON PIP.ITEMCODEID = PIC.ITEMCODEID
		INNER JOIN UOM UOM ON UOM.UOMID = I.UOMID
	WHERE 
		IP.ITEMPRICEID = @ItemPriceID
		AND PIP.DELETEDDATE IS NULL
		AND PIP.BRANCHID IS NULL
		AND PIC.DELETEDDATE IS NULL

	IF @ParentItemPriceID IS NULL
	BEGIN
		SELECT 'Parent not found, or Parent sale price not found!!'
		RETURN
	END

	INSERT INTO STOCKADJUSTMENT(ITEMPRICEID, BRANCHID, QUANTITY, WEIGHTINKGS, CREATEDBY, CREATEDDATE, PREVQUANTITY, PREVWEIGHTINKGS, STOCKADJUSTMENTTYPEID)
	
	SELECT @ItemPriceID, @WarehouseID, SS.QUANTITY + @Quantity, SS.WEIGHTINKGS, @UserID, GETDATE(), SS.QUANTITY, SS.WEIGHTINKGS, @StockAdjustmentTypeID
	FROM STOCKSUMMARY SS 
	WHERE SS.BRANCHID = @WarehouseID AND SS.ITEMPRICEID = @ItemPriceID

	UNION ALL

	SELECT @ParentItemPriceID, @WarehouseID, SS.QUANTITY, SS.WEIGHTINKGS - @WeightToDeduct, @UserID, GETDATE(), SS.QUANTITY, SS.WEIGHTINKGS, @StockAdjustmentTypeID
	FROM STOCKSUMMARY SS 
	WHERE SS.BRANCHID = @WarehouseID AND SS.ITEMPRICEID = @ParentItemPriceID

	UPDATE SS
	SET SS.QUANTITY = SS.QUANTITY + @Quantity, SS.TTYPE = 'SA', SS.MODIFIEDDATE = GETDATE()
	FROM STOCKSUMMARY SS 
	WHERE SS.BRANCHID = @WarehouseID AND SS.ITEMPRICEID = @ItemPriceID

	UPDATE SS
	SET SS.WEIGHTINKGS = SS.WEIGHTINKGS - @WeightToDeduct, SS.TTYPE = 'SA', SS.MODIFIEDDATE = GETDATE()
	FROM STOCKSUMMARY SS 
	WHERE SS.BRANCHID = @WarehouseID AND SS.ITEMPRICEID = @ParentItemPriceID

	SELECT @@ROWCOUNT

END
GO
/****** Object:  StoredProcedure [dbo].[USP_C_HASACCESS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_C_HASACCESS]
(
	@RoleID INT = NULL
	, @UserID INT = NULL
	, @AddedAccessList VARCHAR(MAX)
	, @RemovedAccessList VARCHAR(MAX)
	, @ApplyToUsers BIT = 0
	, @ChangedByUserID INT
)
AS
BEGIN

	SELECT Item AddedAccessID INTO #AddedAccessList FROM dbo.SplitString(@AddedAccessList,',')
	SELECT Item RemovedAccessID INTO #RemovedAccessList FROM dbo.SplitString(@RemovedAccessList,',')

	DELETE FROM #AddedAccessList WHERE AddedAccessID = 0
	DELETE FROM #RemovedAccessList WHERE RemovedAccessID = 0

	SELECT @UserID USERID INTO #USERS WHERE @UserID IS NOT NULL
	
	IF @RoleID IS NOT NULL
	BEGIN

		INSERT INTO HASACCESS(ROLEID, WORKFLOWACTIONID, CREATEDBY, CREATEDDATE)
		SELECT @RoleID, AddedAccessID, @ChangedByUserID, GETDATE() 
		FROM 
			#AddedAccessList AAL
		WHERE 			
			NOT EXISTS
			(
				SELECT 1 
				FROM HASACCESS HA
				WHERE 
					HA.ROLEID = @RoleID 
					AND HA.WORKFLOWACTIONID = AAL.AddedAccessID
					AND HA.DELETEDDATE IS NULL
			)

		UPDATE HA
		SET 
			HA.DELETEDBY = @ChangedByUserID
			, HA.DELETEDDATE = GETDATE()
		FROM
			HASACCESS HA
			INNER JOIN #RemovedAccessList RAL ON RAL.RemovedAccessID = HA.WORKFLOWACTIONID
		WHERE HA.ROLEID = @RoleID AND HA.DELETEDDATE IS NULL

	END

	IF @ApplyToUsers = 1
	BEGIN
		
		INSERT INTO #USERS
		SELECT USR.USERID
		FROM TBLUSER USR
		WHERE USR.DELETEDDATE IS NULL AND USR.ROLEID = @RoleID

	END

	IF EXISTS ( SELECT 1 FROM #USERS )
	BEGIN

		INSERT INTO HASACCESS(USERID, WORKFLOWACTIONID, CREATEDBY, CREATEDDATE)
		SELECT USR.USERID, AddedAccessID, @ChangedByUserID, GETDATE() 
		FROM 
			#AddedAccessList AAL CROSS APPLY #USERS USR
		WHERE 			
			NOT EXISTS
			(
				SELECT 1 
				FROM HASACCESS HA
				WHERE 
					HA.USERID = USR.USERID 
					AND HA.WORKFLOWACTIONID = AAL.AddedAccessID
					AND HA.DELETEDDATE IS NULL
			)

		UPDATE HA
		SET 
			HA.DELETEDBY = @ChangedByUserID
			, HA.DELETEDDATE = GETDATE()
		FROM
			HASACCESS HA
			INNER JOIN 
				(
					SELECT RALINNER.RemovedAccessID, USR.USERID
					FROM 
						#RemovedAccessList RALINNER 
						CROSS APPLY #USERS USR
				) RAL ON RAL.RemovedAccessID = HA.WORKFLOWACTIONID AND HA.USERID = RAL.USERID 
		WHERE HA.DELETEDDATE IS NULL
		

	END

END
GO
/****** Object:  StoredProcedure [dbo].[USP_C_PICKLISTDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[USP_C_PICKLISTDISPATCH]
(
	@LocationDivisionID INT,
	@BranchID INT
	, @UserID INT
)
AS
BEGIN

	IF EXISTS 
	(
		SELECT 1 
		FROM PICKLISTDISPATCH PLD
		WHERE
			PLD.DELETEDDATE IS NULL
			AND PLD.STOCKDISPATCHID IS NULL
			AND PLD.BRANCHID = @BranchID
			AND PLD.LOCATIONDIVISIONID = @LocationDivisionID
	)
	BEGIN
		SELECT 'Branch dispatch already created for selected branch'
		RETURN
	END

	DECLARE @PickListStartCount INT, @PickListID INT

	SELECT @PickListStartCount = COUNT(1)
	FROM
		PICKLISTBRANCH PLB
		INNER JOIN PICKLIST PB ON PB.PICKLISTID = PLB.PICKLISTID
	WHERE
		PLB.BRANCHID = @BranchID
		AND PB.LOCATIONDIVISIONID = @LocationDivisionID
		AND PB.DELETEDDATE IS NULL
		AND PLB.DELETEDDATE IS NULL
		AND PLB.PICKEDSTATUS = 19 --Seggregated
		

	INSERT INTO PICKLISTDISPATCH(LOCATIONDIVISIONID, BRANCHID, STARTPLCOUNT, CREATEDBY, CREATEDDATE)
	SELECT @LocationDivisionID, @BranchID, ISNULL(@PickListStartCount, 0) , @UserID, GETDATE()

	SET @PickListID = SCOPE_IDENTITY() 

	SELECT @PickListID AS PICKLISTID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CHK_ENTITYLOCK]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[USP_CHK_ENTITYLOCK]
(
	@EntityType VARCHAR(100)
	, @EntityID INT
	, @IsCompleted BIT
)
AS
BEGIN

	IF @IsCompleted = 0
	BEGIN
		
		IF EXISTS ( SELECT 1 FROM ENTITYLOCK WITH(NOLOCK) WHERE ENTITYTYPE = @EntityType AND ENTITYID = @EntityID )
		BEGIN
			THROW 50001, 'The operation is already in progress or completed, please check status or contact administrator.', 1;
			RETURN
		END

		INSERT INTO ENTITYLOCK(ENTITYTYPE, ENTITYID, ISCOMPLETED, STARTTIME)
		SELECT @EntityType, @EntityID, 0, GETDATE()

	END
	ELSE 
	BEGIN
		
		IF NOT EXISTS ( SELECT 1 FROM ENTITYLOCK WITH(NOLOCK) WHERE ENTITYTYPE = @EntityType AND ENTITYID = @EntityID AND ISCOMPLETED = 0 )
		BEGIN
			THROW 50001, 'Invalid lock state, please check status or contact administrator.', 1
			RETURN
		END

		UPDATE ENTITYLOCK 
		SET ISCOMPLETED = 1, ENDTIME = GETDATE() 
		WHERE ENTITYTYPE = @EntityType AND ENTITYID = @EntityID 
	END
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CR_ADDBULKPROCESSING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_CR_ADDBULKPROCESSING]
(
	@UserID INT
	, @CreateBulk BIT
)
AS
BEGIN

	DECLARE @AddBulkProcessingID INT, @WareHouseID INT = 45

	SELECT @AddBulkProcessingID = ADDBULKPROCESSINGID
	FROM ADDBULKPROCESSING
	WHERE CREATEDBY = @UserID AND DELETEDDATE IS NULL AND ISNULL(STATUS, 0) = 0

	IF ISNULL(@AddBulkProcessingID, 0) = 0 AND @CreateBulk = 1
	BEGIN

		INSERT INTO ADDBULKPROCESSING(STATUS, CREATEDDATE, CREATEDBY)
		SELECT 0, GETDATE(), @UserID

		SET @AddBulkProcessingID = SCOPE_IDENTITY()

	END


	SELECT @AddBulkProcessingID

	SELECT I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE
		, CASE WHEN I.ISOPENITEM = 0 THEN ABPD.QUANTITY ELSE ABPD.WEIGHTINKGS END AS QUANTITY
		, (CASE WHEN I.ISOPENITEM = 0 THEN ABPD.QUANTITY ELSE ABPD.WEIGHTINKGS END) * UOM.MULTIPLIER WEIGHTTODEDUCT
		, PITEM.SKUCODE PARENTSKUCODE, PITEM.ITEMNAME PARENTITEMNAME, SSP.PARENTWEIGHINKGS, ABPD.ADDBULKPROCESSINGDETAILID
		, ABPD.ITEMPRICEID, I.ISOPENITEM
	FROM
		ADDBULKPROCESSINGDETAIL ABPD
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ABPD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID
		LEFT JOIN UOM UOM ON UOM.UOMID = I.UOMID
		LEFT JOIN 
			(
				SELECT ICINNER.ITEMID, SUM(SS.WEIGHTINKGS) PARENTWEIGHINKGS
				FROM 
					STOCKSUMMARY SS
					INNER JOIN ITEMPRICE IPINNER ON IPINNER.ITEMPRICEID = SS.ITEMPRICEID
					INNER JOIN ITEMCODE ICINNER ON ICINNER.ITEMCODEID = IPINNER.ITEMCODEID
				WHERE SS.BRANCHID = @WareHouseID		
				GROUP BY ICINNER.ITEMID
			) SSP ON SSP.ITEMID = PITEM.ITEMID
	WHERE ABPD.DELETEDDATE IS NULL AND ABPD.ADDBULKPROCESSINGID = @AddBulkProcessingID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_ADDBULKPROCESSINGDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_CU_ADDBULKPROCESSINGDETAIL]
(
	@ADDBULKPROCESSINGDETAILID INT = 0,
	@ADDBULKPROCESSINGID INT = 0,
	@ItemPriceID INT,
	@Quantity INT,
	@WeightInKGs DECIMAL(7, 2)
)
AS
BEGIN

	IF ISNULL(@ADDBULKPROCESSINGID, 0) <= 0 AND ISNULL(@ADDBULKPROCESSINGDETAILID, 0) > 0
	BEGIN
		SELECT @ADDBULKPROCESSINGID = ADDBULKPROCESSINGID FROM ADDBULKPROCESSINGDETAIL WHERE ADDBULKPROCESSINGDETAILID = @ADDBULKPROCESSINGDETAILID
	END

	IF EXISTS ( SELECT 1 FROM ADDBULKPROCESSING WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID AND STATUS = 1 )
	BEGIN
		SELECT 'Bulk processing is already submitted, Operation has been cancelled!!'
		RETURN
	END

	IF EXISTS ( SELECT 1 FROM ADDBULKPROCESSING WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID AND DELETEDDATE IS NOT NULL )
	BEGIN
		SELECT 'Bulk processing is already deleted, Operation has been cancelled!!'
		RETURN
	END

	IF ISNULL(@ADDBULKPROCESSINGDETAILID, 0) = 0
	BEGIN

		SELECT @ADDBULKPROCESSINGDETAILID = ADDBULKPROCESSINGDETAILID, @Quantity = @Quantity + QUANTITY, @WeightInKGs = @WeightInKGs + WEIGHTINKGS
		FROM ADDBULKPROCESSINGDETAIL 
		WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID AND ITEMPRICEID = @ItemPriceID AND DELETEDDATE IS NULL

	END

	IF ISNULL(@ADDBULKPROCESSINGDETAILID, 0) = 0
	BEGIN

		INSERT INTO ADDBULKPROCESSINGDETAIL(ADDBULKPROCESSINGID, ITEMPRICEID, QUANTITY, WEIGHTINKGS, CREATEDDATE)
		SELECT @ADDBULKPROCESSINGID, @ItemPriceID, @Quantity, @WeightInKGs, GETDATE()

		SET @ADDBULKPROCESSINGDETAILID = SCOPE_IDENTITY()

	END
	ELSE
	BEGIN
		
		UPDATE ADDBULKPROCESSINGDETAIL
		SET QUANTITY = @Quantity, WEIGHTINKGS = @WeightInKGs 
		WHERE ADDBULKPROCESSINGDETAILID = @ADDBULKPROCESSINGDETAILID 

	END

	SELECT @ADDBULKPROCESSINGDETAILID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_BASEOFFER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_BASEOFFER]
@BASEOFFERID INT = 0
,@OFFERCODE VARCHAR(50)
,@OFFERNAME VARCHAR(50)
,@CATEGORYID INT
,@STARTDATE DATE
,@ENDDATE DATE
,@USERID INT
,@dtBranches dtInts READONLY
AS
BEGIN
	BEGIN TRY
		BEGIN TRAN

			IF @BASEOFFERID = 0
			BEGIN
				INSERT INTO BASEOFFER
				(
					OFFERCODE
					,OFFERNAME
					,CATEGORYID
					,STARTDATE
					,ENDDATE
					,CREATEDBY
					,CREATEDDATE
				)
				VALUES
				(
					@OFFERCODE
					,@OFFERNAME
					,@CATEGORYID
					,@STARTDATE
					,@ENDDATE
					,@USERID
					,GETDATE()
				)

				SET @BASEOFFERID = SCOPE_IDENTITY()
			END
			ELSE
			BEGIN
				UPDATE BASEOFFER 
				SET 
					OFFERCODE = @OFFERCODE,
					OFFERNAME = @OFFERNAME,
					CATEGORYID = @CATEGORYID,
					STARTDATE = @STARTDATE,
					ENDDATE = @ENDDATE,
					UPDATEDBY = @USERID,
					UPDATEDDATE = GETDATE()
				WHERE BASEOFFERID = @BASEOFFERID

				UPDATE OFFER 
				SET 
					UPDATEDBY = @USERID,
					UPDATEDDATE = GETDATE()
				WHERE BASEOFFERID = @BASEOFFERID

			END
		COMMIT TRAN                                          
	END TRY                                          
	BEGIN CATCH                                          
		SELECT ERROR_MESSAGE() AS ErrorMessage                                           
		IF(@@TRANCOUNT > 0)                                          
		ROLLBACK TRAN                                          
	END CATCH                             
	SELECT @BASEOFFERID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_BRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_BRANCH]          
@BRANCHID int = 0,          
@BRANCHNAME varchar(100),          
@BRANCHCODE varchar(5),          
@ADDRESS varchar(500),          
@STATEID INT,  
@PHONENO varchar(20),          
@LANDLINE VARCHAR(20),    
@EMAILID varchar(50),          
@SUPERVISORID INT,    
@ISWAREHOUSE BIT,    
@USERID int = 0,
@EnableDraftBills INT,
@BRANCHGRADEID INT,
@BRANCHZONE VARCHAR(50) = NULL
AS          
BEGIN          
          
 IF @BRANCHID > 0           
 BEGIN          
  UPDATE BRANCH           
  SET        
   BRANCHNAME = @BRANCHNAME,    
   BRANCHCODE = @BRANCHCODE,    
   ADDRESS = @ADDRESS,    
   STATEID = @STATEID,  
   PHONENO = @PHONENO,    
   LANDLINE = @LANDLINE,    
   EMAILID = @EMAILID,    
   ISWAREHOUSE = @ISWAREHOUSE,    
   SUPERVISORID = @SUPERVISORID,    
   UPDATEDBY = @USERID,    
   UPDATEDATE = GETDATE(),
   ENABLEDRAFTBILLS = @EnableDraftBills,
   BRANCHGRADEID = @BRANCHGRADEID,
   BRANCHZONE = @BRANCHZONE
  WHERE BRANCHID = @BRANCHID          
 END          
 ELSE          
 BEGIN          
  INSERT INTO BRANCH (BRANCHNAME, BRANCHCODE, ADDRESS, STATEID,  
  PHONENO,LANDLINE, EMAILID, ISWAREHOUSE,SUPERVISORID,     
  CREATEDBY, CREATEDDATE, ENABLESTOCKCOUNTING, ENABLESTOCKDISPATCH, FILTERMRPBYSTOCK, MULTIEDITTHRESHOLD, ENABLEDRAFTBILLS, BRANCHGRADEID
	, BRANCHZONE)          
  VALUES (@BRANCHNAME, @BRANCHCODE, @ADDRESS,@STATEID,  
  @PHONENO,@LANDLINE, @EMAILID,@ISWAREHOUSE,@SUPERVISORID,     
  @USERID, GETDATE(), 0, 1, 1, 10, @EnableDraftBills, @BRANCHGRADEID, @BRANCHZONE)          
          
  SET @BRANCHID = SCOPE_IDENTITY()      
    
  INSERT INTO STOCKSUMMARY(ITEMPRICEID, BRANCHID, QUANTITY, WEIGHTINKGS, TTYPE, MODIFIEDDATE)  
  SELECT ITEMPRICEID, @BRANCHID, 0, 0, 'BC', GETDATE() FROM ITEMPRICE WHERE DELETEDDATE IS NULL  AND BRANCHID IS NULL
 END          
          
 SELECT @BRANCHID          
          
END
GO
