CREATE PROCEDURE [dbo].[USP_R_BRANCHCOUNTERMOP]
    @COUNTERID int = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT M.MOPID, M.MOPNAME, M.ISGATEWAYCONFIGURABLE,
        CONVERT(bit, CASE WHEN CM.BRANCHCOUNTERMOPID IS NULL THEN 0 ELSE 1 END) AS ISAVAILABLE,
        CM.PAYMENTGATEWAYINFOID, CM.PAYMENTGATEWAYADDITIONALCONFIG
    FROM dbo.TBLMOP M
    LEFT JOIN dbo.BRANCHCOUNTERMOP CM ON CM.MOPID = M.MOPID
        AND CM.COUNTERID = @COUNTERID AND CM.DELETEDDATE IS NULL
    WHERE M.DELETEDDATE IS NULL
    ORDER BY M.MOPID;
END
GO
CREATE PROCEDURE [dbo].[USP_CU_BRANCHCOUNTER_MOPCONFIG]
    @COUNTERID int = 0,
    @BRANCHID int,
    @COUNTERNAME nvarchar(50),
    @USERID int,
    @ISMOBILECOUNTER bit = 0,
    @Mappings dbo.BRANCHCOUNTERMOPTYPE READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;

    IF NULLIF(LTRIM(RTRIM(@COUNTERNAME)), N'') IS NULL
        THROW 50100, 'Counter name is required.', 1;
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @Now datetime = GETDATE();
        IF NOT EXISTS (SELECT 1 FROM dbo.BRANCH WITH (UPDLOCK, HOLDLOCK)
                       WHERE BRANCHID = @BRANCHID AND DELETEDDATE IS NULL)
            THROW 50101, 'Select an active branch.', 1;

        IF EXISTS
        (
            SELECT 1 FROM @Mappings S
            LEFT JOIN dbo.TBLMOP M WITH (UPDLOCK, HOLDLOCK) ON M.MOPID = S.MOPID
            WHERE M.MOPID IS NULL OR M.DELETEDDATE IS NOT NULL
               OR (M.ISGATEWAYCONFIGURABLE = 0 AND
                   (S.PAYMENTGATEWAYINFOID IS NOT NULL OR S.PAYMENTGATEWAYADDITIONALCONFIG IS NOT NULL))
               OR (M.ISGATEWAYCONFIGURABLE = 1 AND S.PAYMENTGATEWAYINFOID IS NULL)
        )
            THROW 50102, 'Invalid MOP assignment. Configurable MOPs require a gateway; manual MOPs cannot have gateway settings.', 1;

        IF EXISTS (SELECT 1 FROM @Mappings WHERE PAYMENTGATEWAYADDITIONALCONFIG IS NOT NULL
                   AND ISJSON(PAYMENTGATEWAYADDITIONALCONFIG) <> 1)
            THROW 50103, 'Gateway settings must contain valid JSON.', 1;

        IF EXISTS
        (
            SELECT 1 FROM @Mappings S
            LEFT JOIN dbo.PAYMENTGATEWAYINFO P WITH (UPDLOCK, HOLDLOCK)
                ON P.PAYMENTGATEWAYINFOID = S.PAYMENTGATEWAYINFOID
            WHERE S.PAYMENTGATEWAYINFOID IS NOT NULL AND
                (P.PAYMENTGATEWAYINFOID IS NULL OR P.DELETEDDATE IS NOT NULL)
        )
            THROW 50104, 'Select an active gateway for each configurable MOP.', 1;

        IF EXISTS
        (
            SELECT 1 FROM @Mappings S
            INNER JOIN dbo.PAYMENTGATEWAYINFO P ON P.PAYMENTGATEWAYINFOID = S.PAYMENTGATEWAYINFOID
            WHERE (P.PAYMENTGATEWAYINFOTYPE = 'PineLabs' AND
                  (NULLIF(LTRIM(RTRIM(JSON_VALUE(S.PAYMENTGATEWAYADDITIONALCONFIG, '$.ClientID'))), '') IS NULL
                   OR NULLIF(LTRIM(RTRIM(JSON_VALUE(S.PAYMENTGATEWAYADDITIONALCONFIG, '$.StoreID'))), '') IS NULL))
               OR (P.PAYMENTGATEWAYINFOTYPE = 'BharathPe' AND
                  (NULLIF(LTRIM(RTRIM(JSON_VALUE(S.PAYMENTGATEWAYADDITIONALCONFIG, '$.UserName'))), '') IS NULL
                   OR NULLIF(LTRIM(RTRIM(JSON_VALUE(S.PAYMENTGATEWAYADDITIONALCONFIG, '$.Password'))), '') IS NULL))
        )
            THROW 50105, 'Complete the required gateway settings.', 1;

        IF EXISTS (SELECT 1 FROM dbo.BRANCHCOUNTER WITH (UPDLOCK, HOLDLOCK)
                   WHERE COUNTERNAME = @COUNTERNAME AND DELETEDDATE IS NULL AND COUNTERID <> @COUNTERID)
            THROW 50106, 'Counter Already Exists!!', 1;

        IF @COUNTERID > 0
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM dbo.BRANCHCOUNTER WITH (UPDLOCK, HOLDLOCK)
                           WHERE COUNTERID = @COUNTERID AND DELETEDDATE IS NULL)
                THROW 50107, 'Active counter not found.', 1;
            UPDATE dbo.BRANCHCOUNTER
            SET BRANCHID = @BRANCHID, COUNTERNAME = @COUNTERNAME,
                ISMOBILECOUNTER = @ISMOBILECOUNTER, UPDATEDBY = @USERID, UPDATEDDATE = @Now
            WHERE COUNTERID = @COUNTERID;
        END
        ELSE
        BEGIN
            INSERT dbo.BRANCHCOUNTER (BRANCHID, COUNTERNAME, ISMOBILECOUNTER, CREATEDBY, CREATEDDATE)
            VALUES (@BRANCHID, @COUNTERNAME, @ISMOBILECOUNTER, @USERID, @Now);
            SET @COUNTERID = CONVERT(int, SCOPE_IDENTITY());
        END;

        -- The same terminal can serve multiple MOPs at one counter, but not another counter.
        IF EXISTS
        (
            SELECT 1 FROM @Mappings S
            INNER JOIN dbo.PAYMENTGATEWAYINFO P ON P.PAYMENTGATEWAYINFOID = S.PAYMENTGATEWAYINFOID
            INNER JOIN dbo.BRANCHCOUNTERMOP CM WITH (UPDLOCK, HOLDLOCK)
                ON CM.COUNTERID <> @COUNTERID AND CM.DELETEDDATE IS NULL
            INNER JOIN dbo.BRANCHCOUNTER C ON C.COUNTERID = CM.COUNTERID AND C.DELETEDDATE IS NULL
            INNER JOIN dbo.PAYMENTGATEWAYINFO CP ON CP.PAYMENTGATEWAYINFOID = CM.PAYMENTGATEWAYINFOID
            WHERE P.PAYMENTGATEWAYINFOTYPE = 'BharathPe' AND CP.PAYMENTGATEWAYINFOTYPE = 'BharathPe'
              AND JSON_VALUE(S.PAYMENTGATEWAYADDITIONALCONFIG, '$.UserName') =
                  JSON_VALUE(CM.PAYMENTGATEWAYADDITIONALCONFIG, '$.UserName')
        )
            THROW 50108, 'Payment gateway username already exists for another counter.', 1;

        UPDATE CM SET DELETEDBY = @USERID, DELETEDDATE = @Now,
            UPDATEDBY = @USERID, UPDATEDDATE = @Now
        FROM dbo.BRANCHCOUNTERMOP CM
        WHERE CM.COUNTERID = @COUNTERID AND CM.DELETEDDATE IS NULL
          AND NOT EXISTS (SELECT 1 FROM @Mappings S WHERE S.MOPID = CM.MOPID);

        UPDATE CM SET PAYMENTGATEWAYINFOID = S.PAYMENTGATEWAYINFOID,
            PAYMENTGATEWAYADDITIONALCONFIG = S.PAYMENTGATEWAYADDITIONALCONFIG,
            UPDATEDBY = @USERID, UPDATEDDATE = @Now
        FROM dbo.BRANCHCOUNTERMOP CM
        INNER JOIN @Mappings S ON S.MOPID = CM.MOPID
        WHERE CM.COUNTERID = @COUNTERID AND CM.DELETEDDATE IS NULL;

        INSERT dbo.BRANCHCOUNTERMOP
            (COUNTERID, MOPID, PAYMENTGATEWAYINFOID, PAYMENTGATEWAYADDITIONALCONFIG, CREATEDBY, CREATEDDATE)
        SELECT @COUNTERID, S.MOPID, S.PAYMENTGATEWAYINFOID, S.PAYMENTGATEWAYADDITIONALCONFIG, @USERID, @Now
        FROM @Mappings S
        WHERE NOT EXISTS (SELECT 1 FROM dbo.BRANCHCOUNTERMOP CM
                          WHERE CM.COUNTERID = @COUNTERID AND CM.MOPID = S.MOPID AND CM.DELETEDDATE IS NULL);

        COMMIT TRANSACTION;
        SELECT @COUNTERID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_BRANCHCOUNTER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_BRANCHCOUNTER]  
    @COUNTERID INT = 0,  
    @BRANCHID INT,  
    @COUNTERNAME VARCHAR(100),  
    @USERID INT = 0,
    @ISMOBILECOUNTER BIT = 0,
    @PaymentGatewayID INT = NULL,
    @PaymentGatewayAdditionalConfig VARCHAR(MAX) = NULL
AS  
BEGIN  
    SET NOCOUNT ON;



    DECLARE @GatewayUserName VARCHAR(200);

    -- Extract username from JSON
    SET @GatewayUserName = JSON_VALUE(@PaymentGatewayAdditionalConfig, '$.UserName');

    -- Validation
    IF EXISTS
    (
        SELECT 1
        FROM BRANCHCOUNTER
        WHERE 
            COUNTERID <> @COUNTERID
            AND JSON_VALUE(PAYMENTGATEWAYADDITIONALCONFIG, '$.UserName') = @GatewayUserName
            AND @GatewayUserName IS NOT NULL
    )
    BEGIN
        RAISERROR ('Payment gateway username already exists for another counter.', 16, 1);
        RETURN;
    END

    IF @COUNTERID > 0       
    BEGIN      
        UPDATE BRANCHCOUNTER  
        SET    
            BRANCHID = @BRANCHID,      
            COUNTERNAME = @COUNTERNAME,
            PAYMENTGATEWAYADDITIONALCONFIG = @PaymentGatewayAdditionalConfig,
            PAYMENTGATEWAYID = @PaymentGatewayID,
            UPDATEDBY = @USERID,      
            UPDATEDDATE = GETDATE()
        WHERE COUNTERID = @COUNTERID;
    END      
    ELSE      
    BEGIN     
	
		IF EXISTS
		(
			SELECT 1 FROM BRANCHCOUNTER 
			WHERE COUNTERNAME = @COUNTERNAME 
				AND DELETEDDATE IS NULL
		)
		BEGIN
			RAISERROR ('Counter Already Exists!!', 16, 1);
			RETURN;
		END

        INSERT INTO BRANCHCOUNTER
        (
            BRANCHID,
            COUNTERNAME,
            CREATEDBY,
            CREATEDDATE,
            ISMOBILECOUNTER,
            PAYMENTGATEWAYADDITIONALCONFIG,
            PAYMENTGATEWAYID
        )      
        VALUES
        (
            @BRANCHID,
            @COUNTERNAME,
            @USERID,
            GETDATE(),
            @ISMOBILECOUNTER,
            @PaymentGatewayAdditionalConfig,
            @PaymentGatewayID
        );

        SET @COUNTERID = SCOPE_IDENTITY();
    END      

    SELECT @COUNTERID;
END
GO
