CREATE PROC [dbo].[USP_CU_BRANCHEXPENSE]
(
	@BranchExpenseID INT = 0
	, @BranchID INT
	, @BranchExpenseTypeID INT
	, @Description VARCHAR(MAX) = ''
	, @Amount DECIMAL(18, 2)
	, @BillImage IMAGE = NULL
	, @UserID INT
	, @CreatedDate DATETIME = NULL
)
AS
BEGIN

	--;THROW 50001, 'Branch expense is temporarily stopped', 1;

	IF @CreatedDate IS NULL
	BEGIN
		SELECT @CreatedDate = GETDATE()
	END

	IF @BranchExpenseID > 0
	BEGIN
		
		UPDATE BRANCHEXPENSE
		SET
			BRANCHEXPENSETYPEID = @BranchExpenseTypeID
			, EXPENSEDESC = @Description
			, AMOUNT = @Amount
			, UPDATEDBY = @UserID
			, UPDATEDDATE = GETDATE()
			, CREATEDDATE = @CreatedDate
		WHERE BRANCHEXPENSEID = @BranchExpenseID

		UPDATE BRANCHEXPENSEATTACHMENTS SET BRANCHEXPENSEATTACHMENT = @BillImage WHERE BRANCHEXPENSEID = @BranchExpenseID

	END
	ELSE
	BEGIN

		INSERT INTO BRANCHEXPENSE(BRANCHID, BRANCHEXPENSETYPEID, EXPENSEDESC, AMOUNT, CREATEDBY, CREATEDDATE)
		SELECT @BranchID, @BranchExpenseTypeID, @Description, @Amount, @UserID, @CreatedDate

		SET @BranchExpenseID = SCOPE_IDENTITY()

		INSERT INTO BRANCHEXPENSEATTACHMENTS(BRANCHEXPENSEID, BRANCHEXPENSEATTACHMENT)
		VALUES(@BranchExpenseID, @BillImage)

	END

	SELECT @BranchExpenseID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_BRANCHINDENT_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
