CREATE PROCEDURE [dbo].[USP_CU_BRANCHINDENT_v2]
@BRANCHINDENTID INT = 0,
@FROMBRANCHID INT,
@TOBRANCHID INT,
@CATEGORYID INT,
@NOOFDAYS INT,
@USERID INT,
@IndentMethod VARCHAR(100) = '6M sale days AVG',
@dtDetail BRANCHINDENTDETAILTYPE READONLY
AS
BEGIN

	IF NOT EXISTS(SELECT 1 FROM @dtDetail)
	BEGIN
		SELECT 'Indent cannot be created with zero items'
		RETURN;
	END
	
	DECLARE @CREATEDDATE DATETIME = GETDATE()

	SELECT @FROMBRANCHID = BRANCHID FROM TBLUSER WHERE USERID = @USERID

		IF EXISTS(
					SELECT 1 FROM BRANCHINDENT BI
						INNER JOIN SUBCATEGORY SCAT ON BI.SUBCATEGORYID = SCAT.SUBCATEGORYID
					WHERE BI.FROMBRANCHID = @FROMBRANCHID 
						AND BI.TOBRANCHID = @TOBRANCHID 
						AND SCAT.CATEGORYID = @CATEGORYID
						AND ISNULL(BI.ISCOMPLETED,0) = 0 
						AND BI.DELETEDDATE IS NULL
				)
			BEGIN
				SELECT 'Few indents/dispatches for same branch and category are not yet closed'
				RETURN;
			END


		INSERT INTO BRANCHINDENT
		(
			FROMBRANCHID,TOBRANCHID,
			SUBCATEGORYID,NOOFDAYS,CREATEDBY,CREATEDDATE,ISCOMPLETED, INDENTMETHOD
		)
		SELECT DISTINCT @FROMBRANCHID, @TOBRANCHID,
			SUBCATEGORYID, @NOOFDAYS, @USERID, @CREATEDDATE, 0, @IndentMethod
		FROM @dtDetail

		SET @BRANCHINDENTID = SCOPE_IDENTITY()

		INSERT INTO BRANCHINDENTDETAIL
		(
			BRANCHINDENTID,ITEMID,BRANCHSTOCK,AVGSALES,NOOFDAYSSALES,
			INDENTQUANTITY,LASTDISPATCHEDDATE,CREATEDBY,CREATEDDATE, WHSTOCK
		)
		SELECT 
			BI.BRANCHINDENTID, BID.ITEMID, BID.BRANCHSTOCK, BID.AVGSALES, BID.NOOFDAYSSALES,
			BID.INDENTQUANTITY, BID.LASTDISPATCHDATE, @USERID, @CREATEDDATE, BID.WHSTOCK
		FROM @dtDetail BID
			INNER JOIN BRANCHINDENT BI ON BID.SUBCATEGORYID = BI.SUBCATEGORYID
		WHERE BI.CREATEDDATE = @CREATEDDATE 
			AND BI.TOBRANCHID = @TOBRANCHID 
			AND BI.ISCOMPLETED = 0

		SELECT @BRANCHINDENTID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_BRANCHITEMPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
