CREATE PROCEDURE [dbo].[USP_CU_BRANCHITEMPRICE]
@ITEMPRICEID INT = 0,
@PARENTITEMPRICEID INT,
@SALEPRICE DECIMAL(18,2),
@BRANCHID INT,
@USERID INT
AS
BEGIN
	
	IF EXISTS(SELECT 1 FROM ITEMPRICE WHERE ITEMPRICEID = @PARENTITEMPRICEID AND SALEPRICE = @SALEPRICE  AND DELETEDDATE IS NULL)
	BEGIN
		RAISERROR('Saleprice already exists! Enter different value to create new one.',16,1)
		RETURN;
	END

	IF ISNULL(@SALEPRICE, 0) <= 0
	BEGIN
		RAISERROR('Sale price must be greater than 0', 16, 1)
		RETURN;
	END

	DECLARE @SourceProcedure NVARCHAR(517) =
        QUOTENAME(OBJECT_SCHEMA_NAME(@@PROCID))
        + N'.'
        + QUOTENAME(OBJECT_NAME(@@PROCID));

    EXEC sys.sp_set_session_context
        @key = N'ITEMPRICE_SOURCE_PROC',
        @value = @SourceProcedure;

	IF EXISTS(SELECT 1 FROM ITEMPRICE WHERE ITEMPRICEID = @ITEMPRICEID AND SALEPRICE <> @SALEPRICE AND DELETEDDATE IS NULL)
	BEGIN
		UPDATE ITEMPRICE SET DELETEDBY = @USERID, DELETEDDATE = GETDATE()
		WHERE ITEMPRICEID = @ITEMPRICEID
		
		SET @ITEMPRICEID = 0
	END

	IF(@ITEMPRICEID = 0)
	BEGIN
		INSERT INTO ITEMPRICE
		(
			ITEMCODEID
			,SALEPRICE
			,MRP
			,GSTID
			,CREATEDBY
			,CREATEDDATE
			,BRANCHID
			,PARENTITEMPRICEID
		)
		SELECT 
			ITEMCODEID
			,@SALEPRICE
			,MRP
			,GSTID
			,@USERID
			,GETDATE()
			,@BRANCHID
			,@PARENTITEMPRICEID
		FROM ITEMPRICE 
		WHERE ITEMPRICEID = @PARENTITEMPRICEID

		SET @ITEMPRICEID = SCOPE_IDENTITY()
	END

	SELECT @ITEMPRICEID

END
GO
