CREATE PROCEDURE [dbo].[USP_CU_BRAND]
@BRANDID INT = 0,
@BRANDNAME NVARCHAR(100),
@USERID INT
AS
BEGIN

	IF(@BRANDID > 0)
	BEGIN
		UPDATE TBLBRAND 
		SET 
			BRANDNAME = @BRANDNAME, 
			UPDATEDBY = @USERID, 
			UPDATEDDATE = GETDATE()
		WHERE BRANDID = @BRANDID
	END
	ELSE
	BEGIN
		INSERT INTO TBLBRAND(BRANDNAME, CREATEDBY, CREATEDDATE)
		VALUES(@BRANDNAME, @USERID, GETDATE())
		SET @BRANDID = SCOPE_IDENTITY()
	END

	SELECT @BRANDID
END
