/****** Object:  StoredProcedure [dbo].[USP_CU_CLONESTOCKDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_CLONESTOCKDISPATCH]
@STOCKDISPATCHID INT,
@USERID INT
AS                        
BEGIN                        

	IF NOT EXISTS
	(
		SELECT 1 
		FROM STOCKDISPATCH SD
		WHERE SD.STOCKDISPATCHID = @STOCKDISPATCHID 
			AND SD.Reverted_Date IS NOT NULL
	)
	BEGIN
		RAISERROR ('Only reverted dispatch can be cloned', 16, 1)
		RETURN
	END

	SELECT @USERID = CREATEDBY FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	IF EXISTS (SELECT 1 FROM STOCKDISPATCH WHERE CREATEDBY = @USERID AND ISNULL(STATUS,0) = 0 AND DELETEDDATE IS NULL)
	BEGIN
		SELECT 'There is already a dispatch in draft state, please close to continue with cloning!'
		Return;
	END

	DECLARE @NEWSTOCKDISPATCHID INT = 0
	
	INSERT INTO STOCKDISPATCH(FROMBRANCHID,TOBRANCHID,STATUS,CREATEDBY,CREATEDDATE,CATEGORYID)
	SELECT FROMBRANCHID,TOBRANCHID,0,CREATEDBY,CREATEDDATE,CATEGORYID
	FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	SET @NEWSTOCKDISPATCHID = SCOPE_IDENTITY()

	INSERT INTO STOCKDISPATCHDETAIL(STOCKDISPATCHID,ITEMPRICEID,TRAYNUMBER,DISPATCHQUANTITY,RECEIVEDQUANTITY,WEIGHTINKGS,CREATEDDATE)
	SELECT @NEWSTOCKDISPATCHID,ITEMPRICEID,TRAYNUMBER,DISPATCHQUANTITY,RECEIVEDQUANTITY,WEIGHTINKGS,CREATEDDATE
	FROM STOCKDISPATCHDETAIL 
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID AND DELETEDDATE = Reverted_Date
   
   SELECT @NEWSTOCKDISPATCHID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_CLONESTOCKENTRY]    Script Date: 17-10-2026 13:04:47 ******/
