CREATE PROCEDURE [dbo].[USP_CU_CLONESTOCKENTRY]
@STOCKENTRYID INT,
@USERID INT
AS                        
BEGIN                        

	DECLARE @NEWSTOCKENTRYID INT = 0
	INSERT INTO STOCKENTRY
	(
		STOCKENTRYNUMBER,DESCRIPTION,SUPPLIERID,SUPPLIERINVOICENO,
		CATEGORYID,STATUS,INVOICEDATE,CREATEDBY,CREATEDDATE,TCS,
		DISCOUNT,EXPENSES,TRANSPORT,IsBranchInvoice,
		SOURCEBRANCHID,SUPPLIERINDENTID,MobileSubmissionDate,
		PriceEntryMethod,InvoiceType,LorryFrightMode,PackingCharges,Notes, RECEIVINGBRANCHID
	)
	
	SELECT 
		STOCKENTRYNUMBER,DESCRIPTION,SUPPLIERID,SUPPLIERINVOICENO,
		CATEGORYID,0,INVOICEDATE,CREATEDBY,CREATEDDATE,TCS,
		DISCOUNT,EXPENSES,TRANSPORT,IsBranchInvoice,
		SOURCEBRANCHID,SUPPLIERINDENTID,MobileSubmissionDate,
		PriceEntryMethod,InvoiceType,LorryFrightMode,PackingCharges,Notes, RECEIVINGBRANCHID
	FROM STOCKENTRY WHERE STOCKENTRYID = @STOCKENTRYID

	SET @NEWSTOCKENTRYID = SCOPE_IDENTITY()

	INSERT INTO STOCKENTRYDETAIL
	(
		STOCKENTRYID,QUANTITY,WEIGHTINKGS,CREATEDBY,CREATEDDATE,
		DISCOUNTFLAT,DISCOUNTPERCENTAGE,SCHEMEPERCENTAGE,SCHEMEFLAT,
		TOTALPRICEWT,TOTALPRICEWOT,APPLIEDDISCOUNT,APPLIEDSCHEME,APPLIEDDGST,FINALPRICE,
		ITEMCOSTPRICEID,CGST,SGST,IGST,CESS,CPWITHTAX,CPWITHOUTTAX,GSTID,
		INVOICECPWITHTAX,INVOICECPWITHOUTTAX,MRP,SALEPRICE,ITEMCODEID,FINALPRICEWOTAX,ISFREEITEM
	)
	SELECT 
		@NEWSTOCKENTRYID,QUANTITY,WEIGHTINKGS,CREATEDBY,CREATEDDATE,
		DISCOUNTFLAT,DISCOUNTPERCENTAGE,SCHEMEPERCENTAGE,SCHEMEFLAT,
		TOTALPRICEWT,TOTALPRICEWOT,APPLIEDDISCOUNT,APPLIEDSCHEME,APPLIEDDGST,FINALPRICE,
		ITEMCOSTPRICEID,CGST,SGST,IGST,CESS,CPWITHTAX,CPWITHOUTTAX,GSTID,
		INVOICECPWITHTAX,INVOICECPWITHOUTTAX,MRP,SALEPRICE,ITEMCODEID,FINALPRICEWOTAX,ISFREEITEM
	FROM STOCKENTRYDETAIL 
	WHERE STOCKENTRYID = @STOCKENTRYID AND DELETEDDATE = Reverted_Date
   
   SELECT @NEWSTOCKENTRYID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_COUNTER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
