CREATE PROCEDURE [dbo].[usp_cu_CreditNote]
(
    @CreditNoteId               INT = 0,
    @CNNumber                   VARCHAR(50),
    @Description                VARCHAR(255) = null,
    @SupplierId                 INT,
    @CreditValue                DECIMAL(18,2),
    @CreditNoteAdjustmentTypeId INT,
    @StockEntryId               INT = NULL,
    @UserId                     INT
)
AS
BEGIN
    SET NOCOUNT ON;

    IF @CreditNoteId = 0
    BEGIN
        INSERT INTO CreditNote
        (
            CNNumber,
            Description,
            SupplierId,
            CreditValue,
            CreditNoteAdjustmentTypeId,
            StockEntryId,
            CreatedBy,
            CreatedDate
        )
        VALUES
        (
            @CNNumber,
            @Description,
            @SupplierId,
            @CreditValue,
            @CreditNoteAdjustmentTypeId,
            @StockEntryId,
            @UserId,
            GETDATE()
        );

        SELECT SCOPE_IDENTITY() AS CreditNoteId;
    END
    ELSE
    BEGIN
        UPDATE CreditNote
        SET
            CNNumber = @CNNumber,
            Description = @Description,
            SupplierId = @SupplierId,
            CreditValue = @CreditValue,
            CreditNoteAdjustmentTypeId = @CreditNoteAdjustmentTypeId,
            StockEntryId = @StockEntryId,
            UpdatedBy = @UserId,
            UpdatedDate = GETDATE()
        WHERE CreditNoteId = @CreditNoteId
          AND DeletedDate IS NULL;

        SELECT @CreditNoteId AS CreditNoteId;
    END
END;
GO
