/****** Object:  StoredProcedure [dbo].[USP_CU_DISPATCHDC]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_DISPATCHDC]                
@DISPATCHDCID INT = 0,                
@CATEGORYID INT = 0,                
@BRANCHID INT,                
@USERID INT,
@LocationName VARCHAR(50) = NULL
AS                
BEGIN                
            
	IF NOT EXISTS
	(
		SELECT 1 
		FROM 
			STOCKDISPATCH SD                 
			INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = SD.CATEGORYID
		WHERE 
			NOT EXISTS 
				(    
					SELECT 1 FROM DISPATCHDCMAPPING DDM                 
					WHERE SD.STOCKDISPATCHID = DDM.STOCKDISPATCHID    
				)     
			AND SD.TOBRANCHID = @BRANCHID 
			AND (SD.CATEGORYID = @CATEGORYID OR @CATEGORYID = 0 OR @CATEGORYID = 13)
			AND STATUS <>  0 
			AND SD.CREATEDDATE > CONVERT(DATE, GETDATE())
			AND (@LocationName IS NULL OR CAT.LOCATIONNAME = @LocationName)
	)
		RETURN;            
          
	DECLARE @FROMBRANCHID INT,  @BranchCode varchar(20), @SNO INT
	SELECT TOP(1) @FROMBRANCHID = BRANCHID FROM BRANCH WHERE ISWAREHOUSE = 1
	
	SELECT @BRANCHCODE = BRANCHCODE FROM BRANCH WHERE BRANCHID = @BRANCHID
	SELECT @SNO = ISNULL(MAX(SNO),0) + 1 FROM DISPATCHDC
          
	INSERT INTO DISPATCHDC(FROMBRANCHID,BRANCHID,CATEGORYID,CREATEDBY,CREATEDDATE,DISPATCHDCNUMBER,SNO)          
	SELECT @FROMBRANCHID,@BRANCHID,@CATEGORYID,@USERID,GETDATE(), 'DC' + @BRANCHCODE + 
			REPLACE(CONVERT(VARCHAR(10), GETDATE(),111),'/','') + RIGHT('0000000'+CAST(@SNO AS VARCHAR(8)),10),@SNO
      
	SET @DISPATCHDCID = SCOPE_IDENTITY()          
                
	INSERT INTO DISPATCHDCMAPPING(STOCKDISPATCHID,DISPATCHDCID)                
	SELECT SD.STOCKDISPATCHID, @DISPATCHDCID       
	FROM 
		STOCKDISPATCH SD                 
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = SD.CATEGORYID
	WHERE SD.STATUS <> 0       
		AND NOT EXISTS 
			(
				SELECT 1 
				FROM DISPATCHDCMAPPING DDM
				WHERE 
					SD.STOCKDISPATCHID = DDM.STOCKDISPATCHID)      
		AND SD.TOBRANCHID = @BRANCHID AND (SD.CATEGORYID = @CATEGORYID OR @CATEGORYID = 0 OR @CATEGORYID = 13) AND SD.CREATEDDATE > CONVERT(DATE, GETDATE())  
		AND (@LocationName IS NULL OR CAT.LOCATIONNAME = @LocationName)

	EXEC USP_R_STOCKDISPATCHDC @DISPATCHDCID              
                
END
GO
