/****** Object:  StoredProcedure [dbo].[USP_CU_INDENTLIMIT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_CU_INDENTLIMIT]
(
	@IndentLimits INDENTLIMITTYPE READONLY,
	@UserID INT
)
AS
BEGIN

	UPDATE IL
	SET 
		IL.THRESHOLD = ILU.THRESHOLD
		, IL.DESIREDQUANTITY = ILU.DESIREDQUANTITY
		, IL.UPDATEDBY = @UserID, IL.UPDATEDDATE = GETDATE()
	FROM
		INDENTLIMIT IL
		INNER JOIN @IndentLimits ILU ON ILU.INDENTLIMITID = IL.INDENTLIMITID
	WHERE
		IL.THRESHOLD <> ILU.THRESHOLD OR IL.DESIREDQUANTITY <> ILU.DESIREDQUANTITY

	INSERT INTO INDENTLIMIT(ITEMID, BRANCHID, THRESHOLD, DESIREDQUANTITY, CREATEDBY, CREATEDDATE)
	SELECT ILU.ITEMID, ILU.BRANCHID, ILU.THRESHOLD, ILU.DESIREDQUANTITY, @UserID, GETDATE()
	FROM @IndentLimits ILU
	WHERE NOT EXISTS (SELECT 1 FROM INDENTLIMIT IL WHERE IL.INDENTLIMITID = ISNULL(ILU.INDENTLIMITID, 0))
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_ITEMCLASSIFICATION]    Script Date: 17-10-2026 13:04:47 ******/
