CREATE   PROC [dbo].[USP_CU_ITEMCLASSIFICATION]
(
	@ItemClassificationID INT = 0
	, @ClassificationName VARCHAR(100)
	, @CategoryID INT
	, @UserID INT
)
AS
BEGIN

	IF EXISTS(SELECT 1 FROM ITEMCLASSIFICATION WHERE CLASSIFICATIONNAME = @ClassificationName AND CATEGORYID = @CategoryID AND CLASSIFICATIONID <> @ItemClassificationID)
	BEGIN
		SELECT 'Classification name already exists. Operation has been cancelled!!'
		RETURN
	END

	IF @ItemClassificationID = 0
	BEGIN
		
		INSERT INTO ITEMCLASSIFICATION(CATEGORYID, CLASSIFICATIONNAME, CREATEDBY, CREATEDDATE)
		SELECT @CategoryID, @ClassificationName, @UserID, GETDATE()

		SET @ItemClassificationID = SCOPE_IDENTITY()
	END
	ELSE
	BEGIN

		UPDATE ICLS
		SET
			CATEGORYID = @CategoryID
			, CLASSIFICATIONNAME = @ClassificationName
			, UPDATEDBY = @UserID
			, UPDATEDDATE = GETDATE()
		FROM ITEMCLASSIFICATION ICLS
		WHERE ICLS.CLASSIFICATIONID = @ItemClassificationID

	END

	SELECT @ItemClassificationID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_ITEMCODE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_CU_ITEMCODE]    
@ItemCodeID INT = 0    
, @ItemID INT = 0    
, @ItemName VARCHAR(100)    
, @ItemCode VARCHAR(20)    
, @Description VARCHAR(500) = NULL    
, @CategoryID INT    
, @SubCategoryID INT  = NULL  
, @HSNCode VARCHAR(10) = NULL    
, @IsEAN BIT    
, @SKUCode VARCHAR(10)     
, @CostPriceWT DECIMAL(11, 4)    
, @CostPriceWOT DECIMAL(11, 4)    
, @SalePrice DECIMAL(10, 2)    
, @MRP DECIMAL(10, 2)    
, @GSTID INT    
, @UserID INT    
, @IsOpenItem BIT = 0    
, @ParentItemID INT = NULL    
, @UOMID INT = NULL    
, @FreeItemCodeID INT = NULL   
, @ClassificationID INT = NULL
, @SubClassificationID INT = NULL
, @BrandID INT = NULL
, @ManufacturerID INT = NULL
, @UQCID INT = NULL
, @VendorSKUCode VARCHAR(20) = NULL
, @SeasonalityIDs VARCHAR(500) = NULL
, @RefundPathID INT = NULL
, @IsDSD BIT = null
AS    
BEGIN    
    
	--Pre-write validations    
	IF EXISTS (SELECT 1 FROM ITEM I WHERE I.SKUCODE = @SKUCode AND I.DELETEDDATE IS NULL AND I.ITEMID != @ItemID)    
	BEGIN    
		RAISERROR('Item SKU code already exists',16,1)
		RETURN;
	END    
    
	IF EXISTS (SELECT 1 FROM ITEMCODE IC WHERE IC.ITEMCODE = @ItemCode AND IC.DELETEDDATE IS NULL AND IC.ITEMCODEID != @ItemCodeID)    
	BEGIN    
		RAISERROR('Item code already exists',16,1)
		RETURN;
	END    
    
	IF  ISNULL(@ItemID, 0) <= 0    
		AND NOT EXISTS (SELECT 1 FROM ITEM I WHERE I.SKUCODE = @SKUCode AND I.DELETEDDATE IS NULL) 
		AND NOT EXISTS (SELECT 1 FROM TBLUSER WHERE USERID = @UserID AND ROLEID IN (1, 2))
	BEGIN    
		RAISERROR('Permission denied to create item SKU', 16,1)
		RETURN    
	END    

    IF ISNULL(@MRP, 0) <= 0 OR ISNULL(@SalePrice, 0) <= 0
    BEGIN
        RAISERROR('MRP and Sale Price must be greater than 0', 16, 1)
        RETURN;
    END


	-- End Validations    
    
	-- pre clean variable not to violate FK relations    
    
	IF @ParentItemID <= 0    
	BEGIN    
		SET @ParentItemID = NULL    
	END    
     
	IF @UOMID <= 0    
	BEGIN    
		SET @UOMID = NULL    
	END    
     
	IF @FreeItemCodeID <= 0    
	BEGIN    
		SET @FreeItemCodeID = NULL    
	END    
    
	-- end pre clean    
    
	IF @ItemID > 0    
	BEGIN    
		UPDATE ITEM    
		SET    
			SKUCODE = @SKUCode    
			, ITEMNAME = @ItemName    
			, DESCRIPTION = @Description    
			, CATEGORYID = @CategoryID    
			, UPDATEDBY = @UserID    
			, UPDATEDATE = GETDATE()    
			, ISOPENITEM = @IsOpenItem    
			, PARENTITEMID = @ParentItemID    
			, SUBCATEGORYID = @SubCategoryID    
			, UOMID = @UOMID    
			, ClassificationID = @ClassificationID
			, SUBCLASSIFICATIONID = @SubClassificationID
			, BRANDID = @BrandID
			, MANUFACTURERID = @ManufacturerID
			, UQCID = @UQCID
			, HSNCODE = @HSNCode
			, GSTID = @GSTID
			, VENDORSKUCODE = @VendorSKUCode
			, SEASONALITYIDS = @SeasonalityIDs
			, REFUNDPATHID = @RefundPathID
		WHERE ITEMID = @ItemID    
	END    
	ELSE    
	BEGIN    
		INSERT INTO ITEM(SKUCODE, ITEMNAME, DESCRIPTION, CATEGORYID, CREATEDBY, CREATEDDATE, ISOPENITEM, SUBCATEGORYID, PARENTITEMID
			, UOMID, ClassificationID, SUBCLASSIFICATIONID, BRANDID, MANUFACTURERID, UQCID, GSTID, VENDORSKUCODE)    
		SELECT @SKUCode, @ItemName, @Description, @CategoryID, @UserID, GETDATE(), @IsOpenItem, @SubCategoryID, @ParentItemID, @UOMID
			, @ClassificationID, @SubClassificationID, @BrandID, @ManufacturerID, @UQCID, @GSTID, @VendorSKUCode
    
		SET @ItemID = SCOPE_IDENTITY()    
    
	END    
    
	-- Store Item Code    
	IF @ItemCodeID > 0    
	BEGIN    
		UPDATE ITEMCODE    
		SET    
			ITEMCODE = @ItemCode   
			, ITEMID = @ItemID
			, ISEAN = @IsEAN    
			, HSNCODE = @HSNCode    
			, UPDATEDBY = @UserID    
			, UPDATEDATE = GETDATE()    
			, FREEITEMCODEID = @FreeItemCodeID    
		WHERE ITEMCODEID = @ItemCodeID    
	END    
	ELSE    
	BEGIN    
		INSERT INTO ITEMCODE(ITEMCODE, ITEMID, HSNCODE, ISEAN,   
		CREATEDBY, CREATEDDATE, FREEITEMCODEID)    
		SELECT @ItemCode, @ItemID, @HSNCode, @IsEAN,   
		@UserID, GETDATE(), @FreeItemCodeID    
    
		SET @ItemCodeID = SCOPE_IDENTITY()    

	END    

	--Propogate HSN to all other itemcodes under that ItemID

	UPDATE ITEMCODE 
	SET HSNCODE = @HSNCode, UPDATEDBY = @UserID, UPDATEDATE = GETDATE()
	WHERE ITEMID = @ItemID AND ITEMCODEID <> @ItemCodeID
     
	-- Store Item Price    
	DECLARE @ITEMPRICEID INT = 0  
   
	SELECT @ITEMPRICEID = ITEMPRICEID 
	FROM 
		ITEMPRICE IP 
	WHERE     
		IP.ITEMCODEID = @ItemCodeID 
		AND IP.MRP = @MRP   
		AND IP.DELETEDDATE IS NULL  
		AND IP.BRANCHID IS NULL
  
	IF @ITEMPRICEID = 0    
	BEGIN    
		
		IF (@SALEPRICE <= 0)
		BEGIN
			RAISERROR('Sale price must be greater than 0',16,1)
			RETURN;
		END

		IF EXISTS (
			SELECT 1 FROM ITEMPRICE
			WHERE ITEMCODEID = @ITEMCODEID 
				AND MRP = @MRP 
				AND DELETEDDATE IS NULL
		)
		BEGIN
			RAISERROR('MRP already exists with same or different saleprice',16,1)
			RETURN
		END

			DECLARE @SourceProcedure NVARCHAR(517) =
        QUOTENAME(OBJECT_SCHEMA_NAME(@@PROCID))
        + N'.'
        + QUOTENAME(OBJECT_NAME(@@PROCID));

    EXEC sys.sp_set_session_context
        @key = N'ITEMPRICE_SOURCE_PROC',
        @value = @SourceProcedure;

		INSERT INTO ITEMPRICE(ITEMCODEID, SALEPRICE, MRP, GSTID, CREATEDBY, CREATEDDATE)
		SELECT @ItemCodeID, @SalePrice, @MRP, @GSTID, @UserID, GETDATE()    
		SET @ITEMPRICEID = SCOPE_IDENTITY()  

		IF @IsOpenItem = 1
		BEGIN
			
			INSERT INTO STOCKMOVE(OLDITEMPRICEID, NEWITEMPRICEID, REASON, STOCKADJUSTMENTTYPEID, CREATEDBY, CREATEDDATE)
			SELECT 
				IP.ITEMPRICEID, @ITEMPRICEID, 'Open item Stock entry', 2, @UserID, GETDATE()
			FROM 
				ITEMPRICE IP 
			WHERE 
				IP.ITEMCODEID = @ItemCodeID 
				AND IP.ITEMPRICEID <> @ITEMPRICEID 
				AND IP.DELETEDDATE IS NULL 
				AND IP.BRANCHID IS NULL

		END
	END   
 
	IF NOT EXISTS 
	(
		SELECT 1 FROM ITEMCOSTPRICE ICP 
		WHERE ICP.ITEMPRICEID = @ITEMPRICEID AND ICP.DELETEDDATE IS NULL 
			AND ICP.COSTPRICEWOT = @CostPriceWOT AND ICP.COSTPRICEWT = @CostPriceWT
	)
	BEGIN
		INSERT INTO ITEMCOSTPRICE(ITEMPRICEID, COSTPRICEWT, COSTPRICEWOT, QUANTITY, WEIGHTINKGS, GSTID, CREATEDBY, CREATEDDATE)
		SELECT @ITEMPRICEID,  @CostPriceWT, @CostPriceWOT, CASE WHEN @IsOpenItem = 1  THEN 0 ELSE 1 END, CASE WHEN @IsOpenItem = 1  THEN 1 ELSE 0 END
		, @GSTID, @UserID, GETDATE()
	END
    
	SELECT CONCAT(@ItemCodeID, ',', @ItemID) AS ITEMANDCODEID    
    
END
GO
