/****** Object:  StoredProcedure [dbo].[USP_CU_ITEMPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_ITEMPRICE]
@ITEMCODEID INT,
@ITEMPRICEID INT = 0,
@USERID INT,
@MRP DECIMAL(10,2),
@SALEPRICE DECIMAL(10,2),
@GSTID INT,
@Immediate BIT = 0,
@GoLiveDate DATETIME = NULL
AS
BEGIN
	IF (@SALEPRICE <= 0)
		BEGIN
			RAISERROR('Sale price must be greater than 0',16,1)
			RETURN;
		END

	DECLARE @SourceProcedure NVARCHAR(517) =
        QUOTENAME(OBJECT_SCHEMA_NAME(@@PROCID))
        + N'.'
        + QUOTENAME(OBJECT_NAME(@@PROCID));

    EXEC sys.sp_set_session_context
        @key = N'ITEMPRICE_SOURCE_PROC',
        @value = @SourceProcedure;

	IF(@ITEMPRICEID <= 0)
	BEGIN

		IF EXISTS (
			SELECT 1 FROM ITEMPRICE
			WHERE ITEMCODEID = @ITEMCODEID 
				AND MRP = @MRP 
				AND BRANCHID IS NULL
				AND DELETEDDATE IS NULL
		)
		BEGIN
			RAISERROR('MRP already exists with same or different saleprice',16,1)
			RETURN
		END

		DECLARE @LATESTIPID INT
		SELECT TOP(1) @LATESTIPID = ITEMPRICEID FROM ITEMPRICE WHERE ITEMCODEID = @ITEMCODEID AND DELETEDDATE IS NULL ORDER BY CREATEDDATE DESC

		INSERT INTO ITEMPRICE(ITEMCODEID, MRP, SALEPRICE, GSTID, CREATEDBY, CREATEDDATE, [IMMEDIATE])
		VALUES(@ITEMCODEID, @MRP, @SALEPRICE, @GSTID, @USERID , GETDATE(), 1)
		SET @ITEMPRICEID = SCOPE_IDENTITY()

		INSERT INTO ITEMCOSTPRICE(ITEMPRICEID,COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,CREATEDBY,CREATEDDATE)
		SELECT TOP(1) @ITEMPRICEID,COSTPRICEWT,COSTPRICEWOT,1,1,GSTID,@USERID,CREATEDDATE
		FROM ITEMCOSTPRICE WHERE ITEMPRICEID = @LATESTIPID
		
		INSERT INTO STOCKMOVE(OLDITEMPRICEID, NEWITEMPRICEID, REASON, STOCKADJUSTMENTTYPEID, CREATEDBY, CREATEDDATE)
		SELECT 
			IP.ITEMPRICEID, @ITEMPRICEID, 'Open item - price change', 2, @UserID, GETDATE()
		FROM
			ITEMPRICE IP
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		WHERE 
			IP.ITEMCODEID = @ITEMCODEID
			AND IP.DELETEDDATE IS NULL
			AND IP.BRANCHID IS NULL
			AND IP.ITEMPRICEID <> @ITEMPRICEID
			AND I.ISOPENITEM = 1

	END
	ELSE
	BEGIN

		IF EXISTS(
					SELECT 1 
					FROM 
						ITEMPRICE IP 
						LEFT JOIN STOCKMOVE SM ON SM.NEWITEMPRICEID = IP.ITEMPRICEID 
					WHERE 
						IP.[IMMEDIATE] = 0 
						AND ISNULL(SM.GOLIVEDATE, '1900-01-01') > GETDATE()
						AND IP.ITEMPRICEID = @ITEMPRICEID
				)
		BEGIN

			--allow sale price change if the mrp is not active yet
			UPDATE SM
			SET SM.GOLIVEDATE = @GoLiveDate, SM.UPDATEDBY = @USERID, SM.UPDATEDDATE = GETDATE()
			FROM STOCKMOVE SM				
			WHERE SM.NEWITEMPRICEID = @ITEMPRICEID

			UPDATE IP
			SET IP.[IMMEDIATE] = @Immediate, IP.SALEPRICE = @SALEPRICE, IP.UPDATEDBY = @USERID, IP.UPDATEDATE = GETDATE()
			FROM ITEMPRICE IP				
			WHERE IP.ITEMPRICEID = @ITEMPRICEID

			SELECT @ITEMPRICEID

			RETURN

		END

		IF EXISTS
		(
			SELECT 1 FROM ITEMPRICE 
			WHERE ITEMCODEID = @ITEMCODEID 
				AND ITEMPRICEID <> @ITEMPRICEID 
				AND MRP = @MRP 
				AND BRANCHID IS NULL
				AND DELETEDDATE IS NULL
		)
		BEGIN
			RAISERROR('MRP already exists with same or different saleprice',16,1)
			RETURN
		END

		DECLARE @NewItemPriceID int = 0
		INSERT INTO ITEMPRICE(ITEMCODEID, MRP, SALEPRICE, GSTID, CREATEDBY, CREATEDDATE, [IMMEDIATE])
		VALUES(@ITEMCODEID, @MRP, @SALEPRICE, @GSTID, @USERID , GETDATE(), @Immediate)

		SET @NewItemPriceID = SCOPE_IDENTITY()

		INSERT INTO ITEMCOSTPRICE(ITEMPRICEID,COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,CREATEDBY,CREATEDDATE)
		SELECT TOP(1) @NewItemPriceID,COSTPRICEWT,COSTPRICEWOT,1,1,GSTID,@USERID,CREATEDDATE
		FROM ITEMCOSTPRICE WHERE ITEMPRICEID = @ITEMPRICEID

		DECLARE @StockMoveID INT

		INSERT INTO STOCKMOVE(OLDITEMPRICEID, NEWITEMPRICEID, STOCKADJUSTMENTTYPEID, GOLIVEDATE, CREATEDBY, CREATEDDATE)
		SELECT @ITEMPRICEID, @NewItemPriceID, 2, @GoLiveDate, @USERID, GETDATE()

		SET @StockMoveID = SCOPE_IDENTITY()

		SET  @ITEMPRICEID = @NewItemPriceID
	END

	SELECT @ITEMPRICEID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_ITEMSUBCLASSIFICATION]    Script Date: 17-10-2026 13:04:47 ******/
