CREATE   PROC [dbo].[USP_CU_ITEMSUBCLASSIFICATION]
(
	@ItemSubClassificationID INT = 0
	, @SubClassificationName VARCHAR(100)
	, @ItemClassificationID INT
	, @UserID INT
)
AS
BEGIN

	IF EXISTS(SELECT 1 FROM ITEMSUBCLASSIFICATION WHERE SUBCLASSIFICATIONNAME = @SubClassificationName AND CLASSIFICATIONID = @ItemClassificationID AND SUBCLASSIFICATIONID <> @ItemSubClassificationID)
	BEGIN
		SELECT 'Sub-Classification name already exists. Operation has been cancelled!!'
		RETURN
	END

	IF @ItemSubClassificationID <= 0
	BEGIN
		
		INSERT INTO ITEMSUBCLASSIFICATION(CLASSIFICATIONID, SUBCLASSIFICATIONNAME, CREATEDBY, CREATEDDATE)
		SELECT @ItemClassificationID, @SubClassificationName, @UserID, GETDATE()

		SET @ItemSubClassificationID = SCOPE_IDENTITY()
	END
	ELSE
	BEGIN

		UPDATE ISCLS
		SET
			CLASSIFICATIONID = @ItemClassificationID
			, SUBCLASSIFICATIONNAME = @SubClassificationName
			, UPDATEDBY = @UserID
			, UPDATEDDATE = GETDATE()
		FROM ITEMSUBCLASSIFICATION ISCLS
		WHERE ISCLS.SUBCLASSIFICATIONID = @ItemSubClassificationID

	END

	SELECT @ItemSubClassificationID
END
GO
