/****** Object:  StoredProcedure [dbo].[USP_CU_MOP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_MOP]
    @MOPID int = 0,
    @MOPNAME varchar(100),
    @USERID varchar(100) = 0,
    @ISGATEWAYCONFIGURABLE bit = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NULLIF(LTRIM(RTRIM(@MOPNAME)), '') IS NULL OR LEN(@MOPNAME) > 50
        THROW 50001, 'MOP name is required and must not exceed 50 characters.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @MOPID > 0
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM dbo.TBLMOP WITH (UPDLOCK, HOLDLOCK)
                           WHERE MOPID = @MOPID AND DELETEDDATE IS NULL)
                THROW 50002, 'Active MOP not found.', 1;

            IF @ISGATEWAYCONFIGURABLE = 0 AND EXISTS
            (
                SELECT 1 FROM dbo.BRANCHCOUNTERMOP
                WHERE MOPID = @MOPID AND DELETEDDATE IS NULL
                  AND PAYMENTGATEWAYINFOID IS NOT NULL
            )
                THROW 50003, 'Remove active gateway assignments before disabling gateway configuration.', 1;

            UPDATE dbo.TBLMOP
            SET MOPNAME = @MOPNAME,
                ISGATEWAYCONFIGURABLE = ISNULL(@ISGATEWAYCONFIGURABLE, ISGATEWAYCONFIGURABLE),
                UPDATEDBY = @USERID, UPDATEDDATE = GETDATE()
            WHERE MOPID = @MOPID;
        END
        ELSE
        BEGIN
            INSERT dbo.TBLMOP (MOPNAME, ISGATEWAYCONFIGURABLE, CREATEDBY, CREATEDDATE)
            VALUES (@MOPNAME, ISNULL(@ISGATEWAYCONFIGURABLE, 0), @USERID, GETDATE());
            SET @MOPID = CONVERT(int, SCOPE_IDENTITY());
        END;

        COMMIT TRANSACTION;
        SELECT @MOPID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_OFFER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
