CREATE PROCEDURE [dbo].[USP_CU_OFFER]            
@OfferID int = 0,            
@OfferName nvarchar(100),            
@OfferCode nvarchar(10),            
@StartDate datetime,            
@EndDate datetime,            
@OfferValue decimal(10,2) = null,
@OfferTypeID int,            
@CategoryID int = null,            
@ItemGroupID int = null,           
@IsActive bit = 1,          
@AppliesToID int,      
@UserID int,
@FreeItemPriceID int = null,
@NumberOfItems int = null,
@OFFERTHRESHOLDPRICE DECIMAL(18,2) = NULL,
@NumberOfFreeItems int = null
AS            
BEGIN            
            
	IF(@OfferID <= 0)            
	begin            
            
		insert into OFFER(OFFERNAME,OFFERCODE,STARTDATE,      
		ENDDATE,OFFERVALUE,OFFERTYPEID,CATEGORYID,ITEMGROUPID,      
		CREATEDBY,CREATEDDATE,ISACTIVE,APPLIESTOID,
		FREEITEMPRICEID,NUMBEROFITEMS,OFFERTHRESHOLDPRICE, NUMBEROFFREEITEMS)            
		select @OfferName,@OfferCode,@StartDate,      
		@EndDate,@OfferValue,@OfferTypeID,@CategoryID,@ItemGroupID,      
		@UserID,GETDATE(),@IsActive,@AppliesToID,
		@FreeItemPriceID,@NumberOfItems,@OFFERTHRESHOLDPRICE, @NumberOfFreeItems
            
		set @OfferID = SCOPE_IDENTITY()            
            
	end            
	else             
	begin            
            
		update OFFER set OFFERNAME = @OfferName,OFFERCODE = @OfferCode,            
		STARTDATE = @StartDate,ENDDATE = @EndDate,OFFERVALUE = @OfferValue,
		OFFERTYPEID = @OfferTypeID,CATEGORYID = @CategoryID,ITEMGROUPID = @ItemGroupID,            
		UPDATEDBY = @UserID,UPDATEDDATE = GETDATE(),ISACTIVE = @IsActive,APPLIESTOID = @AppliesToID,
		FREEITEMPRICEID = @FreeItemPriceID, NUMBEROFITEMS = @NumberOfItems, OFFERTHRESHOLDPRICE = @OFFERTHRESHOLDPRICE,
		NUMBEROFFREEITEMS = @NumberOfFreeItems
		where OFFERID = @OfferID            
            
	end                     
	select @OfferID            
            
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_OFFERBRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_OFFERBRANCH]
@OfferID int,
@BranchID int,
@UserID int,
@IsBaseoffer bit = 0
AS
BEGIN
	IF @IsBaseoffer = 0
	BEGIN
		IF @BranchID = -1 
		BEGIN
			INSERT INTO OFFERBRANCH(OFFERID,BRANCHID,CREATEDBY,CREATEDDATE)
			SELECT @OfferID, B.BRANCHID, @UserID, GETDATE()
			FROM BRANCH B 
			WHERE  B.DELETEDDATE IS NULL AND NOT EXISTS (SELECT 1 FROM OFFERBRANCH OB WHERE OB.BRANCHID = B.BRANCHID AND OB.OFFERID = @OfferID AND DELETEDDATE IS NULL)
		END
		ELSE
		BEGIN
			INSERT INTO OFFERBRANCH(OFFERID,BRANCHID,CREATEDBY,CREATEDDATE)
			SELECT @OfferID,@BranchID,@UserID,GETDATE()
			WHERE NOT EXISTS (SELECT 1 FROM OFFERBRANCH OB WHERE OB.BRANCHID = @BranchID AND OB.OFFERID = @OfferID AND DELETEDDATE IS NULL)
		END

		UPDATE OFFER
		SET UPDATEDBY = @UserID, UPDATEDDATE = GETDATE()
		WHERE OFFERID = @OfferID

		UPDATE OFFERITEMMAP
		SET CREATEDBY = @UserID, CREATEDDATE = GETDATE()
		WHERE OFFERID = @OfferID
	END
	ELSE 
	BEGIN
		
		IF @BranchID = -1
		BEGIN
			
			INSERT INTO OFFERBRANCH(OFFERID,BRANCHID,CREATEDBY,CREATEDDATE)
			SELECT OFR.OFFERID,B.BRANCHID,@USERID,GETDATE() 
			FROM OFFER OFR CROSS APPLY BRANCH B 
			WHERE OFR.BASEOFFERID = @OfferID
				AND B.DELETEDDATE IS NULL 
				AND OFR.DELETEDDATE IS NULL
				AND NOT EXISTS 
				(
					SELECT 1 FROM BASEOFFERBRANCH BOB 
					WHERE BOB.BRANCHID = B.BRANCHID 
						AND BOB.BASEOFFERID = @OfferID 
						AND BOB.DELETEDDATE IS NULL
				)

			INSERT INTO BASEOFFERBRANCH(BASEOFFERID,BRANCHID,CREATEDBY,CREATEDDATE)
			SELECT @OfferID, B.BRANCHID, @UserID, GETDATE()
			FROM BRANCH B 
			WHERE  B.DELETEDDATE IS NULL 
				AND NOT EXISTS 
				(
					SELECT 1 FROM BASEOFFERBRANCH BOB 
					WHERE BOB.BRANCHID = B.BRANCHID 
						AND BOB.BASEOFFERID = @OfferID 
						AND BOB.DELETEDDATE IS NULL
				)
		END
		ELSE
		BEGIN
			INSERT INTO BASEOFFERBRANCH(BASEOFFERID,BRANCHID,CREATEDBY,CREATEDDATE)
			VALUES(@OfferID,@BRANCHID,@USERID,GETDATE())

			INSERT INTO OFFERBRANCH(OFFERID,BRANCHID,CREATEDBY,CREATEDDATE)
			SELECT OFFERID,@BRANCHID,@USERID,GETDATE() FROM OFFER
			WHERE BASEOFFERID = @OfferID
				AND DELETEDDATE IS NULL
		END
	END

	select @BranchID AS OFFERBRANCHID

END
GO
