/****** Object:  StoredProcedure [dbo].[USP_CU_OFFERFROMBASE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_OFFERFROMBASE]
@OFFERID INT = 0
,@OFFERTYPEID INT
,@OFFERVALUE DECIMAL(18,2)
,@ITEMCODEID INT = 0
,@BASEOFFERID INT
,@USERID INT
,@NUMBEROFPIECES INT
AS
BEGIN
	BEGIN TRY
		BEGIN TRAN
			SELECT @OFFERID = OFFERID 
			FROM OFFER 
			WHERE OFFERTYPEID = @OFFERTYPEID 
				AND OFFERVALUE = @OFFERVALUE 
				AND BASEOFFERID = @BASEOFFERID
				AND DELETEDDATE IS NULL

			IF @OFFERID = 0
			BEGIN
				
				DECLARE @OFFERCODE VARCHAR(10), @OFFERNAME VARCHAR(100) , @OFCOUNT INT

				SELECT @OFCOUNT = COUNT(*) FROM OFFER WHERE BASEOFFERID = @BASEOFFERID
				SELECT 
					@OFFERCODE = OFFERCODE + CAST(@OFCOUNT + 1 AS VARCHAR(10)), 
					@OFFERNAME = OFFERNAME + CAST(@OFCOUNT + 1 AS VARCHAR(100))
				FROM BASEOFFER 
				WHERE BASEOFFERID = @BASEOFFERID 


				INSERT INTO OFFER(OFFERNAME,OFFERCODE,OFFERVALUE,OFFERTYPEID,ISACTIVE,APPLIESTOID,BASEOFFERID,CREATEDBY,CREATEDDATE)
				VALUES(@OFFERNAME,@OFFERCODE,@OFFERVALUE,@OFFERTYPEID,1,1,@BASEOFFERID,@USERID,GETDATE())
				SET @OFFERID = SCOPE_IDENTITY()

				INSERT INTO OFFERBRANCH (OFFERID, BRANCHID, CREATEDBY,CREATEDDATE)
				SELECT @OFFERID, BRANCHID, @USERID, GETDATE() FROM BASEOFFERBRANCH WHERE BASEOFFERID = @BASEOFFERID
			END

			IF NOT EXISTS(SELECT 1 FROM OFFERITEMMAP WHERE OFFERID = @OFFERID AND ITEMCODEID = @ITEMCODEID AND DELETEDDATE IS NULL)
			BEGIN
				INSERT INTO OFFERITEMMAP(OFFERID,ITEMCODEID,CREATEDBY,CREATEDDATE, NUMBEROFPIECES)
				VALUES(@OFFERID,@ITEMCODEID,@USERID,GETDATE(), @NUMBEROFPIECES)
			END
		COMMIT TRAN                                          
	END TRY                                          
	BEGIN CATCH                                          
		SELECT ERROR_MESSAGE() AS ErrorMessage                                           
		IF(@@TRANCOUNT > 0)                                          
		ROLLBACK TRAN                                          
	END CATCH                             
	SELECT @OFFERID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_OFFERITEM]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
