CREATE PROCEDURE [dbo].[USP_CU_OFFERITEM]
    @OfferItemMapID int = 0,
    @OfferID int = 0,
    @ItemCodeID int,
    @UserID int,
    @NUMBEROFPIECES int = 0,
    @OFFERITEMCONFIG nvarchar(max)
AS
BEGIN
    SET NOCOUNT ON;

    IF ISNULL(@OfferItemMapID, 0) = 0
    BEGIN
        INSERT INTO OFFERITEMMAP
        (
            OFFERID,
            ITEMCODEID,
            CREATEDBY,
            CREATEDDATE,
            NUMBEROFPIECES,
            OFFERITEMCONFIG
        )
        SELECT
            @OfferID,
            @ItemCodeID,
            @UserID,
            GETDATE(),
            @NUMBEROFPIECES,
            @OFFERITEMCONFIG;

        SELECT SCOPE_IDENTITY() AS OFFERITEMMAPID;
    END
    ELSE
    BEGIN
        UPDATE OFFERITEMMAP
        SET
            NUMBEROFPIECES = @NUMBEROFPIECES,
            OFFERITEMCONFIG = @OFFERITEMCONFIG,
            UPDATEDBY = @UserID,
            UPDATEDDATE = GETDATE()
        WHERE OFFERITEMMAPID = @OfferItemMapID;

        SELECT @OfferItemMapID AS OFFERITEMMAPID;
    END
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_PICKLIST_TRAYDATA]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[USP_CU_PICKLIST_TRAYDATA]
(
	@PicklistID INT,
	@PickListItemID INT,
	@Quantity DECIMAL(18, 2),
	@TrayNumber VARCHAR(20),
	@UserID INT
)
AS
BEGIN

	IF EXISTS 
		( 
			SELECT 1 
			FROM PICKLISTITEM PLI 
			WHERE 
				PLI.PICKLISTITEMID = @PickListItemID
				AND PLI.QUANTITY - PLI.PICKEDQUANTITY < @Quantity
		)
	BEGIN
		
		THROW 50001, 'Given Quantity is exceeding availble quantity', 1
		RETURN

	END

	IF EXISTS 
		( 
			SELECT 1 
			FROM PICKLIST PLI 
			WHERE 
				PICKLISTID = @PicklistID
				AND PICKEDSTATUS <> 0
		)
	BEGIN
		
		THROW 50001, 'Picklist is already submitted', 1
		RETURN

	END


	DECLARE @PickListTrayID INT, @PickListItemDetailID INT, @BranchID INT, @CategoryID INT

	SELECT @BranchID = BRANCHID, @CategoryID = CATEGORYID FROM PICKLIST WHERE PICKLISTID = @PicklistID
	
	SELECT @PickListTrayID = PLT.PICKLISTTRAYID 
	FROM PICKLISTTRAY PLT
	WHERE 
		PLT.BRANCHID = @BranchID
		AND PLT.TRAYNUMBER = @TrayNumber
		AND PLT.CATEGORYID = @CategoryID
		AND PLT.ISDISPATCHED = 0
		AND PLT.DELETEDDATE IS NULL

	IF ISNULL(@PickListTrayID, 0) = 0
	BEGIN

		INSERT INTO PICKLISTTRAY(BRANCHID, TRAYNUMBER, CREATEDBY, CREATEDDATE, CATEGORYID)
		SELECT @BranchID, @TrayNumber, @UserID, GETDATE(), @CategoryID
	
		SELECT @PickListTrayID = SCOPE_IDENTITY()
	END

	SELECT @PickListItemDetailID = PLID.PICKLISTITEMDETAILID
	FROM PICKLISTITEMDETAIL PLID
	WHERE
		PLID.PICKLISTITEMID = @PickListItemID
		AND PLID.PICKLISTTRAYID = @PickListTrayID
		AND PLID.STOCKDISPATCHDETAILID IS NULL
		AND PLID.DELETEDDATE IS NULL

	IF ISNULL(@PickListItemDetailID, 0) = 0
	BEGIN

		INSERT INTO PICKLISTITEMDETAIL(PICKLISTITEMID, PICKLISTTRAYID, QUANTITY, CREATEDBY, CREATEDDATE)
		SELECT @PickListItemID, @PickListTrayID, @Quantity, @UserID, GETDATE()

		SELECT @PickListItemDetailID = SCOPE_IDENTITY()

	END
	ELSE
	BEGIN

		UPDATE PLID
		SET 
			PLID.QUANTITY = PLID.QUANTITY + @Quantity
			, PLID.UPDATEDBY = @UserID
			, PLID.UPDATEDDATE = GETDATE()
		FROM
			PICKLISTITEMDETAIL PLID
		WHERE PLID.PICKLISTITEMDETAILID = @PickListItemDetailID

	END

	UPDATE PLI
	SET PLI.PICKEDQUANTITY = PLI.PICKEDQUANTITY + @Quantity
	FROM PICKLISTITEM PLI 
	WHERE PLI.PICKLISTITEMID = @PickListItemID

	SELECT @PickListItemDetailID AS PICKLISTITEMDETAILID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_PICKLISTDISPATCHDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[USP_CU_PICKLISTDISPATCHDETAIL]
(
	@ItemCodeID INT,
	@PicklistDispatchID INT,
	@Quantity INT,
	@MRP DECIMAL(18, 2),
	@TrayNumber VARCHAR(10)
)
AS
BEGIN

	DECLARE @BranchID INT, @LocationDivisionID INT, @PicklistDispatchDetailID INT
		, @TotalPickListQty INT, @AllocatedQty INT, @AvailableQty INT

	IF NOT EXISTS 
	(
		SELECT 1
		FROM PICKLISTDISPATCH PLD
		WHERE 
			PLD.PICKLISTDISPATCHID = @PicklistDispatchID
			AND PLD.DELETEDDATE IS NULL
			AND PLD.STOCKDISPATCHID IS NULL
	)
	BEGIN
		SELECT 'Picklist dispatch not found\already dispatched or deleted'
		RETURN
	END

	SELECT @BranchID = PLD.BRANCHID, @LocationDivisionID = PLD.LOCATIONDIVISIONID
	FROM PICKLISTDISPATCH PLD
	WHERE PLD.PICKLISTDISPATCHID = @PicklistDispatchID

	SELECT @TotalPickListQty = SUM(PLI.QUANTITY)
	FROM
		PICKLISTITEM PLI
		INNER JOIN PICKLISTBRANCH PLB ON PLB.PICKLISTBRANCHID = PLI.PICKLISTBRANCHID
		INNER JOIN PICKLIST PL ON PL.PICKLISTID = PLB.PICKLISTID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PLI.ITEMCODEID
	WHERE
		PLB.BRANCHID = @BranchID
		AND PL.LOCATIONDIVISIONID = @LocationDivisionID
		AND PL.DELETEDDATE IS NULL
		AND PLB.DELETEDDATE IS NULL
		AND PLI.DELETEDDATE IS NULL
		AND PLB.PICKEDSTATUS = 19 --Seggregated
		AND PLI.ITEMCODEID = @ItemCodeID
		AND PLI.MRP = @MRP

	SELECT @AllocatedQty = SUM(PLDD.QUANTITY)
	FROM
		PICKLISTDISPATCHDETAIL PLDD
		INNER JOIN PICKLISTDISPATCH PLD ON PLD.PICKLISTDISPATCHID = PLDD.PICKLISTDISPATCHID
	WHERE
		PLD.BRANCHID = @BranchID
		AND PLD.LOCATIONDIVISIONID = @LocationDivisionID
		AND PLDD.DELETEDDATE IS NULL
		AND PLD.DELETEDDATE IS NULL
		AND PLD.STOCKDISPATCHID IS NULL
		AND PLDD.ITEMCODEID = @ItemCodeID
		AND PLDD.MRP = @MRP

	SELECT @AvailableQty = ISNULL(@TotalPickListQty, 0) - ISNULL(@AllocatedQty, 0)
	
	IF @Quantity > @AvailableQty
	BEGIN
		SELECT REPLACE(REPLACE('Given quantity {0} exceeds available quantity {1}', '{0}', @Quantity), '{1}', @AvailableQty)
		RETURN
	END

	SELECT @PicklistDispatchDetailID = PLDD.PICKLISTDISPATCHDETAILID
	FROM PICKLISTDISPATCHDETAIL PLDD
	WHERE
		PLDD.PICKLISTDISPATCHID = @PicklistDispatchID
		AND PLDD.ITEMCODEID = @ItemCodeID
		AND PLDD.MRP = @MRP
		AND PLDD.DELETEDDATE IS NULL
		AND PLDD.TRAYNUMBER = @TrayNumber


	IF ISNULL(@PicklistDispatchDetailID, 0) = 0
	BEGIN
		INSERT INTO PICKLISTDISPATCHDETAIL(PICKLISTDISPATCHID, ITEMCODEID, MRP, TRAYNUMBER, QUANTITY, CREATEDDATE)
		SELECT @PicklistDispatchID, @ItemCodeID, @MRP, @TrayNumber, @Quantity, GETDATE()

		SET @PicklistDispatchDetailID = SCOPE_IDENTITY()
	END
	ELSE
	BEGIN
		UPDATE PLDD
		SET PLDD.QUANTITY = PLDD.QUANTITY + @Quantity
		FROM PICKLISTDISPATCHDETAIL PLDD
		WHERE PLDD.PICKLISTDISPATCHDETAILID = @PicklistDispatchDetailID
	END

	SELECT @PicklistDispatchDetailID

END
GO
