CREATE PROC [dbo].[USP_CU_POS_PGW_TRANSACTIONDATA]    
(    
 @DATA POS_PGW_TRANSACTIONDATATYPE READONLY    
)    
AS    
BEGIN 

UPDATE B    
 SET    
B.TRANSACTIONDATAID = UB.TRANSACTIONDATAID
, B.MOPID = UB.MOPID
, B.AMOUNT = UB.AMOUNT 
, B.PAYMENTREQUEST = UB.PAYMENTREQUEST
, B.PAYMENTRESPONSE = UB.PAYMENTRESPONSE
, B.PAYMENTGATEWAYID = UB.PAYMENTGATEWAYID
, B.ADDITIONALCONFIG = UB.ADDITIONALCONFIG
, B.CREATEDDATE = UB.CREATEDDATE

 FROM     
  POS_PGW_TRANSACTIONDATA B 
  INNER JOIN @DATA UB ON UB.TRANSACTIONDATAID = B.TRANSACTIONDATAID
 WHERE    
  B.BRANCHCOUNTERID = UB.BRANCHCOUNTERID
    
 INSERT INTO POS_PGW_TRANSACTIONDATA
 (
	TRANSACTIONDATAID
	,BRANCHCOUNTERID
	,BILLID
	,MOPID
	,AMOUNT
	,PAYMENTREQUEST
	,PAYMENTRESPONSE
	,PAYMENTGATEWAYID
	,ADDITIONALCONFIG
	,CREATEDDATE
 )    
 SELECT TRANSACTIONDATAID
	,BRANCHCOUNTERID
	,BILLID
	,MOPID
	,AMOUNT
	,PAYMENTREQUEST
	,PAYMENTRESPONSE
	,PAYMENTGATEWAYID
	,ADDITIONALCONFIG
	,CREATEDDATE
 FROM @DATA UB    
 WHERE NOT EXISTS    
  (    
   SELECT 1 FROM POS_PGW_TRANSACTIONDATA BINNER 
   WHERE BINNER.TRANSACTIONDATAID = UB.TRANSACTIONDATAID 
	AND BINNER.BRANCHCOUNTERID = UB.BRANCHCOUNTERID
  )    

END
GO
