CREATE PROCEDURE [dbo].[USP_CU_SR_CANCEL_WRITE_OFF]
@SUPPLIERRETURNSID INT,
@USERID INT
AS
BEGIN
	
	UPDATE SUPPLIERRETURNS 
	SET 
		STATUS = 1, 
		UPDATEDDATE = GETDATE(), 
		UPDATEDBY = @USERID 
	WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID

END
