GO
CREATE PROCEDURE [dbo].[USP_CU_SR_CN_MAPPING]
@SUPPLIERRETURNSID INT,
@CREDITNOTEID  INT,
@CNVALUETOBEMAPPED DECIMAL(18,2),
@USERID INT
AS
BEGIN

	DECLARE @SupplierId INT;
    DECLARE @ExistingStatus INT;

	SELECT 
        @SupplierId = SupplierId,
        @ExistingStatus = STATUS
    FROM SUPPLIERRETURNS
    WHERE SUPPLIERRETURNSID = @SupplierReturnsID;

	IF @ExistingStatus = 3
	BEGIN
		RAISERROR ('Debit note already closed',16,1)
		RETURN;
	END

    IF @SupplierId IS NULL
    BEGIN
        RAISERROR ('Invalid Supplier Returns reference', 16, 1);
        RETURN;
    END

    IF @CNVALUETOBEMAPPED IS NULL OR @CNVALUETOBEMAPPED <= 0
    BEGIN
        RAISERROR ('CN Value is mandatory', 16, 1);
        RETURN;
    END

	IF @CREDITNOTEID IS NULL OR @CREDITNOTEID = 0
    BEGIN
        RAISERROR ('Credit Note is mandatory', 16, 1);
        RETURN;
    END

	IF NOT EXISTS (
            SELECT 1
            FROM CreditNote
            WHERE CreditNoteId = @CreditNoteId
                AND SupplierId = @SupplierId
                AND DeletedDate IS NULL
        )
        BEGIN
            RAISERROR ('Selected Credit Note does not belong to this supplier', 16, 1);
            RETURN;
        END

	IF NOT EXISTS
		(
			SELECT 1
			FROM CreditNote cn
			WHERE cn.CreditNoteId = @CREDITNOTEID
			AND cn.CreditValue >
				ISNULL(
					(
						SELECT SUM(MappedReturnValue)
						FROM SUPPLIERRETURNSCREDITNOTEMAP
						WHERE CREDITNOTEID = cn.CreditNoteId
						AND DELETEDDATE IS NULL
					),0
				)
		)
		BEGIN
			RAISERROR ('Selected Credit Note has no balance value available for mapping',16,1)
			RETURN
		END

	DECLARE 
		@TOTALDNVALUE DECIMAL(18,2) = 0, 
		@MAPPEDDNVALUE DECIMAL(18,2) = 0,
		@BALANCEDNVALUETOBEMAPPED DECIMAL(18,2) =0,
		
		@TOTALCNVALUE DECIMAL(18,2) = 0,
		@MAPPEDCNVALUE DECIMAL(18,2) = 0,
		@BALANCECNVALUECANBEMAPPED DECIMAL(18,2) = 0

	SELECT @TOTALDNVALUE = SUM(ICP.COSTPRICEWT * CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY ELSE SRD.WEIGHTINKGS END)
        FROM SUPPLIERRETURNSDETAIL SRD
        INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
        WHERE SRD.SUPPLIERRETURNSID = @SUPPLIERRETURNSID AND SRD.DELETEDDATE IS NULL
        GROUP BY SUPPLIERRETURNSID
	
	SELECT @MAPPEDDNVALUE = SUM(MappedReturnValue) FROM SUPPLIERRETURNSCREDITNOTEMAP WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID AND DELETEDDATE IS NULL

	SET @BALANCEDNVALUETOBEMAPPED = @TOTALDNVALUE - @MAPPEDDNVALUE
	
	SELECT @TOTALCNVALUE = CreditValue FROM CreditNote WHERE CreditNoteId = @CREDITNOTEID

	SELECT @MAPPEDCNVALUE = SUM(MappedReturnValue) FROM SUPPLIERRETURNSCREDITNOTEMAP WHERE CREDITNOTEID = @CREDITNOTEID AND DELETEDDATE IS NULL
	
	SET @BALANCECNVALUECANBEMAPPED = @TOTALCNVALUE - @MAPPEDCNVALUE

	IF(@CNVALUETOBEMAPPED > @BALANCEDNVALUETOBEMAPPED)
	BEGIN
		RAISERROR ('Mapping value cannot be greater than balance Debit Note value',16,1);
		RETURN;
	END

	IF(@CNVALUETOBEMAPPED > @BALANCECNVALUECANBEMAPPED)
	BEGIN
		RAISERROR ('Mapping value cannot be greater than available Credit Note value',16,1);
		RETURN;
	END

	IF EXISTS
	(
		SELECT 1
		FROM SUPPLIERRETURNSCREDITNOTEMAP
		WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID
		  AND CREDITNOTEID = @CREDITNOTEID
		  AND DELETEDDATE IS NULL
	)
	BEGIN

		UPDATE SUPPLIERRETURNSCREDITNOTEMAP
		SET 
			MappedReturnValue = MappedReturnValue + @CNVALUETOBEMAPPED,
			UPDATEDBY = @USERID,
			UPDATEDDATE = GETDATE()
		WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID
		  AND CREDITNOTEID = @CREDITNOTEID
		  AND DELETEDDATE IS NULL

	END
	ELSE
	BEGIN

		INSERT INTO SUPPLIERRETURNSCREDITNOTEMAP
		(
			SUPPLIERRETURNSID,
			CREDITNOTEID,
			CREATEDBY,
			CREATEDDATE,
			MappedReturnValue
		)
		VALUES
		(
			@SupplierReturnsID,
			@CreditNoteId,
			@UserID,
			GETDATE(),
			@CNVALUETOBEMAPPED
		)

	END

	UPDATE SUPPLIERRETURNS
    SET
        STATUS = 2, --Partially Closed
        UPDATEDBY = @UserID,
        UPDATEDDATE = GETDATE()
    WHERE SUPPLIERRETURNSID = @SupplierReturnsID;

	SELECT @SUPPLIERRETURNSID

END
GO
