/****** Object:  StoredProcedure [dbo].[USP_CU_STOCKDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_STOCKDISPATCH]            
@STOCKDISPATCHID INT = 0 OUT,    
@FROMBRANCHID INT,            
@TOBRANCHID INT,            
@CATEGORYID INT,          
@USERID INT,
@AUTOGENERATED BIT = 0,
@REFID INT = 0,
@BRANCHINDENTID INT = 0,
@SUBCATEGORYID INT = 0,
@Notes VARCHAR(MAX) = NULL
AS            
BEGIN            
   
   

	IF EXISTS(SELECT 1 FROM BRANCH WHERE BRANCHID = @TOBRANCHID AND isnull(ENABLESTOCKDISPATCH,0) = 0)
	BEGIN
		SELECT 'Stock dispatch disabled for selected branch, Please contact your administrator!'
		return;
	END

	IF @BRANCHINDENTID = 0 
	BEGIN
		SELECT @BRANCHINDENTID = NULL
	END
    
	IF(@STOCKDISPATCHID > 0)
	BEGIN
		UPDATE STOCKDISPATCH SET TOBRANCHID = @TOBRANCHID, NOTES = @Notes WHERE STOCKDISPATCHID = @STOCKDISPATCHID
	END
	ELSE
	BEGIN

		IF EXISTS (SELECT 1 FROM BRANCH WHERE BRANCHID = @TOBRANCHID AND ENABLESTOCKCOUNTING = 1)
		BEGIN
			SELECT 'Stock counting initiated for selected branch. Dispatch cannot be created'
			RETURN;
		END
		
		INSERT INTO STOCKDISPATCH(FROMBRANCHID, TOBRANCHID, CATEGORYID,SUBCATEGORYID ,STATUS,
					CREATEDBY, CREATEDDATE,AUTOGENERATED, REFID, BRANCHINDENTID, NOTES, ACTUALCREATEDDATE)
		VALUES(@FROMBRANCHID,@TOBRANCHID,@CATEGORYID,@SUBCATEGORYID,0,
					@USERID,GETDATE(),@AUTOGENERATED, @REFID, @BRANCHINDENTID, @Notes,GETDATE())
      
		SET @STOCKDISPATCHID = SCOPE_IDENTITY()    
	END
   
	SELECT  @STOCKDISPATCHID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_STOCKDISPATCH_BRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_STOCKDISPATCH_BRANCH]  
@STOCKENTRYID INT,  
@STOCKDISPATCHID INT = 0,  
@FROMBRANCHID INT = 45,  
@TOBRANCHID INT,  
@CATEGORYID INT,  
@USERID INT  
AS  
BEGIN  

	--CREATING DISPATCH FROM STOCKENTRY

	INSERT INTO STOCKDISPATCH(FROMBRANCHID, TOBRANCHID, STATUS, CREATEDBY, CREATEDDATE, CATEGORYID,AUTOGENERATED, REFID, SOURCEENTITYID)
	SELECT @FROMBRANCHID, @TOBRANCHID, 0, @UserID, GETDATE(), @CATEGORYID, 1, @STOCKENTRYID, 2
	SET @STOCKDISPATCHID = SCOPE_IDENTITY()

  
	IF @STOCKDISPATCHID = 0  
	BEGIN  
  		SELECT 'Dispatch not saved!'  
		RETURN  
  	END  
  
	--CREATING DISPATCHDETAIL FROM STOCKENTRYDETAIL

	INSERT INTO STOCKDISPATCHDETAIL  
	(  
		STOCKDISPATCHID,  
		ITEMPRICEID,  
		TRAYNUMBER,  
		DISPATCHQUANTITY,  
		RECEIVEDQUANTITY,  
		WEIGHTINKGS,  
		CREATEDDATE,
		ISACCEPTED
	)              
	SELECT   
		@STOCKDISPATCHID,   
		SED.ITEMPRICEID,   
		0,   
		SED.QUANTITY,   
		SED.QUANTITY,   
		SED.WEIGHTINKGS,   
		GETDATE(),
		0
	FROM   
	(  
		SELECT 
			ICP.ITEMPRICEID,
			SUM(SED.QUANTITY) AS QUANTITY , 
			SUM(SED.WEIGHTINKGS) AS WEIGHTINKGS 
		FROM STOCKENTRYDETAIL SED  
			INNER JOIN ITEMCOSTPRICE ICP ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID  
			INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID  
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID  
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID  
		WHERE STOCKENTRYID = @STOCKENTRYID 
			AND I.CATEGORYID = @CATEGORYID 
			AND SED.DELETEDDATE IS NULL  
		GROUP BY ICP.ITEMPRICEID  
	) SED   
  
	-- PROCCESSING STOCKDISPATCH
	--EXEC USP_P_STOCKDISPATCH @STOCKDISPATCHID, @UserID
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_STOCKDISPATCH_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_STOCKDISPATCH_v2]
@STOCKDISPATCHID INT = 0 OUT,    
@FROMBRANCHID INT,            
@TOBRANCHID INT,            
@CATEGORYID INT,          
@USERID INT,
@AUTOGENERATED BIT = 0,
@REFID INT = 0,
@BRANCHINDENTID INT = 0,
@SUBCATEGORYID INT = 0
AS            
BEGIN            
   
	IF EXISTS(SELECT 1 FROM BRANCH WHERE BRANCHID = @TOBRANCHID AND isnull(ENABLESTOCKDISPATCH,0) = 0)
	BEGIN
		SELECT 'Stock dispatch disabled for selected branch, Please contact your administrator!'
		return;
	END
    
	IF @BRANCHINDENTID = 0 
   BEGIN
		SELECT @BRANCHINDENTID = NULL
   END

	IF(@STOCKDISPATCHID > 0)
	BEGIN
		UPDATE STOCKDISPATCH SET TOBRANCHID = @TOBRANCHID WHERE STOCKDISPATCHID = @STOCKDISPATCHID
	END
	ELSE
	BEGIN
		INSERT INTO STOCKDISPATCH(FROMBRANCHID, TOBRANCHID, CATEGORYID,SUBCATEGORYID ,STATUS, 
					CREATEDBY, CREATEDDATE,AUTOGENERATED, REFID, BRANCHINDENTID)
		VALUES(@FROMBRANCHID,@TOBRANCHID,@CATEGORYID,@SUBCATEGORYID,0,
					@USERID,GETDATE(),@AUTOGENERATED, @REFID, @BRANCHINDENTID)
      
		SET @STOCKDISPATCHID = SCOPE_IDENTITY()    
	END

	DECLARE @IsManualDispatch bit = CASE WHEN @BRANCHINDENTID = 0 THEN 1 ELSE 0 END
	EXEC USP_R_DISPATCHDRAFT_v2 @UserID, @IsManualDispatch

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_STOCKDISPATCHDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_STOCKDISPATCHDETAIL]            
@STOCKDISPATCHDETAILID INT = 0,            
@STOCKDISPATCHID INT,            
@ITEMPRICEID INT,            
@TRAYNUMBER INT,            
@DISPATCHQUANTITY int,            
@WEIGHTINKGS DECIMAL(10,2),            
@USERID INT,
@BRANCHINDENTDETAILID INT = 0,
@TRAYINFOID INT = 0
AS            
BEGIN            
            
	IF NOT EXISTS
	(
		SELECT 1 FROM STOCKDISPATCH SD 			
		WHERE ISNULL(SD.STATUS, 0) = 0 AND SD.STOCKDISPATCHID = @STOCKDISPATCHID
	)
	BEGIN
		SELECT 'Dispatch already completed'
		RETURN
	END

	IF EXISTS(SELECT 1 FROM TRAYINFO WHERE TRAYINFOID = @TRAYINFOID AND DELETEDDATE IS NOT NULL)
	BEGIN
		SELECT 'Tray number no longer exists. To see the updated list, please close and reopen dispatch.'
		RETURN
	END


	DECLARE @WHStock DECIMAL(18, 2), @IsOpenItem BIT, @FromBranchID INT, @CategoryID INT
			, @ItemCodeID INT, @isWarehouse BIT = 0, @TOBRANCHID INT, @PARENTITEMID INT
			, @ItemID INT, @BranchIndentID INT

	SELECT @FromBranchID = SD.FROMBRANCHID, @TOBRANCHID = SD.TOBRANCHID, @BranchIndentID = SD.BRANCHINDENTID
	FROM STOCKDISPATCH SD 		
	WHERE SD.STOCKDISPATCHID = @STOCKDISPATCHID

	SELECT @isWarehouse = ISNULL(ISWAREHOUSE, 0) FROM BRANCH WHERE BRANCHID = @TOBRANCHID

	SELECT @IsOpenItem = I.ISOPENITEM, @ItemCodeID = IC.ITEMCODEID, @CategoryID = I.CATEGORYID, @ItemID = I.ITEMID
	FROM
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE IP.ITEMPRICEID = @ITEMPRICEID 

	
	IF @BRANCHINDENTDETAILID = 0 AND @BranchIndentID > 0
	BEGIN
		
		IF EXISTS
		(
			SELECT 1 
			FROM BRANCHINDENTDETAIL BID 
			WHERE 
				BID.BRANCHINDENTID = @BranchIndentID 
				AND BID.DELETEDDATE IS NULL
				AND BID.ITEMID = @ItemID
		)
		BEGIN
			SELECT 'Item already exists in auto-generated indent, cannot add it manually'
			RETURN
		END
	END
		
	IF(@isWarehouse = 1  AND (@PARENTITEMID > 0 OR @isOpenItem = 1))
	BEGIN
		IF(@isOpenItem = 1)
		BEGIN
			
			SELECT @WHStock = SUM(WEIGHTINKGS)
			FROM STOCKSUMMARY SS    
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
			WHERE SS.BRANCHID = @FROMBRANCHID AND IP.ITEMCODEID = @ITEMCODEID

		END
		ELSE
		BEGIN

			SELECT @WHStock = SUM(WEIGHTINKGS)
			FROM STOCKSUMMARY SS    
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID    
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
			WHERE SS.BRANCHID = @FROMBRANCHID AND I.ITEMID = @PARENTITEMID    

		END
	END
	
	IF(@isWarehouse = 0)
	BEGIN    
  
		SELECT @WHStock = CASE WHEN @isOpenItem = 1 THEN SUM(WEIGHTINKGS) ELSE SUM(QUANTITY) END
		FROM STOCKSUMMARY SS   
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
		WHERE SS.BRANCHID = @FROMBRANCHID AND IP.ITEMCODEID = @ITEMCODEID      
  
	END    

	--SELECT @WHStock = SUM(CASE WHEN @IsOpenItem = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END)
	--FROM
	--	STOCKSUMMARY SS
	--	INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID			
	--WHERE IP.ITEMCODEID = @ItemCodeID AND SS.BRANCHID = @FromBranchID

	IF (@WHStock < CASE WHEN @IsOpenItem = 1 THEN @WEIGHTINKGS ELSE @DISPATCHQUANTITY END)
		AND (@CategoryID NOT IN (2, 7, 14))
	BEGIN
		SELECT 'Warehouse stock is less than desired dispatch quantity'
		RETURN
	END

	IF @STOCKDISPATCHDETAILID > 0            
	BEGIN            
            
		UPDATE STOCKDISPATCHDETAIL             
		SET ITEMPRICEID = @ITEMPRICEID,            
			TRAYNUMBER = @TRAYNUMBER,            
			DISPATCHQUANTITY = @DISPATCHQUANTITY,            
			RECEIVEDQUANTITY = @DISPATCHQUANTITY,          
			WEIGHTINKGS = @WEIGHTINKGS,            
			UPDATEDATE = GETDATE(),
			ISTRAYVERIFIED = 0
		WHERE STOCKDISPATCHDETAILID = @STOCKDISPATCHDETAILID            
            
	END            
	ELSE            
	BEGIN            
      
		SELECT @STOCKDISPATCHDETAILID = ISNULL(STOCKDISPATCHDETAILID,0) 
		FROM STOCKDISPATCHDETAIL       
		WHERE STOCKDISPATCHID = @STOCKDISPATCHID 
			AND ITEMPRICEID = @ITEMPRICEID 
			AND TRAYNUMBER = @TRAYNUMBER 
			and DELETEDDATE is null
      
		IF(@STOCKDISPATCHDETAILID  > 0)      
		BEGIN      
    
			UPDATE STOCKDISPATCHDETAIL 
			SET DISPATCHQUANTITY = DISPATCHQUANTITY + @DISPATCHQUANTITY,    
				RECEIVEDQUANTITY = DISPATCHQUANTITY + @DISPATCHQUANTITY,    
				WEIGHTINKGS = WEIGHTINKGS + @WEIGHTINKGS,            
				UPDATEDATE = GETDATE(),
				ISTRAYVERIFIED = 0    
			WHERE STOCKDISPATCHDETAILID = @STOCKDISPATCHDETAILID     
    
		END      
		ELSE      
		BEGIN      
			INSERT INTO STOCKDISPATCHDETAIL(STOCKDISPATCHID,ITEMPRICEID,TRAYNUMBER,            
				DISPATCHQUANTITY,RECEIVEDQUANTITY,WEIGHTINKGS,CREATEDDATE, 
				BRANCHINDENTDETAILID, TRAYINFOID, ISVERIFIED)            
			VALUES(@STOCKDISPATCHID,@ITEMPRICEID,@TRAYNUMBER,            
				@DISPATCHQUANTITY,@DISPATCHQUANTITY,@WEIGHTINKGS,GETDATE(), 
				@BRANCHINDENTDETAILID, @TRAYINFOID, 0)            
			SET @STOCKDISPATCHDETAILID = SCOPE_IDENTITY()            
		END      
    
	END            
	SELECT @STOCKDISPATCHDETAILID            
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_STOCKENTRY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
