CREATE PROCEDURE [dbo].[USP_CU_STOCKENTRY]              
@STOCKENTRYID INT = 0,                  
@SUPPLIERID INT,                  
@SUPPLIERINVOICENO VARCHAR(30),                  
@TAXINCLUSIVE BIT,              
@INVOICEDATE DATE,          
@TCS DECIMAL(10,2) = NULL,        
@DISCOUNTPER DECIMAL(10,2) = NULL,        
@DISCOUNT DECIMAL(10,2) = NULL,        
@EXPENSES DECIMAL(10,2) = NULL,        
@TRANSPORT DECIMAL(10,2) = NULL,        
@CATEGORYID INT = 0,                
@USERID INT = 0,  
@IsBranchInvoice BIT = 0,  
@SourceBranchID INT = 0 ,
@SupplierIndentID INT = NULL
AS              
BEGIN              
  
	 DECLARE @FinYearStartDate DATE, @InvoiceFinYear INT, @FinYearEndDate DATE  
	 SELECT @InvoiceFinYear = YEAR(@INVOICEDATE) - CASE WHEN MONTH(@INVOICEDATE) > 3 THEN 0 ELSE 1 END  
	 SELECT @FinYearStartDate = DATEFROMPARTS(@InvoiceFinYear, 4, 1), @FinYearEndDate = DATEFROMPARTS(@InvoiceFinYear + 1, 3, 31)  
	 
	 IF EXISTS(
				SELECT 1 FROM STOCKENTRY 
				WHERE SUPPLIERID = @SUPPLIERID 
					AND SUPPLIERINVOICENO = @SUPPLIERINVOICENO 
					AND DELETEDDATE IS NULL 
					AND INVOICEDATE BETWEEN @FinYearStartDate AND @FinYearEndDate
					AND STOCKENTRYID <> @STOCKENTRYID
			)  
	 BEGIN  
		RAISERROR('Invoice Number Already Exists!',16,1)
		RETURN;
	 END  

	 SELECT @SupplierIndentID = CASE WHEN @SupplierIndentID = 0 THEN NULL ELSE @SupplierIndentID END

	 IF(@STOCKENTRYID > 0)
	 BEGIN
		UPDATE STOCKENTRY 
		SET 
			SUPPLIERINVOICENO = @SUPPLIERINVOICENO, 
			INVOICEDATE = @INVOICEDATE
		WHERE STOCKENTRYID = @STOCKENTRYID
		SELECT @STOCKENTRYID
	 END
	ELSE 
	BEGIN

	SELECT @SourceBranchID = BRANCHID FROM TBLUSER WHERE USERID = @USERID

	 INSERT INTO STOCKENTRY(SUPPLIERID,SUPPLIERINVOICENO,          
		 TAXINCLUSIVE,CATEGORYID,CREATEDBY,CREATEDDATE,STATUS,INVOICEDATE,      
		 TCS,DISCOUNTPER,DISCOUNT,EXPENSES,TRANSPORT,IsBranchInvoice, SOURCEBRANCHID,
		 SUPPLIERINDENTID, RECEIVINGBRANCHID)          
	 VALUES(@SUPPLIERID,@SUPPLIERINVOICENO,          
		 @TAXINCLUSIVE,@CATEGORYID,@USERID,GETDATE(),0,@INVOICEDATE,      
		 @TCS,@DISCOUNTPER,@DISCOUNT,@EXPENSES,@TRANSPORT, @IsBranchInvoice, @SourceBranchID,
		 @SupplierIndentID, @SourceBranchID)      
		 
	 SELECT @STOCKENTRYID = SCOPE_IDENTITY() 
	 
	 
	 -- Supplier indent found, add items 
	 IF ISNULL(@SupplierIndentID, 0) <> 0
	 BEGIN

		INSERT INTO STOCKENTRYDETAIL(STOCKENTRYID, SUPPLIERINDENTDETAILID, QUANTITY, CREATEDBY, CREATEDDATE)
		SELECT @STOCKENTRYID, SID.SUPPLIERINDENTDETAILID, SID.REQUIREDITEMINDENT, @USERID, GETDATE()
		FROM 
			SUPPLIERINDENTDETAIL SID
			LEFT JOIN 
				(
					SELECT I.ITEMID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END) FILLEDQTY
					FROM 
						STOCKENTRYDETAIL SED 
						INNER JOIN STOCKENTRY SE ON SE.STOCKENTRYID = SED.STOCKENTRYID	
						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = SED.ITEMCODEID
						INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
					WHERE
						SED.DELETEDDATE IS NULL
						AND SE.DELETEDDATE IS NULL
						AND SE.SUPPLIERINDENTID = @SupplierIndentID
					GROUP BY I.ITEMID
				) FILLED ON FILLED.ITEMID = SID.ITEMID
		WHERE 
			SID.SUPPLIERINDENTID = @SupplierIndentID
			AND SID.DELETEDDATE IS NULL
			AND ISNULL(FILLED.FILLEDQTY, 0) < SID.REQUIREDITEMINDENT
			AND SID.DESIREDINDENT <> 0

	 END

	 SELECT @STOCKENTRYID AS STOCKENTRYID        

   END        
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_STOCKENTRY_CREDITNOTEMAP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
