CREATE PROC [dbo].[USP_CU_STOCKENTRY_CREDITNOTEMAP]
(
    @STOCKENTRYID INT,
    @CREDITNOTEID INT,
    @CREDITVALUE DECIMAL(18, 2),
    @USERID INT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PROCCESSTIME DATETIME = GETDATE();

    IF EXISTS
    (
        SELECT 1
        FROM STOCKENTRYCREDITNOTEMAP
        WHERE STOCKENTRYID = @STOCKENTRYID
          AND CREDITNOTEID = @CREDITNOTEID
		  AND DELETEDDATE IS NULL
    )
    BEGIN
        SELECT 'This credit note is already mapped to this invoice.';
        RETURN;
    END;

    IF ISNULL(@CREDITVALUE, 0) <= 0
    BEGIN
        SELECT 'Credit note value should be greater than zero.';
        RETURN;
    END;

    INSERT INTO STOCKENTRYCREDITNOTEMAP
    (
        STOCKENTRYID,
        CREDITNOTEID,
        CREATEDBY,
        CREATEDDATE,
  
      MappedReturnValue
    )
    VALUES
    (
        @STOCKENTRYID,
        @CREDITNOTEID,
        @USERID,
        @PROCCESSTIME,
        @CREDITVALUE
    );

    SELECT SCOPE_IDENTITY();
END;
GO
