GO
CREATE PROCEDURE [dbo].[USP_CU_STOCKENTRYDETAIL_v2]
(
	@STOCKENTRYDETAILID INT = 0,
	@STOCKENTRYID INT,
	@ITEMCODEID INT,
	@QUANTITY INT = 0,
	@WEIGHTINKGS DECIMAL(10,2) = 0,
	@MRP DECIMAL(10,2)=0,
	@SALEPRICE DECIMAL(10,2) = 0,
	@COSTPRICEWT DECIMAL(11,4) = 0,
	@COSTPRICEWOT DECIMAL(11,4) = 0,
	@INVOICECPWITHTAX DECIMAL(11,4) = 0,
	@INVOICECPWITHOUTTAX DECIMAL(11,4) = 0,
	@GSTID INT = 0,
	@DISCOUNTFLAT DECIMAL(9,2)= 0,
	@DISCOUNTPERCENTAGE DECIMAL(4,2) = 0,
	@SCHEMEPERCENTAGE DECIMAL(4,2) = 0,
	@SCHEMEFLAT DECIMAL(9,2) = 0,
	@TOTALPRICEWT DECIMAL(11,4) = 0,
	@TOTALPRICEWOT DECIMAL(11,4) = 0,
	@APPLIEDDISCOUNT DECIMAL(9,2) = 0,
	@APPLIEDSCHEME DECIMAL(9,2) = 0,
	@APPLIEDDGST DECIMAL(9,2) = 0,
	@FINALPRICEWOTAX DECIMAL(9,2) = 0,
	@FINALPRICE DECIMAL(9,2) = 0,
	@CGST DECIMAL(10,2) = 0,
	@SGST DECIMAL(10,2) = 0,
	@IGST DECIMAL(10,2) = 0,
	@CESS DECIMAL(10,2) = 0,
	@HSNCODE VARCHAR(10) = '',
	@USERID INT,
	@ISFREEITEM BIT = 0
)
AS
BEGIN

	IF NOT EXISTS
	(
		SELECT 1 
		FROM STOCKENTRY SE 
		WHERE (ISNULL(SE.STATUS,0) = 0 OR ISNULL(SE.STATUS,0) = 2)
		AND SE.STOCKENTRYID=@STOCKENTRYID AND DELETEDDATE IS NULL
	)
	BEGIN
		RAISERROR('Stock entry already completed',16,1)
		RETURN
	END

	IF(@STOCKENTRYDETAILID > 0)
	BEGIN

		UPDATE STOCKENTRYDETAIL
		SET
			ITEMCODEID = @ITEMCODEID,
			CPWITHTAX = @COSTPRICEWT,
			CPWITHOUTTAX = @COSTPRICEWOT,
			INVOICECPWITHTAX = @INVOICECPWITHTAX,
			INVOICECPWITHOUTTAX = @INVOICECPWITHOUTTAX,
			MRP = @MRP,
			SALEPRICE = @SALEPRICE,
			GSTID = @GSTID,
			QUANTITY = @QUANTITY,
			WEIGHTINKGS = @WEIGHTINKGS,
			DISCOUNTFLAT = @DISCOUNTFLAT,
			DISCOUNTPERCENTAGE = @DISCOUNTPERCENTAGE,
			SCHEMEPERCENTAGE = @SCHEMEPERCENTAGE,
			SCHEMEFLAT = @SCHEMEFLAT,
			TOTALPRICEWT = @TOTALPRICEWT,
			TOTALPRICEWOT = @TOTALPRICEWOT,
			APPLIEDDISCOUNT = @APPLIEDDISCOUNT,
			APPLIEDSCHEME = @APPLIEDSCHEME,
			APPLIEDDGST = @APPLIEDDGST,
			FINALPRICEWOTAX = @FINALPRICEWOTAX,
			FINALPRICE = @FINALPRICE,
			CGST = @CGST,
			SGST = @SGST,
			IGST = @IGST,
			CESS = @CESS,
			UPDATEDBY = @USERID,
			UPDATEDATE = GETDATE(),
			ISFREEITEM = @ISFREEITEM
		WHERE STOCKENTRYDETAILID = @STOCKENTRYDETAILID

	END
	ELSE
	BEGIN

		SELECT @STOCKENTRYDETAILID = STOCKENTRYDETAILID
		FROM STOCKENTRYDETAIL
		WHERE STOCKENTRYID = @STOCKENTRYID
			AND ITEMCODEID = @ITEMCODEID
			AND MRP = @MRP
			AND SALEPRICE = @SALEPRICE
			AND CPWITHTAX = @COSTPRICEWT
			AND CPWITHOUTTAX = @COSTPRICEWOT
			AND DISCOUNTPERCENTAGE = @DISCOUNTPERCENTAGE
			AND SCHEMEPERCENTAGE = @SCHEMEPERCENTAGE
			AND GSTID = @GSTID
			AND DELETEDDATE IS NULL

		IF @STOCKENTRYDETAILID > 0
		BEGIN

			UPDATE STOCKENTRYDETAIL
			SET 
				QUANTITY = QUANTITY + @QUANTITY,
				WEIGHTINKGS = WEIGHTINKGS + @WEIGHTINKGS,
				DISCOUNTFLAT = DISCOUNTFLAT + @DISCOUNTFLAT,
				SCHEMEFLAT = SCHEMEFLAT + @SCHEMEFLAT,
				TOTALPRICEWT = TOTALPRICEWT + @TOTALPRICEWT,
				TOTALPRICEWOT = TOTALPRICEWOT + @TOTALPRICEWOT,
				APPLIEDDISCOUNT = APPLIEDDISCOUNT + @APPLIEDDISCOUNT,
				APPLIEDSCHEME = APPLIEDSCHEME + @APPLIEDSCHEME,
				APPLIEDDGST = APPLIEDDGST + @APPLIEDDGST,
				FINALPRICEWOTAX = FINALPRICEWOTAX + @FINALPRICEWOTAX,
				FINALPRICE = FINALPRICE + @FINALPRICE,
				CGST = CGST + @CGST,
				SGST = SGST + @SGST,
				IGST = IGST + @IGST,
				CESS = CESS + @CESS,
				UPDATEDBY = @USERID,
				UPDATEDATE = GETDATE(),
				ISFREEITEM = @ISFREEITEM
			WHERE STOCKENTRYDETAILID = @STOCKENTRYDETAILID

		END
		ELSE
		BEGIN
			INSERT INTO STOCKENTRYDETAIL
				(
					STOCKENTRYID,ITEMCODEID,CPWITHTAX,CPWITHOUTTAX,INVOICECPWITHTAX,INVOICECPWITHOUTTAX,
					MRP,SALEPRICE,GSTID,QUANTITY,WEIGHTINKGS,CREATEDBY,CREATEDDATE,DISCOUNTFLAT,DISCOUNTPERCENTAGE,
					SCHEMEPERCENTAGE,SCHEMEFLAT,TOTALPRICEWT,TOTALPRICEWOT,APPLIEDDISCOUNT,APPLIEDSCHEME,
					APPLIEDDGST,FINALPRICE, FINALPRICEWOTAX,CGST,SGST,IGST,CESS, ISFREEITEM
				)
			VALUES
				(
					@STOCKENTRYID,@ITEMCODEID,@COSTPRICEWT,@COSTPRICEWOT,@INVOICECPWITHTAX,@INVOICECPWITHOUTTAX,
					@MRP,@SALEPRICE,@GSTID,@QUANTITY,@WEIGHTINKGS,@USERID,GETDATE(),@DISCOUNTFLAT,@DISCOUNTPERCENTAGE,
					@SCHEMEPERCENTAGE,@SCHEMEFLAT,@TOTALPRICEWT,@TOTALPRICEWOT,@APPLIEDDISCOUNT,@APPLIEDSCHEME,@APPLIEDDGST,
					@FINALPRICE,@FINALPRICEWOTAX,@CGST,@SGST,@IGST,@CESS, @ISFREEITEM
				)
			SET @STOCKENTRYDETAILID = SCOPE_IDENTITY()
		END

	END

	SELECT 
		SE.STOCKENTRYID, SE.STOCKENTRYDETAILID,I.ITEMID,I.ISOPENITEM,IC.ITEMCODEID,
		I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,SE.CPWITHTAX,SE.CPWITHOUTTAX,SE.INVOICECPWITHTAX, SE.INVOICECPWITHOUTTAX,    
		SE.MRP,SE.SALEPRICE,SE.QUANTITY,SE.WEIGHTINKGS,
		SE.DISCOUNTFLAT, SE.DISCOUNTPERCENTAGE, SE.SCHEMEPERCENTAGE, SE.SCHEMEFLAT, 
		SE.TOTALPRICEWT, SE.TOTALPRICEWOT, SE.APPLIEDDISCOUNT, SE.APPLIEDSCHEME, 
		SE.GSTID, SE.APPLIEDDGST,SE.FINALPRICEWOTAX, SE.FINALPRICE,SE.CGST,
		SE.SGST,SE.IGST,SE.CESS,IC.HSNCODE, GST.GSTCODE,ISNULL(SE.ISFREEITEM,0) AS ISFREEITEM,
		SE.CREATEDDATE, CU.FULLNAME AS CREATEDBY
	FROM STOCKENTRYDETAIL SE
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = SE.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN GSTDETAIL GST ON SE.GSTID = GST.GSTID
		LEFT JOIN TBLUSER CU ON SE.CREATEDBY = CU.USERID
	WHERE STOCKENTRYDETAILID = @STOCKENTRYDETAILID 

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_STOCKSLIPPAGE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
