CREATE PROC [dbo].[USP_CU_STOCKSLIPPAGE]
(
	@ItemPriceID INT
	, @WeightInKGs DECIMAL(12, 2)
	, @Description VARCHAR(500)
	, @UserID INT
)
AS
BEGIN
	
	DECLARE @BulkWarehouseID INT = 45
	DECLARE @CurStock DECIMAL(9, 2)

	SELECT @CurStock = WEIGHTINKGS FROM STOCKSUMMARY WHERE BRANCHID = @BulkWarehouseID AND ITEMPRICEID = @ItemPriceID

	INSERT INTO STOCKADJUSTMENT(ITEMPRICEID, BRANCHID, WEIGHTINKGS, CREATEDBY, CREATEDDATE, PREVWEIGHTINKGS, DESCRIPTION, TTYPE, STOCKADJUSTMENTTYPEID)
	SELECT @ItemPriceID, @BulkWarehouseID, @CurStock - @WeightInKGs, @UserID, GETDATE(), @CurStock, @Description, 1, 4

	UPDATE SS
	SET WEIGHTINKGS = @CurStock - @WeightInKGs, TTYPE = 'PS', SS.MODIFIEDDATE = GETDATE()
	FROM STOCKSUMMARY SS
	WHERE SS.BRANCHID = @BulkWarehouseID AND SS.ITEMPRICEID = @ItemPriceID

END
GO
