CREATE PROCEDURE [dbo].[USP_CU_SUBCATEGORY]
@SUBCATEGORYID INT = 0,    
@CATEGORYID int,    
@SUBCATEGORYNAME varchar(100),    
@USERID int = 0        ,
@INSTANTDISPATCHENABLED BIT
AS    
BEGIN    
        
 IF @SUBCATEGORYID > 0         
 BEGIN        
  UPDATE SUBCATEGORY
  SET      
   CATEGORYID = @CATEGORYID,        
   SUBCATEGORYNAME = @SUBCATEGORYNAME,    
   INSTANTDISPATCHENABLED = @INSTANTDISPATCHENABLED,
   UPDATEDBY = @USERID,        
   UPDATEDDATE = GETDATE()        
  WHERE SUBCATEGORYID = @SUBCATEGORYID    
 END        
 ELSE        
 BEGIN        
  INSERT INTO SUBCATEGORY(CATEGORYID, SUBCATEGORYNAME,INSTANTDISPATCHENABLED,CREATEDBY,CREATEDDATE)        
  VALUES (@CATEGORYID,@SUBCATEGORYNAME,@INSTANTDISPATCHENABLED,@USERID, GETDATE())        
        
  SET @SUBCATEGORYID = SCOPE_IDENTITY()        
 END        
        
 SELECT @SUBCATEGORYID    
        
END
GO
