CREATE   PROCEDURE [dbo].[USP_CU_SUPPLIERINDENT]  
@SUPPLIERINDENTID INT = 0,  
@SUPPLIERID INT,  
@CATEGORYID INT,  
@INDENTDAYS INT = null,  
@SAFETYDAYS INT = null,  
@USERID INT,  
@MOBILENO VARCHAR(20) = NULL,
@dtDetail SUPPLIERINDENTDETAILTYPE readonly,  
@ISAPPROVED INT = 0 , 
@IndentType VARCHAR(20),
@BranchID INT = 45
AS  
BEGIN  

	--DECLARE @IndentTypeID INT

	--IF @ISAPPROVED = 2 -- Reject status
	--BEGIN

	--	UPDATE SUPPLIERINDENT   
	--	SET   
	--		APPROVEDBY = CASE WHEN @ISAPPROVED <> 0 THEN @USERID ELSE NULL END,  
	--		APPROVEDDATE = CASE WHEN @ISAPPROVED <> 0 THEN GETDATE() ELSE NULL END,
	--		STATUS = @ISAPPROVED,
	--		MOBILENO = @MOBILENO
	--	WHERE   
	--		SUPPLIERINDENTID = @SUPPLIERINDENTID  

	--	RETURN
	--END

	UPDATE SUPPLIERINDENT   
	SET   
		SUPPLIERID = @SUPPLIERID,  
		INDENTDAYS = @INDENTDAYS,  
		SAFETYDAYS = @SAFETYDAYS,  
		CATEGORYID = @CATEGORYID,  
		UPDATEDBY = CASE WHEN @ISAPPROVED = 0 THEN @USERID ELSE UPDATEDBY END,
		UPDATEDDATE = CASE WHEN @ISAPPROVED = 0 THEN GETDATE() ELSE UPDATEDDATE END,
		APPROVEDBY = CASE WHEN @ISAPPROVED <> 0 THEN @USERID ELSE NULL END,  
		APPROVEDDATE = CASE WHEN @ISAPPROVED <> 0 THEN GETDATE() ELSE NULL END,
		STATUS = @ISAPPROVED,
		MOBILENO = @MOBILENO
	WHERE   
		SUPPLIERINDENTID = @SUPPLIERINDENTID   

	UPDATE SID  
	SET   
		SID.DESIREDINDENT = USID.DESIREDINDENT,  
		SID.UPDATEDBY = CASE WHEN SID.DESIREDINDENT <> USID.DESIREDINDENT THEN @USERID ELSE SID.UPDATEDBY END,  
		SID.UPDATEDDATE = CASE WHEN SID.DESIREDINDENT <> USID.DESIREDINDENT THEN GETDATE() ELSE SID.UPDATEDDATE END
	FROM   
		SUPPLIERINDENTDETAIL SID  
		INNER JOIN @dtDetail USID ON SID.SUPPLIERINDENTDETAILID = USID.SUPPLIERINDENTDETAILID  


	/*
	
	DECLARE @FINYEAR INT, @FINYEARSTARTDATE DATE, @SUPPLIERINDENTNO VARCHAR(30)
	SELECT @FINYEAR = YEAR(GETDATE()) - CASE WHEN MONTH(GETDATE()) < 4 THEN 1 ELSE 0 END
	SELECT @FINYEARSTARTDATE = DATEFROMPARTS(@FINYEAR, 04, 01)

	IF @IndentType = 'Indent (Original)'
	BEGIN

		SELECT @IndentTypeID = ENUMID FROM ENUMLIST WHERE ENUMTYPE = 'Supplier Indent Type' AND ENUMVALUE = 'Indent (Original)'
		
		IF(@SUPPLIERINDENTID = 0)  
		BEGIN  
		
			SELECT @SUPPLIERINDENTNO = CAT.CATEGORYNAME + '-' + RIGHT(CAST(@FINYEAR AS VARCHAR(4)), 2) + '-' + RIGHT('000000' + CAST(COUNT(1) + 1 AS VARCHAR(10)), 7)
			FROM 
				TBLCATEGORY CAT
				LEFT JOIN SUPPLIERINDENT SI ON CAT.CATEGORYID = SI.CATEGORYID AND SI.CREATEDDATE > @FINYEARSTARTDATE
			WHERE 
				CAT.CATEGORYID = @CATEGORYID	
			GROUP BY CAT.CATEGORYNAME

			INSERT INTO SUPPLIERINDENT(SUPPLIERID, INDENTDAYS, SAFETYDAYS, CATEGORYID, CREATEDBY, CREATEDDATE, STATUS, SUPPLIERINDENTNO, MOBILENO, SUPPLIERINDENTTYPEID, BRANCHID)  
			SELECT @SUPPLIERID, @INDENTDAYS, @SAFETYDAYS, @CATEGORYID, @USERID, GETDATE(), 0, @SUPPLIERINDENTNO, CNUMBER, @IndentTypeID, 45
			FROM TBLUSER WHERE USERID = @USERID

			SET @SUPPLIERINDENTID = SCOPE_IDENTITY()  
  
		END  
		ELSE  
		BEGIN  
			UPDATE SUPPLIERINDENT   
			SET   
				SUPPLIERID = @SUPPLIERID,  
				INDENTDAYS = @INDENTDAYS,  
				SAFETYDAYS = @SAFETYDAYS,  
				CATEGORYID = @CATEGORYID,  
				UPDATEDBY = CASE WHEN @ISAPPROVED = 0 THEN @USERID ELSE UPDATEDBY END,
				UPDATEDDATE = CASE WHEN @ISAPPROVED = 0 THEN GETDATE() ELSE UPDATEDDATE END,
				APPROVEDBY = CASE WHEN @ISAPPROVED <> 0 THEN @USERID ELSE NULL END,  
				APPROVEDDATE = CASE WHEN @ISAPPROVED <> 0 THEN GETDATE() ELSE NULL END,
				STATUS = @ISAPPROVED,
				MOBILENO = @MOBILENO
			WHERE   
				SUPPLIERINDENTID = @SUPPLIERINDENTID   
		END  
  
		INSERT INTO SUPPLIERINDENTDETAIL(SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT, DESIREDINDENT, CREATEDBY, CREATEDDATE, MRP, COSTPRICEWT)  
		SELECT @SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT, DESIREDINDENT, @USERID, GETDATE(), MRP, COSTPRICEWT
		FROM @dtDetail USID  
		WHERE NOT EXISTS        
			(        
				SELECT 1 FROM SUPPLIERINDENTDETAIL SIDINNER WHERE SIDINNER.SUPPLIERINDENTDETAILID = USID.SUPPLIERINDENTDETAILID  
			)        
  
  
		UPDATE SID  
		SET   
			SID.DESIREDINDENT = USID.DESIREDINDENT,  
			SID.UPDATEDBY = @USERID,  
			SID.UPDATEDDATE = GETDATE()  
		FROM   
			SUPPLIERINDENTDETAIL SID  
			INNER JOIN @dtDetail USID ON SID.SUPPLIERINDENTDETAILID = USID.SUPPLIERINDENTDETAILID  

		RETURN

	END
  
	IF @IndentType = 'Indent By MBQ' OR @IndentType = 'DSD Indent by MBQ'
	BEGIN

		SELECT @IndentTypeID = ENUMID FROM ENUMLIST WHERE ENUMTYPE = 'Supplier Indent Type' AND ENUMVALUE = @IndentType
		DECLARE @RowCount INT 

		SELECT ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT, DESIREDINDENT, MRP, COSTPRICEWT, SUPPLIERINDENTDETAILID
		INTO #SID
		FROM @dtDetail USID  
		WHERE NOT EXISTS        
			(        
				SELECT 1 FROM SUPPLIERINDENTDETAIL SIDINNER WHERE SIDINNER.SUPPLIERINDENTDETAILID = ISNULL(USID.SUPPLIERINDENTDETAILID, 0)  
			)   

		SELECT @RowCount = COUNT(1) FROM #SID
		
		WHILE @RowCount > 0
		BEGIN

			SELECT @SUPPLIERINDENTNO = CAT.CATEGORYNAME + '-' + RIGHT(CAST(@FINYEAR AS VARCHAR(4)), 2) + '-' + RIGHT('000000' + CAST(COUNT(1) + 1 AS VARCHAR(10)), 7)
			FROM 
				TBLCATEGORY CAT
				LEFT JOIN SUPPLIERINDENT SI ON CAT.CATEGORYID = SI.CATEGORYID AND SI.CREATEDDATE > @FINYEARSTARTDATE
			WHERE 
				CAT.CATEGORYID = @CATEGORYID	
			GROUP BY CAT.CATEGORYNAME

			INSERT INTO SUPPLIERINDENT(SUPPLIERID, INDENTDAYS, SAFETYDAYS, CATEGORYID, CREATEDBY, CREATEDDATE, STATUS, SUPPLIERINDENTNO, MOBILENO, SUPPLIERINDENTTYPEID, BRANCHID)  
			SELECT @SUPPLIERID, @INDENTDAYS, @SAFETYDAYS, @CATEGORYID, @USERID, GETDATE(), 0, @SUPPLIERINDENTNO, CNUMBER, @IndentTypeID, @BranchID
			FROM TBLUSER WHERE USERID = @USERID

			SET @SUPPLIERINDENTID = SCOPE_IDENTITY()  

			INSERT INTO SUPPLIERINDENTDETAIL(SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT, DESIREDINDENT, CREATEDBY, CREATEDDATE, MRP, COSTPRICEWT)  
			SELECT TOP 20 @SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT, DESIREDINDENT, @USERID, GETDATE(), MRP, COSTPRICEWT
			FROM #SID

			DELETE TOP (20) FROM #SID
			
			SELECT @RowCount = COUNT(1) FROM #SID

		END

		UPDATE SID  
		SET   
			SID.DESIREDINDENT = USID.DESIREDINDENT,  
			SID.UPDATEDBY = @USERID,  
			SID.UPDATEDDATE = GETDATE()  
		FROM   
			SUPPLIERINDENTDETAIL SID  
			INNER JOIN @dtDetail USID ON SID.SUPPLIERINDENTDETAILID = USID.SUPPLIERINDENTDETAILID  


	END
	*/
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_SUPPLIERINDENTDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   proc [dbo].[USP_CU_SUPPLIERINDENTDETAIL]
(
	@ITEMPRICEID INT,
	@QUANTITY INT
	, @SUPPLIERINDENTID INT
	, @USERID INT
)
AS
BEGIN
	
	IF EXISTS ( SELECT 1 FROM SUPPLIERINDENT SI WHERE SI.SUPPLIERINDENTID = @SUPPLIERINDENTID AND SI.DELETEDDATE IS NOT NULL )
	BEGIN
		SELECT 'Supplier indent deleted, The operation cannot continue'
		RETURN
	END

	IF EXISTS ( SELECT 1 FROM SUPPLIERINDENT SI WHERE SI.SUPPLIERINDENTID = @SUPPLIERINDENTID AND SI.APPROVEDDATE IS NOT NULL )
	BEGIN
		SELECT 'Supplier indent has already approved, The operation cannot continue'
		RETURN
	END

	IF EXISTS 
		(
			SELECT 1 
			FROM 
				SUPPLIERINDENTDETAIL SID 
				INNER JOIN ITEMCODE IC ON IC.ITEMID = SID.ITEMID
				INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID AND IP.MRP = SID.MRP
			WHERE SID.SUPPLIERINDENTID = @SUPPLIERINDENTID 
				AND SID.DELETEDDATE IS NOT NULL 
				AND IP.ITEMPRICEID = @ITEMPRICEID
		)
	BEGIN
		SELECT 'Item already exists in supplier indent'
		RETURN
	END

	INSERT INTO SUPPLIERINDENTDETAIL(SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT, CREATEDBY, CREATEDDATE, DESIREDINDENT, MRP, COSTPRICEWT, ISMANUAL)
	SELECT @SUPPLIERINDENTID, IC.ITEMID, SS.QUANTITY, 0, 0, @USERID, GETDATE(), @QUANTITY, IP.MRP, ICP.COSTPRICEWT, 1
	FROM
		ITEMPRICE IP 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID AND SS.BRANCHID = 45
		LEFT JOIN 
			(
				SELECT MAX(ICPINNER.ITEMCOSTPRICEID) MAXITEMCOSTPRICEID, ICPINNER.ITEMPRICEID 
				FROM ITEMCOSTPRICE ICPINNER 
				WHERE ICPINNER.ITEMPRICEID = @ITEMPRICEID AND ICPINNER.DELETEDDATE IS NULL
				GROUP BY ICPINNER.ITEMPRICEID
			) MAXICP ON MAXICP.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = MAXICP.MAXITEMCOSTPRICEID
	WHERE IP.ITEMPRICEID = @ITEMPRICEID

	SELECT SCOPE_IDENTITY()

END
GO
