/****** Object:  StoredProcedure [dbo].[USP_CU_SUPPLIERRETURNSDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_SUPPLIERRETURNSDETAIL]
@SupplierReturnsDetailID INT = 0,
@SupplierReturnsID INT,        
@ItemCostPriceID INT,        
@Quantity DECIMAL(18,2),
@UserID int,
@ReasonID INT = 2
AS        
BEGIN        



	IF NOT EXISTS (SELECT 1 FROM SUPPLIERRETURNS WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID AND ISNULL(STATUS,0) = 0)
	BEGIN
		SELECT 'Cannot add item as sheet is already submitted.'
		return;
	END

	DECLARE @WHStock DECIMAL(18, 2), @IsOpenItem BIT, @ItemCodeID INT, @BRANCHID INT, @ITEMPRICEID INT

	SELECT @BRANCHID = BRANCHID FROM SUPPLIERRETURNS WHERE SUPPLIERRETURNSID = @SupplierReturnsID

	SELECT @IsOpenItem = I.ISOPENITEM, @ItemCodeID = IC.ITEMCODEID, @ITEMPRICEID = ICP.ITEMPRICEID
		FROM ITEMCOSTPRICE	ICP 
			INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		WHERE ICP.ITEMCOSTPRICEID = @ItemCostPriceID

	SELECT @WHStock = CASE WHEN @isOpenItem = 1 THEN SUM(WEIGHTINKGS) ELSE SUM(QUANTITY) END
		FROM STOCKSUMMARY SS  WHERE SS.BRANCHID = @BRANCHID AND SS.ITEMPRICEID = @ITEMPRICEID

			--SELECT @WHStock, @ItemCodeID, @IsOpenItem

	IF (@WHStock < @Quantity)
	BEGIN
		SELECT 'Selected branch stock is less than desired refund quantity'
		RETURN
	END
    
	IF(@SupplierReturnsDetailID > 0)        
	BEGIN        
		UPDATE SUPPLIERRETURNSDETAIL
		SET 
			WEIGHTINKGS = CASE WHEN @IsOpenItem = 1 THEN @QUANTITY ELSE WEIGHTINKGS END,
			QUANTITY    = CASE WHEN @IsOpenItem = 1 THEN QUANTITY ELSE @QUANTITY END,
			UPDATEDDATE = GETDATE(),
			ReasonID = @ReasonID
		WHERE SUPPLIERRETURNSDETAILID = @SupplierReturnsDetailID;
	END
	ELSE
	BEGIN

		SELECT @SupplierReturnsDetailID = SUPPLIERRETURNSDETAILID 
		FROM SUPPLIERRETURNSDETAIL
		WHERE SUPPLIERRETURNSID = @SupplierReturnsID 
			AND ITEMCOSTPRICEID = @ItemCostPriceID    
			AND REASONID = @ReasonID
			AND DELETEDDATE IS NULL

	IF(@SupplierReturnsDetailID > 0)    
	BEGIN    
    
		UPDATE SUPPLIERRETURNSDETAIL
		SET 
			WEIGHTINKGS = CASE WHEN @IsOpenItem = 1 THEN @QUANTITY ELSE WEIGHTINKGS END,
			QUANTITY    = CASE WHEN @IsOpenItem = 1 THEN QUANTITY ELSE @QUANTITY END,
			UPDATEDDATE = GETDATE(),
			ReasonID = @ReasonID
		WHERE SUPPLIERRETURNSDETAILID = @SupplierReturnsDetailID;
    
	end    
	else    
	begin    
		INSERT INTO SUPPLIERRETURNSDETAIL (SUPPLIERRETURNSID,ITEMCOSTPRICEID,QUANTITY,WEIGHTINKGS,CREATEDBY,CREATEDDATE, RETURNSTATUS, REASONID)
		SELECT @SupplierReturnsID,@ItemCostPriceID,
			CASE WHEN @IsOpenItem = 1 THEN 0 ELSE @QUANTITY END AS QUANTITY,
			CASE WHEN @IsOpenItem = 1 THEN @QUANTITY ELSE 0 END AS WEIGHTINKGS,
			@UserID,GETDATE(), 1, @ReasonID;

		SET @SupplierReturnsDetailID = SCOPE_IDENTITY()        
	end    
	END        
        
	SELECT @SupplierReturnsDetailID        
        
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_SUPPLIERSKUMAP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_SUPPLIERSKUMAP]
@SUPPLIERID INT,
@ITEMID INT,
@USERID INT
AS
BEGIN
	
	IF NOT EXISTS
	(
		SELECT 1 FROM ITEMSUPPLIERMAP ISM 
		WHERE ISM.SUPPLIERID = @SUPPLIERID 
			AND ISM.ITEMID = @ITEMID 
			AND ISM.DELETEDDATE IS NULL
	)
	BEGIN
		
		DECLARE @ITEMCOSTPRICEID INT = 0, @ITEMPRICEID INT, @ITEMCODEID INT, @LASTRECIEVEDDATE DATETIME
		
		SELECT TOP(1) 
			@ITEMCOSTPRICEID = ITEMCOSTPRICEID,
			@LASTRECIEVEDDATE = SED.CREATEDDATE
		FROM STOCKENTRYDETAIL SED 
			INNER JOIN STOCKENTRY SE ON SED.STOCKENTRYID = SE.STOCKENTRYID
		WHERE SE.SUPPLIERID = @SUPPLIERID 
			AND SE.DELETEDDATE IS NULL 
			AND SED.DELETEDDATE IS NULL
		ORDER BY STOCKENTRYDETAILID DESC

		IF(@ITEMCOSTPRICEID = 0)
		BEGIN
			SELECT 'Select item does not contain item prices under this supplier'
			RETURN;
		END

		SELECT @ITEMPRICEID = ITEMPRICEID FROM ITEMCOSTPRICE WHERE ITEMCOSTPRICEID = @ITEMCOSTPRICEID
		SELECT @ITEMCODEID = ITEMCODEID FROM ITEMPRICE WHERE ITEMPRICEID = @ITEMPRICEID

		INSERT INTO ITEMSUPPLIERMAP
		(
			SUPPLIERID, 
			ITEMID, 
			ITEMCODEID, 
			ITEMPRICEID, 
			ITEMCOSTPRICEID, 
			LASTRECEIVEDDATE, 
			CREATEDBY, 
			CREATEDDATE
		)
		VALUES 
		(
			@SUPPLIERID, 
			@ITEMID, 
			@ITEMCODEID, 
			@ITEMPRICEID, 
			@ITEMCOSTPRICEID, 
			@LASTRECIEVEDDATE, 
			@USERID, 
			GETDATE()
		)

		SELECT SCOPE_IDENTITY()

	END

END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_TRAYINFO]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_TRAYINFO]
@STOCKDISPATCHID INT,
@TRAYNUMBER INT,
@USERID INT
AS
BEGIN

	IF (@TRAYNUMBER = 0)
	BEGIN
		SELECT '0 not allowed as tray number'
		RETURN
	END

	DECLARE @BRANCHID INT, @CATEGORYID INT
	SELECT @BRANCHID = TOBRANCHID, @CATEGORYID = CATEGORYID FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	IF EXISTS
	(
		SELECT 1 FROM TRAYINFO TI WITH(NOLOCK)
			INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON TI.STOCKDISPATCHID = SD.STOCKDISPATCHID
		WHERE SD.TOBRANCHID = @BRANCHID 
			AND SD.CATEGORYID = @CATEGORYID
			AND SD.STATUS <> 2
			AND TRAYNUMBER = @TRAYNUMBER 
			AND SD.DELETEDDATE IS NULL
			AND TI.DELETEDDATE IS NULL

	)
	BEGIN
		SELECT 'Tray number already exists under another dispatch under same category, select same from drop down'
		RETURN
	END

	IF EXISTS
	(
		SELECT 1 FROM TRAYINFO TI WITH(NOLOCK)
			INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON TI.STOCKDISPATCHID = SD.STOCKDISPATCHID
		WHERE SD.TOBRANCHID = @BRANCHID 
			AND SD.STATUS <> 2
			AND TRAYNUMBER = @TRAYNUMBER 
			AND SD.DELETEDDATE IS NULL
			AND TI.DELETEDDATE IS NULL

	)
	BEGIN
		SELECT 'Tray number already exists under another dispatch under different category, select another tray number'
		RETURN
	END

	INSERT INTO TRAYINFO(STOCKDISPATCHID, TRAYNUMBER, ISACCEPTED, CREATEDBY, CREATEDATE)
	VALUES(@STOCKDISPATCHID, @TRAYNUMBER, 0, @USERID, GETDATE())
	
	SELECT SCOPE_IDENTITY() AS TRAYINFOID

END
GO
