CREATE PROCEDURE [dbo].[USP_CU_UOM]
@UOMID int = 0,    
@DISPLAYVALUE varchar(100),    
@BASEUOMID int,
@MULTIPLIER decimal(5,2),
@USERID int
AS    
BEGIN    
    
 IF @UOMID > 0     
 BEGIN    
  UPDATE UOM
  SET  
   DISPLAYVALUE = @DISPLAYVALUE,  
   BASEUOMID = @BASEUOMID,
   MULTIPLIER = @MULTIPLIER,
   UPDATEDBY = @USERID,  
   UPDATEDDATE = GETDATE()  
   WHERE UOMID = @UOMID 
 END    
 ELSE    
 BEGIN    
  INSERT INTO UOM(DISPLAYVALUE,BASEUOMID,MULTIPLIER,CREATEDBY, CREATEDDATE)    
  VALUES (@DISPLAYVALUE,@BASEUOMID,@MULTIPLIER,@USERID,GETDATE())    
    
  SET @UOMID = SCOPE_IDENTITY()    
 END    
    
 SELECT @UOMID    
    
END
GO
/****** Object:  StoredProcedure [dbo].[USP_CU_USER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_CU_USER]              
@USERID int = 0,              
@ROLEID int = 0,              
@REPORTINGLEADID int = 0,              
@CATEGORYID int = 0,              
@BRANCHID int = 0,              
@USERNAME varchar(50),              
@PASSWORDSTRING varchar(100),              
@FULLNAME varchar(50),              
@EMAIL varchar(50),              
@CNUMBER VARCHAR(50),          
@GENDER INT,              
@DOB DATE = NULL,              
@CUSERID int = 0,
@SUBCATEGORYID INT = 0
AS              
BEGIN              
              
	IF @USERID > 0               
	BEGIN              

		DECLARE @OldRoleID INT
		SELECT @OldRoleID = ROLEID FROM TBLUSER WHERE USERID = @USERID

		UPDATE TBLUSER               
		SET            
			ROLEID = @ROLEID,          
			REPORTINGLEADID = @REPORTINGLEADID,          
			CATEGORYID = @CATEGORYID,          
			BRANCHID = @BRANCHID,          
			FULLNAME = @FULLNAME,              
			CNUMBER = @CNUMBER,              
			EMAIL = @EMAIL,              
			GENDER = @GENDER,              
			DOB = @DOB,          
			UPDATEDBY = @CUSERID,              
			UPDATEDDATE = GETDATE(), 
			USERNAME = @USERNAME,
			SUBCATEGORYID = @SUBCATEGORYID
		WHERE USERID = @USERID      
		

		IF @OldRoleID <> @ROLEID
		BEGIN

			UPDATE HA
			SET DELETEDBY = @CUSERID, DELETEDDATE = GETDATE()
			FROM HASACCESS HA
			WHERE HA.USERID = @USERID AND HA.DELETEDDATE IS NULL

			INSERT INTO HASACCESS(USERID, WORKFLOWACTIONID, CREATEDBY, CREATEDDATE)
			SELECT @USERID, HA.WORKFLOWACTIONID, @CUSERID, GETDATE()
			FROM HASACCESS HA
			WHERE HA.ROLEID = @ROLEID AND HA.DELETEDDATE IS NULL

		END

	END              
	ELSE              
	BEGIN           
 
		IF EXISTS (SELECT 1 FROM TBLUSER WHERE USERNAME = @USERNAME AND DELETEDDATE IS NULL)
		BEGIN
			THROW 51000, 'Username has to be unique', 1;
		END
          
		INSERT INTO TBLUSER(ROLEID, REPORTINGLEADID, CATEGORYID,BRANCHID, USERNAME, PASSWORDSTRING, 
							FULLNAME, CNUMBER, EMAIL, ISOTP, GENDER, DOB, CREATEDBY, CREATEDDATE, SUBCATEGORYID)              
		VALUES (@ROLEID, @REPORTINGLEADID, @CATEGORYID, @BRANCHID, @USERNAME, @PASSWORDSTRING, 
							@FULLNAME, @CNUMBER, @EMAIL, 1, @GENDER, @DOB, @CUSERID, GETDATE(), @SUBCATEGORYID)              
              
		SET @USERID = SCOPE_IDENTITY()             
		
		INSERT INTO HASACCESS(USERID, WORKFLOWACTIONID, CREATEDBY, CREATEDDATE)
		SELECT @USERID, HA.WORKFLOWACTIONID, @CUSERID, GETDATE()
		FROM HASACCESS HA
		WHERE HA.ROLEID = @ROLEID AND HA.DELETEDDATE IS NULL
	END              
              
	SELECT @USERID          
              
END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_ADDBULKPROCESSINGDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_D_ADDBULKPROCESSINGDETAIL]
(
	@ADDBULKPROCESSINGDETAILID INT
	, @ADDBULKPROCESSINGID INT
)
AS
BEGIN


	IF ISNULL(@ADDBULKPROCESSINGID, 0) <= 0
	BEGIN
		SELECT @ADDBULKPROCESSINGID = ADDBULKPROCESSINGID FROM ADDBULKPROCESSINGDETAIL WHERE ADDBULKPROCESSINGDETAILID = @ADDBULKPROCESSINGDETAILID
	END

	IF EXISTS ( SELECT 1 FROM ADDBULKPROCESSING WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID AND STATUS = 1 )
	BEGIN
		SELECT 'Bulk processing is already submitted, Operation has been cancelled!!'
		RETURN
	END

	IF EXISTS ( SELECT 1 FROM ADDBULKPROCESSING WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID AND DELETEDDATE IS NOT NULL )
	BEGIN
		SELECT 'Bulk processing is already deleted, Operation has been cancelled!!'
		RETURN
	END


	UPDATE ADDBULKPROCESSINGDETAIL
	SET DELETEDDATE = GETDATE()
	WHERE ADDBULKPROCESSINGDETAILID = @ADDBULKPROCESSINGDETAILID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_BASEOFFER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_BASEOFFER]
@BASEOFFERID INT,
@USERID INT
AS
BEGIN
	
	BEGIN TRY
		BEGIN TRAN
			UPDATE OFB
			SET 
				DELETEDBY = @USERID, 
				DELETEDDATE = GETDATE() 
			FROM OFFERBRANCH OFB
				INNER JOIN OFFER OFR ON OFB.OFFERID = OFR.OFFERID
			WHERE BASEOFFERID = @BASEOFFERID
				AND OFB.DELETEDDATE IS NULL

			UPDATE OFIM
			SET 
				DELETEDBY = @USERID, 
				DELETEDDATE = GETDATE()
			FROM OFFERITEMMAP OFIM
				INNER JOIN OFFER OFR ON OFIM.OFFERID = OFR.OFFERID
			WHERE BASEOFFERID = @BASEOFFERID
				AND OFIM.DELETEDDATE IS NULL

			UPDATE OFFER
			SET
				DELETEDBY = @USERID,
				DELETEDDATE = GETDATE()
			WHERE BASEOFFERID = @BASEOFFERID
				AND DELETEDDATE IS NULL

			UPDATE BASEOFFERBRANCH
			SET 
				DELETEDBY = @USERID,
				DELETEDDATE = GETDATE()
			WHERE BASEOFFERID = @BASEOFFERID
				AND DELETEDDATE IS NULL

			UPDATE BASEOFFER
			SET
				DELETEDBY = @USERID,
				DELETEDDATE = GETDATE()
			WHERE BASEOFFERID = @BASEOFFERID

		COMMIT TRAN                                          
	END TRY                                          
	BEGIN CATCH                                          
		SELECT ERROR_MESSAGE() AS ErrorMessage                                           
		IF(@@TRANCOUNT > 0)                                          
		ROLLBACK TRAN                                          
	END CATCH                             

	SELECT @BASEOFFERID
END
GO
