/****** Object:  StoredProcedure [dbo].[USP_D_BRANCHCOUNTER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_BRANCHCOUNTER]
    @COUNTERID int = 0,
    @USERID int
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET ANSI_PADDING ON;
    SET ANSI_WARNINGS ON;
    SET ARITHABORT ON;
    SET CONCAT_NULL_YIELDS_NULL ON;
    SET NUMERIC_ROUNDABORT OFF;
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @Now datetime = GETDATE();
        UPDATE dbo.BRANCHCOUNTER
        SET DELETEDBY = @USERID, DELETEDDATE = @Now
        WHERE COUNTERID = @COUNTERID AND DELETEDDATE IS NULL;

        UPDATE dbo.BRANCHCOUNTERMOP
        SET DELETEDBY = @USERID, DELETEDDATE = @Now, UPDATEDBY = @USERID, UPDATEDDATE = @Now
        WHERE COUNTERID = @COUNTERID AND DELETEDDATE IS NULL;
        COMMIT TRANSACTION;
        SELECT @COUNTERID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END
GO
