/****** Object:  StoredProcedure [dbo].[usp_D_CreditNote]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_D_CreditNote]
(
    @CreditNoteId INT,
    @UserId       INT
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Check whether this Credit Note is mapped to any active Supplier Return
    IF EXISTS
    (
        SELECT 1
        FROM SUPPLIERRETURNSCREDITNOTEMAP SRCNM
        INNER JOIN SUPPLIERRETURNS SR
            ON SR.SUPPLIERRETURNSID = SRCNM.SUPPLIERRETURNSID
           AND SR.DELETEDDATE IS NULL
        WHERE SRCNM.CREDITNOTEID = @CreditNoteId
          AND SRCNM.DELETEDDATE IS NULL
    )
    BEGIN
        RAISERROR
        (
            'Cannot delete Credit Note: Supplier Returns exist for this Credit Note.',
            16,
            1
        );
        RETURN;
    END

    UPDATE CreditNote
    SET
        DeletedBy   = @UserId,
        DeletedDate = GETDATE()
    WHERE CreditNoteId = @CreditNoteId
      AND DeletedDate IS NULL;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_CREDITNOTEMAP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_CREDITNOTEMAP]
(
    @MAPID INT,
    @MAPTYPE VARCHAR(10), -- 'SR' or 'SE'
    @UserID INT
)
AS
BEGIN
    SET NOCOUNT ON;

    -- ===============================
    -- SUPPLIER RETURNS CREDIT NOTE
    -- ===============================
    IF (@MAPTYPE = 'SR')
    BEGIN
        IF NOT EXISTS (
            SELECT 1
            FROM SUPPLIERRETURNSCREDITNOTEMAP
            WHERE SUPPLIERRETURNSCREDITNOTEMAPID = @MAPID
              AND DeletedDate IS NULL
        )
        BEGIN
            RAISERROR ('No active Supplier Return Credit Note mapping found.', 16, 1);
            RETURN;
        END

        UPDATE SUPPLIERRETURNSCREDITNOTEMAP
        SET
            DeletedBy = @UserID,
            DeletedDate = GETDATE()
        WHERE SUPPLIERRETURNSCREDITNOTEMAPID = @MAPID
          AND DeletedDate IS NULL;

        RETURN;
    END

    -- ===============================
    -- STOCK ENTRY CREDIT NOTE
    -- ===============================
    IF (@MAPTYPE = 'SE')
    BEGIN
        IF NOT EXISTS (
            SELECT 1
            FROM STOCKENTRYCREDITNOTEMAP
            WHERE STOCKENTRYCREDITNOTEMAPID = @MAPID
              AND DeletedDate IS NULL
        )
        BEGIN
            RAISERROR ('No active Stock Entry Credit Note mapping found.', 16, 1);
            RETURN;
        END

        UPDATE STOCKENTRYCREDITNOTEMAP
        SET
            DeletedBy = @UserID,
            DeletedDate = GETDATE()
        WHERE STOCKENTRYCREDITNOTEMAPID = @MAPID
          AND DeletedDate IS NULL;

        RETURN;
    END

    -- ===============================
    -- INVALID MAP TYPE
    -- ===============================
    RAISERROR ('Invalid MAPTYPE. Allowed values: SR, SE.', 16, 1);

END;
GO
