/****** Object:  StoredProcedure [dbo].[USP_D_DISCARDSTOCKENTRY_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_DISCARDSTOCKENTRY_v2]
@STOCKENTRYID INT = 0
, @UserID INT = 0
AS
BEGIN
	
	IF EXISTS
	(
		SELECT 1 
		FROM STOCKENTRY SE
		WHERE ISNULL(SE.STATUS, 0) = 1 AND SE.STOCKENTRYID = @STOCKENTRYID
	)
	BEGIN
		RAISERROR ('Invoice already completed', 16, 1)
		RETURN
	END

	DECLARE @PROCCESSTIME DATETIME = GETDATE()

	UPDATE SED
	SET SED.DELETEDDATE = @PROCCESSTIME, SED.DELETEDBY = @UserID
	FROM STOCKENTRYDETAIL SED 
	WHERE 
		STOCKENTRYID = @STOCKENTRYID
		AND SED.DELETEDDATE IS NULL

	UPDATE SE
	SET 
		SE.DELETEDDATE = @PROCCESSTIME, 
		SE.DELETEDBY = @UserID
	FROM STOCKENTRY SE
	WHERE STOCKENTRYID = @STOCKENTRYID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_DISCARDSUPPLIERRETURNS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_DISCARDSUPPLIERRETURNS]
@SUPPLIERRETURNSID INT,
@USERID INT
AS
BEGIN

	IF NOT EXISTS (SELECT 1 FROM SUPPLIERRETURNS WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID AND (ISNULL(STATUS,0) = 0  OR ISNULL(STATUS,0) = 1))
	BEGIN
		SELECT 'Cannot discard return sheet which not a draft or open'
		return;
	END

	DECLARE @BRANCHID INT, @SHEETSTATUS INT
	SELECT @BRANCHID = BRANCHID, @SHEETSTATUS = ISNULL(STATUS,0) FROM SUPPLIERRETURNS WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID

	IF(@SHEETSTATUS = 1)
	BEGIN
		UPDATE SS        
			SET 
				SS.QUANTITY = ISNULL(SS.QUANTITY, 0) + SDD.QUANTITY,        
				SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS, 0) + SDD.WEIGHTINKGS,
				SS.TTYPE = 'SR', SS.MODIFIEDDATE = GETDATE()
			FROM 
				STOCKSUMMARY SS        
				INNER JOIN          
					(
						SELECT           
							ICP.ITEMPRICEID, SUM(SRD.QUANTITY) AS QUANTITY, SUM(SRD.WEIGHTINKGS) AS WEIGHTINKGS
						FROM
							SUPPLIERRETURNSDETAIL SRD
							INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
						WHERE 
							SRD.SUPPLIERRETURNSID = @SupplierReturnsID 
							AND SRD.DELETEDDATE IS NULL
						GROUP BY ICP.ITEMPRICEID
					) SDD ON SS.ITEMPRICEID = SDD.ITEMPRICEID
			WHERE SS.BRANCHID = @BRANCHID
	END

	UPDATE SUPPLIERRETURNSDETAIL 
	SET 
		DELETEDBY = @USERID, 
		DELETEDDATE = GETDATE() 
	WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID

	UPDATE SUPPLIERRETURNS 
	SET 
		DELETEDBY = @USERID, 
		DELETEDDATE = GETDATE() 
	WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID

	select @SUPPLIERRETURNSID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_DISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_DISPATCH]    
@StockDispatchID int,  
@UserID int = 4
AS    
BEGIN    
    
	IF NOT EXISTS
	(
		SELECT 1 FROM STOCKDISPATCH SD 			
		WHERE ISNULL(SD.STATUS, 0) = 0 AND SD.STOCKDISPATCHID = @STOCKDISPATCHID
	)
	BEGIN
		RAISERROR('Dispatch already completed', 16, 1)
		RETURN
	END

	DECLARE @DELETEDDATE DATETIME = GETDATE()

	UPDATE STOCKDISPATCHDETAIL SET DELETEDDATE = @DELETEDDATE WHERE STOCKDISPATCHID = @StockDispatchID  AND DELETEDDATE IS NULL  
	UPDATE STOCKDISPATCH SET DELETEDBY = @UserID, DELETEDDATE = @DELETEDDATE WHERE STOCKDISPATCHID = @StockDispatchID    

	IF EXISTS
	(
		SELECT 1 FROM TRAYINFO TI 
			INNER JOIN STOCKDISPATCHDETAIL SDD ON TI.STOCKDISPATCHID = SDD.STOCKDISPATCHID 
		WHERE SDD.DELETEDDATE IS NULL AND TI.STOCKDISPATCHID = @StockDispatchID
	)
	BEGIN
		RAISERROR('Cannot delete dispatch: stock still exists in tray numbers linked to the selected dispatch.', 16, 1)
		RETURN
	END

	UPDATE TRAYINFO SET DELETEDDATE = @DELETEDDATE, DELETEDBY = @UserID WHERE STOCKDISPATCHID = @StockDispatchID AND DELETEDDATE IS NULL
    
END
GO
