/****** Object:  StoredProcedure [dbo].[USP_D_ITEMCLASSIFICATION]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_D_ITEMCLASSIFICATION]
(
	@ItemClassificationID INT
	, @UserID INT
)
AS
BEGIN

	DECLARE @Count INT
	SELECT @Count = COUNT(1) FROM ITEM I WHERE I.CLASSIFICATIONID = @ItemClassificationID AND I.DELETEDDATE IS NULL

	IF @Count > 0 
	BEGIN
		SELECT 'Cannot delete "' + ICLS.CLASSIFICATIONNAME + '" as it is in use for ' + LTRIM(STR(@Count)) + ' item(s)'
		FROM ITEMCLASSIFICATION ICLS WHERE ICLS.CLASSIFICATIONID = @ItemClassificationID		
		RETURN
	END

	IF EXISTS (SELECT 1 FROM ITEMCLASSIFICATION ICLS WHERE ICLS.CLASSIFICATIONID = @ItemClassificationID AND DELETEDDATE IS NOT NULL)
	BEGIN
		SELECT 'Cannot delete "' + ICLS.CLASSIFICATIONNAME + '" as it is already deleted'
		FROM ITEMCLASSIFICATION ICLS WHERE ICLS.CLASSIFICATIONID = @ItemClassificationID	
		RETURN
	END

	UPDATE ITEMCLASSIFICATION 
	SET DELETEDBY = @UserID, DELETEDDATE = GETDATE()
	WHERE CLASSIFICATIONID = @ItemClassificationID

	SELECT @ItemClassificationID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_ITEMCODE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_D_ITEMCODE]
(
	@ITEMCODEID INT
	, @USERID INT
	, @isDelete BIT
)
AS
BEGIN
	
	IF @isDelete = 1
	BEGIN
		IF EXISTS
		(
			SELECT 1 FROM STOCKSUMMARY SS 
				INNER JOIN ITEMPRICE IP ON SS.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN BRANCH B ON B.BRANCHID = SS.BRANCHID
			WHERE 
				IP.ITEMCODEID = @ITEMCODEID 
				AND B.DELETEDDATE IS NULL
				AND ((CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) <> 0)
		)
		BEGIN
			SELECT 'Stock exists under selected itemcode , please move the stock another item and try again!'
			RETURN;
		END

		UPDATE ITEMPRICE 
		SET DELETEDBY = @USERID,
			DELETEDDATE = GETDATE()
		WHERE ITEMCODEID = @ITEMCODEID AND DELETEDDATE IS NULL

		UPDATE IC
		SET
			IC.DELETEDBY = @USERID
			, IC.DELETEDDATE = GETDATE()
		FROM ITEMCODE IC
		WHERE IC.ITEMCODEID = @ITEMCODEID AND IC.DELETEDBY IS NULL
	END
	ELSE
	BEGIN
		UPDATE IC
		SET
			IC.DELETEDBY = NULL
			, IC.DELETEDDATE = NULL
			, IC.UPDATEDBY = @USERID
			, IC.UPDATEDATE = GETDATE()
		FROM ITEMCODE IC
		WHERE IC.ITEMCODEID = @ITEMCODEID AND IC.DELETEDBY IS NOT NULL
	END

END
