/****** Object:  StoredProcedure [dbo].[USP_D_ITEMPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_ITEMPRICE]
@ITEMPRICEID INT,
@USERID INT,
@DeleteChildPrices BIT = 0
AS
BEGIN

	IF EXISTS 
		(
			SELECT 1 
			FROM ITEMPRICE IP 
			WHERE IP.ITEMPRICEID = @ITEMPRICEID AND IP.DELETEDDATE IS NOT NULL
		)
	BEGIN
		SELECT 'Item price already deleted, the operation is canceled!!'
		RETURN
	END

	IF EXISTS 
		(
			SELECT 1 
			FROM
				STOCKSUMMARY SS 
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN BRANCH B ON B.BRANCHID = SS.BRANCHID
			WHERE 
				B.DELETEDDATE IS NULL
				AND SS.ITEMPRICEID = @ITEMPRICEID 
				AND CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END <> 0
		)
	BEGIN
		
		SELECT 'Item price has stock in branches\warehouse, please check stock summary report'
		RETURN
		
	END

	UPDATE ITEMPRICE 
	SET 
		DELETEDBY = @USERID,
		DELETEDDATE = GETDATE()
	WHERE ITEMPRICEID = @ITEMPRICEID

	UPDATE ITEMPRICE 
	SET 
		DELETEDBY = @USERID,
		DELETEDDATE = GETDATE()
	WHERE PARENTITEMPRICEID = @ITEMPRICEID

	UPDATE SM
	SET SM.DELETEDBY = @USERID, SM.DELETEDDATE = GETDATE()
	FROM STOCKMOVE SM
	WHERE
		SM.MOVESTATUS = 0
		AND (SM.OLDITEMPRICEID = @ITEMPRICEID OR SM.NEWITEMPRICEID = @ITEMPRICEID)

	SELECT @ITEMPRICEID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_ITEMSUBCLASSIFICATION]    Script Date: 17-10-2026 13:04:47 ******/
