CREATE   PROC [dbo].[USP_D_ITEMSUBCLASSIFICATION]
(
	@ItemSubClassificationID INT
	, @UserID INT
)
AS
BEGIN

	DECLARE @Count INT
	SELECT @Count = COUNT(1) FROM ITEM I WHERE I.SUBCLASSIFICATIONID = @ItemSubClassificationID AND I.DELETEDDATE IS NULL

	IF @Count > 0 
	BEGIN
		SELECT 'Cannot delete "' + ICLS.SUBCLASSIFICATIONNAME + '" as it is in use for ' + LTRIM(STR(@Count)) + ' item(s)'
		FROM ITEMSUBCLASSIFICATION ICLS WHERE ICLS.SUBCLASSIFICATIONID = @ItemSubClassificationID		
		RETURN
	END

	IF EXISTS (SELECT 1 FROM ITEMSUBCLASSIFICATION ICLS WHERE ICLS.SUBCLASSIFICATIONID = @ItemSubClassificationID AND DELETEDDATE IS NOT NULL)
	BEGIN
		SELECT 'Cannot delete "' + ICLS.SUBCLASSIFICATIONNAME + '" as it is already deleted'
		FROM ITEMSUBCLASSIFICATION ICLS WHERE ICLS.SUBCLASSIFICATIONID = @ItemSubClassificationID	
		RETURN
	END

	UPDATE ITEMSUBCLASSIFICATION 
	SET DELETEDBY = @UserID, DELETEDDATE = GETDATE()
	WHERE SUBCLASSIFICATIONID = @ItemSubClassificationID

	SELECT @ItemSubClassificationID

END
GO
