/****** Object:  StoredProcedure [dbo].[USP_D_MOP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_MOP]
    @MOPID int = 0,
    @USERID int
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        DECLARE @DeletedDate datetime = GETDATE();
        UPDATE dbo.TBLMOP
        SET DELETEDBY = @USERID, DELETEDDATE = @DeletedDate
        WHERE MOPID = @MOPID AND DELETEDDATE IS NULL;

        UPDATE dbo.BRANCHCOUNTERMOP
        SET DELETEDBY = @USERID, DELETEDDATE = @DeletedDate,
            UPDATEDBY = @USERID, UPDATEDDATE = @DeletedDate
        WHERE MOPID = @MOPID AND DELETEDDATE IS NULL;
        COMMIT TRANSACTION;
        SELECT @MOPID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END
GO
