CREATE PROCEDURE [dbo].[USP_D_OFFERBRANCH]
@OfferBranchID INT,
@UserID INT,
@IsBaseOffer BIT = 0
AS
BEGIN

	IF @IsBaseOffer = 0
	BEGIN
		UPDATE OFFERBRANCH 
		SET 
			DELETEDBY = @UserID,
			DELETEDDATE = GETDATE()
		WHERE OFFERBRANCHID = @OfferBranchID
	END
	ELSE
	BEGIN

		DECLARE @BASEOFFERID INT, @BRANCHID INT
		SELECT @BASEOFFERID = BASEOFFERID, @BRANCHID = BRANCHID  FROM BASEOFFERBRANCH 
		WHERE BASEOFFERBRANCHID = @OfferBranchID

		UPDATE BASEOFFERBRANCH 
		SET
			DELETEDBY = @USERID,
			DELETEDDATE = GETDATE()
		WHERE 
			BASEOFFERBRANCHID = @OfferBranchID

		
		UPDATE OFB 
		SET 
			OFB.DELETEDBY = @UserID,
			OFB.DELETEDDATE = GETDATE()
		FROM OFFERBRANCH OFB
			INNER JOIN OFFER OFR ON OFB.OFFERID = OFR.OFFERID
		WHERE OFR.BASEOFFERID = @BASEOFFERID
			AND OFB.BRANCHID = @BRANCHID
			AND OFB.DELETEDDATE IS NULL

	END

END
