CREATE   PROC [dbo].[USP_D_PICKLIST_ITEMDATA]
(
	@PickListItemDetailID INT,
	@UserID INT
)
AS
BEGIN

	DECLARE @PickListID INT, @PickListItemID INT, @PickListStatus INT
		, @ItemDetailQuantity DECIMAL(18, 2), @PicklistTrayID INT

	SELECT 
		@PickListID = PL.PICKLISTID
		, @PickListStatus = PL.PICKEDSTATUS
		, @PickListItemID = PLI.PICKLISTITEMID
		, @ItemDetailQuantity = PLID.QUANTITY
		, @PicklistTrayID = PLID.PICKLISTTRAYID
	FROM
		PICKLISTITEMDETAIL PLID
		INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTITEMID = PLID.PICKLISTITEMID
		INNER JOIN PICKLIST PL ON PL.PICKLISTID = PLI.PICKLISTID
	WHERE
		PLID.PICKLISTITEMDETAILID = @PickListItemDetailID

	IF @PickListStatus <> 0
	BEGIN
		
		THROW 50001, 'Picklist already submitted, changes cannot be made', 1;
		RETURN

	END

	UPDATE PICKLISTITEM
	SET 
		PICKEDQUANTITY = PICKEDQUANTITY - @ItemDetailQuantity
		, UPDATEDBY = @UserID, UPDATEDDATE = GETDATE()
	WHERE PICKLISTITEMID = @PickListItemID

	UPDATE PICKLISTITEMDETAIL
	SET DELETEDBY = @UserID, DELETEDDATE = GETDATE()
	WHERE PICKLISTITEMDETAILID = @PickListItemDetailID

	UPDATE PLT
	SET PLT.DELETEDBY = @UserID, PLT.DELETEDDATE = GETDATE()
	FROM PICKLISTTRAY PLT
	WHERE 
		PLT.PICKLISTTRAYID = @PicklistTrayID
		AND NOT EXISTS 
		(
			SELECT 1
			FROM PICKLISTITEMDETAIL PLID
			WHERE 
				PLID.PICKLISTTRAYID = @PicklistTrayID
				AND PLID.DELETEDDATE IS NULL	
		)

END
GO
