CREATE   PROC [dbo].[USP_D_PICKLIST_TRAY]
(
	@PickListTrayID INT,
	@UserID INT
)
AS
BEGIN

	DECLARE @PickListID INT, @PickListStatus INT

	SELECT 
		@PickListID = PL.PICKLISTID
		, @PickListStatus = PL.PICKEDSTATUS
	FROM
		PICKLISTTRAY PLT
		INNER JOIN PICKLIST PL ON PL.PICKLISTID = PLT.PICKLISTID
	WHERE
		PLT.PICKLISTTRAYID = @PickListTrayID

	IF @PickListStatus <> 0
	BEGIN
		
		THROW 50001, 'Picklist already submitted, changes cannot be made', 1;
		RETURN

	END

	IF EXISTS 
		(
			SELECT 1 
			FROM PICKLISTITEMDETAIL PLID
			WHERE 
				PLID.DELETEDDATE IS NULL
				AND PLID.PICKLISTTRAYID = @PickListTrayID
		)
	BEGIN
		
		THROW 50001, 'Items exists in the given tray, cannot be deleted', 1;
		RETURN

	END

	UPDATE PICKLISTTRAY
	SET DELETEDBY = @UserID, DELETEDDATE = GETDATE()
	WHERE PICKLISTTRAYID = @PickListTrayID

END
