/****** Object:  StoredProcedure [dbo].[USP_D_REVERTSTOCKDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_REVERTSTOCKDISPATCH]
@STOCKDISPATCHID INT = 0,
@UserID INT = 0
AS
BEGIN
	
	IF NOT EXISTS
	(
		SELECT 1 
		FROM STOCKDISPATCH SD
		WHERE SD.STOCKDISPATCHID = @STOCKDISPATCHID 
			AND ISNULL(SD.STATUS, 0) = 1
			AND SD.DELETEDDATE IS NULL
			AND SD.Reverted_Date IS NULL
	)
	BEGIN
		RAISERROR ('Only submitted dispatch can be reverted', 16, 1)
		RETURN
	END

	DECLARE @TOBRANCHID INT, @FROMBRANCHID INT
	SELECT @FROMBRANCHID = FROMBRANCHID, @TOBRANCHID = STOCKDISPATCHID FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	DECLARE @currentdate DATETIME = GETDATE()

	SELECT         
		ISNULL(IP.STOCKMOVETOID, SDD.ITEMPRICEID) ITEMPRICEID,
		SDD.DISPATCHQUANTITY, 
		SDD.WEIGHTINKGS
	INTO #DISPATCHES
	FROM         
		STOCKDISPATCHDETAIL SDD
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
	WHERE SDD.STOCKDISPATCHID = @STOCKDISPATCHID
		AND	SDD.DELETEDDATE IS NULL
        
	--updating warehosue stock        
	UPDATE SS  
	SET 
		SS.QUANTITY = ISNULL(SS.QUANTITY,0) + SDD.QUANTITY,        
		SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS,0) + SDD.WEIGHTINKGS      ,  
		SS.TTYPE = 'SDR', SS.MODIFIEDDATE = @currentdate
	FROM STOCKSUMMARY SS        
		INNER JOIN          
		(  
			SELECT SDD.ITEMPRICEID,  
				SUM(DISPATCHQUANTITY) AS QUANTITY,  
				SUM(WEIGHTINKGS) AS WEIGHTINKGS      
			FROM #DISPATCHES SDD
			GROUP BY SDD.ITEMPRICEID
		)SDD ON SS.ITEMPRICEID = SDD.ITEMPRICEID  
	WHERE SS.BRANCHID = @FROMBRANCHID  


	UPDATE SDD
	SET 
		SDD.DELETEDDATE = @currentdate, 
		SDD.Reverted_Date = @currentdate
	FROM STOCKDISPATCHDETAIL SDD 
	WHERE 
		SDD.STOCKDISPATCHID = @STOCKDISPATCHID
		AND SDD.DELETEDDATE IS NULL

	UPDATE SD
	SET 
		SD.DELETEDDATE = @currentdate, 
		SD.DELETEDBY = @UserID,
		SD.Reverted_By = @UserID, 
		SD.Reverted_Date = @currentdate
	FROM STOCKDISPATCH SD
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	SELECT @STOCKDISPATCHID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_REVERTSTOCKENTRY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_REVERTSTOCKENTRY]
@STOCKENTRYID INT = 0,
@UserID INT = 0
AS
BEGIN
	
	IF EXISTS
	(
		SELECT 1 
		FROM STOCKENTRY SE
		WHERE ISNULL(SE.STATUS, 0) = 0 AND SE.STOCKENTRYID = @STOCKENTRYID
	)
	BEGIN
		RAISERROR ('Draft invoice cannot be reverted', 16, 1)
		RETURN
	END

	declare @currentdate datetime = getdate(), @RECEIVINGBRANCHID INT
	
	SELECT @RECEIVINGBRANCHID = RECEIVINGBRANCHID FROM STOCKENTRY WHERE STOCKENTRYID = @STOCKENTRYID

	UPDATE SS    
	SET SS.QUANTITY = CASE WHEN SED.ISOPENITEM = 0 THEN SS.QUANTITY - SED.QUANTITY ELSE SS.QUANTITY END,
		SS.WEIGHTINKGS = CASE WHEN SED.ISOPENITEM = 1 THEN SS.WEIGHTINKGS - SED.WEIGHTINKGS ELSE SS.WEIGHTINKGS END,
		SS.TTYPE = 'SER', SS.MODIFIEDDATE = @currentdate  
	FROM 
		STOCKSUMMARY SS 
		INNER JOIN 
		(
			SELECT 
				ICP.ITEMPRICEID, I.ISOPENITEM
				, SUM(SED.QUANTITY + ISNULL(SED.FREEQUANTITY,0)) AS QUANTITY
				, SUM(SED.WEIGHTINKGS) AS WEIGHTINKGS     
			FROM STOCKENTRYDETAIL SED      
				INNER JOIN ITEMCOSTPRICE ICP ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID    
				INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
				INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
			WHERE STOCKENTRYID = @STOCKENTRYID 
				AND SED.DELETEDDATE IS NULL 
			GROUP BY ICP.ITEMPRICEID, I.ISOPENITEM
		) SED ON SS.ITEMPRICEID = SED.ITEMPRICEID
	WHERE SS.BRANCHID = @RECEIVINGBRANCHID

	UPDATE SED
	SET 
		SED.DELETEDDATE = @currentdate, 
		SED.DELETEDBY = @UserID, 
		SED.Reverted_Date = @currentdate
	FROM STOCKENTRYDETAIL SED 
	WHERE 
		SED.STOCKENTRYID = @STOCKENTRYID
		AND SED.DELETEDDATE IS NULL

	UPDATE SE
	SET 
		SE.DELETEDDATE = @currentdate, 
		SE.DELETEDBY = @UserID,
		SE.Reverted_By = @UserID, 
		SE.Reverted_Date = @currentdate
	FROM STOCKENTRY SE
	WHERE STOCKENTRYID = @STOCKENTRYID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_D_STOCKCOUNTING]    Script Date: 17-10-2026 13:04:47 ******/
