CREATE PROCEDURE [dbo].[USP_D_STOCKCOUNTINGDETAIL]    
@BranchID INT,
@ITEMID INT

AS    
BEGIN    

	UPDATE SCD 
	SET SCD.DELETEDDATE = GETDATE()
	FROM 
		STOCKCOUNTINGDETAIL SCD INNER JOIN 
		STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
	WHERE 
		SC.BRANCHID = @BranchID 
		AND (ISNULL(SC.STATUS,0) = 1 OR ISNULL(SC.STATUS,0) = 0)
		AND SCD.DELETEDDATE IS NULL
		AND EXISTS
			(
				SELECT 1 
				FROM 
					ITEMCODE IC 
					INNER JOIN ITEMPRICE IP ON IC.ITEMCODEID = IP.ITEMCODEID 
				WHERE 
					IC.ITEMID = @ITEMID
					AND IP.ITEMPRICEID = SCD.ITEMPRICEID
			)
    
END
