/****** Object:  StoredProcedure [dbo].[USP_D_STOCKENTRYDETAIL_V2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_D_STOCKENTRYDETAIL_V2]      
@STOCKENTRYDETAILID INT,    
@UserID int = 0    
AS      
BEGIN      
  
	IF EXISTS
	(
		SELECT 1 
		FROM STOCKENTRY SE
			INNER JOIN STOCKENTRYDETAIL SED ON SED. STOCKENTRYID = SE.STOCKENTRYID
		WHERE ISNULL(SE.STATUS, 0) = 1 
			AND SED. STOCKENTRYDETAILID = @STOCKENTRYDETAILID
	)
	BEGIN
		RAISERROR ('Invoice already completed', 16, 1)
		RETURN
	END
      
	UPDATE STOCKENTRYDETAIL 
	SET 
		DELETEDBY = @UserID,    
		DELETEDDATE = GETDATE()    
	WHERE STOCKENTRYDETAILID = @STOCKENTRYDETAILID      
      
END
GO
