CREATE PROCEDURE [dbo].[USP_D_TRAYINFO]
@STOCKDISPATCHID INT = 0,
@TRAYINFOID INT,
@USERID INT
AS
BEGIN

	IF EXISTS(SELECT 1 FROM STOCKDISPATCHDETAIL WHERE TRAYINFOID = @TRAYINFOID AND DELETEDDATE IS NULL)
	BEGIN
		SELECT 'Tray number cannot be deleted while it still contains items. Please delete the items first.'
		RETURN;
	END

	IF(@STOCKDISPATCHID > 0)
	BEGIN
		IF NOT EXISTS(SELECT 1 FROM TRAYINFO WHERE TRAYINFOID = @TRAYINFOID AND STOCKDISPATCHID = @STOCKDISPATCHID AND DELETEDDATE IS NULL)
		BEGIN
			SELECT 'This tray can’t be deleted because it belongs to another dispatch.'
			RETURN;
		END
	END

	UPDATE TRAYINFO 
		SET DELETEDBY = @USERID, 
			DELETEDDATE = GETDATE() 
	WHERE TRAYINFOID = @TRAYINFOID

	SELECT @TRAYINFOID

END
GO
