/****** Object:  StoredProcedure [dbo].[USP_FINDSTOCKDIFFERENCES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_FINDSTOCKDIFFERENCES]
AS
BEGIN

declare @branchid int = 0
declare cur2 cursor for select BRANCHID from BRANCH WHERE BRANCHID NOT IN (45,91, 92, 95, 97, 100, 103, 105) AND DELETEDDATE IS NULL
open cur2

fetch next from cur2 into @branchid

WHILE   @@FETCH_STATUS = 0   
begin

exec USP_SS_IL_NOTMATCHING_BRANCH @branchid

FETCH NEXT FROM cur2 into @branchid

end

close cur2

deallocate cur2

END
GO
/****** Object:  StoredProcedure [dbo].[USP_G_PICKLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_G_PICKLIST]
(
	@CategoryID INT
	, @SupplierID INT
	, @LocationDivisionID INT
	, @StockEntryIDs NVARCHAR(MAX)
	, @UserID INT
)
AS
BEGIN
	
	SELECT * INTO #STOCKENTRY FROM dbo.SplitString(@StockEntryIDs,',')

	IF EXISTS (
		SELECT 1
		FROM 
			STOCKENTRY SE
			INNER JOIN #STOCKENTRY SETMP ON SETMP.Item = SE.STOCKENTRYID
		WHERE
			SE.PICKLISTID IS NOT NULL		
	)
	BEGIN

		SELECT 'One or more stock entries are already included in picklist generation'
		RETURN

	END

	DECLARE @PickListID INT, @PickListGeneratedStatusID INT, @PickListNumber VARCHAR(50)
		, @RunDate DATETIME

	SELECT @RunDate = GETDATE()
		
	SELECT SIDFT.BRANCHID, SED.ITEMCODEID, SED.MRP, SUM(SED.QUANTITY) STOCKENTRYQUANTITY
		, SUM(SID.DESIREDINDENT) SID_DESIREDINDENT, SUM(SIDFT.REQUIREDITEMINDENT) SID_REQBRANCHINDENT
		, CAST(0.00 AS DECIMAL(18, 2)) BRANCHQTYCALC, 0 AS PICKLISTBRANCHID, 0 AS APPLYROUNDING
	INTO #PICKLISTITEM
	FROM
		STOCKENTRYDETAIL SED
		INNER JOIN STOCKENTRY SE ON SE.STOCKENTRYID = SED.STOCKENTRYID
		INNER JOIN #STOCKENTRY SETMP ON SETMP.Item = SE.STOCKENTRYID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = SED.ITEMCODEID
		INNER JOIN SUPPLIERINDENTDETAIL SID ON SID.SUPPLIERINDENTID = SE.SUPPLIERINDENTID AND SID.ITEMID = IC.ITEMID
		INNER JOIN SID_FT_DETAIL SIDFT ON SIDFT.SUPPLIERINDENTDETAILID = SID.SUPPLIERINDENTDETAILID			
	WHERE 
		SED.DELETEDDATE IS NULL
		AND SE.DELETEDDATE IS NULL
	GROUP BY SIDFT.BRANCHID, SED.ITEMCODEID, SED.MRP

	UPDATE X
	SET BRANCHQTYCALC =
		CASE
			--WHEN DeliveryPerc >= 100 THEN SID_REQBRANCHINDENT
			WHEN DeliveryPerc >= 70 THEN ROUND(SID_REQBRANCHINDENT * STOCKENTRYQUANTITY / TotalNeededStock, 0)
			ELSE
				CASE
					WHEN CumIndent <= STOCKENTRYQUANTITY THEN SID_REQBRANCHINDENT
					WHEN CumIndent - SID_REQBRANCHINDENT >= STOCKENTRYQUANTITY THEN 0
					ELSE STOCKENTRYQUANTITY - (CumIndent - SID_REQBRANCHINDENT)
				END
		END
		, APPLYROUNDING = CASE WHEN DeliveryPerc >= 70 THEN 1 ELSE 0 END
	FROM
		(
			SELECT *, SUM(SID_REQBRANCHINDENT) OVER ( PARTITION BY ITEMCODEID ) TotalNeededStock,
					DeliveryPerc = STOCKENTRYQUANTITY * 100.0 / SUM(SID_REQBRANCHINDENT) OVER ( PARTITION BY ITEMCODEID ),
					CumIndent =
						SUM(SID_REQBRANCHINDENT) OVER
						(
							PARTITION BY ITEMCODEID
							ORDER BY SID_REQBRANCHINDENT DESC, BRANCHID
						)
			FROM #PICKLISTITEM
		) X;


	-- distribute rounding back to highest quantity branches as one piece per branch
	UPDATE PL
	SET PL.BRANCHQTYCALC = PL.BRANCHQTYCALC + PLRD.ROUNDINGDIFF / ABS(PLRD.ROUNDINGDIFF)
	FROM
		#PICKLISTITEM PL
		INNER JOIN
			(
				SELECT IC.ITEMID, PL.ITEMCODEID, PL.MRP, BRANCHQTYCALC, PL.BRANCHID, ROW_NUMBER() OVER (
							PARTITION BY IC.ITEMID
							ORDER BY BRANCHQTYCALC DESC
						) AS RN
				FROM
					#PICKLISTITEM PL 
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PL.ITEMCODEID
			) PLMAX ON PLMAX.ITEMCODEID = PL.ITEMCODEID AND PLMAX.MRP = PL.MRP AND PLMAX.BRANCHID = PL.BRANCHID
		INNER JOIN 
			(
				SELECT 
					IC.ITEMID, STOCKENTRYQUANTITY - SUM(BRANCHQTYCALC) ROUNDINGDIFF
				FROM 
					#PICKLISTITEM PL
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PL.ITEMCODEID
				GROUP BY IC.ITEMID, STOCKENTRYQUANTITY
			) PLRD ON PLRD.ITEMID = PLMAX.ITEMID
	WHERE
		PLRD.ROUNDINGDIFF <> 0
		AND PL.APPLYROUNDING = 1
		and PLMAX.RN <= ABS(PLRD.ROUNDINGDIFF)

		/*
	-- Adjusts rounding back to highest quantity branch
	UPDATE PL
	SET PL.BRANCHQTYCALC = PL.BRANCHQTYCALC + PLRD.ROUNDINGDIFF
	FROM
		#PICKLISTITEM PL
		INNER JOIN
			(
				SELECT *
				FROM
					(
						SELECT IC.ITEMID, PL.ITEMCODEID, PL.MRP, BRANCHQTYCALC, PL.BRANCHID, ROW_NUMBER() OVER (
								   PARTITION BY IC.ITEMID
								   ORDER BY BRANCHQTYCALC DESC
							   ) AS RN
						FROM
							#PICKLISTITEM PL 
							INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PL.ITEMCODEID
					) PLOUTER
				WHERE PLOUTER.RN = 1
			) PLMAX ON PLMAX.ITEMCODEID = PL.ITEMCODEID AND PLMAX.MRP = PL.MRP AND PLMAX.BRANCHID = PL.BRANCHID
		INNER JOIN 
			(
				SELECT 
					IC.ITEMID, STOCKENTRYQUANTITY - SUM(BRANCHQTYCALC) ROUNDINGDIFF
				FROM 
					#PICKLISTITEM PL
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PL.ITEMCODEID
				GROUP BY IC.ITEMID, STOCKENTRYQUANTITY
			) PLRD ON PLRD.ITEMID = PLMAX.ITEMID
	WHERE
		PLRD.ROUNDINGDIFF <> 0
		AND PL.APPLYROUNDING = 1
		*/

	SELECT @PickListGeneratedStatusID = ENUMID
	FROM ENUMLIST
	WHERE ENUMTYPE = 'Picklist Status' AND ENUMVALUE = 'Generated'

	INSERT INTO PICKLIST(CATEGORYID, SUPPLIERID, LOCATIONDIVISIONID, PICKLISTSTATUS, CREATEDBY, CREATEDDATE)
	SELECT @CategoryID, @SupplierID, @LocationDivisionID, @PickListGeneratedStatusID, @UserID, @RunDate

	SET @PickListID = SCOPE_IDENTITY()

	SELECT @PickListNumber = 'PL-' + FORMAT(@RunDate, 'yyMMdd') + '-' + LD.LOCATIONDIVISIONNAME + '-' + RIGHT('000' + CAST(COUNT(1) AS VARCHAR(4)), 4)
	FROM
		PICKLIST PL
		INNER JOIN LOCATIONDIVISION LD ON LD.LOCATIONDIVISIONID = PL.LOCATIONDIVISIONID
	WHERE CAST(PL.CREATEDDATE AS DATE) = CAST(@RunDate AS DATE)
		AND PL.LOCATIONDIVISIONID = @LocationDivisionID
	GROUP BY LD.LOCATIONDIVISIONNAME

	UPDATE PICKLIST
	SET PICKLISTNUMBER = @PickListNumber
	WHERE PICKLISTID = @PickListID

	INSERT INTO PICKLISTBRANCH(BRANCHID, CREATEDBY, CREATEDDATE, PICKEDSTATUS, PICKLISTID)
	SELECT DISTINCT PL.BRANCHID, @UserID, @RunDate, @PickListGeneratedStatusID, @PickListID
	FROM #PICKLISTITEM PL
		
	UPDATE PL
	SET PL.PICKLISTBRANCHID = PLB.PICKLISTBRANCHID
	FROM
		#PICKLISTITEM PL
		INNER JOIN PICKLISTBRANCH PLB ON PLB.BRANCHID = PL.BRANCHID
	WHERE
		PLB.PICKLISTID = @PickListID

	
	UPDATE PLID
	SET PLID.QUANTITY = PLID.QUANTITY + PL.BRANCHQTYCALC, UPDATEDBY = @UserID, UPDATEDDATE = @RunDate
	FROM
		PICKLISTITEM PLID
		INNER JOIN #PICKLISTITEM PL ON PL.PICKLISTBRANCHID = PLID.PICKLISTBRANCHID AND PL.ITEMCODEID = PLID.ITEMCODEID AND PL.MRP = PLID.MRP
	WHERE
		PLID.PICKEDSTATUS = 0
		AND PLID.DELETEDDATE IS NULL

		
	INSERT INTO PICKLISTITEM(PICKLISTBRANCHID, ITEMCODEID, MRP, QUANTITY, PICKEDQUANTITY, PICKEDSTATUS, CREATEDBY, CREATEDDATE)
	SELECT PL.PICKLISTBRANCHID, PL.ITEMCODEID, PL.MRP, PL.BRANCHQTYCALC, 0, 0, @UserID, @RunDate
	FROM
		#PICKLISTITEM PL
	WHERE
		NOT EXISTS
			(
				SELECT 1 
				FROM PICKLISTITEM PLIDINNER
				WHERE 
					PLIDINNER.PICKLISTBRANCHID = PL.PICKLISTBRANCHID
					AND PLIDINNER.ITEMCODEID = PL.ITEMCODEID
					AND PLIDINNER.MRP = PL.MRP
					AND PLIDINNER.PICKEDSTATUS = 0
					AND PLIDINNER.DELETEDDATE IS NULL
			)

	UPDATE SE
	SET SE.PICKLISTID = @PickListID
	FROM 
		STOCKENTRY SE
		INNER JOIN #STOCKENTRY SETMP ON SETMP.Item = SE.STOCKENTRYID
	 WHERE SE.DELETEDDATE IS NULL

	 SELECT @PickListID PICKLISTID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_G_SUPPLIERINDENT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_G_SUPPLIERINDENT]
(
	@SupplierID INT 
	, @CategoryID INT
	, @ManufacturerID INT = NULL
	, @SafetyDays INT
	, @IndentItemSelectionType INT
	, @BranchID INT = NULL
	, @UserID INT
)
AS
BEGIN

	IF EXISTS 
	(
		SELECT 1
		FROM SUPPLIERINDENT SI
		WHERE 
			SI.DELETEDDATE IS NULL
			AND SI.SUPPLIERID = @SupplierID
			AND SI.CATEGORYID = @CategoryID
			AND ISNULL(SI.MANUFACTURERID, 0) = ISNULL(@ManufacturerID, 0)
			AND SUPPLIERITEMINDENTTYPEID = @IndentItemSelectionType 
			AND SI.ISINTERNAL <> 1
			AND SI.CREATEDDATE > DATEADD(d, -15, CAST(GETDATE() AS DATE))
			AND SI.STATUS NOT IN (16, 17) -- closed\rejected
			AND ISNULL(SI.BRANCHID, 45) = ISNULL(@BranchID, 45)
			AND NOT EXISTS
				(
					SELECT 1 
					FROM STOCKENTRY SE
					WHERE
						SE.DELETEDDATE IS NULL
						AND SE.SUPPLIERINDENTID = SI.SUPPLIERINDENTID
				)
	)
	BEGIN
		RAISERROR ('Supplier indent already exists in the last 15 days for the same parameters', 16, 1);
		RETURN;

	END

	DECLARE @SupplierItemIndentType VARCHAR(100), @TargetBranchID INT 
	
	SELECT @SupplierItemIndentType = ENUMVALUE FROM ENUMLIST WHERE ENUMID = @IndentItemSelectionType

	SELECT I.ITEMID, SED.STOCKENTRYDETAILID, I.INNERCASEQTY, I.OUTERCASEQTY
	INTO #ITEMDATA
	FROM 
		ITEM I WITH(NOLOCK)
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMID = I.ITEMID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = I.ITEMID
		LEFT JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID AND SED.DELETEDDATE IS NULL
		LEFT JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID AND SE.SUPPLIERID = @SupplierID AND SE.DELETEDDATE IS NULL
	WHERE
		ISM.SUPPLIERID = @SupplierID
		AND I.CATEGORYID = @CategoryID
		AND I.DELETEDDATE IS NULL
		AND IC.DELETEDDATE IS NULL
		AND ICP.DELETEDDATE IS NULL
		AND ISM.DELETEDDATE IS NULL
		AND I.SUPPLIERINDENTITEMTYPEID = @IndentItemSelectionType
		AND (I.MANUFACTURERID = @ManufacturerID OR ISNULL(@ManufacturerID, 0) = 0)
		
	PRINT 'Total items matching supplier criteria - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	SELECT @TargetBranchID = CASE 
								WHEN @SupplierItemIndentType = 'Non - Flow Through' THEN 45 
								WHEN @SupplierItemIndentType = 'Direct store dispatch' THEN @BranchID 
							ELSE NULL END
	

	SELECT FULLDATA.ITEMID, SSTOTAL.BRANCHID, MAX(FULLDATA.STOCKENTRYDETAILID) STOCKENTRYDETAILID -- pick recent entry
		, 0 AS ITEMCOSTPRICEID, SSTOTAL.QTYORWGHTINKGS BRANCHQUANTITY, CAST(0 AS DECIMAL(18, 2)) INTRANSITQTY
		--, CAST(IL.THRESHOLD * ROUND(((14.00 + @SafetyDays) / 14), 0) AS DECIMAL(18, 2)) AS THRESHOLD
		, IL.THRESHOLD
		, CAST(ROUND(IL.DESIREDQUANTITY * ((14.00 + @SafetyDays) / 14), 0) AS DECIMAL(18, 2)) AS REQUIREDBRANCHSTOCK		
		, CAST(0 AS DECIMAL(18, 2)) REQUIREDITEMINDENT, FULLDATA.INNERCASEQTY, FULLDATA.OUTERCASEQTY
	INTO #ITEMSTOCKDATA
	FROM 
		#ITEMDATA FULLDATA
		INNER JOIN 
			(
				SELECT I.ITEMID, SS.BRANCHID
					, SUM(CASE WHEN I.ISOPENITEM <> 1 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END) QTYORWGHTINKGS
				FROM 
					STOCKSUMMARY SS WITH(NOLOCK)
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
					INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID
				WHERE 
					IP.DELETEDDATE IS NULL
					AND IC.DELETEDDATE IS NULL
					AND I.DELETEDDATE IS NULL
					AND (SS.BRANCHID = @TargetBranchID OR @TargetBranchID IS NULL)
					AND B.DELETEDDATE IS NULL
				GROUP BY I.ITEMID, SS.BRANCHID
			) SSTOTAL ON SSTOTAL.ITEMID = FULLDATA.ITEMID
		INNER JOIN INDENTLIMIT IL ON IL.ITEMID = FULLDATA.ITEMID AND IL.BRANCHID = SSTOTAL.BRANCHID	
	WHERE IL.DESIREDQUANTITY > 0
	GROUP BY FULLDATA.ITEMID, SSTOTAL.BRANCHID, SSTOTAL.QTYORWGHTINKGS, IL.THRESHOLD
		, IL.DESIREDQUANTITY, FULLDATA.INNERCASEQTY, FULLDATA.OUTERCASEQTY
		
	PRINT 'Total items matching branch and supplier criteria - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	UPDATE ISD 
	SET ISD.INTRANSITQTY = INTRANSITSDD.INTRANSITQTY
	FROM
		#ITEMSTOCKDATA ISD 
		INNER JOIN 
			(
				SELECT I.ITEMID, SD.TOBRANCHID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END) INTRANSITQTY
				FROM
					STOCKDISPATCHDETAIL SDD WITH(NOLOCK)
					INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				WHERE
					SD.STATUS = 1
					AND SD.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
				GROUP BY I.ITEMID, SD.TOBRANCHID
			) INTRANSITSDD ON INTRANSITSDD.TOBRANCHID = ISD.BRANCHID AND INTRANSITSDD.ITEMID = ISD.ITEMID

	PRINT 'updated in-transit qty for - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	DELETE ISD
	FROM #ITEMSTOCKDATA ISD
	WHERE (CASE WHEN BRANCHQUANTITY > 0 THEN BRANCHQUANTITY ELSE 0 END + ISD.INTRANSITQTY) > ISD.THRESHOLD

	PRINT 'Removed items with sufficient stock (physical + in-transit) > threshold - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	UPDATE ISD
	SET REQUIREDITEMINDENT = REQUIREDBRANCHSTOCK - (CASE WHEN BRANCHQUANTITY > 0 THEN BRANCHQUANTITY ELSE 0 END + INTRANSITQTY)
	FROM #ITEMSTOCKDATA ISD

	PRINT 'Calculated desired MBQ for - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	DELETE ISD	
	FROM #ITEMSTOCKDATA ISD
	WHERE ISD.REQUIREDITEMINDENT <= 0

	PRINT 'Cleared zero or negative indent branches - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	SELECT
		ISD.ITEMID, ISD.STOCKENTRYDETAILID, SUM(ISD.REQUIREDITEMINDENT) REQUIREDITEMINDENT, CAST(0 AS DECIMAL(18, 2)) CALCULATEDITEMINDENT
		, CAST(0 AS DECIMAL(18, 2)) MRP, CAST(0 AS DECIMAL(18, 2)) COSTPRICEWT
		, SUM(CASE WHEN BRANCHQUANTITY > 0 THEN BRANCHQUANTITY ELSE 0 END + ISD.INTRANSITQTY) BRANCHQUANTITY, SUM(ISD.REQUIREDBRANCHSTOCK) REQUIREDBRANCHSTOCK
		, ISD.INNERCASEQTY, ISD.OUTERCASEQTY, CAST(0 AS DECIMAL(18, 2)) WHQTY
	INTO #SUPPLIERINDENTDETAIL
	FROM #ITEMSTOCKDATA ISD
	GROUP BY ISD.ITEMID, ISD.ITEMCOSTPRICEID, ISD.STOCKENTRYDETAILID, ISD.INNERCASEQTY, ISD.OUTERCASEQTY

	PRINT 'Grouped branch data into item, new count - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	IF @SupplierItemIndentType = 'Flow Through'
	BEGIN

		PRINT 'Flow through logic - calculating WH stock'
		
		UPDATE SID
		SET SID.WHQTY = SSTOTAL.QTYORWGHTINKGS
		FROM
			#SUPPLIERINDENTDETAIL SID
			INNER JOIN 
				(
					SELECT I.ITEMID, SS.BRANCHID
						, SUM(CASE WHEN I.ISOPENITEM <> 1 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END) QTYORWGHTINKGS
					FROM 
						STOCKSUMMARY SS WITH(NOLOCK)
						INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
					WHERE 
						IP.DELETEDDATE IS NULL
						AND IC.DELETEDDATE IS NULL
						AND I.DELETEDDATE IS NULL
						AND SS.BRANCHID = 45
					GROUP BY I.ITEMID, SS.BRANCHID
				) SSTOTAL ON SSTOTAL.ITEMID = SID.ITEMID

		PRINT 'Updated WH stock for items - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

		UPDATE SID
		SET SID.REQUIREDITEMINDENT = SID.REQUIREDITEMINDENT - ISNULL(CASE WHEN SID.WHQTY < 0 THEN 0 ELSE SID.WHQTY END, 0)
		FROM #SUPPLIERINDENTDETAIL SID
		
		DELETE SID
		FROM #SUPPLIERINDENTDETAIL SID
		WHERE SID.REQUIREDITEMINDENT <= 0

		PRINT 'Deleted indent items with WH stock - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	END

	UPDATE ITEMDATA
	SET 
		MRP = IP.MRP
		, COSTPRICEWT = ICP.COSTPRICEWT
	FROM
		#SUPPLIERINDENTDETAIL ITEMDATA
		INNER JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.STOCKENTRYDETAILID = ITEMDATA.STOCKENTRYDETAILID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID

	PRINT 'Updated MRP and Recent Costprice WT for - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	UPDATE ITEMDATA
	SET CALCULATEDITEMINDENT = REQUIREDITEMINDENT, REQUIREDITEMINDENT = DBO.UDF_ROUND_QTY_BY_CASE(ITEMDATA.REQUIREDITEMINDENT, OUTERCASEQTY, INNERCASEQTY)
	FROM #SUPPLIERINDENTDETAIL ITEMDATA

	PRINT 'Applied case rounding - ' + CAST(@@ROWCOUNT AS VARCHAR(10))
	
	DELETE SID
	FROM #SUPPLIERINDENTDETAIL SID
	WHERE SID.REQUIREDITEMINDENT <= 0

	PRINT 'Deleted 80% less items after case rounding - ' + CAST(@@ROWCOUNT AS VARCHAR(10))

	DELETE ISD
	FROM #ITEMSTOCKDATA ISD
	WHERE NOT EXISTS
		(
			SELECT 1 
			FROM #SUPPLIERINDENTDETAIL SID
			WHERE SID.ITEMID = ISD.ITEMID
		)

	
	SELECT I.ITEMNAME, I.SKUCODE, SID.*, SID.REQUIREDITEMINDENT DESIREDITEMINDENT 
	FROM
		#SUPPLIERINDENTDETAIL SID
		INNER JOIN ITEM I ON I.ITEMID = SID.ITEMID
	ORDER BY SID.REQUIREDITEMINDENT DESC

	SELECT B.BRANCHNAME, ISD.ITEMID, ISD.BRANCHID, ISD.STOCKENTRYDETAILID, ISD.BRANCHQUANTITY, ISD.REQUIREDITEMINDENT
		, ISD.INTRANSITQTY, ISD.THRESHOLD, ISD.REQUIREDBRANCHSTOCK, ISD.INNERCASEQTY, ISD.OUTERCASEQTY
	FROM 
		#ITEMSTOCKDATA ISD
		INNER JOIN ITEM I ON I.ITEMID = ISD.ITEMID
		INNER JOIN BRANCH B ON B.BRANCHID = ISD.BRANCHID
	ORDER BY ISD.ITEMID, B.BRANCHNAME
			   	

	PRINT ''

END
GO
/****** Object:  StoredProcedure [dbo].[USP_GET_GSTVALUE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_GET_GSTVALUE]
AS
BEGIN

DECLARE @FromDate DATE, @ToDate DATE

SET @FromDate = '2022-03-01'
SET @ToDate = '2022-04-01'

CREATE TABLE #TBLDC(DayClosureID INT, BranchCounterID INT)

INSERT INTO #TBLDC(DayClosureID,BranchCounterID)
SELECT DAYCLOSUREID,BRANCHCOUNTERID FROM POS_DAYCLOSURE 
WHERE CLOSUREDATE > @FromDate AND CLOSUREDATE < @ToDate

SELECT 
CONVERT(DATE,BD.CREATEDDATE) AS BILLDATE,
BD.GSTID,
GST.GSTCODE,
SUM(BD.BILLEDAMOUNT) AS BILLEDAMOUNT,
SUM(BD.CGST) AS CGST,
SUM(BD.SGST) AS SGST,
SUM(BD.CESS) AS CESS
FROM POS_BILLDETAIL BD
INNER JOIN #TBLDC LDC ON BD.DAYCLOSUREID = LDC.DayClosureID 
	AND BD.BRANCHCOUNTERID = LDC.BranchCounterID
INNER JOIN GSTDETAIL GST ON BD.GSTID = GST.GSTID
WHERE BD.DELETEDDATE IS NULL
GROUP BY CONVERT(DATE,BD.CREATEDDATE),BD.GSTID,GST.GSTCODE

DROP TABLE #TBLDC
END
GO
/****** Object:  StoredProcedure [dbo].[USP_IMP_DISCOUNTSALECODES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_IMP_DISCOUNTSALECODES]
@data IMPORTSD READONLY,
@USERID INT,
@BRANCHID INT
AS    
BEGIN    

	CREATE TABLE #DATA
	(
		ITEMCODE NVARCHAR(100), 
		MRP DECIMAL(18,2), 
		OLDSALEPRICE DECIMAL(18,2), 
		NEWSALEPRICE DECIMAL(18,2), 
		QUANTITY INT, 
		WEIGHTINKGS DECIMAL(18,2),
		NEWITEMCODE NVARCHAR(100),
		OLDITEMCODEID INT,
		NEWITEMCODEID INT,
		OLDITEMPRICEID INT,
		NEWITEMPRICEID INT,
		PREVQUANTITY INT,
		PREVWEIGHTINKGS DECIMAL(18,2)
	)

	DECLARE @CREATEDDATE DATETIME = GETDATE(), @ERROR_MSG NVARCHAR(MAX) = ''

	INSERT INTO #DATA(ITEMCODE, MRP, OLDSALEPRICE, NEWSALEPRICE, QUANTITY, WEIGHTINKGS, PREVQUANTITY, PREVWEIGHTINKGS)
	SELECT ITEMCODE, MRP, OLDSALEPRICE, NEWSALEPRICE, QUANTITY, WEIGHTINKGS, 0, 0 FROM @data

	UPDATE #DATA SET NEWITEMCODE = 'V'+ ITEMCODE

	IF EXISTS(SELECT 1 FROM ITEMCODE IC INNER JOIN #DATA DT ON IC.ITEMCODE = DT.NEWITEMCODE)
	BEGIN
		SET @ERROR_MSG = 'Few items are already having discount sale codes.'
	END

	UPDATE DT
	SET DT.OLDITEMCODEID = IC.ITEMCODEID
	FROM #DATA DT
	INNER JOIN ITEMCODE IC ON DT.ITEMCODE = IC.ITEMCODE
	WHERE IC.DELETEDDATE IS NULL

	UPDATE DT
	SET DT.OLDITEMPRICEID = IP.ITEMPRICEID
	FROM #DATA DT
	INNER JOIN ITEMPRICE IP ON DT.OLDITEMCODEID = IP.ITEMCODEID 
		AND DT.MRP = IP.MRP 
		AND DT.OLDSALEPRICE = IP.SALEPRICE
	WHERE IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL

-- Fetch previous stock summary
    UPDATE DT
    SET DT.PREVQUANTITY = SS.QUANTITY,
        DT.PREVWEIGHTINKGS = SS.WEIGHTINKGS
    FROM #DATA DT
    INNER JOIN STOCKSUMMARY SS 
        ON DT.OLDITEMPRICEID = SS.ITEMPRICEID 
        AND SS.BRANCHID = @BRANCHID


	-- Validation: compare new and previous quantities
        IF EXISTS (
            SELECT 1
            FROM #DATA DT
            INNER JOIN ITEMCODE IC ON DT.OLDITEMCODEID = IC.ITEMCODEID
            INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
            WHERE 
                (I.ISOPENITEM = 0 AND DT.PREVQUANTITY = 0)
                OR (I.ISOPENITEM = 1 AND DT.PREVWEIGHTINKGS = 0)
                OR (DT.QUANTITY - DT.PREVQUANTITY) > 0
                OR (DT.WEIGHTINKGS - DT.PREVWEIGHTINKGS) > 0
        )
        BEGIN
            IF @ERROR_MSG <> ''
				SET @ERROR_MSG = @ERROR_MSG + CHAR(13) + CHAR(10);
        
		SET @ERROR_MSG = @ERROR_MSG + 'New quantity and previous quantity/weight mismatch for few items.';
        END
    
	IF(@ERROR_MSG <> '')
	BEGIN
		SELECT @ERROR_MSG
		RETURN;
	END

	INSERT INTO ITEMCODE(ITEMCODE, ITEMID, HSNCODE, ISEAN,   CREATEDBY, CREATEDDATE, FREEITEMCODEID, IsDSCode)    
	SELECT DISTINCT DT.NEWITEMCODE, IC.ITEMID, IC.HSNCODE , 1,   @UserID, @CREATEDDATE, IC.FREEITEMCODEID, 1  
	FROM #DATA DT 
		INNER JOIN ITEMCODE IC ON  DT.OLDITEMCODEID = IC.ITEMCODEID

	UPDATE DT
		SET NEWITEMCODEID = IC.ITEMCODEID
	FROM #DATA DT 
		INNER JOIN ITEMCODE IC ON DT.NEWITEMCODE = IC.ITEMCODE
  
	
	INSERT INTO ITEMPRICE(ITEMCODEID, SALEPRICE, MRP, GSTID, CREATEDBY, CREATEDDATE)
	SELECT DT.NEWITEMCODEID, DT.NEWSALEPRICE, DT.MRP, IP.GSTID, @UserID, @CREATEDDATE FROM #DATA DT
		INNER JOIN ITEMPRICE IP ON DT.OLDITEMPRICEID = IP.ITEMPRICEID

	UPDATE DT
	SET DT.NEWITEMPRICEID = IP.ITEMPRICEID  
	FROM #DATA DT
		INNER JOIN ITEMPRICE IP ON DT.NEWITEMCODEID = IP.ITEMCODEID AND DT.MRP = IP.MRP AND DT.NEWSALEPRICE = IP.SALEPRICE  
	WHERE IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL AND IP.CREATEDDATE = @CREATEDDATE
	
	INSERT INTO ITEMCOSTPRICE(ITEMPRICEID,COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,CREATEDBY,CREATEDDATE)  
	SELECT ICPINNER.NEWITEMPRICEID, COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,4,@CREATEDDATE FROM   
	(  
		SELECT DT.OLDITEMPRICEID, DT.NEWITEMPRICEID, MAX(ITEMCOSTPRICEID) AS ITEMCOSTPRICEID  
		FROM #DATA DT
			INNER JOIN ITEMCOSTPRICE ICP ON DT.OLDITEMPRICEID = ICP.ITEMPRICEID  
		WHERE ICP.DELETEDDATE IS NULL  
		GROUP BY DT.OLDITEMPRICEID, DT.NEWITEMPRICEID  
	) ICPINNER   
	INNER JOIN ITEMCOSTPRICE ICP ON ICPINNER .ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID   

	INSERT INTO STOCKMOVE
	(
		OLDITEMPRICEID, NEWITEMPRICEID, STOCKADJUSTMENTTYPEID, GOLIVEDATE, 
		CREATEDBY, CREATEDDATE, REASON, DEDUCTEDQUANTITY, ADDEDQUANTITY, 
		BRANCHID, DEDUCTEDWEIGHTINKGS, ADDEDWEIGHTINKGS
	)  
	SELECT 
		OLDITEMPRICEID, NEWITEMPRICEID, 7, NULL, @USERID, @CREATEDDATE, 
		'Discount Sale Codes Import', QUANTITY, QUANTITY, @BRANCHID,
		WEIGHTINKGS, WEIGHTINKGS
	FROM #DATA

	SELECT 0
    
END
GO
/****** Object:  StoredProcedure [dbo].[USP_IMP_MBQ]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_IMP_MBQ]
@data IMPORTMBQ READONLY,
@USERID INT
AS    
BEGIN    

	CREATE TABLE #INPUTDATA
	(
		ROWID INT IDENTITY(1, 1),
		[MBQTARGET] [VARCHAR](100) NULL,
		[TARGETTYPE] [VARCHAR](15) NULL,
		[SKUCODE] [VARCHAR](10) NULL,
		[THRESHOLD] [DECIMAL](18, 2) NULL,
		[DESIREDQUANTITY] [DECIMAL](18, 2) NULL,
		ERRORMSG VARCHAR(MAX) DEFAULT '',
		ISERROR BIT DEFAULT 0,
		BRANCHID INT,
		BRANCHGRADEID INT,
		ITEMID INT
	)

	INSERT INTO #INPUTDATA(MBQTARGET, TARGETTYPE, SKUCODE, THRESHOLD, DESIREDQUANTITY)
	SELECT * FROM @data

	UPDATE #INPUTDATA
	SET ERRORMSG = 'Invalid Target type. '
	WHERE TARGETTYPE <> 'BRANCH' AND TARGETTYPE <> 'BRANCHGRADE'

	UPDATE ID
	SET ID.BRANCHID = B.BRANCHID
	FROM 
		#INPUTDATA ID
		INNER JOIN BRANCH B ON B.BRANCHNAME = ID.MBQTARGET 
	WHERE TARGETTYPE = 'BRANCH'
		AND B.DELETEDDATE IS NULL

	UPDATE ID
	SET ID.ERRORMSG = ID.ERRORMSG + 'Branch not found. '
	FROM #INPUTDATA ID
	WHERE TARGETTYPE = 'BRANCH' AND ID.BRANCHID IS NULL

	UPDATE ID
	SET ID.BRANCHGRADEID = BG.BRANCHGRADEID
	FROM 
		#INPUTDATA ID
		INNER JOIN BRANCHGRADE BG ON BG.GRADE = ID.MBQTARGET
	WHERE TARGETTYPE = 'BRANCHGRADE'

	UPDATE ID
	SET ID.ERRORMSG = ID.ERRORMSG + 'Branch grade not found. '
	FROM #INPUTDATA ID
	WHERE TARGETTYPE = 'BRANCHGRADE' AND ID.BRANCHGRADEID IS NULL

	UPDATE ID
	SET ID.ERRORMSG = ID.ERRORMSG + 'Threshold is empty. '
	FROM #INPUTDATA ID
	WHERE THRESHOLD IS NULL

	UPDATE ID
	SET ID.ERRORMSG = ID.ERRORMSG + 'Desired Quantity is empty. '
	FROM #INPUTDATA ID
	WHERE DESIREDQUANTITY IS NULL

	UPDATE ID
	SET ID.ITEMID = I.ITEMID
	FROM 
		#INPUTDATA ID
		INNER JOIN ITEM I ON I.SKUCODE = ID.SKUCODE

	UPDATE ID
	SET ID.ERRORMSG = ID.ERRORMSG + 'SKU Code not found. '
	FROM #INPUTDATA ID
	WHERE ID.ITEMID IS NULL

	UPDATE ID
	SET ID.ERRORMSG = ID.ERRORMSG + 'Duplicate record found in input file. '
	FROM #INPUTDATA ID
	WHERE EXISTS
		(
			SELECT 1
			FROM #INPUTDATA IDINNER
			WHERE IDINNER.SKUCODE = ID.SKUCODE AND IDINNER.MBQTARGET = ID.MBQTARGET AND IDINNER.TARGETTYPE = ID.TARGETTYPE
			GROUP BY IDINNER.SKUCODE, IDINNER.MBQTARGET, IDINNER.TARGETTYPE
			HAVING COUNT(1) > 1
		)

	UPDATE ID
	SET ID.ISERROR = 1
	FROM #INPUTDATA ID
	WHERE ID.ERRORMSG <> ''

	CREATE TABLE #FINALDATA 
	(
		BRANCHID INT,
		ITEMID INT,
		[THRESHOLD] [DECIMAL](18, 2) NULL,
		[DESIREDQUANTITY] [DECIMAL](18, 2) NULL
	)

	INSERT INTO #FINALDATA(BRANCHID, ITEMID, THRESHOLD, DESIREDQUANTITY)
	SELECT BRANCHID, ITEMID, THRESHOLD, DESIREDQUANTITY
	FROM #INPUTDATA
	WHERE ISERROR = 0 AND TARGETTYPE = 'BRANCH'

	INSERT INTO #FINALDATA(BRANCHID, ITEMID, THRESHOLD, DESIREDQUANTITY)
	SELECT B.BRANCHID, ITEMID, THRESHOLD, DESIREDQUANTITY
	FROM 
		#INPUTDATA ID 
		INNER JOIN BRANCHGRADE BG ON BG.GRADE = ID.MBQTARGET
		INNER JOIN BRANCH B ON B.BRANCHGRADEID = BG.BRANCHGRADEID
	WHERE 
		ISERROR = 0 
		AND TARGETTYPE = 'BRANCHGRADE'
		AND NOT EXISTS
			(
				SELECT 1 FROM #FINALDATA FD 
				WHERE 
					FD.BRANCHID = B.BRANCHID
					AND FD.ITEMID = ID.ITEMID
			)

	UPDATE IL
	SET 
		IL.THRESHOLD = FD.THRESHOLD
		, IL.DESIREDQUANTITY = FD.DESIREDQUANTITY
		, IL.UPDATEDBY = @USERID
		, IL.UPDATEDDATE = GETDATE()
	FROM
		INDENTLIMIT IL
		INNER JOIN #FINALDATA FD ON FD.ITEMID = IL.ITEMID AND FD.BRANCHID = IL.BRANCHID

	INSERT INTO INDENTLIMIT(BRANCHID, ITEMID, THRESHOLD, DESIREDQUANTITY, CREATEDBY, CREATEDDATE)
	SELECT FD.BRANCHID, FD.ITEMID, FD.THRESHOLD, FD.DESIREDQUANTITY, @USERID, GETDATE()
	FROM #FINALDATA FD
	WHERE NOT EXISTS
		(
			SELECT 1
			FROM INDENTLIMIT IL
			WHERE 
				IL.BRANCHID = FD.BRANCHID
				AND IL.ITEMID = FD.ITEMID
		)

	DECLARE @combinedString VARCHAR(MAX), @FailedRowCount INT, @TotalRowCount INT
	SELECT @combinedString = COALESCE(@combinedString + ' \n ', '') + ( 'Row #: ' + CAST(ROWID + 1 AS VARCHAR(5)) + ' - ' + ERRORMSG)
	FROM #INPUTDATA ID
	WHERE ID.ISERROR = 1

	SELECT @FailedRowCount = COUNT(1) FROM #INPUTDATA WHERE ISERROR = 1
	SELECT @TotalRowCount = COUNT(1) FROM #INPUTDATA 


	SELECT @combinedString = ISNULL(@combinedString, '') + ' \n Total Row count: ' + CAST(@TotalRowCount AS VARCHAR(10))
		+ ' \n Failed Row count: ' + CAST(@FailedRowCount AS VARCHAR(10))

	SELECT @combinedString
END
GO
/****** Object:  StoredProcedure [dbo].[USP_IMP_OFFER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_IMP_OFFER]
@BASEOFFERID INT,
@CATEGORYID INT,
@dtOffer OFFERIMPORT READONLY,
@USERID INT
AS
BEGIN

	IF EXISTS(SELECT 1 FROM @dtOffer WHERE OFFERTYPE NOT IN ('DF','DP','FR') AND ISNULL(ITEMCODE,'') != '')
	BEGIN
		SELECT 'Offer type not recognized'
		return
	END

	IF EXISTS
	(
		SELECT 1 FROM @dtOffer OFR
			INNER JOIN ITEMCODE IC ON CAST(OFR.ITEMCODE AS VARCHAR) = IC.ITEMCODE
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		WHERE I.CATEGORYID <> @CATEGORYID AND ISNULL(OFR.ITEMCODE,'') != ''
	)
	BEGIN
		SELECT 'Other category items are exists, please correct them.'
		RETURN;
	END

	DECLARE @OFFERCODE VARCHAR(10), @OFFERNAME VARCHAR(100)
	SELECT 
		@OFFERCODE = OFFERCODE, 
		@OFFERNAME = OFFERNAME 
	FROM BASEOFFER 
	WHERE BASEOFFERID = @BASEOFFERID

	DECLARE @COUNT INT
	SELECT @COUNT = ISNULL(COUNT(*),0) FROM OFFER WHERE BASEOFFERID = @BASEOFFERID

	BEGIN TRY                                          
	BEGIN TRAN                   
		
		CREATE TABLE #OFFERDETAILS(ID INT IDENTITY(1,1),ITEMCODEID INT, OFFERTYPEID INT, OFFERVALUE DECIMAL(10,2), OFFERID INT, NUMBEROFPIECES INT)

		INSERT INTO #OFFERDETAILS(ITEMCODEID, OFFERTYPEID, OFFERVALUE, NUMBEROFPIECES)
		SELECT IC.ITEMCODEID, OT.OFFERTYPEID, OFR.OFFERVALUE, OFR.NUMBEROFPIECES
		FROM @dtOffer OFR 
			INNER JOIN OFFERTYPE OT ON OFR.OFFERTYPE = OT.OFFERTYPECODE
			INNER JOIN ITEMCODE IC ON CAST(OFR.ITEMCODE AS VARCHAR) = IC.ITEMCODE
		WHERE ISNULL(OFR.ITEMCODE,'') != ''
			
		INSERT INTO OFFER
		(
			OFFERCODE, 
			OFFERNAME, 
			OFFERVALUE, 
			OFFERTYPEID, 
			CREATEDBY, 
			CREATEDDATE, 
			ISACTIVE, 
			APPLIESTOID, 
			BASEOFFERID
		)
		SELECT 
			@OFFERCODE + CAST((ROW_NUMBER() OVER (Order by OFFERTYPEID)) + @COUNT AS varchar(5)) AS OFFERCODE, 
			@OFFERNAME + CAST((ROW_NUMBER() OVER (Order by OFFERTYPEID)) + @COUNT AS varchar(5)) AS OFFERNAME, 
			OFFERVALUE,
			OFFERTYPEID,
			@USERID AS USERID, 
			GETDATE() AS CREATEDDATE,
			1 AS ISACTIVE,
			1 AS APPLIESTOID,
			@BASEOFFERID AS BASEOFFERID 
		FROM
		( 
			SELECT DISTINCT
				UOFR.OFFERVALUE,
				UOFR.OFFERTYPEID
			FROM #OFFERDETAILS UOFR 
			WHERE NOT EXISTS 
			(
				SELECT 1 FROM OFFER OFR
				WHERE OFR.OFFERTYPEID = UOFR.OFFERTYPEID
				 AND OFR.OFFERVALUE = UOFR.OFFERVALUE
				 AND OFR.BASEOFFERID = @BASEOFFERID
				 AND OFR.DELETEDDATE IS NULL
			)
		) AS OFR

		UPDATE UOFR SET UOFR.OFFERID = OFR.OFFERID
		FROM #OFFERDETAILS UOFR
			INNER JOIN OFFER OFR ON UOFR.OFFERTYPEID = OFR.OFFERTYPEID AND UOFR.OFFERVALUE = OFR.OFFERVALUE
		WHERE OFR.BASEOFFERID = @BASEOFFERID 
			AND OFR.DELETEDDATE IS NULL

		INSERT INTO OFFERITEMMAP(OFFERID, ITEMCODEID, CREATEDBY, CREATEDDATE, NUMBEROFPIECES)
		SELECT DISTINCT OFR.OFFERID, OFR.ITEMCODEID, @USERID, GETDATE(), OFR.NUMBEROFPIECES 
		FROM #OFFERDETAILS OFR
		WHERE NOT EXISTS
		(
			SELECT 1 FROM OFFERITEMMAP OFRM 
			WHERE OFRM.OFFERID = OFR.OFFERID 
				AND OFRM.ITEMCODEID = OFR.ITEMCODEID
				AND OFRM.DELETEDDATE IS NULL
		)
		
		INSERT INTO OFFERBRANCH(OFFERID, BRANCHID, CREATEDBY, CREATEDDATE)
		SELECT DISTINCT OFR.OFFERID, BOB.BRANCHID, @USERID, GETDATE() FROM BASEOFFERBRANCH BOB 
			INNER JOIN OFFER OFR ON BOB.BASEOFFERID = OFR.BASEOFFERID
		WHERE BOB.BASEOFFERID = @BASEOFFERID AND OFR.DELETEDDATE IS NULL AND BOB.DELETEDDATE IS NULL
			AND NOT EXISTS
			(
				SELECT 1 FROM OFFERBRANCH OB 
				WHERE OB.OFFERID = OFR.OFFERID 
					AND OB.BRANCHID = BOB.BRANCHID
					AND OB.DELETEDDATE IS NULL
			)
	SELECT @BASEOFFERID	
	COMMIT TRAN                                          
	 END TRY                                          
	 BEGIN CATCH                                          
	 SELECT ERROR_MESSAGE() AS ErrorMessage                                           
			IF(@@TRANCOUNT > 0)                                          
	   ROLLBACK TRAN                                          
	 END CATCH                             
END
GO
/****** Object:  StoredProcedure [dbo].[USP_IMP_OFFERITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_IMP_OFFERITEMS]
@OFFERID INT,
@dtItems OFFERIMPORT READONLY,
@USERID INT
AS
BEGIN

	INSERT INTO OFFERITEMMAP(OFFERID, ITEMCODEID, CREATEDBY, CREATEDDATE, NUMBEROFPIECES)
	SELECT DISTINCT @OFFERID, IC.ITEMCODEID, @USERID, GETDATE(), DI.NUMBEROFPIECES
	FROM 
		@dtItems DI
		INNER JOIN ITEMCODE IC ON CAST(DI.ITEMCODE AS VARCHAR) = IC.ITEMCODE
	WHERE NOT EXISTS
	(
		SELECT 1 
		FROM OFFERITEMMAP OIM 
		WHERE IC.ITEMCODEID = OIM.ITEMCODEID 
			AND OIM.OFFERID = @OFFERID
			AND OIM.DELETEDDATE IS NULL
	)
	AND ISNULL(DI.ITEMCODE,'') != ''

END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_AUTOGENERATEBREFUND]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_P_AUTOGENERATEBREFUND]
(
	@STOCKDISPATCHID INT,
	@COUNTERID INT,
	@UserID INT
)
AS
BEGIN

	--Creating BRefundDetail details

	CREATE TABLE #SDD(SNO INT IDENTITY(1,1) NOT NULL, ITEMPRICEID INT, TRAYNUMBER INT, REFUNDQUANTITY INT)
	INSERT INTO #SDD (ITEMPRICEID, TRAYNUMBER, REFUNDQUANTITY)
	SELECT
		SDD.ITEMPRICEID, 
		SDD.TRAYNUMBER, 
		SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY AS REFUNDQUANTITY 
	FROM
		STOCKDISPATCHDETAIL SDD
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE 
		SDD.STOCKDISPATCHID = @STOCKDISPATCHID
		AND SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY > 0
		AND SDD.DELETEDDATE IS NULL
		AND SDD.ISACCEPTED = 1
		AND ISNULL(I.ISOPENITEM, 0) = 0

	IF NOT EXISTS(SELECT 1 FROM #SDD)
	BEGIN
		RETURN;
	END

	DECLARE @ProcesingDateTime DATETIME = GETDATE()

	--Creating BRefund
	DECLARE @BRID INT, @BRANCHID INT, @CATEGORYID INT, @DISPATCHNUMBER VARCHAR(100), @WHID INT
	SELECT @WHID = FROMBRANCHID, @BRANCHID = TOBRANCHID, @CATEGORYID = CATEGORYID , @DISPATCHNUMBER = DISPATCHNUMBER
	FROM STOCKDISPATCH 
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	EXEC POS_USP_CU_BREFUND_1 @USERID ,@BRANCHID ,@CATEGORYID ,@BRID OUT, @STOCKDISPATCHID

	INSERT INTO POS_BREFUNDDETAIL(BRID,ITEMPRICEID,QUANTITY,WEIGHTINKGS,CREATEDDATE,SNO,TRAYNUMBER,REASONID,REFUNDDESCRIPTION)          
	SELECT @BRID, ITEMPRICEID,REFUNDQUANTITY,0,GETDATE(),SNO,TRAYNUMBER,3, 'REFUND CREATED FROM DISPATCH: ' + @DISPATCHNUMBER
	FROM #SDD 

	--SUBMITTING BREFUND

	EXEC POS_USP_FINISHBREFUND_1 @BRID, @BRANCHID, @WHID
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_AUTOGENERATEBREFUND_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_P_AUTOGENERATEBREFUND_1]
(
	@STOCKDISPATCHID INT,
	@COUNTERID INT,
	@UserID INT
)
AS
BEGIN

	--Creating BRefundDetail details

	CREATE TABLE #SDD(SNO INT IDENTITY(1,1) NOT NULL, ITEMPRICEID INT, TRAYNUMBER INT, REFUNDQUANTITY INT)
	INSERT INTO #SDD (ITEMPRICEID, TRAYNUMBER, REFUNDQUANTITY)
	SELECT
		SDD.ITEMPRICEID, 
		SDD.TRAYNUMBER, 
		SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY AS REFUNDQUANTITY 
	FROM
		STOCKDISPATCHDETAIL SDD
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE 
		SDD.STOCKDISPATCHID = @STOCKDISPATCHID
		AND SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY > 0
		AND SDD.DELETEDDATE IS NULL
		AND SDD.ISACCEPTED = 1
		AND ISNULL(I.ISOPENITEM, 0) = 0

	IF NOT EXISTS(SELECT 1 FROM #SDD)
	BEGIN
		RETURN;
	END

	DECLARE @ProcesingDateTime DATETIME = GETDATE()

	--Creating BRefund
	DECLARE @BRID INT, @BRANCHID INT, @CATEGORYID INT, @DISPATCHNUMBER VARCHAR(100), @WHID INT
	SELECT @WHID = FROMBRANCHID, @BRANCHID = TOBRANCHID, @CATEGORYID = CATEGORYID , @DISPATCHNUMBER = DISPATCHNUMBER
	FROM STOCKDISPATCH 
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	EXEC POS_USP_CU_BREFUND_1 @USERID ,@BRANCHID ,@CATEGORYID ,@BRID OUT, @STOCKDISPATCHID


	INSERT INTO POS_BREFUNDDETAIL(BRID,ITEMPRICEID,QUANTITY,WEIGHTINKGS,CREATEDDATE,SNO,TRAYNUMBER,REASONID,REFUNDDESCRIPTION)          
	SELECT @BRID, ITEMPRICEID, REFUNDQUANTITY, 0 ,@ProcesingDateTime ,SNO ,TRAYNUMBER,3, 'REFUND CREATED FROM DISPATCH: ' + @DISPATCHNUMBER
	FROM #SDD 

	--SUBMITTING BREFUND
	EXEC POS_USP_FINISHBREFUND_1 @BRID, @BRANCHID, @WHID
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_AUTOGENERATEDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_P_AUTOGENERATEDISPATCH]
(
	@STOCKDISPATCHID INT,
	@UserID INT
)
AS
BEGIN

	IF NOT EXISTS(SELECT 1 FROM STOCKDISPATCHDETAIL 
				WHERE STOCKDISPATCHID = @StockDispatchID 
					AND DISPATCHQUANTITY - RECEIVEDQUANTITY < 0 
					AND WEIGHTINKGS = 0
					AND DELETEDDATE IS NULL
					AND ISACCEPTED = 1)
	BEGIN
		RETURN;
	END

	DECLARE @ProcesingDateTime DATETIME = GETDATE()

	--Creating dispatch

	DECLARE @NEWSTOCKDISPATCHID INT
	INSERT INTO STOCKDISPATCH(FROMBRANCHID, TOBRANCHID, STATUS, CREATEDBY, CREATEDDATE, CATEGORYID,AUTOGENERATED, REFID, SOURCEENTITYID)
	SELECT FROMBRANCHID, TOBRANCHID, 0, @UserID, @ProcesingDateTime, CATEGORYID, 1, @STOCKDISPATCHID, 1
	FROM STOCKDISPATCH 
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID
	SET @NEWSTOCKDISPATCHID = SCOPE_IDENTITY()

		
	--Creating dispatch details

	INSERT INTO STOCKDISPATCHDETAIL(ITEMPRICEID, TRAYNUMBER, DISPATCHQUANTITY, RECEIVEDQUANTITY, WEIGHTINKGS, CREATEDDATE, ISACCEPTED, STOCKDISPATCHID)
	SELECT
		SDD.ITEMPRICEID, 
		SDD.TRAYNUMBER, 
		(SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY) * -1, 
		(SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY) * -1 ,
		SDD.WEIGHTINKGS, 
		@ProcesingDateTime,
		0, @NEWSTOCKDISPATCHID
	FROM
		STOCKDISPATCHDETAIL SDD
	WHERE 
		SDD.STOCKDISPATCHID = @STOCKDISPATCHID
		AND SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY < 0
		AND SDD.WEIGHTINKGS = 0
		AND SDD.DELETEDDATE IS NULL

	--PROCCESSING dispatch

	EXEC USP_P_STOCKDISPATCH @NEWSTOCKDISPATCHID, @UserID
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_CALCULATEAVGCP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_P_CALCULATEAVGCP] 
(
	@CalculateDate DATE = NULL
	, @SkipLastMonth BIT = 0
)
AS
BEGIN

	IF @CalculateDate IS NULL
	BEGIN
		SELECT @CalculateDate = GETDATE()
	END

	IF @SkipLastMonth = 0 AND DAY(@CalculateDate) <= 10
	BEGIN
		SELECT @CalculateDate = DATEADD(M, -1, @CalculateDate)		
	END

	SELECT @CalculateDate = DATEFROMPARTS(YEAR(@CalculateDate), MONTH(@CalculateDate), 1) -- Make it to 1st of the month
	
	DECLARE @EndDate DATE, @CurMonthDate DATE, @PrevMonthDate DATE, @PrevFYDate DATE

	CREATE TABLE #AVGCOSTPRICE
	(
		ITEMCODEID INT,
		MRP DECIMAL(18, 2),
		AVGCPDATE DATE,
		STOCKINCOSTPRICEWT DECIMAL(18, 2) DEFAULT 0,
		STOCKINCOSTPRICEWOT DECIMAL(18, 2) DEFAULT 0, 	
		STOCKINQTY DECIMAL(18, 2) DEFAULT 0,
		PREVMONCOSTPRICEWT DECIMAL(18, 2) DEFAULT 0,
		PREVMONCOSTPRICEWOT DECIMAL(18, 2) DEFAULT 0, 
		PREVMONCUMULATIVEFYQTY DECIMAL(18, 2) DEFAULT 0,
		PREVFYCOSTPRICEWT DECIMAL(18, 2) DEFAULT 0,
		PREVFYCOSTPRICEWOT DECIMAL(18, 2) DEFAULT 0, 
		COSTPRICEWT DECIMAL(18, 2) DEFAULT 0,
		COSTPRICEWOT DECIMAL(18, 2) DEFAULT 0,
		CUMULATIVEFYQTY DECIMAL(18, 2) DEFAULT 0
	)

	SELECT @CurMonthDate = @CalculateDate
	   
	WHILE @CurMonthDate <= GETDATE()
	BEGIN
	
		SELECT @EndDate = DATEADD(M, 1, @CurMonthDate)
			, @PrevMonthDate = DATEADD(M, -1, @CurMonthDate)
			, @PrevFYDate = DATEFROMPARTS(YEAR(@CurMonthDate) - CASE WHEN MONTH(@CurMonthDate) < 4 THEN 1 ELSE 0 END, 3, 1)

		TRUNCATE TABLE #AVGCOSTPRICE

		INSERT INTO #AVGCOSTPRICE(ITEMCODEID, MRP, AVGCPDATE)
		SELECT IC.ITEMCODEID, IP.MRP, @CurMonthDate
		FROM
			ITEMCODE IC WITH(NOLOCK)
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID
		--WHERE IC.ITEMCODEID = 89184 AND MRP = 555
		GROUP BY IC.ITEMCODEID, IP.MRP
		
		UPDATE TAVG
		SET 
			TAVG.PREVMONCOSTPRICEWOT = ISNULL(FAVG.COSTPRICEWOT, 0)
			, TAVG.PREVMONCOSTPRICEWT = ISNULL(FAVG.COSTPRICEWT, 0)
			, TAVG.PREVMONCUMULATIVEFYQTY = ISNULL(FAVG.CUMULATIVEFYQTY, 0)
		FROM
			#AVGCOSTPRICE TAVG
			LEFT JOIN AVGCOSTPRICE FAVG ON FAVG.ITEMCODEID = TAVG.ITEMCODEID AND FAVG.MRP = TAVG.MRP
		WHERE
			FAVG.AVGCPDATE = @PrevMonthDate 
			AND MONTH(@CurMonthDate) <> 4  -- In case of april month, do not cumulate
			AND FAVG.CUMULATIVEFYQTY > 0 -- filters out items which are not purchased in this FY


		UPDATE TAVGMAIN
		SET 
			TAVGMAIN.STOCKINCOSTPRICEWOT = TAVGINNER.STOCKINTOTALCOSTPRICEWOT / TAVGINNER.STOCKINQTY --make average
			, TAVGMAIN.STOCKINCOSTPRICEWT = TAVGINNER.STOCKINTOTALCOSTPRICEWT / TAVGINNER.STOCKINQTY --make average
			, TAVGMAIN.STOCKINQTY = TAVGINNER.STOCKINQTY 
		FROM
			#AVGCOSTPRICE TAVGMAIN
			INNER JOIN 
				(	
					SELECT TAVG.ITEMCODEID, TAVG.MRP
						, SUM(ICP.COSTPRICEWOT * (CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END)) STOCKINTOTALCOSTPRICEWOT
						, SUM(ICP.COSTPRICEWT * (CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END)) STOCKINTOTALCOSTPRICEWT
						, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END) STOCKINQTY
					FROM
						#AVGCOSTPRICE TAVG
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = TAVG.ITEMCODEID
						INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMCODEID = TAVG.ITEMCODEID AND IP.MRP = TAVG.MRP 
						INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMPRICEID = IP.ITEMPRICEID
						INNER JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
						INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
					WHERE
						IP.BRANCHID IS NULL
						AND SED.DELETEDDATE IS NULL
						AND SE.DELETEDDATE IS NULL
						AND SE.Reverted_Date IS NULL
						AND SE.STATUS <> 0
						AND SE.CREATEDDATE > @CurMonthDate
						AND SE.CREATEDDATE < @EndDate
					GROUP BY TAVG.ITEMCODEID, TAVG.MRP, I.ISOPENITEM
				) TAVGINNER ON TAVGINNER.ITEMCODEID = TAVGMAIN.ITEMCODEID AND TAVGINNER.MRP = TAVGMAIN.MRP
		WHERE TAVGINNER.STOCKINQTY > 0

		
		UPDATE TAVG
		SET TAVG.PREVFYCOSTPRICEWOT = ISNULL(FAVG.COSTPRICEWOT, 0), TAVG.PREVFYCOSTPRICEWT = ISNULL(FAVG.COSTPRICEWT, 0)
		FROM
			#AVGCOSTPRICE TAVG
			LEFT JOIN AVGCOSTPRICE FAVG ON FAVG.ITEMCODEID = TAVG.ITEMCODEID AND FAVG.MRP = TAVG.MRP
		WHERE
			FAVG.AVGCPDATE = @PrevFYDate
			AND TAVG.STOCKINQTY = 0 -- filter out current FY purchased items
							
		--Child price
		UPDATE CAVG
		SET
			CAVG.STOCKINCOSTPRICEWOT = ((PAVG.STOCKINCOSTPRICEWOT * UOM.MULTIPLIER) / (100 + (GST.CGST + GST.SGST + GST.CESS))) * 100
			, CAVG.STOCKINCOSTPRICEWT = PAVG.STOCKINCOSTPRICEWT * UOM.MULTIPLIER
			, CAVG.PREVFYCOSTPRICEWOT = ((PAVG.PREVFYCOSTPRICEWOT * UOM.MULTIPLIER) / (100 + (GST.CGST + GST.SGST + GST.CESS))) * 100
			, CAVG.PREVFYCOSTPRICEWT = PAVG.PREVFYCOSTPRICEWT * UOM.MULTIPLIER
			, CAVG.STOCKINQTY = 1
		FROM 
			#AVGCOSTPRICE CAVG
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = CAVG.ITEMCODEID
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
			INNER JOIN UOM UOM ON UOM.UOMID = I.UOMID
			INNER JOIN ITEMCODE PIC WITH(NOLOCK) ON PIC.ITEMID = I.PARENTITEMID
			INNER JOIN
				(
					SELECT 
						PAVGINNER.ITEMCODEID, PAVGINNER.PREVFYCOSTPRICEWOT, PAVGINNER.PREVFYCOSTPRICEWT
						, SUM(PAVGINNER.STOCKINCOSTPRICEWOT * PAVGINNER.STOCKINQTY) / SUM(PAVGINNER.STOCKINQTY) STOCKINCOSTPRICEWOT
						, SUM(PAVGINNER.STOCKINCOSTPRICEWT * PAVGINNER.STOCKINQTY) / SUM(PAVGINNER.STOCKINQTY) STOCKINCOSTPRICEWT					 
					FROM #AVGCOSTPRICE PAVGINNER 
					WHERE PAVGINNER.STOCKINQTY > 0				
					GROUP BY PAVGINNER.ITEMCODEID, PAVGINNER.PREVFYCOSTPRICEWOT, PAVGINNER.PREVFYCOSTPRICEWT				
				) PAVG ON PAVG.ITEMCODEID = PIC.ITEMCODEID
			LEFT JOIN GSTDETAIL GST ON GST.GSTID = I.GSTID
		WHERE 
			I.PARENTITEMID IS NOT NULL
			AND I.ITEMID <> I.PARENTITEMID
		
	
		UPDATE TAVG
		SET 
			TAVG.COSTPRICEWOT = CASE WHEN TAVG.STOCKINQTY = 0 AND TAVG.PREVMONCUMULATIVEFYQTY = 0 THEN TAVG.PREVFYCOSTPRICEWOT 
				ELSE ((TAVG.STOCKINQTY *  TAVG.STOCKINCOSTPRICEWOT) + (TAVG.PREVMONCUMULATIVEFYQTY * TAVG.PREVMONCOSTPRICEWOT)) / (TAVG.STOCKINQTY + TAVG.PREVMONCUMULATIVEFYQTY) END
			, TAVG.COSTPRICEWT = CASE WHEN TAVG.STOCKINQTY = 0 AND TAVG.PREVMONCUMULATIVEFYQTY = 0 THEN TAVG.PREVFYCOSTPRICEWT 
				ELSE ((TAVG.STOCKINQTY *  TAVG.STOCKINCOSTPRICEWT) + (TAVG.PREVMONCUMULATIVEFYQTY * TAVG.PREVMONCOSTPRICEWT)) / (TAVG.STOCKINQTY + TAVG.PREVMONCUMULATIVEFYQTY) END
			, TAVG.CUMULATIVEFYQTY = TAVG.STOCKINQTY + TAVG.PREVMONCUMULATIVEFYQTY --cumulate sum by FY
		FROM #AVGCOSTPRICE TAVG

		DELETE FAVG
		FROM #AVGCOSTPRICE FAVG WITH(NOLOCK)
		WHERE 
			STOCKINCOSTPRICEWT = 0
			AND STOCKINCOSTPRICEWOT	= 0
			AND STOCKINQTY = 0
			AND PREVFYCOSTPRICEWT = 0
			AND PREVFYCOSTPRICEWOT = 0
			AND COSTPRICEWT	= 0
			AND COSTPRICEWOT = 0

		UPDATE FYAVG
		SET 
			FYAVG.STOCKINCOSTPRICEWT    = TAVG.STOCKINCOSTPRICEWT
			, FYAVG.STOCKINCOSTPRICEWOT = TAVG.STOCKINCOSTPRICEWOT
			, FYAVG.STOCKINQTY			= TAVG.STOCKINQTY
			, FYAVG.PREVMONCOSTPRICEWT = TAVG.PREVMONCOSTPRICEWT
			, FYAVG.PREVMONCOSTPRICEWOT = TAVG.PREVMONCOSTPRICEWOT
			, FYAVG.PREVMONCUMULATIVEFYQTY = TAVG.PREVMONCUMULATIVEFYQTY
			, FYAVG.PREVFYCOSTPRICEWT		= TAVG.PREVFYCOSTPRICEWT
			, FYAVG.PREVFYCOSTPRICEWOT	= TAVG.PREVFYCOSTPRICEWOT
			, FYAVG.COSTPRICEWT			= TAVG.COSTPRICEWT
			, FYAVG.COSTPRICEWOT		= TAVG.COSTPRICEWOT
			, FYAVG.CUMULATIVEFYQTY		= TAVG.CUMULATIVEFYQTY
		FROM
			AVGCOSTPRICE FYAVG
			INNER JOIN #AVGCOSTPRICE TAVG ON 
				TAVG.ITEMCODEID = FYAVG.ITEMCODEID
				AND TAVG.MRP = FYAVG.MRP
				AND TAVG.AVGCPDATE = FYAVG.AVGCPDATE
				
		INSERT INTO AVGCOSTPRICE(ITEMCODEID, MRP, AVGCPDATE
			, STOCKINCOSTPRICEWT, STOCKINCOSTPRICEWOT, STOCKINQTY -- Current month
			, PREVMONCOSTPRICEWT, PREVMONCOSTPRICEWOT, PREVMONCUMULATIVEFYQTY -- previous month
			, PREVFYCOSTPRICEWT, PREVFYCOSTPRICEWOT  -- previous year
			, COSTPRICEWT, COSTPRICEWOT, CUMULATIVEFYQTY) -- final CP
		SELECT 
			TAVG.ITEMCODEID, TAVG.MRP, TAVG.AVGCPDATE
			, TAVG.STOCKINCOSTPRICEWT, TAVG.STOCKINCOSTPRICEWOT, TAVG.STOCKINQTY
			, TAVG.PREVMONCOSTPRICEWT, TAVG.PREVMONCOSTPRICEWOT, TAVG.PREVMONCUMULATIVEFYQTY
			, TAVG.PREVFYCOSTPRICEWT, TAVG.PREVFYCOSTPRICEWOT
			, TAVG.COSTPRICEWT, TAVG.COSTPRICEWOT, TAVG.CUMULATIVEFYQTY
		FROM
			#AVGCOSTPRICE TAVG
		WHERE NOT EXISTS
			(
				SELECT 1
				FROM AVGCOSTPRICE MAVG
				WHERE
					MAVG.ITEMCODEID = TAVG.ITEMCODEID
				AND MAVG.MRP = TAVG.MRP
				AND MAVG.AVGCPDATE = TAVG.AVGCPDATE
			)

		SELECT @CurMonthDate = @EndDate
		

	END

	DROP TABLE #AVGCOSTPRICE	

	DECLARE @NextDay DATE
	SELECT @NextDay = DATEADD(d, 1, @CalculateDate)

	IF @SkipLastMonth = 0 AND MONTH(@CalculateDate) <> MONTH(@NextDay) -- Month changing next day
	BEGIN
		EXEC [USP_P_CALCULATEAVGCP] @NextDay, 1
	END

END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_DAYCLOSURES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[USP_P_DAYCLOSURES]  
AS  
BEGIN  
  
	SELECT TOP(1) DCL.BRANCHCOUNTERID, DCL.DAYCLOSUREID  
	INTO #DayClosuresToProcess  
	FROM  
		POS_DAYCLOSURE DCL  
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = DCL.BRANCHCOUNTERID
		INNER JOIN  
			(  
				SELECT PBD.BRANCHCOUNTERID, PBD.DAYCLOSUREID, COUNT(1) NOOFBILLDETAILRECS FROM POS_BILLDETAIL PBD   
				GROUP BY PBD.BRANCHCOUNTERID, PBD.DAYCLOSUREID  
			) BD ON BD.BRANCHCOUNTERID = DCL.BRANCHCOUNTERID AND BD.DAYCLOSUREID = DCL.DAYCLOSUREID  
		INNER JOIN  
			(  
				SELECT PBD.BRANCHCOUNTERID, PBD.DAYCLOSUREID, COUNT(1) NOOFBILLRECS FROM POS_BILL PBD   
				GROUP BY PBD.BRANCHCOUNTERID, PBD.DAYCLOSUREID  
			) B ON B.BRANCHCOUNTERID = DCL.BRANCHCOUNTERID AND B.DAYCLOSUREID = DCL.DAYCLOSUREID  
		LEFT JOIN  
			(  
				SELECT PBD.COUNTERID, PBD.DAYCLOSUREID, COUNT(1) NOOFCREFUNDRECS FROM POS_CREFUND PBD   
				GROUP BY PBD.COUNTERID, PBD.DAYCLOSUREID  
			) CRF ON CRF.COUNTERID = DCL.BRANCHCOUNTERID AND CRF.DAYCLOSUREID = DCL.DAYCLOSUREID  
	WHERE   
		ISNULL(DCL.ISPROCESSED, 0) = 0   
		AND DCL.BILLCOUNT = B.NOOFBILLRECS  
		AND DCL.BILLDETAILCOUNT = BD.NOOFBILLDETAILRECS  
		AND DCL.CREFUNDCOUNT = ISNULL(CRF.NOOFCREFUNDRECS, 0)  
	ORDER BY BC.BRANCHID
  
	UPDATE DCL  
	SET DCL.ISPROCESSED = 1, PROCESSEDTIME = GETDATE()  
	FROM  
		POS_DAYCLOSURE DCL  
		INNER JOIN #DayClosuresToProcess DCLTPR ON DCLTPR.DAYCLOSUREID = DCL.DAYCLOSUREID  
		AND DCLTPR.BRANCHCOUNTERID = DCL.BRANCHCOUNTERID  

	SELECT         
		BC.BRANCHID  
		, ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID) ITEMPRICEID
		, BD.QUANTITY, BD.WEIGHTINKGS
	INTO #SALES
	FROM         
		POS_BILLDETAIL BD        
		INNER JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID    
		INNER JOIN POS_BILL B ON BD.BILLID = B.BILLID   
			AND BD.BRANCHCOUNTERID = B.BRANCHCOUNTERID AND B.DAYCLOSUREID = BD.DAYCLOSUREID  
		INNER JOIN #DayClosuresToProcess UDC ON B.DAYCLOSUREID = UDC.DAYCLOSUREID   
			AND B.BRANCHCOUNTERID = UDC.BRANCHCOUNTERID        
		INNER JOIN BRANCHCOUNTER BC ON B.BRANCHCOUNTERID = BC.COUNTERID
	WHERE        
		B.DELETEDDATE IS NULL   
		AND BD.DELETEDDATE IS NULL   
		AND B.BILLSTATUS = 1     
			
	UPDATE SALES
	SET SALES.ITEMPRICEID = IP.STOCKMOVETOID
	FROM
		#SALES SALES
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SALES.ITEMPRICEID
	WHERE IP.STOCKMOVETOID IS NOT NULL

	MERGE STOCKSUMMARY AS Target          
	USING         
	(        
		SELECT         
			SALES.BRANCHID  
			, SALES.ITEMPRICEID  
			, SUM(SALES.QUANTITY) AS QUANTITY  
			, SUM(SALES.WEIGHTINKGS) AS WEIGHTINKGS   
			, GETDATE() AS MODIFIEDDATE
		FROM #SALES SALES		   
		GROUP BY SALES.BRANCHID, SALES.ITEMPRICEID
	) AS Source                
		ON Source.BRANCHID = Target.BRANCHID AND Source.ITEMPRICEID = Target.ITEMPRICEID    
                    
	WHEN MATCHED THEN UPDATE  
	SET                
		Target.QUANTITY = ISNULL(Target.QUANTITY,0) - ISNULL(Source.QUANTITY,0),                
		Target.WEIGHTINKGS = ISNULL(Target.WEIGHTINKGS,0) - ISNULL(Source.WEIGHTINKGS,0),  
		Target.TTYPE = 'BS', Target.MODIFIEDDATE = Source.MODIFIEDDATE ;        
    
	SELECT         
		BC.BRANCHID  
		, ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID) AS ITEMPRICEID  
		, CR.REFUNDQUANTITY AS QUANTITY  
		, CR.REFUNDWEIGHTINKGS AS WEIGHTINKGS 
	INTO #REFUNDS
	FROM         
		POS_CREFUND CR        
		INNER JOIN POS_BILLDETAIL BD ON CR.BILLDETAILID = BD.BILLDETAILID   
			AND CR.COUNTERID = BD.BRANCHCOUNTERID    
		INNER JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID    
		INNER JOIN #DayClosuresToProcess UDC ON CR.DAYCLOSUREID = UDC.DAYCLOSUREID    
			AND CR.COUNTERID = UDC.BRANCHCOUNTERID        
		INNER JOIN BRANCHCOUNTER BC ON CR.COUNTERID = BC.COUNTERID        
			AND CR.DELETEDDATE IS NULL  
		INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
	

	UPDATE REFUNDS
	SET REFUNDS.ITEMPRICEID = IP.STOCKMOVETOID
	FROM
		#REFUNDS REFUNDS
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = REFUNDS.ITEMPRICEID
	WHERE IP.STOCKMOVETOID IS NOT NULL

	MERGE STOCKSUMMARY AS Target          
	USING         
	(        
		SELECT         
			REFUNDS.BRANCHID  
			, REFUNDS.ITEMPRICEID  
			, SUM(REFUNDS.QUANTITY) AS QUANTITY  
			, SUM(REFUNDS.WEIGHTINKGS) AS WEIGHTINKGS 
			, GETDATE() AS MODIFIEDDATE
		FROM         
			#REFUNDS REFUNDS
		GROUP BY REFUNDS.BRANCHID, REFUNDS.ITEMPRICEID
	) AS Source                
	ON Source.BRANCHID = Target.BRANCHID AND Source.ITEMPRICEID = Target.ITEMPRICEID  
                    
	WHEN MATCHED THEN UPDATE   
	SET                
		Target.QUANTITY = ISNULL(Target.QUANTITY,0) + ISNULL(Source.QUANTITY,0),                
		Target.WEIGHTINKGS = ISNULL(Target.WEIGHTINKGS,0) + ISNULL(Source.WEIGHTINKGS,0),  
		Target.TTYPE = 'CR', Target.MODIFIEDDATE = Source.MODIFIEDDATE ;        
        
   
  
	UPDATE BC      
	SET       
		BC.DAYCLOSUREID = MAXDC.MAXDAYCLOSUREID      
		, UPDATEDDATE = GETDATE()      
	FROM       
		BRANCHCOUNTER BC      
		INNER JOIN       
			(      
				SELECT DC.BRANCHCOUNTERID, MAX(DC.DAYCLOSUREID) AS MAXDAYCLOSUREID       
				FROM #DayClosuresToProcess DC       
				GROUP BY DC.BRANCHCOUNTERID      
			) MAXDC ON MAXDC.BRANCHCOUNTERID = BC.COUNTERID      
	WHERE ISNULL(BC.DAYCLOSUREID, 0) < MAXDC.MAXDAYCLOSUREID      
  
	SELECT COUNT(1) FROM #DayClosuresToProcess  
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_DISCOUNTSALECODES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_P_DISCOUNTSALECODES]
    @data IMPORTSD READONLY,
    @BRANCHID INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE 
        @CREATEDDATE DATETIME = GETDATE(),
        @ERROR_MSG NVARCHAR(MAX) = ''

        CREATE TABLE #DATA
        (
            ITEMCODE NVARCHAR(100), 
            MRP DECIMAL(18,2), 
            OLDSALEPRICE DECIMAL(18,2), 
            NEWSALEPRICE DECIMAL(18,2), 
            QUANTITY INT, 
            WEIGHTINKGS DECIMAL(18,2),
            NEWITEMCODE NVARCHAR(100),
            OLDITEMCODEID INT,
            OLDITEMPRICEID INT,
            PREVQUANTITY INT,
            PREVWEIGHTINKGS DECIMAL(18,2)
        );

        -- Load input data
        INSERT INTO #DATA (ITEMCODE, MRP, OLDSALEPRICE, NEWSALEPRICE, QUANTITY, WEIGHTINKGS,PREVQUANTITY, PREVWEIGHTINKGS)
        SELECT ITEMCODE, MRP, OLDSALEPRICE, NEWSALEPRICE, QUANTITY, WEIGHTINKGS, 0, 0
        FROM @data;

        -- Generate new item codes
        UPDATE #DATA SET NEWITEMCODE = 'V' + ITEMCODE;

        -- Check if any new item codes already exist
        IF EXISTS (
            SELECT 1
            FROM ITEMCODE IC
            INNER JOIN #DATA DT ON IC.ITEMCODE = DT.NEWITEMCODE
        )
        BEGIN
            SET @ERROR_MSG = 'Few items already have discount sale codes. Please check "Already Exists" column.';
        END

        -- Map to old item code IDs
        UPDATE DT
        SET DT.OLDITEMCODEID = IC.ITEMCODEID
        FROM #DATA DT
        INNER JOIN ITEMCODE IC ON DT.ITEMCODE = IC.ITEMCODE
        WHERE IC.DELETEDDATE IS NULL;

        -- Map to old item price IDs
        UPDATE DT
        SET DT.OLDITEMPRICEID = IP.ITEMPRICEID
        FROM #DATA DT
        INNER JOIN ITEMPRICE IP ON DT.OLDITEMCODEID = IP.ITEMCODEID 
                                AND DT.MRP = IP.MRP 
                                AND DT.OLDSALEPRICE = IP.SALEPRICE
        WHERE IP.DELETEDDATE IS NULL 
          AND IP.BRANCHID IS NULL;

        -- Fetch previous stock summary
        UPDATE DT
        SET DT.PREVQUANTITY = SS.QUANTITY,
            DT.PREVWEIGHTINKGS = SS.WEIGHTINKGS
        FROM #DATA DT
        INNER JOIN STOCKSUMMARY SS 
            ON DT.OLDITEMPRICEID = SS.ITEMPRICEID 
           AND SS.BRANCHID = @BRANCHID

        -- Validation: compare new and previous quantities
        IF EXISTS (
            SELECT 1
            FROM #DATA DT
            INNER JOIN ITEMCODE IC ON DT.OLDITEMCODEID = IC.ITEMCODEID
            INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
            WHERE 
                (I.ISOPENITEM = 0 AND DT.PREVQUANTITY = 0)
                OR (I.ISOPENITEM = 1 AND DT.PREVWEIGHTINKGS = 0)
                OR (DT.QUANTITY - DT.PREVQUANTITY) > 0
                OR (DT.WEIGHTINKGS - DT.PREVWEIGHTINKGS) > 0
        )
        BEGIN
            IF @ERROR_MSG <> ''
				SET @ERROR_MSG = @ERROR_MSG + CHAR(13) + CHAR(10);
        
		SET @ERROR_MSG = @ERROR_MSG + 'New quantity and previous quantity/weight mismatch for few items.';
        END

        -- Final output
        SELECT 
            DT.*,
            I.ITEMNAME,
            CASE WHEN IC.ITEMCODEID IS NOT NULL THEN 'YES' ELSE 'NO' END AS ALREADYEXISTS
        FROM #DATA DT
        INNER JOIN ITEMCODE ICOLD ON DT.ITEMCODE = ICOLD.ITEMCODE
        INNER JOIN ITEM I ON ICOLD.ITEMID = I.ITEMID
        LEFT JOIN ITEMCODE IC ON DT.NEWITEMCODE = IC.ITEMCODE;

		IF(@ERROR_MSG <> '')
			SELECT @ERROR_MSG
END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_DISPATCHFTBRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_P_DISPATCHFTBRANCH]
(
	@BranchID INT,
	@PickListTrayIDs VARCHAR(MAX),
	@UserID INT
)
AS
BEGIN

	SELECT Item AS PICKLISTTRAYID, 0 AS TRAYINFOID INTO #PICKLISTTRAYIDS FROM dbo.SplitString(@PickListTrayIDs,',')
	
	IF EXISTS 
		(
			SELECT 1
			FROM 
				PICKLISTTRAY PLT
				INNER JOIN #PICKLISTTRAYIDS PLTINPUT ON PLTINPUT.PICKLISTTRAYID = PLT.PICKLISTTRAYID
			WHERE
				PLT.DELETEDDATE IS NOT NULL
				OR PLT.ISTRAYVERIFIED = 0
				OR PLT.ISDISPATCHED = 1
		)
	BEGIN

		THROW 50001, 'One or more trays in selected list is either deleted or already dispatch, The operation is cancelled', 1
		RETURN

	END

	DECLARE @CategoryID INT, @SubCategoryID INT, @StockDispatchID INT

	--find category id on fly but better to pass from ui next
	-- hard code subcategoryid
	SELECT 
		TOP 1 @CategoryID = PLT.CATEGORYID
		, @SubCategoryID = CASE WHEN PLT.CATEGORYID = 3 THEN 129 WHEN PLT.CATEGORYID = 4 THEN 132 ELSE NULL END
	FROM 
		PICKLISTTRAY PLT 
		INNER JOIN #PICKLISTTRAYIDS PLTINPUT ON PLTINPUT.PICKLISTTRAYID = PLT.PICKLISTTRAYID

	INSERT INTO STOCKDISPATCH(FROMBRANCHID, TOBRANCHID, STATUS, CREATEDBY, CREATEDDATE, CATEGORYID, SUBCATEGORYID)
	SELECT 45, @BranchID, 0, @UserID, GETDATE(), @CategoryID, @SubCategoryID

	SELECT @StockDispatchID = SCOPE_IDENTITY()

	INSERT INTO TRAYINFO(STOCKDISPATCHID, TRAYNUMBER, ISACCEPTED, CREATEDBY, CREATEDATE)
	SELECT @StockDispatchID, PLT.TRAYNUMBER, 0, @UserID, GETDATE()
	FROM
		#PICKLISTTRAYIDS PLTID
		INNER JOIN PICKLISTTRAY PLT ON PLT.PICKLISTTRAYID = PLTID.PICKLISTTRAYID

	UPDATE PLTID
	SET PLTID.TRAYINFOID = TI.TRAYINFOID
	FROM
		#PICKLISTTRAYIDS PLTID
		INNER JOIN PICKLISTTRAY PLT ON PLT.PICKLISTTRAYID = PLTID.PICKLISTTRAYID
		INNER JOIN TRAYINFO TI ON TI.TRAYNUMBER = PLT.TRAYNUMBER
	WHERE TI.STOCKDISPATCHID = @StockDispatchID

	INSERT INTO STOCKDISPATCHDETAIL(STOCKDISPATCHID, ITEMPRICEID, TRAYNUMBER, DISPATCHQUANTITY, RECEIVEDQUANTITY, WEIGHTINKGS, CREATEDDATE, TRAYINFOID, ISVERIFIED, ISTRAYVERIFIED)
	SELECT @StockDispatchID, IP.ITEMPRICEID, PLT.TRAYNUMBER, PLID.QUANTITY, PLID.QUANTITY, 0.00, GETDATE(), PLTID.TRAYINFOID, 0, 0
	FROM
		#PICKLISTTRAYIDS PLTID
		INNER JOIN PICKLISTTRAY PLT ON PLT.PICKLISTTRAYID = PLTID.PICKLISTTRAYID
		INNER JOIN PICKLISTITEMDETAIL PLID ON PLID.PICKLISTTRAYID = PLT.PICKLISTTRAYID
		INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTITEMID = PLID.PICKLISTITEMID		
		INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = PLI.ITEMCODEID AND IP.MRP = PLI.MRP
	WHERE
		PLID.DELETEDDATE IS NULL
		AND PLI.DELETEDDATE IS NULL
		AND IP.DELETEDDATE IS NULL
		AND IP.BRANCHID IS NULL
		
	EXEC USP_U_STOCKDISPATCH @StockDispatchID, @BranchID

	UPDATE PLTMAIN
	SET ISDISPATCHED = 1
	FROM
		PICKLISTTRAY PLTMAIN
		INNER JOIN #PICKLISTTRAYIDS PLT ON PLT.PICKLISTTRAYID = PLTMAIN.PICKLISTTRAYID

END
GO
