CREATE PROC [dbo].[USP_P_GSTUPDATE]  
AS  
BEGIN  
  
SELECT 'YOU CANNOT RUN THIS PROC AS IT IS DANGER'  
RETURN;  
  
SELECT * FROM GSTUpdate_23092025 GSTU   
INNER JOIN ITEM I ON GSTU.SKUCODE = I.SKUCODE  
INNER JOIN GSTDETAIL GSTOLD ON GSTU.OldGSTCode = GSTOLD.GSTCODE  
INNER JOIN GSTDETAIL GSTNEW ON GSTU.NewGSTCode = GSTNEW.GSTCODE  
WHERE I.DELETEDDATE IS NULL  
  
ALTER TABLE GSTUpdate_23092025  
ADD OldGSTID INT  
  
ALTER TABLE GSTUpdate_23092025  
ADD NewGSTID INT  
  
ALTER TABLE GSTUpdate_23092025  
ADD ITEMID INT  
  
UPDATE GSTU   
SET GSTU.OldGSTID = GSTOLD.GSTID,  
GSTU.NewGSTID = GSTNEW.GSTID,  
GSTU.ITEMID = I.ITEMID  
FROM GSTUpdate_23092025 GSTU   
INNER JOIN ITEM I ON GSTU.SKUCODE = I.SKUCODE  
INNER JOIN GSTDETAIL GSTOLD ON GSTU.OldGSTCode = GSTOLD.GSTCODE  
INNER JOIN GSTDETAIL GSTNEW ON GSTU.NewGSTCode = GSTNEW.GSTCODE  
WHERE I.DELETEDDATE IS NULL  
  
SELECT IP.*, GSTU.NewGSTID, 0 AS NEWITEMPRICEID  
INTO IPGSTUpdate_23092025  
FROM GSTUpdate_23092025 GSTU   
INNER JOIN ITEMCODE IC ON GSTU.ITEMID = IC.ITEMID  
INNER JOIN ITEMPRICE IP ON IC.ITEMCODEID = IP.ITEMCODEID  
WHERE IC.DELETEDDATE IS NULL AND IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL  
  
SELECT * FROM IPGSTUpdate_23092025
  
  
INSERT INTO ITEMPRICE(ITEMCODEID, MRP, SALEPRICE, GSTID, CREATEDBY, CREATEDDATE, [IMMEDIATE])  
SELECT GSTU.ITEMCODEID, GSTU.MRP, GSTU.SALEPRICE, GSTU.NewGSTID,4,GETDATE(),1  
FROM IPGSTUpdate_23092025 GSTU  
  
declare @latestdate datetime  
select top(1) @latestdate = CREATEDDATE from ITEMPRICE order by ITEMPRICEID desc  
  
SELECT IP.*, GSTU.NewGSTID, 0 AS NEWITEMPRICEID  
FROM IPGSTUpdate_23092025 GSTU   
INNER JOIN ITEMPRICE IP ON GSTU.ITEMCODEID = IP.ITEMCODEID AND GSTU.MRP = IP.MRP AND GSTU.SALEPRICE = IP.SALEPRICE  
WHERE IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL AND IP.CREATEDDATE = @latestdate  
  
UPDATE GSTU   
SET NEWITEMPRICEID = IP.ITEMPRICEID  
FROM IPGSTUpdate_23092025 GSTU   
INNER JOIN ITEMPRICE IP ON GSTU.ITEMCODEID = IP.ITEMCODEID AND GSTU.MRP = IP.MRP AND GSTU.SALEPRICE = IP.SALEPRICE  
WHERE IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL AND IP.CREATEDDATE = @latestdate  
  
select * from IPGSTUpdate_23092025
  
SELECT * FROM   
(  
 SELECT GSTU.ITEMPRICEID, GSTU.NEWITEMPRICEID, MAX(ITEMCOSTPRICEID) AS ITEMCOSTPRICEID  
  FROM IPGSTUpdate_23092025 GSTU   
 INNER JOIN ITEMCOSTPRICE ICP ON GSTU.ITEMPRICEID = ICP.ITEMPRICEID  
 WHERE ICP.DELETEDDATE IS NULL  
 GROUP BY GSTU.ITEMPRICEID, GSTU.NEWITEMPRICEID  
) ICPINNER   
INNER JOIN ITEMCOSTPRICE ICP ON ICPINNER .ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID   
  
INSERT INTO ITEMCOSTPRICE(ITEMPRICEID,COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,CREATEDBY,CREATEDDATE)  
SELECT ICPINNER.NEWITEMPRICEID, COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,4,GETDATE() FROM   
(  
 SELECT GSTU.ITEMPRICEID, GSTU.NEWITEMPRICEID, MAX(ITEMCOSTPRICEID) AS ITEMCOSTPRICEID  
  FROM IPGSTUpdate_23092025 GSTU   
 INNER JOIN ITEMCOSTPRICE ICP ON GSTU.ITEMPRICEID = ICP.ITEMPRICEID  
 WHERE ICP.DELETEDDATE IS NULL  
 GROUP BY GSTU.ITEMPRICEID, GSTU.NEWITEMPRICEID  
) ICPINNER   
INNER JOIN ITEMCOSTPRICE ICP ON ICPINNER .ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID   
  
  
INSERT INTO STOCKMOVE(OLDITEMPRICEID, NEWITEMPRICEID, STOCKADJUSTMENTTYPEID, GOLIVEDATE, CREATEDBY, CREATEDDATE, REASON)  
SELECT ITEMPRICEID, NEWITEMPRICEID, 6, NULL, 4, GETDATE(), 'GST update by GOVT' FROM IPGSTUpdate_23092025  
  
select * from STOCKMOVE  
  
END
GO
