/****** Object:  StoredProcedure [dbo].[USP_P_LEFTSALEDISPATCH_BRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_P_LEFTSALEDISPATCH_BRANCH]
(
	@UserID INT
	, @LeftBranchID INT
)
AS
BEGIN

	DECLARE @WarehouseID INT = 45, @StockDispatchID INT, @ProcesingDateTime DATETIME
	
	SELECT
		SS.ITEMPRICEID, I.ISOPENITEM, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END * -1 AS WEIGHTINKGS
		, CASE WHEN I.ISOPENITEM <> 1 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END * -1 AS QUANTITY, I.CATEGORYID
	INTO #STOCKDISPATCHDETAIL
	FROM
		STOCKSUMMARY SS
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE 
		SS.BRANCHID = @LeftBranchID
		AND CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END < 0

	IF NOT EXISTS ( SELECT 1 FROM #STOCKDISPATCHDETAIL)
	BEGIN
		SELECT 'No sale items to process'
		RETURN
	END

	SELECT 'Found sale items : ' + CAST(COUNT(1) AS VARCHAR(10))
	FROM #STOCKDISPATCHDETAIL

	SELECT 'Found categories: ' 

	SELECT DISTINCT CAT.CATEGORYNAME
	FROM 
		#STOCKDISPATCHDETAIL SDD
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = SDD.CATEGORYID
	GROUP BY CAT.CATEGORYNAME

	SELECT @ProcesingDateTime = GETDATE()

	SELECT 'Creating dispatches' 

	INSERT INTO STOCKDISPATCH(FROMBRANCHID, TOBRANCHID, STATUS, CREATEDBY, CREATEDDATE, CATEGORYID)
	SELECT DISTINCT @WarehouseID, @LeftBranchID, 0, @UserID, @ProcesingDateTime, CATEGORYID
	FROM #STOCKDISPATCHDETAIL
		

	SELECT 'Creating dispatch details' 

	INSERT INTO STOCKDISPATCHDETAIL(ITEMPRICEID, TRAYNUMBER, DISPATCHQUANTITY, RECEIVEDQUANTITY, WEIGHTINKGS, CREATEDDATE, ISACCEPTED, STOCKDISPATCHID)
	SELECT SDD.ITEMPRICEID, 0, SDD.QUANTITY, SDD.QUANTITY, SDD.WEIGHTINKGS, @ProcesingDateTime, 0, SD.STOCKDISPATCHID
	FROM 
		#STOCKDISPATCHDETAIL SDD
		INNER JOIN STOCKDISPATCH SD ON SD.CREATEDDATE = @ProcesingDateTime AND SD.CATEGORYID = SDD.CATEGORYID
	WHERE 
		SD.FROMBRANCHID = @WarehouseID
		AND SD.TOBRANCHID = @LeftBranchID

	SELECT 'Processing dispatches' 

	WHILE EXISTS( SELECT 1 FROM STOCKDISPATCH SD WHERE SD.CREATEDDATE = @ProcesingDateTime AND SD.STATUS = 0 AND SD.TOBRANCHID = @LeftBranchID AND SD.CREATEDBY = @UserID)
	BEGIN

		SELECT @StockDispatchID = SD.STOCKDISPATCHID 
		FROM STOCKDISPATCH SD 
		WHERE 
			SD.CREATEDDATE = @ProcesingDateTime 
			AND SD.STATUS = 0 
			AND SD.TOBRANCHID = @LeftBranchID 
			AND SD.CREATEDBY = @UserID

		SELECT 
			'Processing dipatch for category : ' + CAT.CATEGORYNAME + ' with dispatch ID : ' + CAST(@StockDispatchID AS VARCHAR(10))
		FROM 
			STOCKDISPATCH SD 
			INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = SD.CATEGORYID
		WHERE SD.STOCKDISPATCHID  = @StockDispatchID

		EXEC USP_U_STOCKDISPATCH @StockDispatchID

		-- PROCCESSING STOCKDISPATCH
		EXEC USP_P_STOCKDISPATCH @StockDispatchID, @UserID

		SELECT 
			'Processing dipatch completed for category : ' + CAT.CATEGORYNAME + ' with dispatch ID : ' 
			+ CAST(@StockDispatchID AS VARCHAR(10)) + ' AND dispatch # ' + SD.DISPATCHNUMBER
		FROM 
			STOCKDISPATCH SD 
			INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = SD.CATEGORYID
		WHERE SD.STOCKDISPATCHID  = @StockDispatchID

	END

	SELECT 'Updating dispatch status to completed'

	SELECT SD.STOCKDISPATCHID, SD.DISPATCHNUMBER
	FROM STOCKDISPATCH SD 
	WHERE 
		SD.CREATEDDATE = @ProcesingDateTime 
		AND SD.STATUS = 2 
		AND SD.TOBRANCHID = @LeftBranchID 
		AND SD.CREATEDBY = @UserID
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_STOCKDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
