CREATE PROCEDURE [dbo].[USP_P_STOCKDISPATCH]
@STOCKDISPATCHID INT,
@UserID INT
AS
BEGIN

	--Submitting dispatch

	EXEC USP_U_STOCKDISPATCH @STOCKDISPATCHID

	--Accepting dispatch

	DECLARE @DispatchDetails POS_FINSIH_STOCKDISPATCHDETAIL
	INSERT INTO @DispatchDetails(STOCKSUMMARYTRANSITID, STOCKDISPATCHDETAILID,RECEIVEDQUANTITY)
		SELECT   
			0, 
			SDD.STOCKDISPATCHDETAILID, 
			SDD.RECEIVEDQUANTITY AS RECEIVEDQUANTITY
		FROM STOCKDISPATCHDETAIL SDD  
		WHERE SDD.STOCKDISPATCHID = @STOCKDISPATCHID
			AND SDD.DELETEDDATE IS NULL

	EXEC POS_USP_FINISH_STOCKIN @UserID, @STOCKDISPATCHID, @DispatchDetails

END
GO
/****** Object:  StoredProcedure [dbo].[USP_P_STOCKMOVE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_P_STOCKMOVE]
(
	@StockMoveToID INT = 0
)
AS
BEGIN
	
	SELECT * 
	INTO #STOCKMOVE
	FROM STOCKMOVE SM
	WHERE SM.MOVESTATUS = 0 AND ISNULL(SM.GOLIVEDATE, GETDATE()) <= GETDATE() AND DELETEDDATE IS NULL
	
	CREATE TABLE #STOCKADJUSTMENT
		(ITEMPRICEID INT, BRANCHID INT, QUANTITY INT, WEIGHTINKGS DECIMAL(18, 2), PREVQUANTITY INT, PREVWEIGHTINKGS DECIMAL(18, 2)
			, STOCKADJUSTMENTTYPEID INT, OLDITEMPRICEID INT, NEWITEMPRICEID INT, STOCKSUMMARYID INT, REASON VARCHAR(500),
			ADDEDQUANTITY INT, ADDEDWEIGHTINKGS DECIMAL(18,2),DEDUCTEDQUANTITY INT,  DEDUCTEDWEIGHTINKGS DECIMAL(18,2))
	
	--insert negative adjustments for old itemprice records first so that they can be made zero
	INSERT INTO #STOCKADJUSTMENT
	SELECT 
		OSS.ITEMPRICEID, OSS.BRANCHID
		, CASE WHEN ISNULL(SM.DEDUCTEDQUANTITY,0) = 0 THEN  0 ELSE OSS.QUANTITY - SM.DEDUCTEDQUANTITY END
		, CASE WHEN ISNULL(SM.DEDUCTEDWEIGHTINKGS,0) = 0 THEN 0 ELSE OSS.WEIGHTINKGS - SM.DEDUCTEDWEIGHTINKGS END
		, OSS.QUANTITY, OSS.WEIGHTINKGS, SM.STOCKADJUSTMENTTYPEID, SM.OLDITEMPRICEID, SM.NEWITEMPRICEID, OSS.STOCKSUMMARYID
			, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(
				ISNULL(SM.REASON + ' - ', '') + 'Qty {Quantity}, Weight {Weight} stock moved from MRP:{OMRP},SalePrice:{OSALEPRICE},GST:{OGSTCODE} to MRP:{NMRP},SalePrice:{NSALEPRICE},GST:{NGSTCODE}'				
					, '{Quantity}', (CASE WHEN ISNULL(SM.ADDEDQUANTITY, 0) = 0 THEN OSS.QUANTITY ELSE ISNULL(SM.ADDEDQUANTITY, 0) END))
					, '{Weight}', (CASE WHEN ISNULL(SM.ADDEDWEIGHTINKGS, 0) = 0 THEN OSS.WEIGHTINKGS ELSE ISNULL(SM.ADDEDWEIGHTINKGS, 0) END))
					, '{OMRP}', OIP.MRP)
					, '{OSALEPRICE}', OIP.SALEPRICE)
					, '{OGSTCODE}', OGST.GSTCODE)
					, '{NMRP}', NIP.MRP)
					, '{NSALEPRICE}', NIP.SALEPRICE)
					, '{NGSTCODE}', NGST.GSTCODE)
			, ISNULL(SM.ADDEDQUANTITY, 0), ISNULL(SM.ADDEDWEIGHTINKGS, 0)
			, ISNULL(SM.DEDUCTEDQUANTITY, 0), ISNULL(SM.DEDUCTEDWEIGHTINKGS, 0)
	FROM
		#STOCKMOVE SM		
		INNER JOIN ITEMPRICE OIP ON OIP.ITEMPRICEID = SM.OLDITEMPRICEID
		INNER JOIN ITEMPRICE NIP ON NIP.ITEMPRICEID = SM.NEWITEMPRICEID
		INNER JOIN GSTDETAIL OGST ON OGST.GSTID = OIP.GSTID
		INNER JOIN GSTDETAIL NGST ON NGST.GSTID = NIP.GSTID
		INNER JOIN STOCKSUMMARY OSS ON OSS.ITEMPRICEID = SM.OLDITEMPRICEID 
			AND (OSS.BRANCHID = SM.BRANCHID OR ISNULL(SM.BRANCHID,0) = 0)
	WHERE 
		SM.MOVESTATUS = 0
		AND (OSS.QUANTITY <> 0 OR OSS.WEIGHTINKGS <> 0)

	---- picking the negative adjustments, create a positive adjustment for new itempriceid
	INSERT INTO #STOCKADJUSTMENT
	SELECT 
		NSS.ITEMPRICEID, SM.BRANCHID, 
		NSS.QUANTITY + (CASE WHEN SM.ADDEDQUANTITY = 0 THEN OSS.QUANTITY ELSE SM.ADDEDQUANTITY END)
		, NSS.WEIGHTINKGS + (CASE WHEN SM.ADDEDWEIGHTINKGS = 0 THEN OSS.WEIGHTINKGS ELSE SM.ADDEDWEIGHTINKGS END)
		, NSS.QUANTITY, NSS.WEIGHTINKGS, SM.STOCKADJUSTMENTTYPEID, SM.OLDITEMPRICEID, SM.NEWITEMPRICEID, NSS.STOCKSUMMARYID
			, SM.REASON, 0,0,0,0 -- proper reason is already built
	FROM
		#STOCKADJUSTMENT SM		
		INNER JOIN ITEMPRICE OIP ON OIP.ITEMPRICEID = SM.OLDITEMPRICEID
		INNER JOIN ITEMPRICE NIP ON NIP.ITEMPRICEID = SM.NEWITEMPRICEID
		INNER JOIN GSTDETAIL OGST ON OGST.GSTID = OIP.GSTID
		INNER JOIN GSTDETAIL NGST ON NGST.GSTID = NIP.GSTID
		INNER JOIN STOCKSUMMARY OSS ON OSS.ITEMPRICEID = SM.OLDITEMPRICEID AND OSS.BRANCHID = SM.BRANCHID
		INNER JOIN STOCKSUMMARY NSS ON NSS.ITEMPRICEID = SM.NEWITEMPRICEID AND NSS.BRANCHID = SM.BRANCHID


	INSERT INTO STOCKADJUSTMENT(ITEMPRICEID, BRANCHID, QUANTITY, WEIGHTINKGS, CREATEDBY, CREATEDDATE, PREVQUANTITY, PREVWEIGHTINKGS, DESCRIPTION, STOCKADJUSTMENTTYPEID)
	SELECT ITEMPRICEID, BRANCHID, QUANTITY, WEIGHTINKGS, 4, GETDATE(), PREVQUANTITY, PREVWEIGHTINKGS, REASON, STOCKADJUSTMENTTYPEID
	FROM #STOCKADJUSTMENT

	UPDATE SS
	SET 
		SS.QUANTITY = SS.QUANTITY + SM.QUANTITY - SM.PREVQUANTITY
		, SS.WEIGHTINKGS = SS.WEIGHTINKGS + SM.WEIGHTINKGS - SM.PREVWEIGHTINKGS
		, SS.TTYPE = 'SM' 
		, SS.MODIFIEDDATE = GETDATE()
	FROM
		STOCKSUMMARY SS
		INNER JOIN 
			( 
				SELECT 
					SMINNER.ITEMPRICEID, SMINNER.BRANCHID
					, SUM(SMINNER.QUANTITY) QUANTITY, SUM(SMINNER.WEIGHTINKGS) WEIGHTINKGS
					, SMINNER.PREVQUANTITY, SMINNER.PREVWEIGHTINKGS
				FROM #STOCKADJUSTMENT SMINNER
				GROUP BY SMINNER.ITEMPRICEID, SMINNER.BRANCHID, SMINNER.PREVQUANTITY, SMINNER.PREVWEIGHTINKGS
			) SM ON SM.ITEMPRICEID = SS.ITEMPRICEID AND SM.BRANCHID = SS.BRANCHID

	UPDATE OIP
	SET 
		OIP.STOCKMOVETOID = SM.NEWITEMPRICEID, OIP.DELETEDBY = ISNULL(OIP.DELETEDBY, 4), OIP.DELETEDDATE = ISNULL(OIP.DELETEDDATE, GETDATE())
	FROM
		ITEMPRICE OIP 
		INNER JOIN #STOCKMOVE SM ON (SM.OLDITEMPRICEID = OIP.ITEMPRICEID OR SM.OLDITEMPRICEID = OIP.STOCKMOVETOID) AND ISNULL(SM.BRANCHID,0) = 0
		
	UPDATE SMA
	SET MOVESTATUS = 1, PROCESSEDDATE = GETDATE()
	FROM
		STOCKMOVE SMA
		INNER JOIN #STOCKMOVE SM ON SM.STOCKMOVEID = SMA.STOCKMOVEID

END
GO
