/****** Object:  StoredProcedure [dbo].[USP_PRINT_PICKLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_PRINT_PICKLIST]
(
	@PickListID INT
)
AS
BEGIN

	SELECT PL.PICKLISTID, PL.PICKLISTNUMBER, DLR.DEALERNAME SUPPLIERNAME
	FROM 
		PICKLIST PL
		INNER JOIN TBLDEALER DLR ON DLR.DEALERID = PL.SUPPLIERID
	WHERE PICKLISTID = @PickListID

	SELECT 
		I.ITEMNAME, IC.ITEMCODE, B.BRANCHCODE, CAST(PLI.QUANTITY - PLI.PICKEDQUANTITY AS INT) AVAILABLEQUANTITY
	FROM 
		PICKLISTBRANCH PLB
		INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTBRANCHID = PLB.PICKLISTBRANCHID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = PLI.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = PLB.BRANCHID
	WHERE 
		PLB.PICKLISTID = @PickListID
		AND PLI.QUANTITY <> 0
	ORDER BY B.BRANCHCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_PU_STOCKENTRY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_PU_STOCKENTRY]                      
@STOCKENTRYID INT,
@SUPPLIERID INT,
@SUPPLIERINVOICENO VARCHAR(30),
@INVOICEDATE DATE,
@USERID INT
AS                      
BEGIN               

	DECLARE @FinYearStartDate DATE, @InvoiceFinYear INT, @FinYearEndDate DATE
	SELECT @InvoiceFinYear = YEAR(@INVOICEDATE) - CASE WHEN MONTH(@INVOICEDATE) > 3 THEN 0 ELSE 1 END
	SELECT @FinYearStartDate = DATEFROMPARTS(@InvoiceFinYear, 4, 1), @FinYearEndDate = DATEFROMPARTS(@InvoiceFinYear + 1, 3, 31)

	IF EXISTS
		(
			SELECT 1 
			FROM STOCKENTRY 
			WHERE 
				SUPPLIERID = @SUPPLIERID 
				AND SUPPLIERINVOICENO = @SUPPLIERINVOICENO 
				AND DELETEDDATE IS NULL 
				AND INVOICEDATE BETWEEN @FinYearStartDate AND @FinYearEndDate
				AND STOCKENTRYID <> @STOCKENTRYID
		)
	BEGIN

		SELECT 'Invoice Number Already Exists!'
		RETURN;

	END
	
	UPDATE STOCKENTRY 
	SET 
		SUPPLIERID = @SUPPLIERID,
		SUPPLIERINVOICENO = @SUPPLIERINVOICENO,
		INVOICEDATE = @INVOICEDATE,
		UPDATEDBY = @USERID,
		UPDATEDATE = GETDATE()
	WHERE STOCKENTRYID = @STOCKENTRYID               

	SELECT @STOCKENTRYID
    
END
GO
