CREATE PROCEDURE [dbo].[USP_R_BASEOFFER]
AS
BEGIN

	SELECT 
	BASEOFFERID
	,BO.OFFERCODE
	,BO.OFFERNAME
	,C.CATEGORYNAME
	,BO.CATEGORYID
	,BO.STARTDATE
	,BO.ENDDATE
	,CU.FULLNAME AS CREATEDBY
	,BO.CREATEDDATE
	,UU.FULLNAME AS UPDATEDBY
	,BO.UPDATEDDATE
	,DU.FULLNAME AS DELETEDBY
	,BO.DELETEDDATE
	,CASE WHEN BO.DELETEDDATE IS NULL THEN 'YES' ELSE 'NO' END AS ISACTIVE
	FROM BASEOFFER BO 
		LEFT JOIN TBLUSER CU ON BO.CREATEDBY = CU.USERID
		LEFT JOIN TBLUSER UU ON BO.UPDATEDBY = UU.USERID
		LEFT JOIN TBLUSER DU ON BO.DELETEDBY = DU.USERID
