CREATE PROCEDURE [dbo].[USP_R_BILLDETAILBYID]    
@BRANCHCOUNTERID INT,    
@BILLID INT,
@INCLUDEVOIDITEMS BIT = 0
AS    
BEGIN    
    
	SELECT     
		IC.ITEMCODE    
		,I.ITEMNAME    
		,IP.MRP    
		,IP.SALEPRICE    
		,BD.QUANTITY
		,BD.WEIGHTINKGS    
		,GST.GSTCODE    
		,BD.GSTVALUE    
		,BD.BILLEDAMOUNT    
		,BD.DISCOUNT   
		,CAST(BD.CREATEDDATE AS TIME) AS CREATEDDATE
		,CAST(BD.DELETEDDATE AS TIME) AS DELETEDDATE 
	FROM POS_BILLDETAIL BD     
		INNER JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID    
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID    
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
		LEFT JOIN OFFER OFR ON BD.OFFERID = OFR.OFFERID    
		LEFT JOIN GSTDETAIL GST ON BD.GSTID = GST.GSTID    
	WHERE BD.BRANCHCOUNTERID = @BRANCHCOUNTERID     
		AND BD.BILLID = @BILLID    
		AND (@INCLUDEVOIDITEMS = 1 OR BD.DELETEDDATE IS NULL)

	SELECT 
		BILLMOPDETAILID,
		BMOP.MOPID,
		MOP.MOPNAME,
		MOPVALUE
	FROM POS_BILLMOPDETAIL BMOP
		INNER JOIN TBLMOP MOP ON BMOP.MOPID = MOP.MOPID
	WHERE COUNTERID = @BRANCHCOUNTERID 
		AND BILLID = @BILLID
    
END
GO
