CREATE PROCEDURE [dbo].[USP_R_BRANCH]  
(
	@IncludeDeleted BIT = 0
)
AS                  
BEGIN                  
            
	SELECT                   
		B.BRANCHID,B.BRANCHNAME,B.BRANCHCODE, B.BRANCHGRADEID, BG.GRADE, B.ADDRESS,  
		B.STATEID,B.PHONENO,B.LANDLINE,    
		B.EMAILID,ISNULL(B.ISWAREHOUSE,0) AS ISWAREHOUSE,B.SUPERVISORID,    
		BS.FULLNAME AS SUPERVISOR, BS.CNUMBER AS SUPERVISORMOBILE,    
		C.FULLNAME AS CREATEDBY,B.CREATEDDATE,        
		U.FULLNAME AS UPDATEDBY,B.UPDATEDATE    , B.DELETEDDATE,
		B.FILTERMRPBYSTOCK AS MRPFilterEnabled,
		B.ENABLESTOCKCOUNTING AS StockCountingEnabled, B.ENABLESTOCKDISPATCH as StockDispatchEnabled
		, B.ENABLEDRAFTBILLS, B.BRANCHZONE
	FROM BRANCH B           
		LEFT JOIN TBLUSER C ON B.CREATEDBY = C.USERID            
		LEFT JOIN TBLUSER U ON B.UPDATEDBY = U.USERID            
		LEFT JOIN TBLUSER BS ON B.SUPERVISORID = BS.USERID    
		LEFT JOIN BRANCHGRADE BG ON BG.BRANCHGRADEID = B.BRANCHGRADEID
	WHERE B.DELETEDDATE IS NULL OR (@IncludeDeleted = 1 AND B.DELETEDDATE > '2024-04-01' )                
	ORDER BY BRANCHCODE
               
END


GO
