CREATE PROCEDURE [dbo].[USP_R_BRANCHCOUNTER_LEGACY]
AS
BEGIN
    SET NOCOUNT ON;
    SELECT BC.COUNTERID, BC.COUNTERNAME, BC.BRANCHID, B.BRANCHNAME,
        C.FULLNAME AS CREATEDBY, BC.CREATEDDATE, U.FULLNAME AS UPDATEDBY, BC.UPDATEDDATE,
        ISNULL(BC.ISMOBILECOUNTER, 0) AS ISMOBILECOUNTER,
        BC.PAYMENTGATEWAYID AS PAYMENTGATEWAYINFOID,
        BC.PAYMENTGATEWAYADDITIONALCONFIG, P.PAYMENTGATEWAYINFONAME
    FROM dbo.BRANCHCOUNTER BC
    INNER JOIN dbo.BRANCH B ON B.BRANCHID = BC.BRANCHID
    LEFT JOIN dbo.TBLUSER C ON C.USERID = BC.CREATEDBY
    LEFT JOIN dbo.TBLUSER U ON U.USERID = BC.UPDATEDBY
    LEFT JOIN dbo.PAYMENTGATEWAYINFO P ON P.PAYMENTGATEWAYINFOID = BC.PAYMENTGATEWAYID
    WHERE BC.DELETEDDATE IS NULL AND B.DELETEDDATE IS NULL;
END
GO
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_BRANCHCOUNTER]  
AS
BEGIN
    SET NOCOUNT ON;
    SELECT BC.COUNTERID, BC.COUNTERNAME, BC.BRANCHID, B.BRANCHNAME,
        C.FULLNAME AS CREATEDBY, BC.CREATEDDATE, U.FULLNAME AS UPDATEDBY, BC.UPDATEDDATE,
        ISNULL(BC.ISMOBILECOUNTER, 0) AS ISMOBILECOUNTER,
        STUFF((SELECT ', ' + M.MOPNAME + CASE WHEN P.PAYMENTGATEWAYINFOID IS NULL THEN ''
                     ELSE ' (' + P.PAYMENTGATEWAYINFONAME + ')' END
               FROM dbo.BRANCHCOUNTERMOP CM
               INNER JOIN dbo.TBLMOP M ON M.MOPID = CM.MOPID AND M.DELETEDDATE IS NULL
               LEFT JOIN dbo.PAYMENTGATEWAYINFO P ON P.PAYMENTGATEWAYINFOID = CM.PAYMENTGATEWAYINFOID
               WHERE CM.COUNTERID = BC.COUNTERID AND CM.DELETEDDATE IS NULL
               ORDER BY M.MOPID
               FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, '') AS MOPCONFIGURATION
    FROM dbo.BRANCHCOUNTER BC
    INNER JOIN dbo.BRANCH B ON B.BRANCHID = BC.BRANCHID
    LEFT JOIN dbo.TBLUSER C ON C.USERID = BC.CREATEDBY
    LEFT JOIN dbo.TBLUSER U ON U.USERID = BC.UPDATEDBY
    WHERE BC.DELETEDDATE IS NULL AND B.DELETEDDATE IS NULL;
END
