CREATE   PROC [dbo].[USP_R_BRANCHEXPENSE]
(
	@BranchIDs VARCHAR(MAX)
	, @FromDate DATE
	, @ToDate DATE
)
AS
BEGIN


	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')

	SELECT 
		BE.BRANCHEXPENSEID, BE.BRANCHID, BE.BRANCHEXPENSETYPEID, AB.BRANCHNAME, BET.BRANCHEXPENSETYPENAME
		, BE.EXPENSEDESC, BE.AMOUNT, CU.FULLNAME CREATEDBY, BE.CREATEDDATE, UU.FULLNAME UPDATEDBY, BE.UPDATEDDATE
	FROM
		BRANCHEXPENSE BE
		INNER JOIN #BRANCH B ON B.ITEM = BE.BRANCHID
		INNER JOIN BRANCH AB ON AB.BRANCHID = BE.BRANCHID
		INNER JOIN BRANCHEXPENSETYPE BET ON BET.BRANCHEXPENSETYPEID = BE.BRANCHEXPENSETYPEID
		INNER JOIN TBLUSER CU ON CU.USERID = BE.CREATEDBY
		LEFT JOIN TBLUSER UU ON UU.USERID = BE.UPDATEDBY
	WHERE
		BE.CREATEDDATE >= @FromDate
		AND BE.CREATEDDATE <= @ToDate
		AND BE.DELETEDDATE IS NULL
	ORDER BY BE.CREATEDDATE DESC
	
END

GO
