CREATE PROCEDURE [dbo].[USP_R_BRANCHFORDISPATCH]  
(
	@USERID INT
)
AS                  
BEGIN                  
            
	SELECT                   
		B.BRANCHID,B.BRANCHNAME,B.BRANCHCODE,B.ADDRESS,  
		B.STATEID,B.PHONENO,B.LANDLINE,    
		B.EMAILID,ISNULL(B.ISWAREHOUSE,0) AS ISWAREHOUSE,B.SUPERVISORID,    
