/****** Object:  StoredProcedure [dbo].[USP_R_BRANCHFORDISPATCH_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_BRANCHFORDISPATCH_v2]  
(
	@USERID INT,
	@IsManualDispatch BIT
)
AS                  
BEGIN                  

	SELECT 1 AS PARENTID
	IF(@IsManualDispatch = 1)
	BEGIN
		SELECT                   
			1 AS PARENTID, B.BRANCHID,B.BRANCHNAME,B.BRANCHCODE, 0 AS BRANCHINDENTID
		FROM BRANCH B           
		WHERE B.DELETEDDATE IS NULL
		ORDER BY BRANCHCODE
	END
	ELSE
	BEGIN
		SELECT                   
			1 AS PARENTID, B.BRANCHID,B.BRANCHNAME,B.BRANCHCODE,BI.BRANCHINDENTID
		FROM BRANCHINDENT BI 
			INNER JOIN BRANCH B ON BI.TOBRANCHID = B.BRANCHID
			INNER JOIN TBLUSER U ON BI.SUBCATEGORYID = U.SUBCATEGORYID
		WHERE U.USERID = @USERID AND BI.DELETEDDATE IS NULL  AND 
			NOT EXISTS(SELECT  1 FROM STOCKDISPATCH SD WHERE SD.BRANCHINDENTID = BI.BRANCHINDENTID AND SD.DELETEDDATE IS NULL)
		ORDER BY BI.CREATEDDATE
	END
               
END
GO
