/****** Object:  StoredProcedure [dbo].[USP_R_BRANCHINDENT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_BRANCHINDENT]
@BranchID INT,
@CategoryID INT,
@IndentDays INT,
@SafetyStockDays INT = 0
AS
BEGIN
	
	DECLARE @FromDate DATE, @ToDate DATE, @MultiplierDays INT, @IndentSaleFromDate DATE

	SELECT @FromDate = GETDATE() - 60, @ToDate = DATEADD(d, 1, GETDATE()), @MultiplierDays = @IndentDays + @SafetyStockDays, @IndentSaleFromDate = GETDATE() - @IndentDays


	SELECT I.ITEMID, BS.QUANTITY AS BRANCHSTOCK, ITEMSALE.SALEQUANTITY, ISNULL(ITEMINDENTSALE.INDENTDAYSSALEQUANTITY, 0) INDENTDAYSSALEQUANTITY
		, CAST(0.00 AS DECIMAL(18, 2)) AS MAXSALE, CAST(0.00 AS DECIMAL(18, 2)) AS INDENTQUANTITY, CAST(NULL AS DATETIME) LASTDISPATCHDATE, 0 AS ISINDENTNEEDED 
	INTO #INDENT
	FROM ITEM I 
		INNER JOIN 
			(
				SELECT IC.ITEMID, CAST(CASE WHEN I.ISOPENITEM = 1 THEN SUM(SSINNER.WEIGHTINKGS) ELSE SUM(SSINNER.QUANTITY) END AS DECIMAL(18, 2)) AS QUANTITY
				FROM STOCKSUMMARY SSINNER 
					INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE SSINNER.BRANCHID = @BranchID
				GROUP BY IC.ITEMID, I.ISOPENITEM
			) BS ON BS.ITEMID = I.ITEMID
		INNER JOIN	
			(
				SELECT IC.ITEMID
					, CAST(ROUND(((CASE WHEN I.ISOPENITEM = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END * 1.00) / 60) --COUNT(DISTINCT CAST(PBD.CREATEDDATE AS DATE))) 
									, 2) AS DECIMAL(18, 2))  AS SALEQUANTITY
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE
					BC.BRANCHID = @BranchID
					AND I.CATEGORYID = @CategoryID
					AND PB.CREATEDDATE >= @FromDate
					AND PB.CREATEDDATE <= @ToDate
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
				GROUP BY IC.ITEMID, I.ISOPENITEM
			) ITEMSALE ON ITEMSALE.ITEMID = I.ITEMID
		LEFT JOIN	
			(
				SELECT IC.ITEMID
					, CAST(ROUND((CASE WHEN I.ISOPENITEM = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END), 2) AS DECIMAL(18, 2)) AS INDENTDAYSSALEQUANTITY
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE
					BC.BRANCHID = @BranchID
					AND I.CATEGORYID = @CategoryID
					AND PB.CREATEDDATE >= @IndentSaleFromDate
					AND PB.CREATEDDATE <= @ToDate
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
				GROUP BY IC.ITEMID, I.ISOPENITEM
			) ITEMINDENTSALE ON ITEMINDENTSALE.ITEMID = I.ITEMID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID

	UPDATE #INDENT
	SET SALEQUANTITY = SALEQUANTITY * @MultiplierDays

	UPDATE #INDENT
	SET SALEQUANTITY = CASE WHEN SALEQUANTITY < 1 THEN  1 -- 5.00 / @MultiplierDays 
							ELSE SALEQUANTITY END

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)
	UPDATE #INDENT SET MAXSALE = CASE WHEN SALEQUANTITY > INDENTDAYSSALEQUANTITY THEN SALEQUANTITY ELSE INDENTDAYSSALEQUANTITY END

	UPDATE #INDENT SET INDENTQUANTITY = MAXSALE - (CASE WHEN  BRANCHSTOCK > 0 THEN BRANCHSTOCK ELSE 0 END)

	UPDATE #INDENT
	SET INDENTQUANTITY = 5 
	WHERE INDENTQUANTITY > 0 AND INDENTQUANTITY < 5

	UPDATE #INDENT
	SET INDENTQUANTITY = 5 
	WHERE MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5
	
	UPDATE #INDENT
	SET INDENTQUANTITY = CAST(CEILING((INDENTQUANTITY * 1.00 / 5)) AS INT) * 5
	WHERE INDENTQUANTITY > 0 

	UPDATE I
	SET I.LASTDISPATCHDATE = LSD.LASTDISPATCHDATE
	FROM	
		#INDENT I		
		INNER JOIN 
			(
				SELECT IC.ITEMID, MAX(SD.CREATEDDATE) LASTDISPATCHDATE
				FROM
					STOCKDISPATCHDETAIL SDD 
					INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				WHERE
					SD.STATUS IN (1, 2) AND SD.DELETEDDATE IS NULL AND SDD.DELETEDDATE IS NULL AND SD.TOBRANCHID = @BranchID
				GROUP BY IC.ITEMID
			) LSD ON LSD.ITEMID = I.ITEMID

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)

	UPDATE #INDENT
	SET ISINDENTNEEDED = 1
	WHERE BRANCHSTOCK <= 0 -- Send all negatives, since sale is there and we think stock is wrong send them

	UPDATE #INDENT
	SET ISINDENTNEEDED = CASE
							WHEN MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5 THEN 1  
							WHEN INDENTDAYSSALEQUANTITY = 0 OR BRANCHSTOCK < INDENTDAYSSALEQUANTITY * 1.5 THEN 1
						ELSE 0 END
	WHERE ISINDENTNEEDED = 0 AND MAXSALE > BRANCHSTOCK


	SELECT
		I.ITEMID, I.SKUCODE, I.ITEMNAME, SUBCAT.SUBCATEGORYNAME, BRANCHSTOCK, SALEQUANTITY, INDENTDAYSSALEQUANTITY
		, CAST(INDENTQUANTITY AS INT) INDENTQUANTITY, INDENT.LASTDISPATCHDATE 
	FROM
		#INDENT INDENT
		INNER JOIN ITEM I ON I.ITEMID = INDENT.ITEMID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
	WHERE INDENT.ISINDENTNEEDED = 1
	ORDER BY SUBCATEGORYNAME, ITEMNAME 
	
	
	--WHERE
	--	INDENT.BRANCHSTOCK <= 0 
	--	AND ((((INDENT.MAXSALE - (INDENT.BRANCHSTOCK)) * 1.00 / 5) > 0 AND (INDENT.BRANCHSTOCK < ISNULL(INDENT.INDENTDAYSSALEQUANTITY, 0) * 1.5))
	--	OR (INDENT.MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5))
	--ORDER BY SUBCATEGORYNAME, ITEMNAME 

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_BRAND]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
