/****** Object:  StoredProcedure [dbo].[USP_R_CONSOLIDATEDSTOCKCOUNTING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_CONSOLIDATEDSTOCKCOUNTING]
@BranchID int
AS
BEGIN

	SELECT
		I.SKUCODE,
		IC.ITEMID,
		IC.ITEMCODEID,
		IC.ITEMCODE,
		I.ITEMNAME,
		IP.MRP,
		C.CATEGORYNAME,
		SC.SUBCATEGORYNAME,
		CASE WHEN I.ISOPENITEM = 0 THEN SCD.QUANTITY ELSE SCD.WEIGHTINKGS END AS PHYSICALQAUNTITY,
		CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS SYSTEMQUANTITY,
		SCD.STOCKCOUNTINGID,
		SCD.STOCKLOCATIONNAME
	FROM 
		(
			SELECT 
				IP.ITEMPRICEID, 
				SC.STOCKCOUNTINGID,
				SCL.STOCKLOCATIONNAME,
				SUM(QUANTITY) AS QUANTITY,
				SUM(WEIGHTINKGS) AS WEIGHTINKGS
			FROM 
				STOCKCOUNTINGDETAIL SCD
				INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
				INNER JOIN STOCKLOCATION SCL ON SC.STOCKLOCATIONID = SCL.STOCKLOCATIONID
				INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
			WHERE
				SC.BRANCHID = @BranchID 
				AND (ISNULL(STATUS,0) = 1 OR ISNULL(STATUS,0) = 0)
				AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
			GROUP BY IP.ITEMPRICEID,SC.STOCKCOUNTINGID,SCL.STOCKLOCATIONNAME
		) SCD
		INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN STOCKSUMMARY SS ON SCD.ITEMPRICEID = SS.ITEMPRICEID
	WHERE SS.BRANCHID = @BranchID
	ORDER BY I.ITEMNAME, IC.ITEMCODE, IP.MRP

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_CONTINGDATA]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_CONTINGDATA]
@BRANCHID INT    
AS    
BEGIN    

	SELECT     
		I.ITEMID, I.SKUCODE, SS.ITEMCODEID, IC.ITEMCODE, I.ITEMNAME, C.CATEGORYNAME, SCAT.SUBCATEGORYNAME,    
		SC.QUANTITY AS PHYSICALSTOCK, SS.SYSTEMSTOCK, SC.QUANTITY - SS.SYSTEMSTOCK as STOCKDIFF

	INTO #STOCKDIFF
	FROM 
		(  
			SELECT IC.ITEMID, IC.ITEMCODEID, 
				SUM(CASE WHEN ISNULL(I.ISOPENITEM,0) = 0 THEN SCD.QUANTITY ELSE SCD.WEIGHTINKGS END) AS QUANTITY
			FROM 
				STOCKCOUNTINGDETAIL SCD  
				INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID  
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID  
				INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
				INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID    
			WHERE 
				SC.BRANCHID = @BRANCHID   
				AND (ISNULL(STATUS,0) = 0 OR ISNULL(STATUS,0) = 1)   
				AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
			GROUP BY IC.ITEMCODEID, IC.ITEMID
		) SC    
		
		LEFT JOIN 
		(
			SELECT IP.ITEMCODEID, SUM(CASE WHEN ISNULL(I.ISOPENITEM,0) = 0 THEN SSINNER.QUANTITY ELSE SSINNER.WEIGHTINKGS END) AS SYSTEMSTOCK
			FROM 
				STOCKSUMMARY SSINNER
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID    
				INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
			WHERE SSINNER.BRANCHID = @BRANCHID
			GROUP BY IP.ITEMCODEID
		) SS ON SC.ITEMCODEID = SS.ITEMCODEID  

		INNER JOIN ITEMCODE IC ON SC.ITEMCODEID = IC.ITEMCODEID    
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID    
		LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID

	SELECT DISTINCT I.CATEGORYID  
	INTO #Categories  
	FROM   
		STOCKCOUNTINGDETAIL SCD WITH(NOLOCK) 
		INNER JOIN STOCKCOUNTING SC WITH(NOLOCK) ON SCD.STOCKCOUNTINGID = SC .STOCKCOUNTINGID   
			AND SC.BRANCHID = @BRANCHID  
			AND ISNULL(SC.STATUS, 0) = 1  
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON SCD.ITEMPRICEID = IP.ITEMPRICEID  
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID  
		INNER JOIN ITEM I WITH(NOLOCK) ON IC.ITEMID = I.ITEMID  
	WHERE SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL  
	GROUP BY I.CATEGORYID  
	HAVING SUM(SCD.QUANTITY) <> 0 OR SUM(SCD.WEIGHTINKGS) <> 0  

	INSERT INTO #STOCKDIFF(ITEMID, SKUCODE, ITEMCODEID, ITEMCODE, ITEMNAME, CATEGORYNAME, SUBCATEGORYNAME,    
		PHYSICALSTOCK, SYSTEMSTOCK, STOCKDIFF)
	SELECT I.ITEMID, I.SKUCODE, IP.ITEMCODEID, IC.ITEMCODE, I.ITEMNAME, C.CATEGORYNAME, SCAT.SUBCATEGORYNAME, 
		0 AS PHYSICALSTOCK, SUM(SS.QUANTITY) AS QUANTITY,  SUM(SS.QUANTITY) * -1
	FROM
		STOCKSUMMARY SS WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID	
		INNER JOIN TBLCATEGORY C WITH(NOLOCK) ON I.CATEGORYID = C.CATEGORYID  
		INNER JOIN #Categories CA WITH(NOLOCK) ON CA.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT WITH(NOLOCK) ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
	WHERE
		SS.QUANTITY != 0
		AND IP.DELETEDDATE IS NULL
		AND IC.DELETEDDATE IS NULL
		AND NOT EXISTS 
			(
				SELECT 1 
				FROM 
					STOCKCOUNTINGDETAIL SED WITH(NOLOCK) 
					INNER JOIN STOCKCOUNTING SC WITH(NOLOCK) ON SC.STOCKCOUNTINGID = SED.STOCKCOUNTINGID  
					INNER JOIN ITEMPRICE IPINNER WITH(NOLOCK) ON SED.ITEMPRICEID = IPINNER.ITEMPRICEID
				WHERE SC.BRANCHID = @BRANCHID 
					AND ((ISNULL(STATUS,0) = 0 OR ISNULL(STATUS,0) = 1))
					AND IPINNER.ITEMPRICEID = IP.ITEMPRICEID
					AND SED.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
				)
		AND SS.BRANCHID = @BRANCHID	
	GROUP BY I.ITEMID,I.SKUCODE, IP.ITEMCODEID, IC.ITEMCODE, I.ITEMNAME, C.CATEGORYNAME, SCAT.SUBCATEGORYNAME

		SELECT     
		ITEMID, SKUCODE, ITEMCODEID, ITEMCODE, ITEMNAME, CATEGORYNAME, SUBCATEGORYNAME,    
		PHYSICALSTOCK AS PHYSICALQAUNTITY , SYSTEMSTOCK AS SYSTEMQUANTITY, PHYSICALSTOCK - SYSTEMSTOCK as STOCKDIFF FROM #STOCKDIFF

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_COSTPRICELIST_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_COSTPRICELIST_v2]
@ITEMCODEID INT,
@MRP DECIMAL(11,4) = 0
AS      
BEGIN      


	SELECT SED.* 
	INTO #SED
	FROM STOCKENTRYDETAIL SED 
		INNER JOIN ITEMCOSTPRICE ICP ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
	WHERE SED.DELETEDDATE IS NULL
		AND IP.ITEMCODEID = @ITEMCODEID

	SELECT 
		ICP.ITEMCOSTPRICEID, 
		IP.MRP, 
		IP.SALEPRICE, 
		ICP.COSTPRICEWOT, 
		ICP.COSTPRICEWT, 
		ICP.GROSSCOSTPRICEWOT,
		ICP.GROSSCOSTPRICEWT,
		G.GSTCODE, 
		G.GSTID, 
		G.CGST, 
		G.SGST, 
		G.IGST, 
		G.CESS, 
		IP.ITEMPRICEID,
		SED_APPLY.INVOICEDATE,
		D.DEALERNAME

	FROM ITEMCOSTPRICE ICP 

	INNER JOIN ITEMPRICE IP    
		ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		AND IP.ITEMCODEID = @ITEMCODEID
		AND IP.BRANCHID IS NULL
		AND IP.DELETEDDATE IS NULL
		AND (@MRP = 0 OR IP.MRP = @MRP)

	LEFT JOIN GSTDETAIL G 
		ON ICP.GSTID = G.GSTID    

	OUTER APPLY
	(
		SELECT TOP 1 
			SE.INVOICEDATE,
			SE.SUPPLIERID
		FROM #SED SED
		INNER JOIN STOCKENTRY SE 
			ON SE.STOCKENTRYID = SED.STOCKENTRYID
		WHERE 
			SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
			AND SED.DELETEDDATE IS NULL
		ORDER BY 
			SE.INVOICEDATE DESC,
			SED.STOCKENTRYDETAILID DESC
	) SED_APPLY

	LEFT JOIN TBLDEALER D 
		ON D.DEALERID = SED_APPLY.SUPPLIERID      

	WHERE 
		ICP.DELETEDDATE IS NULL

	ORDER BY 
		CASE WHEN SED_APPLY.INVOICEDATE IS NULL THEN 1 ELSE 0 END,
		SED_APPLY.INVOICEDATE DESC

END
GO
