/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGAPPROVAL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_COUNTINGAPPROVAL]
@BRANCHID VARCHAR(500),
@FromDate Date = NULL,      
@ToDate Date = NULL    
AS
BEGIN

	SELECT
		CA.COUNTINGAPPROVALID, CA.BRANCHID, B.BRANCHNAME, 
		CU.FULLNAME AS [Accepted By], CA.CREATEDDATE AS [Accepted Date]
	FROM COUNTINGAPPROVAL CA
		INNER JOIN BRANCH B ON CA.BRANCHID = B.BRANCHID
		INNER JOIN TBLUSER CU ON CA.CREATEDBY = CU.USERID
		INNER JOIN dbo.SplitString(@BRANCHID,',') BIDS ON B.BRANCHID = BIDS.ITEM
	WHERE CA.CREATEDDATE >= @FromDate     
		AND CA.CREATEDDATE <= DATEADD(day,1,@ToDate)
	ORDER BY CA.CREATEDDATE DESC  

END	
GO
