/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGDATA]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_COUNTINGDATA]
@BranchID int
AS
BEGIN


	CREATE TABLE #CDATA(ITEMID INT, COUNTEDQUANTITY DECIMAL(18,2), 
		FIRSTCOUNTINGDATE DATETIME, LASTCOUNTNGDATE DATETIME, SALESBETWEEN DECIMAL(18,2), 
		SALESAFTER DECIMAL(18,2), BREFUND DECIMAL(18,2), CREFUNDBETWEEN DECIMAL(18,2), CREFUNDAFTER DECIMAL(18,2) , 
		DISPATCH DECIMAL(18,2), FINALQUANTITY DECIMAL(18,2), SYSTEMQUANTITY DECIMAL(18,2))

	INSERT INTO #CDATA(ITEMID, COUNTEDQUANTITY, FIRSTCOUNTINGDATE, LASTCOUNTNGDATE)
	SELECT 
		I.ITEMID, 
		CASE WHEN I.ISOPENITEM = 0 THEN SUM(QUANTITY) ELSE SUM(WEIGHTINKGS) END,
		MIN(SCD.CREATEDDATE),
		MAX(SCD.CREATEDDATE)
	FROM 
		STOCKCOUNTINGDETAIL SCD
		INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
		INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE
		SC.BRANCHID = @BranchID 
		AND (ISNULL(SC.STATUS,0) = 1 OR ISNULL(SC.STATUS,0) = 0)
		AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
	GROUP BY I.ITEMID,I.ISOPENITEM

	SELECT DISTINCT I.SUBCATEGORYID
	INTO #SubCategories  
	FROM STOCKCOUNTINGDETAIL SCD WITH(NOLOCK) 
		INNER JOIN STOCKCOUNTING SC WITH(NOLOCK) ON SCD.STOCKCOUNTINGID = SC .STOCKCOUNTINGID   
			AND SC.BRANCHID = @BRANCHID  
			AND (ISNULL(SC.STATUS, 0) = 1 OR ISNULL(SC.STATUS, 0) = 0)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON SCD.ITEMPRICEID = IP.ITEMPRICEID  
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID  
		INNER JOIN ITEM I WITH(NOLOCK) ON IC.ITEMID = I.ITEMID  
	WHERE SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL  
	GROUP BY I.SUBCATEGORYID
	HAVING SUM(SCD.QUANTITY) <> 0 OR SUM(SCD.WEIGHTINKGS) <> 0

	DECLARE @FDATE DATETIME, @LDATE DATETIME

	SELECT @FDATE = MIN(SCD.CREATEDDATE),@LDATE = MAX(SCD.CREATEDDATE)
	FROM STOCKCOUNTINGDETAIL SCD
		INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
		INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE
		SC.BRANCHID = @BranchID 
		AND (ISNULL(SC.STATUS,0) = 1 OR ISNULL(SC.STATUS,0) = 0)
		AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL

	INSERT INTO #CDATA(ITEMID, COUNTEDQUANTITY, FIRSTCOUNTINGDATE,LASTCOUNTNGDATE, SALESBETWEEN, SALESAFTER, CREFUNDBETWEEN,CREFUNDAFTER, FINALQUANTITY)
	SELECT DISTINCT I.ITEMID, 0, @FDATE, @LDATE, 0,0,0,0,0
	FROM
		STOCKSUMMARY SS WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID	
		INNER JOIN #SubCategories SCA WITH(NOLOCK) ON I.SUBCATEGORYID = SCA.SUBCATEGORYID
	WHERE
		(CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END <> 0)
		AND IP.DELETEDDATE IS NULL
		AND IC.DELETEDDATE IS NULL
		AND NOT EXISTS 
			(
				SELECT 1 
				FROM 
					STOCKCOUNTINGDETAIL SED WITH(NOLOCK) 
					INNER JOIN STOCKCOUNTING SC WITH(NOLOCK) ON SC.STOCKCOUNTINGID = SED.STOCKCOUNTINGID  
				WHERE SC.BRANCHID = @BRANCHID 
					AND (ISNULL(STATUS,0) = 0 OR ISNULL(STATUS,0) = 1)
					AND SED.ITEMPRICEID = IP.ITEMPRICEID
					AND SED.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
			)
		AND NOT EXISTS 
			(
				SELECT 1 FROM #CDATA CD WHERE CD.ITEMID = I.ITEMID
			)
		AND SS.BRANCHID = @BRANCHID

	SELECT 
		CD.ITEMID, 
		SUM(CASE WHEN PBD.CREATEDDATE < CD.LASTCOUNTNGDATE THEN PBD.SALE ELSE 0 END) AS BETWEENSALE,
		SUM(CASE WHEN PBD.CREATEDDATE > CD.LASTCOUNTNGDATE THEN PBD.SALE ELSE 0 END) AS AFTERSALE
	INTO #SALES
	FROM #CDATA CD
		INNER JOIN 
			(	SELECT 
					I.ITEMID, 
					PBD.CREATEDDATE, 
					CASE WHEN I.ISOPENITEM = 0 THEN QUANTITY ELSE WEIGHTINKGS END AS SALE 
				FROM POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID  AND PBD.BILLID = PB.BILLID
					INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
					INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
					INNER JOIN BRANCHCOUNTER BC ON PB.BRANCHCOUNTERID = BC.COUNTERID
				WHERE BC.BRANCHID = @BranchID AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL AND PB.BILLSTATUS = 1
			) PBD ON CD.ITEMID = PBD.ITEMID AND PBD.CREATEDDATE > CD.FIRSTCOUNTINGDATE

	GROUP BY CD.ITEMID
	
	UPDATE CD
	SET 
		CD.SALESBETWEEN = ISNULL(S.BETWEENSALE,0),
		CD.SALESAFTER = ISNULL(S.AFTERSALE,0)
	FROM #CDATA CD
	LEFT JOIN #SALES S ON CD.ITEMID = S.ITEMID

	SELECT 
		CD.ITEMID, 
		SUM(CASE WHEN CR.CREATEDDATE < CD.LASTCOUNTNGDATE THEN CR.CREFUND ELSE 0 END) AS BETWEENCREFUND ,
		SUM(CASE WHEN CR.CREATEDDATE > CD.LASTCOUNTNGDATE THEN CR.CREFUND ELSE 0 END) AS AFTERCREFUND 
	INTO #CREFUNDS
	FROM #CDATA CD
		INNER JOIN 
			(	SELECT 
					I.ITEMID, 
					CR.CREATEDDATE, 
					CASE WHEN I.ISOPENITEM = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS CREFUND 
				FROM POS_CREFUND CR 
					INNER JOIN POS_BILLDETAIL PBD ON CR.BILLDETAILID = PBD.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
					INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
					INNER JOIN BRANCHCOUNTER BC ON CR.COUNTERID = BC.COUNTERID
				WHERE BC.BRANCHID = @BranchID
			) CR ON CD.ITEMID = CR.ITEMID AND CR.CREATEDDATE > CD.FIRSTCOUNTINGDATE

	GROUP BY CD.ITEMID

	UPDATE CD
	SET 
		CD.CREFUNDBETWEEN = ISNULL(CR.BETWEENCREFUND,0),
		CD.CREFUNDAFTER = ISNULL(CR.AFTERCREFUND,0)
	FROM #CDATA CD
	LEFT JOIN #CREFUNDS CR ON CD.ITEMID = CR.ITEMID

	UPDATE #CDATA
	SET FINALQUANTITY = COUNTEDQUANTITY - ISNULL(SALESBETWEEN,0) - ISNULL(SALESAFTER,0) + ISNULL(CREFUNDBETWEEN,0) + ISNULL(CREFUNDAFTER,0)

	UPDATE CD
	SET CD.SYSTEMQUANTITY = SS.SYSTEMQUANTITY
	FROM #CDATA CD 
	INNER JOIN 
	(
		SELECT I.ITEMID, CASE WHEN I.ISOPENITEM = 0 THEN SUM(SSINNER.QUANTITY) ELSE SUM(SSINNER.WEIGHTINKGS) END AS SYSTEMQUANTITY FROM STOCKSUMMARY SSINNER
			INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID  
		WHERE SSINNER.BRANCHID = @BRANCHID
		GROUP BY I.ITEMID, I.ISOPENITEM
	) SS ON CD.ITEMID = SS.ITEMID

	SELECT I.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SCAT.SUBCATEGORYNAME, 
		CD.COUNTEDQUANTITY, CD.FIRSTCOUNTINGDATE, CD.LASTCOUNTNGDATE, 
		CD.SALESBETWEEN, CD.SALESAFTER , CD.CREFUNDBETWEEN, CD.CREFUNDAFTER, CD.FINALQUANTITY, CD.SYSTEMQUANTITY,
		CASE WHEN CD.SALESBETWEEN <> 0 THEN 'YES' ELSE 'NO' END RECOUNTINGREQUIRED
		
	FROM #CDATA CD 
		INNER JOIN ITEM I ON CD.ITEMID = I.ITEMID
		INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGDATA_LOCATION]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_COUNTINGDATA_LOCATION]
@BranchID INT
AS
BEGIN

	SELECT
		I.ITEMID,
		IC.ITEMCODEID,
		I.SKUCODE,
		IC.ITEMCODE,
		I.ITEMNAME,
		CAT.CATEGORYNAME,
		SUBCAT.SUBCATEGORYNAME,
		SC.QUANTITY,
		SCL.STOCKLOCATIONNAME
	FROM 
	(
		SELECT 
			IC.ITEMCODEID,
			SC.STOCKLOCATIONID,
			CASE WHEN I.ISOPENITEM = 0 THEN SUM(QUANTITY) ELSE SUM(WEIGHTINKGS) END AS QUANTITY
		FROM 
			STOCKCOUNTINGDETAIL SCD
			INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
			INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		WHERE
			SC.BRANCHID = @BranchID 
			AND (ISNULL(SC.STATUS,0) = 1 OR ISNULL(SC.STATUS,0) = 0)
			AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
		GROUP BY IC.ITEMCODEID,I.ISOPENITEM,SC.STOCKLOCATIONID
	) SC
	INNER JOIN STOCKLOCATION SCL ON SC.STOCKLOCATIONID = SCL.STOCKLOCATIONID
	INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = SC.ITEMCODEID
	INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
	LEFT JOIN SUBCATEGORY SUBCAT ON I.SUBCATEGORYID = SUBCAT.SUBCATEGORYID
	
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGDATA_SALES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
