CREATE PROCEDURE [dbo].[USP_R_COUNTINGDATA_SALES]
@BRANCHID INT,
@ITEMID INT,
@FIRSTCOUNTINGDATE DATETIME,
@LASTCOUNTINGDATE DATETIME
AS
BEGIN

	SELECT 
		I.ITEMID, 
		IC.ITEMCODEID,
		IP.ITEMPRICEID,
		IC.ITEMCODE,
		IP.MRP,
		PBD.CREATEDDATE,
		CASE WHEN I.ISOPENITEM = 0 THEN QUANTITY ELSE WEIGHTINKGS END AS SALE,
		BC.COUNTERNAME,
		PB.BILLID,
		PB.BILLNUMBER,
		BU.FULLNAME AS BILLCLOSEDBY,
		CASE WHEN PBD.CREATEDDATE < @LASTCOUNTINGDATE THEN 'BETWEEN' ELSE 'AFTER' END AS SALETYPE
	FROM POS_BILLDETAIL PBD
		INNER JOIN POS_BILL PB ON PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID  AND PBD.BILLID = PB.BILLID
		INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		INNER JOIN BRANCHCOUNTER BC ON PB.BRANCHCOUNTERID = BC.COUNTERID
		LEFT JOIN TBLUSER BU ON PB.BILLCLOSEDBY = BU.USERID
	WHERE BC.BRANCHID = @BranchID 
		AND I.ITEMID = @ITEMID
		AND PB.DELETEDDATE IS NULL 
		AND PBD.DELETEDDATE IS NULL 
		AND PB.BILLSTATUS = 1 
		AND PBD.CREATEDDATE > @FIRSTCOUNTINGDATE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGDATABYMRP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
