CREATE PROCEDURE [dbo].[USP_R_COUNTINGDATAFORAPPROVAL]
@BranchID int,
@SelectedCategories VARCHAR(MAX)
AS
BEGIN

	CREATE TABLE #CDATA(ITEMPRICEID INT, COUNTEDQUANTITY DECIMAL(18,2), 
		FIRSTCOUNTINGDATE DATETIME, LASTCOUNTNGDATE DATETIME, SALESBETWEEN DECIMAL(18,2), 
		SALESAFTER DECIMAL(18,2), CREFUNDBETWEEN DECIMAL(18,2), CREFUNDAFTER DECIMAL(18,2), 
		FINALQUANTITY DECIMAL(18,2), SYSTEMQUANTITY DECIMAL(18,2))


	SELECT ITEM AS SUBCATEGORYID
	INTO #SubCategories
	FROM dbo.SplitString(@SelectedCategories, ',')

	--Inserting counting data

	INSERT INTO #CDATA(ITEMPRICEID, COUNTEDQUANTITY, FIRSTCOUNTINGDATE, LASTCOUNTNGDATE)
	SELECT 
		IP.ITEMPRICEID, 
		CASE WHEN I.ISOPENITEM = 0 THEN SUM(QUANTITY) ELSE SUM(WEIGHTINKGS) END,
		MIN(SCD.CREATEDDATE),
		MAX(SCD.CREATEDDATE)
	FROM 
		STOCKCOUNTINGDETAIL SCD
		INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
		INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE
		SC.BRANCHID = @BranchID 
		AND (ISNULL(SC.STATUS,0) = 1 OR ISNULL(SC.STATUS,0) = 0)
		AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL 
	GROUP BY IP.ITEMPRICEID,I.ISOPENITEM

	DECLARE @FDATE DATETIME, @LDATE DATETIME

	SELECT @FDATE = MIN(SCD.CREATEDDATE),@LDATE = MAX(SCD.CREATEDDATE)
	FROM 
		STOCKCOUNTINGDETAIL SCD
		INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
		INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE
		SC.BRANCHID = @BranchID 
		AND (ISNULL(SC.STATUS,0) = 1 OR ISNULL(SC.STATUS,0) = 0)
		AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL

	--Inserting not counted items
	INSERT INTO #CDATA(ITEMPRICEID, COUNTEDQUANTITY, FIRSTCOUNTINGDATE, LASTCOUNTNGDATE, 
		SALESBETWEEN, SALESAFTER, CREFUNDBETWEEN, CREFUNDAFTER, FINALQUANTITY, SYSTEMQUANTITY)
	SELECT IP.ITEMPRICEID, 0, @FDATE, @LDATE, 0,0,0,0,0, CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END
	FROM
		STOCKSUMMARY SS WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID	
		INNER JOIN #SubCategories SCAT WITH(NOLOCK) ON SCAT.SUBCATEGORYID = I.SUBCATEGORYID
	WHERE
		SS.BRANCHID = @BRANCHID	
		AND (CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END <> 0)
		--AND IC.DELETEDDATE IS NULL
		AND NOT EXISTS 
			(
				SELECT 1 
				FROM 
					STOCKCOUNTINGDETAIL SED WITH(NOLOCK) 
					INNER JOIN STOCKCOUNTING SC WITH(NOLOCK) ON SC.STOCKCOUNTINGID = SED.STOCKCOUNTINGID  
					INNER JOIN ITEMPRICE IPINNER WITH(NOLOCK) ON SED.ITEMPRICEID = IPINNER.ITEMPRICEID
				WHERE SC.BRANCHID = @BRANCHID 
					AND ((ISNULL(STATUS,0) = 0 OR ISNULL(STATUS,0) = 1))
					AND IPINNER.ITEMPRICEID = IP.ITEMPRICEID
					AND SED.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
				)

	--Updating sales
	SELECT 
		CD.ITEMPRICEID, 
		SUM(CASE WHEN PBD.CREATEDDATE < CD.LASTCOUNTNGDATE THEN PBD.SALE ELSE 0 END) AS BETWEENSALE,
		SUM(CASE WHEN PBD.CREATEDDATE > CD.LASTCOUNTNGDATE THEN PBD.SALE ELSE 0 END) AS AFTERSALE
	INTO #SALES
	FROM #CDATA CD
		INNER JOIN 
			(	SELECT PBD.ITEMPRICEID, PBD.CREATEDDATE, CASE WHEN I.ISOPENITEM = 0 THEN QUANTITY ELSE WEIGHTINKGS END AS SALE FROM POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID  AND PBD.BILLID = PB.BILLID
					INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
					INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
					INNER JOIN BRANCHCOUNTER BC ON PB.BRANCHCOUNTERID = BC.COUNTERID
				WHERE BC.BRANCHID = @BranchID AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL AND PB.BILLSTATUS = 1
			) PBD ON CD.ITEMPRICEID = PBD.ITEMPRICEID AND PBD.CREATEDDATE > CD.FIRSTCOUNTINGDATE

	GROUP BY CD.ITEMPRICEID
	
	UPDATE CD
	SET 
		CD.SALESBETWEEN = ISNULL(S.BETWEENSALE,0),
		CD.SALESAFTER = ISNULL(S.AFTERSALE,0)
	FROM #CDATA CD
	LEFT JOIN #SALES S ON CD.ITEMPRICEID = S.ITEMPRICEID

	SELECT 
		CD.ITEMPRICEID, 
		SUM(CASE WHEN CR.CREATEDDATE < CD.LASTCOUNTNGDATE THEN CR.CREFUND ELSE 0 END) AS BETWEENCREFUND ,
		SUM(CASE WHEN CR.CREATEDDATE > CD.LASTCOUNTNGDATE THEN CR.CREFUND ELSE 0 END) AS AFTERCREFUND 
	INTO #CREFUNDS
	FROM #CDATA CD
		INNER JOIN 
			(	SELECT PBD.ITEMPRICEID, CR.CREATEDDATE, CASE WHEN I.ISOPENITEM = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS CREFUND FROM 
					POS_CREFUND CR  
					INNER JOIN POS_BILLDETAIL PBD ON CR.BILLDETAILID = PBD.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
					INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
					INNER JOIN BRANCHCOUNTER BC ON CR.COUNTERID = BC.COUNTERID
				WHERE BC.BRANCHID = @BranchID
			) CR ON CD.ITEMPRICEID = CR.ITEMPRICEID AND CR.CREATEDDATE > CD.FIRSTCOUNTINGDATE
	GROUP BY CD.ITEMPRICEID

	--Updating crefunds
	UPDATE CD
	SET 
		CD.CREFUNDBETWEEN = ISNULL(CR.BETWEENCREFUND,0),
		CD.CREFUNDAFTER = ISNULL(CR.AFTERCREFUND,0)
	FROM #CDATA CD
	LEFT JOIN #CREFUNDS CR ON CD.ITEMPRICEID = CR.ITEMPRICEID

	UPDATE #CDATA
	SET FINALQUANTITY = COUNTEDQUANTITY - ISNULL(SALESBETWEEN,0) - ISNULL(SALESAFTER,0) + ISNULL(CREFUNDBETWEEN,0) + ISNULL(CREFUNDAFTER,0)

	UPDATE CD
	SET CD.SYSTEMQUANTITY = CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END
	FROM #CDATA CD 
	INNER JOIN STOCKSUMMARY SS ON CD.ITEMPRICEID = SS.ITEMPRICEID AND SS.BRANCHID = @BranchID
	INNER JOIN ITEMPRICE IP ON SS.ITEMPRICEID = IP.ITEMPRICEID
	INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
	INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID  

	SELECT I.ITEMID,IP.ITEMPRICEID, I.SKUCODE, IC.ITEMCODE, I.ITEMNAME, CAT.CATEGORYNAME, SCAT.SUBCATEGORYNAME,IP.MRP,
		CD.COUNTEDQUANTITY, CD.FIRSTCOUNTINGDATE, CD.LASTCOUNTNGDATE, 
		 CD.SALESAFTER, CD.CREFUNDAFTER, 0 AS BREFUND, 0 AS DISPATCH, CD.FINALQUANTITY,CD.SYSTEMQUANTITY,
		CASE WHEN CD.SALESBETWEEN <> 0 THEN 'YES' ELSE 'NO' END RECOUNTINGREQUIRED, CD.SALESBETWEEN, CD.CREFUNDBETWEEN
	FROM #CDATA CD 
		INNER JOIN ITEMPRICE IP ON CD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID  
		INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_COUNTINGDETAIL]
@BranchID INT,
@ItemID INT,
@COUNTINGAPPROVALID INT = 0
AS
BEGIN

	IF(@COUNTINGAPPROVALID > 0)
	BEGIN
		SELECT 
			SC.STOCKCOUNTINGID
			, SCD.STOCKCOUNTINGDETAILID
			, I.SKUCODE
			, I.ITEMNAME
			, IC.ITEMCODE
			, IP.MRP
			, SCD.QUANTITY 
			, SCD.WEIGHTINKGS
			, U.FULLNAME
			, SCD.CREATEDDATE
			, SC.STOCKLOCATIONID
			, SCL.STOCKLOCATIONNAME
		FROM STOCKCOUNTINGDETAIL SCD
			INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
			INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
			INNER JOIN TBLUSER U ON SC.CREATEDBY = U.USERID
			LEFT JOIN STOCKLOCATION SCL ON SC.STOCKLOCATIONID = SCL.STOCKLOCATIONID
		WHERE ISNULL(SC.COUNTINGAPPROVALID,0) = @COUNTINGAPPROVALID AND I.ITEMID = @ItemID
			AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
	END
	ELSE
	BEGIN

		SELECT 
			SC.STOCKCOUNTINGID
			, SCD.STOCKCOUNTINGDETAILID
			, I.SKUCODE
			, I.ITEMNAME
			, IC.ITEMCODE
			, IP.MRP
			, SCD.QUANTITY 
			, SCD.WEIGHTINKGS
			, U.FULLNAME
			, SCD.CREATEDDATE
			, SC.STOCKLOCATIONID
			, SCL.STOCKLOCATIONNAME
		FROM STOCKCOUNTINGDETAIL SCD
			INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
			INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
			INNER JOIN TBLUSER U ON SC.CREATEDBY = U.USERID
			LEFT JOIN STOCKLOCATION SCL ON SC.STOCKLOCATIONID = SCL.STOCKLOCATIONID
		WHERE SC.BRANCHID = @BranchID AND I.ITEMID = @ItemID
			AND (ISNULL(SC.STATUS,0) = 0 OR ISNULL(SC.STATUS,0) = 1)
			AND SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL

	END
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGITEMSBYAPPROVALID]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_COUNTINGITEMSBYAPPROVALID]
@COUNTINGAPPROVALID INT,
@IncludeMRP bit = 0
AS
BEGIN

	
	SELECT
		I.SKUCODE,
		IC.ITEMID,
		IC.ITEMCODEID,
		IP.ITEMPRICEID,
		IC.ITEMCODE,
		I.ITEMNAME,
		IP.MRP,
		C.CATEGORYNAME,
		SC.SUBCATEGORYNAME,
		CASE WHEN I.ISOPENITEM = 0 THEN SCD.PHYSICALQAUNTITY ELSE SCD.PHYSICALWEIGHTINKGS END AS PHYSICALQAUNTITY,
		CASE WHEN I.ISOPENITEM = 0 THEN SCD.SYSTEMQUANTITY ELSE SCD.SYSTEMWEIGHTINKGS END AS SYSTEMQUANTITY
	FROM 
		(
			SELECT 
				ITEMCODEID,
				CASE WHEN @IncludeMRP = 0 THEN NULL ELSE IP.ITEMPRICEID END AS ITEMPRICEID,
				SUM(PHYSICALQAUNTITY) AS PHYSICALQAUNTITY,
				SUM(PHYSICALWEIGHTINKGS) AS PHYSICALWEIGHTINKGS,
				SUM(SYSTEMQUANTITY) AS SYSTEMQUANTITY,
				SUM(SYSTEMWEIGHTINKGS) AS SYSTEMWEIGHTINKGS
			FROM 
				COUNTINGAPPROVALITEM CAI
				INNER JOIN ITEMPRICE IP ON CAI.ITEMPRICEID = IP.ITEMPRICEID
			WHERE
				CAI.COUNTINGAPPROVALID = @COUNTINGAPPROVALID
			GROUP BY ITEMCODEID, CASE WHEN @IncludeMRP = 0 THEN NULL ELSE IP.ITEMPRICEID END
		) SCD
		LEFT JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON SCD.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
	ORDER BY I.ITEMNAME, IC.ITEMCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_COUNTINGSHEETSBYAPPROVALID]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_COUNTINGSHEETSBYAPPROVALID]
@COUNTINGAPPROVALID INT
AS
BEGIN

	SELECT 
		SC.STOCKCOUNTINGID,                 
		scl.STOCKLOCATIONNAME AS [Stock Location],
		CU.FULLNAME AS CREATEDBY,                
		SC.CREATEDDATE,                
		UU.FULLNAME AS SubmittedBy,                
		SC.UPDATEDDATE SubmittedDate,                
		CASE WHEN ISNULL(SC.STATUS,0) = 0 THEN 'Draft'                
		WHEN  ISNULL(SC.STATUS,0) = 1 then 'Submitted'     
		WHEN  ISNULL(SC.STATUS,0) = 2 then 'Accepted' 
		WHEN  ISNULL(SC.STATUS,0) = 3 then 'Archived' END AS STATUS,
		ARU.FULLNAME AS ArchivedBy,
		SC.ArchivedDate
	FROM STOCKCOUNTING SC
		left join STOCKLOCATION scl on sc.STOCKLOCATIONID = scl.STOCKLOCATIONID
		left JOIN TBLUSER CU ON SC.CREATEDBY = CU.USERID                
		left JOIN TBLUSER UU ON SC.UPDATEDBY = UU.USERID                
		LEFT JOIN TBLUSER ARU ON SC.ArchivedBy = ARU.USERID
	WHERE SC.COUNTINGAPPROVALID = @COUNTINGAPPROVALID
	ORDER BY ISNULL(SC.UPDATEDDATE, SC.CREATEDDATE) DESC

END
GO
