CREATE PROCEDURE [dbo].[usp_R_CreditNote_GetById]
(
    @CreditNoteId INT
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        cn.CreditNoteId,
        cn.CNNumber,
        cn.Description,

        cn.SupplierId,
        s.DEALERNAME,

        cn.CreditValue,

        cn.CreditNoteAdjustmentTypeId,
        cat.Description AS AdjustmentType,

        cn.StockEntryId,
        se.SUPPLIERINVOICENO,

        cn.CreatedBy,
        cn.CreatedDate,
        cn.UpdatedBy,
        cn.UpdatedDate
    FROM CreditNote cn
    INNER JOIN TBLDEALER s
        ON cn.SupplierId = s.DEALERID
    INNER JOIN CreditNoteAdjustmentType cat
        ON cn.CreditNoteAdjustmentTypeId = cat.CreditNoteAdjustmentTypeId
    LEFT JOIN StockEntry se
        ON cn.StockEntryId = se.StockEntryId
    WHERE cn.CreditNoteId = @CreditNoteId
      AND cn.DeletedDate IS NULL;
END;
GO
/****** Object:  StoredProcedure [dbo].[usp_R_CreditNote_List]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_R_CreditNote_List]
(
    @SupplierId INT = 0,
    @FromDate DATETIME = NULL,
    @ToDate DATETIME = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Aggregate mappings from Supplier Returns
    ;WITH SRMap AS
    (
        SELECT 
            CREDITNOTEID,
            SUM(MappedReturnValue) AS MappedValue
        FROM SUPPLIERRETURNSCREDITNOTEMAP
        WHERE DELETEDDATE IS NULL
        GROUP BY CREDITNOTEID
    ),
    
    -- Aggregate mappings from Stock Entry
    SEMap AS
    (
        SELECT 
            CREDITNOTEID,
            SUM(0) AS MappedValue
        FROM STOCKENTRYCREDITNOTEMAP
        WHERE DELETEDDATE IS NULL
        GROUP BY CREDITNOTEID
    ),

    -- Combine both mappings
    TotalMap AS
    (
        SELECT 
            CREDITNOTEID,
            SUM(MappedValue) AS MappedValue
        FROM
        (
            SELECT * FROM SRMap
            UNION ALL
            SELECT * FROM SEMap
        ) X
        GROUP BY CREDITNOTEID
    )

    SELECT
        cn.CreditNoteId,
        cn.CNNumber,
        cn.SupplierID,
        s.DEALERNAME,
        cn.CreditValue,
        ISNULL(tm.MappedValue,0) AS MappedValue,
        cn.CreditValue - ISNULL(tm.MappedValue,0) AS BalanceCNValueCanBeMapped,
        cat.Description AS AdjustmentType,
        cn.StockEntryId,
        se.SUPPLIERINVOICENO,
        cn.CreatedDate,
        cn.Description
    FROM CreditNote cn

    INNER JOIN TBLDEALER s
        ON cn.SupplierId = s.DEALERID

    LEFT JOIN CreditNoteAdjustmentType cat
        ON cn.CreditNoteAdjustmentTypeId = cat.CreditNoteAdjustmentTypeId

    LEFT JOIN StockEntry se
        ON cn.StockEntryId = se.StockEntryId

    LEFT JOIN TotalMap tm
        ON tm.CREDITNOTEID = cn.CreditNoteId

    WHERE cn.DeletedDate IS NULL
      AND (@SupplierId = 0 OR cn.SupplierId = @SupplierId)
      AND (@FromDate IS NULL OR cn.CreatedDate >= @FromDate)
      AND (@ToDate IS NULL OR cn.CreatedDate < DATEADD(DAY,1,@ToDate))

    ORDER BY cn.CreatedDate DESC;

END
GO
/****** Object:  StoredProcedure [dbo].[usp_R_CreditNote_Mappings]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_R_CreditNote_Mappings]
(
    @CreditNoteId INT
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Supplier Returns mappings
    SELECT
        'SR' AS ReferenceType,
        srcm.SupplierReturnsId AS ReferenceId,
        sr.SupplierReturnsId as MapRefId,
		sr.SupplierReturnsId as MapRefNumber,
        srcm.MappedReturnValue AS MappedValue,
        srcm.CreatedDate
    FROM SUPPLIERRETURNSCREDITNOTEMAP srcm
    INNER JOIN SUPPLIERRETURNS sr
        ON srcm.SupplierReturnsId = sr.SupplierReturnsId
    WHERE srcm.CreditNoteId = @CreditNoteId
      AND srcm.DeletedDate IS NULL

    UNION ALL

    -- Stock Entry mappings
    SELECT
        'SE' AS ReferenceType,
        secm.StockEntryId AS ReferenceId,
        se.StockEntryId as MapRefId,
		se.SUPPLIERINVOICENO AS MapRefNumber,
        secm.MappedReturnValue AS MappedValue,
        secm.CreatedDate
    FROM STOCKENTRYCREDITNOTEMAP secm
    INNER JOIN STOCKENTRY se
        ON secm.StockEntryId = se.StockEntryId
    WHERE secm.CreditNoteId = @CreditNoteId
      AND secm.DeletedDate IS NULL

    ORDER BY CreatedDate DESC;

END
GO
