/****** Object:  StoredProcedure [dbo].[usp_R_CreditNotes_ForMapping]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_R_CreditNotes_ForMapping]
(
    @SupplierRefId INT,
    @ReferenceType VARCHAR(10)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SupplierId INT;

    -- Get SupplierId based on reference
    IF (@ReferenceType = 'SR')
    BEGIN
        SELECT @SupplierId = SupplierId
        FROM SUPPLIERRETURNS
        WHERE SUPPLIERRETURNSID = @SupplierRefId;
    END
    ELSE IF (@ReferenceType = 'SE')
    BEGIN
        SELECT @SupplierId = SupplierId
        FROM STOCKENTRY
        WHERE STOCKENTRYID = @SupplierRefId;
    END

    IF @SupplierId IS NULL
        THROW 50010, 'Invalid reference', 1;

   SELECT
    cn.CreditNoteId,
    cn.CNNumber,
    cn.CreditValue AS TotalCNValue,
    ISNULL(srcm.MappedValue,0) + ISNULL(secm.MappedValue,0) AS MappedCNValue,
    cn.CreditValue - (ISNULL(srcm.MappedValue,0) + ISNULL(secm.MappedValue,0)) AS BalanceCNValueCanBeMapped,
    cat.Description AS AdjustmentType,
    cn.CreatedDate
	FROM CreditNote cn
	INNER JOIN CreditNoteAdjustmentType cat
		ON cn.CreditNoteAdjustmentTypeId = cat.CreditNoteAdjustmentTypeId
	LEFT JOIN
	(
		SELECT CREDITNOTEID, SUM(MappedReturnValue) AS MappedValue
		FROM SUPPLIERRETURNSCREDITNOTEMAP
		WHERE DELETEDDATE IS NULL
		GROUP BY CREDITNOTEID
	) srcm
		ON srcm.CREDITNOTEID = cn.CreditNoteId
	LEFT JOIN
	(
		SELECT CREDITNOTEID, SUM(MappedReturnValue) AS MappedValue
		FROM STOCKENTRYCREDITNOTEMAP
		WHERE DELETEDDATE IS NULL
		GROUP BY CREDITNOTEID
	) secm
		ON secm.CREDITNOTEID = cn.CreditNoteId
    WHERE cn.SupplierId = @SupplierId
      AND cn.DeletedDate IS NULL
      AND (cn.CreditValue - (ISNULL(srcm.MappedValue,0) + ISNULL(secm.MappedValue,0))) > 0

    ORDER BY cn.CreatedDate DESC;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_CREFUNDITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_CREFUNDITEMS]
@BILLID INT,
@BRANCHCOUNTERID INT
AS
BEGIN

	SELECT
		CR.BILLNUMBER, IC.ITEMCODE, I.ITEMNAME, IP.MRP, IP.SALEPRICE, CR.REFUNDQUANTITY AS QUANTITY
		, CR.REFUNDWEIGHTINKGS AS WEIGHTINKGS, CR.REFUNDAMOUNT AS BILLEDAMOUNT, CR.CREATEDDATE  ,I.ISOPENITEM, IC.HSNCODE
	FROM 
		(    
			SELECT 
				BD.ITEMPRICEID, PB.BILLNUMBER, SUM(CR.REFUNDQUANTITY) AS REFUNDQUANTITY
				, SUM(ISNULL(CR.REFUNDWEIGHTINKGS,0)) AS REFUNDWEIGHTINKGS, SUM(REFUNDAMOUNT) AS REFUNDAMOUNT
				, MAX(CR.CREATEDDATE) CREATEDDATE
			FROM 
				POS_CREFUND CR    
				INNER JOIN POS_BILLDETAIL BD ON CR.BILLDETAILID = BD.BILLDETAILID AND CR.COUNTERID = BD.BRANCHCOUNTERID    
				INNER JOIN POS_BILL PB ON PB.BILLID = BD.BILLID AND PB.BRANCHCOUNTERID = BD.BRANCHCOUNTERID
			WHERE CR.COUNTERID = @BRANCHCOUNTERID     
				AND PB.BILLID = @BILLID
			GROUP BY ITEMPRICEID, PB.BILLNUMBER
		) CR    
		INNER JOIN ITEMPRICE IP ON CR.ITEMPRICEID = IP.ITEMPRICEID    
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID    
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
    ORDER BY CR.BILLNUMBER, I.ITEMNAME
 
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_CREFUNDSHEETS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_R_CREFUNDSHEETS]
@BRANCHID VARCHAR(500),
@FromDate DATE = NULL,
@ToDate DATE = NULL,
@UnmaskCustomerPhone BIT = 0
AS
BEGIN

	SELECT 
		PB.BILLID,
		CR.BILLDETAILID,
		PB.BRANCHCOUNTERID,
		CR.CREATEDBY,
		CR.CREATEDDATE,
		SUM(CR.REFUNDQUANTITY) REFUNDQUANTITY,
		SUM(CR.REFUNDWEIGHTINKGS) REFUNDWEIGHTINKGS,
		SUM(CR.REFUNDAMOUNT) AS REFUNDAMOUNT
	INTO #CR
	FROM POS_CREFUND CR 
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CR.COUNTERID
		INNER JOIN dbo.SplitString(@BranchID,',') B ON BC.BRANCHID = B.ITEM
		LEFT JOIN POS_BILLDETAIL PBD ON CR.BILLDETAILID = PBD.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
		LEFT JOIN POS_BILL PB ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
	WHERE CR.CREATEDDATE >= @FromDate     
		AND CR.CREATEDDATE <= DATEADD(day,1,@ToDate)
	GROUP BY PB.BILLID, PB.BRANCHCOUNTERID, CR.CREATEDBY, CR.CREATEDDATE, CR.BILLDETAILID

	SELECT 
		CR.CREATEDDATE AS REFUNDDATE, 
		FORMAT(CR.CREATEDDATE, 'HH:mm:ss') AS REFUNDTIME, 
		RU.FULLNAME AS CREATEDBY, CR.BILLID, B.BRANCHID, CR.BRANCHCOUNTERID, B.BRANCHNAME, 
		BC.COUNTERNAME, PB.BILLNUMBER, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE,
		CASE WHEN I.ISOPENITEM = 1 THEN CR.REFUNDWEIGHTINKGS ELSE CR.REFUNDQUANTITY END REFUNDQTYORWGHTINKGS
		, CR.REFUNDAMOUNT, PB.CUSTOMERNAME
		, CASE WHEN PB.CUSTOMERNUMBER IS NOT NULL AND @UnmaskCustomerPhone = 0 THEN 'XXXXXX' + RIGHT(PB.CUSTOMERNUMBER, 4) ELSE PB.CUSTOMERNUMBER END CUSTOMERNUMBER
		, PB.CREATEDDATE AS BILLOPENDATE, 
		FORMAT(PB.CREATEDDATE, 'HH:mm:ss') AS BILLOPENTIME, 
		FORMAT(PB.BILLCLOSEDDATE, 'HH:mm:ss') AS BILLCLOSEDTIME
	FROM #CR CR
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BRANCHCOUNTERID = CR.BRANCHCOUNTERID AND PB.BILLID = CR.BILLID
		INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CR.BILLDETAILID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLUSER RU WITH(NOLOCK) ON RU.USERID = CR.CREATEDBY
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CR.BRANCHCOUNTERID
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = BC.BRANCHID
	ORDER BY B.BRANCHNAME, PB.BILLNUMBER

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_CURRENTSTOCK]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_CURRENTSTOCK]    
@FROMBRANCHID INT,    
@TOBRANCHID INT,    
@ITEMCODEID INT,    
@PARENTITEMID INT = 0  ,
@ITEMPRICEID INT = 0
    
AS    
BEGIN    
    
	DECLARE @FROMBRANCHSTCK DECIMAL(18,2) = 0,@TOBRANCHSTOCK DECIMAL(18,2) = 0, @isWarehouse BIT = 0, @isOpenItem BIT = 0
	SELECT @isWarehouse = ISNULL(ISWAREHOUSE,0) FROM BRANCH WHERE BRANCHID = @TOBRANCHID
	SELECT @isOpenItem = ISNULL(I.ISOPENITEM,0) FROM ITEMCODE IC INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID WHERE IC.ITEMCODEID = @ITEMCODEID

	IF(@isWarehouse = 1  AND (@PARENTITEMID > 0 OR @isOpenItem = 1))
	BEGIN
		IF(@isOpenItem = 1)
		BEGIN
			
			SELECT @FROMBRANCHSTCK = SUM(WEIGHTINKGS)
			FROM STOCKSUMMARY SS    
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
			WHERE SS.BRANCHID = @FROMBRANCHID AND IP.ITEMCODEID = @ITEMCODEID

		END
		ELSE
		BEGIN

			SELECT @FROMBRANCHSTCK = SUM(WEIGHTINKGS)
			FROM STOCKSUMMARY SS    
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID    
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
			WHERE SS.BRANCHID = @FROMBRANCHID AND I.ITEMID = @PARENTITEMID    

		END
	END
	
	IF(@isWarehouse = 0)
	BEGIN    
  
		SELECT @FROMBRANCHSTCK = CASE WHEN @isOpenItem = 1 THEN SUM(WEIGHTINKGS) ELSE SUM(QUANTITY) END
		FROM STOCKSUMMARY SS   
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
		WHERE SS.BRANCHID = @FROMBRANCHID AND IP.ITEMCODEID = @ITEMCODEID      
  
	END    
      
	SELECT @TOBRANCHSTOCK = CASE WHEN @isOpenItem = 1 THEN SUM(WEIGHTINKGS) ELSE SUM(QUANTITY) END
	FROM STOCKSUMMARY SS  
	INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
	WHERE SS.BRANCHID = @TOBRANCHID AND IP.ITEMCODEID = @ITEMCODEID  

	SELECT @FROMBRANCHSTCK AS WHSTOCK, @TOBRANCHSTOCK AS BRANCHSTOCK
    
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DAYCLOSURE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DAYCLOSURE]                  
@BRANCHID VARCHAR(500),
@FromDate Date = NULL,      
@ToDate Date = NULL      
                  
AS                  
BEGIN                  
                  
	SELECT                 
		DC.DAYCLOSUREID,  
		B.BRANCHNAME,                
		BC.COUNTERNAME,
		DC.CLOSUREDATE,                
		DC.BRANCHCOUNTERID,                
		DC.OPENINGBALANCE,     
		DC.REFUNDAMOUNT,
		DC.OPENINGBALANCE - DC.REFUNDAMOUNT AS DAYTURNOVER,                
		DC.CLOSINGBALANCE,                
		DC.CLOSINGDIFFERENCE,
		VB.VOIDAMOUNT,		
		CU.FULLNAME AS CLOSEDBY   , 
		CASE WHEN DC.ISPROCESSED = 1 THEN 'Processed' ELSE 'Yet to process' END AS IsProcessed, 
		DC.PROCESSEDTIME
	FROM POS_DAYCLOSURE DC                  
		INNER JOIN BRANCHCOUNTER BC ON DC.BRANCHCOUNTERID = BC.COUNTERID                  
		INNER JOIN BRANCH B ON BC.BRANCHID = B.BRANCHID              
		INNER JOIN dbo.SplitString(@BRANCHID,',') BIDS ON B.BRANCHID = BIDS.ITEM
		INNER JOIN TBLUSER CU ON DC.CLOSEDBY = CU.USERID     
		LEFT JOIN 
			(
				SELECT PB.BRANCHCOUNTERID, PB.DAYCLOSUREID, SUM(PBD.BILLEDAMOUNT) VOIDAMOUNT
				FROM 
					POS_BILL PB 
					INNER JOIN POS_BILLDETAIL PBD ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
				WHERE 
					PB.CREATEDDATE >= @FromDate     
					AND PB.CREATEDDATE <= DATEADD(day,1,@ToDate)					
					AND PBD.DELETEDDATE IS NOT NULL
				GROUP BY PB.BRANCHCOUNTERID, PB.DAYCLOSUREID
			) VB ON VB.BRANCHCOUNTERID = DC.BRANCHCOUNTERID AND VB.DAYCLOSUREID = DC.DAYCLOSUREID
	WHERE DC.CREATEDDATE >= @FromDate     
		AND DC.CREATEDDATE <= DATEADD(day,1,@ToDate)
	ORDER BY B.BRANCHCODE ASC,BC.COUNTERNAME ASC,DC.CLOSUREDATE DESC  
  
                  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DAYCLOSUREBILL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DAYCLOSUREBILL]        
@COUNTERID INT,        
@DAYCLOSUREID INT        
AS        
BEGIN        
        
SELECT         
	B.BILLID        
	,B.BRANCHCOUNTERID        
	,B.DAYCLOSUREID        
	,B.BILLNUMBER        
	,B.CUSTOMERNAME        
	,B.CUSTOMERNUMBER    
	,BD.BILLEDAMOUNT AS ITEMAMOUNT  
	,BM.MOPVALUE AS MOPAMOUNT  
	,BD.BILLEDAMOUNT - BM.MOPVALUE AS BillDIFF
	,CU.FULLNAME AS CREATEDBY        
	,CONVERT(VARCHAR(10),B.CREATEDDATE,8) AS CREATEDDATE
	,B.UPDATEDDATE
	,B.TENDEREDCASH
	,B.TENDEREDCHANGE
	,B.ISDOORDELIVERY
	,CASE WHEN B.BILLSTATUS = 0 THEN 'Open Bill' 
		WHEN B.BILLSTATUS = 1 THEN 'Completed Bill' 
		WHEN B.BILLSTATUS = 2 THEN 'Draft Bill' ELSE 'Unknown' END AS BILLSTATUS
	,B.BILLSTATUS  AS BILLSTATUSID
	,FU.FULLNAME AS BILLCLOSEDBY
	,CONVERT(VARCHAR(10), B.BILLCLOSEDDATE,8) AS BILLCLOSEDDATE
FROM  POS_BILL B        
	LEFT JOIN( 
		SELECT BRANCHCOUNTERID,BILLID, SUM(BILLEDAMOUNT) AS BILLEDAMOUNT FROM POS_BILLDETAIL   
		WHERE BRANCHCOUNTERID = @COUNTERID AND DAYCLOSUREID = @DAYCLOSUREID AND DELETEDDATE IS NULL  
		GROUP BY BRANCHCOUNTERID,BILLID
		) BD 
	
		ON B.BILLID = BD.BILLID AND B.BRANCHCOUNTERID = BD.BRANCHCOUNTERID  

	LEFT JOIN   
	(
		SELECT COUNTERID,BILLID,SUM(MOPVALUE) AS MOPVALUE FROM POS_BILLMOPDETAIL   
		WHERE COUNTERID = @COUNTERID AND DAYCLOSUREID = @DAYCLOSUREID  
		GROUP BY COUNTERID,BILLID
	) BM ON B.BILLID = BM.BILLID AND B.BRANCHCOUNTERID = BM.COUNTERID  

	INNER JOIN TBLUSER CU ON B.CREATEDBY = CU.USERID 
	LEFT JOIN TBLUSER FU ON B.BILLCLOSEDBY = FU.USERID
WHERE B.BRANCHCOUNTERID = @COUNTERID AND B.DAYCLOSUREID = @DAYCLOSUREID
ORDER BY B.BILLID
  
END
GO
