CREATE PROCEDURE [dbo].[USP_R_DAYCLOSUREDETAIL]  
@DAYCLOSUREID INT,  
@COUNTERID INT  
  
AS  
BEGIN  
  
SELECT DCD.MOPID,MOP.MOPNAME,DCD.CLOSUREVALUE FROM (  
SELECT   
MOPID,
SUM(CLOSUREVALUE) AS CLOSUREVALUE  
FROM POS_DAYCLOSUREDETAIL  
WHERE DAYCLOSUREID = @DAYCLOSUREID AND COUNTERID = @COUNTERID  
GROUP BY MOPID) DCD   
LEFT JOIN TBLMOP MOP ON ISNULL(DCD.MOPID,1) = MOP.MOPID  
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DAYCLOSUREITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DAYCLOSUREITEMS]            
@BRANCHCOUNTERID INT,            
@DAYCLOSUREID INT          
AS            
BEGIN            
            
SELECT             
            
IC.ITEMCODE,I.ITEMNAME,IP.MRP,IP.SALEPRICE,BD.QUANTITY,            
BD.WEIGHTINKGS,BD.BILLEDAMOUNT,BD.DISCOUNT, BD.ITEMPRICEID FROM (            
  
  
SELECT ITEMPRICEID            
, SUM(QUANTITY) AS QUANTITY            
,SUM(ISNULL(WEIGHTINKGS,0)) AS WEIGHTINKGS            
,SUM(DISCOUNT) AS DISCOUNT            
,SUM(BILLEDAMOUNT) AS BILLEDAMOUNT            
FROM POS_BILLDETAIL BD       
INNER JOIN POS_BILL B ON BD.BRANCHCOUNTERID = B.BRANCHCOUNTERID  AND BD.DAYCLOSUREID = B.DAYCLOSUREID    
AND BD.BILLID = B.BILLID  
	WHERE 
	BD.DELETEDDATE IS NULL
	AND B.BRANCHCOUNTERID = @BRANCHCOUNTERID 
	AND B.DAYCLOSUREID = @DAYCLOSUREID            
	AND B.BILLSTATUS = 1 
	
	GROUP BY ITEMPRICEID  
 
) BD            
INNER JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID            
INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID            
INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID            
            
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DAYCLOSUREREFUND]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DAYCLOSUREREFUND]    
@DAYCLOSUREID INT,    
@BRANCHCOUNTERID INT    
AS    
BEGIN    
    
	SELECT
		CR.BILLNUMBER, IC.ITEMCODE, I.ITEMNAME, IP.MRP, IP.SALEPRICE, CR.REFUNDQUANTITY AS QUANTITY
		, CR.REFUNDWEIGHTINKGS AS WEIGHTINKGS, CR.REFUNDAMOUNT AS BILLEDAMOUNT, CR.CREATEDDATE    
	FROM 
		(    
			SELECT 
				BD.ITEMPRICEID, PB.BILLNUMBER, SUM(CR.REFUNDQUANTITY) AS REFUNDQUANTITY
				, SUM(ISNULL(CR.REFUNDWEIGHTINKGS,0)) AS REFUNDWEIGHTINKGS, SUM(REFUNDAMOUNT) AS REFUNDAMOUNT
				, MAX(CR.CREATEDDATE) CREATEDDATE
			FROM 
				POS_CREFUND CR    
				INNER JOIN POS_BILLDETAIL BD ON CR.BILLDETAILID = BD.BILLDETAILID AND CR.COUNTERID = BD.BRANCHCOUNTERID    
				INNER JOIN POS_BILL PB ON PB.BILLID = BD.BILLID AND PB.BRANCHCOUNTERID = BD.BRANCHCOUNTERID
			WHERE 
				CR.COUNTERID = @BRANCHCOUNTERID     
				AND CR.DAYCLOSUREID = @DAYCLOSUREID    
			GROUP BY ITEMPRICEID, PB.BILLNUMBER
		) CR    
		INNER JOIN ITEMPRICE IP ON CR.ITEMPRICEID = IP.ITEMPRICEID    
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID    
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
    ORDER BY CR.BILLNUMBER, I.ITEMNAME
END
GO
