CREATE PROCEDURE [dbo].[USP_R_DEALER]      
AS      
BEGIN      
	SELECT       
		D.DEALERID,      
		D.DEALERNAME,  
		D.VENDORCODE,
		D.ADDRESS,      
		D.SHIPPINGADDRESS,      
		D.STATEID,
		D.PHONENO,      
		D.GSTIN,      
		D.PANNUMBER,      
		D.EMAILID,      
		C.FULLNAME AS CREATEDBY,D.CREATEDDATE,      
		U.FULLNAME AS UPDATEDBY,D.UPDATEDDATE, 
		CASE WHEN D.GSTIN LIKE '37%' THEN 0 ELSE 1 END AS ISIGST
	FROM TBLDealer  D    
		LEFT JOIN TBLUSER C ON D.CREATEDBY = C.USERID        
		LEFT JOIN TBLUSER U ON D.UPDATEDBY = U.USERID        
		LEFT JOIN TBLSTATE S ON D.STATEID = S.STATEID
	WHERE D.DELETEDDATE IS NULL
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DEALER_METADATA]    Script Date: 17-10-2026 13:04:47 ******/
