CREATE PROCEDURE [dbo].[USP_R_DEALER_METADATA]      
AS      
BEGIN      
	SELECT       
		D.DEALERID,      
		D.DEALERNAME,  
		D.VENDORCODE,
		D.ADDRESS,      
		D.SHIPPINGADDRESS,      
		D.STATEID,
		D.PHONENO,      
		D.GSTIN,      
		D.PANNUMBER,      
		D.EMAILID,      
		C.FULLNAME AS CREATEDBY,D.CREATEDDATE,      
		U.FULLNAME AS UPDATEDBY,D.UPDATEDDATE, 
		CASE WHEN D.GSTIN LIKE '37%' THEN 0 ELSE 1 END AS ISIGST,
		CASE WHEN D.DELETEDDATE IS NULL THEN 'Active' ELSE 'In-Active' END AS STATUS,
		D.AUTORUNFREQID, ARFQID.ENUMVALUE AUTORUNFREQTXT
	FROM TBLDealer  D    
		LEFT JOIN TBLUSER C ON D.CREATEDBY = C.USERID        
		LEFT JOIN TBLUSER U ON D.UPDATEDBY = U.USERID        
		LEFT JOIN TBLSTATE S ON D.STATEID = S.STATEID
		LEFT JOIN ENUMLIST ARFQID ON ARFQID.ENUMID = D.AUTORUNFREQID
END
