CREATE PROCEDURE [dbo].[USP_R_DEALER_v2]
@SearchKey NVARCHAR(50) = ''
AS      
BEGIN      
	SELECT 1 AS PARENTID
	
	SELECT 
		1 AS PARENTID,
		DEALERID AS SUPPLIERID,      
		DEALERNAME SUPPLIERNAME,      
		GSTIN,      
		PANNUMBER,      
		CASE WHEN GSTIN LIKE '37%' THEN 0 ELSE 1 END AS ISIGST
	FROM TBLDealer
	WHERE DELETEDBY IS NULL AND DEALERNAME LIKE '%' + @SearchKey + '%'
