/****** Object:  StoredProcedure [dbo].[USP_R_DEALERINDENT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DEALERINDENT]    
@DealerID INT,    
@CategoryID INT,    
@IndentDays INT,    
@SafetyStockDays INT    
AS    
BEGIN    
  
	DECLARE @FromDate DATE, @ToDate DATE, @MultiplierDays INT, @IndentSaleFromDate DATE

	SELECT @FromDate = GETDATE() - 180, @ToDate = DATEADD(d, 1, GETDATE()), @MultiplierDays = @IndentDays + @SafetyStockDays, @IndentSaleFromDate = GETDATE() - @IndentDays
	  
	CREATE TABLE #DealerIndentBranchDetails(ITEMID INT, SKUCODE VARCHAR(100), ITEMNAME VARCHAR(200), SUBCATEGORYID INT,  
		BranchQuantity DECIMAL(18, 2), BRANCHID INT, BRANCHSTOCK DECIMAL(18, 2) DEFAULT 0, AVGSALEQUANTITY DECIMAL(18, 2) DEFAULT 0, INDENTDAYSSALEQUANTITY DECIMAL(18, 2) DEFAULT 0
		, BRANCHINDENTQUANTITY DECIMAL(18, 2) DEFAULT 0)  
	
	CREATE TABLE #DelearIndentItems(SNO INT, ITEMID INT, SKUCODE VARCHAR(20), ITEMNAME VARCHAR(200), SUBCATEGORYNAME VARCHAR(100), BranchQuantity DECIMAL(18, 2) DEFAULT 0
		, REQUIREDBRANCHSTOCK DECIMAL(18, 2) DEFAULT 0, REQUIREDITEMINDENT DECIMAL(18, 2) DEFAULT 0, DESIREDINDENT DECIMAL(18, 2) DEFAULT 0)

	INSERT INTO #DealerIndentBranchDetails(ITEMID, SKUCODE,ITEMNAME,SUBCATEGORYID, BRANCHID)  
	SELECT
		I.ITEMID, I.SKUCODE, I.ITEMNAME, I.SUBCATEGORYID, B.BRANCHID
	FROM 
		ITEM I
		CROSS APPLY BRANCH B
	WHERE 
		I.CATEGORYID = @CategoryID   
		AND B.DELETEDDATE IS NULL
		AND I.DELETEDDATE IS NULL
		AND B.ISWAREHOUSE = 0
		AND EXISTS
			(
				SELECT 1 
				FROM 
					ITEMCODE IC WITH(NOLOCK)  
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID  
					INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMPRICEID = IP.ITEMPRICEID  
					INNER JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID  
					INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID  
				WHERE 
					IC.ITEMID = I.ITEMID AND SE.SUPPLIERID = @DealerID AND SED.DELETEDDATE IS NULL
			)   		
  
	UPDATE DIBD SET   
	DIBD.BranchQuantity = WHS.QUANTITY  
	FROM #DealerIndentBranchDetails DIBD  
	INNER JOIN 
		( 
			SELECT I.ITEMID, SUM(SS.QUANTITY) AS QUANTITY  
			FROM 
				STOCKSUMMARY SS WITH(NOLOCK)    
				INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
				INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID    
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID    
			WHERE 
				SS.BRANCHID = 45 
				AND I.CATEGORYID = @CategoryID 
				AND I.ISOPENITEM <> 1
			GROUP BY I.ITEMID
		) WHS ON DIBD.ITEMID = WHS.ITEMID  
	  
	UPDATE DIBD
	SET DIBD.AVGSALEQUANTITY = ITEMSALE.SALEQUANTITY * 1.00 / 180 
	FROM
		#DealerIndentBranchDetails DIBD  
		INNER JOIN
		( 
			SELECT 
				IC.ITEMID, SUM(PBD.QUANTITY) AS SALEQUANTITY, BC.BRANCHID  
			FROM 
				POS_BILLDETAIL PBD WITH(NOLOCK)    
				INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID    
				INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID    
				INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID    
				INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID    
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID    
				INNER JOIN #DealerIndentBranchDetails DBI ON DBI.ITEMID = I.ITEMID AND DBI.BRANCHID = BC.BRANCHID
			WHERE    
				I.CATEGORYID = @CategoryID    
				AND PB.CREATEDDATE >= @FromDate    
				AND PB.CREATEDDATE <= @ToDate    
				AND PB.BILLSTATUS = 1    
				AND PBD.DELETEDDATE IS NULL 
			GROUP BY 
				IC.ITEMID, BC.BRANCHID
		) ITEMSALE  
	ON DIBD.ITEMID = ITEMSALE.ITEMID AND ITEMSALE.BRANCHID = DIBD.BRANCHID

	UPDATE DIBD
	SET DIBD.INDENTDAYSSALEQUANTITY = ITEMSALE.SALEQUANTITY
	FROM
		#DealerIndentBranchDetails DIBD  
		INNER JOIN
		( 
			SELECT 
				IC.ITEMID, SUM(PBD.QUANTITY) AS SALEQUANTITY, BC.BRANCHID  
			FROM 
				POS_BILLDETAIL PBD WITH(NOLOCK)    
				INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID    
				INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID    
				INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID    
				INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID    
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID    
				INNER JOIN #DealerIndentBranchDetails DBI ON DBI.ITEMID = I.ITEMID AND DBI.BRANCHID = BC.BRANCHID
			WHERE    
				I.CATEGORYID = @CategoryID    
				AND PB.CREATEDDATE >= @IndentSaleFromDate    
				AND PB.CREATEDDATE <= @ToDate    
				AND PB.BILLSTATUS = 1    
				AND PBD.DELETEDDATE IS NULL 
			GROUP BY 
				IC.ITEMID, BC.BRANCHID
		) ITEMSALE  
	ON DIBD.ITEMID = ITEMSALE.ITEMID AND ITEMSALE.BRANCHID = DIBD.BRANCHID

	UPDATE DIBD
	SET DIBD.AVGSALEQUANTITY = (CASE WHEN DIBD.AVGSALEQUANTITY < 1 THEN  (DIBD.AVGSALEQUANTITY * @IndentDays) / @MultiplierDays ELSE DIBD.AVGSALEQUANTITY END) * @MultiplierDays
	FROM #DealerIndentBranchDetails DIBD  
  
	UPDATE DIBD 
	SET DIBD.BRANCHSTOCK = ALLBS.BRANCHSTOCK  
	FROM
		#DealerIndentBranchDetails DIBD  
		INNER JOIN
		(    
			SELECT IC.ITEMID, SSINNER.BRANCHID, SUM(SSINNER.QUANTITY) AS BRANCHSTOCK    
			FROM 
				STOCKSUMMARY SSINNER WITH(NOLOCK)    
				INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
				INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID    
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID    
			WHERE I.CATEGORYID = @CategoryID  
			GROUP BY IC.ITEMID, SSINNER.BRANCHID    
		) ALLBS ON DIBD.ITEMID = ALLBS.ITEMID AND ALLBS.BRANCHID = DIBD.BRANCHID  

	UPDATE DIBD 
	SET DIBD.BRANCHINDENTQUANTITY = 
		(CASE WHEN DIBD.AVGSALEQUANTITY > DIBD.INDENTDAYSSALEQUANTITY  THEN DIBD.AVGSALEQUANTITY ELSE DIBD.INDENTDAYSSALEQUANTITY END) 
			- (CASE WHEN DIBD.BRANCHSTOCK > 0 THEN DIBD.BRANCHSTOCK ELSE 0 END)		
	FROM #DealerIndentBranchDetails DIBD

	UPDATE DIBD 
	SET DIBD.BRANCHINDENTQUANTITY = CAST(CEILING(DIBD.BRANCHINDENTQUANTITY / 5.00) AS INT) * 5
	FROM #DealerIndentBranchDetails DIBD

	DELETE DIBD
	FROM #DealerIndentBranchDetails DIBD
	WHERE DIBD.BRANCHINDENTQUANTITY <= 0 

	INSERT INTO #DelearIndentItems
	SELECT 
		ROW_NUMBER() OVER(ORDER BY I.ITEMNAME ASC) AS SNO, I.ITEMID, I.SKUCODE, I.ITEMNAME, SC.SUBCATEGORYNAME, I.BranchQuantity
		, SUM(I.BRANCHINDENTQUANTITY) REQUIREDBRANCHSTOCK, 0.00 AS REQUIREDITEMINDENT, 0.00 AS DESIREDINDENT	
	FROM 
		#DealerIndentBranchDetails I
		LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID  
	GROUP BY 
		I.ITEMID, I.SKUCODE, I.ITEMNAME, SC.SUBCATEGORYNAME, I.BranchQuantity 
	HAVING SUM(I.BRANCHINDENTQUANTITY) > I.BranchQuantity OR I.BranchQuantity < 0

	UPDATE DIID
	SET DIID.REQUIREDITEMINDENT = DIID.REQUIREDBRANCHSTOCK - (CASE WHEN DIID.BranchQuantity > 0 THEN DIID.BranchQuantity ELSE 0 END)
	FROM #DelearIndentItems DIID
	WHERE DIID.REQUIREDBRANCHSTOCK - (CASE WHEN DIID.BranchQuantity > 0 THEN DIID.BranchQuantity ELSE 0 END) > 0

	UPDATE DIID
	SET DIID.REQUIREDITEMINDENT = 5
	FROM #DelearIndentItems DIID
	WHERE DIID.REQUIREDITEMINDENT > 0 AND DIID.REQUIREDITEMINDENT < 5

	UPDATE DIID
	SET DIID.REQUIREDITEMINDENT = CAST(CEILING(DIID.REQUIREDITEMINDENT / 5.00) AS INT) * 5
	FROM #DelearIndentItems DIID
	WHERE DIID.REQUIREDITEMINDENT > 0 

	DELETE DIID
	FROM #DelearIndentItems DIID
	WHERE DIID.REQUIREDITEMINDENT <= 0 

	UPDATE DIID
	SET DIID.DESIREDINDENT = DIID.REQUIREDITEMINDENT
	FROM #DelearIndentItems DIID

	SELECT
		DIID.SNO, DIID.ITEMID,  DIID.SKUCODE, I.VENDORSKUCODE, DIID.ITEMNAME, DIID.SUBCATEGORYNAME, IP.MRP, ICP.COSTPRICEWT, DIID.BranchQuantity
		, DIID.REQUIREDBRANCHSTOCK, DIID.REQUIREDITEMINDENT, DESIREDINDENT
	FROM 
		#DelearIndentItems DIID 
		LEFT JOIN 
			(
				SELECT ICINNER.ITEMID, MAX(SEDINNER.STOCKENTRYDETAILID) MAXSTOCKENTRYDETAILID
				FROM 
					STOCKENTRY SEINNER WITH(NOLOCK) 
					INNER JOIN STOCKENTRYDETAIL SEDINNER WITH(NOLOCK) ON SEDINNER.STOCKENTRYID = SEINNER.STOCKENTRYID
					INNER JOIN ITEMCOSTPRICE ICPINNER WITH(NOLOCK) ON ICPINNER.ITEMCOSTPRICEID = SEDINNER.ITEMCOSTPRICEID
					INNER JOIN ITEMPRICE IPINNER WITH(NOLOCK) ON IPINNER.ITEMPRICEID = ICPINNER.ITEMPRICEID
					INNER JOIN ITEMCODE ICINNER WITH(NOLOCK) ON ICINNER.ITEMCODEID = IPINNER.ITEMCODEID
				WHERE 
					SEINNER.SUPPLIERID = @DealerID
					AND SEDINNER.DELETEDDATE IS NULL
				GROUP BY ICINNER.ITEMID
			) SEDMAX ON SEDMAX.ITEMID = DIID.ITEMID
		LEFT JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.STOCKENTRYDETAILID = SEDMAX.MAXSTOCKENTRYDETAILID
		LEFT JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		LEFT JOIN ITEM I ON DIID.ITEMID = I.ITEMID
	ORDER BY ITEMNAME


	SELECT DIID.ITEMID, DIBD.BRANCHID, B.BRANCHNAME, DIBD.BRANCHSTOCK, DIBD.AVGSALEQUANTITY, DIBD.INDENTDAYSSALEQUANTITY, DIBD.BRANCHINDENTQUANTITY
	FROM 
		#DelearIndentItems DIID
		INNER JOIN #DealerIndentBranchDetails DIBD ON DIBD.ITEMID = DIID.ITEMID
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = DIBD.BRANCHID
   ORDER BY DIBD.ITEMID, B.BRANCHNAME
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DEALERINDENT_MBQ]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_R_DEALERINDENT_MBQ]    
@DealerID INT,    
@CategoryID INT
AS    
BEGIN    
  
	SELECT I.ITEMID, SED.STOCKENTRYDETAILID
	INTO #DATA
	FROM 
		ITEM I WITH(NOLOCK)
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMID = I.ITEMID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
	WHERE
		SE.SUPPLIERID = @DealerID
		AND I.CATEGORYID = @CategoryID
		AND I.DELETEDDATE IS NULL
		AND IC.DELETEDDATE IS NULL
		AND ICP.DELETEDDATE IS NULL
		AND SED.DELETEDDATE IS NULL
		AND SE.DELETEDDATE IS NULL
		AND I.ISDSD = 0
	
	SELECT FULLDATA.ITEMID, MAX(FULLDATA.STOCKENTRYDETAILID) STOCKENTRYDETAILID -- pick recent entry
		, 0 AS ITEMCOSTPRICEID, SSTOTAL.QTYORWGHTINKGS, IL.THRESHOLD, IL.DESIREDQUANTITY MBQDESIREDQUANTITY
		, IL.DESIREDQUANTITY - SSTOTAL.QTYORWGHTINKGS AS DESIREDQUANTITY
	INTO #ITEMDATA
	FROM 
		#DATA FULLDATA
		INNER JOIN 
			(
				SELECT I.ITEMID, SUM(CASE WHEN I.ISOPENITEM <> 1 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END) QTYORWGHTINKGS
				FROM 
					STOCKSUMMARY SS WITH(NOLOCK)
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				WHERE 
					IP.DELETEDDATE IS NULL
					AND IC.DELETEDDATE IS NULL
					AND I.DELETEDDATE IS NULL
					AND SS.BRANCHID = 45
				GROUP BY I.ITEMID
			) SSTOTAL ON SSTOTAL.ITEMID = FULLDATA.ITEMID
		INNER JOIN INDENTLIMIT IL ON IL.ITEMID = FULLDATA.ITEMID AND IL.BRANCHID = 45
	WHERE SSTOTAL.QTYORWGHTINKGS < IL.THRESHOLD
	GROUP BY FULLDATA.ITEMID, SSTOTAL.QTYORWGHTINKGS, IL.THRESHOLD, IL.DESIREDQUANTITY

	UPDATE ITEMDATA
	SET ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID, DESIREDQUANTITY = ROUND(DESIREDQUANTITY / 5, 0) * 5
	FROM
		#ITEMDATA ITEMDATA
		INNER JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.STOCKENTRYDETAILID = ITEMDATA.STOCKENTRYDETAILID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID

	SELECT 
		NULL AS SUPPLIERINDENTDETAILID, I.ITEMID, I.SKUCODE, I.ITEMNAME, I.VENDORSKUCODE, SUBCAT.SUBCATEGORYNAME, IP.MRP RecentMRP
		, ICP.COSTPRICEWT RecentCostPriceWT, ITEMDATA.QTYORWGHTINKGS BranchQuantity
		, ITEMDATA.THRESHOLD Threshold, ITEMDATA.MBQDESIREDQUANTITY MBQDesiredQuantity
		, ITEMDATA.DESIREDQUANTITY CalculatedIndent, ITEMDATA.DESIREDQUANTITY DesiredIndent
	FROM 
		#ITEMDATA ITEMDATA
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = ITEMDATA.ITEMID
		INNER JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = ITEMDATA.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DISPATCH]      
@STOCKDISPATCHID INT,
@ISDRAFT bit = 0
AS      
BEGIN      
      
SELECT 
	SD.STOCKDISPATCHID,SD.FROMBRANCHID,SD.TOBRANCHID,          
	SD.CATEGORYID,C.CATEGORYNAME,FB.BRANCHNAME AS FROMBRANCHNAME,          
	FB.BRANCHCODE,TB.BRANCHNAME AS TOBRANCHNAME,        
	CU.FULLNAME AS CREATEDBY,SD.CREATEDDATE,          
	UU.FULLNAME AS UPDATEDBY,SD.UPDATEDATE,    
	SD.DISPATCHNUMBER, SD.NOTES 
FROM STOCKDISPATCH SD          
	LEFT JOIN BRANCH FB ON SD.FROMBRANCHID = FB.BRANCHID          
	LEFT JOIN BRANCH TB ON SD.TOBRANCHID = TB.BRANCHID          
	LEFT JOIN TBLUSER CU ON SD.CREATEDBY = CU.USERID          
	LEFT JOIN TBLUSER UU ON SD.UPDATEDBY = UU.USERID          
	LEFT JOIN TBLCATEGORY C ON SD.CATEGORYID = C.CATEGORYID          
WHERE STOCKDISPATCHID = @STOCKDISPATCHID          
	AND (@ISDRAFT = 1 OR (ISNULL(SD.STATUS,0) = 1 OR ISNULL(SD.STATUS,0) = 2))
    
      
SELECT           
	DS.STOCKDISPATCHID, DS.STOCKDISPATCHDETAILID,I.ITEMID,IC.ITEMCODEID,IP.ITEMPRICEID,          
	I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,IP.MRP,IP.SALEPRICE,DS.DISPATCHQUANTITY,          
	DS.WEIGHTINKGS,DS.TRAYNUMBER, ISNULL(I.ISOPENITEM,0) AS ISOPENITEM,
	DS.RECEIVEDQUANTITY, DS.DISPATCHQUANTITY - DS.RECEIVEDQUANTITY AS DIFF, DS.TRAYINFOID
FROM  STOCKDISPATCHDETAIL DS             
	INNER JOIN ITEMPRICE IP ON DS.ITEMPRICEID = IP.ITEMPRICEID            
	INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID            
	INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID          
WHERE STOCKDISPATCHID = @STOCKDISPATCHID            
	AND (DS.DELETEDDATE IS NULL OR DS.Reverted_Date IS NOT NULL)
ORDER BY DS.STOCKDISPATCHDETAILID

SELECT           
	DS.TRAYNUMBER, COUNT(1) AS TRAYCOUNT
FROM  
	STOCKDISPATCHDETAIL DS             
	INNER JOIN ITEMPRICE IP ON DS.ITEMPRICEID = IP.ITEMPRICEID            
	INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID            
	INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID          
WHERE 
	STOCKDISPATCHID = @STOCKDISPATCHID            
	AND DS.DELETEDDATE IS NULL
GROUP BY DS.TRAYNUMBER
      
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DISPATCH_TRAYDATA]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create     PROC [dbo].[USP_R_DISPATCH_TRAYDATA]
(
	@BranchID INT,
	@CategoryID INT
)
AS
BEGIN

	SELECT 1 AS PARENTID

	SELECT PLT.PICKLISTTRAYID, PLT.TRAYNUMBER, PLT.ISTRAYVERIFIED, 0 AS ITEMCOUNT, 0 AS PIECECOUNT
	INTO #PICKLISTTRAY
	FROM
		PICKLISTTRAY PLT
	WHERE
		PLT.BRANCHID = @BranchID
		AND PLT.CATEGORYID = @CategoryID
		AND PLT.DELETEDDATE IS NULL
		AND PLT.ISDISPATCHED = 0

	UPDATE PLTMAIN
	SET ITEMCOUNT = PLTCOUNT.ITEMCOUNT
	FROM
		#PICKLISTTRAY PLTMAIN
		INNER JOIN 
			(
				SELECT PLT.PICKLISTTRAYID, COUNT(DISTINCT PLI.ITEMCODEID) ITEMCOUNT
				FROM 
					#PICKLISTTRAY PLT
					INNER JOIN PICKLISTITEMDETAIL PLID ON PLID.PICKLISTTRAYID = PLT.PICKLISTTRAYID
					INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTITEMID = PLID.PICKLISTITEMID
				WHERE
					PLI.DELETEDDATE IS NULL
					AND PLID.DELETEDDATE IS NULL
				GROUP BY PLT.PICKLISTTRAYID
			) PLTCOUNT ON PLTCOUNT.PICKLISTTRAYID = PLTMAIN.PICKLISTTRAYID

	UPDATE PLTMAIN
	SET ITEMCOUNT = PLTCOUNT.ITEMCOUNT
	FROM
		#PICKLISTTRAY PLTMAIN
		INNER JOIN 
			(
				SELECT PLT.PICKLISTTRAYID, COUNT(DISTINCT PLI.ITEMCODEID) ITEMCOUNT
				FROM 
					#PICKLISTTRAY PLT
					INNER JOIN PICKLISTITEMDETAIL PLID ON PLID.PICKLISTTRAYID = PLT.PICKLISTTRAYID
					INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTITEMID = PLID.PICKLISTITEMID
				WHERE
					PLI.DELETEDDATE IS NULL
					AND PLID.DELETEDDATE IS NULL
				GROUP BY PLT.PICKLISTTRAYID
			) PLTCOUNT ON PLTCOUNT.PICKLISTTRAYID = PLTMAIN.PICKLISTTRAYID

	UPDATE PLTMAIN
	SET PIECECOUNT = PLTCOUNT.PIECESCOUNT
	FROM
		#PICKLISTTRAY PLTMAIN
		INNER JOIN 
			(
				SELECT PLT.PICKLISTTRAYID, SUM(PLID.QUANTITY) PIECESCOUNT
				FROM 
					#PICKLISTTRAY PLT
					INNER JOIN PICKLISTITEMDETAIL PLID ON PLID.PICKLISTTRAYID = PLT.PICKLISTTRAYID
				WHERE PLID.DELETEDDATE IS NULL
				GROUP BY PLT.PICKLISTTRAYID
			) PLTCOUNT ON PLTCOUNT.PICKLISTTRAYID = PLTMAIN.PICKLISTTRAYID

	SELECT 1 AS PARENTID, * FROM #PICKLISTTRAY

	SELECT PLT.PICKLISTTRAYID, I.ITEMNAME, IC.ITEMCODE, PLI.MRP
		, CAST(PLID.QUANTITY AS INT) QUANTITY, PLID.PICKLISTITEMDETAILID
	FROM
		PICKLISTTRAY PLT
		INNER JOIN PICKLISTITEMDETAIL PLID ON PLID.PICKLISTTRAYID = PLT.PICKLISTTRAYID
		INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTITEMID = PLID.PICKLISTITEMID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PLI.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE
		PLT.BRANCHID = @BranchID
		AND PLT.CATEGORYID = @CategoryID
		AND PLT.DELETEDDATE IS NULL
		AND PLT.ISDISPATCHED = 0
		AND PLI.DELETEDDATE IS NULL
		AND PLID.DELETEDDATE IS NULL
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DISPATCHDCLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DISPATCHDCLIST]      
@BranchID VARCHAR(500),
@CategoryID INT = 13,
@FromDate date = null,  
@ToDate date = null  
AS      
BEGIN      
    
SELECT       
	DD.DISPATCHDCID,DD.DISPATCHDCNUMBER,      
	B.BRANCHCODE,    
	B.BRANCHNAME,C.CATEGORYNAME,      
	DD.BRANCHID,DD.CATEGORYID,      
	U.FULLNAME AS CREATEDBY,DD.CREATEDDATE      
FROM DISPATCHDC DD      
	INNER JOIN BRANCH B ON DD.BRANCHID = B.BRANCHID      
	INNER JOIN TBLCATEGORY C ON DD.CATEGORYID = C.CATEGORYID      
	INNER JOIN TBLUSER U ON DD.CREATEDBY = U.USERID      
	INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON DD.BRANCHID = BIDS.ITEM
WHERE (DD.CATEGORYID = @CategoryID OR @CategoryID = 13)
	AND DD.CREATEDDATE >= @FromDate   
	AND DD.CREATEDDATE <= DATEADD(day,1,@ToDate)
  ORDER BY DISPATCHDCID DESC
    
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DISPATCHDRAFT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DISPATCHDRAFT]              
@USERID INT,          
@CATEGORYID INT  = null  
AS              
BEGIN              
              
DECLARE @STOCKDISPATCHID INT        
SELECT @STOCKDISPATCHID = ISNULL(STOCKDISPATCHID,0)        
FROM STOCKDISPATCH               
WHERE CREATEDBY = @USERID 
AND ISNULL(STATUS,0)  = 0              
AND DELETEDDATE IS NULL
              
IF @STOCKDISPATCHID > 0              
BEGIN              
              
exec USP_R_DISPATCH @STOCKDISPATCHID , 1
        
END              
ELSE            
SELECT 'DISPATCH DOES NOT EXISTS'  AS 'Message'
            
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DISPATCHDRAFT_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DISPATCHDRAFT_v2]
@USERID INT,
@IsManualDispatch BIT
AS              
BEGIN              
              
	DECLARE @STOCKDISPATCHID INT = 0, @BRANCHINDENTID INT = 0
	IF(@IsManualDispatch = 1)
		BEGIN
		SELECT 
			@STOCKDISPATCHID = ISNULL(STOCKDISPATCHID,0),
			@BRANCHINDENTID = ISNULL(BRANCHINDENTID,0)
		FROM STOCKDISPATCH               
		WHERE CREATEDBY = @USERID 
			AND ISNULL(BRANCHINDENTID,0) = 0
			AND ISNULL(STATUS,0)  = 0              
			AND DELETEDDATE IS NULL
		END
	ELSE
		BEGIN
			SELECT 
				@STOCKDISPATCHID = ISNULL(STOCKDISPATCHID,0),
				@BRANCHINDENTID = ISNULL(BRANCHINDENTID,0)
			FROM STOCKDISPATCH               
			WHERE CREATEDBY = @USERID 
				AND ISNULL(BRANCHINDENTID,0) > 0
				AND ISNULL(STATUS,0)  = 0              
				AND DELETEDDATE IS NULL	
		END
              
	IF @STOCKDISPATCHID > 0
	BEGIN          
	
		DECLARE @FromBranchID INT

		SELECT @FromBranchID = SD.FROMBRANCHID
		FROM STOCKDISPATCH SD  
		WHERE STOCKDISPATCHID = @STOCKDISPATCHID
	
		SELECT 
			SD.STOCKDISPATCHID,
			SD.FROMBRANCHID,
			SD.TOBRANCHID,          
			SD.CATEGORYID,C.CATEGORYNAME,FB.BRANCHNAME AS FROMBRANCHNAME,
			FB.BRANCHCODE,TB.BRANCHNAME AS TOBRANCHNAME,
			CU.FULLNAME AS CREATEDBY,SD.CREATEDDATE,
			UU.FULLNAME AS UPDATEDBY,SD.UPDATEDATE,    
			SD.DISPATCHNUMBER, ISNULL(SD.SUBCATEGORYID,0) AS SUBCATEGORYID, 
			ISNULL(SCAT.SUBCATEGORYNAME,'') AS SUBCATEGORYNAME, ISNULL(BI.BRANCHINDENTID,0) AS BRANCHINDENTID,
			ISNULL(BI.NOOFDAYS, 0) AS NOOFDAYS
		FROM STOCKDISPATCH SD          
			LEFT JOIN BRANCH FB ON SD.FROMBRANCHID = FB.BRANCHID          
			LEFT JOIN BRANCH TB ON SD.TOBRANCHID = TB.BRANCHID          
			LEFT JOIN TBLUSER CU ON SD.CREATEDBY = CU.USERID          
			LEFT JOIN TBLUSER UU ON SD.UPDATEDBY = UU.USERID          
			LEFT JOIN TBLCATEGORY C ON SD.CATEGORYID = C.CATEGORYID
			LEFT JOIN SUBCATEGORY SCAT ON SD.SUBCATEGORYID = SCAT.SUBCATEGORYID
			LEFT JOIN BRANCHINDENT BI ON SD.BRANCHINDENTID = BI.BRANCHINDENTID
		WHERE STOCKDISPATCHID = @STOCKDISPATCHID

		SELECT           
			DS.STOCKDISPATCHID, DS.STOCKDISPATCHDETAILID,I.ITEMID,IC.ITEMCODEID,IP.ITEMPRICEID,          
			I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,IP.MRP,IP.SALEPRICE,DS.DISPATCHQUANTITY,          
			DS.WEIGHTINKGS,DS.TRAYNUMBER, ISNULL(I.ISOPENITEM,0) AS ISOPENITEM, 
			ISNULL(DS.BRANCHINDENTDETAILID,0) AS BRANCHINDENTDETAILID, 
			SCAT.SUBCATEGORYID, SCAT.SUBCATEGORYNAME, DS.TRAYINFOID, DS.ISTRAYVERIFIED
		INTO #SDD
		FROM  STOCKDISPATCHDETAIL DS             
			INNER JOIN ITEMPRICE IP ON DS.ITEMPRICEID = IP.ITEMPRICEID            
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID            
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
			LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
			
		WHERE STOCKDISPATCHID = @STOCKDISPATCHID            
			AND DS.DELETEDDATE IS NULL
		ORDER BY DS.STOCKDISPATCHDETAILID

		SELECT
			BID.BRANCHINDENTID
			,BID.BRANCHINDENTDETAILID
			,BID.ITEMID
			,I.SKUCODE
			,I.ITEMNAME
			,I.ISOPENITEM
			,BID.INDENTQUANTITY
			,ISNULL(SDD.DISPATCHQUANTITY, 0) AS DISPATCHQUANTITY
			,SDD.WEIGHTINKGS
			, SS.WHSTOCK
			, BID.LASTDISPATCHEDDATE
		FROM BRANCHINDENTDETAIL BID
			LEFT JOIN 
			(
				SELECT 
					BRANCHINDENTDETAILID, 
					SUM(DISPATCHQUANTITY) AS DISPATCHQUANTITY, 
					SUM(WEIGHTINKGS) AS WEIGHTINKGS 
				FROM #SDD
				GROUP BY BRANCHINDENTDETAILID
			) AS SDD ON BID.BRANCHINDENTDETAILID = SDD.BRANCHINDENTDETAILID
			INNER JOIN ITEM I ON I.ITEMID = BID.ITEMID
			INNER JOIN 
				(
					SELECT IINNER.ITEMID
						, CAST(SUM(CASE WHEN IINNER.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) AS DECIMAL(18, 2)) WHSTOCK
					FROM
						STOCKSUMMARY SSINNER WITH(NOLOCK)
						INNER JOIN ITEMPRICE IPINNER ON IPINNER.ITEMPRICEID = SSINNER.ITEMPRICEID
						INNER JOIN ITEMCODE ICINNER ON ICINNER.ITEMCODEID = IPINNER.ITEMCODEID
						INNER JOIN ITEM IINNER ON IINNER.ITEMID = ICINNER.ITEMID
					WHERE SSINNER.BRANCHID = @FromBranchID 
					GROUP BY IINNER.ITEMID
				) SS ON SS.ITEMID = I.ITEMID
		WHERE BRANCHINDENTID = @BRANCHINDENTID
		ORDER BY I.MANUFACTURERID, I.ITEMNAME

		SELECT SDD.* FROM #SDD SDD WHERE BRANCHINDENTDETAILID <> 0
		SELECT SDD.* FROM #SDD SDD WHERE BRANCHINDENTDETAILID = 0

		DECLARE @BRANCHID INT, @CATEGORYID INT
		SELECT @BRANCHID = TOBRANCHID, @CATEGORYID = CATEGORYID FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

		SELECT 
			@STOCKDISPATCHID AS STOCKDISPATCHID, TI.TRAYINFOID, TI.TRAYNUMBER
		FROM TRAYINFO TI
				INNER JOIN STOCKDISPATCH SD ON TI.STOCKDISPATCHID = SD.STOCKDISPATCHID
			WHERE SD.TOBRANCHID = @BRANCHID 
				AND SD.CATEGORYID = @CATEGORYID
				AND SD.STATUS <> 2
				AND SD.DELETEDDATE IS NULL
				AND TI.DELETEDDATE IS NULL
        
	END              
	ELSE            
	SELECT 'DISPATCH DOES NOT EXISTS'  AS 'Message'
            
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DISPATCHITEMSBYTRAY]    Script Date: 17-10-2026 13:04:47 ******/
