CREATE PROCEDURE [dbo].[USP_R_DISPATCHITEMSBYTRAY]
@TRAYINFOID INT
AS
BEGIN

	SELECT 
		I.SKUCODE, IC.ITEMCODE, I.ITEMNAME, IP.MRP, SDD.DISPATCHQUANTITY, SDD.RECEIVEDQUANTITY, SDD.WEIGHTINKGS, SD.STOCKDISPATCHID, SD.DISPATCHNUMBER
	FROM STOCKDISPATCHDETAIL SDD
		INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE SDD.TRAYINFOID = @TRAYINFOID
		AND SDD.DELETEDDATE IS NULL
		AND SD.DELETEDDATE IS NULL

END
