/****** Object:  StoredProcedure [dbo].[USP_R_DISPATCHLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_DISPATCHLIST]            
@CategoryID int = 13,
@BranchID VARCHAR(500),
@FromDate date = NULL,    
@ToDate date = NULL    
AS            
BEGIN      

	SELECT @ToDate = DATEADD(day, 1, @ToDate)
            
	SELECT             
		SD.STOCKDISPATCHID,         
		SD.DISPATCHNUMBER,            
		B.BRANCHCODE,      
		B.BRANCHNAME,      
		C.CATEGORYNAME,        
		CU.FULLNAME AS CREATEDBY,            
		SD.CREATEDDATE  ,      
		CASE WHEN SD.Reverted_Date IS NOT NULL THEN 'Reverted'
			WHEN SD.STATUS = 0 THEN 'Draft'       
			when SD.STATUS = 1 THEN 'In-Transit'      
			ELSE 'Accepted' end as STATUS,
		ISNULL(SD.BRANCHINDENTID,0) AS INDENTNUMBER,
		CASE WHEN ISNULL(SD.AUTOGENERATED,0) = 1 THEN 'YES' ELSE 'NO' END AS [Auto Generated],
		CASE WHEN SD.SOURCEENTITYID = 1 THEN SDINNER.DISPATCHNUMBER ELSE SEINNER.SUPPLIERINVOICENO END AS [Ref #],
		SD.Notes
	FROM STOCKDISPATCH SD      
		INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON SD.TOBRANCHID = BIDS.ITEM
		LEFT JOIN BRANCH B ON SD.TOBRANCHID = B.BRANCHID            
		LEFT JOIN TBLCATEGORY C ON SD.CATEGORYID = C.CATEGORYID            
		LEFT JOIN TBLUSER CU ON SD.CREATEDBY = CU.USERID
		LEFT JOIN STOCKDISPATCH SDINNER ON SD.REFID = SDINNER.STOCKDISPATCHID
		LEFT JOIN STOCKENTRY SEINNER ON SD.REFID = SEINNER.STOCKENTRYID
	where (SD.CATEGORYID = @CategoryID OR @CategoryID = 13)
		AND	SD.CREATEDDATE >= @FromDate     
		AND SD.CREATEDDATE <= @ToDate
		AND (
			SD.DELETEDDATE IS NULL 
			OR 
				(SD.Reverted_Date IS NOT NULL
				AND SD.Reverted_Date >= @FromDate
				AND SD.Reverted_Date <= @ToDate)
			)
	ORDER BY STOCKDISPATCHID DESC
            
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_DRAFTSTOCKENTRIES]    Script Date: 17-10-2026 13:04:47 ******/
