CREATE PROC [dbo].[USP_R_DRAFTSTOCKENTRIES]
(
	@UserID INT
)
AS 
BEGIN

	SELECT SE.STOCKENTRYID, SE.STOCKENTRYNUMBER, DLR.DEALERNAME, SE.SUPPLIERINVOICENO, SE.INVOICEDATE
	FROM 
		STOCKENTRY SE
		INNER JOIN TBLDEALER DLR ON DLR.DEALERID = SE.SUPPLIERID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = SE.CATEGORYID
	WHERE SE.CREATEDBY = @UserID AND SE.DELETEDDATE IS NULL AND ISNULL(SE.STATUS,0) = 0

END
