/****** Object:  StoredProcedure [dbo].[USP_R_EXPORTITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_EXPORTITEMS]
@EXPORTTYPE VARCHAR(10)
AS
BEGIN

	IF(@EXPORTTYPE = 'ITEM')
	BEGIN
		SELECT 
		  I.ITEMID
		, I.CATEGORYID
		, I.SUBCATEGORYID
		, I.PARENTITEMID
		, I.UOMID
		, I.ClassificationID
		, I.SKUCODE
		, I.ITEMNAME
		, I.ISOPENITEM
		, GSTD.GSTCODE
		, C.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, PITEM.SKUCODE AS PARENTSKU
		, UOM.DISPLAYVALUE AS UOM
		, CLS.ClassificationName
		, SUBCLS.SUBCLASSIFICATIONNAME
		FROM ITEM I
			INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
			LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
			LEFT JOIN ITEM PITEM ON I.PARENTITEMID = PITEM.ITEMID
			LEFT JOIN UOM UOM ON I.UOMID = UOM.UOMID
			LEFT JOIN ITEMCLASSIFICATION CLS ON I.ClassificationID = CLS.ClassificationID
			LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
			LEFT JOIN GSTDETAIL GSTD ON I.GSTID = GSTD.GSTID
		WHERE I.DELETEDDATE IS NULL
			AND EXISTS
				(
					SELECT 1 
					FROM ITEMCODE IC 
					WHERE IC.ITEMID = I.ITEMID AND IC.DELETEDDATE IS NULL
				)
	END

	IF(@EXPORTTYPE = 'ITEMCODE')
	BEGIN
		SELECT 
		 I.ITEMID
		, IC.ITEMCODEID
		, I.CATEGORYID
		, I.SUBCATEGORYID
		, I.PARENTITEMID
		, I.UOMID
		, I.ClassificationID
		, I.SKUCODE
		, I.ITEMNAME
		, IC.ITEMCODE
		, IC.ISEAN
		, IC.HSNCODE
		, I.ISOPENITEM
		, C.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, PITEM.SKUCODE AS PARENTSKU
		, UOM.DISPLAYVALUE AS UOM
		, CLS.ClassificationName
		, SUBCLS.SUBCLASSIFICATIONNAME
		FROM ITEM I
			INNER JOIN ITEMCODE IC ON I.ITEMID = IC.ITEMID
			INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
			LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
			LEFT JOIN ITEM PITEM ON I.PARENTITEMID = PITEM.ITEMID
			LEFT JOIN UOM UOM ON I.UOMID = UOM.UOMID
			LEFT JOIN ITEMCLASSIFICATION CLS ON I.ClassificationID = CLS.ClassificationID
			LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		WHERE IC.DELETEDDATE IS NULL
	END

	IF(@EXPORTTYPE = 'ITEMPRICE')
	BEGIN
		SELECT 
		  I.ITEMID
		, IC.ITEMCODEID
		, IP.ITEMPRICEID
		, I.CATEGORYID
		, I.SUBCATEGORYID
		, I.PARENTITEMID
		, I.UOMID
		, I.ClassificationID
		, I.SKUCODE
		, I.ITEMNAME
		, IC.ITEMCODE
		, IC.ISEAN
		, IC.HSNCODE
		, IP.MRP
		, IP.SALEPRICE
		, GST.GSTCODE
		, I.ISOPENITEM
		, C.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, PITEM.SKUCODE AS PARENTSKU
		, UOM.DISPLAYVALUE AS UOM
		, CLS.ClassificationName
		, SUBCLS.SUBCLASSIFICATIONNAME
		FROM ITEM I
			INNER JOIN ITEMCODE IC ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEMPRICE IP ON IC.ITEMCODEID = IP.ITEMCODEID
			LEFT JOIN GSTDETAIL GST ON IP.GSTID = GST.GSTID
			INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
			LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
			LEFT JOIN ITEM PITEM ON I.PARENTITEMID = PITEM.ITEMID
			LEFT JOIN UOM UOM ON I.UOMID = UOM.UOMID
			LEFT JOIN ITEMCLASSIFICATION CLS ON I.ClassificationID = CLS.ClassificationID
			LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		WHERE IP.DELETEDDATE IS NULL
	END

	IF(@EXPORTTYPE = 'ITEMCOSTPRICE')
	BEGIN
		SELECT 
		  I.ITEMID
		, IC.ITEMCODEID
		, IP.ITEMPRICEID
		, ICP.ITEMCOSTPRICEID
		, I.CATEGORYID
		, I.SUBCATEGORYID
		, I.PARENTITEMID
		, I.UOMID
		, I.ClassificationID
		, I.SKUCODE
		, I.ITEMNAME
		, IC.ITEMCODE
		, IC.ISEAN
		, IC.HSNCODE
		, IP.MRP
		, IP.SALEPRICE
		, ICP.COSTPRICEWT
		, ICP.COSTPRICEWOT
		, GST.GSTCODE
		, I.ISOPENITEM
		, C.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, PITEM.SKUCODE AS PARENTSKU
		, UOM.DISPLAYVALUE AS UOM
		, CLS.ClassificationName
		, SUBCLS.SUBCLASSIFICATIONNAME
		FROM ITEM I
			INNER JOIN ITEMCODE IC ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEMPRICE IP ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
			LEFT JOIN GSTDETAIL GST ON IP.GSTID = GST.GSTID
			INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
			LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
			LEFT JOIN ITEM PITEM ON I.PARENTITEMID = PITEM.ITEMID
			LEFT JOIN UOM UOM ON I.UOMID = UOM.UOMID
			LEFT JOIN ITEMCLASSIFICATION CLS ON I.ClassificationID = CLS.ClassificationID
			LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		WHERE ICP.DELETEDDATE IS NULL
	END

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_GETOFFERS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
