CREATE PROCEDURE [dbo].[USP_R_GETOFFERS]
@ITEMPRICEID INT  
AS  
BEGIN  
  
	SELECT IOFR.OFFERID,OFR.OFFERNAME,OFR.OFFERCODE,  
	ISNULL(OFR.STARTDATE, BO.STARTDATE) AS STARTDATE,
	ISNULL(OFR.ENDDATE, BO.ENDDATE) AS ENDDATE,
	OFR.OFFERVALUE,OT.OFFERTYPENAME AS OFFERTYPE
	FROM DBO.UDF_GETOFFERS(@ITEMPRICEID) IOFR  
	LEFT JOIN OFFER OFR ON IOFR.OFFERID = OFR.OFFERID  
	LEFT JOIN OFFERTYPE OT ON OFR.OFFERTYPEID = OT.OFFERTYPEID  
	LEFT JOIN BASEOFFER BO ON OFR.BASEOFFERID = BO.BASEOFFERID
	WHERE IOFR.OFFERID IS NOT NULL
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_GETOFFERS_BYITEM]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_R_GETOFFERS_BYITEM]
@ITEMID INT
AS
BEGIN
    SET NOCOUNT ON;

    ;WITH ItemPrices AS
    (
        SELECT
            I.ITEMID,
            I.ITEMNAME,
            IC.ITEMCODEID,
            IC.ITEMCODE,
            IC.HSNCODE,
            IP.ITEMPRICEID,
            IP.MRP,
            IP.SALEPRICE
        FROM ITEM I
            INNER JOIN ITEMCODE IC ON IC.ITEMID = I.ITEMID
            INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
        WHERE I.ITEMID = @ITEMID
            AND IC.DELETEDDATE IS NULL
            AND IP.DELETEDDATE IS NULL
    )
    SELECT DISTINCT
        IP.ITEMID,
        IP.ITEMNAME,
        IP.ITEMCODEID,
        IP.ITEMCODE,
        IP.HSNCODE,
        IP.ITEMPRICEID,
        IP.MRP,
        IP.SALEPRICE,
        'Offer' AS OFFERKIND,
        OFR.OFFERID,
        OFR.OFFERNAME,
        OFR.OFFERCODE,
        ISNULL(OFR.STARTDATE, BO.STARTDATE) AS STARTDATE,
        ISNULL(OFR.ENDDATE, BO.ENDDATE) AS ENDDATE,
        OFR.OFFERVALUE,
        OT.OFFERTYPENAME AS OFFERTYPE,
        OFR.BASEOFFERID,
        BO.OFFERNAME AS BASEOFFERNAME,
        BO.OFFERCODE AS BASEOFFERCODE,
        BO.STARTDATE AS BASESTARTDATE,
        BO.ENDDATE AS BASEENDDATE,
        OIM.NUMBEROFPIECES,
        CASE
            WHEN LOWER(ISNULL(JSON_VALUE(OIM.OFFERITEMCONFIG, '$.IsFreeItem'), '0')) IN ('1', 'true') THEN 'Free Item'
            WHEN OIM.OFFERITEMMAPID IS NOT NULL THEN 'Buying Item'
            ELSE NULL
        END AS OFFERITEMTYPE,
        CASE JSON_VALUE(OIM.OFFERITEMCONFIG, '$.PriceBasedOn')
            WHEN 'MRP' THEN 'MRP'
            WHEN 'SP' THEN 'Sale Price'
            WHEN 'OP' THEN 'Offer Price'
            ELSE NULL
        END AS PRICEBASEDONTEXT,
        JSON_VALUE(OIM.OFFERITEMCONFIG, '$.PriceBasedOn') AS PRICEBASEDON,
        TRY_CONVERT(decimal(18, 2), JSON_VALUE(OIM.OFFERITEMCONFIG, '$.OfferPrice')) AS OFFERPRICE
    FROM ItemPrices IP
        CROSS APPLY DBO.UDF_GETOFFERS(IP.ITEMPRICEID) IOFR
        INNER JOIN OFFER OFR ON IOFR.OFFERID = OFR.OFFERID
        LEFT JOIN OFFERTYPE OT ON OFR.OFFERTYPEID = OT.OFFERTYPEID
        LEFT JOIN BASEOFFER BO ON OFR.BASEOFFERID = BO.BASEOFFERID
        OUTER APPLY
        (
            SELECT TOP 1 OFRIM.*
            FROM OFFERITEMMAP OFRIM
            WHERE OFRIM.OFFERID = OFR.OFFERID
                AND OFRIM.DELETEDDATE IS NULL
                AND
                (
                    OFRIM.ITEMCODEID = IP.ITEMCODEID
                    OR TRY_CONVERT(int, JSON_VALUE(OFRIM.OFFERITEMCONFIG, '$.ItemPriceID')) = IP.ITEMPRICEID
                )
            ORDER BY OFRIM.OFFERITEMMAPID
        ) OIM
    WHERE IOFR.OFFERID IS NOT NULL
    ORDER BY IP.ITEMCODE, IP.MRP, OFR.OFFERID;
END
GO
