CREATE PROCEDURE [dbo].[USP_R_GST]
AS          
BEGIN          
    
SELECT           
G.GSTID,G.GSTCODE,G.CGST,G.SGST,G.IGST,G.CESS
,C.FULLNAME AS CREATEDBY,G.CREATEDDATE,U.FULLNAME AS UPDATEDBY,G.UPDATEDATE    
FROM GSTDETAIL G
LEFT JOIN TBLUSER C ON G.CREATEDBY = C.USERID    
LEFT JOIN TBLUSER U ON G.UPDATEDBY = U.USERID    
WHERE G.DELETEDDATE IS NULL          
ORDER BY LEN(G.GSTCODE), G.GSTCODE
       
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_GSTLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[USP_R_GSTLIST]
AS          
BEGIN          
    
SELECT           
	G.GSTID, G.GSTCODE, G.CGST, G.SGST, G.IGST, G.CESS, CAST(ROUND((G.CGST + G.SGST + G.CESS) / 100, 3) AS DECIMAL(4, 3)) GSTVALUE
FROM GSTDETAIL G
WHERE G.DELETEDDATE IS NULL          
ORDER BY LEN(G.GSTCODE), G.GSTCODE
       
END
GO
