	SELECT 1 AS PARENTID
    
	SELECT 1 AS PARENTID, G.GSTID, G.GSTCODE
	FROM GSTDETAIL G
	WHERE G.DELETEDDATE IS NULL          
	ORDER BY LEN(G.GSTCODE), G.GSTCODE
       
END
