/****** Object:  StoredProcedure [dbo].[USP_R_HASACCESS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_R_HASACCESS]
(
	@RoleID INT = 0
	, @UserID INT = 0
)
AS
BEGIN


	-- WORKFLOW TABLE GENERATION -- work flow to display
	SELECT WF.WORKFLOWID, WF.WORKFLOWTEXT, WF.PARENTWORKFLOWID, WF.[UNIQUEIDENTIFIER] 
		, CAST(CASE WHEN WFAVIEW.WORKFLOWID > 0 THEN 0 ELSE NULL END AS BIT) 'View', WFAVIEW.WORKFLOWACTIONID 'ViewActionID'
		, CAST(CASE WHEN WFACREATE.WORKFLOWID > 0 THEN 0 ELSE NULL END AS BIT) 'Create', WFACREATE.WORKFLOWACTIONID 'CreateActionID'
		, CAST(CASE WHEN WFAUPDATE.WORKFLOWID > 0 THEN 0 ELSE NULL END AS BIT) 'Update', WFAUPDATE.WORKFLOWACTIONID 'UpdateActionID'
		, CAST(CASE WHEN WFADELETE.WORKFLOWID > 0 THEN 0 ELSE NULL END AS BIT) 'Delete', WFADELETE.WORKFLOWACTIONID 'DeleteActionID'
		, CAST(CASE WHEN WFAEXECUTE.WORKFLOWID > 0 THEN 0 ELSE NULL END AS BIT) 'Execute', WFAEXECUTE.WORKFLOWACTIONID 'ExecuteActionID'
	FROM
		WORKFLOW WF
		LEFT JOIN 
			(
				SELECT WFAVIEW.*
				FROM 
					WORKFLOWACTION WFAVIEW 
					INNER JOIN ACTIONTYPE ATYPVIEW ON ATYPVIEW.ACTIONTYPEID = WFAVIEW.ACTIONTYPEID AND ATYPVIEW.ACTIONTYPETEXT = 'View'
			) WFAVIEW ON WFAVIEW.WORKFLOWID = WF.WORKFLOWID
		LEFT JOIN 
			(
				SELECT WFACREATE.*
				FROM 
					WORKFLOWACTION WFACREATE 
					INNER JOIN ACTIONTYPE ATYPCREATE ON ATYPCREATE.ACTIONTYPEID = WFACREATE.ACTIONTYPEID AND ATYPCREATE.ACTIONTYPETEXT = 'Create'
			) WFACREATE ON WFACREATE.WORKFLOWID = WF.WORKFLOWID
		LEFT JOIN
			(
				SELECT WFAUPDATE.*
				FROM 
					WORKFLOWACTION WFAUPDATE
					INNER JOIN ACTIONTYPE ATYPUPDATE ON ATYPUPDATE.ACTIONTYPEID = WFAUPDATE.ACTIONTYPEID AND ATYPUPDATE.ACTIONTYPETEXT = 'Update'
			) WFAUPDATE ON WFAUPDATE.WORKFLOWID = WF.WORKFLOWID
		LEFT JOIN
			(
				SELECT WFADELETE.*
				FROM 
					WORKFLOWACTION WFADELETE
					INNER JOIN ACTIONTYPE ATYPDELETE ON ATYPDELETE.ACTIONTYPEID = WFADELETE.ACTIONTYPEID AND ATYPDELETE.ACTIONTYPETEXT = 'Delete'
			) WFADELETE ON WFADELETE.WORKFLOWID = WF.WORKFLOWID
		LEFT JOIN
			(
				SELECT WFAEXECUTE.*
				FROM 
					WORKFLOWACTION WFAEXECUTE
					INNER JOIN ACTIONTYPE ATYPEXECUTE ON ATYPEXECUTE.ACTIONTYPEID = WFAEXECUTE.ACTIONTYPEID AND ATYPEXECUTE.ACTIONTYPETEXT = 'Execute'
			) WFAEXECUTE ON WFAEXECUTE.WORKFLOWID = WF.WORKFLOWID


	-- FILLING VALUES IN ABOVE WORKFLOW TABLE -- filling the able workflow table
	SELECT 
		RA.HASACCESSID
		, CAST(ISNULL(WFAVIEW.WORKFLOWACTIONID - WFAVIEW.WORKFLOWACTIONID + 1, 0) AS BIT) 'View', WFAVIEW.WORKFLOWACTIONID 'ViewActionID'
		, CAST(ISNULL(WFACREATE.WORKFLOWACTIONID - WFACREATE.WORKFLOWACTIONID + 1, 0) AS BIT) 'Create', WFACREATE.WORKFLOWACTIONID 'CreateActionID'
		, CAST(ISNULL(WFAUPDATE.WORKFLOWACTIONID - WFAUPDATE.WORKFLOWACTIONID + 1, 0) AS BIT) 'Update', WFAUPDATE.WORKFLOWACTIONID 'UpdateActionID'
		, CAST(ISNULL(WFADELETE.WORKFLOWACTIONID - WFADELETE.WORKFLOWACTIONID + 1, 0) AS BIT) 'Delete', WFADELETE.WORKFLOWACTIONID 'DeleteActionID'
		, CAST(ISNULL(WFAEXECUTE.WORKFLOWACTIONID - WFAEXECUTE.WORKFLOWACTIONID + 1, 0) AS BIT) 'Execute', WFAEXECUTE.WORKFLOWACTIONID 'ExecuteActionID'
	FROM
		HASACCESS RA
		LEFT JOIN 
			(
				SELECT WFAVIEW.*
				FROM 
					WORKFLOWACTION WFAVIEW 
					INNER JOIN ACTIONTYPE ATYPVIEW ON ATYPVIEW.ACTIONTYPEID = WFAVIEW.ACTIONTYPEID AND ATYPVIEW.ACTIONTYPETEXT = 'View'
			) WFAVIEW ON WFAVIEW.WORKFLOWACTIONID = RA.WORKFLOWACTIONID
		LEFT JOIN 
			(
				SELECT WFACREATE.*
				FROM 
					WORKFLOWACTION WFACREATE 
					INNER JOIN ACTIONTYPE ATYPCREATE ON ATYPCREATE.ACTIONTYPEID = WFACREATE.ACTIONTYPEID AND ATYPCREATE.ACTIONTYPETEXT = 'Create'
			) WFACREATE ON WFACREATE.WORKFLOWACTIONID = RA.WORKFLOWACTIONID
		LEFT JOIN
			(
				SELECT WFAUPDATE.*
				FROM 
					WORKFLOWACTION WFAUPDATE
					INNER JOIN ACTIONTYPE ATYPUPDATE ON ATYPUPDATE.ACTIONTYPEID = WFAUPDATE.ACTIONTYPEID AND ATYPUPDATE.ACTIONTYPETEXT = 'Update'
			) WFAUPDATE ON WFAUPDATE.WORKFLOWACTIONID = RA.WORKFLOWACTIONID
		LEFT JOIN
			(
				SELECT WFADELETE.*
				FROM 
					WORKFLOWACTION WFADELETE
					INNER JOIN ACTIONTYPE ATYPDELETE ON ATYPDELETE.ACTIONTYPEID = WFADELETE.ACTIONTYPEID AND ATYPDELETE.ACTIONTYPETEXT = 'Delete'
			) WFADELETE ON WFADELETE.WORKFLOWACTIONID = RA.WORKFLOWACTIONID
		LEFT JOIN
			(
				SELECT WFAEXECUTE.*
				FROM 
					WORKFLOWACTION WFAEXECUTE
					INNER JOIN ACTIONTYPE ATYPEXECUTE ON ATYPEXECUTE.ACTIONTYPEID = WFAEXECUTE.ACTIONTYPEID AND ATYPEXECUTE.ACTIONTYPETEXT = 'Execute'
			) WFAEXECUTE ON WFAEXECUTE.WORKFLOWACTIONID = RA.WORKFLOWACTIONID
	WHERE
		(RA.ROLEID = @RoleID OR @RoleID = 0)
		AND (RA.USERID = @UserID OR @UserID = 0)
		AND RA.DELETEDDATE IS NULL

	SELECT RA.HASACCESSID, RA.WORKFLOWACTIONID
	FROM HASACCESS RA
	WHERE
		(RA.ROLEID = @RoleID OR @RoleID = 0)
		AND (RA.USERID = @UserID OR @UserID = 0)
		AND RA.DELETEDDATE IS NULL

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_HD_ENTITY_MASTER]    Script Date: 17-10-2026 13:04:47 ******/
