CREATE PROCEDURE [dbo].[USP_R_HD_ENTITY_MASTER]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ISNULL(BRANCHNAME, '') AS [Entity Name *],
        ISNULL(BRANCHCODE, '') AS [Entity Code],
        CASE
            WHEN ISWAREHOUSE = 1 THEN 'Warehouse'
            ELSE 'Store'
        END AS [Entity Type *],
        CASE
            WHEN DELETEDDATE IS NULL THEN 'Active'
            ELSE 'Inactive'
        END AS [Status],
        ISNULL(EMAILID, '') AS [Email],
        ISNULL(PHONENO, '') AS [Mobile],
        '' AS [Default],
        CASE
            WHEN ISWAREHOUSE = 1 THEN 'Warehouse'
            ELSE 'Store'
        END AS [Entity Category *],
        CONVERT(VARCHAR(20), BRANCHID) AS [Erp Id *],
        'NSRetail' AS [Erp Source],
        '' AS [OwnerShip],
        '' AS [Description],
        '37AAICV7240C1ZC' AS [GST No.],
        'U51390AP2022PTC121579' AS [CIN],
        '10114004000548' AS [FSSAI],
        '' AS [TRN],
        '' AS [Business City],
        '' AS [Business Area],
        '' AS [Contact Name],
        '' AS [Contact Designation],
        ISNULL(EMAILID, '') AS [Contact Email],
        ISNULL(PHONENO, '') AS [Contact Number],
        ISNULL(ADDRESS, '') AS [Address Line 1 *],
        '' AS [Address Line 2],
        '' AS [Locality *],
        '' AS [City *],
        CASE
            WHEN STATEID IS NULL THEN ''
            ELSE CONVERT(VARCHAR(20), STATEID)
        END AS [State *],
        '' AS [Country *],
        '' AS [Pincode *]
    FROM dbo.BRANCH
    ORDER BY BRANCHCODE;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_HD_INVENTORY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_HD_INVENTORY]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
		B.BRANCHCODE,
        ISNULL(ITEMCODE, '') AS [Item Code / Barcode *],
        0 AS [Is Publish To Customer *],
        CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS 
		ELSE SS.QUANTITY END AS [Inventory Count *]
    FROM ITEMPRICE IP
		INNER JOIN STOCKSUMMARY SS ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		INNER JOIN BRANCH B ON SS.BRANCHID = B.BRANCHID
	WHERE B.DELETEDDATE IS NULL
		AND I.DELETEDDATE IS NULL
		AND IC.DELETEDDATE IS NULL
		AND IP.DELETEDDATE IS NULL
		AND (SS.QUANTITY > 0 OR SS.WEIGHTINKGS > 0)
    ORDER BY B.BRANCHCODE, IC.ITEMCODE, IP.MRP
END
GO
