CREATE PROCEDURE [dbo].[USP_R_HD_PRODUCT_MASTER]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        '' AS [Image Folder],
        '' AS [Images],
        ISNULL(TB.BRANDNAME, '') AS [Brand],
        ISNULL(I.SKUCODE, '') AS [Product Code *],
        ISNULL(I.ITEMNAME, '') AS [Product Name *],
        ISNULL(I.SKUCODE, '') AS [Variant SKU *],
        '' AS [Option Name -1],
        '' AS [Option Value -1],
        ISNULL(PITEM.ITEMNAME, '') AS [Common Name],
        '' AS [Description],
        ISNULL(SNLTY.SEASONALITY, '') AS [Tags (Product Keywords)],
        ISNULL(IBC.ITEMCODE, '') AS [Variant Barcode],
        '' AS [Quantity],
        ISNULL(CONVERT(VARCHAR(50), UM.MULTIPLIER), '') AS [Measure],
        ISNULL(CONVERT(VARCHAR(50), UQC.QUANTITY), '') AS [UOM *],
        ISNULL(RP.REFUNDPATHTEXT, '') AS [Product Family],
        '' AS [Product Type *],
        ISNULL(C.CATEGORYNAME, '') AS [Category *],
        ISNULL(SC.SUBCATEGORYNAME, '') AS [Sub Category],
        ISNULL(CLS.CLASSIFICATIONNAME, '') AS [Classification],
        ISNULL(IBC.ITEMCODE, '') AS [ERP - Item Code],
        ISNULL(I.SKUCODE, '') AS [ERP - Product Code],
        '' AS [ERP - (Variant Quantity)],
        '' AS [ERP - (Variant Value)],
        ISNULL(CONVERT(VARCHAR(50), UQC.QUANTITY), '') AS [ERP - UOM],
        ISNULL(CONVERT(VARCHAR(50), IP.MRP), '') AS [MRP],
        '' AS [Online Discount Type],
        '' AS [Online Discount Value],
        '' AS [In Store Discount Type],
        '' AS [In Store Discount Value],
        '' AS [Whole Sales Price],
        '' AS [Inventory Type],
        0 AS [Inventory],
        ISNULL(GST.GSTCODE, '') AS [Tax Template],
        '' AS [Tax Inclusive],
        ISNULL(IBC.HSNCODE, ISNULL(I.HSNCODE, '')) AS [HSN],
        0 AS [Is Publish To Customer],
        '' AS [Slug],
        '' AS [SEO Title],
        '' AS [SEO Description],
        '' AS [Keywords],
        '' AS [Image Alt Text]
    FROM dbo.ITEMCODE IBC
        INNER JOIN dbo.ITEM I ON I.ITEMID = IBC.ITEMID
        LEFT JOIN dbo.TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
        LEFT JOIN dbo.SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
        LEFT JOIN dbo.UOM UM ON I.UOMID = UM.UOMID
        LEFT JOIN dbo.ITEM PITEM ON I.PARENTITEMID = PITEM.ITEMID
        LEFT JOIN dbo.TBLBRAND TB ON I.BRANDID = TB.BRANDID
        LEFT JOIN dbo.ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
        LEFT JOIN dbo.UQCDATA UQC ON UQC.UQCID = I.UQCID
        LEFT JOIN dbo.GSTDETAIL GST ON GST.GSTID = I.GSTID
        LEFT JOIN dbo.REFUNDPATH RP ON RP.REFUNDPATHID = I.REFUNDPATHID
        OUTER APPLY
        (
            SELECT STRING_AGG(SNLTY.SEASON, ', ') AS SEASONALITY
            FROM dbo.SplitString(I.SEASONALITYIDS, ',') SPLIT
                INNER JOIN dbo.SEASONALITY SNLTY ON SNLTY.SEASONALITYID = SPLIT.Item
        ) SNLTY
        OUTER APPLY
        (
            SELECT TOP (1)
                IP.MRP,
                IP.SALEPRICE
            FROM dbo.ITEMPRICE IP
            WHERE IP.ITEMCODEID = IBC.ITEMCODEID
              AND IP.DELETEDBY IS NULL
              AND IP.BRANCHID IS NULL
            ORDER BY IP.ITEMPRICEID DESC
        ) IP
    WHERE IBC.DELETEDDATE IS NULL
      AND I.DELETEDDATE IS NULL
    ORDER BY I.ITEMID, IBC.ITEMCODEID;
END
GO
