/****** Object:  StoredProcedure [dbo].[USP_R_INDENTITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_INDENTITEMS]
@BRANCHINDENTID INT,
@STOCKDISPATCHID INT
AS
BEGIN

	SELECT           
		DS.STOCKDISPATCHID, DS.STOCKDISPATCHDETAILID,I.ITEMID,IC.ITEMCODEID,IP.ITEMPRICEID,          
		I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,IP.MRP,IP.SALEPRICE,DS.DISPATCHQUANTITY,          
		DS.WEIGHTINKGS,DS.TRAYNUMBER, ISNULL(I.ISOPENITEM,0) AS ISOPENITEM, 
		ISNULL(DS.BRANCHINDENTDETAILID,0) AS BRANCHINDENTDETAILID, SCAT.SUBCATEGORYNAME
	INTO #SDD
	FROM  STOCKDISPATCHDETAIL DS             
		INNER JOIN ITEMPRICE IP ON DS.ITEMPRICEID = IP.ITEMPRICEID            
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID            
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
		LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID            
		AND DS.DELETEDDATE IS NULL
	ORDER BY DS.STOCKDISPATCHDETAILID

	SELECT
		BID.BRANCHINDENTID
		,BID.BRANCHINDENTDETAILID
		,BID.ITEMID
		,I.SKUCODE
		,I.ITEMNAME
		,I.ISOPENITEM
		,BID.INDENTQUANTITY
		,ISNULL(SDD.DISPATCHQUANTITY, 0) AS DISPATCHQUANTITY
		,ISNULL(SDD.WEIGHTINKGS,0) AS WEIGHTINKGS
		,BID.BRANCHSTOCK
		,BID.AVGSALES
		,BID.NOOFDAYSSALES
		,BID.LASTDISPATCHEDDATE
	FROM BRANCHINDENTDETAIL BID
		INNER JOIN ITEM I ON I.ITEMID = BID.ITEMID
		LEFT JOIN 
		(
			SELECT 
				BRANCHINDENTDETAILID, 
				SUM(DISPATCHQUANTITY) AS DISPATCHQUANTITY, 
				SUM(WEIGHTINKGS) AS WEIGHTINKGS 
			FROM #SDD
			GROUP BY BRANCHINDENTDETAILID
		) AS SDD ON BID.BRANCHINDENTDETAILID = SDD.BRANCHINDENTDETAILID
	WHERE BRANCHINDENTID = @BRANCHINDENTID AND BID.DELETEDDATE IS NULL
	ORDER BY I.ITEMNAME

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_INDENTLIMIT_BY_ITEM]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_R_INDENTLIMIT_BY_ITEM]
(
	@ItemID INT
)
AS
BEGIN

	SELECT 
		IL.INDENTLIMITID, B.BRANCHID, B.BRANCHNAME, @ItemID ITEMID, SSMAIN.BRANCHSTOCK
		, ISNULL(IL.THRESHOLD, 0) THRESHOLD, ISNULL(IL.DESIREDQUANTITY, 0) DESIREDQUANTITY 
		, CU.FULLNAME CREATEDBY, IL.CREATEDDATE, UU.FULLNAME UPDATEDBY, IL.UPDATEDDATE
	FROM 
		BRANCH B
		INNER JOIN 
		(
			SELECT SSINNER.BRANCHID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) BRANCHSTOCK
			FROM
				STOCKSUMMARY SSINNER
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			WHERE 
				I.ITEMID = @ItemID
			GROUP BY SSINNER.BRANCHID
		) SSMAIN ON SSMAIN.BRANCHID = B.BRANCHID
		LEFT JOIN INDENTLIMIT IL ON IL.BRANCHID = B.BRANCHID AND IL.ITEMID = @ItemID
		LEFT JOIN TBLUSER CU ON CU.USERID = IL.CREATEDBY
		LEFT JOIN TBLUSER UU ON UU.USERID = IL.UPDATEDBY
	WHERE 
		B.DELETEDDATE IS NULL
		
END
GO
