CREATE PROCEDURE [dbo].[USP_R_INITIALSR]
@SupplierID int,
@CategoryID int,
@StockEntryID int = 0,
@BranchID int
AS
BEGIN

	DECLARE @SUPPLIERETURNSID INT = 0
	SELECT @SUPPLIERETURNSID = SUPPLIERRETURNSID 
	FROM SUPPLIERRETURNS 
	WHERE SUPPLIERID = @SupplierID 
		AND CATEGORYID = @CategoryID 
		AND BRANCHID = @BranchID
		AND (ISNULL(STOCKENTRYID,0) = @StockEntryID) 
		AND ISNULL(STATUS,0) = 0
		AND DELETEDDATE IS NULL

	SELECT SUPPLIERRETURNSID,SUPPLIERID,CATEGORYID,STOCKENTRYID, BRANCHID
	FROM SUPPLIERRETURNS 
	WHERE SUPPLIERRETURNSID = @SUPPLIERETURNSID

	EXEC USP_R_SUPPLIERRETURNSDETAIL @SUPPLIERETURNSID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_INVOICELIST_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_INVOICELIST_v2]          
@DealerID int = 0,
@FromDate date = NULL,  
@ToDate date = NULL  ,
@IsBranchInvoice Bit = 0,
@BranchID INT = 0
AS          
BEGIN          
    
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT           
		ROW_NUMBER() OVER (ORDER BY SE.STOCKENTRYID DESC) AS SNO, 
		SE.STOCKENTRYID,
		SE.SUPPLIERINVOICENO,    
		SI.SUPPLIERINDENTNO,
		D.DEALERNAME, 
		D.GSTIN, 
		C.CATEGORYNAME,
		CU.FULLNAME AS CREATEDBY, 
		SE.CREATEDDATE ,      
		SU.FULLNAME AS SUBMITTEDBY, 
		SE.SUBMITTEDDATE AS SUBMITTEDDATE,
		SE.INVOICEDATE,
		ISNULL(SE.TRANSPORT,0) AS Transport, 
		ISNULL(SECNM.CREDITVALUE,0) as CreditValue,
		ISNULL(SE.DISCOUNT,0) as Discount, 
		ISNULL(SE.PackingCharges,0) AS PackingCharges,
		ISNULL(SE.TCS,0) AS TCS,
		ISNULL(SE.EXPENSES,0) AS Expenses,
		(
			SEDSUM.FINALPRICE + 
			ISNULL(SE.TRANSPORT, 0) -
			ISNULL(SECNM.CREDITVALUE, 0) - 
			ISNULL(SE.DISCOUNT, 0) +
			ISNULL(SE.PackingCharges, 0) +
			ISNULL(SE.TCS, 0) + 
			ISNULL(SE.EXPENSES, 0) 
		) AS FinalPrice, 
		CASE 
			WHEN SE.Reverted_Date IS NOT NULL THEN 'Reverted' 
			WHEN ISNULL(SE.STATUS, 0) = 0 THEN 'Draft' 
			WHEN SE.STATUS = 1 THEN 'Submitted' 
			WHEN SE.STATUS = 2 THEN 'Submitted via Mobile' 
			ELSE 'Unknown' END AS STATUS, 
		ISNULL(ItemCount, 0) AS 'Item Count',  
		SE.RECEIVINGBRANCHID, 
		B.BRANCHNAME AS RECEIVINGBRANCH,
		SD.DISPATCHNUMBER as DispatchNumber, 
		DB.BRANCHNAME AS DispatchBranch,
		D.DEALERID

	FROM STOCKENTRY SE          
		LEFT JOIN TBLDEALER D ON SE.SUPPLIERID = D.DEALERID          
		LEFT JOIN TBLCATEGORY C ON SE.CATEGORYID = C.CATEGORYID          
		LEFT JOIN TBLUSER CU ON SE.CREATEDBY = CU.USERID         
		LEFT JOIN TBLUSER SU ON SE.SUBMITTEDBY = SU.USERID         
		LEFT JOIN 
			(
				SELECT COUNT(*) AS ItemCount,SED.STOCKENTRYID, SUM(SED.FINALPRICE) AS FINALPRICE
				FROM 
					STOCKENTRYDETAIL SED
					INNER JOIN STOCKENTRY SE ON SE.STOCKENTRYID = SED.STOCKENTRYID
				WHERE
					SED.DELETEDDATE IS NULL OR SED.Reverted_Date IS NOT NULL
				GROUP BY SED.STOCKENTRYID
			) SEDSUM ON SEDSUM.STOCKENTRYID = SE.STOCKENTRYID
		LEFT JOIN  BRANCH B ON SE.RECEIVINGBRANCHID = B.BRANCHID
		LEFT JOIN 
		(
			SELECT DISPATCHNUMBER, REFID, TOBRANCHID FROM STOCKDISPATCH WHERE SOURCEENTITYID = 2 
		) SD ON SE.STOCKENTRYID =  SD.REFID
		LEFT JOIN 
		(
			SELECT 
				STOCKENTRYID, SUM(MappedReturnValue) AS CREDITVALUE
			FROM STOCKENTRYCREDITNOTEMAP 
			WHERE DELETEDDATE IS NULL
			GROUP BY STOCKENTRYID

		) SECNM ON SE.STOCKENTRYID = SECNM.STOCKENTRYID
		LEFT JOIN BRANCH DB ON SD.TOBRANCHID = DB.BRANCHID
		LEFT JOIN SUPPLIERINDENT SI ON SI.SUPPLIERINDENTID = SE.SUPPLIERINDENTID
	WHERE   
		(SE.SUPPLIERID = @DealerID OR @DealerID = 0)
		AND SE.CREATEDDATE >= @FromDate  
		AND SE.CREATEDDATE <= @ToDate
		AND (SE.DELETEDDATE IS NULL OR SE.Reverted_Date IS NOT NULL)
		AND (SE.RECEIVINGBRANCHID = @BranchID OR @BranchID = 0)
	ORDER BY STOCKENTRYID DESC
          
END
GO
