CREATE PROCEDURE [dbo].[USP_R_ITEMCLASSIFICATION]    
(
	@IncludeDeleted BIT = 0
)
AS      
BEGIN      
      

	SELECT 
		ICLS.CLASSIFICATIONID, ICLS.CATEGORYID, ICLS.CLASSIFICATIONNAME, CAT.CATEGORYNAME
		, CU.USERNAME AS CREATEDBY, ICLS.CREATEDDATE, UU.USERNAME AS UPDATEDBY, ICLS.UPDATEDDATE
		, DU.USERNAME AS DELETEDBY, ICLS.DELETEDDATE
	FROM 
		ITEMCLASSIFICATION ICLS
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = ICLS.CATEGORYID
		LEFT JOIN TBLUSER CU ON CU.USERID = ICLS.CREATEDBY
		LEFT JOIN TBLUSER UU ON UU.USERID = ICLS.UPDATEDBY
		LEFT JOIN TBLUSER DU ON DU.USERID = ICLS.DELETEDBY
     WHERE (ICLS.DELETEDDATE IS NULL OR @IncludeDeleted = 1)

END
