/****** Object:  StoredProcedure [dbo].[USP_R_ITEMCODE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_R_ITEMCODE]    
@ItemCodeID INT  
, @CategoryID INT    
AS    
BEGIN    
    
 DECLARE @AllCategoryID INT    
 SELECT @AllCategoryID = CATEGORYID FROM TBLCATEGORY WHERE CATEGORYNAME = 'ALL'    
    
 SELECT    
  IC.ITEMCODEID    
  , IC.ITEMID    
  , IC.ITEMCODE    
  , I.ITEMNAME    
  , I.SKUCODE    
  , I.DESCRIPTION    
  , I.CATEGORYID    
  , ISNULL(I.ISOPENITEM, 0) AS ISOPENITEM    
  , I.PARENTITEMID    
  , I.SUBCATEGORYID    
  , I.UOMID    
  , IC.HSNCODE    
  , IC.ISEAN      
  , CU.FULLNAME AS CREATEDBY    
  , I.CREATEDDATE    
  , UU.FULLNAME AS UPDATEDBY    
  , I.UPDATEDATE     
  , IC.FREEITEMCODEID    
  , I.CLASSIFICATIONID
  , I.SUBCLASSIFICATIONID
  , I.BRANDID
  , I.MANUFACTURERID
  , I.UQCID
  , I.VENDORSKUCODE
  , I.SEASONALITYIDS, I.REFUNDPATHID, I.ISDSD
 FROM     
  ITEMCODE IC     
  INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID    
  INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID    
  LEFT JOIN TBLUSER CU ON CU.USERID = IC.CREATEDBY    
  LEFT JOIN TBLUSER UU ON UU.USERID = IC.UPDATEDBY      
 WHERE     
  IC.ITEMCODEID = @ItemCodeID    
  AND IC.DELETEDDATE IS NULL    
    
 SELECT     
	 ICP.COSTPRICEWT,
	 ICP.COSTPRICEWOT,
	 IP.SALEPRICE, 
	 IP.MRP, 
	 IP.GSTID, 
	 GST.GSTCODE
 FROM  
  ITEMPRICE IP    
  INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID    
  INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID    
  INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID    
  INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
  LEFT JOIN IPICPView ICP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
 WHERE    
  IC.ITEMCODEID = @ItemCodeID    
  AND IP.BRANCHID IS NULL
  AND IP.DELETEDDATE IS NULL    
  
END
GO
