CREATE PROC [dbo].[USP_R_ITEMCODES_STOCKENTRY_BRANCH]
AS                              
BEGIN                              
  
	SELECT I.ITEMID, I.SKUCODE, I.ITEMNAME,C.CATEGORYNAME, I.GSTID
	FROM ITEM I LEFT JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID                          
	WHERE I.DELETEDDATE IS NULL                              
                              
	SELECT                              
		IBC.ITEMCODEID,I.ITEMID,IBC.ITEMCODE,I.ITEMNAME,I.SKUCODE,                      
		C.CATEGORYNAME, GST.GSTID, GST.GSTCODE, CU.FULLNAME AS CREATEDBY,I.CREATEDDATE,                      
		UU.FULLNAME AS UPDATEDBY,I.UPDATEDATE,ISNULL(I.ISOPENITEM,0) AS ISOPENITEM,                      
		ISNULL(I.PARENTITEMID,0) AS PARENTITEMID,UM.MULTIPLIER ,                
		I.CATEGORYID,C.CATEGORYNAME,I.SUBCATEGORYID,SC.SUBCATEGORYNAME,          
		IBC.HSNCODE  , PITEM.SKUCODE AS PARENTSKUCODE, PITEM.ITEMNAME AS PARENTITEMNAME,
		CLS.CLASSIFICATIONNAME, SUBCLS.SUBCLASSIFICATIONNAME,
		TB.BRANDNAME, TM.MANUFACTURERNAME, TB.BRANDID, TM.MANUFACTURERID, UQC.QUANTITY UQCNAME
	FROM ITEMCODE IBC                               
		INNER JOIN ITEM I ON I.ITEMID = IBC.ITEMID                              
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID                          
		INNER JOIN SUBCATEGORY sc ON I.SUBCATEGORYID = SC.SUBCATEGORYID          
		LEFT JOIN UOM UM ON I.UOMID = UM.UOMID      
		LEFT JOIN ITEM PITEM ON I.PARENTITEMID = PITEM.ITEMID
		LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
		LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
		LEFT JOIN ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		LEFT JOIN UQCDATA UQC ON UQC.UQCID = I.UQCID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = I.GSTID
		LEFT JOIN TBLUSER CU ON CU.USERID = I.CREATEDBY                              
		LEFT JOIN TBLUSER UU ON UU.USERID = I.UPDATEDBY                              
	WHERE   IBC.DELETEDDATE IS NULL 
		AND SC.INSTANTDISPATCHENABLED = 1
		AND ISNULL(IBC.IsDSCode,0) = 0
                    
END
GO
