CREATE PROCEDURE [dbo].[USP_R_ITEMDATA]
@ITEMCODE VARCHAR(100)
AS
BEGIN
	DECLARE @ITEMCODEID INT = 0,@ITEMID INT = 0
	SELECT 
		@ITEMID = ITEMID, 
		@ITEMCODEID = ITEMCODEID 
	FROM ITEMCODE 
	WHERE ITEMCODE = @ITEMCODE 
		AND DELETEDDATE IS NULL

	IF(@ITEMCODEID = 0)
	BEGIN
		SELECT 
			@ITEMID = ITEMID 
		FROM ITEM 
		WHERE SKUCODE = @ITEMCODE
	END

	IF (@ITEMID = 0)
	BEGIN
		SELECT 'Item Does Not Exists!'
		RETURN;
	END

	SELECT ITEMID, SKUCODE, ITEMNAME, ISOPENITEM FROM ITEM WHERE ITEMID = @ITEMID AND DELETEDDATE IS NULL

	SELECT ITEMID, ITEMCODEID, ITEMCODE, HSNCODE 
	FROM ITEMCODE 
	WHERE (ITEMCODEID = @ITEMCODEID OR @ITEMCODEID = 0) AND ITEMID = @ITEMID AND DELETEDDATE IS NULL

	SELECT IP.ITEMCODEID, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, IP.GSTID, ICP.COSTPRICEWT, ICP.COSTPRICEWOT
	FROM ITEMCOSTPRICE ICP 
		INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
	WHERE (IP.ITEMCODEID = @ITEMCODEID OR @ITEMCODEID = 0) 
		AND IC.ITEMID = @ITEMID
		AND IP.DELETEDDATE IS NULL
		AND ICP.DELETEDDATE IS NULL

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_ITEMDATAFORDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
