CREATE PROCEDURE [dbo].[USP_R_ITEMDATAFORDISPATCH]
@ITEMCODE VARCHAR(100),
@CATEGORYID INT
AS
BEGIN
	
	DECLARE @ITEMCODEID INT = 0, @ITEMID INT = 0, @IsOpenItem BIT

	SELECT 
		@ITEMID = IC.ITEMID, 
		@ITEMCODEID = ITEMCODEID,
		@IsOpenItem = I.ISOPENITEM
	FROM ITEMCODE IC
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE ITEMCODE = @ITEMCODE 
		AND I.CATEGORYID = @CATEGORYID
		AND IC.DELETEDDATE IS NULL

	IF(@ITEMCODEID = 0)
	BEGIN
		SELECT 
			@ITEMID = ITEMID 
		FROM ITEM 
		WHERE SKUCODE = @ITEMCODE
		AND CATEGORYID = @CATEGORYID
	END

	IF (@ITEMID = 0)
	BEGIN
		SELECT 'Item Does Not Exists!'
		RETURN;
	END

	SELECT ITEMID, SKUCODE, ITEMNAME, ISOPENITEM, PARENTITEMID FROM ITEM WHERE ITEMID = @ITEMID AND DELETEDDATE IS NULL

	SELECT ITEMID, ITEMCODEID, ITEMCODE, HSNCODE 
	FROM ITEMCODE 
	WHERE (ITEMCODEID = @ITEMCODEID OR @ITEMCODEID = 0) AND ITEMID = @ITEMID AND DELETEDDATE IS NULL

	SELECT IP.ITEMCODEID, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE
	FROM 
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID
	WHERE (IP.ITEMCODEID = @ITEMCODEID OR @ITEMCODEID = 0) 
		AND IC.DELETEDDATE IS NULL
		AND IC.ITEMID = @ITEMID
		AND IP.DELETEDDATE IS NULL
		AND IP.BRANCHID IS NULL
		AND (CASE WHEN @IsOpenItem = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) > 0
		AND SS.BRANCHID = 45

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_ITEMDATAFORDISPATCH_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
