CREATE PROCEDURE [dbo].[USP_R_ITEMDATAFORDISPATCH_v2]  
@ITEMCODE VARCHAR(100),  
@CATEGORYID INT,  
@SUBCATEGORYID INT  
AS  
BEGIN  
   
	DECLARE @ITEMCODEID INT = 0, @ITEMID INT = 0, @IsOpenItem BIT  
  
	SELECT @ITEMID = ITEMID, @IsOpenItem = ISOPENITEM FROM ITEM WHERE SKUCODE = @ITEMCODE AND DELETEDDATE IS NULL
 
	IF(@ITEMID = 0)
	BEGIN
		SELECT   
		@ITEMID = IC.ITEMID,
		@ITEMCODEID = ITEMCODEID,
		@IsOpenItem = I.ISOPENITEM
		FROM ITEMCODE IC
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		WHERE ITEMCODE = @ITEMCODE   
			AND IC.DELETEDDATE IS NULL  
	END
  

  
	IF (@ITEMID = 0)  
	BEGIN  
		SELECT 'Item Does Not Exists!'  
		RETURN;  
	END  
  
	IF NOT EXISTS (SELECT 1 FROM ITEM WHERE ITEMID = @ITEMID AND SUBCATEGORYID = @SUBCATEGORYID)  
	BEGIN  
		SELECT 'Item Does Not Exists In Selected Subcategory!'  
		RETURN;  
	END  
  
	SELECT ITEMID, SKUCODE, ITEMNAME, ISOPENITEM, PARENTITEMID 
	FROM ITEM 
	WHERE ITEMID = @ITEMID 
		AND DELETEDDATE IS NULL  
  
	SELECT ITEMID, ITEMCODEID, ITEMCODE, HSNCODE   
	FROM ITEMCODE   
	WHERE ITEMID = @ITEMID 
		AND (ITEMCODEID = @ITEMCODEID OR @ITEMCODEID = 0) 
		AND DELETEDDATE IS NULL  
  
	SELECT IP.ITEMCODEID, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE  
	FROM ITEMPRICE IP  
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID  
		INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID  
	WHERE (IP.ITEMCODEID = @ITEMCODEID OR @ITEMCODEID = 0)   
		AND IC.DELETEDDATE IS NULL  
		AND IC.ITEMID = @ITEMID  
		AND IP.DELETEDDATE IS NULL  
		AND IP.BRANCHID IS NULL  
		AND (CASE WHEN @IsOpenItem = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) > 0  
		AND SS.BRANCHID = 45  
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_ITEMDATAFORITEMDETAILS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_ITEMDATAFORITEMDETAILS] 
@ItemCode VARCHAR(100),
@BRANCHID INT
AS
BEGIN
	
	DECLARE @IsOpenItem BIT, @ItemID INT, @ItemFound BIT = 0
		
	SELECT @ItemID = IC.ITEMID, @ItemFound = 1
	FROM ITEMCODE IC WHERE ITEMCODE = @ITEMCODE

	IF @ItemFound = 0
	BEGIN
		SELECT @ItemID = I.ITEMID, @ItemFound = 1
		FROM ITEM I WHERE SKUCODE = @ITEMCODE
	END

	IF @ItemFound = 0
	BEGIN
		SELECT 'Item not found'
		RETURN
	END
	
	SELECT 1 AS PARENTID, I.ITEMID, I.SKUCODE, I.ITEMNAME
	FROM ITEM I 
	WHERE ITEMID = @ItemID

	SELECT 
		1 AS PARENTID, I.ITEMID, IC.ITEMCODE, MRP, SALEPRICE, IC.ITEMCODEID, IP.ITEMPRICEID,
		CASE WHEN IP.DELETEDDATE IS NULL THEN 'ACTIVE' ELSE 'INACTIVE' END AS STATUS,
		CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS QTYORWEIGHTINKGS
	FROM
		ITEMPRICE IP		
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID AND SS.BRANCHID = @BRANCHID
	WHERE I.ITEMID = @ItemID
		AND IP.DELETEDDATE IS NULL

	SELECT 1 AS PARENTID, IC.ITEMCODEID, OT.OFFERTYPENAME, OFR.OFFERCODE, OFR.OFFERVALUE
	FROM 
		OFFERITEMMAP OIM 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = OIM.ITEMCODEID
		INNER JOIN OFFER OFR ON OIM.OFFERID = OFR.OFFERID
		INNER JOIN OFFERTYPE OT ON OFR.OFFERTYPEID = OT.OFFERTYPEID
		INNER JOIN OFFERBRANCH OB ON OB.OFFERID = OFR.OFFERID
	WHERE IC.ITEMID = @ItemID
		AND OB.BRANCHID = @BRANCHID
		AND OFR.DELETEDDATE IS NULL
		AND OIM.DELETEDDATE IS NULL
		AND OB.DELETEDDATE IS NULL
	ORDER BY OFR.OFFERID DESC

	--SELECT ICP.ITEMPRICEID, ICP.COSTPRICEWT, ICP.COSTPRICEWOT, GST.GSTCODE
	--FROM ITEMCOSTPRICE ICP
	--	INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
	--	INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	--	INNER JOIN GSTDETAIL GST ON ICP.GSTID = GST.GSTID
	--WHERE IC.ITEMID = @ItemID
	--	AND ICP.DELETEDDATE IS NULL
	--	AND IP.DELETEDDATE IS NULL
		
END
GO
