CREATE PROCEDURE [dbo].[USP_R_ITEMGROUP]
AS
BEGIN

SELECT 
ITEMGROUPID,GROUPNAME,
CASE WHEN ISACTIVE = 0 THEN 'NO' ELSE 'YES' END AS ISACTIVE,
U.FULLNAME AS CREATEDBY,
IG.CREATEDDATE
FROM ITEMGROUP IG
INNER JOIN TBLUSER U ON IG.CREATEDBY = U.USERID

