CREATE PROCEDURE [dbo].[USP_R_ITEMHISTORY]
(
    @ITEMID int
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        il.[ITEMLOGID],
        il.[ACTIONTYPE] AS [Action],
        il.[ACTIONDATE] AS [Action Date],
        il.[ACTIONBY],
        COALESCE(u.[FULLNAME], u.[USERNAME], CONVERT(varchar(20), il.[ACTIONBY])) AS [Action By],
        il.[CHANGEDCOLUMNS] AS [Changed Columns],

        il.[ITEMID],
        il.[SKUCODE],
        il.[ITEMNAME],
        il.[CATEGORYID],
        c.[CATEGORYNAME],
        il.[SUBCATEGORYID],
        sc.[SUBCATEGORYNAME],
        il.[PARENTITEMID],
        pi.[SKUCODE] AS [PARENTSKUCODE],
        pi.[ITEMNAME] AS [PARENTITEMNAME],
        il.[BRANDID],
        b.[BRANDNAME],
        il.[MANUFACTURERID],
        m.[MANUFACTURERNAME],
        il.[UQCID],
        uqc.[QUANTITY] AS UQCName,
        il.[GSTID],
        g.[GSTCODE],
        il.[REFUNDPATHID],
        rp.[REFUNDPATHTEXT],
        il.[SUPPLIERINDENTITEMTYPEID],
        siit.[ENUMVALUE] AS [SUPPLIERINDENTITEMTYPE],

        il.[ISOPENITEM],
        il.[UOMID],
        uom.[DISPLAYVALUE] AS [UOM],
        il.[CLASSIFICATIONID],
        ic.[CLASSIFICATIONNAME],
        il.[SUBCLASSIFICATIONID],
        isc.[SUBCLASSIFICATIONNAME],
        il.[HSNCODE],
        il.[VENDORSKUCODE],
        il.[SEASONALITYIDS],
        il.[ISDSD],
        il.[INNERCASEQTY],
        il.[OUTERCASEQTY],
        il.[PRODUCTRANK]
    FROM [dbo].[ITEM_LOG] il
    LEFT JOIN [dbo].[TBLUSER] u ON u.[USERID] = il.[ACTIONBY]
    LEFT JOIN [dbo].[TBLCATEGORY] c ON c.[CATEGORYID] = il.[CATEGORYID]
    LEFT JOIN [dbo].[SUBCATEGORY] sc ON sc.[SUBCATEGORYID] = il.[SUBCATEGORYID]
    LEFT JOIN [dbo].[ITEM] pi ON pi.[ITEMID] = il.[PARENTITEMID]
    LEFT JOIN [dbo].[UOM] uom ON uom.[UOMID] = il.[UOMID]
    LEFT JOIN [dbo].[ITEMCLASSIFICATION] ic ON ic.[CLASSIFICATIONID] = il.[CLASSIFICATIONID]
    LEFT JOIN [dbo].[ITEMSUBCLASSIFICATION] isc ON isc.[SUBCLASSIFICATIONID] = il.[SUBCLASSIFICATIONID]
    LEFT JOIN [dbo].[TBLBRAND] b ON b.[BRANDID] = il.[BRANDID]
    LEFT JOIN [dbo].[TBLMANUFACTURER] m ON m.[MANUFACTURERID] = il.[MANUFACTURERID]
    LEFT JOIN [dbo].[UQCDATA] uqc ON uqc.[UQCID] = il.[UQCID]
    LEFT JOIN [dbo].[GSTDETAIL] g ON g.[GSTID] = il.[GSTID]
    LEFT JOIN [dbo].[REFUNDPATH] rp ON rp.[REFUNDPATHID] = il.[REFUNDPATHID]
    LEFT JOIN [dbo].[ENUMLIST] siit ON siit.[ENUMID] = il.[SUPPLIERINDENTITEMTYPEID]
        AND siit.[ENUMTYPE] = 'Supplier Indent Item Type'
    WHERE il.[ITEMID] = @ITEMID
    ORDER BY il.[ACTIONDATE] DESC, il.[ITEMLOGID] DESC;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_ITEMMRPLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_ITEMMRPLIST]          
@ITEMCODEID NVARCHAR(20)          
AS          
BEGIN          
          
	SELECT IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, IP.GSTID, GD.GSTCODE
		, GD.CGST, GD.SGST, GD.IGST, GD.CESS, IP.[IMMEDIATE], SM.GOLIVEDATE, ISNULL(SM.MOVESTATUS, 1)
	FROM ITEMPRICE IP      
		INNER JOIN GSTDETAIL GD ON IP.GSTID = GD.GSTID      
		LEFT JOIN 
			( 
				SELECT MAX(SMINNER.STOCKMOVEID) STOCKMOVEID, SMINNER.NEWITEMPRICEID 
				FROM STOCKMOVE SMINNER 
				WHERE SMINNER.DELETEDDATE IS NULL
				GROUP BY SMINNER.NEWITEMPRICEID
			) SMMAX ON SMMAX.NEWITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN STOCKMOVE SM ON SM.STOCKMOVEID = SMMAX.STOCKMOVEID
	WHERE ITEMCODEID = @ITEMCODEID          
		AND IP.DELETEDDATE IS NULL
		AND IP.BRANCHID IS NULL
	ORDER BY IP.ITEMPRICEID desc
          
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_ITEMPRICE_BRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_R_ITEMPRICE_BRANCH]
@BRANCHID INT,
@ITEMCODEID INT
AS
BEGIN

	SELECT 
		PIP.ITEMPRICEID AS PIPID, 
		ISNULL(CIP.ITEMPRICEID,0) AS CIPID,
		PIP.MRP, 
		ISNULL(CIP.SALEPRICE, PIP.SALEPRICE) AS SALEPRICE, 
		GST.GSTID, 
		GST.GSTCODE, 
		GST.SGST, 
		GST.CGST, 
		GST.IGST, 
		GST.CESS
	FROM ITEMPRICE PIP 
	LEFT JOIN ITEMPRICE CIP ON PIP.ITEMPRICEID = CIP.PARENTITEMPRICEID AND CIP.BRANCHID = @BRANCHID
	INNER JOIN GSTDETAIL GST ON PIP.GSTID = GST.GSTID
	WHERE PIP.ITEMCODEID = @ITEMCODEID 
		AND PIP.BRANCHID IS NULL
		AND PIP.DELETEDDATE IS NULL
		AND CIP.DELETEDDATE IS NULL

END
GO
