SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_ITEMSFORSUPPLIERSKUMAPPING]
@SUPPLIERID INT
AS
BEGIN
	
	SELECT 
		I.ITEMID, 
		I.SKUCODE, 
		I.ITEMNAME, 
		CAT.CATEGORYNAME, 
		SCAT.SUBCATEGORYNAME, 
		BR.BRANDNAME, 
		MAN.MANUFACTURERNAME
	FROM ITEM I 
		INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
		LEFT  JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
		LEFT  JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT  JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	WHERE NOT EXISTS
	(
		SELECT 1 FROM ITEMSUPPLIERMAP ISM 
		WHERE I.ITEMID = ISM.ITEMID 
			AND ISM.SUPPLIERID = @SUPPLIERID 
			AND ISM.DELETEDDATE IS NULL
	)
	AND I.DELETEDDATE IS NULL

END
GO
