CREATE PROCEDURE [dbo].[USP_R_ITEMSUBCLASSIFICATION]      
(
	@IncludeDeleted BIT = 0
)
AS      
BEGIN      
      
	SELECT 
		ISCLS.SUBCLASSIFICATIONID, ISCLS.CLASSIFICATIONID, ISCLS.SUBCLASSIFICATIONNAME, 
		CU.USERNAME AS CREATEDBY, ISCLS.CREATEDDATE, UU.USERNAME AS UPDATEDBY, ISCLS.UPDATEDDATE
		, DU.USERNAME AS DELETEDBY, ISCLS.DELETEDDATE
	FROM 
		ITEMSUBCLASSIFICATION ISCLS		
		LEFT JOIN TBLUSER CU ON CU.USERID = ISCLS.CREATEDBY
		LEFT JOIN TBLUSER UU ON UU.USERID = ISCLS.UPDATEDBY
		LEFT JOIN TBLUSER DU ON DU.USERID = ISCLS.DELETEDBY
     WHERE (ISCLS.DELETEDDATE IS NULL OR @IncludeDeleted = 1)
 
     
END
