/****** Object:  StoredProcedure [dbo].[USP_R_ITEMVISUALIZER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_R_ITEMVISUALIZER]          
@ItemID INT          
AS          
BEGIN          
          
	SELECT I.ITEMNAME, I.SKUCODE, I.DESCRIPTION          
	FROM ITEM I          
	WHERE I.ITEMID = @ItemID          
          
	SELECT           
		IP.ITEMPRICEID          
		, IP.ITEMCODEID          
		, IC.ITEMCODE          
		, ICP.COSTPRICEWT          
		, ICP.COSTPRICEWOT          
		, IP.SALEPRICE          
		, IP.MRP          
		, IP.GSTID          
		, GST.GSTCODE          
		, CIP.FULLNAME AS IPCREATEDBY          
		, IP.CREATEDDATE AS IPCREATEDDATE
		, DIP.FULLNAME AS IPDELETEDBY
		, IP.DELETEDDATE AS IPDELETEDDATE
		, CICP.FULLNAME AS ICPCREATEDBY
		, ICP.CREATEDDATE AS ICPCREATEDDATE
		, DICP.FULLNAME AS ICPDELETEDBY
		, ICP.DELETEDDATE AS ICPDELETEDDATE
		
	FROM  ITEMPRICE IP          
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID          
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID          
		LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMPRICEID = IP.ITEMPRICEID        
		LEFT JOIN TBLUSER CIP ON CIP.USERID = IP.CREATEDBY          
		LEFT JOIN TBLUSER DIP ON DIP.USERID = IP.DELETEDBY
		LEFT JOIN TBLUSER CICP ON CICP.USERID = ICP.CREATEDBY          
		LEFT JOIN TBLUSER DICP ON DICP.USERID = ICP.DELETEDBY
	WHERE IC.ITEMID = @ItemID AND IP.BRANCHID IS NULL
          
	SELECT 
		IC.ITEMCODEID
		, IC.ITEMCODE
		, SS.BRANCHID          
		, B.BRANCHNAME          
		, SUM(SS.QUANTITY) AS QUANTITY
		, SUM(SS.WEIGHTINKGS) AS WEIGHTINKGS
	FROM           
	STOCKSUMMARY SS          
	INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
	INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID  
	INNER JOIN BRANCH B ON B.BRANCHID = SS.BRANCHID  
	WHERE IC.ITEMID = @ItemID  AND B.DELETEDDATE IS NULL
	GROUP BY 
		IC.ITEMCODEID
		, IC.ITEMCODE
		, SS.BRANCHID          
		, B.BRANCHNAME  

	SELECT 
		IP.ITEMPRICEID,
		IP.PARENTITEMPRICEID,
		B.BRANCHNAME,
		IP.SALEPRICE
	FROM ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN BRANCH B ON IP.BRANCHID = B.BRANCHID
	WHERE IC.ITEMID = @ItemID 
		AND IP.DELETEDDATE IS NULL
		AND IP.BRANCHID IS NOT NULL
          
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_ITEMWITHADDITIONALFIELDS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_R_ITEMWITHADDITIONALFIELDS]
AS 
BEGIN

	SELECT                              
		I.ITEMID,I.ITEMNAME,I.SKUCODE
		, C.CATEGORYNAME,ISNULL(I.ISOPENITEM,0) AS ISOPENITEM
		, I.CATEGORYID,C.CATEGORYNAME,I.SUBCATEGORYID,SC.SUBCATEGORYNAME, I.HSNCODE
		, TB.BRANDNAME, TM.MANUFACTURERNAME, TB.BRANDID, TM.MANUFACTURERID
		, I.REFUNDPATHID, RP.REFUNDPATHTEXT AS REFUNDPATH, I.SUPPLIERINDENTITEMTYPEID, SIIP.ENUMVALUE AS SUPPLIERINDENTITEMTYPE
		, I.INNERCASEQTY, I.OUTERCASEQTY, I.PRODUCTRANK, i.DELETEDDATE
	FROM ITEM I
		LEFT JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID                          
		LEFT JOIN SUBCATEGORY sc ON I.SUBCATEGORYID = SC.SUBCATEGORYID          
		LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
		LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
		LEFT JOIN REFUNDPATH RP ON I.REFUNDPATHID = RP.REFUNDPATHID	
		LEFT JOIN ENUMLIST SIIP ON I.SUPPLIERINDENTITEMTYPEID = SIIP.ENUMID AND SIIP.ENUMTYPE = 'Supplier Indent Item Type'
	WHERE   I.DELETEDDATE IS NULL

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_LIQUIDATION]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_R_LIQUIDATION]
(
	@FromDate DATE,
	@ToDate DATE,
	@BranchIDs VARCHAR(MAX),
	@ShowStock BIT = 0,
	@ShowAll BIT = 1,
	@ShowCostPrice BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(D, 1, @ToDate)
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')

	SELECT 
		LQ.LIQUIDATIONID, LQ.BRANCHID, BNAME.BRANCHNAME, CAT.CATEGORYID, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, I.ISOPENITEM, RP.REFUNDPATHTEXT, IP.MRP, IP.SALEPRICE, LQ.QTYORWGHTINKGS, LQ.LIQUIDATIONSALEPRICE, LQ.LIQUIDATIONREASONID, LR.LIQUIDATIONREASONTEXT
		, LQ.MANUFACTUREDATE, LQ.EXPIRYDATE, CASE WHEN LQ.EXPIRYDATE > GETDATE() THEN DATEDIFF(d, GETDATE(), LQ.EXPIRYDATE) ELSE 0 END AS EXPIRINGINDAYS
		, CAST(0.00 AS DECIMAL(9, 2)) STOCK, CAST(0.00 AS DECIMAL(9, 2)) RUNNINGSALE, LQ.STATUS, LQ.[DESCRIPTION], IC.ITEMCODEID, IP.ITEMPRICEID
		, CASE 
			WHEN LQ.STATUS = 0 THEN 'Created' 
			WHEN LQ.STATUS = 1 THEN 'Approved' 
			WHEN LQ.STATUS = 2 THEN 'Rejected' 
		  ELSE 'Unknown' END STATUSTEXT
		, CASE WHEN SM.MOVESTATUS = 1 THEN 'Yes' ELSE 'No' END STOCKPROCESSED
		, NIC.ITEMCODE LIQUIDATIONITEMCODE, SM.NEWITEMPRICEID LIQITEMPRICEID, CAST((CASE WHEN I.ISOPENITEM = 1 THEN SSLIQ.WEIGHTINKGS ELSE SSLIQ.QUANTITY END) AS DECIMAL(9, 2)) LIQSTOCK
		, CUSR.FULLNAME AS CREATEDBY, LQ.CREATEDDATE, SUSR.FULLNAME AS STATUSCHANGEDBY, LQ.STATUSCHANGEDDATE
		, ISNULL(ICP.COSTPRICEWOT, 0) COSTPRICEWOT, LQ.LIQUIDATIONSALEPRICE - ISNULL(ICP.COSTPRICEWOT, 0) MARGIN
		, CASE WHEN ISNULL(ICP.COSTPRICEWOT, 0) = 0 THEN 100 ELSE CAST((LQ.LIQUIDATIONSALEPRICE - ISNULL(ICP.COSTPRICEWOT, 0)) / ISNULL(LQ.LIQUIDATIONSALEPRICE, 0) AS DECIMAL(5, 2)) END MARGINPER		
	INTO #LQ
	FROM
		LIQUIDATION LQ WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = LQ.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #BRANCH B ON B.Item = LQ.BRANCHID
		INNER JOIN BRANCH BNAME WITH(NOLOCK) ON BNAME.BRANCHID = LQ.BRANCHID
		INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN LIQUIDATIONREASON LR WITH(NOLOCK) ON LR.LIQUIDATIONREASONID = LQ.LIQUIDATIONREASONID
		LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN STOCKMOVE SM WITH(NOLOCK) ON SM.STOCKMOVEID = LQ.STOCKMOVEID 
		LEFT JOIN TBLUSER CUSR WITH(NOLOCK) ON CUSR.USERID = LQ.CREATEDBY
		LEFT JOIN TBLUSER SUSR WITH(NOLOCK) ON SUSR.USERID = LQ.STATUSCHANGEDBY		
		LEFT JOIN ITEMPRICE NIP WITH(NOLOCK) ON NIP.ITEMPRICEID = LQ.NEWITEMPRICEID
		LEFT JOIN ITEMCODE NIC WITH(NOLOCK) ON NIC.ITEMCODEID = NIP.ITEMCODEID
		LEFT JOIN 
			(
				SELECT ICP.ITEMPRICEID, MAX(ICP.ITEMCOSTPRICEID) MAXITEMCOSTPRICEID
				FROM ITEMCOSTPRICE ICP
				WHERE ICP.DELETEDDATE IS NULL AND @ShowCostPrice = 1
				GROUP BY ICP.ITEMPRICEID
			) MAXICP ON MAXICP.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = MAXICP.MAXITEMCOSTPRICEID
		LEFT JOIN REFUNDPATH RP ON RP.REFUNDPATHID = I.REFUNDPATHID
		LEFT JOIN STOCKSUMMARY SSLIQ WITH(NOLOCK) ON SSLIQ.ITEMPRICEID = LQ.NEWITEMPRICEID AND SSLIQ.BRANCHID = LQ.BRANCHID
	WHERE
		LQ.DELETEDDATE IS NULL		
		AND (@ShowAll = 1 OR LQ.STATUS = 0)
		AND LQ.CREATEDDATE > @FromDate AND LQ.CREATEDDATE < @ToDate


	SELECT LQ.ITEMPRICEID, LQ.BRANCHID
	INTO #STOCKNEEDEDPRICES
	FROM #LQ LQ
	WHERE LQ.STATUS = 0 AND @ShowStock = 1
		

	UPDATE LQ
	SET
		STOCK = ISNULL(CASE WHEN ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END, 0)
		, RUNNINGSALE = ISNULL(CASE WHEN ISOPENITEM = 1 THEN BILL.RUNNINGWGHTINKGS ELSE BILL.RUNNINGQTY END, 0)
	FROM
		#LQ LQ
		LEFT JOIN STOCKSUMMARY SS ON SS.BRANCHID = LQ.BRANCHID AND SS.ITEMPRICEID = LQ.ITEMPRICEID AND @ShowStock = 1
		LEFT JOIN
			(
				SELECT PBD.ITEMPRICEID, BC.BRANCHID, SUM(PBD.QUANTITY) RUNNINGQTY, SUM(PBD.WEIGHTINKGS) RUNNINGWGHTINKGS
				FROM 
					POS_BILLDETAIL PBD WITH(NOLOCK)
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN #STOCKNEEDEDPRICES SNP ON SNP.BRANCHID = BC.BRANCHID AND SNP.ITEMPRICEID = PBD.ITEMPRICEID
				WHERE
					@ShowStock = 1
					AND PBD.DELETEDDATE IS NULL
					AND PBD.DAYCLOSUREID IS NULL
				GROUP BY PBD.ITEMPRICEID, BC.BRANCHID
			) BILL ON BILL.ITEMPRICEID = LQ.ITEMPRICEID AND BILL.BRANCHID = LQ.BRANCHID
	WHERE LQ.STATUS = 0


	SELECT * 
	FROM #LQ
	ORDER BY BRANCHNAME, CATEGORYNAME, SUBCATEGORYNAME, ITEMNAME

END
GO
