CREATE   PROC [dbo].[USP_R_LOCATIONDIVISION]
(
	@CategoryID INT = 0
	, @IsMobileCall BIT = 0
)
AS
BEGIN

	IF @IsMobileCall = 1 
	BEGIN
		SELECT 1 AS PARENTID
	END

	SELECT 1 AS PARENTID, * 
	FROM LOCATIONDIVISION 
	WHERE 
		DELETEDDATE IS NULL
		AND (CATEGORYID = @CategoryID OR @CategoryID = 0)
END
