/****** Object:  StoredProcedure [dbo].[USP_R_OFFER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_OFFER]
@BASETYPEID INT = 1
AS              
BEGIN              
              
	SELECT              
		O.OFFERID,
		O.OFFERCODE,
		O.OFFERNAME,
		O.STARTDATE,
		O.ENDDATE,              
		O.OFFERVALUE,
		O.OFFERTYPEID,
		OT.OFFERTYPECODE,  
		OT.OFFERTYPENAME,
		O.CATEGORYID,
		C.CATEGORYNAME,
		CU.FULLNAME AS CREATEDBY,
		O.CREATEDDATE,              
		UU.FULLNAME AS UPDATEDBY,
		O.UPDATEDDATE,              
		DU.FULLNAME AS DELETEDBY,
		O.DELETEDDATE,              
		CASE WHEN O.DELETEDBY IS NULL THEN 'YES' ELSE 'NO' END AS ISACTIVE,
		O.APPLIESTOID as  AppliesToID,          
		ATO.AppliesToName,
		I.SKUCODE,
		IC.ITEMCODE,
		I.ITEMNAME,
		ISNULL(O.NUMBEROFITEMS,0) AS NUMBEROFITEMS,
		O.FREEITEMPRICEID,
		O.BASEOFFERID,
		BB.OFFERNAME AS BONAME,
		O.OFFERTHRESHOLDPRICE,
		IP.MRP,
		ISNULL(O.NUMBEROFFREEITEMS,0) AS NUMBEROFFREEITEMS
	FROM OFFER O              
		LEFT JOIN OFFERTYPE OT ON O.OFFERTYPEID = OT.OFFERTYPEID              
		LEFT JOIN TBLCATEGORY C ON O.CATEGORYID = C.CATEGORYID              
		LEFT JOIN APPLIESTO ATO ON O.APPLIESTOID = ATO.AppliesToID      
		LEFT JOIN ITEMPRICE IP ON IP.ITEMPRICEID = O.FREEITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN TBLUSER CU ON O.CREATEDBY = CU.USERID              
		LEFT JOIN TBLUSER UU ON O.UPDATEDBY = UU.USERID              
		LEFT JOIN TBLUSER DU ON O.DELETEDBY = DU.USERID	
		LEFT JOIN BASEOFFER BB ON O.BASEOFFERID = BB.BASEOFFERID
	WHERE OT.BASETYPE = @BASETYPEID AND (OT.BASETYPE = 2 OR O.CATEGORYID IS NOT NULL)
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_OFFERBRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_OFFERBRANCH]
@OfferID int,
@IsBaseOffer BIT = 0
AS      
BEGIN      
   
   IF @IsBaseOffer = 0
   BEGIN
		SELECT 
			OB.OFFERBRANCHID, B.BRANCHID, B.BRANCHNAME, B.BRANCHCODE, B.PHONENO 
			, CASE WHEN OB.DELETEDBY IS NULL THEN 'YES' ELSE 'NO' END AS ISACTIVE
		FROM OFFERBRANCH OB      
			INNER JOIN BRANCH B ON OB.BRANCHID = B.BRANCHID      
		WHERE OB.OFFERID = @OfferID  
   END
   ELSE
   BEGIN
	   SELECT
			BOB.BASEOFFERBRANCHID AS OFFERBRANCHID, BOB.BRANCHID, BRANCHNAME, BRANCHCODE, PHONENO
			, CASE WHEN BOB.DELETEDBY IS NULL THEN 'Yes' ELSE 'No' END AS ISACTIVE
		FROM BASEOFFERBRANCH BOB
			INNER JOIN BRANCH B ON BOB.BRANCHID = B.BRANCHID
		WHERE BASEOFFERID = @OfferID 
   END
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_OFFERBYBASEOFFER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_R_OFFERBYBASEOFFER]
@BASEOFFERID INT
AS
BEGIN
    SELECT 
        OFR.OFFERID
        , OIM.ITEMCODEID
        , IC.ITEMCODE
        , I.ITEMNAME
        , OFR.OFFERNAME
        , OFR.OFFERCODE
        , OFR.OFFERVALUE
        , OFR.OFFERTYPEID
        , CU.FULLNAME AS CREATEDBY
        , OFR.CREATEDDATE
        , UU.FULLNAME AS UPDATEDBY
        , OFR.UPDATEDDATE
        , DU.FULLNAME AS DELETEDBY
        , OFR.DELETEDDATE
        , IP.ITEMPRICEID
        , IP.MRP
        , IP.SALEPRICE
        , ISNULL(SS.TOTALSTOCK, 0) AS TOTALSTOCK
        , ICPVW.COSTPRICEWOT
        , ICPVW.COSTPRICEWT
        , CAST(CASE 
            WHEN OFR.OFFERTYPEID = 1 THEN IP.MRP - OFR.OFFERVALUE 
            WHEN OFR.OFFERTYPEID = 2 THEN IP.MRP - ((IP.MRP * OFR.OFFERVALUE) / 100.00)
            WHEN OFR.OFFERTYPEID = 3 THEN OFR.OFFERVALUE
            ELSE 0 END AS DECIMAL(15, 2)) FINALPRICE
        , OIM.NUMBEROFPIECES
        , CASE WHEN (OFR.DELETEDDATE IS NULL AND OIM.DELETEDDATE IS NULL AND IP.DELETEDDATE IS NULL) THEN 'YES' ELSE 'NO' END AS ISACTIVE
    FROM OFFER OFR 
        INNER JOIN OFFERITEMMAP OIM ON OFR.OFFERID = OIM.OFFERID
        INNER JOIN ITEMCODE IC ON OIM.ITEMCODEID = IC.ITEMCODEID
        INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
        LEFT JOIN TBLUSER CU ON OFR.CREATEDBY = CU.USERID
        LEFT JOIN TBLUSER UU ON OFR.UPDATEDBY = UU.USERID
        LEFT JOIN TBLUSER DU ON OFR.DELETEDBY = DU.USERID
        LEFT JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
        LEFT JOIN
        (
            SELECT
                ITEMPRICEID
                , SUM(ISNULL(QUANTITY, 0)) AS TOTALSTOCK
            FROM STOCKSUMMARY WITH(NOLOCK)
            GROUP BY ITEMPRICEID
        ) SS ON SS.ITEMPRICEID = IP.ITEMPRICEID
        LEFT JOIN IPICPView ICPVW ON ICPVW.ITEMPRICEID = IP.ITEMPRICEID  
    WHERE BASEOFFERID = @BASEOFFERID 
        --AND OFR.DELETEDDATE IS NULL 
        --AND OIM.DELETEDDATE IS NULL
        --AND IP.DELETEDDATE IS NULL
    ORDER BY OIM.OFFERITEMMAPID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_OFFEREXCLUSION]    Script Date: 17-10-2026 13:04:47 ******/
