CREATE PROCEDURE [dbo].[USP_R_OFFEREXCLUSION]
@OFFERID INT
AS
BEGIN

	SELECT 
		OE.OFFEREXCLUSIONID,
		OE.OFFERID, 
		OE.EXCLUSIONID,
		CASE WHEN OE.ISCATEGORY = 0 THEN  IC.ITEMCODE ELSE CAT.CATEGORYNAME END AS EXCLUSIONCODE,
		CASE WHEN OE.ISCATEGORY = 0 THEN  I.ITEMNAME ELSE CAT.CATEGORYNAME END AS EXCLUSIONNAME,
		CASE WHEN OE.ISCATEGORY = 0 THEN 'ITEM' ELSE 'CATEGORY' END AS EXCLUSIONTYPE,
		CU.FULLNAME AS CREATEDBY,
		OE.CREATEDDATE,
		DU.FULLNAME AS DELETEDBY,
		DU.DELETEDDATE
	FROM OFFEREXCLUSION OE
		LEFT JOIN ITEMCODE IC ON OE.EXCLUSIONID = IC.ITEMCODEID 
		LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON OE.EXCLUSIONID = CAT.CATEGORYID
		INNER JOIN TBLUSER CU ON OE.CREATEDBY = CU.USERID
		LEFT JOIN TBLUSER DU ON OE.DELETEDBY = DU.USERID
	WHERE OFFERID = @OFFERID
		AND OE.DELETEDDATE IS NULL

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_OFFERITEM]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_OFFERITEM]
@OfferID int
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        OI.OFFERITEMMAPID,
        IC.ITEMCODEID,
        TRY_CONVERT(int, JSON_VALUE(OI.OFFERITEMCONFIG, '$.ItemPriceID')) AS ITEMPRICEID,
        ISNULL(TRY_CONVERT(bit, JSON_VALUE(OI.OFFERITEMCONFIG, '$.IsFreeItem')),0) AS IsFreeItem,
        CASE
            WHEN TRY_CONVERT(bit, JSON_VALUE(OI.OFFERITEMCONFIG, '$.IsFreeItem')) = 1
                THEN 'Free Item'
            ELSE 'Buying Item'
        END AS OfferItemType,
        IC.ITEMCODE,
        I.ITEMNAME,
        IC.HSNCODE,
        I.CATEGORYID,
        I.SUBCATEGORYID,
        C.CATEGORYNAME,
        SC.SUBCATEGORYNAME,
        IP.MRP,
        OI.NUMBEROFPIECES,
        CASE JSON_VALUE(OI.OFFERITEMCONFIG, '$.PriceBasedOn')
            WHEN 'MRP' THEN 'MRP'
            WHEN 'SP' THEN 'Sale Price'
            WHEN 'OP' THEN 'Offer Price'
            ELSE NULL
        END AS PriceBasedOnText,
        JSON_VALUE(OI.OFFERITEMCONFIG, '$.PriceBasedOn') AS PriceBasedOn,
        TRY_CONVERT(decimal(18, 2), JSON_VALUE(OI.OFFERITEMCONFIG, '$.OfferPrice')) AS OfferPrice
    FROM OFFERITEMMAP OI
        LEFT JOIN ITEMCODE IC ON OI.ITEMCODEID = IC.ITEMCODEID
        LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID
        LEFT JOIN ITEMPRICE IP 
            ON IP.ITEMPRICEID = TRY_CONVERT(int, JSON_VALUE(OI.OFFERITEMCONFIG, '$.ItemPriceID'))
        LEFT JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
        LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
    WHERE OI.OFFERID = @OfferID
        AND OI.DELETEDDATE IS NULL;
END
GO
