CREATE   PROC [dbo].[USP_R_PICKLIST_TRAYDATA]
(
	@PickListID INT	
)
AS
BEGIN

	SELECT 1 AS PARENTID

	SELECT DISTINCT 1 AS PARENTID, PLT.PICKLISTTRAYID, PLT.TRAYNUMBER
	FROM
		PICKLISTTRAY PLT
		INNER JOIN PICKLISTITEMDETAIL PLID ON PLID.PICKLISTTRAYID = PLT.PICKLISTTRAYID
		INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTITEMID = PLID.PICKLISTITEMID
	WHERE
		PLI.PICKLISTID = @PickListID
		AND PLT.DELETEDDATE IS NULL
		AND PLT.ISDISPATCHED = 0

	SELECT PLT.PICKLISTTRAYID, I.ITEMNAME, IC.ITEMCODE, PLI.MRP
		, CAST(PLID.QUANTITY AS INT) QUANTITY, PLID.PICKLISTITEMDETAILID
	FROM
		PICKLISTTRAY PLT
		INNER JOIN PICKLISTITEMDETAIL PLID ON PLID.PICKLISTTRAYID = PLT.PICKLISTTRAYID
		INNER JOIN PICKLISTITEM PLI ON PLI.PICKLISTITEMID = PLID.PICKLISTITEMID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PLI.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE
		PLI.PICKLISTID = @PickListID
		AND PLT.DELETEDDATE IS NULL
		AND PLT.ISDISPATCHED = 0
		AND PLI.DELETEDDATE IS NULL
		AND PLID.DELETEDDATE IS NULL
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_PICKLISTDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[USP_R_PICKLISTDISPATCH]
(
	@PickListDispatchID INT = NULL
	, @UserID INT = NULL
)
AS
BEGIN

	IF ISNULL(@PickListDispatchID, 0) = 0 
	BEGIN
		SELECT @PickListDispatchID = PLD.PICKLISTDISPATCHID
		FROM
			PICKLISTDISPATCH PLD
		WHERE 
			PLD.DELETEDDATE IS NULL
			AND PLD.STOCKDISPATCHID IS NULL
			AND PLD.CREATEDBY = ISNULL(@UserID, 0)
	END

	IF ISNULL(@PickListDispatchID, 0) = 0 
	BEGIN
		SELECT 'No open picklist found'
		RETURN
	END

	SELECT
		PLD.PICKLISTDISPATCHID, LD.LOCATIONDIVISIONNAME, B.BRANCHNAME, PLD.CREATEDBY, PLD.LOCATIONDIVISIONID, PLD.BRANCHID
	FROM
		PICKLISTDISPATCH PLD
		INNER JOIN LOCATIONDIVISION LD ON LD.LOCATIONDIVISIONID = PLD.LOCATIONDIVISIONID
		INNER JOIN BRANCH B ON B.BRANCHID = PLD.BRANCHID
	WHERE 
		PLD.PICKLISTDISPATCHID = @PickListDispatchID

	SELECT
		ROW_NUMBER() OVER (ORDER BY I.ITEMNAME ASC) AS SNo
		, PLDD.PICKLISTDISPATCHDETAILID, PLDD.PICKLISTDISPATCHID, I.ITEMID, IC.ITEMCODEID
		, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, PLDD.MRP, PLDD.TRAYNUMBER, PLDD.QUANTITY
	FROM
		PICKLISTDISPATCHDETAIL PLDD
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PLDD.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE 
		PLDD.PICKLISTDISPATCHID = @PickListDispatchID
		AND PLDD.DELETEDDATE IS NULL
	ORDER BY I.ITEMNAME


END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_PICKLISTDISPATCHITEM]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[USP_R_PICKLISTDISPATCHITEM]
(
	@ItemCode VARCHAR(20),
	@PicklistDispatchID INT
)
AS
BEGIN

	DECLARE @BranchID INT, @LocationDivisionID INT

	IF NOT EXISTS 
	(
		SELECT 1
		FROM PICKLISTDISPATCH PLD
		WHERE 
			PLD.PICKLISTDISPATCHID = @PicklistDispatchID
			AND PLD.DELETEDDATE IS NULL
			AND PLD.STOCKDISPATCHID IS NULL
	)
	BEGIN
		SELECT 'Picklist dispatch not found\already dispatched or deleted'
		RETURN
	END

	SELECT @BranchID = PLD.BRANCHID, @LocationDivisionID = PLD.LOCATIONDIVISIONID
	FROM PICKLISTDISPATCH PLD
	WHERE PLD.PICKLISTDISPATCHID = @PicklistDispatchID

	SELECT IC.ITEMCODEID, IC.ITEMCODE, PLI.MRP, IC.ITEMID, SUM(PLI.QUANTITY) TOTALPICKLISTQTY, 0 AS ALLOCATEDQTY, 0 AS AVAILABLEQTY
	INTO #PLI
	FROM
		PICKLISTITEM PLI
		INNER JOIN PICKLISTBRANCH PLB ON PLB.PICKLISTBRANCHID = PLI.PICKLISTBRANCHID
		INNER JOIN PICKLIST PL ON PL.PICKLISTID = PLB.PICKLISTID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = PLI.ITEMCODEID
	WHERE
		PLB.BRANCHID = @BranchID
		AND PL.LOCATIONDIVISIONID = @LocationDivisionID
		AND PL.DELETEDDATE IS NULL
		AND PLB.DELETEDDATE IS NULL
		AND PLI.DELETEDDATE IS NULL
		AND PLB.PICKEDSTATUS = 19 --Seggregated
		AND IC.ITEMCODE = @ItemCode
	GROUP BY IC.ITEMCODEID, IC.ITEMCODE, PLI.MRP, IC.ITEMID


	IF NOT EXISTS ( SELECT 1 FROM #PLI )
	BEGIN
		SELECT 'Item code not found in all open picklists'
		RETURN
	END

	UPDATE PLI
	SET ALLOCATEDQTY = ISNULL(AQ.ALLOCATEDQTY, 0)
		, AVAILABLEQTY = TOTALPICKLISTQTY - ISNULL(AQ.ALLOCATEDQTY, 0)
	FROM
		#PLI PLI
		LEFT JOIN
			(
				SELECT PLDD.ITEMCODEID, PLDD.MRP, SUM(PLDD.QUANTITY) ALLOCATEDQTY
				FROM
					PICKLISTDISPATCHDETAIL PLDD
					INNER JOIN PICKLISTDISPATCH PLD ON PLD.PICKLISTDISPATCHID = PLDD.PICKLISTDISPATCHID
				WHERE
					PLD.BRANCHID = @BranchID
					AND PLD.LOCATIONDIVISIONID = @LocationDivisionID
					AND PLDD.DELETEDDATE IS NULL
					AND PLD.DELETEDDATE IS NULL
					AND PLD.STOCKDISPATCHID IS NULL
				GROUP BY PLDD.ITEMCODEID, PLDD.MRP
			) AQ ON AQ.ITEMCODEID = PLI.ITEMCODEID AND AQ.MRP = PLI.MRP

	SELECT 1 AS PARENTID

	SELECT 1 AS PARENTID, PLI.*, I.SKUCODE, I.ITEMNAME
	FROM 
		#PLI PLI
		INNER JOIN ITEM I ON I.ITEMID = PLI.ITEMID

END
GO
