/****** Object:  StoredProcedure [dbo].[USP_R_SC_GetCountedCategories]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_R_SC_GetCountedCategories]
(
	@BRANCHID INT
)
AS
BEGIN

	CREATE TABLE #CATEGORIES(CATEGORYID INT, CATEGORYNAME VARCHAR(100), SUBCATEGORYID INT, SUBCATEGORYNAME VARCHAR(100), INCOUNTING BIT, INCLUDEINACCEPT BIT)

	INSERT INTO #CATEGORIES
	SELECT DISTINCT I.CATEGORYID, CAT.CATEGORYNAME, I.SUBCATEGORYID, SCAT.SUBCATEGORYNAME, 1, 1
	FROM   
		STOCKCOUNTINGDETAIL SCD  
		INNER JOIN STOCKCOUNTING SC ON SCD.STOCKCOUNTINGID = SC .STOCKCOUNTINGID   
			AND SC.BRANCHID = @BRANCHID  
			AND ISNULL(SC.STATUS, 0) = 1  
		INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID  
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID  
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID  
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT ON SCAT.SUBCATEGORYID = I.SUBCATEGORYID
	WHERE SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL  
	GROUP BY I.CATEGORYID, CAT.CATEGORYNAME ,I.SUBCATEGORYID, SCAT.SUBCATEGORYNAME
	HAVING SUM(SCD.QUANTITY) <> 0 OR SUM(SCD.WEIGHTINKGS) <> 0  

	INSERT INTO #CATEGORIES
	SELECT CAT.CATEGORYID, CAT.CATEGORYNAME,SCAT.SUBCATEGORYID, SCAT.SUBCATEGORYNAME, 0, 0
	FROM TBLCATEGORY CAT
	INNER JOIN SUBCATEGORY SCAT ON CAT.CATEGORYID = SCAT.CATEGORYID
	WHERE CAT.DELETEDDATE IS NULL
		AND SCAT.DELETEDDATE IS NULL
		AND NOT EXISTS
			(
				SELECT 1 FROM #CATEGORIES LCAT WHERE LCAT.CATEGORYID = CAT.CATEGORYID AND LCAT.SUBCATEGORYID = SCAT.SUBCATEGORYID
			)

	SELECT * FROM #CATEGORIES ORDER BY CATEGORYNAME ASC , SUBCATEGORYNAME ASC
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SD_EMPTYTRAYS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SD_EMPTYTRAYS]
@STOCKDISPATCHID INT
AS
BEGIN

	DECLARE @CATEGORYID INT, @BRANCHID INT
	
	SELECT @CATEGORYID = CATEGORYID, @BRANCHID = TOBRANCHID 
	FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	SELECT @STOCKDISPATCHID AS STOCKDISPATCHID

	SELECT 
		TI.STOCKDISPATCHID,
		TI.TRAYINFOID,
		TI.TRAYNUMBER
	FROM TRAYINFO TI 
		INNER JOIN 
		(
			SELECT SDD.TRAYINFOID, COUNT(*) AS ITEMCOUNT FROM STOCKDISPATCHDETAIL SDD 
				INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID 
			WHERE SD.TOBRANCHID = @BRANCHID 
				AND SD.CATEGORYID = @CATEGORYID 
				AND SD.DELETEDDATE IS NULL 
				AND SDD.DELETEDDATE IS NULL
			GROUP BY SDD.TRAYINFOID
		) SDD ON TI.TRAYINFOID = SDD.TRAYINFOID
	WHERE TI.STOCKDISPATCHID = @STOCKDISPATCHID
		AND TI.DELETEDDATE IS NULL

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SD_TRAYINFO]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SD_TRAYINFO]
@STOCKDISPATCHID INT
AS
BEGIN

	DECLARE @CATEGORYID INT, @BRANCHID INT
	
	SELECT @CATEGORYID = CATEGORYID, @BRANCHID = TOBRANCHID 
	FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	SELECT @STOCKDISPATCHID AS STOCKDISPATCHID

	SELECT 
		TI.STOCKDISPATCHID,
		TI.TRAYINFOID,
		TI.TRAYNUMBER,
		ISNULL(SDD.ITEMCOUNT,0) AS ITEMCOUNT,
		CASE WHEN TI.ISACCEPTED = 0 THEN 'No' ELSE 'Yes' END AS ISVERIFIED
	FROM TRAYINFO TI 
		LEFT JOIN 
		(
			SELECT SDD.TRAYINFOID, COUNT(*) AS ITEMCOUNT FROM STOCKDISPATCHDETAIL SDD 
				INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID 
			WHERE SD.TOBRANCHID = @BRANCHID 
				AND SD.CATEGORYID = @CATEGORYID 
				AND SD.DELETEDDATE IS NULL 
				AND SDD.DELETEDDATE IS NULL
			GROUP BY SDD.TRAYINFOID
		) SDD ON TI.TRAYINFOID = SDD.TRAYINFOID
	WHERE TI.STOCKDISPATCHID = @STOCKDISPATCHID
		AND TI.DELETEDDATE IS NULL

END
