/****** Object:  StoredProcedure [dbo].[USP_R_SKUSTOCKBYMRP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_R_SKUSTOCKBYMRP]
(
	@BranchID INT
	, @ItemID INT
)
AS
BEGIN

	SELECT 
		IC.ITEMCODEID, IP.ITEMPRICEID, SS.STOCKSUMMARYID, IC.ITEMCODE, IP.MRP, IP.SALEPRICE, IP.CREATEDDATE, IP.DELETEDDATE
		, CASE WHEN I.ISOPENITEM = 1 THEN STKDIS.DISPATCHWEIGHTINKGS ELSE STKDIS.DISPATCHQUANTITY END AS INTRANSITSTOCK 
		, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS SYSTEMSTOCK 
		, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS PHYSICALSTOCK 
		, GST.GSTCODE
	FROM
		STOCKSUMMARY SS
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		LEFT JOIN 
			(
				SELECT SDD.ITEMPRICEID, SUM(SDD.DISPATCHQUANTITY) DISPATCHQUANTITY, SUM(SDD.WEIGHTINKGS) DISPATCHWEIGHTINKGS
				FROM
					STOCKDISPATCH SD
					INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
				WHERE 
					ISNULL(SD.STATUS, 0) = 1
					AND SD.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
					AND SD.TOBRANCHID = @BranchID
				GROUP BY SDD.ITEMPRICEID
			) STKDIS ON STKDIS.ITEMPRICEID = SS.ITEMPRICEID
	WHERE
		SS.BRANCHID = @BranchID
		AND IC.ITEMID = @ItemID
		AND (IP.DELETEDDATE IS NULL OR (CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) <> 0)
	ORDER BY IC.ITEMCODE, IP.CREATEDDATE DESC

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SLICECOUNTING_ITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_R_SLICECOUNTING_ITEMS]
(
	@BranchIDs VARCHAR(MAX)
	, @SelectedCriteria VARCHAR(200)
	, @SaleDays INT = 0
)
AS
BEGIN

	DECLARE @BranchCount INT

	SELECT * INTO #BRANCH FROM DBO.SplitString(@BranchIDs, ',')
	SELECT @BranchCount = COUNT(1) FROM #BRANCH
	
	IF @SelectedCriteria = 'Top selling items'
	BEGIN

		IF @SaleDays <= 0
		BEGIN
			RAISERROR('No of sale days cannot be less than or equal to zero', 16, 1)
			RETURN
		END

		DECLARE @FromDate DATE 
		SELECT @FromDate = DATEADD(d, - @SaleDays, GETDATE())

		SELECT 
			BC.BRANCHID, IC.ITEMID, CASE WHEN I.ISOPENITEM = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END AS SALEQTYORWGHTINKGS
		INTO #SALE
		FROM
			POS_BILL PB WITH(NOLOCK)
			INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN #BRANCH B ON B.Item = BC.BRANCHID
		WHERE
			PBD.DELETEDDATE IS NULL 
			AND PBD.CREATEDDATE > @FromDate
			AND PB.BILLSTATUS = 1
		GROUP BY BC.BRANCHID, IC.ITEMID, I.ISOPENITEM

		SELECT 
			SALE.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
			, CAST(ROUND(AVG(SALE.SALEQTYORWGHTINKGS), 2) AS DECIMAL(18, 2))  AS SALEAVG
		FROM
			#SALE SALE
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SALE.ITEMID
			INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
			LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
			LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION ISUBCLS WITH(NOLOCK) ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		GROUP BY 
			SALE.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
		ORDER BY SALEAVG DESC

		SELECT SALE.ITEMID, B.BRANCHNAME, SALE.SALEQTYORWGHTINKGS
		FROM
			#SALE SALE
			INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SALE.BRANCHID
	END

	ELSE IF @SelectedCriteria = 'High quantity'
	BEGIN
		
		SELECT 
			SS.BRANCHID, IC.ITEMID, CASE WHEN I.ISOPENITEM = 1 THEN SUM(SS.WEIGHTINKGS) ELSE SUM(SS.QUANTITY) END AS STOCKQTYORWGHTINKGS
		INTO #SSHQ
		FROM
			STOCKSUMMARY SS WITH(NOLOCK)
			INNER JOIN #BRANCH B WITH(NOLOCK) ON B.Item = SS.BRANCHID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		WHERE IP.DELETEDDATE IS NULL AND IC.DELETEDDATE IS NULL
		GROUP BY SS.BRANCHID, IC.ITEMID, I.ISOPENITEM

		DELETE FROM #SSHQ WHERE STOCKQTYORWGHTINKGS <= 0

		SELECT 
			SS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
			, CAST(ROUND(AVG(SS.STOCKQTYORWGHTINKGS), 2) AS DECIMAL(18, 2))  AS STOCKAVG
		FROM
			#SSHQ SS
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SS.ITEMID
			INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
			LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
			LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION ISUBCLS WITH(NOLOCK) ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		GROUP BY 
			SS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
		ORDER BY STOCKAVG DESC

		SELECT SS.ITEMID, B.BRANCHNAME, SS.STOCKQTYORWGHTINKGS
		FROM
			#SSHQ SS
			INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID
	END
	
	ELSE IF @SelectedCriteria = 'High value items'
	BEGIN
		
		SELECT 
			SS.BRANCHID, IC.ITEMID, CASE WHEN I.ISOPENITEM = 1 THEN SUM(SS.WEIGHTINKGS) ELSE SUM(SS.QUANTITY) END AS STOCKQTYORWGHTINKGS
			, CASE WHEN I.ISOPENITEM = 1 THEN SUM(SS.WEIGHTINKGS * IP.MRP) ELSE SUM(SS.QUANTITY * IP.MRP) END AS STOCKVALUE
		INTO #SSHV
		FROM
			STOCKSUMMARY SS WITH(NOLOCK)
			INNER JOIN #BRANCH B WITH(NOLOCK) ON B.Item = SS.BRANCHID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		WHERE IP.DELETEDDATE IS NULL AND IC.DELETEDDATE IS NULL
		GROUP BY SS.BRANCHID, IC.ITEMID, I.ISOPENITEM

		DELETE FROM #SSHV WHERE STOCKQTYORWGHTINKGS <= 0

		SELECT 
			SS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
			, SUM(SS.STOCKQTYORWGHTINKGS) STOCKQTYORWGHTINKGS, CAST(ROUND(AVG(SS.STOCKVALUE), 2) AS DECIMAL(18, 2)) AS STOCKVALUEAVG
		FROM
			#SSHV SS
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SS.ITEMID
			INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
			LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
			LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION ISUBCLS WITH(NOLOCK) ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		GROUP BY 
			SS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
		ORDER BY STOCKVALUEAVG DESC

		SELECT SS.ITEMID, B.BRANCHNAME, SS.STOCKQTYORWGHTINKGS, SS.STOCKVALUE
		FROM
			#SSHV SS
			INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID

	END

	ELSE IF @SelectedCriteria = 'Negatives'
	BEGIN
		
		SELECT 
			SS.BRANCHID, IC.ITEMID, IP.MRP, IP.SALEPRICE, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS STOCKQTYORWGHTINKGS			
		INTO #SSNG
		FROM
			STOCKSUMMARY SS WITH(NOLOCK)
			INNER JOIN #BRANCH B WITH(NOLOCK) ON B.Item = SS.BRANCHID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID		
		WHERE 
			 IP.DELETEDDATE IS NULL 
			 AND IC.DELETEDDATE IS NULL
			 AND EXISTS 
				(
					SELECT 1 
					FROM 
						STOCKSUMMARY SSINNER WITH(NOLOCK) 
						INNER JOIN #BRANCH B WITH(NOLOCK) ON B.Item = SSINNER.BRANCHID
						INNER JOIN ITEMPRICE IPINNER WITH(NOLOCK) ON IPINNER.ITEMPRICEID = SSINNER.ITEMPRICEID
						INNER JOIN ITEMCODE ICINNER WITH(NOLOCK) ON ICINNER.ITEMCODEID = IPINNER.ITEMCODEID
					WHERE
						ICINNER.ITEMID = I.ITEMID						
						AND CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END < 0
				)		

		SELECT 
			SS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
			, SUM(SS.STOCKQTYORWGHTINKGS) STOCKQTYORWGHTINKGS
		FROM
			#SSNG SS
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SS.ITEMID
			INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
			LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
			LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION ISUBCLS WITH(NOLOCK) ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		GROUP BY 
			SS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME
		ORDER BY STOCKQTYORWGHTINKGS

		SELECT SS.ITEMID, B.BRANCHNAME, SS.MRP, SS.SALEPRICE, SS.STOCKQTYORWGHTINKGS
		FROM
			#SSNG SS
			INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID

	END

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SR_CN_MAPPINGVALUES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SR_CN_MAPPINGVALUES]
@SUPPLIERRETURNSID INT,
@CREDITNOTEID  INT = 0
AS
BEGIN

	DECLARE @SupplierId INT;
    DECLARE @ExistingStatus INT;

	SELECT 
        @SupplierId = SupplierId,
        @ExistingStatus = STATUS
    FROM SUPPLIERRETURNS
    WHERE SUPPLIERRETURNSID = @SupplierReturnsID;

	IF @ExistingStatus = 3
	BEGIN
		RAISERROR ('Debit note already closed',16,1)
		RETURN;
	END

    IF @SupplierId IS NULL
    BEGIN
        RAISERROR ('Invalid Supplier Returns reference', 16, 1);
        RETURN;
    END

	IF(@CREDITNOTEID <> 0)
	BEGIN
		IF NOT EXISTS (
				SELECT 1
				FROM CreditNote
				WHERE CreditNoteId = @CreditNoteId
					AND SupplierId = @SupplierId
					AND DeletedDate IS NULL
			)
			BEGIN
				RAISERROR ('Selected Credit Note does not belong to this supplier', 16, 1);
				RETURN;
			END

			IF NOT EXISTS
			(
				SELECT 1
				FROM CreditNote cn
				WHERE cn.CreditNoteId = @CREDITNOTEID
				AND cn.CreditValue >
					ISNULL(
						(
							SELECT SUM(MappedReturnValue)
							FROM SUPPLIERRETURNSCREDITNOTEMAP
							WHERE CREDITNOTEID = cn.CreditNoteId
							AND DELETEDDATE IS NULL
						),0
					)
			)
			BEGIN
				RAISERROR ('Selected Credit Note has no balance value available for mapping',16,1)
				RETURN
			END
	END

	DECLARE 
		@TOTALDNVALUE DECIMAL(18,2) = 0, 
		@MAPPEDDNVALUE DECIMAL(18,2) = 0,
		@BALANCEDNVALUETOBEMAPPED DECIMAL(18,2) =0,
		
		@TOTALCNVALUE DECIMAL(18,2) = 0,
		@MAPPEDCNVALUE DECIMAL(18,2) = 0,
		@BALANCECNVALUECANBEMAPPED DECIMAL(18,2) = 0

	SELECT @TOTALDNVALUE = ISNULL(SUM(ICP.COSTPRICEWT * CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY ELSE SRD.WEIGHTINKGS END),0)
        FROM SUPPLIERRETURNSDETAIL SRD
        INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
        WHERE SRD.SUPPLIERRETURNSID = @SUPPLIERRETURNSID AND SRD.DELETEDDATE IS NULL
        GROUP BY SUPPLIERRETURNSID
	
	SELECT @MAPPEDDNVALUE = ISNULL(SUM(MappedReturnValue),0) FROM SUPPLIERRETURNSCREDITNOTEMAP WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID AND DELETEDDATE IS NULL

	SET @BALANCEDNVALUETOBEMAPPED = @TOTALDNVALUE - @MAPPEDDNVALUE
	
	SELECT @TOTALCNVALUE = CreditValue FROM CreditNote WHERE CreditNoteId = @CREDITNOTEID

	SELECT @MAPPEDCNVALUE = ISNULL(SUM(MappedReturnValue),0) FROM SUPPLIERRETURNSCREDITNOTEMAP WHERE CREDITNOTEID = @CREDITNOTEID AND DELETEDDATE IS NULL
	
	SET @BALANCECNVALUECANBEMAPPED = @TOTALCNVALUE - @MAPPEDCNVALUE

	SELECT 
		@TOTALDNVALUE AS TOTALDNVALUE, 
		@MAPPEDDNVALUE AS MAPPEDDNVALUE,
		@BALANCEDNVALUETOBEMAPPED AS BALANCEDNVALUETOBEMAPPED,
		@TOTALCNVALUE AS TOTALCNVALUE,
		@MAPPEDCNVALUE AS MAPPEDCNVALUE,
		@BALANCECNVALUECANBEMAPPED AS BALANCECNVALUECANBEMAPPED
END
GO
