CREATE PROCEDURE [dbo].[USP_R_STOCKCONTINGNOTENTERED]  
@BRANCHID INT  
AS  
BEGIN  


	SELECT DISTINCT I.CATEGORYID  
	INTO #Categories  
	FROM   
		STOCKCOUNTINGDETAIL SCD WITH(NOLOCK) 
		INNER JOIN STOCKCOUNTING SC WITH(NOLOCK) ON SCD.STOCKCOUNTINGID = SC .STOCKCOUNTINGID   
			AND SC.BRANCHID = @BRANCHID  
			AND ISNULL(SC.STATUS, 0) = 1  
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON SCD.ITEMPRICEID = IP.ITEMPRICEID  
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID  
		INNER JOIN ITEM I WITH(NOLOCK) ON IC.ITEMID = I.ITEMID  
	WHERE SCD.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL  
	GROUP BY I.CATEGORYID  
	HAVING SUM(SCD.QUANTITY) <> 0 OR SUM(SCD.WEIGHTINKGS) <> 0  

	SELECT I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, C.CATEGORYNAME, SCAT.SUBCATEGORYNAME, IP.SALEPRICE, IP.MRP, 0 AS PHYSICALSTOCK
		, SS.QUANTITY SYSTEMSTOCK, SS.QUANTITY * -1 AS STOCKDIFF, ISNULL(ICPVW.COSTPRICEWT, 0) COSTPRICEWT
	FROM
		STOCKSUMMARY SS WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID	
		INNER JOIN TBLCATEGORY C WITH(NOLOCK) ON I.CATEGORYID = C.CATEGORYID  
		INNER JOIN #Categories CA WITH(NOLOCK) ON CA.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT WITH(NOLOCK) ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
		LEFT JOIN ITEMCOSTPRICEVIEW ICPVW WITH(NOLOCK) ON ICPVW.ITEMCODEID = IC.ITEMCODEID
	WHERE
		SS.QUANTITY != 0
		AND IP.DELETEDDATE IS NULL
		AND IC.DELETEDDATE IS NULL
		AND NOT EXISTS 
			(
				SELECT 1 
				FROM 
					STOCKCOUNTINGDETAIL SED WITH(NOLOCK) 
					INNER JOIN STOCKCOUNTING SC WITH(NOLOCK) ON SC.STOCKCOUNTINGID = SED.STOCKCOUNTINGID  
					INNER JOIN ITEMPRICE IPINNER WITH(NOLOCK) ON SED.ITEMPRICEID = IPINNER.ITEMPRICEID
				WHERE SC.BRANCHID = @BRANCHID 
					AND ((ISNULL(STATUS,0) = 0 OR ISNULL(STATUS,0) = 1))
					AND IPINNER.ITEMPRICEID = IP.ITEMPRICEID
					AND SED.DELETEDDATE IS NULL AND SC.DELETEDDATE IS NULL
			)
		AND SS.BRANCHID = @BRANCHID	
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKCOUNTING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_STOCKCOUNTING]             
@BRANCHID INT = 0                
AS                
BEGIN                
                
	SELECT 
		SCL.STOCKLOCATIONID,
		SC.STOCKCOUNTINGID,
		SC.STOCKCOUNTINGID AS [Counting Sheet #], 
		SCL.STOCKLOCATIONNAME AS [Stock Location],
		CU.FULLNAME AS CREATEDBY,                
		SC.CREATEDDATE,                
		UU.FULLNAME AS SubmittedBy,                
		SC.UPDATEDDATE SubmittedDate,                
		CASE WHEN ISNULL(SC.STATUS,0) = 0 THEN 'Draft'                
		WHEN  ISNULL(SC.STATUS,0) = 1 then 'Submitted'     
		WHEN  ISNULL(SC.STATUS,0) = 2 then 'Accepted' 
		WHEN  ISNULL(SC.STATUS,0) = 3 then 'Archived' END AS STATUS,
		ACU.FULLNAME AS ACCEPTEDBY,
		SC.STOCKACCEPTEDDATE,
		ARU.FULLNAME AS ArchivedBy,
		SC.ArchivedDate
	FROM STOCKCOUNTING SC                
		LEFT JOIN STOCKLOCATION SCL ON SC.STOCKLOCATIONID = SCL.STOCKLOCATIONID AND SC.BRANCHID = SCL.BRANCHID
		left JOIN TBLUSER CU ON SC.CREATEDBY = CU.USERID                
		left JOIN TBLUSER UU ON SC.UPDATEDBY = UU.USERID                
		LEFT JOIN TBLUSER ACU ON SC.ACCEPTEDBY = ACU.USERID
		LEFT JOIN TBLUSER ARU ON SC.ArchivedBy = ARU.USERID
	WHERE SC.BRANCHID = @BRANCHID	
		AND SC.DELETEDDATE IS NULL
	ORDER BY ISNULL(SC.UPDATEDDATE, SC.CREATEDDATE) DESC
                
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKCOUNTINGDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
