CREATE PROCEDURE [dbo].[USP_R_STOCKCOUNTINGDETAIL]        
@STOCKCOUNTINGID INT        
AS        
BEGIN        
        
SELECT I.ITEMID, I.SKUCODE, STOCKCOUNTINGDETAILID,SCD.ITEMPRICEID ,      
IC.ITEMCODE,I.ITEMNAME,IP.MRP,SCD.QUANTITY, SCD.WEIGHTINKGS,
C.CATEGORYNAME,SC.SUBCATEGORYNAME
FROM STOCKCOUNTINGDETAIL SCD        
INNER JOIN ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID        
INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID        
INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID        
INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID      
left JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID      
where SCD.STOCKCOUNTINGID = @STOCKCOUNTINGID    
and SCD.DELETEDDATE is null  
     
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKDISPATCHDC]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_STOCKDISPATCHDC]                  
@DISPATCHDCID INT                  
AS                  
BEGIN   

	DECLARE @CreatedDate DATETIME 

	SELECT @CreatedDate = DD.CREATEDDATE              
	FROM DISPATCHDC DD		       
	WHERE DISPATCHDCID = @DISPATCHDCID  
            
	SELECT                 
		DD.DISPATCHDCID,                
		DD.DISPATCHDCNUMBER,                
		B.BRANCHNAME AS TOBRANCHNAME,            
		B.ADDRESS AS TOADDRESS,            
		B.PHONENO AS TOPHONENO,            
		TS.STATENAME AS TOSTATENAME,            
		FB.BRANCHNAME AS FROMBRANCHNAME,            
		FB.ADDRESS AS FROMADDRESS,            
		FB.PHONENO AS FROMPHONENO,            
		FS.STATENAME AS FROMSTATENAME,            
		C.CATEGORYNAME,                
		U.FULLNAME AS CREATEDBY,                
		DD.CREATEDDATE                
	FROM 
		DISPATCHDC DD                
		LEFT JOIN BRANCH B ON DD.BRANCHID = B.BRANCHID            
		LEFT JOIN BRANCH FB ON DD.FROMBRANCHID = FB.BRANCHID            
		LEFT JOIN TBLCATEGORY C ON DD.CATEGORYID = C.CATEGORYID                
		LEFT JOIN TBLUSER U ON DD.CREATEDBY = U.USERID                
		LEFT JOIN TBLSTATE TS ON B.STATEID = TS.STATEID            
		LEFT JOIN TBLSTATE FS ON FS.STATEID = TS.STATEID            
	WHERE DISPATCHDCID = @DISPATCHDCID                
                
	SELECT          
		ROW_NUMBER() OVER(ORDER BY SDD.STOCKDISPATCHID,SDD.STOCKDISPATCHDETAILID DESC) AS Sno          
		, IC.ITEMCODE, I.ITEMNAME, IC.HSNCODE, SDD.DISPATCHQUANTITY, SDD.WEIGHTINKGS, LEN(GSTCODE) GSTLEN,      
		G.GSTCODE, 
		CAST(ROUND(ISNULL(PICP.COSTPRICEWOT * UOM.MULTIPLIER, ICP.AVGCOSTPRICEWOT) * (CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END), 2) AS DECIMAL(18, 2)) as COSTPRICEWOT,                
		0.00 as CGST,                
		0.00 as SGST,
		0.00 IGST,
		0.00 as CESS,                
		CAST(ROUND(ISNULL(PICP.COSTPRICEWOT * UOM.MULTIPLIER, ICP.AVGCOSTPRICEWOT) * (CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END), 2) AS DECIMAL(18, 2)) as COSTPRICE
		, IP.MRP, IP.SALEPRICE   
	FROM 
		STOCKDISPATCHDETAIL SDD              
		INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID                
		INNER JOIN GSTDETAIL G ON IP.GSTID = G.GSTID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID                
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN UOM UOM ON UOM.UOMID = I.UOMID
		LEFT JOIN
			(
				SELECT ITEMPRICEID
					, SUM(COSTPRICEWT * QUANTITY) / SUM(QUANTITY) AS AVGCOSTPRICEWT                
					, SUM(COSTPRICEWOT * QUANTITY) / SUM(QUANTITY) AS AVGCOSTPRICEWOT                
				FROM ITEMCOSTPRICE WHERE DELETEDDATE IS NULL
				GROUP BY ITEMPRICEID
				HAVING SUM(QUANTITY) > 0
			) AS ICP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		LEFT JOIN
			(
				SELECT MAX(PICP.ITEMCOSTPRICEID) MAXITEMCOSTPRICEID, I.ITEMID
				FROM 
					ITEM I 
					INNER JOIN ITEMCODE PIC ON PIC.ITEMID = I.PARENTITEMID
					INNER JOIN ITEMPRICE PIP ON PIP.ITEMCODEID = PIC.ITEMCODEID
					INNER JOIN ITEMCOSTPRICE PICP ON PICP.ITEMPRICEID = PIP.ITEMPRICEID
				WHERE
					PIP.DELETEDDATE IS NULL
					AND PICP.DELETEDDATE IS NULL
					AND PICP.CREATEDDATE < @CreatedDate
				GROUP BY I.ITEMID
			) PICPMAX ON PICPMAX.ITEMID = I.ITEMID
		LEFT JOIN ITEMCOSTPRICE PICP ON PICP.ITEMCOSTPRICEID = PICPMAX.MAXITEMCOSTPRICEID
	WHERE 
		EXISTS
			(
				SELECT STOCKDISPATCHID FROM DISPATCHDCMAPPING DDM                 
				WHERE SDD.STOCKDISPATCHID = DDM.STOCKDISPATCHID                
				AND DISPATCHDCID = @DISPATCHDCID
			)                
	AND SDD.DELETEDDATE IS NULL  

	SELECT   
		G.GSTCODE              
		, CAST(ROUND(SUM(ISNULL(PICP.COSTPRICEWOT * UOM.MULTIPLIER, ICP.AVGCOSTPRICE) * (CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END)), 2) AS DECIMAL(18, 2)) as TAXAMOUNT             
	FROM 
		STOCKDISPATCHDETAIL SDD              
		INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID                
		INNER JOIN GSTDETAIL G ON IP.GSTID = G.GSTID 
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID                
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID    
		LEFT JOIN UOM UOM ON UOM.UOMID = I.UOMID
		LEFT JOIN
			(
				SELECT ITEMPRICEID,SUM(COSTPRICEWT * QUANTITY)/SUM(QUANTITY) AS AVGCOSTPRICE                 
				FROM ITEMCOSTPRICE WHERE DELETEDDATE IS NULL
				GROUP BY ITEMPRICEID
				HAVING SUM(QUANTITY) > 0
			) AS ICP ON IP.ITEMPRICEID = ICP.ITEMPRICEID      
		LEFT JOIN
			(
				SELECT MAX(PICP.ITEMCOSTPRICEID) MAXITEMCOSTPRICEID, I.ITEMID
				FROM 
					ITEM I 
					INNER JOIN ITEMCODE PIC ON PIC.ITEMID = I.PARENTITEMID
					INNER JOIN ITEMPRICE PIP ON PIP.ITEMCODEID = PIC.ITEMCODEID
					INNER JOIN ITEMCOSTPRICE PICP ON PICP.ITEMPRICEID = PIP.ITEMPRICEID
				WHERE
					PIP.DELETEDDATE IS NULL
					AND PICP.DELETEDDATE IS NULL
					AND PICP.CREATEDDATE < @CreatedDate
				GROUP BY I.ITEMID
			) PICPMAX ON PICPMAX.ITEMID = I.ITEMID
		LEFT JOIN ITEMCOSTPRICE PICP ON PICP.ITEMCOSTPRICEID = PICPMAX.MAXITEMCOSTPRICEID
	WHERE 
		EXISTS
			(
				SELECT STOCKDISPATCHID 
				FROM DISPATCHDCMAPPING DDM                 
				WHERE 
					SDD.STOCKDISPATCHID = DDM.STOCKDISPATCHID                
					AND DISPATCHDCID = @DISPATCHDCID
			)                
		AND SDD.DELETEDDATE IS NULL  
	GROUP BY G.GSTCODE  
                
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKENTRY_FOR_PICKLIST_GENERATION]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE   PROC [dbo].[USP_R_STOCKENTRY_FOR_PICKLIST_GENERATION]
(
	@CategoryID INT,
	@SupplierID INT
)
AS
BEGIN

	SELECT SE.STOCKENTRYID, SE.SUPPLIERINVOICENO, SE.INVOICEDATE, CU.FULLNAME AS CREATEDBY, SE.CREATEDDATE
	FROM 
		STOCKENTRY SE 
		INNER JOIN SUPPLIERINDENT SI ON SI.SUPPLIERINDENTID = SE.SUPPLIERINDENTID 
		INNER JOIN ENUMLIST EL ON EL.ENUMID = SI.SUPPLIERITEMINDENTTYPEID
		LEFT JOIN TBLUSER CU ON CU.USERID = SE.CREATEDBY
	WHERE 
		EL.ENUMVALUE = 'Flow Through'
		AND SE.DELETEDDATE IS NULL
		AND SE.CATEGORYID = @CategoryID
		AND SE.SUPPLIERID = @SupplierID
		AND SE.PICKLISTID IS NULL
	
END

GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKENTRY_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_STOCKENTRY_v2]                        
@STOCKENTRYID INT,
@IsDraft BIT = 0
AS                        
BEGIN                        
              
	DECLARE @FinalPriceSUM DECIMAL(18, 2), @CreditValue DECIMAL(18, 2)
	SELECT 
		@FinalPriceSUM = ISNULL(SUM(FINALPRICE),0) 
	FROM STOCKENTRYDETAIL 
	WHERE STOCKENTRYID = @STOCKENTRYID                  
		AND DELETEDDATE IS NULL

	SELECT 
		@CreditValue = ISNULL(SUM(MappedReturnValue),0) 
	FROM STOCKENTRYCREDITNOTEMAP
	WHERE STOCKENTRYID = @STOCKENTRYID
		AND DELETEDDATE IS NULL
              
	SELECT 
		SE.STOCKENTRYID,SE.SUPPLIERID,SE.SUPPLIERINVOICENO,S.GSTIN AS SUPPLIERGSTIN,
		CASE WHEN SE.TAXINCLUSIVE = 0 THEN 'NO' ELSE 'YES' END AS TAXINCLUSIVE,        
		SE.TAXINCLUSIVE AS TAXINCLUSIVEVALUE,SE.CATEGORYID,S.DEALERNAME,  S.DEALERNAME AS SUPPLIERNAME,
		S.GSTIN,C.CATEGORYNAME,CU.FULLNAME AS CREATEDBY,SE.CREATEDDATE,
		SE.INVOICEDATE,ISNULL(SE.TCS,0) AS TCS,ISNULL(SE.DISCOUNT,0) AS DISCOUNT,ISNULL(SE.EXPENSES,0) AS EXPENSES,
		ISNULL(SE.TRANSPORT,0) AS TRANSPORT,ISNULL(SE.PackingCharges,0) AS PackingCharges,
		@CreditValue AS CreditValue, ISNULL(SE.Notes, '') AS Notes,
		@FinalPriceSUM AS FINALPRICE,
		CASE WHEN SE.Reverted_Date IS NOT NULL then 'Reverted' ELSE 'Submitted' end AS Status_text,
		SOURCEBRANCHID, SI.SUPPLIERINDENTID, SI.SUPPLIERINDENTNO,
		InvoiceType, PriceEntryMethod, LorryFrightMode
	FROM STOCKENTRY SE                        
		LEFT JOIN SUPPLIERINDENT SI ON SE.SUPPLIERINDENTID = SI.SUPPLIERINDENTID
		LEFT JOIN TBLDEALER S ON SE.SUPPLIERID = S.DEALERID                      
		LEFT JOIN TBLCATEGORY C ON SE.CATEGORYID = C.CATEGORYID                        
		LEFT JOIN TBLUSER CU ON SE.CREATEDBY = CU.USERID                        
	WHERE STOCKENTRYID = @STOCKENTRYID                        
	AND (@IsDraft = 1 OR ISNULL(SE.STATUS,0) = 1 OR SE.STATUS = 2)
            
	SELECT  ROW_NUMBER() OVER (ORDER BY SE.STOCKENTRYDETAILID DESC) AS SNO,                      
		SE.STOCKENTRYID, SE.STOCKENTRYDETAILID,I.ITEMID,I.ISOPENITEM,IC.ITEMCODEID,
		I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,SE.CPWITHTAX,SE.CPWITHOUTTAX,SE.INVOICECPWITHTAX, SE.INVOICECPWITHOUTTAX,    
		SE.GSTID,SE.MRP,SE.SALEPRICE,SE.QUANTITY,SE.WEIGHTINKGS,
		SE.DISCOUNTFLAT, SE.DISCOUNTPERCENTAGE, SE.SCHEMEPERCENTAGE, SE.SCHEMEFLAT, 
		SE.TOTALPRICEWT, SE.TOTALPRICEWOT, SE.APPLIEDDISCOUNT, SE.APPLIEDSCHEME, 
		SE.GSTID, SE.APPLIEDDGST,SE.FINALPRICEWOTAX, SE.FINALPRICE,SE.CGST,
		SE.SGST,SE.IGST,SE.CESS,IC.HSNCODE, GST.GSTCODE,ISNULL(SE.ISFREEITEM,0) AS ISFREEITEM,
		SE.CREATEDDATE, CU.FULLNAME AS CREATEDBY, SID.REQUIREDITEMINDENT INDENTQUANTITY
	FROM STOCKENTRYDETAIL SE                           
		LEFT JOIN ITEMCODE IC ON SE.ITEMCODEID = IC.ITEMCODEID            
		LEFT JOIN SUPPLIERINDENTDETAIL SID ON SID.SUPPLIERINDENTDETAILID = SE.SUPPLIERINDENTDETAILID
		LEFT JOIN ITEM I ON I.ITEMID = ISNULL(IC.ITEMID, SID.ITEMID)
		LEFT JOIN GSTDETAIL GST ON SE.GSTID = GST.GSTID
		LEFT JOIN TBLUSER CU ON SE.CREATEDBY = CU.USERID
	WHERE STOCKENTRYID = @STOCKENTRYID            
		AND (SE.DELETEDDATE IS NULL OR SE.REVERTED_DATE IS NOT  NULL)
	ORDER BY STOCKENTRYDETAILID ASC
                        
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKENTRYDTAFT_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_STOCKENTRYDTAFT_v2]              
@USERID INT
,@CATEGORYID INT      
,@STOCKENTRYID INT = 0
AS              
BEGIN              
              
	IF @STOCKENTRYID = 0
	BEGIN
		SELECT @STOCKENTRYID = STOCKENTRYID FROM STOCKENTRY              
		WHERE CREATEDBY = @USERID 
			AND ISNULL(STATUS,0) = 0 
			AND DELETEDDATE IS NULL
	END
    
	EXEC USP_R_STOCKENTRY_v2 @STOCKENTRYID , 1
              
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKSUMMARY_SUPPLIER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
