GO
CREATE proc [dbo].[USP_R_STOCKSUMMARY_SUPPLIER]
@BranchID VARCHAR(500), 
@SupplierID INT = 0
AS          
BEGIN          
    
	--declare @ItemID INT = 0

	SELECT  
		SS.ITEMID	
		, I.SKUCODE
		, I.ITEMNAME
		, C.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, BR.BRANDNAME
		, MAN.MANUFACTURERNAME
		, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN 'NO' ELSE 'YES' END AS ISOPENITEM          
		, SS.QUANTITY
		, SS.WEIGHTINKGS		
		, SS.TOTALCOSTPRICEWOT
		, SS.TOTALCOSTPRICETAX
		, SS.TOTALCOSTPRICEWT
	FROM 
		(
			SELECT           
				IC.ITEMID	
				, SUM(SSINNER.QUANTITY) QUANTITY
				, SUM(SSINNER.WEIGHTINKGS) WEIGHTINKGS
				, CAST(SUM((CASE WHEN ISNULL(IINNER.ISOPENITEM, 0) = 0 THEN SSINNER.QUANTITY ELSE SSINNER.WEIGHTINKGS END) * ICP.COSTPRICEWOT) AS DECIMAL(18, 2)) AS TOTALCOSTPRICEWOT
				, CAST(SUM((CASE WHEN ISNULL(IINNER.ISOPENITEM, 0) = 0 THEN SSINNER.QUANTITY ELSE SSINNER.WEIGHTINKGS END) * (ICP.COSTPRICEWT - ICP.COSTPRICEWOT)) AS DECIMAL(18, 2)) AS TOTALCOSTPRICETAX
				, CAST(SUM((CASE WHEN ISNULL(IINNER.ISOPENITEM, 0) = 0 THEN SSINNER.QUANTITY ELSE SSINNER.WEIGHTINKGS END) * ICP.COSTPRICEWT) AS DECIMAL(18, 2)) AS TOTALCOSTPRICEWT
			FROM STOCKSUMMARY SSINNER
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID        
				INNER JOIN dbo.SplitString(@BranchID,',') B ON SSINNER.BRANCHID = B.ITEM
				INNER JOIN ITEM IINNER ON IINNER.ITEMID = IC.ITEMID     
				INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = IINNER.ITEMID
				LEFT JOIN
					(
						SELECT ICPINNER.ITEMPRICEID, MAX(ICPINNER.ITEMCOSTPRICEID) MAXITEMCOSTPRICEID
						FROM ITEMCOSTPRICE ICPINNER 
						WHERE ICPINNER.DELETEDDATE IS NULL
						GROUP BY ICPINNER.ITEMPRICEID
					) MAXICP ON MAXICP.ITEMPRICEID = SSINNER.ITEMPRICEID
				LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = MAXICP.ITEMPRICEID
			WHERE ISM.SUPPLIERID = @SupplierID
			AND (SSINNER.QUANTITY <> 0 OR SSINNER.WEIGHTINKGS <> 0)
			GROUP BY IC.ITEMID, IINNER.ISOPENITEM
		) SS
		INNER JOIN ITEM I ON I.ITEMID = SS.ITEMID      
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID  
		LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID		
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY I.SKUCODE, I.ITEMNAME
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKSUMMARY1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[USP_R_STOCKSUMMARY1]          
@BranchID INT = 0
, @ItemID INT = 0
AS          
BEGIN          

	SELECT  
		SS.ITEMID	
		, I.SKUCODE
		, I.ITEMNAME
		, C.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, TB.BRANDNAME
		, TM.MANUFACTURERNAME
		, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN 'NO' ELSE 'YES' END AS ISOPENITEM          
		, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS 'Qty or Weight in KG(s)'
	FROM 
	(
		SELECT           
			IC.ITEMID	
			, SUM(SSINNER.QUANTITY) QUANTITY
			, SUM(SSINNER.WEIGHTINKGS) WEIGHTINKGS
		FROM STOCKSUMMARY SSINNER
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID        
		WHERE SSINNER.BRANCHID = @BranchID
			AND (IC.ITEMID = @ItemID OR @ItemID = 0)    
		GROUP BY 
			  IC.ITEMID
	) SS
		INNER JOIN ITEM I ON I.ITEMID = SS.ITEMID      
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID  
		LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION ICL ON I.CLASSIFICATIONID = ICL.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCL ON I.SUBCLASSIFICATIONID = ISCL.SUBCLASSIFICATIONID
		LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
		LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
	WHERE 
	(
		SS.QUANTITY <> 0 
		OR SS.WEIGHTINKGS <> 0 
	) 
	ORDER BY I.SKUCODE, I.ITEMNAME


	SELECT 
			SS.ITEMID
			, SS.ITEMCODEID
			, IC.ITEMCODE
			, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS 'Qty or Weight in KG(s)'    

	FROM 
	(
		SELECT          
			IC.ITEMID
			, IP.ITEMCODEID
			, SUM(SSINNER.QUANTITY) AS QUANTITY
			, SUM(SSINNER.WEIGHTINKGS) AS WEIGHTINKGS
		FROM STOCKSUMMARY SSINNER
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		WHERE SSINNER.BRANCHID = @BranchID
			AND (IC.ITEMID = @ItemID OR @ItemID = 0)
		GROUP BY IC.ITEMID, IP.ITEMCODEID
	) SS
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = SS.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID      
	WHERE  
	(
		SS.QUANTITY <> 0 
		OR SS.WEIGHTINKGS <> 0 
	)
	AND 0 = 1
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_STOCKSUMMARYITEMID]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_STOCKSUMMARYITEMID]
@ITEMID INT,
@BRANCHID INT
AS
BEGIN

	SELECT 
		SUM(SS.QUANTITY) AS QUANTITY, SUM(SS.WEIGHTINKGS) AS WEIGHTINKGS, I.ISOPENITEM
	FROM STOCKSUMMARY SS
		INNER JOIN ITEMPRICE IP ON SS.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE SS.BRANCHID = @BRANCHID
		AND IC.ITEMID = @ITEMID
		AND IP.DELETEDDATE IS NULL
	GROUP BY I.ISOPENITEM

	IF EXISTS(SELECT 1 FROM BRANCH WHERE BRANCHID = @BRANCHID AND ISWAREHOUSE = 0)
	BEGIN
		SELECT 
			SUM(DISPATCHQUANTITY) AS QUANTITY, 
			SUM(WEIGHTINKGS) AS WEIGHTINKGS, 
			I.ISOPENITEM
		FROM STOCKDISPATCHDETAIL SDD
			INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
			INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		WHERE SD.TOBRANCHID = @BRANCHID
			AND IC.ITEMID = @ITEMID
			AND SD.DELETEDDATE IS NULL
			AND SDD.DELETEDDATE IS NULL
			AND ISNULL(SDD.ISACCEPTED,0) = 0
		GROUP BY I.ISOPENITEM
	END
	ELSE
	BEGIN
		SELECT 
			SUM(QUANTITY) AS QUANTITY, 
			SUM(WEIGHTINKGS) AS WEIGHTINKGS, 
			I.ISOPENITEM
		FROM POS_BREFUNDDETAIL BRD
			INNER JOIN POS_BREFUND BR ON BRD.BRID = BR.BRID
			INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		WHERE BR.BRANCHID = @BRANCHID
			AND IC.ITEMID = @ITEMID
			AND BR.DELETEDDATE IS NULL
			AND BRD.DELETEDDATE IS NULL
			AND BR.ACCEPTEDDATE IS NULL
		GROUP BY I.ISOPENITEM
	END
END
GO
