CREATE PROCEDURE [dbo].[USP_R_SUPPLIER_ITEMS]
@SUPPLIERID INT
AS
BEGIN

	SELECT  
		ISM.ITEMSUPPLIERMAPID,
		I.ITEMID,
		I.SKUCODE,
		I.ITEMNAME,
		CAT.CATEGORYNAME,
		SCAT.SUBCATEGORYNAME,
		BR.BRANDNAME,
		MAN.MANUFACTURERNAME
	FROM ITEMSUPPLIERMAP ISM
		INNER JOIN ITEM I ON ISM.ITEMID = I.ITEMID
		INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
		INNER JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
