/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERDEBITNOTE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERDEBITNOTE]  
@SupplierReturnsID INT = 0  
AS  
BEGIN  
  
	SELECT 
		SR.SUPPLIERRETURNSID,
		SR.CNINITIATEDDATE AS DCDATE,
		'37AAICV7240C1ZC' AS WHGSTIN,
		B.ADDRESS AS WHAddress,
		S.ADDRESS AS SupplierAddress,
		S.SHIPPINGADDRESS,
		S.GSTIN AS SupplierGSTIN,
		U.FULLNAME AS USERNAME
	FROM SUPPLIERRETURNS SR 
		INNER JOIN BRANCH B ON SR.BRANCHID = B.BRANCHID
		INNER JOIN TBLDEALER S ON SR.SUPPLIERID = S.DEALERID	
		INNER JOIN TBLUSER U ON SR.CNINITIATEDBY = U.USERID
	WHERE SUPPLIERRETURNSID = @SupplierReturnsID

	SELECT ROW_NUMBER() OVER(ORDER BY SRD.SUPPLIERRETURNSDETAILID ASC) AS SNO  
		,I.ITEMNAME  
		,IC.HSNCODE
		,GST.GSTCODE
		,CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY   ELSE SRD.WEIGHTINKGS  END QUANTITY
		,ICP.COSTPRICEWT * (CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY   ELSE SRD.WEIGHTINKGS  END) AS TOTALCOSTPRICE  
	FROM SUPPLIERRETURNSDETAIL SRD  
		INNER JOIN SUPPLIERRETURNS SR ON SRD.SUPPLIERRETURNSID = SR.SUPPLIERRETURNSID  
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID  
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID  
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID  
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID  
	WHERE SR.SUPPLIERRETURNSID = @SupplierReturnsID  
		AND SRD.DELETEDDATE IS NULL  
	ORDER BY 1  
  
END
GO
