CREATE PROCEDURE [dbo].[USP_R_SUPPLIERINDENT]
@CATEGORYID INT = 13,
@Fromdate date,
@Todate date
AS
BEGIN

	SELECT 
		SI.SUPPLIERINDENTID, SI.SUPPLIERID, D.DEALERNAME, SI.INDENTDAYS, SI.SAFETYDAYS, C.CATEGORYNAME, MFR.MANUFACTURERNAME
		, SI.SUPPLIERINDENTNO, CU.FULLNAME AS CREATEDBY, SI.CREATEDDATE, UU.FULLNAME AS UPDATEDBY
		, SI.UPDATEDDATE, AU.FULLNAME AS APPROVEDBY, SI.APPROVEDDATE
		, SI.STATUS, ELSTATUS.ENUMVALUE AS STATUSTEXT, SI.CATEGORYID, SI.MOBILENO
		, EL.ENUMVALUE AS SUPPLIERINDENTTYPE, EL2.ENUMVALUE AS ItemSelection
		, SI.BRANCHID, B.BRANCHNAME, B.ADDRESS BRANCHADDRESS,  REPLACE(REPLACE(D.ADDRESS, CHAR(13), ''), CHAR(10), '') SUPPLIERADDRESS
	FROM SUPPLIERINDENT SI
		INNER JOIN TBLDEALER D ON D.DEALERID = SI.SUPPLIERID
		INNER JOIN TBLCATEGORY C ON C.CATEGORYID = SI.CATEGORYID
		left JOIN TBLUSER CU ON CU.USERID = SI.CREATEDBY
		left JOIN TBLUSER AU ON AU.USERID = SI.APPROVEDBY
		left JOIN TBLUSER UU ON UU.USERID = SI.UPDATEDBY
		LEFT JOIN ENUMLIST EL ON EL.ENUMID = SI.SUPPLIERINDENTTYPEID
		LEFT JOIN ENUMLIST EL2 ON EL2.ENUMID = SI.SUPPLIERITEMINDENTTYPEID
		LEFT JOIN ENUMLIST ELSTATUS ON ELSTATUS.ENUMID = SI.STATUS
		LEFT JOIN BRANCH B ON B.BRANCHID = SI.BRANCHID
		LEFT JOIN TBLMANUFACTURER MFR ON MFR.MANUFACTURERID = SI.MANUFACTURERID
	WHERE (SI.CATEGORYID = @CATEGORYID OR @CATEGORYID = 13)
		AND CONVERT(date, SI.CREATEDDATE) >= CONVERT(date, @Fromdate)
		AND CONVERT(date,SI.CREATEDDATE) <= CONVERT(date,@Todate)

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERINDENTDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERINDENTDETAIL]
@SUPPLIERINDENTID INT,
@SkipZero BIT = 0
AS
BEGIN

	SELECT 
		ROW_NUMBER() OVER(ORDER BY I.ITEMNAME ASC) AS SNO,
		SID.SUPPLIERINDENTDETAILID, SID.ITEMID, I.SKUCODE, I.ITEMNAME, SC.SUBCATEGORYNAME, SID.MRP, SID.COSTPRICEWT
		, SID.BRANCHQUANTITY BranchQuantity, SID.REQUIREDBRANCHSTOCK, SID.REQUIREDITEMINDENT, SID.DESIREDINDENT
		, CASE 
			WHEN SID.ISMANUAL = 1 THEN 'Added' 
			ELSE CASE WHEN SID.REQUIREDITEMINDENT = SID.DESIREDINDENT THEN 'Generated'  ELSE 'Modified' END 
		END AS INDENTTYPE
		, I.VENDORSKUCODE 
	FROM SUPPLIERINDENTDETAIL SID
		INNER JOIN ITEM I ON I.ITEMID = SID.ITEMID
		LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
	WHERE SID.SUPPLIERINDENTID = @SUPPLIERINDENTID
		AND SID.DELETEDBY IS NULL
		AND (@SkipZero = 0 OR SID.DESIREDINDENT <> 0)
	ORDER BY I.ITEMNAME

	SELECT SIDFT.SUPPLIERINDENTDETAILID, B.BRANCHNAME, SIDFT.BRANCHQUANTITY, SIDFT.REQUIREDBRANCHSTOCK, SIDFT.REQUIREDITEMINDENT
	FROM
		SID_FT_DETAIL SIDFT
		INNER JOIN SUPPLIERINDENTDETAIL SID ON SID.SUPPLIERINDENTDETAILID = SIDFT.SUPPLIERINDENTDETAILID 
		INNER JOIN BRANCH B ON B.BRANCHID = SIDFT.BRANCHID		
	WHERE SID.SUPPLIERINDENTID = @SUPPLIERINDENTID
		AND SID.DELETEDBY IS NULL
		AND (@SkipZero = 0 OR SID.DESIREDINDENT <> 0)
	ORDER BY SIDFT.SUPPLIERINDENTDETAILID, SIDFT.REQUIREDITEMINDENT DESC

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERINDENTLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_R_SUPPLIERINDENTLIST]
    @SUPPLIERID INT,
    @CATEGORYID INT,
    @BRANCHID INT = 45,
    @SELECTEDSUPPLIERINDENTID INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 0 AS PARENTID;

    SELECT 0 AS PARENTID, SI.SUPPLIERINDENTID, SI.SUPPLIERINDENTNO
    FROM SUPPLIERINDENT SI
        INNER JOIN TBLDEALER D ON D.DEALERID = SI.SUPPLIERID
    WHERE SI.SUPPLIERID = @SUPPLIERID
        AND SI.CATEGORYID = @CATEGORYID
        AND SI.BRANCHID = @BRANCHID
        AND SI.DELETEDDATE IS NULL
        AND SI.SUPPLIERINDENTNO IS NOT NULL
        AND (
            (SI.STATUS IN (14, 15)
                AND SI.CREATEDDATE > DATEADD(d, -15, CAST(GETDATE() AS DATE)))
            OR SI.SUPPLIERINDENTID = @SELECTEDSUPPLIERINDENTID
        );
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERITEMS]
@SUPPLIERID INT
AS
BEGIN

	SELECT 
		I.ITEMID,
		IC.ITEMCODEID,
		IP.ITEMPRICEID,
		I.SKUCODE,
		I.VENDORSKUCODE,
		IC.ITEMCODE,
		I.ITEMNAME,
		C.CATEGORYNAME,
		BR.BRANDNAME AS Brand, 
		MAN.MANUFACTURERNAME AS Manufacturer,
		IP.MRP,
		IP.SALEPRICE,
		ICP.COSTPRICEWOT,
		ICP.COSTPRICEWT,
		SE.CREATEDDATE AS [Last Recived Date],
		SE.SUPPLIERINVOICENO as [Invoice Number]
	FROM ITEMSUPPLIERMAP ISM
		INNER JOIN ITEMCOSTPRICE ICP ON ISM.ITEMCOSTPRICEID = ICP. ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
		LEFT JOIN STOCKENTRY SE ON ISM.STOCKENTRYID = SE.STOCKENTRYID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	WHERE ISM.SUPPLIERID = @SUPPLIERID
	ORDER BY SE.CREATEDDATE DESC

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERITEMS_BY_BRANCHSTOCK]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERITEMS_BY_BRANCHSTOCK]
@SUPPLIERID INT,
@BRANCHID INT,
@CATEGORYID INT,
@SUPPLIERRETURNSID INT
AS
BEGIN

		SELECT 
			ITEMPRICEID,
			MAX(ITEMCOSTPRICEID) AS LATESTITEMCOSTPRICEID
		INTO #LATESTCOSTPRICE
		FROM ITEMCOSTPRICE
		WHERE DELETEDDATE IS NULL
		GROUP BY ITEMPRICEID

		;WITH StockData AS
		(
			SELECT 
				I.ITEMID,
				IC.ITEMCODEID,
				IP.ITEMPRICEID,
				I.GSTID,
				I.SKUCODE,
				IC.ITEMCODE,
				I.ITEMNAME,
				IP.MRP,
				CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS QUANTITY,
				ICP.COSTPRICEWT,
				ICP.ITEMCOSTPRICEID,
				CASE WHEN ISNULL(SRD.SUPPLIERRETURNSDETAILID, 0) = 0 THEN 0 ELSE 1 END AS IsAdded
			FROM STOCKSUMMARY SS
				INNER JOIN ITEMPRICE IP ON SS.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
				INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
				INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = I.ITEMID
				INNER JOIN #LATESTCOSTPRICE LC ON LC.ITEMPRICEID = IP.ITEMPRICEID
				LEFT JOIN ITEMCOSTPRICE ICP ON LC.LATESTITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
				LEFT JOIN SUPPLIERRETURNSDETAIL SRD ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID 
					AND SRD.SUPPLIERRETURNSID = @SUPPLIERRETURNSID 
					AND SRD.DELETEDDATE IS NULL
			WHERE I.CATEGORYID = @CATEGORYID
				AND SS.BRANCHID = @BRANCHID
				AND ISM.SUPPLIERID = @SUPPLIERID
				AND ISM.DELETEDDATE IS NULL
				AND I.DELETEDDATE IS NULL
				AND IC.DELETEDDATE IS NULL
				AND IP.DELETEDDATE IS NULL
				AND (SS.QUANTITY > 0 OR SS.WEIGHTINKGS > 0)
		)

		SELECT
			ITEMID,
			ITEMCODEID,
			ITEMPRICEID,
			ITEMCOSTPRICEID,
			GSTID,
			SKUCODE,
			ITEMCODE,
			ITEMNAME,
			MRP,
			COSTPRICEWT,
			QUANTITY AS QUANTITY,
			QUANTITY AS RETURNQUANTITY,
			IsAdded
		FROM StockData
		ORDER BY ITEMCOSTPRICEID;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERRETURNDETAILFORCN]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERRETURNDETAILFORCN]  
@SupplierReturnsID INT = 0  
AS  
BEGIN  
  
	SELECT ROW_NUMBER() OVER(ORDER BY SRD.SUPPLIERRETURNSDETAILID ASC) AS SNO  
		,SRD.SUPPLIERRETURNSDETAILID  
		,SRD.SUPPLIERRETURNSID  
		,SRD.ITEMCOSTPRICEID  
		,IC.ITEMCODE  
		,I.ITEMNAME  
		,IC.HSNCODE
		,IP.MRP  
		,GST.GSTCODE
		,CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY   ELSE SRD.WEIGHTINKGS  END QUANTITY
		,ICP.COSTPRICEWT AS COSTPRICE  
		,ICP.COSTPRICEWT * (CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY   ELSE SRD.WEIGHTINKGS  END) AS TOTALCOSTPRICE  
		,CAST(0 AS BIT) AS SELECTED  
		,ISNULL(RETURNSTATUS ,1) AS RETURNSTATUS
	FROM SUPPLIERRETURNSDETAIL SRD  
		INNER JOIN SUPPLIERRETURNS SR ON SRD.SUPPLIERRETURNSID = SR.SUPPLIERRETURNSID  
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID  
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID  
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID  
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID  
	WHERE SR.SUPPLIERRETURNSID = @SupplierReturnsID  
		AND SRD.DELETEDDATE IS NULL  
	ORDER BY 1  
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERRETURNS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERRETURNS]
@SupplierID INT = 0,
@FromDate datetime,
@ToDate datetime,
@CategoryID INT = 0
AS                
BEGIN                
                
SELECT SR.SUPPLIERRETURNSID,                 
    SR.SUPPLIERRETURNSID AS 'Debit Note #',
    SR.SUPPLIERID,
    D.DEALERNAME,
    CAT.CATEGORYNAME,
    B.BRANCHNAME,
    SRD.TOTALCOSTPRICE AS PROPOSEDVALUE,
    CASE WHEN ISNULL(SR.RETURNVALUE,0) = 0 THEN ISNULL(SRCNM.MAPPEDVALUE,0) ELSE SR.RETURNVALUE END AS ACCEPTEDVALUE,
    SRD.TOTALCOSTPRICE - CASE WHEN ISNULL(SR.RETURNVALUE,0) = 0 THEN ISNULL(SRCNM.MAPPEDVALUE,0) ELSE SR.RETURNVALUE END AS REJECTEDVALUE,
    CU.FULLNAME AS CREATEDBY,
    SR.CREATEDDATE,
    IU.FULLNAME AS GeneratedBy,
    SR.CNINITIATEDDATE AS GeneratedDate,
    UU.FULLNAME AS UPDATEDBY,
    SR.UPDATEDDATE,
    CASE 
        WHEN ISNULL(SR.STATUS,0) = 0 THEN 'Draft'
        WHEN ISNULL(SR.STATUS,0) = 1 THEN 'Open' 
        WHEN ISNULL(SR.STATUS,0) = 2 THEN 'Partially Closed'
        WHEN ISNULL(SR.STATUS,0) = 3 THEN 'Closed'
		WHEN ISNULL(SR.STATUS,0) = 4 THEN 'Write Off'
    END AS STATUS,
    SE.SUPPLIERINVOICENO AS [Invoice No #]
FROM SUPPLIERRETURNS SR
    LEFT JOIN BRANCH B ON SR.BRANCHID = B.BRANCHID
    LEFT JOIN STOCKENTRY SE ON SR.STOCKENTRYID = SE.STOCKENTRYID
    LEFT JOIN (
        SELECT SRD.SUPPLIERRETURNSID,
            SUM(ICP.COSTPRICEWT * CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY ELSE SRD.WEIGHTINKGS END) AS TOTALCOSTPRICE
        FROM SUPPLIERRETURNSDETAIL SRD
        INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
        WHERE SRD.DELETEDDATE IS NULL
        GROUP BY SUPPLIERRETURNSID
    ) SRD ON SR.SUPPLIERRETURNSID = SRD.SUPPLIERRETURNSID
    INNER JOIN TBLDEALER D ON D.DEALERID = SR.SUPPLIERID
    LEFT JOIN TBLUSER CU ON SR.CREATEDBY = CU.USERID                
    LEFT JOIN TBLUSER IU ON SR.CNINITIATEDBY = IU.USERID
    LEFT JOIN TBLUSER UU ON SR.UPDATEDBY = UU.USERID    
    LEFT JOIN TBLCATEGORY CAT ON SR.CATEGORYID = CAT.CATEGORYID
	LEFT JOIN
	(
		SELECT 
			SUPPLIERRETURNSID,
			SUM(MappedReturnValue) AS MAPPEDVALUE
		FROM SUPPLIERRETURNSCREDITNOTEMAP
		WHERE DELETEDDATE IS NULL
		GROUP BY SUPPLIERRETURNSID
	) SRCNM
	ON SR.SUPPLIERRETURNSID = SRCNM.SUPPLIERRETURNSID
WHERE (SR.SUPPLIERID = @SupplierID OR @SupplierID = 0)
    AND (SR.CATEGORYID = @CategoryID OR @CategoryID = 13)
    AND CONVERT(DATE,SR.CREATEDDATE) >= CONVERT(DATE,@FromDate) 
    AND CONVERT(DATE,SR.CREATEDDATE) <= CONVERT(DATE,@ToDate)
    AND (ISNULL(SR.STATUS, 0) <> 0 OR SR.BRANCHID IS NOT NULL)
    AND SR.DELETEDDATE IS NULL
ORDER BY SR.CNINITIATEDDATE DESC;


END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERRETURNS_CREDITNOTES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERRETURNS_CREDITNOTES]
(
    @SupplierRefId INT,
	@ReferenceType  varchar(10)
)
AS
BEGIN
    SET NOCOUNT ON;

	if(@ReferenceType = 'SR')
	BEGIN
		SELECT
			SRCNM.SUPPLIERRETURNSCREDITNOTEMAPID AS MAPID,
			SRCNM.CREDITNOTEID,
			CN.CNNumber,
			CN.CreditValue,
			SRCNM.MappedReturnValue,
			CU.FULLNAME AS CREATEDBY,
			SRCNM.CREATEDDATE
		FROM SUPPLIERRETURNSCREDITNOTEMAP SRCNM
		INNER JOIN CreditNote CN
			ON CN.CreditNoteId = SRCNM.CREDITNOTEID
		INNER JOIN TBLUSER CU ON SRCNM.CREATEDBY = CU.USERID
		WHERE SRCNM.SUPPLIERRETURNSID = @SupplierRefId
		  AND SRCNM.DELETEDDATE IS NULL
		  AND CN.DeletedDate IS NULL;
	END
	ELSE if(@ReferenceType = 'SE')
	BEGIN
		SELECT
			SECNM.STOCKENTRYCREDITNOTEMAPID AS MAPID,
			SECNM.CREDITNOTEID,
			CN.CNNumber,
			CN.CreditValue,
			SECNM.MappedReturnValue AS MappedReturnValue,
			CU.FULLNAME AS CREATEDBY,
			SECNM.CREATEDDATE
		FROM STOCKENTRYCREDITNOTEMAP SECNM
		INNER JOIN CreditNote CN ON CN.CreditNoteId = SECNM.CREDITNOTEID
		INNER JOIN TBLUSER CU ON SECNM.CREATEDBY = CU.USERID
		WHERE SECNM.STOCKENTRYID = @SupplierRefId
		  AND SECNM.DELETEDDATE IS NULL
		  AND CN.DeletedDate IS NULL;
	END

END;
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERRETURNSDETAIL]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERRETURNSDETAIL]
@SUPPLIERRETURNSID INT = 0
AS
BEGIN

	SELECT 

		ROW_NUMBER() OVER(ORDER BY SRD.SUPPLIERRETURNSDETAILID ASC) AS SNO
		,SRD.SUPPLIERRETURNSDETAILID
		,SRD.SUPPLIERRETURNSID
		,SRD.ITEMCOSTPRICEID
		,IC.ITEMCODE
		,I.ITEMNAME
		,IP.MRP
		,IP.SALEPRICE
		,CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY ELSE SRD.WEIGHTINKGS END AS QUANTITY
		,ICP.COSTPRICEWT AS COSTPRICE
		,(CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY ELSE SRD.WEIGHTINKGS END) * ICP.COSTPRICEWT AS TOTALCOSTPRICE
		,I.HSNCODE
		,GST.GSTCODE
		,SRD.REASONID
	FROM SUPPLIERRETURNSDETAIL SRD
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		INNER JOIN GSTDETAIL GST ON IP.GSTID = GST.GSTID
	WHERE SRD.SUPPLIERRETURNSID = @SUPPLIERRETURNSID
		AND SRD.DELETEDDATE IS NULL
	ORDER BY 1

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_SUPPLIERRETURNSITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_SUPPLIERRETURNSITEMS]
@SUPPLIERRETURNSID INT
AS
BEGIN

	SELECT 
		ROW_NUMBER() OVER(ORDER BY SRD.SUPPLIERRETURNSDETAILID ASC) AS SNO
		,SRD.SUPPLIERRETURNSDETAILID
		,SRD.SUPPLIERRETURNSID
		,SRD.ITEMCOSTPRICEID
		,IC.ITEMCODE
		,I.ITEMNAME
		,IC.HSNCODE
		,IP.MRP
		,GST.GSTCODE
		,CASE WHEN I.ISOPENITEM = 0 THEN SRD.QUANTITY ELSE SRD.WEIGHTINKGS END AS QUANTITY
		,ICP.COSTPRICEWT AS COSTPRICE
		,ROUND(ICP.COSTPRICEWT * SRD.QUANTITY,2) AS TOTALCOSTPRICE
	FROM SUPPLIERRETURNSDETAIL SRD
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE SRD.SUPPLIERRETURNSID = @SUPPLIERRETURNSID
		AND SRD.DELETEDDATE IS NULL
	ORDER BY 1

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_TRANSITDETAILSBYITEMID]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_TRANSITDETAILSBYITEMID]
@BRNACHID INT,
@ITEMID INT
AS
BEGIN

	CREATE TABLE #TDETAILS(TRANSITQUANTITY DECIMAL(18,2), BRANCHNAME VARCHAR(100), TRANSITENTITYTYPE VARCHAR(100), TRANSITDIRECTION VARCHAR(100))

	INSERT INTO #TDETAILS
	SELECT 
		CASE WHEN I.ISOPENITEM = 0 THEN SSTRANSITIN.QUANTITY - SSTRANSITIN.RECIEVEDQUANTITY 
				ELSE SSTRANSITIN.WEIGHTINKGS - SSTRANSITIN.RECIEVEDWEIGHTINKGS END AS TRANSITQUANTITY,
		BFROM.BRANCHNAME AS BRANCHNAME,
		TEIN.TRANSITENTITYTYPE,
		'Transit-In' AS TRANSITDIRECTION
	FROM STOCKSUMMARY SS
		INNER JOIN ITEMPRICE IP ON SS.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN STOCKSUMMARYTRANSIT SSTRANSITIN ON SS.STOCKSUMMARYID = SSTRANSITIN.TOSTOCKSUMMARYID
		LEFT JOIN BRANCH BFROM ON SSTRANSITIN.FROMBRANCHID = BFROM.BRANCHID
		LEFT JOIN TRANSITENTITY TEIN ON SSTRANSITIN.TRANSITENTTYID = TEIN.TRANSITENTITYID
	WHERE SS.BRANCHID = 45 AND IC.ITEMID = 2260 AND ISNULL(SSTRANSITIN.QUANTITY,0) > 0


	INSERT INTO #TDETAILS
	SELECT 
		CASE WHEN I.ISOPENITEM = 0 THEN SSTRANSITOUT.QUANTITY - SSTRANSITOUT.RECIEVEDQUANTITY 
				ELSE SSTRANSITOUT.WEIGHTINKGS - SSTRANSITOUT.RECIEVEDWEIGHTINKGS END AS TRANSITQUANTITY,
		BTO.BRANCHNAME ,
		TEOUT.TRANSITENTITYTYPE,
		'Transit-Out'
	FROM STOCKSUMMARY SS
		INNER JOIN ITEMPRICE IP ON SS.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN STOCKSUMMARYTRANSIT SSTRANSITOUT ON SS.STOCKSUMMARYID = SSTRANSITOUT.FROMSTOCKSUMMARYID
		LEFT JOIN BRANCH BTO ON SSTRANSITOUT.TOBRANCHID = BTO.BRANCHID
		LEFT JOIN TRANSITENTITY TEOUT ON SSTRANSITOUT.TRANSITENTTYID = TEOUT.TRANSITENTITYID
	WHERE SS.BRANCHID = @BRNACHID AND IC.ITEMID = @ITEMID AND ISNULL(SSTRANSITOUT.QUANTITY,0) > 0

	SELECT * FROM #TDETAILS

END
GO
