CREATE PROC [dbo].[USP_R_USERACCESSINFO]
(
	@UserID INT
)
AS
BEGIN

	SELECT WF.[UNIQUEIDENTIFIER] + '::' + ATYPE.ACTIONTYPETEXT
	FROM
		WORKFLOWACTION WFA
		INNER JOIN WORKFLOW WF ON WF.WORKFLOWID = WFA.WORKFLOWID
		INNER JOIN ACTIONTYPE ATYPE ON ATYPE.ACTIONTYPEID = WFA.ACTIONTYPEID
		INNER JOIN HASACCESS HA ON HA.WORKFLOWACTIONID = WFA.WORKFLOWACTIONID
	WHERE 
		HA.USERID = @UserID
		AND HA.DELETEDDATE IS NULL

END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_USERLOGIN]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_USERLOGIN]      
@USERNAME NVARCHAR(100),                                              
@PASSWORD NVARCHAR(100), 
@APPVERSION VARCHAR(10) = NULL                          
AS                                              
BEGIN                                              

	IF(SELECT CONFIGVALUE FROM CONFIG WHERE CONFIGNAME = 'APPVERSION') <> ISNULL(@APPVERSION, '')
	BEGIN
		SELECT 'Application version mismatch. please install version ' + CONFIGVALUE FROM CONFIG WHERE CONFIGNAME = 'APPVERSION'
		RETURN
	END
                                              
	DECLARE @USERID INT = 0 , @isWarehouse Bit
                                      
	SELECT 
		@USERID = USERID, 
		@isWarehouse = isnull(ISWAREHOUSE,0)
	FROM TBLUSER U
		INNER JOIN BRANCH B ON U.BRANCHID = B.BRANCHID
	WHERE USERNAME = @USERNAME      
		AND PASSWORDSTRING = @PASSWORD 
		AND U.DELETEDBY IS NULL      

	IF(@USERID > 0 AND @isWarehouse = 0)
	BEGIN

		SELECT 'User does not belongs to warehouse'
		RETURN;

	END


	IF (@USERID > 0)                                              
	BEGIN                                              

		SELECT                                              
			U.USERID, U.USERNAME, U.FULLNAME, U.PASSWORDSTRING, U.CNUMBER, U.EMAIL, U.GENDER, ISNULL(U.ISOTP,0) AS ISOTP, U.REPORTINGLEADID,      
			RL.FULLNAME AS REPORTINGLEAD, U.ROLEID, R.ROLENAME, U.CATEGORYID, C.CATEGORYNAME, U.BRANCHID, B.BRANCHNAME, ISNULL(C.ALLOWOPENITEMS,0) AS ALLOWOPENITEMS  
		FROM 
			TBLUSER U                         
			LEFT JOIN TBLROLE R ON U.ROLEID = R.ROLEID      
			LEFT JOIN TBLUSER RL ON U.REPORTINGLEADID = RL.USERID      
			LEFT JOIN TBLCATEGORY C ON U.CATEGORYID = C.CATEGORYID      
			LEFT JOIN BRANCH B ON U.BRANCHID = B.BRANCHID      
		WHERE U.USERID = @USERID      
    
		EXEC USP_R_PRINTERSETTINGS @USERID    

		SELECT * FROM CONNECTIONINFO ORDER BY DISPLAYORDER

		EXEC USP_R_USERACCESSINFO @USERID
                                             
	END                                              
	ELSE                                              
		SELECT 'Invalid Username or Password'                                              
                                              
END
GO
/****** Object:  StoredProcedure [dbo].[USP_R_USERLOGIN_Mobile]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_R_USERLOGIN_Mobile]        
@USERNAME NVARCHAR(100),                                                
@PASSWORD NVARCHAR(100),   
@APPVERSION VARCHAR(10) = NULL                            
AS                                                
BEGIN                                                
  
 IF(SELECT CONFIGVALUE FROM CONFIG WHERE CONFIGNAME = 'APPVERSION_MOBILE') <> ISNULL(@APPVERSION, '')  
 BEGIN  
  SELECT 'Application version mismatch. please install version ' + CONFIGVALUE FROM CONFIG WHERE CONFIGNAME = 'APPVERSION_MOBILE'  
  RETURN  
 END  
                                                
 DECLARE @USERID INT = 0 , @isWarehouse Bit  
                                        
 SELECT   
  @USERID = USERID,   
  @isWarehouse = isnull(ISWAREHOUSE,0)  
 FROM TBLUSER U  
  INNER JOIN BRANCH B ON U.BRANCHID = B.BRANCHID  
 WHERE USERNAME = @USERNAME        
  AND PASSWORDSTRING = @PASSWORD   
  AND U.DELETEDBY IS NULL        
  
  
 IF (@USERID > 0)                                                
 BEGIN                                                
  
  SELECT                                                
   U.USERID, U.USERNAME, U.FULLNAME, U.ROLEID, R.ROLENAME, U.CATEGORYID, C.CATEGORYNAME, U.BRANCHID, B.BRANCHNAME
  FROM   
   TBLUSER U                           
   LEFT JOIN TBLROLE R ON U.ROLEID = R.ROLEID        
   LEFT JOIN TBLCATEGORY C ON U.CATEGORYID = C.CATEGORYID        
   LEFT JOIN BRANCH B ON U.BRANCHID = B.BRANCHID        
  WHERE U.USERID = @USERID

  SELECT 0 AS FeatureAccess, 'True' AS AccessAvailable UNION ALL
  SELECT 1, 'True' UNION ALL
  SELECT 2, 'True' UNION ALL
  SELECT 3, 'True'


 END                                                
 ELSE                                                
  SELECT 'Invalid Username or Password'                                                
                                                
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_AUDIT_COSTPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_AUDIT_COSTPRICE]
(
	@ItemID INT = 0
	, @DealerID INT = 0
)
AS
BEGIN

	SELECT 
		IP.ITEMPRICEID, IC.ITEMCODEID, I.ITEMID, CAT.CATEGORYID, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME
		, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE, ICP.COSTPRICEWOT, ICP.COSTPRICEWT
		, CU.USERNAME AS CREATEDBY, ICP.CREATEDDATE, CAST(ICP.CREATEDDATE AS TIME) CREATEDTIME
		, DU.USERNAME AS DELETEDBY, ICP.DELETEDDATE, CAST(ICP.DELETEDDATE AS TIME) DELETEDTIME
		, DLR.DEALERNAME, SERECENT.SUPPLIERINVOICENO, CLS.CLASSIFICATIONNAME, SCLS.SUBCLASSIFICATIONNAME
	FROM
		ITEMCOSTPRICE ICP
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		INNER JOIN TBLUSER CU ON CU.USERID = ICP.CREATEDBY
		LEFT JOIN TBLUSER DU ON DU.USERID = ICP.DELETEDBY
		LEFT JOIN ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION SCLS ON SCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
		LEFT JOIN 
			(
				SELECT DISTINCT SED.ITEMCOSTPRICEID, DLRINNER.DEALERID, DLRINNER.DEALERNAME, MAX(SE.STOCKENTRYID) RECENTSTOCKENTRYID
				FROM 
					STOCKENTRY SE
					INNER JOIN STOCKENTRYDETAIL SED ON SED.STOCKENTRYID = SE.STOCKENTRYID
					INNER JOIN TBLDEALER DLRINNER ON DLRINNER.DEALERID = SE.SUPPLIERID
				WHERE
					SE.DELETEDDATE IS NULL AND SED.DELETEDDATE IS NULL
				GROUP BY SED.ITEMCOSTPRICEID, DLRINNER.DEALERID, DLRINNER.DEALERNAME
			) DLR ON DLR.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		LEFT JOIN STOCKENTRY SERECENT ON SERECENT.STOCKENTRYID = DLR.RECENTSTOCKENTRYID
	WHERE 
		I.ITEMID = @ItemID
		AND (DLR.DEALERID = @DealerID OR @DealerID = 0)
	ORDER BY
		CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE
		, IP.CREATEDDATE, IP.DELETEDDATE
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_AUDIT_SALEPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_AUDIT_SALEPRICE]
(
	@ItemID INT = 0
)
AS
BEGIN
	
	SELECT 
		IP.ITEMPRICEID, IC.ITEMCODEID, I.ITEMID, CAT.CATEGORYID, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME
		, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE, GST.GSTCODE, CU.USERNAME AS CREATEDBY, IP.CREATEDDATE, CAST(IP.CREATEDDATE AS TIME) CREATEDTIME
		, DU.USERNAME AS DELETEDBY, IP.DELETEDDATE, CAST(IP.DELETEDDATE AS TIME) DELETEDTIME, B.BRANCHNAME, CLS.CLASSIFICATIONNAME, SCLS.SUBCLASSIFICATIONNAME
	FROM
		ITEMPRICE IP WITH(NOLOCK)
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = IP.GSTID
		LEFT JOIN TBLUSER CU WITH(NOLOCK) ON CU.USERID = IP.CREATEDBY
		LEFT JOIN TBLUSER DU WITH(NOLOCK) ON DU.USERID = IP.DELETEDBY
		LEFT JOIN ITEMCLASSIFICATION CLS WITH(NOLOCK) ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION SCLS WITH(NOLOCK) ON SCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = IP.BRANCHID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	WHERE 
		(I.ITEMID = @ItemID OR @ItemID = 0)
	ORDER BY
		CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE
		, IP.CREATEDDATE, IP.DELETEDDATE
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_AVG_COSTPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_AVG_COSTPRICE]
(
	@ItemID INT = NULL,
	@AvgCPDate DATE = NULL
)
AS
BEGIN

	SELECT @AvgCPDate = DATEFROMPARTS(YEAR(@AvgCPDate), MONTH(@AvgCPDate), 1)

	SELECT I.ITEMID, IC.ITEMCODEID, AVGCPDATE, CAT.CATEGORYNAME, MFG.MANUFACTURERNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, AICP.MRP
		, AICP.STOCKINCOSTPRICEWOT, AICP.STOCKINCOSTPRICEWT, AICP.STOCKINQTY
		, AICP.PREVMONCOSTPRICEWT, AICP.PREVMONCOSTPRICEWOT, AICP.PREVMONCUMULATIVEFYQTY
		, AICP.PREVFYCOSTPRICEWT, AICP.PREVFYCOSTPRICEWOT
		, AICP.COSTPRICEWT, AICP.COSTPRICEWOT, AICP.CUMULATIVEFYQTY
	FROM 
		AVGCOSTPRICE AICP
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = AICP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN TBLMANUFACTURER MFG ON MFG.MANUFACTURERID = I.MANUFACTURERID
	WHERE
		(I.ITEMID = @ItemID OR @ItemID IS NULL OR @ItemID = 0)
		AND (AVGCPDATE = @AvgCPDate OR @AvgCPDate IS NULL)
	ORDER BY AVGCPDATE, CAT.CATEGORYNAME, MFG.MANUFACTURERNAME, I.ITEMNAME


END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BILLNUMINFO]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_BILLNUMINFO]
(
	@FromDate DATE, 
	@ToDate DATE,
	@BranchID VARCHAR(500),
	@CutOff DECIMAL(9, 2) = 0,
	@UnmaskCustomerPhone BIT = 0,
	@ItemID INT = 0,
	@IncludeDate BIT = 0,
	@IncludeBranch BIT = 0,
	@IncludeBranchCounter BIT = 0,
	@IncludeUser BIT = 0,
	@IncludeBillDetails BIT = 0,
	@IncludeBillMode BIT = 0,
	@IncludePaymentMode BIT = 0,
	@IncludeCountAndAvg BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT PB.BILLID, PB.BRANCHCOUNTERID, SUM(BILLEDAMOUNT) BILLEDAMOUNT
		, CAST('' AS VARCHAR(50)) PAYMENTMODE
		, ISNULL(SUM(ROUND(BMDCASH.MOPVALUE, 0)), 0) Cash, ISNULL(SUM(BMDCARD.MOPVALUE), 0) [Card]
		, ISNULL(SUM(BMDPAYTEM.MOPVALUE), 0) PayTM, ISNULL(SUM(BMDSODEX.MOPVALUE), 0) Sodexo
		, ISNULL(SUM(BMDBHARATHPAY.MOPVALUE), 0) BharathPay, ISNULL(SUM(BMDUPI.MOPVALUE), 0) UPI
		, ISNULL(SUM(BMDB2BCREDIT.MOPVALUE), 0) B2BCredit, ISNULL(SUM(BMDB2CCREDIT.MOPVALUE), 0) B2CCredit
		, ISNULL(SUM(BMDQRPAY.MOPVALUE), 0) QRPAY, CAST(0 AS DECIMAL(18, 2)) DIFF
	INTO #CPB
	FROM POS_BILL PB WITH(NOLOCK)
		INNER JOIN 
			(
				SELECT PBINNER.BILLID, PBINNER.BRANCHCOUNTERID, SUM(PBDINNER.BILLEDAMOUNT) BILLEDAMOUNT
				FROM
					POS_BILLDETAIL PBDINNER WITH(NOLOCK)
					INNER JOIN POS_BILL PBINNER WITH(NOLOCK) ON PBINNER.BILLID = PBDINNER.BILLID AND PBINNER.BRANCHCOUNTERID = PBDINNER.BRANCHCOUNTERID
				WHERE 
					PBINNER.BILLSTATUS = 1
					AND PBDINNER.DELETEDDATE IS NULL
					AND PBINNER.CREATEDDATE > @FromDate
					AND PBINNER.CREATEDDATE < @ToDate
				GROUP BY PBINNER.BILLID, PBINNER.BRANCHCOUNTERID
			) PBD ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN dbo.SplitString(@BranchID,',') B ON BC.BRANCHID = B.ITEM
		LEFT JOIN POS_BILLMOPDETAIL BMDCASH WITH(NOLOCK) ON BMDCASH.BILLID = PB.BILLID AND BMDCASH.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDCASH.MOPID = 1
		LEFT JOIN POS_BILLMOPDETAIL BMDCARD WITH(NOLOCK) ON BMDCARD.BILLID = PB.BILLID AND BMDCARD.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDCARD.MOPID = 2
		LEFT JOIN POS_BILLMOPDETAIL BMDPAYTEM WITH(NOLOCK) ON BMDPAYTEM.BILLID = PB.BILLID AND BMDPAYTEM.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDPAYTEM.MOPID = 3
		LEFT JOIN POS_BILLMOPDETAIL BMDSODEX WITH(NOLOCK) ON BMDSODEX.BILLID = PB.BILLID AND BMDSODEX.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDSODEX.MOPID = 1003
		LEFT JOIN POS_BILLMOPDETAIL BMDBHARATHPAY WITH(NOLOCK) ON BMDBHARATHPAY.BILLID = PB.BILLID AND BMDBHARATHPAY.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDBHARATHPAY.MOPID = 1006
		LEFT JOIN POS_BILLMOPDETAIL BMDUPI WITH(NOLOCK) ON BMDUPI.BILLID = PB.BILLID AND BMDUPI.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDUPI.MOPID = 1009
		LEFT JOIN POS_BILLMOPDETAIL BMDB2BCREDIT WITH(NOLOCK) ON BMDB2BCREDIT.BILLID = PB.BILLID AND BMDB2BCREDIT.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDB2BCREDIT.MOPID = 1007
		LEFT JOIN POS_BILLMOPDETAIL BMDB2CCREDIT WITH(NOLOCK) ON BMDB2CCREDIT.BILLID = PB.BILLID AND BMDB2CCREDIT.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDB2CCREDIT.MOPID = 1010
		LEFT JOIN POS_BILLMOPDETAIL BMDQRPAY WITH(NOLOCK) ON BMDQRPAY.BILLID = PB.BILLID AND BMDQRPAY.COUNTERID = PB.BRANCHCOUNTERID 
			AND @IncludePaymentMode = 1 AND BMDQRPAY.MOPID = 1011
	WHERE
		PB.BILLSTATUS = 1		
		AND PB.CREATEDDATE > @FromDate
		AND PB.CREATEDDATE < @ToDate
	GROUP BY PB.BILLID, PB.BRANCHCOUNTERID

	IF @IncludePaymentMode = 1
	BEGIN

		UPDATE #CPB
		SET DIFF = BILLEDAMOUNT - (Cash + [Card] + PayTM + Sodexo + BharathPay + UPI + B2BCredit + B2CCredit + QRPAY)

		UPDATE #CPB
		SET PAYMENTMODE = CASE
				WHEN Cash <> 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'Cash'
				WHEN Cash = 0 AND [Card] <> 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'Card'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM <> 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'PayTM'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo <> 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'Sodexo'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay <> 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'BharathPay'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI <> 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'UPI'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit <> 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'B2B Credit'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit <> 0 AND QRPAY = 0 THEN 'B2C Credit'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY <> 0 THEN 'QR Pay'
				WHEN Cash = 0 AND [Card] = 0 AND PayTM = 0 AND Sodexo = 0 AND BharathPay = 0 AND UPI = 0 AND B2BCredit = 0 AND B2CCredit = 0 AND QRPAY = 0 THEN 'None'
				ELSE 'Multiple'
			END
		
	END
	
	SELECT 
		CASE WHEN @IncludeDate = 1 THEN CAST(PB.CREATEDDATE AS DATE) ELSE NULL END CREATEDDATE,
		CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END BRANCHID,
		CASE WHEN @IncludeBranchCounter = 1 THEN BC.COUNTERID ELSE NULL END BRANCHCOUNTERID,
		CASE WHEN @IncludeUser = 1 THEN PB.CREATEDBY ELSE NULL END CREATEDBY,
		CASE WHEN @IncludeBillMode = 1 THEN ISNULL(PB.ISDOORDELIVERY, 0) ELSE NULL END ISDOORDELIVERY,
		CASE WHEN @IncludeBillDetails = 1 THEN CPB.BILLID ELSE NULL END BILLID,		
		SUM(CPB.BILLEDAMOUNT) BILLEDAMOUNT, CASE WHEN @IncludePaymentMode = 1 THEN CPB.PAYMENTMODE ELSE NULL END PAYMENTMODE
		, COUNT(1) COUNTVALUE, CAST(SUM(CPB.BILLEDAMOUNT) / COUNT(1) AS DECIMAL(18, 2)) AVERAGEVALUE
		, SUM(Cash) Cash, SUM([Card]) [Card], SUM(PayTM) PayTM, SUM(Sodexo) Sodexo, SUM(BharathPay) BharathPay
		, SUM(UPI) UPI, SUM(B2BCredit) B2BCredit, SUM(B2CCredit) B2CCredit, SUM(QRPAY) QRPay, SUM(DIFF) Diff
	INTO #GROUPEDBILLDATA
	FROM
		#CPB CPB
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CPB.BRANCHCOUNTERID
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = CPB.BILLID AND PB.BRANCHCOUNTERID = CPB.BRANCHCOUNTERID
	GROUP BY 
		CASE WHEN @IncludeDate = 1 THEN CAST(PB.CREATEDDATE AS DATE) ELSE NULL END,
		CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END,
		CASE WHEN @IncludeBranchCounter = 1 THEN BC.COUNTERID ELSE NULL END,
		CASE WHEN @IncludeUser = 1 THEN PB.CREATEDBY ELSE NULL END,
		CASE WHEN @IncludeBillMode = 1 THEN ISNULL(PB.ISDOORDELIVERY, 0) ELSE NULL END,
		CASE WHEN @IncludeBillDetails = 1 THEN CPB.BILLID ELSE NULL END,
		CASE WHEN @IncludePaymentMode = 1 THEN CPB.PAYMENTMODE ELSE NULL END
		

	SELECT 
		GBD.CREATEDDATE, B.BRANCHNAME, BC.COUNTERNAME, CU.FULLNAME AS CREATEDBY, PB.BILLNUMBER, GBD.BILLEDAMOUNT
		, CASE WHEN @IncludeBillMode = 0 AND @IncludeBillDetails = 0 THEN NULL ELSE
			CASE WHEN ISNULL(GBD.ISDOORDELIVERY, PB.ISDOORDELIVERY) = 1 THEN 'Door Delivery' ELSE 'Walkin' END END BILLMODE
		, PB.CUSTOMERNAME, PB.CUSTOMERGST, CASE WHEN PB.ISIGSTBILL = 1 THEN 'Yes' ELSE 'No' END IsIGSTBill
		, CASE WHEN PB.CUSTOMERNUMBER IS NOT NULL AND @UnmaskCustomerPhone = 0 THEN 'XXXXXX' + RIGHT(PB.CUSTOMERNUMBER, 4) ELSE PB.CUSTOMERNUMBER END CUSTOMERNUMBER
		, CAST(PB.BILLCLOSEDDATE AS TIME) CREATEDTIME, GBD.BILLID, GBD.BRANCHCOUNTERID, GBD.COUNTVALUE, GBD.AVERAGEVALUE
		, PAYMENTMODE, Cash, [Card], PayTM, Sodexo, BharathPay, UPI, B2BCredit, B2CCredit, QRPay, Diff 'Diff.'
	FROM
		#GROUPEDBILLDATA GBD
		LEFT JOIN BRANCH B ON B.BRANCHID = GBD.BRANCHID
		LEFT JOIN BRANCHCOUNTER BC ON BC.COUNTERID = GBD.BRANCHCOUNTERID
		LEFT JOIN TBLUSER CU ON CU.USERID = GBD.CREATEDBY
		LEFT JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = GBD.BILLID AND PB.BRANCHCOUNTERID = GBD.BRANCHCOUNTERID		
	WHERE GBD.BILLEDAMOUNT >= @CutOff OR @CutOff = 0

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BILLNUMINFO2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_BILLNUMINFO2]
(
	@FromDate DATE, 
	@ToDate DATE,
	@BranchID VARCHAR(500),
	@CutOff DECIMAL(9, 2) = 0,
	@UnmaskCustomerPhone BIT = 0,
	@ItemID INT = 0,
	@IncludeDate BIT = 0,
	@IncludeBranch BIT = 0,
	@IncludeBranchCounter BIT = 0,
	@IncludeUser BIT = 0,
	@IncludeBillDetails BIT = 0,
	@IncludeBillMode BIT = 0,
	@IncludePaymentMode BIT = 0,
	@IncludeCountAndAvg BIT = 0
)
AS
BEGIN

	IF @IncludePaymentMode = 1 AND @IncludeBillDetails = 1
	BEGIN
		RAISERROR('Bill details and Payment mode cannot be used together', 5000, 1) WITH LOG
		RETURN
	END

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT PB.BILLID, PB.BRANCHCOUNTERID, 
		SUM(CASE WHEN @IncludePaymentMode = 1 THEN BMD.MOPVALUE ELSE PBD.BILLEDAMOUNT END) AMOUNT,
		CASE WHEN @IncludePaymentMode = 1 THEN BMD.MOPID ELSE NULL END MOPID		
	INTO #CPB
	FROM POS_BILL PB WITH(NOLOCK)
		INNER JOIN 
			(
				SELECT PBINNER.BILLID, PBINNER.BRANCHCOUNTERID, SUM(PBDINNER.BILLEDAMOUNT) BILLEDAMOUNT
				FROM
					POS_BILLDETAIL PBDINNER WITH(NOLOCK)
					INNER JOIN POS_BILL PBINNER WITH(NOLOCK) ON PBINNER.BILLID = PBDINNER.BILLID AND PBINNER.BRANCHCOUNTERID = PBDINNER.BRANCHCOUNTERID
				WHERE 
					PBINNER.BILLSTATUS = 1
					AND PBDINNER.DELETEDDATE IS NULL
					AND PBINNER.CREATEDDATE > @FromDate
					AND PBINNER.CREATEDDATE < @ToDate
				GROUP BY PBINNER.BILLID, PBINNER.BRANCHCOUNTERID
			) PBD ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN dbo.SplitString(@BranchID,',') B ON BC.BRANCHID = B.ITEM
		LEFT JOIN POS_BILLMOPDETAIL BMD WITH(NOLOCK) ON BMD.BILLID = PB.BILLID AND BMD.COUNTERID = PB.BRANCHCOUNTERID AND @IncludePaymentMode = 1
	WHERE
		PB.BILLSTATUS = 1		
		AND PB.CREATEDDATE > @FromDate
		AND PB.CREATEDDATE < @ToDate
	GROUP BY PB.BILLID, PB.BRANCHCOUNTERID, CASE WHEN @IncludePaymentMode = 1 THEN BMD.MOPID ELSE NULL END

	SELECT 
		CASE WHEN @IncludeDate = 1 THEN CAST(PB.CREATEDDATE AS DATE) ELSE NULL END CREATEDDATE,
		CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END BRANCHID,
		CASE WHEN @IncludeBranchCounter = 1 THEN BC.COUNTERID ELSE NULL END BRANCHCOUNTERID,
		CASE WHEN @IncludeUser = 1 THEN PB.CREATEDBY ELSE NULL END CREATEDBY,
		CASE WHEN @IncludeBillMode = 1 THEN ISNULL(PB.ISDOORDELIVERY, 0) ELSE NULL END ISDOORDELIVERY,
		CASE WHEN @IncludeBillDetails = 1 THEN CPB.BILLID ELSE NULL END BILLID,
		CASE WHEN @IncludePaymentMode = 1 THEN CPB.MOPID ELSE NULL END MOPID,
		SUM(CPB.AMOUNT) AMOUNT, COUNT(1) COUNTVALUE, CAST(SUM(CPB.AMOUNT) / COUNT(1) AS DECIMAL(18, 2)) AVERAGEVALUE
	INTO #GROUPEDBILLDATA
	FROM
		#CPB CPB
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CPB.BRANCHCOUNTERID
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = CPB.BILLID AND PB.BRANCHCOUNTERID = CPB.BRANCHCOUNTERID
	GROUP BY 
		CASE WHEN @IncludeDate = 1 THEN CAST(PB.CREATEDDATE AS DATE) ELSE NULL END,
		CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END,
		CASE WHEN @IncludeBranchCounter = 1 THEN BC.COUNTERID ELSE NULL END,
		CASE WHEN @IncludeUser = 1 THEN PB.CREATEDBY ELSE NULL END,
		CASE WHEN @IncludeBillMode = 1 THEN ISNULL(PB.ISDOORDELIVERY, 0) ELSE NULL END,
		CASE WHEN @IncludeBillDetails = 1 THEN CPB.BILLID ELSE NULL END,
		CASE WHEN @IncludePaymentMode = 1 THEN CPB.MOPID ELSE NULL END
		

	SELECT 
		GBD.CREATEDDATE, B.BRANCHNAME, BC.COUNTERNAME, CU.FULLNAME AS CREATEDBY, PB.BILLNUMBER, MOP.MOPNAME, GBD.AMOUNT
		, CASE WHEN @IncludeBillMode = 0 AND @IncludeBillDetails = 0 THEN NULL ELSE
			CASE WHEN ISNULL(GBD.ISDOORDELIVERY, PB.ISDOORDELIVERY) = 1 THEN 'Door Delivery' ELSE 'Walkin' END END BILLMODE
		, PB.CUSTOMERNAME, PB.CUSTOMERGST, 
		CASE WHEN PB.CUSTOMERNUMBER IS NOT NULL AND @UnmaskCustomerPhone = 0 THEN 'XXXXXX' + RIGHT(PB.CUSTOMERNUMBER, 4) ELSE PB.CUSTOMERNUMBER END CUSTOMERNUMBER, 
		BILLMOP.MOPNAME AS BILLMOPNAME, CAST(PB.CREATEDDATE AS TIME) CREATEDTIME
		, GBD.BILLID, GBD.BRANCHCOUNTERID, GBD.COUNTVALUE, GBD.AVERAGEVALUE
	FROM
		#GROUPEDBILLDATA GBD
		LEFT JOIN BRANCH B ON B.BRANCHID = GBD.BRANCHID
		LEFT JOIN BRANCHCOUNTER BC ON BC.COUNTERID = GBD.BRANCHCOUNTERID
		LEFT JOIN TBLUSER CU ON CU.USERID = GBD.CREATEDBY
		LEFT JOIN TBLMOP MOP ON MOP.MOPID = GBD.MOPID
		LEFT JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = GBD.BILLID AND PB.BRANCHCOUNTERID = GBD.BRANCHCOUNTERID
		LEFT JOIN POS_BILLMOPDETAIL BMD WITH(NOLOCK) ON BMD.BILLID = GBD.BILLID AND BMD.COUNTERID = GBD.BRANCHCOUNTERID
			AND NOT EXISTS
				(
					SELECT 1
					FROM POS_BILLMOPDETAIL BMDINNER WITH(NOLOCK)
					WHERE 
						BMDINNER.BILLID = BMD.BILLID
						AND BMDINNER.COUNTERID = BMD.COUNTERID
						AND BMDINNER.MOPID <> BMD.MOPID
				)
		LEFT JOIN TBLMOP BILLMOP ON BILLMOP.MOPID = BMD.MOPID
	WHERE GBD.AMOUNT >= @CutOff OR @CutOff = 0

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BRANCHINDENT_AVG]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_BRANCHINDENT_AVG]
@BranchID INT,
@CategoryID INT,
@NoOfDays INT = 1,
@ISMobileCall bit = 0,
@IsDSD BIT = 0,
@ManufacturerID INT = NULL,
@SupplierID INT = NULL
AS
BEGIN

	CREATE TABLE #SUPPLIERITEMS(ITEMID INT, STOCKENTRYDETAILID INT)

	INSERT INTO #SUPPLIERITEMS
	SELECT I.ITEMID, MAX(SED.STOCKENTRYDETAILID) STOCKENTRYDETAILID
	FROM 
		STOCKENTRYDETAIL SED WITH(NOLOCK)
		INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
	WHERE 
		@IsDSD = 1
		AND I.CATEGORYID = @CategoryID
		AND I.DELETEDDATE IS NULL
		AND SE.DELETEDDATE IS NULL
		AND SED.DELETEDDATE IS NULL
		AND SE.SUPPLIERID = @SupplierID
	GROUP BY I.ITEMID
	
	
	SELECT 
		I.ITEMID, I.SKUCODE, I.ITEMNAME, SUBCAT.SUBCATEGORYID, SUBCAT.SUBCATEGORYNAME
		, I.BRANDID, i.MANUFACTURERID, BS.BRANCHSTOCK
		, IL.DESIREDQUANTITY, IL.THRESHOLD, CAST(0.00 AS decimal(18, 2)) INDENTQUANTITY
		, CAST(NULL AS DATETIME) LASTDISPATCHDATE, CAST(0.00 AS DECIMAL(18, 2)) WHSTOCK		
	INTO #INDENT
	FROM
		ITEM I WITH(NOLOCK) 
		INNER JOIN 
			(
				SELECT IC.ITEMID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) BRANCHSTOCK					
				FROM STOCKSUMMARY SSINNER WITH(NOLOCK)
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID 
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				WHERE SSINNER.BRANCHID = @BranchID
				GROUP BY IC.ITEMID
			) BS ON BS.ITEMID = I.ITEMID
		INNER JOIN INDENTLIMIT IL WITH(NOLOCK) ON IL.ITEMID = I.ITEMID AND IL.BRANCHID = @BranchID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
	WHERE 
		I.DELETEDDATE IS NULL
		AND I.CATEGORYID = @CategoryID
		AND I.ISDSD = @IsDSD
		AND (@IsDSD = 0 OR 
				(I.MANUFACTURERID = @ManufacturerID AND EXISTS 
					(
						SELECT 1 
						FROM #SUPPLIERITEMS SIINNER
						WHERE SIINNER.ITEMID = I.ITEMID
					)
				)
			)
	ORDER BY ITEMNAME

	UPDATE I
	SET I.BRANCHSTOCK = I.BRANCHSTOCK + SDDOUTER.INTRANSITQUANTITY
	FROM 
		#INDENT I
		INNER JOIN 
			(
				SELECT 
					SUM(CASE WHEN I.ISOPENITEM = 1 THEN WEIGHTINKGS ELSE DISPATCHQUANTITY END) AS INTRANSITQUANTITY, 
					I.ITEMID
				FROM STOCKDISPATCHDETAIL SDD
					INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE SD.TOBRANCHID = @BranchID
					AND SD.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
					AND ISNULL(SDD.ISACCEPTED,0) = 0
				GROUP BY I.ITEMID
			) SDDOUTER ON SDDOUTER.ITEMID = I.ITEMID

	UPDATE #INDENT 
	SET INDENTQUANTITY = DESIREDQUANTITY - (CASE WHEN  BRANCHSTOCK > 0 THEN BRANCHSTOCK ELSE 0 END)
	WHERE BRANCHSTOCK <= THRESHOLD

		
	UPDATE #INDENT
	SET INDENTQUANTITY = DESIREDQUANTITY
	WHERE BRANCHSTOCK < 0 -- Send all negatives, since sale is there and we think stock is wrong send them
		
	UPDATE #INDENT
	SET INDENTQUANTITY =
		CASE WHEN INDENTQUANTITY > 5 THEN CAST(CEILING((INDENTQUANTITY * 1.00 / 5)) AS INT) * 5
		ELSE ROUND(INDENTQUANTITY, 0) END
	 

	DELETE #INDENT WHERE INDENTQUANTITY <= 0

	UPDATE I
	SET I.LASTDISPATCHDATE = LSD.LASTDISPATCHDATE
	FROM	
		#INDENT I		
		INNER JOIN 
			(
				SELECT IC.ITEMID, MAX(SD.CREATEDDATE) LASTDISPATCHDATE
				FROM
					STOCKDISPATCHDETAIL SDD WITH(NOLOCK) 
					INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
				WHERE
					SD.STATUS IN (1, 2) AND SD.DELETEDDATE IS NULL AND SDD.DELETEDDATE IS NULL AND SD.TOBRANCHID = @BranchID
				GROUP BY IC.ITEMID
			) LSD ON LSD.ITEMID = I.ITEMID
			
	UPDATE BI
	SET BI.WHSTOCK = WHSTOCK.WHSTOCK
	FROM 
			#INDENT BI
			LEFT JOIN 
				(
					SELECT I.ITEMID
						, CAST(ISNULL(SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END)
							, 0) AS DECIMAL(18, 2)) WHSTOCK
					FROM 
						ITEM I WITH(NOLOCK) 
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMID = I.ITEMID
						INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN STOCKSUMMARY SS WITH(NOLOCK) ON SS.ITEMPRICEID = IP.ITEMPRICEID
					WHERE SS.BRANCHID = 45
					GROUP BY I.ITEMID

				) WHSTOCK ON WHSTOCK.ITEMID = BI.ITEMID

	IF(@ISMobileCall = 1)
	BEGIN

		DECLARE @BranchName VARCHAR(200), @CategoryName VARCHAR(200), @SubCategoryName VARCHAR(200)

		SELECT @BranchName = BRANCHNAME FROM BRANCH WHERE BRANCHID = @BranchID
		SELECT @CategoryName = CATEGORYNAME FROM TBLCATEGORY WHERE CATEGORYID = @CategoryID
		
		SELECT 
			0 AS PARENTID, 
			0 AS STOCKDISPATCHID,
			45 AS FROMBRANCHID, 
			@BranchID AS TOBRANCHID, 
			@CategoryID AS CATEGORYID, 
			@CategoryName AS CATEGORYNAME, 
			@BranchName AS TOBRANCHNAME, 
			@NoOfDays AS NOOFDAYS

	END

	SELECT 
		0 AS PARENTID, BI.ITEMID, BI.SKUCODE, BI.ITEMNAME, SUBCATEGORYNAME, BRND.BRANDNAME, MFR.MANUFACTURERNAME
		, BRANCHSTOCK, 0 AS AVGSALES, 0 AS NOOFDAYSSALES, THRESHOLD Threshold, DESIREDQUANTITY DesiredQuantity
		, INDENTQUANTITY, LASTDISPATCHDATE, BI.SUBCATEGORYID, BI.WHSTOCK, IP.MRP, ICP.COSTPRICEWT
	FROM 
		#INDENT BI
		LEFT JOIN TBLBRAND BRND WITH(NOLOCK) ON BRND.BRANDID = BI.BRANDID
		LEFT JOIN TBLMANUFACTURER MFR WITH(NOLOCK) ON MFR.MANUFACTURERID = BI.MANUFACTURERID
		LEFT JOIN #SUPPLIERITEMS SI ON SI.ITEMID = BI.ITEMID AND @IsDSD = 1	
		LEFT JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.STOCKENTRYDETAILID = SI.STOCKENTRYDETAILID
		LEFT JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
	ORDER BY SUBCATEGORYNAME, BI.ITEMNAME
	



/*
	DECLARE 
		@SixthMonthFromDate DATE = DATEADD(m, -6, GETDATE()),
		@FifthMonthFromDate DATE = DATEADD(m, -5, GETDATE()),
		@FourthMonthFromDate DATE = DATEADD(m, -4, GETDATE()),
		@ThirdMonthFromDate DATE = DATEADD(m, -3, GETDATE()),
		@SecondMonthFromDate DATE = DATEADD(m, -2, GETDATE()),
		@FirstMonthFromDate DATE = DATEADD(m, -1, GETDATE())
		, @IndentSaleFromDate DATE = GETDATE() - @NoOfDays

	DECLARE 
		@SixthMonthToDate DATE = DATEADD(d, @NoOfDays, @SixthMonthFromDate),
		@FifthMonthToDate DATE = DATEADD(d, @NoOfDays, @FifthMonthFromDate),
		@FourthMonthToDate DATE = DATEADD(d, @NoOfDays, @FourthMonthFromDate),
		@ThirdMonthToDate DATE = DATEADD(d, @NoOfDays, @ThirdMonthFromDate),
		@SecondMonthToDate DATE = DATEADD(d, @NoOfDays, @SecondMonthFromDate),
		@FirstMonthToDate DATE = DATEADD(d, @NoOfDays, @FirstMonthFromDate)
	
	SELECT 
		I.ITEMID, I.SKUCODE, I.ITEMNAME, SUBCAT.SUBCATEGORYID, SUBCAT.SUBCATEGORYNAME, BS.BRANCHSTOCK
		, ITEMSALE.SixthMonthSale, ITEMSALE.FifthMonthSale, ITEMSALE.FourthMonthSale
		, ITEMSALE.ThirdMonthSale, ITEMSALE.SecondMonthSale, ITEMSALE.FirstMonthSale
		, ISNULL(ITEMSALE.AvgSale, 0) AvgSale, ITEMINDENTSALE.INDENTDAYSSALEQUANTITY
		, CAST(0.00 AS decimal(13, 2)) MAXSALE
		, CAST(0.00 AS decimal(13, 2)) INDENTQUANTITY
		, 0 AS ISINDENTNEEDED, CAST(NULL AS DATETIME) LASTDISPATCHDATE, CAST(0.00 AS DECIMAL(18, 2)) WHSTOCK
	INTO #INDENT
	FROM
		ITEM I 
		INNER JOIN 
			(
				SELECT IC.ITEMID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) BRANCHSTOCK					
				FROM STOCKSUMMARY SSINNER 
					INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID 
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE SSINNER.BRANCHID = @BranchID
				GROUP BY IC.ITEMID
			) BS ON BS.ITEMID = I.ITEMID
		LEFT JOIN	
			(
				SELECT IC.ITEMID
					, ISNULL(SUM(CASE WHEN PB.CREATEDDATE >= @SixthMonthFromDate AND PB.CREATEDDATE <= @SixthMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END), 0) SixthMonthSale
					, ISNULL(SUM(CASE WHEN PB.CREATEDDATE >= @FifthMonthFromDate AND PB.CREATEDDATE <= @FifthMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END), 0) FifthMonthSale
					, ISNULL(SUM(CASE WHEN PB.CREATEDDATE >= @FourthMonthFromDate AND PB.CREATEDDATE <= @FourthMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END), 0) FourthMonthSale
					, ISNULL(SUM(CASE WHEN PB.CREATEDDATE >= @ThirdMonthFromDate AND PB.CREATEDDATE <= @ThirdMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END), 0) ThirdMonthSale
					, ISNULL(SUM(CASE WHEN PB.CREATEDDATE >= @SecondMonthFromDate AND PB.CREATEDDATE <= @SecondMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END), 0) SecondMonthSale
					, ISNULL(SUM(CASE WHEN PB.CREATEDDATE >= @FirstMonthFromDate AND PB.CREATEDDATE <= @FirstMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END), 0) FirstMonthSale
					, CEILING(ISNULL(SUM(CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END), 0) / 6) AvgSale
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE
					BC.BRANCHID = @BranchID
					AND I.CATEGORYID = @CategoryID					
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND 
						(
							(PB.CREATEDDATE >= @SixthMonthFromDate AND PB.CREATEDDATE <= @SixthMonthToDate)
							OR (PB.CREATEDDATE >= @FifthMonthFromDate AND PB.CREATEDDATE <= @FifthMonthToDate)
							OR (PB.CREATEDDATE >= @FourthMonthFromDate AND PB.CREATEDDATE <= @FourthMonthToDate)
							OR (PB.CREATEDDATE >= @ThirdMonthFromDate AND PB.CREATEDDATE <= @ThirdMonthToDate)
							OR (PB.CREATEDDATE >= @SecondMonthFromDate AND PB.CREATEDDATE <= @SecondMonthToDate)
							OR (PB.CREATEDDATE >= @FirstMonthFromDate AND PB.CREATEDDATE <= @FirstMonthToDate)
						)
				GROUP BY IC.ITEMID
			) ITEMSALE ON ITEMSALE.ITEMID = I.ITEMID
		LEFT JOIN	
			(
				SELECT IC.ITEMID
					, CAST(ROUND((CASE WHEN I.ISOPENITEM = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END), 2) AS DECIMAL(18, 2)) AS INDENTDAYSSALEQUANTITY
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE
					BC.BRANCHID = @BranchID
					AND I.CATEGORYID = @CategoryID
					AND PB.CREATEDDATE >= @IndentSaleFromDate
					--AND PB.CREATEDDATE <= @ToDate
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
				GROUP BY IC.ITEMID, I.ISOPENITEM
			) ITEMINDENTSALE ON ITEMINDENTSALE.ITEMID = I.ITEMID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
	--WHERE (ITEMSALE.AvgSale - BS.BRANCHSTOCK) > 0 OR BS.BRANCHSTOCK < 0
	WHERE I.DELETEDDATE IS NULL
	ORDER BY ITEMNAME

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)
	UPDATE #INDENT SET MAXSALE = CASE WHEN AvgSale > INDENTDAYSSALEQUANTITY THEN AvgSale ELSE INDENTDAYSSALEQUANTITY END

	UPDATE #INDENT SET INDENTQUANTITY = MAXSALE - (CASE WHEN  BRANCHSTOCK > 0 THEN BRANCHSTOCK ELSE 0 END)

	UPDATE #INDENT
	SET INDENTQUANTITY = 5 
	WHERE INDENTQUANTITY > 0 AND INDENTQUANTITY < 5

	UPDATE #INDENT
	SET INDENTQUANTITY = 5 
	WHERE MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5
	
	UPDATE #INDENT
	SET INDENTQUANTITY = CAST(CEILING((INDENTQUANTITY * 1.00 / 5)) AS INT) * 5
	WHERE INDENTQUANTITY > 0 

	UPDATE I
	SET I.LASTDISPATCHDATE = LSD.LASTDISPATCHDATE
	FROM	
		#INDENT I		
		INNER JOIN 
			(
				SELECT IC.ITEMID, MAX(SD.CREATEDDATE) LASTDISPATCHDATE
				FROM
					STOCKDISPATCHDETAIL SDD 
					INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				WHERE
					SD.STATUS IN (1, 2) AND SD.DELETEDDATE IS NULL AND SDD.DELETEDDATE IS NULL AND SD.TOBRANCHID = @BranchID
				GROUP BY IC.ITEMID
			) LSD ON LSD.ITEMID = I.ITEMID

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)

	DELETE #INDENT WHERE AvgSale = 0 AND INDENTDAYSSALEQUANTITY = 0

	UPDATE #INDENT
	SET ISINDENTNEEDED = 1, INDENTQUANTITY = MAXSALE
	WHERE BRANCHSTOCK <= 0 -- Send all negatives, since sale is there and we think stock is wrong send them

	UPDATE #INDENT
	SET ISINDENTNEEDED = CASE
							WHEN MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5 THEN 1  
							WHEN INDENTDAYSSALEQUANTITY = 0 OR BRANCHSTOCK < INDENTDAYSSALEQUANTITY * 1.5 THEN 1
						ELSE 0 END
	WHERE ISINDENTNEEDED = 0 AND ISNULL(MAXSALE, 0) > BRANCHSTOCK

	UPDATE BI
	SET BI.WHSTOCK = WHSTOCK.WHSTOCK
	FROM 
			#INDENT BI
			LEFT JOIN 
				(
					SELECT I.ITEMID
						, CAST(ISNULL(SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END)
							, 0) AS DECIMAL(18, 2)) WHSTOCK
					FROM 
						ITEM I 
						INNER JOIN ITEMCODE IC ON IC.ITEMID = I.ITEMID
						INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID
					WHERE SS.BRANCHID = 45
					GROUP BY I.ITEMID

				) WHSTOCK ON WHSTOCK.ITEMID = BI.ITEMID

	IF(@ISMobileCall = 1)
	BEGIN

		DECLARE @BranchName VARCHAR(200), @CategoryName VARCHAR(200), @SubCategoryName VARCHAR(200)

		SELECT @BranchName = BRANCHNAME FROM BRANCH WHERE BRANCHID = @BranchID
		SELECT @CategoryName = CATEGORYNAME FROM TBLCATEGORY WHERE CATEGORYID = @CategoryID
		
		SELECT 
			0 AS PARENTID, 
			0 AS STOCKDISPATCHID,
			45 AS FROMBRANCHID, 
			@BranchID AS TOBRANCHID, 
			@CategoryID AS CATEGORYID, 
			@CategoryName AS CATEGORYNAME, 
			@BranchName AS TOBRANCHNAME, 
			@NoOfDays AS NOOFDAYS

		SELECT 
			0 AS PARENTID, BI.ITEMID, BI.SKUCODE, BI.ITEMNAME, SUBCATEGORYNAME, BRANCHSTOCK, AvgSale AS AVGSALES,
			INDENTDAYSSALEQUANTITY AS NOOFDAYSSALES, INDENTQUANTITY, LASTDISPATCHDATE, BI.SUBCATEGORYID, BI.WHSTOCK
		FROM 
			#INDENT BI
		WHERE ISINDENTNEEDED = 1 ORDER BY SUBCATEGORYNAME, BI.ITEMNAME

	END
	ELSE
	BEGIN
		DECLARE @SelectQuery VARCHAR(MAX)
		SELECT @SelectQuery = ' SELECT 0 AS PARENTID, I.ITEMID, I.SKUCODE, I.ITEMNAME, I.SUBCATEGORYNAME, I.BRANCHSTOCK'
		SELECT @SelectQuery = @SelectQuery + ', I.SixthMonthSale AS ''' + CAST(@SixthMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@SixthMonthToDate AS VARCHAR(20)) + ''''
		SELECT @SelectQuery = @SelectQuery + ', I.FifthMonthSale AS ''' + CAST(@FifthMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@FifthMonthToDate AS VARCHAR(20)) + ''''
		SELECT @SelectQuery = @SelectQuery + ', I.FourthMonthSale AS ''' + CAST(@FourthMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@FourthMonthToDate AS VARCHAR(20)) + ''''
		SELECT @SelectQuery = @SelectQuery + ', I.ThirdMonthSale AS ''' + CAST(@ThirdMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@ThirdMonthToDate AS VARCHAR(20)) + ''''
		SELECT @SelectQuery = @SelectQuery + ', I.SecondMonthSale AS ''' + CAST(@SecondMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@SecondMonthToDate AS VARCHAR(20)) + ''''
		SELECT @SelectQuery = @SelectQuery + ', I.FirstMonthSale AS ''' + CAST(@FirstMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@FirstMonthToDate AS VARCHAR(20)) + ''''

		SELECT @SelectQuery = @SelectQuery + ', I.AvgSale AS ''Average Sale (6M)'', I.INDENTDAYSSALEQUANTITY AS ''Last ' + CAST(@NoOfDays AS VARCHAR(20)) + ' days sale'''
		
		SELECT @SelectQuery = @SelectQuery + ', I.AvgSale AS AVGSALES, I.INDENTDAYSSALEQUANTITY AS NOOFDAYSSALES, I.INDENTQUANTITY, I.LASTDISPATCHDATE, I.SUBCATEGORYID, I.WHSTOCK'

		SELECT @SelectQuery = @SelectQuery + ' FROM #INDENT I WHERE I.ISINDENTNEEDED = 1 ORDER BY I.SUBCATEGORYNAME, I.ITEMNAME'
		
	
		EXEC (@SelectQuery)
	END

	--SELECT @Multiplier = (CASE 
	--		WHEN DAY(GETDATE()) <= 5 THEN 70
	--		WHEN DAY(GETDATE()) <= 15 THEN 60
	--		ELSE 50 END / 100.00)
	
	--SELECT ITEMID, SKUCODE, ITEMNAME, SUBCATEGORYNAME, BRANCHSTOCK, SALEQUANTITY, AVGSALEQUANTITY
	--	, CASE INDENTQUANTITY WHEN 0 THEN 1 ELSE INDENTQUANTITY END AS INDENTQUANTITY
	--FROM
	--	(
	--		SELECT 
	--			I.ITEMID, I.SKUCODE, I.ITEMNAME, SUBCAT.SUBCATEGORYNAME
	--			, BS.QUANTITY AS BRANCHSTOCK, ITEMSALE.SALEQUANTITY, ITEMSALE.AVGSALEQUANTITY
	--			,  CAST(ROUND((CASE 
	--					WHEN  BS.QUANTITY < 0 THEN (ITEMSALE.AVGSALEQUANTITY)
	--					ELSE ((ITEMSALE.AVGSALEQUANTITY) - (BS.QUANTITY))
	--				END  * 1.00 / 1), 0) AS INT) * 1 AS INDENTQUANTITY	
	--		FROM ITEM I 
	--			INNER JOIN 
	--				(
	--					SELECT IC.ITEMID, SUM(SSINNER.QUANTITY) AS QUANTITY, SUM(SSINNER.WEIGHTINKGS) AS WEIGHTINKGS 
	--					FROM STOCKSUMMARY SSINNER 
	--						INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
	--						INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID 
	--					WHERE SSINNER.BRANCHID = @BranchID
	--					GROUP BY IC.ITEMID
	--				) BS ON BS.ITEMID = I.ITEMID
	--			INNER JOIN	
	--				(
	--					SELECT IC.ITEMID, SUM(PBD.QUANTITY) SALEQUANTITY, CAST(ROUND(((SUM(PBD.QUANTITY) / 60.00) * @NoOfDays), 2) AS DECIMAL(18, 2)) AS AVGSALEQUANTITY							
	--						, SUM(PBD.WEIGHTINKGS) AS SALEWEIGHTINKGS
	--					FROM 
	--						POS_BILLDETAIL PBD
	--						INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
	--						INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
	--						INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
	--						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	--						INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	--					WHERE
	--						BC.BRANCHID = @BranchID
	--						AND I.CATEGORYID = @CategoryID
	--						AND PB.CREATEDDATE >= @FromDate
	--						AND PB.CREATEDDATE <= @ToDate
	--						AND PB.BILLSTATUS = 1
	--						AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
	--					GROUP BY IC.ITEMID
	--				) ITEMSALE ON ITEMSALE.ITEMID = I.ITEMID
	--			LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
