/****** Object:  StoredProcedure [dbo].[USP_RPT_BRANCHINDENT_AVG_60CAPPED]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_RPT_BRANCHINDENT_AVG_60CAPPED]
@BranchID INT,
@CategoryID INT,
@NoOfDays INT = 1,
@ISMobileCall bit = 0
AS
BEGIN

	DECLARE 
		@SixthMonthFromDate DATE = DATEADD(m, -6, GETDATE())
		, @IndentSaleFromDate DATE = GETDATE() - @NoOfDays

	
	SELECT 
		I.ITEMID, I.SKUCODE, I.ITEMNAME, SUBCAT.SUBCATEGORYID, SUBCAT.SUBCATEGORYNAME, BS.BRANCHSTOCK
		, ITEMSALE.TotalSale, CAST(CEILING(ISNULL(ITEMSALE.TotalSale / 180, 0) * @NoOfDays) AS DECIMAL(18, 2)) AvgSale
		, ITEMINDENTSALE.INDENTDAYSSALEQUANTITY --added as per Vishnu on 17th Jun 2025
		, CAST(0.00 AS decimal(13, 2)) MAXSALE, CAST(0.00 AS decimal(13, 2)) INDENTQUANTITY
		, 0 AS ISINDENTNEEDED, CAST(NULL AS DATETIME) LASTDISPATCHDATE, CAST(0.00 AS DECIMAL(18, 2)) WHSTOCK
		, BRND.BRANDNAME, MFR.MANUFACTURERNAME
	INTO #INDENT
	FROM
		ITEM I 
		INNER JOIN 
			(
				SELECT IC.ITEMID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) BRANCHSTOCK					
				FROM STOCKSUMMARY SSINNER 
					INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID 
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE SSINNER.BRANCHID = @BranchID
				GROUP BY IC.ITEMID
			) BS ON BS.ITEMID = I.ITEMID
		LEFT JOIN	
			(
				SELECT IC.ITEMID , ISNULL(SUM(CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END), 0) TotalSale
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE
					BC.BRANCHID = @BranchID
					AND I.CATEGORYID = @CategoryID					
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND PB.CREATEDDATE >= @SixthMonthFromDate 
				GROUP BY IC.ITEMID
			) ITEMSALE ON ITEMSALE.ITEMID = I.ITEMID
		LEFT JOIN	
			(
				SELECT IC.ITEMID
					, CAST(ROUND((CASE WHEN I.ISOPENITEM = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END), 2) AS DECIMAL(18, 2)) AS INDENTDAYSSALEQUANTITY
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE
					BC.BRANCHID = @BranchID
					AND I.CATEGORYID = @CategoryID
					AND PB.CREATEDDATE >= @IndentSaleFromDate
					--AND PB.CREATEDDATE <= @ToDate
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
				GROUP BY IC.ITEMID, I.ISOPENITEM
			) ITEMINDENTSALE ON ITEMINDENTSALE.ITEMID = I.ITEMID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN TBLBRAND BRND ON BRND.BRANDID = I.BRANDID
		LEFT JOIN TBLMANUFACTURER MFR ON MFR.MANUFACTURERID = I.MANUFACTURERID
	--WHERE (ITEMSALE.AvgSale - BS.BRANCHSTOCK) > 0 OR BS.BRANCHSTOCK < 0
	WHERE I.DELETEDDATE IS NULL
	ORDER BY ITEMNAME

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)

	UPDATE #INDENT SET MAXSALE = ROUND(
		CASE WHEN AvgSale > INDENTDAYSSALEQUANTITY THEN AvgSale 
		ELSE INDENTDAYSSALEQUANTITY END, 0)

	UPDATE #INDENT SET INDENTQUANTITY = MAXSALE - (CASE WHEN  BRANCHSTOCK > 0 THEN BRANCHSTOCK ELSE 0 END)

	--UPDATE #INDENT
	--SET INDENTQUANTITY = 5 
	--WHERE INDENTQUANTITY > 0 AND INDENTQUANTITY < 5

	--UPDATE #INDENT
	--SET INDENTQUANTITY = 5 
	--WHERE MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5
	
	UPDATE #INDENT
	SET INDENTQUANTITY = CAST(CEILING((INDENTQUANTITY * 1.00 / 5)) AS INT) * 5
	WHERE INDENTQUANTITY > 0 

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)

	DELETE #INDENT WHERE AvgSale = 0 AND INDENTDAYSSALEQUANTITY = 0

	UPDATE I
	SET I.LASTDISPATCHDATE = LSD.LASTDISPATCHDATE
	FROM	
		#INDENT I		
		INNER JOIN 
			(
				SELECT IC.ITEMID, MAX(SD.CREATEDDATE) LASTDISPATCHDATE
				FROM
					STOCKDISPATCHDETAIL SDD 
					INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				WHERE
					SD.STATUS IN (1, 2) AND SD.DELETEDDATE IS NULL AND SDD.DELETEDDATE IS NULL AND SD.TOBRANCHID = @BranchID
				GROUP BY IC.ITEMID
			) LSD ON LSD.ITEMID = I.ITEMID


	UPDATE #INDENT
	SET ISINDENTNEEDED = 1, INDENTQUANTITY = MAXSALE
	WHERE BRANCHSTOCK <= 0 -- Send all negatives, since sale is there and we think stock is wrong send them

	UPDATE #INDENT
	SET ISINDENTNEEDED = CASE
							WHEN MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5 THEN 1  
							WHEN INDENTDAYSSALEQUANTITY = 0 OR BRANCHSTOCK < INDENTDAYSSALEQUANTITY THEN 1
							WHEN MAXSALE = AvgSale AND MAXSALE * 0.6 > BRANCHSTOCK THEN 1
						ELSE 0 END
	WHERE ISINDENTNEEDED = 0 AND ISNULL(MAXSALE, 0) > BRANCHSTOCK

	UPDATE BI
	SET BI.WHSTOCK = WHSTOCK.WHSTOCK
	FROM 
			#INDENT BI
			LEFT JOIN 
				(
					SELECT I.ITEMID
						, CAST(ISNULL(SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END)
							, 0) AS DECIMAL(18, 2)) WHSTOCK
					FROM 
						ITEM I 
						INNER JOIN ITEMCODE IC ON IC.ITEMID = I.ITEMID
						INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = IP.ITEMPRICEID
					WHERE SS.BRANCHID = 45
					GROUP BY I.ITEMID

				) WHSTOCK ON WHSTOCK.ITEMID = BI.ITEMID
	WHERE BI.ISINDENTNEEDED = 1

	DECLARE @SelectQuery VARCHAR(MAX)
	SELECT @SelectQuery = ' SELECT 0 AS PARENTID, I.ITEMID, I.SKUCODE, I.ITEMNAME, I.SUBCATEGORYNAME, I.BRANDNAME, I.MANUFACTURERNAME, I.BRANCHSTOCK'
	SELECT @SelectQuery = @SelectQuery + ', I.TotalSale, I.AvgSale AS ''Average Sale ((6M Sale/ 180) * NoOfDays)'', I.INDENTDAYSSALEQUANTITY AS ''Last ' + CAST(@NoOfDays AS VARCHAR(20)) + ' days sale'''
	SELECT @SelectQuery = @SelectQuery + ', I.AvgSale AVGSALES, I.INDENTDAYSSALEQUANTITY NOOFDAYSSALES '
	SELECT @SelectQuery = @SelectQuery + ', I.INDENTQUANTITY, I.LASTDISPATCHDATE, I.SUBCATEGORYID, I.WHSTOCK, I.WHSTOCK ''Warehouse Stock'''
	SELECT @SelectQuery = @SelectQuery + ' FROM #INDENT I WHERE I.ISINDENTNEEDED = 1 ORDER BY I.SUBCATEGORYNAME, I.ITEMNAME'
	
	EXEC (@SelectQuery)

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BRANCHINDENTLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_BRANCHINDENTLIST]
@CATEGORYID INT = 13,
@IsMobileCall BIT = 1,
@FromDate DATETIME = NULL,
@ToDate DATETIME = NULL
AS
BEGIN

	SELECT 
		BI.BRANCHINDENTID, B.BRANCHID, SCAT.SUBCATEGORYID,SCAT.CATEGORYID, ISNULL(SD.STOCKDISPATCHID, 0) AS STOCKDISPATCHID , 
		BI.BRANCHINDENTID AS [Branch Indent #], BI.INDENTMETHOD, B.BRANCHNAME,CAT.CATEGORYNAME,SCAT.SUBCATEGORYNAME, SD.DISPATCHNUMBER,
		CASE WHEN ISNULL(BI.ISCOMPLETED , 0) = 1 THEN 'Closed'
			WHEN ISNULL(SD.STOCKDISPATCHID, 0) > 0 AND SD.STATUS = 0 THEN 'Dispatch In-Progress'
			WHEN ISNULL(SD.STOCKDISPATCHID, 0) > 0 AND SD.STATUS = 1 THEN 'Dispatch Submitted'
			WHEN ISNULL(SD.STOCKDISPATCHID, 0) = 0 THEN 'Dispatch Not Yet Started' END AS INDENTSTATUS,
		BI.CREATEDDATE AS INDENTDATE, SDU.FULLNAME AS DISPATCHBY
	INTO #BIL
	FROM BRANCHINDENT BI
	INNER JOIN BRANCH B ON BI.TOBRANCHID = B.BRANCHID
	INNER JOIN SUBCATEGORY SCAT ON BI.SUBCATEGORYID = SCAT.SUBCATEGORYID
	INNER JOIN TBLCATEGORY CAT ON SCAT.CATEGORYID = CAT.CATEGORYID
	LEFT JOIN STOCKDISPATCH SD ON BI.BRANCHINDENTID = SD.BRANCHINDENTID	 AND SD.DELETEDDATE IS  NULL
	LEFT JOIN TBLUSER SDU ON SD.CREATEDBY = SDU.USERID
	WHERE BI.DELETEDDATE IS NULL
		AND (SCAT.CATEGORYID = @CATEGORYID OR @CATEGORYID = 13)
		AND CAST(BI.CREATEDDATE AS DATE) >= CAST(ISNULL(@FromDate, GETDATE() - 10) AS DATE)
		AND CAST(BI.CREATEDDATE AS DATE) <=  CAST(ISNULL(@ToDate, GETDATE()) AS DATE)
		AND (
				@IsMobileCall = 0 OR 
				(
					ISNULL(BI.ISCOMPLETED, 0) = 0
					AND (
							(ISNULL(SD.STOCKDISPATCHID, 0) = 0)
							OR (ISNULL(SD.STOCKDISPATCHID, 0) > 0 AND SD.STATUS = 0)
						)
				)
			)

	
	IF(@IsMobileCall = 1)
	BEGIN
		SELECT 0 AS PARENTID
	END

	SELECT 0 AS PARENTID, BIL.* FROM #BIL BIL
	ORDER BY BIL.INDENTDATE DESC

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BRANCHSALEBYGST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_BRANCHSALEBYGST]  
(  
 @BranchID INT = 0  
)  
AS  
BEGIN  
  
 SELECT B.BRANCHNAME, B.BRANCHCODE,CAST(DC.CLOSUREDATE AS DATE) AS CLOSUREDATE, GST.GSTCODE, SUM(BD.BILLEDAMOUNT) AS BILLEDVALUE  
 FROM  
  POS_BILL PB  
  INNER JOIN POS_BILLDETAIL BD ON BD.BILLID = PB.BILLID AND PB.BRANCHCOUNTERID = BD.BRANCHCOUNTERID  
  INNER JOIN GSTDETAIL GST ON GST.GSTID = BD.GSTID 
  INNER JOIN POS_DAYCLOSURE DC ON PB.DAYCLOSUREID = DC.DAYCLOSUREID AND PB.BRANCHCOUNTERID = DC.BRANCHCOUNTERID
  INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID  
  INNER JOIN BRANCH B ON B.BRANCHID = BC.BRANCHID  
 WHERE PB.DAYCLOSUREID IS NOT NULL AND BD.DAYCLOSUREID IS NOT NULL 
	 AND PB.DELETEDDATE IS NULL AND BD.DELETEDDATE IS NULL  
	 AND PB.BILLSTATUS = 1 AND (B.BRANCHID = @BranchID OR @BranchID = 0)  
	 GROUP BY BD.GSTID, GST.GSTCODE, B.BRANCHID, B.BRANCHNAME, B.BRANCHCODE,CAST(DC.CLOSUREDATE AS DATE)
	 ORDER BY B.BRANCHCODE, LEN(GST.GSTCODE), GST.GSTCODE  
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BREFUND]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_BREFUND]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(MAX)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeReason Bit = 0
	, @IncludeRefundNumber Bit = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(MAX)
	, @IncludeTrayNumber BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	--DECLARE @CPDate DATE
	--SELECT @CPDate = DATEFROMPARTS(YEAR(@ToDate), MONTH(@ToDate), 1)

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, QUANTITY DECIMAL(18, 2),
		COSTPRICEWOT DECIMAL(18, 2), COSTPRICEWT DECIMAL(18, 2), COSTPRICETAX DECIMAL(18, 2), 
		TOTALCPWOT DECIMAL(18, 2), TOTALCPWT DECIMAL(18, 2), TOTALCPTAX DECIMAL(18, 2), 
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT,
		REASONID INT,BRID INT,REFUNDSTATUS BIT,APPROVEDBY INT, APPROVEDDATE DATETIME, AVGCOSTPRICEID INT, 
		TRAYNUMBER INT, BRANDID INT, MANUFACTURERID INT)

	SELECT BRD.ITEMPRICEID, 
		BR.BRANCHID AS BRANCHID,
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		I.BRANDID,
		I.MANUFACTURERID,
		CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN ISNULL(BRD.ACCEPTEDQUANTITY, BRD.QUANTITY) ELSE ISNULL(BRD.ACCEPTEDWEIGHTKGS, BRD.WEIGHTINKGS) END AS QUANTITY,
		BR.CREATEDATE,
		BRD.REASONID,
		BR.BRID,
		ISNULL(BR.IsAccepted,0) AS IsAccepted,
		CASE WHEN ISNULL(BR.IsAccepted,0) = 1 THEN BR.UPDATEDBY ELSE NULL END AS APPROVEDBY,
		CASE WHEN ISNULL(BR.IsAccepted,0) = 1 THEN BR.UPDATEDDATE ELSE NULL END AS APPROVEDDATE, AICP.AVGCOSTPRICEID, BRD.TRAYNUMBER
	INTO #BRD
	FROM POS_BREFUNDDETAIL BRD
		INNER JOIN POS_BREFUND BR ON BR.BRID = BRD.BRID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID 
		--LEFT JOIN IPICPView IPICP ON IP.ITEMPRICEID = IPICP.ITEMPRICEID
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.ITEMPRICEID = IP.ITEMPRICEID AND AICP.AVGCPDATE = DATEFROMPARTS(YEAR(BR.CREATEDATE), MONTH(BR.CREATEDATE), 1)
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		INNER JOIN #BRANCH B ON BR.BRANCHID =  B.ITEM
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND BR.CREATEDATE > (@FromDate)
		AND BR.CREATEDATE < @ToDate
		AND BRD.DELETEDDATE IS NULL

	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, CATEGORYID,SUBCATEGORYID,
		PERIODOCITY,REASONID,BRID,REFUNDSTATUS,APPROVEDBY,APPROVEDDATE,QUANTITY, AVGCOSTPRICEID
		, TOTALCPWOT, TOTALCPTAX, TOTALCPWT, TRAYNUMBER,BRANDID, MANUFACTURERID)
	SELECT CASE WHEN @IncludeItem = 1 THEN BRD.ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRD.BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN BRD.CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN BRD.SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(BRD.CREATEDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(BRD.CREATEDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(BRD.CREATEDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(BRD.CREATEDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END 
			,CASE WHEN @IncludeReason = 1 THEN BRD.REASONID ELSE NULL END AS REASONID
			,CASE WHEN @IncludeRefundNumber = 1 THEN BRD.BRID ELSE NULL END AS BRID,
			CASE WHEN @IncludeItem = 1 THEN BRD.IsAccepted ELSE NULL END AS IsAccepted,
			CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDBY ELSE NULL END AS APPROVEDBY,
			CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDDATE ELSE NULL END AS APPROVEDDATE,
			SUM(BRD.QUANTITY) AS QUANTITY
			, CASE WHEN @IncludeItem = 1 THEN BRD.AVGCOSTPRICEID ELSE NULL END
			, SUM(AICP.COSTPRICEWOT * BRD.QUANTITY), SUM((AICP.COSTPRICEWT - AICP.COSTPRICEWOT) * BRD.QUANTITY) , SUM(AICP.COSTPRICEWT * BRD.QUANTITY)
			, CASE WHEN @IncludeTrayNumber = 1 THEN BRD.TRAYNUMBER ELSE NULL END
			,CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			,CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	FROM #BRD BRD
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.AVGCOSTPRICEID = BRD.AVGCOSTPRICEID
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN BRD.ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRD.BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN BRD.CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN BRD.SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(BRD.CREATEDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(BRD.CREATEDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(BRD.CREATEDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(BRD.CREATEDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeReason = 1 THEN BRD.REASONID ELSE NULL END
		, CASE WHEN @IncludeRefundNumber = 1 THEN BRD.BRID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.IsAccepted ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDBY ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDDATE ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.AVGCOSTPRICEID ELSE NULL END
		, CASE WHEN @IncludeTrayNumber = 1 THEN BRD.TRAYNUMBER ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	SELECT 
		PT.PERIODOCITY, B.BRANCHNAME, CAT.CATEGORYNAME,SC.SUBCATEGORYNAME,TBR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.VENDORSKUCODE, I.ITEMNAME, IC.ITEMCODE, IC.HSNCODE
		, IP.MRP, GST.GSTCODE, PT.QUANTITY, AICP.COSTPRICEWOT, AICP.COSTPRICETAX, AICP.COSTPRICEWT
		, PT.TOTALCPWOT TOTALCPEWOT, PT.TOTALCPTAX, PT.TOTALCPWT, RFR.REASONNAME AS Reason, BR.BREFUNDNUMBER
		, CASE WHEN REFUNDSTATUS = 0 THEN 'NOT APPROVED' ELSE 'APPROVED' END AS REFUNDSTATUS,
		AU.FULLNAME AS APPROVEDBY, PT.APPROVEDDATE, PT.TRAYNUMBER
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN REASONFORREFUND RFR ON PT.REASONID = RFR.REASONID
		LEFT JOIN POS_BREFUND BR ON PT.BRID = BR.BRID
		LEFT JOIN TBLUSER AU ON PT.APPROVEDBY = AU.USERID
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.AVGCOSTPRICEID = PT.AVGCOSTPRICEID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		LEFT JOIN TBLBRAND TBR ON PT.BRANDID = TBR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BREFUNDS_REJECTEDITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_BREFUNDS_REJECTEDITEMS]
@BRANCHID INT,
@FROMDATE DATETIME,
@TODATE DATETIME
AS
BEGIN

	SELECT 
		I.ITEMID, IC.ITEMCODEID, IP.ITEMPRICEID, I.SKUCODE, IC.ITEMCODE, I.ITEMNAME, 
		CAT.CATEGORYNAME, SCAT.SUBCATEGORYNAME,
		 ICL.CLASSIFICATIONNAME, ISCL.SUBCLASSIFICATIONNAME,IP.MRP, 
		CASE WHEN I.ISOPENITEM = 0 THEN BRD.QUANTITY ELSE BRD.WEIGHTINKGS END REJECTEDQUANTITY, 
		BR.BREFUNDNUMBER, BR.UPDATEDDATE, BR.ACCEPTEDDATE AS REJECTEDDATE
	FROM POS_BREFUNDDETAIL BRD
		INNER JOIN POS_BREFUND BR ON BRD.BRID = BR.BRID
		INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION ICL ON I.CLASSIFICATIONID = ICL.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCL ON I.SUBCLASSIFICATIONID = ISCL.SUBCLASSIFICATIONID
		
	WHERE BR.BRANCHID = @BRANCHID 
		AND BRD.REASONID = 5 
		AND CAST(BR.UPDATEDDATE AS DATE) >= CAST(@FROMDATE AS DATE) 
		AND CAST(BR.UPDATEDDATE AS DATE) <= CAST(@TODATE AS DATE) 
		AND BR.DELETEDDATE IS NULL
		AND BRD.DELETEDDATE IS NULL
		AND BR.IsAccepted = 1

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BREFUNDSHEET_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_BREFUNDSHEET_1]
@BranchID VARCHAR(500),  
@FromDate date= NULL,        
@ToDate date = NULL,  
@IncludeItem BIT = 0,  
@IncludeDrafts BIT = 0,
@SerialNumber VARCHAR(100) = '',  
@CategoryID int = 0  
AS                
BEGIN     
  
 SELECT @ToDate = DATEADD(d, 1, @ToDate), @SerialNumber = '%' + @SerialNumber + '%'  
  
	SELECT   
		BR.BRID,B.BRANCHNAME ,BR.BREFUNDNUMBER, BR.CATEGORYID,CAT.CATEGORYNAME,   
		CU.FULLNAME AS CREATEDBY, BR.CREATEDATE, CAST(BR.CREATEDATE AS TIME) CREATEDTIME, 
		BR.BRANCHID, ISNULL(IsAccepted,0) AS IsAcceptedID
		, BR.STATUS AS ISDRAFT,
		CASE 
			WHEN ISNULL(BR.STATUS, 0) = 0 THEN 'Draft' 
			WHEN ISNULL(ISACCEPTED,0) = 0 THEN 'Not Accepted' 
		ELSE 'Accepted' END AS STATUS,
		AU.FULLNAME as AcceptedBy,
		BR.ACCEPTEDDATE as ACCEPTEDDATE,
		CAST(BR.ACCEPTEDDATE AS TIME) ACCEPTEDTIME,
		CASE WHEN ISNULL(BR.AUTOGENERATED,0) = 1 THEN 'YES' ELSE 'NO' END AS [Auto Generated],
		SDINNER.DISPATCHNUMBER AS [Ref #]
	FROM POS_BREFUND BR WITH(NOLOCK) 
		INNER JOIN BRANCH B ON BR.BRANCHID = B.BRANCHID  
		INNER JOIN dbo.SplitString(@BranchID,',') BINPUT ON BINPUT.ITEM = B.BRANCHID  
		INNER JOIN TBLUSER CU ON BR.CREATEDBY = CU.USERID  
		LEFT JOIN TBLCATEGORY CAT ON BR.CATEGORYID = CAT.CATEGORYID  
		LEFT JOIN TBLUSER AU ON BR.ACCEPTEDBY = AU.USERID
		LEFT JOIN STOCKDISPATCH SDINNER ON BR.REFID = SDINNER.STOCKDISPATCHID
	WHERE 
		BR.CREATEDATE >= @FromDate  
		AND BR.CREATEDATE <= @ToDate  
		AND (ISNULL(BR.STATUS,0) <> 0 OR @IncludeDrafts = 1)
		AND BR.DELETEDDATE IS NULL  
		AND ISNULL(BR.BREFUNDNUMBER, '') LIKE @SerialNumber  
		AND (BR.CATEGORYID = @CategoryID OR BR.CATEGORYID = 13 OR @CategoryID = 13)
	ORDER BY B.BRANCHCODE ASC, BR.CREATEDATE DESC    
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BULK_PROCESSING_INDENT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_RPT_BULK_PROCESSING_INDENT]
@CategoryID INT,
@NoOfDays INT = 1
AS
BEGIN

	DECLARE 
		@SixthMonthFromDate DATE = DATEADD(m, -6, GETDATE()),
		@FifthMonthFromDate DATE = DATEADD(m, -5, GETDATE()),
		@FourthMonthFromDate DATE = DATEADD(m, -4, GETDATE()),
		@ThirdMonthFromDate DATE = DATEADD(m, -3, GETDATE()),
		@SecondMonthFromDate DATE = DATEADD(m, -2, GETDATE()),
		@FirstMonthFromDate DATE = DATEADD(m, -1, GETDATE())
		, @IndentSaleFromDate DATE = GETDATE() - @NoOfDays

	DECLARE 
		@SixthMonthToDate DATE = DATEADD(d, @NoOfDays + 1, @SixthMonthFromDate),
		@FifthMonthToDate DATE = DATEADD(d, @NoOfDays + 1, @FifthMonthFromDate),
		@FourthMonthToDate DATE = DATEADD(d, @NoOfDays + 1, @FourthMonthFromDate),
		@ThirdMonthToDate DATE = DATEADD(d, @NoOfDays + 1, @ThirdMonthFromDate),
		@SecondMonthToDate DATE = DATEADD(d, @NoOfDays + 1, @SecondMonthFromDate),
		@FirstMonthToDate DATE = DATEADD(d, @NoOfDays + 1, @FirstMonthFromDate)
	
	SELECT 
		I.ITEMID, BS.BRANCHID, I.SKUCODE, I.ITEMNAME, SUBCAT.SUBCATEGORYNAME, BS.BRANCHSTOCK
		, ITEMSALE.SixthMonthSale, ITEMSALE.FifthMonthSale, ITEMSALE.FourthMonthSale
		, ITEMSALE.ThirdMonthSale, ITEMSALE.SecondMonthSale, ITEMSALE.FirstMonthSale
		, ITEMSALE.AvgSale, ITEMINDENTSALE.INDENTDAYSSALEQUANTITY
		, CAST(0.00 AS decimal(13, 2)) MAXSALE
		, CAST(0.00 AS decimal(13, 2)) INDENTQUANTITY
		, 0 AS ISINDENTNEEDED, CAST(NULL AS DATETIME) LASTDISPATCHDATE
		, I.PARENTITEMID, ISNULL(UOM.MULTIPLIER, 1) MULTIPLIER, CAST(0.00 AS decimal(13, 2)) WEIGHTINKGS
	INTO #INDENT
	FROM
		ITEM I 
		INNER JOIN 
			(
				SELECT IC.ITEMID, SSINNER.BRANCHID, SUM(CASE WHEN IINNER.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) BRANCHSTOCK					
				FROM 
					STOCKSUMMARY SSINNER WITH (NOLOCK)
					INNER JOIN ITEMPRICE IP WITH (NOLOCK) ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH (NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID 
					INNER JOIN ITEM IINNER WITH (NOLOCK) ON IINNER.ITEMID = IC.ITEMID
				WHERE IINNER.CATEGORYID = @CategoryID AND IC.DELETEDDATE IS NULL
				GROUP BY IC.ITEMID, SSINNER.BRANCHID
			) BS ON BS.ITEMID = I.ITEMID
		INNER JOIN	
			(
				SELECT IC.ITEMID, BC.BRANCHID
					, SUM(CASE WHEN PB.CREATEDDATE >= @SixthMonthFromDate AND PB.CREATEDDATE <= @SixthMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END) SixthMonthSale
					, SUM(CASE WHEN PB.CREATEDDATE >= @FifthMonthFromDate AND PB.CREATEDDATE <= @FifthMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END) FifthMonthSale
					, SUM(CASE WHEN PB.CREATEDDATE >= @FourthMonthFromDate AND PB.CREATEDDATE <= @FourthMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END) FourthMonthSale
					, SUM(CASE WHEN PB.CREATEDDATE >= @ThirdMonthFromDate AND PB.CREATEDDATE <= @ThirdMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END) ThirdMonthSale
					, SUM(CASE WHEN PB.CREATEDDATE >= @SecondMonthFromDate AND PB.CREATEDDATE <= @SecondMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END) SecondMonthSale
					, SUM(CASE WHEN PB.CREATEDDATE >= @FirstMonthFromDate AND PB.CREATEDDATE <= @FirstMonthToDate THEN CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END ELSE 0 END) FirstMonthSale
					, CEILING(SUM(CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END) / 6) AvgSale
				FROM 
					POS_BILLDETAIL PBD WITH (NOLOCK)
					INNER JOIN POS_BILL PB WITH (NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC WITH (NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP WITH (NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH (NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH (NOLOCK) ON I.ITEMID = IC.ITEMID
				WHERE
					I.CATEGORYID = @CategoryID					
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND 
						(
							(PB.CREATEDDATE >= @SixthMonthFromDate AND PB.CREATEDDATE <= @SixthMonthToDate)
							OR (PB.CREATEDDATE >= @FifthMonthFromDate AND PB.CREATEDDATE <= @FifthMonthToDate)
							OR (PB.CREATEDDATE >= @FourthMonthFromDate AND PB.CREATEDDATE <= @FourthMonthToDate)
							OR (PB.CREATEDDATE >= @ThirdMonthFromDate AND PB.CREATEDDATE <= @ThirdMonthToDate)
							OR (PB.CREATEDDATE >= @SecondMonthFromDate AND PB.CREATEDDATE <= @SecondMonthToDate)
							OR (PB.CREATEDDATE >= @FirstMonthFromDate AND PB.CREATEDDATE <= @FirstMonthToDate)
						)
				GROUP BY IC.ITEMID, BC.BRANCHID
			) ITEMSALE ON ITEMSALE.ITEMID = I.ITEMID AND ITEMSALE.BRANCHID = BS.BRANCHID
		LEFT JOIN	
			(
				SELECT IC.ITEMID, BC.BRANCHID
					, CAST(ROUND((CASE WHEN IINNER.ISOPENITEM = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END), 2) AS DECIMAL(18, 2)) AS INDENTDAYSSALEQUANTITY
				FROM 
					POS_BILLDETAIL PBD WITH (NOLOCK)
					INNER JOIN POS_BILL PB WITH (NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC WITH (NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP WITH (NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH (NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM IINNER WITH (NOLOCK) ON IINNER.ITEMID = IC.ITEMID
				WHERE
					IINNER.CATEGORYID = @CategoryID
					AND PB.CREATEDDATE >= @IndentSaleFromDate
					AND PB.BILLSTATUS = 1
					AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
				GROUP BY IC.ITEMID, BC.BRANCHID, IINNER.ISOPENITEM
			) ITEMINDENTSALE ON ITEMINDENTSALE.ITEMID = I.ITEMID AND ITEMINDENTSALE.BRANCHID = BS.BRANCHID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN UOM UOM ON UOM.UOMID = I.UOMID
	WHERE I.PARENTITEMID IS NOT NULL AND ISNULL(SUBCAT.SUBCATEGORYNAME, '') <> 'WH 2ND SALE'
		AND I.SKUCODE IN ('1024650', '1024671', '1024656', '1024961', '1024748', '1024679', '1024865')
	ORDER BY ITEMNAME

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)
	UPDATE #INDENT SET MAXSALE = (CASE WHEN AvgSale > INDENTDAYSSALEQUANTITY THEN AvgSale ELSE INDENTDAYSSALEQUANTITY END) 

	UPDATE #INDENT SET INDENTQUANTITY = MAXSALE - (CASE WHEN  BRANCHSTOCK > 0 THEN BRANCHSTOCK ELSE 0 END)

	UPDATE #INDENT
	SET INDENTQUANTITY = 5 
	WHERE INDENTQUANTITY > 0 AND INDENTQUANTITY < 5

	UPDATE #INDENT
	SET INDENTQUANTITY = 5 
	WHERE MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5
	
	UPDATE #INDENT
	SET INDENTQUANTITY = CAST(CEILING((INDENTQUANTITY * 1.00 / 5)) AS INT) * 5
	WHERE INDENTQUANTITY > 0 

	UPDATE I
	SET I.LASTDISPATCHDATE = LSD.LASTDISPATCHDATE
	FROM	
		#INDENT I		
		INNER JOIN 
			(
				SELECT IC.ITEMID, SD.TOBRANCHID BRANCHID, MAX(SD.CREATEDDATE) LASTDISPATCHDATE
				FROM
					STOCKDISPATCHDETAIL SDD WITH (NOLOCK) 
					INNER JOIN STOCKDISPATCH SD WITH (NOLOCK) ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP WITH (NOLOCK) ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH (NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
				WHERE
					SD.STATUS IN (1, 2) AND SD.DELETEDDATE IS NULL AND SDD.DELETEDDATE IS NULL 
				GROUP BY IC.ITEMID, SD.TOBRANCHID
			) LSD ON LSD.ITEMID = I.ITEMID AND LSD.BRANCHID = I.BRANCHID

	UPDATE #INDENT SET INDENTDAYSSALEQUANTITY = ISNULL(INDENTDAYSSALEQUANTITY, 0)

	UPDATE #INDENT
	SET ISINDENTNEEDED = 1, INDENTQUANTITY = MAXSALE
	WHERE BRANCHSTOCK <= 0 -- Send all negatives, since sale is there and we think stock is wrong send them

	UPDATE #INDENT
	SET ISINDENTNEEDED = CASE
							WHEN MAXSALE = BRANCHSTOCK AND BRANCHSTOCK <= 5 THEN 1  
							WHEN INDENTDAYSSALEQUANTITY = 0 OR BRANCHSTOCK < INDENTDAYSSALEQUANTITY * 1.5 THEN 1
						ELSE 0 END 
	WHERE ISINDENTNEEDED = 0 AND MAXSALE > BRANCHSTOCK

	UPDATE #INDENT SET WEIGHTINKGS = INDENTQUANTITY * MULTIPLIER WHERE ISINDENTNEEDED = 1

	SELECT 
		I.ITEMID, I.SKUCODE, I.ITEMNAME, I.SUBCATEGORYNAME, I.PARENTITEMID, WS.WHSTOCK --, SUM(I.WEIGHTINKGS) BRANCHREQUIREDWGHTINKGS
		, SUM(I.INDENTQUANTITY) - (CASE WHEN WS.WHSTOCK > 0 THEN WS.WHSTOCK ELSE 0 END) BRANCHREQUIREDINDENT
		, CAST(((SUM(I.INDENTQUANTITY) - (CASE WHEN WS.WHSTOCK > 0 THEN WS.WHSTOCK ELSE 0 END)) * I.MULTIPLIER)  AS DECIMAL(18, 2)) PROCESSINGREQUIREDWGHTINKGS
	INTO #ITEMINDENT
	FROM 
		#INDENT I 	
		LEFT JOIN 
			(
				SELECT IC.ITEMID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) WHSTOCK					
				FROM 
					STOCKSUMMARY SSINNER WITH (NOLOCK) 
					INNER JOIN ITEMPRICE IP WITH (NOLOCK) ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH (NOLOCK) ON IP.ITEMCODEID = IC.ITEMCODEID 
					INNER JOIN ITEM I WITH (NOLOCK) ON I.ITEMID = IC.ITEMID
				WHERE SSINNER.BRANCHID = 45
				GROUP BY IC.ITEMID
			) WS ON WS.ITEMID = I.ITEMID	 
	WHERE I.ISINDENTNEEDED = 1
	GROUP BY I.ITEMID, I.SKUCODE, I.ITEMNAME, I.SUBCATEGORYNAME, I.PARENTITEMID, WS.WHSTOCK, I.MULTIPLIER
	HAVING ((SUM(I.INDENTQUANTITY) - CASE WHEN WS.WHSTOCK > 0 THEN WS.WHSTOCK ELSE 0 END) * I.MULTIPLIER) > WS.WHSTOCK

	SELECT 
		PITEM.ITEMID, PITEM.SKUCODE, PITEM.ITEMNAME, SC.SUBCATEGORYNAME, SUM(I.PROCESSINGREQUIREDWGHTINKGS) PROCESSINGREQUIREDWGHTINKGS
	FROM
		#ITEMINDENT I 
		INNER JOIN ITEM PITEM WITH (NOLOCK) ON PITEM.ITEMID = I.PARENTITEMID
		LEFT JOIN SUBCATEGORY SC WITH (NOLOCK) ON SC.SUBCATEGORYID = PITEM.SUBCATEGORYID
	WHERE I.PROCESSINGREQUIREDWGHTINKGS > 0
	GROUP BY PITEM.ITEMID, PITEM.SKUCODE, PITEM.ITEMNAME, SC.SUBCATEGORYNAME
	ORDER BY SC.SUBCATEGORYNAME, PITEM.ITEMNAME

	SELECT * FROM #ITEMINDENT I 
	--WHERE I.PROCESSINGREQUIREDWGHTINKGS > 0 
	ORDER BY I.SUBCATEGORYNAME, I.ITEMNAME

	DECLARE @SelectQuery VARCHAR(MAX)
	SELECT @SelectQuery = ' SELECT I.ITEMID, I.PARENTITEMID, I.SKUCODE, I.ITEMNAME, I.SUBCATEGORYNAME, B.BRANCHID, B.BRANCHNAME, I.BRANCHSTOCK'
	SELECT @SelectQuery = @SelectQuery + ', I.SixthMonthSale AS ''' + CAST(@SixthMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@SixthMonthToDate AS VARCHAR(20)) + ''''
	SELECT @SelectQuery = @SelectQuery + ', I.FifthMonthSale AS ''' + CAST(@FifthMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@FifthMonthToDate AS VARCHAR(20)) + ''''
	SELECT @SelectQuery = @SelectQuery + ', I.FourthMonthSale AS ''' + CAST(@FourthMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@FourthMonthToDate AS VARCHAR(20)) + ''''
	SELECT @SelectQuery = @SelectQuery + ', I.ThirdMonthSale AS ''' + CAST(@ThirdMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@ThirdMonthToDate AS VARCHAR(20)) + ''''
	SELECT @SelectQuery = @SelectQuery + ', I.SecondMonthSale AS ''' + CAST(@SecondMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@SecondMonthToDate AS VARCHAR(20)) + ''''
	SELECT @SelectQuery = @SelectQuery + ', I.FirstMonthSale AS ''' + CAST(@FirstMonthFromDate AS VARCHAR(20))+ ' ~ ' +  CAST(@FirstMonthToDate AS VARCHAR(20)) + ''''

	SELECT @SelectQuery = @SelectQuery + ', I.AvgSale AS ''Average Sale (6M)'', I.INDENTDAYSSALEQUANTITY AS ''Last ' + CAST(@NoOfDays AS VARCHAR(20)) + ' days sale'''
	SELECT @SelectQuery = @SelectQuery + ', I.INDENTQUANTITY FROM #INDENT I INNER JOIN BRANCH B ON B.BRANCHID =  I.BRANCHID ' 
	SELECT @SelectQuery = @SelectQuery + ' INNER JOIN #ITEMINDENT IPARENT ON IPARENT.ITEMID =  I.ITEMID ' 
	SELECT @SelectQuery = @SelectQuery + ' WHERE I.ISINDENTNEEDED = 1 ORDER BY I.SUBCATEGORYNAME, I.ITEMNAME ' 
	
	EXEC (@SelectQuery)

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_BULK_PROCESSING_INDENT_BY_DISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_RPT_BULK_PROCESSING_INDENT_BY_DISPATCH]
@CategoryID INT,
@NoOfDays INT = 1,
@SubCategoryID VARCHAR(MAX)
AS
BEGIN

	DECLARE 
		@SixthMonthFromDate DATE = DATEADD(m, -6, GETDATE()),
		@FifthMonthFromDate DATE = DATEADD(m, -5, GETDATE()),
		@FourthMonthFromDate DATE = DATEADD(m, -4, GETDATE()),
		@ThirdMonthFromDate DATE = DATEADD(m, -3, GETDATE()),
		@SecondMonthFromDate DATE = DATEADD(m, -2, GETDATE()),
		@FirstMonthFromDate DATE = DATEADD(m, -1, GETDATE()), 
		@IndentSaleFromDate DATE = GETDATE() - @NoOfDays,
		@LastNDaysString VARCHAR(20) = 'Last ' + LTRIM(STR(@NoOfDays)) + ' Days AVG'

	DECLARE 
		@SixthMonthToDate DATE = DATEADD(d, @NoOfDays, @SixthMonthFromDate),
		@FifthMonthToDate DATE = DATEADD(d, @NoOfDays, @FifthMonthFromDate),
		@FourthMonthToDate DATE = DATEADD(d, @NoOfDays, @FourthMonthFromDate),
		@ThirdMonthToDate DATE = DATEADD(d, @NoOfDays, @ThirdMonthFromDate),
		@SecondMonthToDate DATE = DATEADD(d, @NoOfDays, @SecondMonthFromDate),
		@FirstMonthToDate DATE = DATEADD(d, @NoOfDays, @FirstMonthFromDate)

	SELECT * INTO #SUBCAT FROM DBO.SplitString(@SubCategoryID, ',')

	SELECT 
		CAST(SDD.CREATEDDATE AS DATE) DISPATCHDATE, I.ITEMID, SUM(SDD.DISPATCHQUANTITY) DISPATCHQUANTITY
		, CASE WHEN CAST(SDD.CREATEDDATE AS DATE) < @IndentSaleFromDate THEN '6 months' ELSE @LastNDaysString END DISPATCHTYPE
	INTO #DISPATCHES
	FROM
		STOCKDISPATCH SD
		INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		INNER JOIN #SUBCAT SC ON SC.Item = I.SUBCATEGORYID
	WHERE
		ISNULL(SD.STATUS, 0) <> 0
		AND SD.DELETEDDATE IS NULL
		AND SDD.DELETEDDATE IS NULL
		AND I.PARENTITEMID IS NOT NULL 
		AND I.CATEGORYID = @CategoryID
		AND ISNULL(SUBCAT.SUBCATEGORYNAME, '') <> 'WH 2ND SALE'
		--AND I.SKUCODE IN ('1024650', '1024671', '1024656', '1024961', '1024748', '1024679', '1024865')
		AND 
			(
				(SDD.CREATEDDATE > @SixthMonthFromDate AND SDD.CREATEDDATE <= @SixthMonthToDate)
				OR (SDD.CREATEDDATE >= @FifthMonthFromDate AND SDD.CREATEDDATE <= @FifthMonthToDate)
				OR (SDD.CREATEDDATE >= @FourthMonthFromDate AND SDD.CREATEDDATE <= @FourthMonthToDate)
				OR (SDD.CREATEDDATE >= @ThirdMonthFromDate AND SDD.CREATEDDATE <= @ThirdMonthToDate)
				OR (SDD.CREATEDDATE >= @SecondMonthFromDate AND SDD.CREATEDDATE <= @SecondMonthToDate)
				OR (SDD.CREATEDDATE >= @FirstMonthFromDate AND SDD.CREATEDDATE <= @FirstMonthToDate)
				OR SDD.CREATEDDATE >= @IndentSaleFromDate
			)
	GROUP BY CAST(SDD.CREATEDDATE AS DATE), I.ITEMID
	--ORDER BY ITEMNAME

	SELECT 
		I.ITEMID, I.SKUCODE, I.ITEMNAME, 0 AS SIXMONTHAVG, 0 AS NDAYSAVG, 0 AS MAXOFAVG, ITEMSTOCK.AVAILABLESTOCK
		, CAST(0 AS INT) AS INDENTNEEDED, UOM.MULTIPLIER, CAST(0.00 AS DECIMAL(18, 2)) AS INDENTNEEDEDINKGS, I.PARENTITEMID
		, SUBCAT.SUBCATEGORYNAME
	INTO #ITEMINDENT
	FROM
		#DISPATCHES DIS
		INNER JOIN ITEM I ON I.ITEMID = DIS.ITEMID
		INNER JOIN 
			(
				SELECT IC.ITEMID, SUM(SS.QUANTITY) AVAILABLESTOCK
				FROM
					STOCKSUMMARY SS
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				WHERE SS.BRANCHID = 45
				GROUP BY IC.ITEMID
			) ITEMSTOCK ON ITEMSTOCK.ITEMID = DIS.ITEMID
		LEFT JOIN UOM UOM ON UOM.UOMID = I.UOMID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
	GROUP BY I.ITEMID, I.SKUCODE, I.ITEMNAME, ITEMSTOCK.AVAILABLESTOCK, UOM.MULTIPLIER, I.PARENTITEMID, SUBCAT.SUBCATEGORYNAME


	UPDATE I
	SET 
		I.SIXMONTHAVG = ISNULL(SMA.SIXMONTHAVG, 0)
		, I.NDAYSAVG = ISNULL(NDA.NDAYSAVG, 0)
	FROM
		#ITEMINDENT I
		LEFT JOIN 
			(
				SELECT DIS.ITEMID, ROUND(SUM(DIS.DISPATCHQUANTITY) / COUNT(1), 0) AS SIXMONTHAVG
				FROM #DISPATCHES DIS
				WHERE DIS.DISPATCHTYPE = '6 months'
				GROUP BY DIS.ITEMID					
			) SMA ON I.ITEMID = SMA.ITEMID
		LEFT JOIN 
			(
				SELECT DIS.ITEMID, ROUND(SUM(DIS.DISPATCHQUANTITY) / COUNT(1), 0) AS NDAYSAVG
				FROM #DISPATCHES DIS
				WHERE DIS.DISPATCHTYPE = @LastNDaysString
				GROUP BY DIS.ITEMID	
			) NDA ON I.ITEMID = NDA.ITEMID

	UPDATE #ITEMINDENT
	SET MAXOFAVG = CASE WHEN SIXMONTHAVG > NDAYSAVG THEN SIXMONTHAVG ELSE NDAYSAVG END

	UPDATE #ITEMINDENT
	SET INDENTNEEDED = (MAXOFAVG * @NoOfDays) - CASE WHEN AVAILABLESTOCK > 0 THEN AVAILABLESTOCK ELSE 0 END

	DELETE #ITEMINDENT WHERE INDENTNEEDED <= 0
	DELETE DIS FROM #DISPATCHES DIS WHERE NOT EXISTS ( SELECT 1 FROM #ITEMINDENT I WHERE I.ITEMID = DIS.ITEMID )

	UPDATE #ITEMINDENT SET INDENTNEEDEDINKGS = INDENTNEEDED * MULTIPLIER

	--SELECT 
	--	PITEM.ITEMID, PITEM.SKUCODE, PITEM.ITEMNAME, SUM(II.INDENTNEEDEDINKGS) INDENTNEEDEDINKGS		
	--FROM
	--	#ITEMINDENT II
	--	INNER JOIN ITEM I ON I.ITEMID = II.ITEMID
	--	INNER JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID		
	--GROUP BY PITEM.ITEMID, PITEM.SKUCODE, PITEM.ITEMNAME
	--ORDER BY PITEM.ITEMNAME
	
	DECLARE @SelectQuery VARCHAR(MAX)
	SELECT @SelectQuery = 'SELECT ITEMID, SUBCATEGORYNAME, SKUCODE, ITEMNAME, SIXMONTHAVG, NDAYSAVG AS ''' + @LastNDaysString + ''''
	SELECT @SelectQuery += ', MAXOFAVG, AVAILABLESTOCK, INDENTNEEDED, PARENTITEMID FROM #ITEMINDENT'
	SELECT @SelectQuery += ' ORDER BY SUBCATEGORYNAME, ITEMNAME'
	EXEC (@SelectQuery)

	SELECT * FROM #DISPATCHES


END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_CREDITBILLPAYMENTS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROC [dbo].[USP_RPT_CREDITBILLPAYMENTS]
 (
	@BranchIDs VARCHAR(500)
	, @FromDate DATE
	, @ToDate DATE
 )
 AS
 BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)


	SELECT 
		CBP.CREDITBILLPAYMENTID, PB.BILLID, B.BRANCHNAME, PB.BILLNUMBER, PB.CUSTOMERNAME, PB.CUSTOMERNUMBER, PB.CUSTOMERGST
		, MOP.MOPNAME, PBMD.MOPVALUE, CBP.STATUS, CASE WHEN CBP.STATUS = 0 THEN 'Open' ELSE 'Closed' END AS STATUSTEXT, CBP.DESCRIPTION
		, CU.USERNAME AS BILLEDBY, PB.CREATEDDATE, SU.USERNAME AS STATUSCHANGEDBY, CBP.STATUSCHANGEDDATE
	FROM 
		CREDITBILLPAYMENTS CBP
		INNER JOIN POS_BILLMOPDETAIL PBMD WITH(NOLOCK) ON PBMD.BILLMOPDETAILID = CBP.BILLMOPDETAILID AND PBMD.COUNTERID = CBP.BRANCHCOUNTERID
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBMD.BILLID AND PB.BRANCHCOUNTERID = PBMD.COUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = CBP.BRANCHCOUNTERID
		INNER JOIN BRANCH B ON B.BRANCHID = BC.BRANCHID
		INNER JOIN TBLUSER CU ON CU.USERID = PB.CREATEDBY
		INNER JOIN dbo.SplitString(@BranchIDs,',') BIDS ON BC.BRANCHID = BIDS.ITEM
		INNER JOIN TBLMOP MOP ON MOP.MOPID = PBMD.MOPID
		LEFT JOIN TBLUSER SU ON SU.USERID = CBP.STATUSCHANGEDBY
	WHERE
		PB.CREATEDDATE >= @FromDate
		AND PB.CREATEDDATE < @ToDate
	ORDER BY B.BRANCHNAME, PB.BILLNUMBER

 END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_CREFUND]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_CREFUND]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(MAX)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(MAX)
	, @IncludeTrayNumber BIT = 0
	, @IncludeCustomerDetails BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, QUANTITY DECIMAL(11, 2),
		COSTPRICEWOT DECIMAL(14, 2), COSTPRICEWT DECIMAL(14, 2), COSTPRICETAX DECIMAL(14, 2), 
		SALEPRICEWOT DECIMAL(14, 2), SALEPRICEWT DECIMAL(14, 2), SALEPRICETAX DECIMAL(14, 2), 
		TOTALCPEWOT DECIMAL(14, 2), TOTALCPWT DECIMAL(14, 2), TOTALCPTAX DECIMAL(14, 2), 
		TOTALSPWOT DECIMAL(14, 2), TOTALSPWT DECIMAL(14, 2), TOTALSPTAX DECIMAL(14, 2),
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT
		, CUSTOMERNAME VARCHAR(100), CUSTOMERNUMBER VARCHAR(10), BILLNUMBER VARCHAR(30), BRANDID INT, MANUFACTURERID INT)

	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, CATEGORYID,SUBCATEGORYID,PERIODOCITY,QUANTITY,
		COSTPRICEWOT, COSTPRICEWT, COSTPRICETAX, SALEPRICEWT, SALEPRICEWOT, SALEPRICETAX, TOTALCPEWOT, TOTALCPWT, TOTALCPTAX
		, TOTALSPWT, TOTALSPWOT, TOTALSPTAX, CUSTOMERNAME, CUSTOMERNUMBER, BILLNUMBER, BRANDID, MANUFACTURERID)
	SELECT CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END,
		SUM(QUANTITY) AS QUANTITY,
		MAX(COSTPRICEWOT) AS COSTPRICEWOT,
		MAX(COSTPRICEWT) AS COSTPRICEWT,
		MAX(COSTPRICETAX) AS COSTPRICETAX,
		MAX(SALEPRICE) AS SALEPRICEWT,
		MAX(SALEPRICEWOT) AS SALEPRICEWOT,
		MAX(SALEPRICETAX) AS SALEPRICETAX,
		SUM(QUANTITY * COSTPRICEWOT) AS TOTALCPWOT,
		SUM(QUANTITY * COSTPRICEWT) AS TOTALCPWT,
		SUM(QUANTITY * COSTPRICETAX) AS TOTALCPTAX,
		SUM(QUANTITY * SALEPRICE) AS TOTALSPWT,
		SUM(QUANTITY * SALEPRICEWOT) AS TOTALSPWOT,
		SUM(QUANTITY * SALEPRICETAX) AS TOTALSPTAX
		, CASE WHEN @IncludeCustomerDetails = 1 THEN CUSTOMERNAME ELSE NULL END
		, CASE WHEN @IncludeCustomerDetails = 1 THEN CUSTOMERNUMBER ELSE NULL END
		, CASE WHEN @IncludeCustomerDetails = 1 THEN BILLNUMBER ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	FROM (
			SELECT BD.ITEMPRICEID, 
				BC.BRANCHID AS BRANCHID,
				I.CATEGORYID, 
				I.SUBCATEGORYID, 
				CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS QUANTITY,
				ISNULL(IPICP.COSTPRICEWOT,0) AS COSTPRICEWOT,
				ISNULL(IPICP.COSTPRICEWT,0) AS COSTPRICEWT,
				IPICP.COSTPRICEWT - IPICP.COSTPRICEWOT AS COSTPRICETAX,
				IP.SALEPRICE,
				(IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100 AS SALEPRICEWOT,
				IP.SALEPRICE - ((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100) AS SALEPRICETAX,
				CR.CREATEDDATE
				, BILL.CUSTOMERNAME, BILL.CUSTOMERNUMBER, BILL.BILLNUMBER,
				I.BRANDID,I.MANUFACTURERID
			FROM POS_CREFUND CR
				INNER JOIN POS_BILLDETAIL  BD ON CR.BILLDETAILID = BD.BILLDETAILID AND CR.COUNTERID = BD.BRANCHCOUNTERID
				INNER JOIN POS_BILL BILL ON BILL.BILLID = BD.BILLID AND BILL.BRANCHCOUNTERID = BD.BRANCHCOUNTERID
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BD.ITEMPRICEID 
				LEFT JOIN IPICPView IPICP ON IP.ITEMPRICEID = IPICP.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
				INNER JOIN BRANCHCOUNTER BC ON CR.COUNTERID = BC.COUNTERID
				INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = BC.BRANCHID
				INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
			WHERE 
				(I.ITEMID = @ITEMID OR @ITEMID = 0)
				AND CR.CREATEDDATE > @FromDate
				AND CR.CREATEDDATE < @ToDate
		) AS BD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeCustomerDetails = 1 THEN CUSTOMERNAME ELSE NULL END
		, CASE WHEN @IncludeCustomerDetails = 1 THEN CUSTOMERNUMBER ELSE NULL END
		, CASE WHEN @IncludeCustomerDetails = 1 THEN BILLNUMBER ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	SELECT 
		PT.PERIODOCITY, B.BRANCHNAME, CAT.CATEGORYNAME,SC.SUBCATEGORYNAME ,BR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, 
		IP.MRP, PT.COSTPRICEWOT, PT.COSTPRICEWT, PT.COSTPRICETAX, PT.SALEPRICEWOT, PT.SALEPRICEWT, PT.SALEPRICETAX, 
		PT.QUANTITY, PT.TOTALCPEWOT, PT.TOTALCPWT, PT.TOTALCPTAX, PT.TOTALSPWOT, PT.TOTALSPWT, PT.TOTALSPTAX
		, PT.CUSTOMERNAME, PT.CUSTOMERNUMBER, PT.BILLNUMBER
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_CURRENTSTOCK]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_CURRENTSTOCK]
(
	@BranchIDs VARCHAR(500)
	, @CategoryID VARCHAR(500)
	, @ITEMID INT = 0
)
AS
BEGIN

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')

	DECLARE @AvgCpDate DATE = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)

	SELECT 
		SS.BRANCHID, B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, IP.MRP, IP.SALEPRICE, SS.ITEMPRICEID, CASE WHEN I.ISOPENITEM <> 1 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS STOCKQTYORWGHT
		, ISNULL(SALE.QTYORWGHT, 0) AS SALEQTYORWGHT
		, CASE WHEN I.ISOPENITEM <> 1 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END - ISNULL(SALE.QTYORWGHT, 0) AS CURRENTQTYORWGHT
		, CLS.CLASSIFICATIONNAME, SUBCLS.SUBCLASSIFICATIONNAME, TB.BRANDNAME, TM.MANUFACTURERNAME
		, AVGCP.COSTPRICEWT AVGCOSTPRICEWT, AVGCP.COSTPRICEWOT AVGCOSTPRICEWOT
	FROM
		STOCKSUMMARY SS WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #BRANCH BIDS ON BIDS.ITEM = SS.BRANCHID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID
		INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION CLS WITH(NOLOCK) ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS WITH(NOLOCK) ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		LEFT JOIN TBLBRAND TB WITH(NOLOCK) ON I.BRANDID = TB.BRANDID
		LEFT JOIN TBLMANUFACTURER TM WITH(NOLOCK) ON I.MANUFACTURERID = TM.MANUFACTURERID
		LEFT JOIN 
			(
				SELECT BC.BRANCHID, PBD.ITEMPRICEID, SUM(CASE WHEN I.ISOPENITEM <> 1 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END) AS QTYORWGHT
				FROM 
					POS_BILL PB WITH(NOLOCK)
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				WHERE
					PB.BILLSTATUS = 1
					AND PBD.DELETEDDATE IS NULL
					AND PB.DAYCLOSUREID IS NULL
				GROUP BY BC.BRANCHID, PBD.ITEMPRICEID
			) SALE ON SALE.BRANCHID = SS.BRANCHID AND SALE.ITEMPRICEID = SS.ITEMPRICEID
		LEFT JOIN AVGCOSTPRICE AVGCP WITH(NOLOCK) ON AVGCP.ITEMCODEID = IC.ITEMCODEID AND AVGCP.MRP = IP.MRP AND AVGCP.AVGCPDATE = @AvgCpDate
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND (SALE.QTYORWGHT <> 0 OR (CASE WHEN I.ISOPENITEM <> 1 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END) <> 0)
	ORDER BY B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_CUSTOMERRETURNS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_CUSTOMERRETURNS]
@BranchID VARCHAR(500),
@FromDate Date,
@ToDate Date,
@IncludeBillNo Bit = 0,
@IncludeBranch Bit = 0,
@IncludeRefundDate Bit = 0
AS
BEGIN

SELECT 
CR.REFUNDDATE,CR.BILLNUMBER,B.BRANCHNAME,I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME,
IP.MRP,IP.SALEPRICE,CR.REFUNDQUANTITY,CR.REFUNDWEIGHTINKGS,CR.REFUNDAMOUNT
FROM (
		SELECT 
			BD.ITEMPRICEID, 
			CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END AS BRANCHID,
			CASE WHEN @IncludeBillNo = 1 THEN B.BILLNUMBER ELSE NULL END AS BILLNUMBER,
			CASE WHEN @IncludeRefundDate = 1 THEN CAST(CR.CREATEDDATE AS DATE) ELSE NULL END AS REFUNDDATE,
			SUM(CR.REFUNDQUANTITY) AS REFUNDQUANTITY, 
			SUM(CR.REFUNDWEIGHTINKGS) AS REFUNDWEIGHTINKGS,
			SUM(CR.REFUNDAMOUNT) AS REFUNDAMOUNT
		FROM POS_CREFUND CR INNER JOIN POS_BILLDETAIL BD ON CR.COUNTERID = BD.BRANCHCOUNTERID AND CR.BILLDETAILID = BD.BILLDETAILID
			INNER JOIN POS_BILL B ON BD.BILLID = B.BILLID AND BD.BRANCHCOUNTERID = B.BRANCHCOUNTERID
			INNER JOIN BRANCHCOUNTER BC ON CR.COUNTERID = BC.COUNTERID
			INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON BC.BRANCHID = BIDS.ITEM
		WHERE CR.CREATEDDATE BETWEEN @FromDate AND DATEADD(day,1, @ToDate)
		GROUP BY BD.ITEMPRICEID,
			CASE WHEN @IncludeBillNo = 1 THEN B.BILLNUMBER ELSE NULL END,
			CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END,
			CASE WHEN @IncludeRefundDate = 1 THEN CAST(CR.CREATEDDATE AS DATE) ELSE NULL END
	)  CR
	INNER JOIN ITEMPRICE IP ON CR.ITEMPRICEID = IP.ITEMPRICEID
	INNER JOIN ITEMCODE	IC ON IP.ITEMCODEID = IC.ITEMCODEID
	INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
	LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
	LEFT JOIN BRANCH B ON CR.BRANCHID = B.BRANCHID
	LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
	LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
ORDER BY I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_DAYSALE_BY_MOP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_DAYSALE_BY_MOP]
(
	@BranchIDs VARCHAR(500)
	, @FromDate DATE
	, @ToDate DATE
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT CAST(BMD.CREATEDDATE AS DATE) BILLDATE, B.BRANCHNAME, BC.COUNTERNAME, MOP.MOPNAME, SUM(BMD.MOPVALUE) AS AMOUNT
	FROM 
		POS_BILLMOPDETAIL BMD
		INNER JOIN TBLMOP MOP ON MOP.MOPID = BMD.MOPID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = BMD.COUNTERID
		INNER JOIN BRANCH B ON B.BRANCHID = BC.BRANCHID
		INNER JOIN dbo.SplitString(@BranchIDs,',') BIDS ON BC.BRANCHID = BIDS.ITEM
	WHERE 
		BMD.CREATEDDATE > @FromDate
		AND BMD.CREATEDDATE < @ToDate
	GROUP BY
		CAST(BMD.CREATEDDATE AS DATE), B.BRANCHNAME, BC.COUNTERNAME, MOP.MOPNAME
	ORDER BY 1, 2, 3, 4
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_DEALS_TRACKING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_DEALS_TRACKING]
(
    @FromDate DATE,
    @ToDate DATE,
    @BranchIDs VARCHAR(MAX),
    @Periodicity VARCHAR(20),
    @DealTypeID INT = 0,
    @IncludeDate BIT = 0,
    @IncludeDeal BIT = 1,
    @IncludeItem BIT = 1,
    @IncludeBranch BIT = 0,
    @IncludeBrand BIT = 0,
    @IncludeManufacturer BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT @ToDate = DATEADD(DAY, 1, @ToDate);

    DECLARE @DateSuffixInYear VARCHAR(15);

    SELECT @DateSuffixInYear =
            '-' + CASE
                    WHEN @Periodicity = 'Yearly' THEN '01'
                    WHEN @Periodicity = 'Fin. Yearly' THEN '04'
                    ELSE NULL
                END
            + '-01 00:00:00';

    SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs, ',');

    CREATE TABLE #DEALSALES
    (
        DEALID INT,
        DEALTYPEID INT,
        ITEMPRICEID INT,
        ITEMCODEID INT,
        ITEMID INT,
        BRANCHID INT,
        BRANDID INT,
        MANUFACTURERID INT,
        CREATEDDATE DATETIME,
        SOLDQUANTITY DECIMAL(14, 2),
        SOLDWEIGHTINKGS DECIMAL(14, 2),
        BILLEDAMOUNT DECIMAL(14, 2),
        DISCOUNT DECIMAL(14, 2)
    );

    INSERT INTO #DEALSALES
    (
        DEALID,
        DEALTYPEID,
        ITEMPRICEID,
        ITEMCODEID,
        ITEMID,
        BRANCHID,
        BRANDID,
        MANUFACTURERID,
        CREATEDDATE,
        SOLDQUANTITY,
        SOLDWEIGHTINKGS,
        BILLEDAMOUNT,
        DISCOUNT
    )
    SELECT
        OFR.OFFERID,
        OFR.OFFERTYPEID,
        IP.ITEMPRICEID,
        IC.ITEMCODEID,
        I.ITEMID,
        BC.BRANCHID,
        I.BRANDID,
        I.MANUFACTURERID,
        PBD.CREATEDDATE,
        PBD.QUANTITY,
        ISNULL(PBD.WEIGHTINKGS, 0),
        ISNULL(PBD.BILLEDAMOUNT, 0),
        ISNULL(PBD.DISCOUNT, 0)
    FROM POS_BILLDETAIL PBD WITH(NOLOCK)
        INNER JOIN POS_BILL PB WITH(NOLOCK)
            ON PB.BILLID = PBD.BILLID
            AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
        INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
        INNER JOIN #BRANCH BRANCHFILTER ON BRANCHFILTER.ITEM = BC.BRANCHID
        INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
        INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
        INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
        INNER JOIN OFFER OFR WITH(NOLOCK) ON OFR.OFFERID = PBD.OFFERID
        INNER JOIN OFFERTYPE OFRT WITH(NOLOCK) ON OFRT.OFFERTYPEID = OFR.OFFERTYPEID
    WHERE
        PBD.CREATEDDATE >= @FromDate
        AND PBD.CREATEDDATE < @ToDate
        AND PBD.DELETEDDATE IS NULL
        AND PB.DELETEDDATE IS NULL
        AND PB.BILLSTATUS = 1
        AND OFR.DELETEDDATE IS NULL
        AND OFRT.BASETYPE = 2
        AND (OFR.OFFERTYPEID = @DealTypeID OR @DealTypeID = 0);

    INSERT INTO #DEALSALES
    (
        DEALID,
        DEALTYPEID,
        ITEMPRICEID,
        ITEMCODEID,
        ITEMID,
        BRANCHID,
        BRANDID,
        MANUFACTURERID,
        CREATEDDATE,
        SOLDQUANTITY,
        SOLDWEIGHTINKGS,
        BILLEDAMOUNT,
        DISCOUNT
    )
    SELECT
        OFR.OFFERID,
        OFR.OFFERTYPEID,
        IP.ITEMPRICEID,
        IC.ITEMCODEID,
        I.ITEMID,
        BC.BRANCHID,
        I.BRANDID,
        I.MANUFACTURERID,
        CR.CREATEDDATE,
        -ISNULL(CR.REFUNDQUANTITY, 0),
        -ISNULL(CR.REFUNDWEIGHTINKGS, 0),
        -ISNULL(CR.REFUNDAMOUNT, 0),
        0
    FROM POS_CREFUND CR WITH(NOLOCK)
        INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK)
            ON PBD.BILLDETAILID = CR.BILLDETAILID
            AND PBD.BRANCHCOUNTERID = CR.COUNTERID
        INNER JOIN POS_BILL PB WITH(NOLOCK)
            ON PB.BILLID = PBD.BILLID
            AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
        INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
        INNER JOIN #BRANCH BRANCHFILTER ON BRANCHFILTER.ITEM = BC.BRANCHID
        INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
        INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
        INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
        INNER JOIN OFFER OFR WITH(NOLOCK) ON OFR.OFFERID = PBD.OFFERID
        INNER JOIN OFFERTYPE OFRT WITH(NOLOCK) ON OFRT.OFFERTYPEID = OFR.OFFERTYPEID
    WHERE
        CR.CREATEDDATE >= @FromDate
        AND CR.CREATEDDATE < @ToDate
        AND CR.DELETEDDATE IS NULL
        AND PB.DELETEDDATE IS NULL
        AND PB.BILLSTATUS = 1
        AND OFR.DELETEDDATE IS NULL
        AND OFRT.BASETYPE = 2
        AND (OFR.OFFERTYPEID = @DealTypeID OR @DealTypeID = 0);

    SELECT
        CASE WHEN @IncludeDate = 1 THEN CAST(CASE
                WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
                WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
                WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
                WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
                WHEN @Periodicity = 'Fin. Yearly' THEN CAST((CAST(YEAR(CREATEDDATE) - CASE WHEN MONTH(CREATEDDATE) < 4 THEN 1 ELSE 0 END AS VARCHAR(4)) + @DateSuffixInYear) AS DATETIME)
            END AS DATETIME) ELSE NULL END AS PERIODICITY,
        CASE WHEN @IncludeDeal = 1 THEN DEALID ELSE NULL END AS DEALID,
        CASE WHEN @IncludeDeal = 1 THEN DEALTYPEID ELSE NULL END AS DEALTYPEID,
        CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END AS ITEMPRICEID,
        CASE WHEN @IncludeItem = 1 THEN ITEMCODEID ELSE NULL END AS ITEMCODEID,
        CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END AS ITEMID,
        CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END AS BRANCHID,
        CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END AS BRANDID,
        CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END AS MANUFACTURERID,
        SUM(SOLDQUANTITY) AS SOLDQUANTITY,
        SUM(SOLDWEIGHTINKGS) AS SOLDWEIGHTINKGS,
        SUM(BILLEDAMOUNT) AS BILLEDAMOUNT,
        SUM(DISCOUNT) AS DISCOUNT
    INTO #SUMMARY
    FROM #DEALSALES
    GROUP BY
        CASE WHEN @IncludeDate = 1 THEN CAST(CASE
                WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
                WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
                WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
                WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
                WHEN @Periodicity = 'Fin. Yearly' THEN CAST((CAST(YEAR(CREATEDDATE) - CASE WHEN MONTH(CREATEDDATE) < 4 THEN 1 ELSE 0 END AS VARCHAR(4)) + @DateSuffixInYear) AS DATETIME)
            END AS DATETIME) ELSE NULL END,
        CASE WHEN @IncludeDeal = 1 THEN DEALID ELSE NULL END,
        CASE WHEN @IncludeDeal = 1 THEN DEALTYPEID ELSE NULL END,
        CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END,
        CASE WHEN @IncludeItem = 1 THEN ITEMCODEID ELSE NULL END,
        CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END,
        CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END,
        CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END,
        CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END;

    SELECT
        S.PERIODICITY,
        OFR.OFFERNAME AS DEALNAME,
        OFR.OFFERCODE AS DEALCODE,
        OFRT.OFFERTYPENAME AS DEALTYPENAME,
        OFR.STARTDATE,
        OFR.ENDDATE,
        B.BRANCHNAME,
        BR.BRANDNAME,
        MAN.MANUFACTURERNAME,
        I.SKUCODE,
        I.ITEMNAME,
        IC.ITEMCODE,
        IP.MRP,
        IP.SALEPRICE,
        S.SOLDQUANTITY,
        S.SOLDWEIGHTINKGS,
        S.BILLEDAMOUNT AS DEALSALEVALUE,
        S.DISCOUNT,
        S.DEALID,
        S.DEALTYPEID,
        S.ITEMID,
        S.ITEMCODEID,
        S.ITEMPRICEID
    FROM #SUMMARY S
        LEFT JOIN OFFER OFR WITH(NOLOCK) ON OFR.OFFERID = S.DEALID
        LEFT JOIN OFFERTYPE OFRT WITH(NOLOCK) ON OFRT.OFFERTYPEID = S.DEALTYPEID
        LEFT JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = S.BRANCHID
        LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = S.ITEMPRICEID
        LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = S.ITEMCODEID
        LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = S.ITEMID
        LEFT JOIN TBLBRAND BR WITH(NOLOCK) ON BR.BRANDID = S.BRANDID
        LEFT JOIN TBLMANUFACTURER MAN WITH(NOLOCK) ON MAN.MANUFACTURERID = S.MANUFACTURERID
    ORDER BY
        S.PERIODICITY,
        OFR.OFFERNAME,
        B.BRANCHNAME,
        I.ITEMNAME,
        IC.ITEMCODE,
        IP.MRP;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_DELETEDITEMCODES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[USP_RPT_DELETEDITEMCODES]
AS
BEGIN
	
	SELECT 
		IC.ITEMCODEID, IC.ITEMCODE, I.ITEMNAME, I.SKUCODE
		, C.CATEGORYID, C.CATEGORYNAME AS Category
		, SC.SUBCATEGORYID, SC.SUBCATEGORYNAME AS [Sub Category]
		,BR.BRANDNAME, MAN.MANUFACTURERNAME
		, CU.FULLNAME AS CREATEDBY, IC.CREATEDDATE
		, UU.FULLNAME AS UPDATEDBY, IC.UPDATEDATE
		, DU.FULLNAME AS DELETEDBY, IC.DELETEDDATE
	FROM
		ITEMCODE IC
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY C ON C.CATEGORYID = I.CATEGORYID
		INNER JOIN SUBCATEGORY SC ON SC.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN TBLUSER CU ON CU.USERID = IC.CREATEDBY
		LEFT JOIN TBLUSER UU ON UU.USERID = IC.UPDATEDBY
		LEFT JOIN TBLUSER DU ON DU.USERID = IC.DELETEDBY		
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	WHERE
		IC.DELETEDDATE IS NOT NULL

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_DELETEDITEMPRICES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
