CREATE   proc [dbo].[USP_RPT_DELETEDITEMPRICES]
AS
BEGIN
	
	SELECT 		
		C.CATEGORYID, C.CATEGORYNAME, SC.SUBCATEGORYID, SC.SUBCATEGORYNAME
		, I.ITEMNAME, I.SKUCODE, IC.ITEMCODEID, IC.ITEMCODE
		, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, GST.GSTCODE
		, BR.BRANDNAME, MAN.MANUFACTURERNAME
		, CU.FULLNAME AS CREATEDBY, IP.CREATEDDATE
		, UU.FULLNAME AS UPDATEDBY, IP.UPDATEDATE
		, DU.FULLNAME AS DELETEDBY, IP.DELETEDDATE
	FROM
		ITEMPRICE IP 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY C ON C.CATEGORYID = I.CATEGORYID
		INNER JOIN SUBCATEGORY SC ON SC.SUBCATEGORYID = I.SUBCATEGORYID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		LEFT JOIN TBLUSER CU ON CU.USERID = IP.CREATEDBY
		LEFT JOIN TBLUSER UU ON UU.USERID = IP.UPDATEDBY
		LEFT JOIN TBLUSER DU ON DU.USERID = IP.DELETEDBY		
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	WHERE
		IP.DELETEDDATE IS NOT NULL
		AND IC.DELETEDDATE IS NULL
		AND I.DELETEDDATE IS NULL
		AND IP.BRANCHID IS NULL

END
