/****** Object:  StoredProcedure [dbo].[USP_RPT_DISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_DISPATCH]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(500)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeTrayNumber BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
	, @IncludeDispatchNumber BIT = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(MAX)
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, QUANTITY DECIMAL(18, 2), 
		AVGCOSTPRICEWOT DECIMAL(18, 2), AVGCOSTPRICEWT DECIMAL(18, 2), AVGCOSTPRICETAX DECIMAL(18, 2), 
		SALEPRICEWOT DECIMAL(18, 2), SALEPRICEWT DECIMAL(18, 2), SALEPRICETAX DECIMAL(18, 2), 
		TOTALAVGCPWOT DECIMAL(18, 2), TOTALAVGCPWT DECIMAL(18, 2), TOTALAVGCPTAX DECIMAL(18, 2), 
		TOTALSPWOT DECIMAL(18, 2), TOTALSPWT DECIMAL(18, 2), TOTALSPTAX DECIMAL(18, 2),
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT, TRAYNUMBER INT, BRANDID INT, MANUFACTURERID INT
		, STOCKDISPATCHID INT)

	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, CATEGORYID,SUBCATEGORYID,PERIODOCITY,QUANTITY,
	AVGCOSTPRICEWOT, AVGCOSTPRICEWT, AVGCOSTPRICETAX, SALEPRICEWT, SALEPRICEWOT, SALEPRICETAX, TOTALAVGCPWOT, 
	TOTALAVGCPWT, TOTALAVGCPTAX, TOTALSPWT, TOTALSPWOT, TOTALSPTAX, TRAYNUMBER, BRANDID, MANUFACTURERID, GSTID, STOCKDISPATCHID)
	SELECT CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END ,
		SUM(QUANTITY) AS QUANTITY,
		MAX(AVGCOSTPRICEWOT) AS AVGCOSTPRICEWOT,
		MAX(AVGCOSTPRICEWT) AS COSTPRICEWT,
		MAX(AVGCOSTPRICETAX) AS AVGCOSTPRICETAX,
		MAX(SALEPRICE) AS SALEPRICEWT,
		MAX(SALEPRICEWOT) AS SALEPRICEWOT,
		MAX(SALEPRICETAX) AS SALEPRICETAX,
		SUM(QUANTITY * AVGCOSTPRICEWOT) AS TOTALAVGCPWOT,
		SUM(QUANTITY * AVGCOSTPRICEWT) AS TOTALAVGCPWT,
		SUM(QUANTITY * AVGCOSTPRICETAX) AS TOTALAVGCPTAX,
		SUM(QUANTITY * SALEPRICE) AS TOTALSPWT,
		SUM(QUANTITY * SALEPRICEWOT) AS TOTALSPWOT,
		SUM(QUANTITY * SALEPRICETAX) AS TOTALSPTAX, 
		CASE WHEN @IncludeTrayNumber = 1 THEN TRAYNUMBER ELSE NULL END,
		CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END,
		CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN GSTID ELSE NULL END
		, CASE WHEN @IncludeDispatchNumber = 1 THEN STOCKDISPATCHID ELSE NULL END
	FROM (
			SELECT SDD.ITEMPRICEID, 
				SD.TOBRANCHID AS BRANCHID,
				I.CATEGORYID, 
				I.SUBCATEGORYID, 
				I.BRANDID,
				I.MANUFACTURERID,
				CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SDD.DISPATCHQUANTITY ELSE SDD.WEIGHTINKGS END AS QUANTITY, 				
				ISNULL(AVGCP.COSTPRICEWOT,0) AS AVGCOSTPRICEWOT,
				ISNULL(AVGCP.COSTPRICEWT,0) AS AVGCOSTPRICEWT,
				AVGCP.COSTPRICEWT - AVGCP.COSTPRICEWOT AS AVGCOSTPRICETAX,
				IP.SALEPRICE,
				(IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100 AS SALEPRICEWOT,
				IP.SALEPRICE - ((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100) AS SALEPRICETAX,
				SD.CREATEDDATE,
				SDD.TRAYNUMBER
				, IP.GSTID, SD.STOCKDISPATCHID
			FROM STOCKDISPATCHDETAIL SDD WITH(NOLOCK)
				INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
				INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SDD.ITEMPRICEID 
				LEFT JOIN AVGCOSTPRICE AVGCP WITH(NOLOCK) ON AVGCP.ITEMCODEID = IP.ITEMCODEID AND AVGCP.MRP = IP.MRP AND AVGCP.AVGCPDATE = DATEFROMPARTS(YEAR(SDD.CREATEDDATE), MONTH(SDD.CREATEDDATE), 1)
				INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = IP.GSTID
				INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SD.TOBRANCHID
				INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
			WHERE 
				(I.ITEMID = @ITEMID OR @ITEMID = 0)
				AND SD.CREATEDDATE > @FromDate
				AND SD.CREATEDDATE < @ToDate
				AND SD.DELETEDDATE IS NULL
				AND SDD.DELETEDDATE IS NULL
				AND SD.STATUS <> 0
		) AS BD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
		, CASE WHEN @IncludeTrayNumber = 1 THEN TRAYNUMBER ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN GSTID ELSE NULL END
		, CASE WHEN @IncludeDispatchNumber = 1 THEN STOCKDISPATCHID ELSE NULL END

	SELECT 
		PT.PERIODOCITY, B.BRANCHNAME, CAT.CATEGORYNAME,SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME , I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, 
		IP.MRP, GST.GSTCODE, PT.AVGCOSTPRICEWOT 'Avg. CP WOT', PT.AVGCOSTPRICEWT 'Avg. CP WT', PT.AVGCOSTPRICETAX 'Avg. CP Tax'
		, PT.SALEPRICEWOT, PT.SALEPRICEWT, PT.SALEPRICETAX, PT.QUANTITY, PT.TOTALAVGCPWOT 'Total Avg. CP WOT', PT.TOTALAVGCPWT 'Total Avg. CP WT'
		, PT.TOTALAVGCPTAX 'Total Avg. CP Tax', PT.TOTALSPWOT, PT.TOTALSPWT, PT.TOTALSPTAX, SD.DISPATCHNUMBER, PT.TRAYNUMBER
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID
		LEFT JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = PT.STOCKDISPATCHID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_DISPATCH_SUFFICIENCY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_DISPATCH_SUFFICIENCY]
AS
BEGIN

	SELECT BI.TOBRANCHID BRANCHID, BID.ITEMID, BID.BRANCHSTOCK, BID.LASTDISPATCHEDDATE, BID.INDENTQUANTITY
		, CAST(0.00 AS decimal(10, 2)) AS DISPATCHEDSTOCK, CAST(0.00 AS decimal(10, 2)) AS CURRENTWHSTOCK
	INTO #DS
	FROM
		BRANCHINDENTDETAIL BID
		INNER JOIN BRANCHINDENT BI ON BI.BRANCHINDENTID = BID.BRANCHINDENTID
	WHERE 
		BID.CREATEDDATE > CAST(GETDATE() AS DATE)
		AND BID.DELETEDDATE IS NULL
		AND BI.DELETEDDATE IS NULL
	
	INSERT INTO #DS
	SELECT SD.TOBRANCHID BRANCHID, I.ITEMID, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS BRANCHSTOCK
		, NULL, 0, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END) DISPATCHEDSTOCK, 0
	FROM 
		STOCKDISPATCHDETAIL SDD
		INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = SDD.ITEMPRICEID AND SS.BRANCHID = SD.TOBRANCHID
	WHERE
		SD.CREATEDDATE > CAST(GETDATE() AS DATE)
		AND SD.STATUS <> 0
		AND SD.DELETEDDATE IS NULL
		AND SDD.DELETEDDATE IS NULL
		AND NOT EXISTS
			(
				 SELECT 1
				 FROM #DS DS
				 WHERE DS.BRANCHID = SD.TOBRANCHID AND DS.ITEMID = I.ITEMID
			)
	GROUP BY SD.TOBRANCHID, I.ITEMID, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END 

	UPDATE DS
	SET DS.DISPATCHEDSTOCK = SD.DISPATCHEDSTOCK
	FROM
		#DS DS
		INNER JOIN 
			(
				SELECT SD.TOBRANCHID BRANCHID, I.ITEMID
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END) DISPATCHEDSTOCK
				FROM 
					STOCKDISPATCHDETAIL SDD
					INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
					INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = SDD.ITEMPRICEID AND SS.BRANCHID = SD.TOBRANCHID
				WHERE
					SD.CREATEDDATE > CAST(GETDATE() AS DATE)
					AND SD.STATUS <> 0
					AND SD.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
				GROUP BY SD.TOBRANCHID, I.ITEMID
			) SD ON SD.ITEMID = DS.ITEMID AND SD.BRANCHID = DS.BRANCHID

	UPDATE DS
	SET DS.CURRENTWHSTOCK = SS.WHSTOCK
	FROM
		#DS DS
		INNER JOIN 
			(
				SELECT SS.BRANCHID, I.ITEMID, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) AS WHSTOCK
				FROM 
					STOCKSUMMARY SS
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE SS.BRANCHID = 45
					AND IP.DELETEDDATE IS NULL
				GROUP BY I.ITEMID, SS.BRANCHID
			) SS ON DS.ITEMID = SS.ITEMID

	UPDATE DS
	SET DS.LASTDISPATCHEDDATE = SD.LASTDISPATCHDATE
	FROM
		#DS DS
		INNER JOIN 
			(
				SELECT SD.TOBRANCHID BRANCHID, I.ITEMID, MAX(SD.CREATEDDATE) LASTDISPATCHDATE
				FROM 
					STOCKDISPATCHDETAIL SDD
					INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE
					SD.STATUS <> 0
					AND SD.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
				GROUP BY SD.TOBRANCHID, I.ITEMID
			) SD ON SD.ITEMID = DS.ITEMID AND SD.BRANCHID = DS.BRANCHID

	SELECT DS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, BRND.BRANDNAME, MAN.MANUFACTURERNAME
		, DS.CURRENTWHSTOCK, SUM(DS.INDENTQUANTITY) INDENTQUANTITY, SUM(DS.DISPATCHEDSTOCK) DISPATCHEDSTOCK
		, CASE WHEN SUM(DS.DISPATCHEDSTOCK) > SUM(DS.INDENTQUANTITY) THEN DS.CURRENTWHSTOCK
			ELSE DS.CURRENTWHSTOCK - CASE WHEN SUM(DS.INDENTQUANTITY) > 0 THEN (SUM(DS.INDENTQUANTITY) - SUM(DS.DISPATCHEDSTOCK))
			ELSE 0 END END AS SUFFICIENCY
	FROM 
		#DS DS
		INNER JOIN ITEM I ON I.ITEMID = DS.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN TBLBRAND BRND ON BRND.BRANDID = I.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON MAN.MANUFACTURERID = I.MANUFACTURERID
	GROUP BY DS.ITEMID, I.SKUCODE, I.ITEMNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, BRND.BRANDNAME, MAN.MANUFACTURERNAME, DS.CURRENTWHSTOCK
	ORDER BY SUFFICIENCY

	SELECT DS.ITEMID, B.BRANCHNAME, DS.BRANCHSTOCK, DS.INDENTQUANTITY, DS.LASTDISPATCHEDDATE
	FROM 
		#DS DS
		INNER JOIN BRANCH B ON B.BRANCHID = DS.BRANCHID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_DISPATCH_VS_SALES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_DISPATCH_VS_SALES]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchIDs VARCHAR(500)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeItemPrice BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0
	, @IncludeStock BIT = 0
	, @ITEMID INT = 0
	, @CategoryIDs VARCHAR(500) 
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
		
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryIDs,',')

	CREATE TABLE #DATA(TRANSACTIONDATE DATE, BRANCHID INT, ITEMID INT, ITEMCODEID INT, MRP DECIMAL(18, 2)
		, DISPATCHQTY DECIMAL(18, 2) DEFAULT 0, SALEQTY DECIMAL(18, 2) DEFAULT 0) 

	SELECT CAST(SD.CREATEDDATE AS DATE) TRANSACTIONDATE, SD.TOBRANCHID BRANCHID, I.ITEMID, IC.ITEMCODEID, IP.MRP
		, ISNULL(CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END, 0) DISPATCHQTY
	INTO #DISPATCH
	FROM
		STOCKDISPATCH SD WITH(NOLOCK)
		INNER JOIN STOCKDISPATCHDETAIL SDD WITH(NOLOCK) ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #BRANCH B ON B.Item = SD.TOBRANCHID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID		
	WHERE
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND SD.DELETEDDATE IS NULL
		AND SDD.DELETEDDATE IS NULL
		AND SD.CREATEDDATE >= @FromDate 
		AND SD.CREATEDDATE < @ToDate
		AND SD.STATUS <> 0

	SELECT CAST(PB.CREATEDDATE AS DATE) TRANSACTIONDATE, BC.BRANCHID, I.ITEMID, IC.ITEMCODEID, IP.MRP
		, ISNULL(CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END, 0) SALEQTY
	INTO #SALES
	FROM
		POS_BILLDETAIL PBD WITH(NOLOCK)
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		--AND (I.CATEGORYID = @CategoryID OR @CategoryID = 13)
		AND PBD.CREATEDDATE > (@FromDate)
		AND PBD.CREATEDDATE < @ToDate
		AND PBD.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1

	SELECT CAST(PCR.CREATEDDATE AS DATE) TRANSACTIONDATE, BC.BRANCHID, I.ITEMID, IC.ITEMCODEID, IP.MRP
		, ISNULL(CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END, 0) REFUNDQTY
	INTO #CREFUND
	FROM
		POS_CREFUND PCR WITH(NOLOCK)
		INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = PCR.BILLDETAILID AND PBD.BRANCHCOUNTERID = PCR.REFUNDID		
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		--AND (I.CATEGORYID = @CategoryID OR @CategoryID = 13)
		AND PCR.CREATEDDATE > (@FromDate)
		AND PCR.CREATEDDATE < @ToDate
		AND PCR.DELETEDDATE IS NULL		

	INSERT INTO #DATA(TRANSACTIONDATE, BRANCHID, ITEMID, ITEMCODEID, MRP)
	SELECT DISTINCT CAST(DT.TRANSACTIONDATE AS DATE), DT.BRANCHID, DT.ITEMID, DT.ITEMCODEID, DT.MRP
	FROM
		(
			SELECT TRANSACTIONDATE, BRANCHID, ITEMID, ITEMCODEID, MRP
			FROM #DISPATCH

			UNION ALL

			SELECT TRANSACTIONDATE, BRANCHID, ITEMID, ITEMCODEID, MRP
			FROM #SALES	
			
			UNION ALL

			SELECT TRANSACTIONDATE, BRANCHID, ITEMID, ITEMCODEID, MRP
			FROM #CREFUND	
		) DT


	UPDATE DT
	SET DT.DISPATCHQTY = SD.DISPATCHQTY
	FROM
		#DATA DT
		INNER JOIN 
			(
				SELECT ITEMID, BRANCHID, TRANSACTIONDATE, ITEMCODEID, MRP, SUM(ISNULL(DISPATCHQTY, 0)) DISPATCHQTY
				FROM #DISPATCH SD
				GROUP BY ITEMID, ITEMCODEID, MRP, BRANCHID, SD.TRANSACTIONDATE
			) SD ON DT.BRANCHID = SD.BRANCHID AND DT.ITEMID = SD.ITEMID AND DT.TRANSACTIONDATE = SD.TRANSACTIONDATE
				AND SD.ITEMCODEID = DT.ITEMCODEID AND SD.MRP = DT.MRP

	UPDATE DT
	SET DT.SALEQTY = BILL.SALEQTY
	FROM
		#DATA DT
		INNER JOIN 
			(
				SELECT ITEMID, ITEMCODEID, MRP, BRANCHID, TRANSACTIONDATE, SUM(ISNULL(SALEQTY, 0)) SALEQTY
				FROM #SALES
				GROUP BY ITEMID, ITEMCODEID, MRP, BRANCHID, TRANSACTIONDATE
			) BILL ON DT.BRANCHID = BILL.BRANCHID AND DT.ITEMID = BILL.ITEMID AND DT.TRANSACTIONDATE = BILL.TRANSACTIONDATE
				AND BILL.ITEMCODEID = DT.ITEMCODEID AND BILL.MRP = DT.MRP

	UPDATE DT
	SET DT.SALEQTY = DT.SALEQTY - BILL.REFUNDQTY
	FROM
		#DATA DT
		INNER JOIN 
			(
				SELECT ITEMID, ITEMCODEID, MRP, BRANCHID, TRANSACTIONDATE, SUM(ISNULL(REFUNDQTY, 0)) REFUNDQTY
				FROM #CREFUND
				GROUP BY ITEMID, ITEMCODEID, MRP, BRANCHID, TRANSACTIONDATE
			) BILL ON DT.BRANCHID = BILL.BRANCHID AND DT.ITEMID = BILL.ITEMID AND DT.TRANSACTIONDATE = BILL.TRANSACTIONDATE
				AND BILL.ITEMCODEID = DT.ITEMCODEID AND BILL.MRP = DT.MRP
	
	CREATE TABLE #FINALDATA(MRP DECIMAL(18, 2), ITEMCODEID INT, BRANCHID INT, CATEGORYID INT, SUBCATEGORYID INT
		, TRANSACTIONDATE DATE, DISPATCHQTY DECIMAL(18, 2), SALEQTY DECIMAL(18, 2), CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT
		, ITEMID INT, BRANDID INT, MANUFACTURERID INT, CURBRANCHSTOCK DECIMAL(18, 2), CURWHSTOCK DECIMAL(18, 2))
	
	INSERT INTO #FINALDATA
	SELECT 
		CASE WHEN @IncludeItemPrice = 1 THEN MRP ELSE NULL END MRP
		, CASE WHEN @IncludeItemPrice = 1 THEN ITEMCODEID ELSE NULL END ITEMCODEID
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END BRANCHID 
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END CATEGORYID 
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END SUBCATEGORYID 
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(TRANSACTIONDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(TRANSACTIONDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(TRANSACTIONDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(TRANSACTIONDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END	TRANSACTIONDATE	
		, SUM(DISPATCHQTY) AS DISPATCHQTY 
		, SUM(SALEQTY) AS SALEQTY		
		, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END CLASSIFICATIONID
		, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END SUBCLASSIFICATIONID
		, CASE WHEN @IncludeItem = 1 THEN BD.ITEMID ELSE NULL END ITEMID
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END BRANDID
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END MANUFACTURERID
		, 0.00 CURBRANCHSTOCK, 0.00 CURWHSTOCK	
	FROM 
		#DATA BD
		INNER JOIN ITEM I ON I.ITEMID = BD.ITEMID
	GROUP BY 
		CASE WHEN @IncludeItemPrice = 1 THEN MRP ELSE NULL END
		, CASE WHEN @IncludeItemPrice = 1 THEN ITEMCODEID ELSE NULL END 
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(TRANSACTIONDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(TRANSACTIONDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(TRANSACTIONDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(TRANSACTIONDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END		
		, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BD.ITEMID ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	
	UPDATE DT
	SET DT.CURWHSTOCK = WHS.CURWHSTOCK
	FROM
		#FINALDATA DT
		LEFT JOIN 
			(
				SELECT I.ITEMID
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) CURWHSTOCK
				FROM 
					STOCKSUMMARY SSINNER WITH(NOLOCK) 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE IP.DELETEDDATE IS NULL
					AND SSINNER.BRANCHID = 45
				GROUP BY I.ITEMID
			) WHS ON WHS.ITEMID = DT.ITEMID
	WHERE @IncludeStock = 1

	UPDATE DT
	SET DT.CURBRANCHSTOCK = BSTOCK.CURBSTOCK
	FROM
		#FINALDATA DT		
		LEFT JOIN
			(
				SELECT 
					SSINNER.BRANCHID, I.ITEMID
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) CURBSTOCK
				FROM 
					STOCKSUMMARY SSINNER WITH(NOLOCK) 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE IP.DELETEDDATE IS NULL
				GROUP BY SSINNER.BRANCHID, I.ITEMID
			) BSTOCK ON BSTOCK.BRANCHID = DT.BRANCHID AND BSTOCK.ITEMID = DT.ITEMID
	WHERE @IncludeStock = 1
		
	SELECT 
		PT.TRANSACTIONDATE, B.BRANCHNAME, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME, BR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IC.HSNCODE
		, PT.MRP, PT.DISPATCHQTY, PT.SALEQTY, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME
		, PT.CURWHSTOCK, PT.CURBRANCHSTOCK
	FROM 
		#FINALDATA PT		
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = PT.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = PT.ITEMID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC WITH(NOLOCK) ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = PT.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS WITH(NOLOCK) ON ISCLS.SUBCLASSIFICATIONID = PT.SUBCLASSIFICATIONID
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4, I.ITEMNAME, IC.ITEMCODE, PT.MRP
	
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_DISPATCHDIFF]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_DISPATCHDIFF]
@BranchID VARCHAR(MAX),
@CategoryID VARCHAR(MAX),
@FromDate DATE,
@ToDate DATE
AS
BEGIN

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	SELECT 
		ROW_NUMBER() OVER(ORDER BY SD.STOCKDISPATCHID ASC) AS SNO,
		SD.CREATEDDATE 'Dispatch date',
		B.BRANCHNAME,
		I.SKUCODE,
		IC.ITEMCODE,
		I.ITEMNAME,
		IP.MRP,
		IP.SALEPRICE,
		SDD.DISPATCHQUANTITY,
		SDD.RECEIVEDQUANTITY,
		SDD.RECEIVEDQUANTITY - SDD.DISPATCHQUANTITY AS STOCKDIFF,
		SD.STOCKDISPATCHID,
		SD.DISPATCHNUMBER,
		C.CATEGORYNAME

	FROM STOCKDISPATCHDETAIL SDD
	INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
	INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SD.TOBRANCHID
	INNER JOIN ITEMPRICE IP ON SDD.ITEMPRICEID = IP.ITEMPRICEID
	INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
	INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
	INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
	INNER JOIN BRANCH B ON B.BRANCHID= SD.TOBRANCHID
	WHERE SDD.DELETEDDATE IS NULL
		AND SDD.CREATEDDATE >= @FROMDATE
		AND SDD.CREATEDDATE <= @TODATE
		AND SD.STATUSAPPROVEDDATE IS NOT NULL
		AND SDD.DISPATCHQUANTITY - SDD.RECEIVEDQUANTITY <> 0
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_GST_BY_PAYMENT_MODE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_GST_BY_PAYMENT_MODE]
(
	@FromDate DATE
	, @ToDate DATE
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	
	SELECT PB.BRANCHCOUNTERID, PB.BILLID, CAST(PB.CREATEDDATE AS DATE) BILLDATE, CAST(0.00 AS DECIMAL(18, 2)) AS TOTALBILLAMOUNT, PBD.GSTID, SUM(PBD.CGST) GSTWISEBILLCGST, SUM(PBD.SGST) GSTWISEBILLSGST
		, SUM(PBD.IGST) GSTWISEBILLIGST, SUM(PBD.CESS) GSTWISEBILLCESS, SUM(PBD.GSTVALUE) GSTWISEBILLGSTVALUE, SUM(PBD.BILLEDAMOUNT) GSTWISEBILLAMOUNT
		, PBMD.MOPID, PBMD.MOPVALUE, CAST(0.00 AS DECIMAL(18, 2))  AS CGSTWISEMOPVALUE, CAST(0.00 AS DECIMAL(18, 2))  AS SGSTWISEMOPVALUE, CAST(0.00 AS DECIMAL(18, 2))  AS IGSTWISEMOPVALUE
		, CAST(0.00 AS DECIMAL(18, 2))  AS CESSGSTWISEMOPVALUE, CAST(0.00 AS DECIMAL(18, 2))  AS TOTALGSTWISEMOPVALUE, CAST(0.00 AS DECIMAL(18, 2))  AS TOTALAMOUNTMOPVALUE
	INTO #GSTWISE
	FROM
		POS_BILLDETAIL PBD WITH(NOLOCK)
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID	
		INNER JOIN POS_BILLMOPDETAIL PBMD WITH(NOLOCK) ON PBMD.BILLID = PB.BILLID AND PBMD.COUNTERID = PB.BRANCHCOUNTERID
	WHERE
		PBD.CREATEDDATE > @FromDate
		AND PBD.CREATEDDATE < @ToDate
		AND PBD.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1
	GROUP BY PBD.GSTID, PB.BRANCHCOUNTERID, PB.BILLID, CAST(PB.CREATEDDATE AS DATE), PBMD.MOPID, PBMD.MOPVALUE
	
	UPDATE GSTWISE
	SET GSTWISE.TOTALBILLAMOUNT = ISNULL(TOTALS.TOTALBILLAMOUNT, 0)
	FROM
		#GSTWISE GSTWISE
		INNER JOIN 
			(
				SELECT PB.BRANCHCOUNTERID, PB.BILLID, SUM(PBD.BILLEDAMOUNT) TOTALBILLAMOUNT
				FROM
					POS_BILLDETAIL PBD WITH(NOLOCK)
					INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID	
				WHERE
					PBD.CREATEDDATE > @FromDate
					AND PBD.CREATEDDATE < @ToDate
					AND PBD.DELETEDDATE IS NULL
					AND PB.BILLSTATUS = 1
				GROUP BY PB.BRANCHCOUNTERID, PB.BILLID
			) TOTALS ON TOTALS.BILLID = GSTWISE.BILLID AND TOTALS.BRANCHCOUNTERID = GSTWISE.BRANCHCOUNTERID

	---- FIX ROUNDING
	--UPDATE GSTWISE
	--SET GSTWISE.TOTALBILLAMOUNT = ROUND(GSTWISE.TOTALBILLAMOUNT, 0)
	--FROM #GSTWISE GSTWISE
	--WHERE 
	--	GSTWISE.MOPID = 1 /*CASH MOPID*/
	--	AND NOT EXISTS
	--		(
	--			SELECT 1 FROM #GSTWISE GSTWISEINNER
	--			WHERE GSTWISEINNER.BILLID = GSTWISE.BILLID
	--				AND GSTWISEINNER.BRANCHCOUNTERID = GSTWISE.BRANCHCOUNTERID
	--				AND GSTWISEINNER.MOPID <> 1
	--		)

	UPDATE GSTWISE
	SET GSTWISE.CGSTWISEMOPVALUE = GSTWISE.MOPVALUE * (GSTWISE.GSTWISEBILLCGST / GSTWISE.TOTALBILLAMOUNT)
		, GSTWISE.SGSTWISEMOPVALUE = GSTWISE.MOPVALUE * (GSTWISE.GSTWISEBILLSGST / GSTWISE.TOTALBILLAMOUNT)
		, GSTWISE.IGSTWISEMOPVALUE = GSTWISE.MOPVALUE * (GSTWISE.GSTWISEBILLIGST / GSTWISE.TOTALBILLAMOUNT)
		, GSTWISE.CESSGSTWISEMOPVALUE = GSTWISE.MOPVALUE * (GSTWISE.GSTWISEBILLCESS / GSTWISE.TOTALBILLAMOUNT)
		, GSTWISE.TOTALGSTWISEMOPVALUE = GSTWISE.MOPVALUE * (GSTWISE.GSTWISEBILLGSTVALUE / GSTWISE.TOTALBILLAMOUNT)
		, GSTWISE.TOTALAMOUNTMOPVALUE = GSTWISE.MOPVALUE * (GSTWISE.GSTWISEBILLAMOUNT / GSTWISE.TOTALBILLAMOUNT)
	FROM
		#GSTWISE GSTWISE
		
	-- INSERT REFUNDS
	INSERT INTO #GSTWISE
	SELECT CR.COUNTERID, PBD.BILLID, CAST(CR.CREATEDDATE AS DATE), 0.00, PBD.GSTID, -(PBD.CGST / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.SGST / PBD.QUANTITY) * CR.REFUNDQUANTITY
		, -(PBD.IGST / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.CESS / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.GSTVALUE / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.BILLEDAMOUNT / PBD.QUANTITY) * CR.REFUNDQUANTITY
		, 1 /*CASH MOPID*/, -(PBD.BILLEDAMOUNT / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.CGST / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.SGST / PBD.QUANTITY) * CR.REFUNDQUANTITY
		, -(PBD.IGST / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.CESS / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.GSTVALUE / PBD.QUANTITY) * CR.REFUNDQUANTITY, -(PBD.BILLEDAMOUNT / PBD.QUANTITY) * CR.REFUNDQUANTITY 	
	FROM 
		POS_CREFUND CR
		INNER JOIN POS_BILLDETAIL PBD ON PBD.BILLDETAILID = CR.BILLDETAILID AND PBD.BRANCHCOUNTERID = CR.COUNTERID
	WHERE
		CR.DELETEDDATE IS NULL
		AND CR.CREATEDDATE > @FromDate
		AND CR.CREATEDDATE < @ToDate
		
	SELECT BC.BRANCHID, GSTWISE.BILLDATE, GSTWISE.GSTID, GSTWISE.MOPID
		, SUM(GSTWISE.TOTALAMOUNTMOPVALUE - GSTWISE.TOTALGSTWISEMOPVALUE) TAXABLEAMOUNT , SUM(GSTWISE.CGSTWISEMOPVALUE) CGST, SUM(GSTWISE.SGSTWISEMOPVALUE) SGST
		, SUM(GSTWISE.IGSTWISEMOPVALUE) IGST, SUM(GSTWISE.CESSGSTWISEMOPVALUE) CESS, SUM(GSTWISE.TOTALGSTWISEMOPVALUE) TOTALGST, SUM(GSTWISE.TOTALAMOUNTMOPVALUE) BILLEDAMOUNT
	INTO #TOTALS
	FROM
		#GSTWISE GSTWISE
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = GSTWISE.BRANCHCOUNTERID
	GROUP BY BC.BRANCHID, GSTWISE.BILLDATE, GSTWISE.GSTID, GSTWISE.MOPID
	
	SELECT 
		B.BRANCHNAME, BILLDATE, MOP.MOPNAME
		, (SELECT CAST(ISNULL(SUM(GSTINNER.TAXABLEAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 6) 'GST 0% Taxable Amt'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.CGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 6) 'GST 0% CGST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.SGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 6) 'GST 0% SGST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.IGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 6) 'GST 0% IGST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.CESS), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 6) 'GST 0% CESS'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.TOTALGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 6) 'GST 0% Total GST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.BILLEDAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 6) 'GST 0% Total Amt'
				  
		, (SELECT CAST(ISNULL(SUM(GSTINNER.TAXABLEAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 7) 'GST 3% Taxable Amt'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.CGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER  
			WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 7) 'GST 3% CGST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.SGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 7) 'GST 3% SGST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.IGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 7) 'GST 3% IGST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.CESS), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 7) 'GST 3% CESS'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.TOTALGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 7) 'GST 3% Total GST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.BILLEDAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 7) 'GST 3% Total Amt'
				  
		, (SELECT CAST(ISNULL(SUM(GSTINNER.TAXABLEAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 4) 'GST 5% Taxable Amt'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.CGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
