		, (SELECT CAST(ISNULL(SUM(GSTINNER.BILLEDAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE AND GSTINNER.GSTID = 12) 'GST 28 + 36C % Total Amt'

		, (SELECT CAST(ISNULL(SUM(GSTINNER.TAXABLEAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE) 'Total Taxable Amt'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.TOTALGST), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE) 'Total GST'
		, (SELECT CAST(ISNULL(SUM(GSTINNER.BILLEDAMOUNT), 0) AS DECIMAL(18, 2)) FROM #TOTALS GSTINNER 
			 WHERE GSTINNER.BRANCHID = MOPWISE.BRANCHID AND GSTINNER.MOPID = MOPWISE.MOPID AND GSTINNER.BILLDATE = MOPWISE.BILLDATE) 'Total Amt'
	FROM
		(
			SELECT DISTINCT BRANCHID, MOPID, BILLDATE FROM #TOTALS
		) MOPWISE
		INNER JOIN BRANCH B ON B.BRANCHID = MOPWISE.BRANCHID
		INNER JOIN TBLMOP MOP ON MOP.MOPID = MOPWISE.MOPID
	ORDER BY B.BRANCHNAME, BILLDATE, MOP.MOPNAME


END
