/****** Object:  StoredProcedure [dbo].[USP_RPT_HSN_WISE_SALE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_HSN_WISE_SALE]
(
	@BranchIDs VARCHAR(MAX)
	, @FromDate DATE
	, @ToDate DATE
	, @IncludeB2C BIT = 0
	, @IncludeB2B BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDS,',')

	SELECT * 
	INTO #MOPIDS
	FROM
		(
			SELECT MOPID FROM TBLMOP WHERE DELETEDDATE IS NULL AND @IncludeB2B = 1 AND MOPNAME = 'B2B Credit' UNION ALL
			SELECT MOPID FROM TBLMOP WHERE DELETEDDATE IS NULL AND @IncludeB2C = 1 AND MOPNAME <> 'B2B Credit'
		) MOP

	IF NOT EXISTS ( SELECT 1 FROM #MOPIDS )
	BEGIN
		SELECT 'Both B2C AND B2B are disabled, no data to show'
		RETURN
	END
		

	SELECT 
		ISNULL(I.HSNCODE, IC.HSNCODE) HSNCODE, I.ITEMNAME, UQCCODE
		, SUM(CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END) TOTALQUANTITY
		, SUM(PBD.BILLEDAMOUNT) TOTALVALUE, GST.GSTCODE, SUM(PBD.BILLEDAMOUNT - PBD.GSTVALUE) TOTALTAXABLEVALUE
		, SUM(PBD.IGST) TOTALINTEGRATEDTAX, SUM(PBD.CGST) TOTALCENTRALTAX, SUM(PBD.SGST) TOTALSTATETAX, SUM(PBD.CESS) TOTALCESS
	INTO #HSNWISETAX
	FROM POS_BILLDETAIL PBD WITH(NOLOCK)
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = PBD.GSTID
		LEFT JOIN UQCDATA UC ON UC.UQCID = I.UQCID		
	WHERE
		1 = 1
		AND PBD.CREATEDDATE > (@FromDate)
		AND PBD.CREATEDDATE < @ToDate
		AND PBD.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1
		AND (
				(@IncludeB2C = 1 AND @IncludeB2B = 1)
				OR EXISTS
					(
						SELECT 1 
						FROM POS_BILLMOPDETAIL PBMD WITH(NOLOCK)
						WHERE 
							PBMD.BILLID = PB.BILLID
							AND PBMD.COUNTERID = PB.BRANCHCOUNTERID
							AND EXISTS
								(
									SELECT 1
									FROM #MOPIDS MOPIDS 
									WHERE MOPIDS.MOPID = PBMD.MOPID
								)
					)
			)
	GROUP BY GST.GSTCODE, ISNULL(I.HSNCODE, IC.HSNCODE), I.ITEMNAME, UQCCODE

	INSERT INTO #HSNWISETAX
	SELECT 
		ISNULL(I.HSNCODE, IC.HSNCODE) HSNCODE, I.ITEMNAME, UQCCODE
		, -SUM(CASE WHEN I.ISOPENITEM = 1 THEN CR.REFUNDWEIGHTINKGS ELSE CR.REFUNDQUANTITY END) TOTALQUANTITY
		, -SUM(CR.REFUNDAMOUNT) TOTALVALUE, GST.GSTCODE
		, -SUM(CR.REFUNDAMOUNT - ((PBD.GSTVALUE / CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END)
			* (CASE WHEN I.ISOPENITEM = 1 THEN CR.REFUNDWEIGHTINKGS ELSE CR.REFUNDQUANTITY END))) TOTALTAXABLEVALUE
		, -SUM(((PBD.IGST / (CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END))
			* (CASE WHEN I.ISOPENITEM = 1 THEN CR.REFUNDWEIGHTINKGS ELSE CR.REFUNDQUANTITY END))) TOTALINTEGRATEDTAX
		, -SUM(((PBD.CGST / (CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END))
			* (CASE WHEN I.ISOPENITEM = 1 THEN CR.REFUNDWEIGHTINKGS ELSE CR.REFUNDQUANTITY END))) TOTALCENTRALTAX
		, -SUM(((PBD.SGST / (CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END))
			* (CASE WHEN I.ISOPENITEM = 1 THEN CR.REFUNDWEIGHTINKGS ELSE CR.REFUNDQUANTITY END))) TOTALSTATETAX
		, -SUM(((PBD.CESS / (CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END))
			* (CASE WHEN I.ISOPENITEM = 1 THEN CR.REFUNDWEIGHTINKGS ELSE CR.REFUNDQUANTITY END))) TOTALCESS
	FROM 
		POS_CREFUND CR WITH(NOLOCK)
		INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CR.BILLDETAILID AND PBD.BRANCHCOUNTERID = CR.COUNTERID
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = PBD.GSTID
		LEFT JOIN UQCDATA UC ON UC.UQCID = I.UQCID		
	WHERE
		1 = 1
		AND CR.CREATEDDATE > (@FromDate)
		AND CR.CREATEDDATE < @ToDate
		AND CR.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1
		AND 
			(
				(@IncludeB2C = 1 AND @IncludeB2B = 1)
				OR EXISTS
					(
						SELECT 1 
						FROM POS_BILLMOPDETAIL PBMD WITH(NOLOCK)
						WHERE 
							PBMD.BILLID = PB.BILLID
							AND PBMD.COUNTERID = PB.BRANCHCOUNTERID
							AND EXISTS
								(
									SELECT 1
									FROM #MOPIDS MOPIDS 
									WHERE MOPIDS.MOPID = PBMD.MOPID
								)
				)
			)
	GROUP BY GST.GSTCODE, ISNULL(I.HSNCODE, IC.HSNCODE), I.ITEMNAME, UQCCODE


	SELECT HSNCODE, ITEMNAME, UQCCODE, SUM(TOTALQUANTITY) TOTALQUANTITY, SUM(TOTALVALUE) TOTALVALUE
		, GSTCODE, SUM(TOTALTAXABLEVALUE) TOTALTAXABLEVALUE, SUM(TOTALINTEGRATEDTAX) TOTALINTEGRATEDTAX
		, SUM(TOTALCENTRALTAX) TOTALCENTRALTAX, SUM(TOTALSTATETAX) TOTALSTATETAX, SUM(TOTALCESS) TOTALCESS
	FROM #HSNWISETAX
	GROUP BY GSTCODE, HSNCODE, ITEMNAME, UQCCODE
	ORDER BY LEN(GSTCODE), GSTCODE, ITEMNAME

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_INDENTVSDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_INDENTVSDISPATCH]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchIDs VARCHAR(MAX)
	, @CategoryIDs VARCHAR(MAX)
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryIDs,',')
	
	CREATE TABLE #INDENTDATA(ITEMID INT, BRANCHID INT, INDENTDATE DATE, PREVBRANCHSTOCK DECIMAL(18, 2) DEFAULT 0
		, INDENTQUANTITY DECIMAL(18, 2) DEFAULT 0, DISPATCHQTY DECIMAL(18, 2) DEFAULT 0
		, PREVWHSTOCK DECIMAL(18, 2) DEFAULT 0, CURBSTOCK DECIMAL(18, 2) DEFAULT 0, CURWHSTOCK DECIMAL(18, 2) DEFAULT 0)

	INSERT INTO #INDENTDATA(ITEMID, BRANCHID, INDENTDATE)
	SELECT DISTINCT ID.ITEMID, ID.BRANCHID, CAST(ID.CREATEDDATE AS DATE)
	FROM
		(
			SELECT BID.ITEMID, BI.TOBRANCHID BRANCHID, BI.CREATEDDATE
			FROM
				BRANCHINDENTDETAIL BID
				INNER JOIN BRANCHINDENT BI ON BI.BRANCHINDENTID = BID.BRANCHINDENTID
				INNER JOIN ITEM I ON I.ITEMID = BID.ITEMID
				INNER JOIN #BRANCH B ON B.Item = BI.TOBRANCHID
				INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID		
			WHERE
				BI.DELETEDDATE IS NULL
				AND BID.DELETEDDATE IS NULL
				AND BI.CREATEDDATE >= @FromDate 
				AND BI.CREATEDDATE < @ToDate

			UNION ALL

			SELECT I.ITEMID, SD.TOBRANCHID, SD.CREATEDDATE
			FROM
				STOCKDISPATCHDETAIL SDD
				INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN #BRANCH B ON B.Item = SD.TOBRANCHID
				INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID		
			WHERE
				SD.DELETEDDATE IS NULL
				AND SDD.DELETEDDATE IS NULL
				AND SD.CREATEDDATE >= @FromDate 
				AND SD.CREATEDDATE < @ToDate
				AND SD.STATUS <> 0
		) ID

	UPDATE ID
	SET ID.INDENTQUANTITY = BD.INDENTQUANTITY, ID.PREVBRANCHSTOCK = BD.BRANCHSTOCK, ID.PREVWHSTOCK = BD.WHSTOCK
	FROM
		#INDENTDATA ID
		INNER JOIN 
			(
				SELECT BID.ITEMID, BI.TOBRANCHID BRANCHID, CAST(BI.CREATEDDATE AS DATE) CREATEDDATE
					, SUM(BID.INDENTQUANTITY) INDENTQUANTITY, MAX(BID.BRANCHSTOCK) BRANCHSTOCK, MIN(BID.WHSTOCK) WHSTOCK
				FROM
					BRANCHINDENTDETAIL BID
					INNER JOIN BRANCHINDENT BI ON BI.BRANCHINDENTID = BID.BRANCHINDENTID
					INNER JOIN ITEM I ON I.ITEMID = BID.ITEMID
					INNER JOIN #BRANCH B ON B.Item = BI.TOBRANCHID
					INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID		
				WHERE
					BI.DELETEDDATE IS NULL
					AND BID.DELETEDDATE IS NULL
					AND BI.CREATEDDATE >= @FromDate 
					AND BI.CREATEDDATE < @ToDate
				GROUP BY BID.ITEMID, BI.TOBRANCHID, CAST(BI.CREATEDDATE AS DATE)
			) BD ON ID.BRANCHID = BD.BRANCHID AND ID.ITEMID = BD.ITEMID AND ID.INDENTDATE = BD.CREATEDDATE
	
	UPDATE ID
	SET ID.DISPATCHQTY = SD.DISPATCHQTY
	FROM
		#INDENTDATA ID
		INNER JOIN 
			(
				SELECT I.ITEMID, SD.TOBRANCHID BRANCHID, CAST(SD.CREATEDDATE AS DATE) CREATEDDATE
					, SUM(ISNULL(CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END, 0)) DISPATCHQTY
				FROM
					STOCKDISPATCHDETAIL SDD
					INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
					INNER JOIN #BRANCH B ON B.Item = SD.TOBRANCHID
					INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID		
				WHERE
					SD.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
					AND SD.CREATEDDATE >= @FromDate 
					AND SD.CREATEDDATE < @ToDate
					AND SD.STATUS <> 0
				GROUP BY I.ITEMID, SD.TOBRANCHID, CAST(SD.CREATEDDATE AS DATE)
			) SD ON ID.BRANCHID = SD.BRANCHID AND ID.ITEMID = SD.ITEMID AND ID.INDENTDATE = SD.CREATEDDATE

	UPDATE ID
	SET ID.CURWHSTOCK = WHS.CURWHSTOCK
	FROM
		#INDENTDATA ID
		LEFT JOIN 
			(
				SELECT I.ITEMID
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) CURWHSTOCK
				FROM 
					STOCKSUMMARY SSINNER WITH(NOLOCK) 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE IP.DELETEDDATE IS NULL
					AND SSINNER.BRANCHID = 45
				GROUP BY I.ITEMID
			) WHS ON WHS.ITEMID = ID.ITEMID

	UPDATE ID
	SET ID.CURBSTOCK = BSTOCK.CURBSTOCK
	FROM
		#INDENTDATA ID		
		LEFT JOIN
			(
				SELECT 
					SSINNER.BRANCHID, I.ITEMID
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) CURBSTOCK
				FROM 
					STOCKSUMMARY SSINNER WITH(NOLOCK) 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				WHERE IP.DELETEDDATE IS NULL
				GROUP BY SSINNER.BRANCHID, I.ITEMID
			) BSTOCK ON BSTOCK.BRANCHID = ID.BRANCHID AND BSTOCK.ITEMID = ID.ITEMID

	SELECT 
		ID.INDENTDATE IndentDate, B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME
		, ID.INDENTQUANTITY, ID.DISPATCHQTY, ID.DISPATCHQTY - ID.INDENTQUANTITY DIFF
		, ID.PREVBRANCHSTOCK, ID.PREVWHSTOCK, ID.CURBSTOCK, ID.CURWHSTOCK
	FROM
		#INDENTDATA ID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = ID.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		INNER JOIN BRANCH B ON B.BRANCHID = ID.BRANCHID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
	ORDER BY DIFF, PREVWHSTOCK DESC

	/*
	SELECT 
		BID.BRANCHINDENTID, SD.STOCKDISPATCHID, SDD.STOCKDISPATCHDETAILID, BID.ITEMID, BID.INDENTQUANTITY, BID.BRANCHSTOCK, BID.WHSTOCK
		, SUM(ISNULL(CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END, 0)) DISPATCHQTY
		, CAST(0.00 AS DECIMAL(18, 2)) CURBSTOCK, CAST(0.00 AS DECIMAL(18, 2)) CURWHSTOCK
		, BI.FROMBRANCHID, BI.TOBRANCHID, BI.CREATEDDATE
	INTO #INDENTDATA
	FROM 
		BRANCHINDENTDETAIL BID 
		INNER JOIN BRANCHINDENT BI ON BI.BRANCHINDENTID = BID.BRANCHINDENTID
		LEFT JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.BRANCHINDENTID = BI.BRANCHINDENTID AND SD.STATUS <> 0
		LEFT JOIN STOCKDISPATCHDETAIL SDD WITH(NOLOCK) ON SDD.BRANCHINDENTDETAILID = BID.BRANCHINDENTDETAILID 
				AND SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
				AND SDD.DELETEDDATE IS NULL		
		LEFT JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = BID.ITEMID
		INNER JOIN #BRANCH B ON B.Item = BI.TOBRANCHID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID		
	WHERE
		BI.DELETEDDATE IS NULL
		AND BID.DELETEDDATE IS NULL
		AND BI.CREATEDDATE >= @FromDate 
				AND BI.CREATEDDATE < @ToDate
	GROUP BY 
		BID.BRANCHINDENTID, SD.STOCKDISPATCHID, SDD.STOCKDISPATCHDETAILID, BID.ITEMID, BID.INDENTQUANTITY
		, BID.BRANCHSTOCK, BID.WHSTOCK, BI.FROMBRANCHID, BI.TOBRANCHID, BI.CREATEDDATE

	INSERT INTO #INDENTDATA(BRANCHINDENTID, STOCKDISPATCHID, STOCKDISPATCHDETAILID, ITEMID, INDENTQUANTITY, BRANCHSTOCK, WHSTOCK, DISPATCHQTY, CURBSTOCK, CURWHSTOCK
		, FROMBRANCHID, TOBRANCHID, CREATEDDATE)
	SELECT 
		BI.BRANCHINDENTID, SD.STOCKDISPATCHID, SDD.STOCKDISPATCHDETAILID, I.ITEMID, 0, 0, 0
		, SUM(ISNULL(CASE WHEN I.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END, 0)) DISPATCHQTY
		, 0, 0, SD.FROMBRANCHID, SD.TOBRANCHID, BI.CREATEDDATE
	FROM
		 BRANCHINDENT BI 
		 INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.BRANCHINDENTID = BI.BRANCHINDENTID AND SD.STATUS <> 0
		 INNER JOIN STOCKDISPATCHDETAIL SDD WITH(NOLOCK) ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		 INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		 INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		 INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		 INNER JOIN #BRANCH B ON B.Item = BI.TOBRANCHID
		 INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID		
	WHERE
		SDD.DELETEDDATE IS NULL	
		AND ISNULL(SDD.BRANCHINDENTDETAILID, 0) = 0 
		AND BI.DELETEDDATE IS NULL
		AND BI.CREATEDDATE >= @FromDate 
				AND BI.CREATEDDATE < @ToDate
	GROUP BY 
		BI.BRANCHINDENTID, SD.STOCKDISPATCHID, SDD.STOCKDISPATCHDETAILID, I.ITEMID, SD.FROMBRANCHID, SD.TOBRANCHID, BI.CREATEDDATE

	DELETE #INDENTDATA WHERE DISPATCHQTY = INDENTQUANTITY AND STOCKDISPATCHDETAILID IS NOT NULL

	UPDATE ID
	SET ID.CURWHSTOCK = WHS.CURWHSTOCK
	FROM
		#INDENTDATA ID
		LEFT JOIN 
			(
				SELECT 
					SSINNER.BRANCHID, I.ITEMID
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) CURWHSTOCK
				FROM 
					STOCKSUMMARY SSINNER WITH(NOLOCK) 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				GROUP BY SSINNER.BRANCHID, I.ITEMID
			) WHS ON WHS.BRANCHID = ID.FROMBRANCHID AND WHS.ITEMID = ID.ITEMID

	UPDATE ID
	SET ID.CURBSTOCK = BSTOCK.CURBSTOCK
	FROM
		#INDENTDATA ID		
		LEFT JOIN
			(
				SELECT 
					SSINNER.BRANCHID, I.ITEMID
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SSINNER.WEIGHTINKGS ELSE SSINNER.QUANTITY END) CURBSTOCK
				FROM 
					STOCKSUMMARY SSINNER WITH(NOLOCK) 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SSINNER.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				GROUP BY SSINNER.BRANCHID, I.ITEMID
			) BSTOCK ON BSTOCK.BRANCHID = ID.TOBRANCHID AND BSTOCK.ITEMID = ID.ITEMID

	SELECT 
		ID.CREATEDDATE, B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, BI.NOOFDAYS, SD.DISPATCHNUMBER, I.SKUCODE, I.ITEMNAME
		, ID.INDENTQUANTITY, ID.DISPATCHQTY, ID.DISPATCHQTY - ID.INDENTQUANTITY DIFF
		, ID.BRANCHSTOCK PREVBRANCHSTOCK, ID.WHSTOCK PREVWHSTOCK
		, ID.CURBSTOCK, ID.CURWHSTOCK
	FROM
		#INDENTDATA ID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = ID.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		INNER JOIN BRANCH B ON B.BRANCHID = ID.TOBRANCHID
		LEFT JOIN BRANCHINDENT BI ON BI.BRANCHINDENTID = ID.BRANCHINDENTID
		LEFT JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = ID.STOCKDISPATCHID
		LEFT JOIN TBLUSER CU ON CU.USERID = SD.CREATEDBY
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		*/
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEM_MARGIN]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_ITEM_MARGIN]
(
	@CategoryID VARCHAR(MAX)
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0
	, @ITEMID INT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
	, @IncludeMarginWOT BIT = 0
	, @IncludeDeleted BIT = 0
)
AS
BEGIN

	DECLARE @MonthDate DATE
	SELECT @MonthDate = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	
	SELECT 
		CATEGORYNAME, SUBCATEGORYNAME,BRANDNAME, MANUFACTURERNAME, SKUCODE, ITEMNAME, ITEMCODE, CLASSIFICATIONNAME, SUBCLASSIFICATIONNAME
		, IPGSTCODE, MRP, MRPWOT, SALEPRICE,/* OFFERNAME, ACTUALPRICEWT, ACTUALPRICEWOT, */ ACTUALPRICEWOT SALEPRICEWOT, IPCREATEDBY, IPCREATEDDATE, IPDELETEDBY, IPDELETEDDATE
		, AVGCOSTPRICEWOT, AVGCOSTPRICEWT --, ICPGSTCODE, ICPCREATEDBY, ICPCREATEDDATE, ICPDELETEDBY, ICPDELETEDDATE

		, CAST(MRPWOT - AVGCOSTPRICEWOT AS decimal(14, 4)) MRPMARGINWOT
		, CAST(((MRPWOT - AVGCOSTPRICEWOT) / MRPWOT) * 100 AS decimal(14, 2)) MRPMARGINWOTPER
		, CAST(MRP - AVGCOSTPRICEWT AS decimal(14, 4)) MRPMARGINWT
		, CAST(((MRP - AVGCOSTPRICEWT) / MRP) * 100 AS decimal(14, 2)) MRPMARGINWTPER

		, CAST(ACTUALPRICEWOT - AVGCOSTPRICEWOT AS decimal(14, 4)) ACTUALMARGINWOT
		, CAST(((ACTUALPRICEWOT - AVGCOSTPRICEWOT) / CASE WHEN ACTUALPRICEWOT = 0 THEN 1 ELSE ACTUALPRICEWOT END) * 100 AS decimal(14, 2)) ACTUALMARGINWOTPER
		, CAST(ACTUALPRICEWT - AVGCOSTPRICEWT AS decimal(14, 4)) ACTUALMARGINWT
		, CAST(((ACTUALPRICEWT - AVGCOSTPRICEWT) / CASE WHEN ACTUALPRICEWT = 0 THEN 1 ELSE ACTUALPRICEWT END) * 100 AS decimal(14, 2)) ACTUALMARGINWTPER
		, LASTCOSTPRICEWOT 'Last CP W/O Tax', LASTCOSTPRICETAX 'Last CP Tax', LASTCOSTPRICEWT 'Last CP with Tax'
		, MARGIN.QTYORWGHTINKGS, MARGIN.ITEMPRICEID
	FROM
		(
			SELECT 
				*, CAST(((ACTUALPRICEWT / (100 + MAR.GSTVAL)) * 100) AS DECIMAL(18, 2)) ACTUALPRICEWOT
			FROM
				(
					SELECT 
						CAT.CATEGORYNAME, 
						SUBCAT.SUBCATEGORYNAME, 
						I.SKUCODE, 
						I.ITEMNAME, 
						IC.ITEMCODE, 
						ICLS.CLASSIFICATIONNAME,
						ISUBCLS.SUBCLASSIFICATIONNAME,
						BR.BRANDNAME, 
						MAN.MANUFACTURERNAME,
						IP.MRP, 
						CAST(((IP.MRP / (100 + IPGST.CGST + IPGST.SGST + IPGST.CESS)) * 100) AS DECIMAL(18, 2)) MRPWOT,
						IP.SALEPRICE, 
						IPGST.GSTCODE IPGSTCODE, 
						IPC.FULLNAME IPCREATEDBY, 
						IP.CREATEDDATE IPCREATEDDATE, 
						IPD.FULLNAME IPDELETEDBY, 
						IP.DELETEDDATE IPDELETEDDATE, 
						AICP.COSTPRICEWOT AVGCOSTPRICEWOT, 
						AICP.COSTPRICEWT AVGCOSTPRICEWT, 
						AICP.COSTPRICEWT - AICP.COSTPRICEWOT AVGCOSTPRICETAX,
						IP.SALEPRICE ACTUALPRICEWT
						--, dbo.UDF_GET_LOWEST_ACTUALPRICE_DATA_PRICE(IP.ITEMPRICEID, IC.ITEMCODEID, I.CATEGORYID, IP.MRP, IP.SALEPRICE) AS ACTUALPRICEWT
						, IPGST.CGST + IPGST.SGST + IPGST.CESS AS GSTVAL
						--, CAST(((dbo.UDF_GET_LOWEST_ACTUALPRICE_DATA_PRICE(IP.ITEMPRICEID, IC.ITEMCODEID, I.CATEGORYID, IP.SALEPRICE) / (100 + IPGST.CGST + IPGST.SGST + IPGST.CESS)) * 100) AS DECIMAL(18, 2)) ACTUALPRICEWOT
						--, dbo.UDF_GET_LOWEST_ACTUALPRICE_DATA_OFFER(IP.ITEMPRICEID, IC.ITEMCODEID, I.CATEGORYID, IP.MRP, IP.SALEPRICE) OFFERNAME
						, ICP.COSTPRICEWOT LASTCOSTPRICEWOT
						, ICP.COSTPRICEWT - ICP.COSTPRICEWOT LASTCOSTPRICETAX
						, ICP.COSTPRICEWT LASTCOSTPRICEWT
						, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS QTYORWGHTINKGS
						, IP.ITEMPRICEID
					FROM
						ITEM I
						INNER JOIN ITEMCODE IC ON IC.ITEMID = I.ITEMID
						INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
						INNER JOIN GSTDETAIL IPGST ON IPGST.GSTID = IP.GSTID
						INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
						LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
						LEFT JOIN AVGCOSTPRICE AICP ON AICP.ITEMCODEID = IP.ITEMCODEID AND AICP.MRP = IP.MRP AND AICP.AVGCPDATE = @MonthDate						
						LEFT JOIN TBLUSER IPC ON IPC.USERID = IP.CREATEDBY
						LEFT JOIN TBLUSER IPD ON IPD.USERID = IP.DELETEDBY						
						LEFT JOIN ITEMCLASSIFICATION ICLS ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
						LEFT JOIN ITEMSUBCLASSIFICATION ISUBCLS ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
						LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
						LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
						LEFT JOIN 
							(
								SELECT ICPINNER.ITEMPRICEID, MAX(ICPINNER.ITEMCOSTPRICEID) MAXITEMCOSTPRICEID
								FROM ITEMCOSTPRICE ICPINNER 
								WHERE ICPINNER.DELETEDDATE IS NULL
								GROUP BY ICPINNER.ITEMPRICEID
							) ICPMAX ON ICPMAX.ITEMPRICEID = IP.ITEMPRICEID
						LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = ICPMAX.MAXITEMCOSTPRICEID
						LEFT JOIN TBLUSER ICPC ON ICPC.USERID = ICP.CREATEDBY
						LEFT JOIN TBLUSER ICPD ON ICPD.USERID = ICP.DELETEDBY
						LEFT JOIN 
							(
								SELECT SSINNER.ITEMPRICEID, SUM(SSINNER.QUANTITY) QUANTITY, SUM(SSINNER.WEIGHTINKGS) WEIGHTINKGS
								FROM 
									STOCKSUMMARY SSINNER WITH(NOLOCK)
									INNER JOIN BRANCH BINNER ON BINNER.BRANCHID = SSINNER.BRANCHID
								WHERE BINNER.DELETEDDATE IS NULL
								GROUP BY SSINNER.ITEMPRICEID
							) SS ON SS.ITEMPRICEID = IP.ITEMPRICEID
					WHERE 
					(I.ITEMID = @ITEMID OR @ITEMID = 0)
					AND (IP.DELETEDDATE IS NULL OR @IncludeDeleted = 1)
				) MAR
		) MARGIN
	ORDER BY CATEGORYNAME, SUBCATEGORYNAME, SKUCODE, IPCREATEDDATE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEM_MARGIN_SUPPLIER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_ITEM_MARGIN_SUPPLIER]
(
	@SupplierID INT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
		SELECT 
			SUPPLIERNAME, CATEGORYNAME, SUBCATEGORYNAME, CLASSIFICATIONNAME, SUBCLASSIFICATIONNAME, BRANDNAME, MANUFACTURERNAME, SKUCODE, ITEMNAME, ITEMCODE
			, IPGSTCODE, MRP, MRPWOT, SALEPRICE, OFFERNAME, ACTUALPRICEWT, ACTUALPRICEWOT, IPCREATEDBY, IPCREATEDDATE, IPDELETEDBY, IPDELETEDDATE
			, COSTPRICEWOT, COSTPRICEWT, ICPGSTCODE, ICPCREATEDBY, ICPCREATEDDATE, ICPDELETEDBY, ICPDELETEDDATE

			, CAST(MRPWOT - COSTPRICEWOT AS decimal(14, 4)) MRPMARGINWOT
			, CAST(((MRPWOT - COSTPRICEWOT) / MRPWOT) * 100 AS decimal(14, 2)) MRPMARGINWOTPER
			, CAST(MRP - COSTPRICEWT AS decimal(14, 4)) MRPMARGINWT
			, CAST(((MRP - COSTPRICEWT) / MRP) * 100 AS decimal(14, 2)) MRPMARGINWTPER

			, CAST(ACTUALPRICEWOT - COSTPRICEWOT AS decimal(14, 4)) ACTUALMARGINWOT
			, CAST(((ACTUALPRICEWOT - COSTPRICEWOT) / ACTUALPRICEWOT) * 100 AS decimal(14, 2)) ACTUALMARGINWOTPER
			, CAST(ACTUALPRICEWT - COSTPRICEWT AS decimal(14, 4)) ACTUALMARGINWT
			, CAST(((ACTUALPRICEWT - COSTPRICEWT) / ACTUALPRICEWT) * 100 AS decimal(14, 2)) ACTUALMARGINWTPER
		FROM
			(
				SELECT 
					*, CAST(((ACTUALPRICEWT / (100 + MAR.GSTVAL)) * 100) AS DECIMAL(18, 2)) ACTUALPRICEWOT
				FROM
					(
						SELECT
							DLR.DEALERNAME SUPPLIERNAME,
							CAT.CATEGORYNAME, 
							SUBCAT.SUBCATEGORYNAME, 
							I.SKUCODE, 
							I.ITEMNAME, 
							IC.ITEMCODE, 
							ICLS.CLASSIFICATIONNAME,
							ISUBCLS.SUBCLASSIFICATIONNAME,
							BR.BRANDNAME, 
							MAN.MANUFACTURERNAME,
							IP.MRP, 
							CAST(((IP.MRP / (100 + IPGST.CGST + IPGST.SGST + IPGST.CESS)) * 100) AS DECIMAL(18, 2)) MRPWOT,
							IP.SALEPRICE, 
							IPGST.GSTCODE IPGSTCODE, 
							IPC.FULLNAME IPCREATEDBY, 
							IP.CREATEDDATE IPCREATEDDATE, 
							IPD.FULLNAME IPDELETEDBY, 
							IP.DELETEDDATE IPDELETEDDATE, 
							ICP.COSTPRICEWOT, 
							ICP.COSTPRICEWT, 
							ICPGST.GSTCODE ICPGSTCODE, 
							ICPC.FULLNAME ICPCREATEDBY, 
							ICP.CREATEDDATE ICPCREATEDDATE, 
							ICPD.FULLNAME ICPDELETEDBY, 
							ICP.DELETEDDATE ICPDELETEDDATE, 
							dbo.UDF_GET_LOWEST_ACTUALPRICE_DATA_PRICE(IP.ITEMPRICEID, IC.ITEMCODEID, I.CATEGORYID, IP.MRP, IP.SALEPRICE) AS ACTUALPRICEWT, 
							IPGST.CGST + IPGST.SGST + IPGST.CESS AS GSTVAL, 
							dbo.UDF_GET_LOWEST_ACTUALPRICE_DATA_OFFER(IP.ITEMPRICEID, IC.ITEMCODEID, I.CATEGORYID, IP.MRP, IP.SALEPRICE) OFFERNAME
						FROM
							ITEM I
							INNER JOIN ITEMCODE IC ON IC.ITEMID = I.ITEMID
							INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
							INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMPRICEID = IP.ITEMPRICEID
							INNER JOIN ITEMCOSTPRICE ICP ON ISM.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
							INNER JOIN GSTDETAIL ICPGST ON ICPGST.GSTID = ICP.GSTID
							INNER JOIN TBLDEALER DLR ON DLR.DEALERID = ISM.SUPPLIERID
							INNER JOIN GSTDETAIL IPGST ON IPGST.GSTID = IP.GSTID
							INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
							LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
							LEFT JOIN TBLUSER IPC ON IPC.USERID = IP.CREATEDBY
							LEFT JOIN TBLUSER IPD ON IPD.USERID = IP.DELETEDBY
							LEFT JOIN TBLUSER ICPC ON ICPC.USERID = ICP.CREATEDBY
							LEFT JOIN TBLUSER ICPD ON ICPD.USERID = ICP.DELETEDBY
							LEFT JOIN ITEMCLASSIFICATION ICLS ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
							LEFT JOIN ITEMSUBCLASSIFICATION ISUBCLS ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
							LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
							LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
						WHERE (ISM.SUPPLIERID = @SupplierID OR @SupplierID = 0)
					) MAR
			) MARGIN
	ORDER BY CATEGORYNAME, SUBCATEGORYNAME, SKUCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEMLEDGER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_ITEMLEDGER]
(
	@ItemID INT
	, @BranchID INT
	, @FromDate DATE
	, @ToDate DATE
	, @IncludeBranch BIT = 0
	, @IncludeItem BIT = 0
)
AS
BEGIN

	DECLARE @LastCountingDate DATETIME, 
		@OpeningBalance DECIMAL(14, 2), 
		@IsOpenItem BIT, 
		@IsWarehouse bit = 0, 
		@FinYearStartDate DATE, 
		@ParentItemID int = 0,
		@WHId INT = 45,
		@DWId INT = 100
	SELECT @IsWarehouse = ISNULL(ISWAREHOUSE,0) FROM BRANCH WHERE BRANCHID = @BranchID

	SELECT @IsOpenItem = I.ISOPENITEM, @ParentItemID = ISNULL(I.PARENTITEMID,0) FROM ITEM I WHERE I.ITEMID = @ItemID
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	

	SELECT @LastCountingDate = MAX(CAI.CREATEDDATE)
	FROM
		COUNTINGAPPROVALITEM CAI
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CAI.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	WHERE CA.BRANCHID = @BranchID
		AND IC.ITEMID = @ItemID
		AND CAI.CREATEDDATE < @ToDate

	--Update sub category counting date if item is not counted
	DECLARE @SubCategoryID INT
	SELECT @SubCategoryID = SUBCATEGORYID FROM ITEM I WHERE I.ITEMID = @ItemID

	SELECT @LastCountingDate = CASE WHEN MAX(CAC.CREATEDDATE) > isnull(@LastCountingDate, '1900-01-01') THEN MAX(CAC.CREATEDDATE) ELSE @LastCountingDate END
	FROM COUNTINGAPPROVALCATEGORYMAP CAC
		INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
	WHERE CA.BRANCHID = @BranchID
		AND CAC.CREATEDDATE < @ToDate
		AND CAC.SUBCATEGORYID = @SubCategoryID

	if(@LastCountingDate is null)
	begin
		--Update category counting date if subcategory is not counted
		DECLARE @CategoryID INT
		SELECT @CategoryID = CATEGORYID FROM ITEM I WHERE I.ITEMID = @ItemID
		SELECT @LastCountingDate = CASE WHEN MAX(CAC.CREATEDDATE) > isnull(@LastCountingDate, '1900-01-01') THEN MAX(CAC.CREATEDDATE) ELSE @LastCountingDate END
		FROM COUNTINGAPPROVALCATEGORYMAP CAC
			INNER JOIN COUNTINGAPPROVAL CA ON CAC.COUNTINGAPPROVALID = CA.COUNTINGAPPROVALID
		WHERE CA.BRANCHID = @BranchID
			AND CAC.CREATEDDATE < @ToDate
			AND CAC.CATEGORYID = @CategoryID
	end
	
	SELECT @OpeningBalance = SUM(CASE WHEN @IsOpenItem = 1 THEN SCD.WEIGHTINKGS ELSE SCD.QUANTITY END)
	FROM
		STOCKCOUNTINGDETAIL SCD
		INNER JOIN STOCKCOUNTING SC ON SC.STOCKCOUNTINGID = SCD.STOCKCOUNTINGID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SCD.ITEMPRICEID		
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	WHERE
		SCD.DELETEDDATE IS NULL
		AND SC.BRANCHID = @BranchID
		AND IC.ITEMID = @ItemID
		AND (SC.STATUS = 2 OR SC.STATUS = 3)
		AND CAST(SC.STOCKACCEPTEDDATE AS DATE) >= CAST(@LastCountingDate AS DATE)

	SELECT @LastCountingDate = ISNULL(@LastCountingDate, '1900-01-01'), @OpeningBalance = ISNULL(@OpeningBalance, 0)
		, @FinYearStartDate = '2023-04-01' --DATEFROMPARTS(YEAR(GETDATE()) - CASE WHEN MONTH(GETDATE()) <= 3 THEN 1 ELSE 0 END, 4, 1) 

	
	-- IF COUNTING IS NOT DONE IN CUR FIN YEAR, THEN PICK OPENING BALANCE
	IF @LastCountingDate < @FinYearStartDate
	BEGIN
		
		SELECT 
			@OpeningBalance = SUM(CASE WHEN @IsOpenItem = 1 THEN SS.FYOPENINGWEIGHTINKGS ELSE SS.FYOPENINGQUANTITY END)
			, @LastCountingDate = @FinYearStartDate
		FROM
			STOCKSUMMARY SS 
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID		
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		WHERE			
			SS.BRANCHID = @BranchID
			AND IC.ITEMID = @ItemID			

	END
	
	CREATE TABLE #StockBalance(TRANSACTIONID INT IDENTITY(1, 1), TRANSACTIONDATE DATE, CREDIT DECIMAL(14, 2), DEBIT DECIMAL(14, 2)
		, TRANSACTIONTYPE VARCHAR(500), BRANCHID INT, SKUCODE VARCHAR(10), ITEMNAME NVARCHAR(100))

	INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
	SELECT @LastCountingDate, @OpeningBalance, 0, 'Opening Balance', CASE WHEN @IncludeBranch = 1 THEN @BranchID ELSE NULL END

		INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
		SELECT CAST(SE.UPDATEDATE AS DATE), CASE WHEN @IsOpenItem = 1 THEN SUM(SED.WEIGHTINKGS) ELSE SUM(SED.QUANTITY) END
			, 0, 'Stock Entry', CASE WHEN @IncludeBranch = 1 THEN @BranchID ELSE NULL END
		FROM
			STOCKENTRYDETAIL SED
			INNER JOIN STOCKENTRY SE ON SE.STOCKENTRYID = SED.STOCKENTRYID
			INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		WHERE
			SED.DELETEDDATE IS NULL
			AND SED.DELETEDDATE IS NULL
			AND IC.ITEMID = @ItemID
			AND SE.STATUS = 1
			AND SE.UPDATEDATE > @LastCountingDate
			AND SE.UPDATEDATE < @ToDate
			AND SE.RECEIVINGBRANCHID = @BranchID
		GROUP BY CAST(SE.UPDATEDATE AS DATE)
	
	IF @IsWarehouse = 0 
	BEGIN
		INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
		SELECT CAST(SD.CREATEDDATE AS DATE), CASE WHEN @IsOpenItem = 1 THEN SUM(SDD.WEIGHTINKGS) ELSE SUM(SDD.DISPATCHQUANTITY) END, 
		0, 
		CASE WHEN ISNULL(SD.REFID,0) > 0 THEN 'Auto Stock Dispatch-In' ELSE 'Manual Stock Dispatch-In' END, 
		CASE WHEN @IncludeBranch = 1 THEN SD.FROMBRANCHID ELSE NULL END
		FROM
			STOCKDISPATCHDETAIL SDD
			INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		WHERE
			SDD.DELETEDDATE IS NULL
			AND SD.DELETEDDATE IS NULL
			AND IC.ITEMID = @ItemID
			AND SD.STATUS = 2
			AND ISNULL(SDD.ISACCEPTED,0) = 1
			AND SD.CREATEDDATE > @LastCountingDate
			AND SD.CREATEDDATE < @ToDate
			AND SD.TOBRANCHID = @BranchID
		GROUP BY CAST(SD.CREATEDDATE AS DATE),CASE WHEN @IncludeBranch = 1 THEN SD.FROMBRANCHID ELSE NULL END,SD.REFID
	END

		
	INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
	SELECT CAST(SD.CREATEDDATE AS DATE), 0, CASE WHEN @IsOpenItem = 1 THEN SUM(SDD.WEIGHTINKGS) ELSE SUM(SDD.DISPATCHQUANTITY) END
		, 'Stock Dispatch-Out', CASE WHEN @IncludeBranch = 1 THEN SD.TOBRANCHID ELSE NULL END
	FROM
		STOCKDISPATCHDETAIL SDD
		INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	WHERE
		SDD.DELETEDDATE IS NULL
		AND SD.DELETEDDATE IS NULL
		AND IC.ITEMID = @ItemID
		AND SD.STATUS <> 0
		AND SD.CREATEDDATE > @LastCountingDate
		AND SD.CREATEDDATE < @ToDate
		AND SD.FROMBRANCHID = @BranchID
	GROUP BY CAST(SD.CREATEDDATE AS DATE), CASE WHEN @IncludeBranch = 1 THEN SD.TOBRANCHID ELSE NULL END
	
	IF @BranchID = @WHId
	BEGIN

		IF(@IsOpenItem  = 0)
		BEGIN

			INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
			SELECT CAST(BD.ACCEPTEDDATE AS DATE), SUM(BRD.QUANTITY), 0, 'Branch refund', 
				CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END
			FROM POS_BREFUNDDETAIL BRD
				INNER JOIN POS_BREFUND BD ON BRD.BRID = BD.BRID
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN REASONFORREFUND ROR ON BRD.REASONID = ROR.REASONID
			WHERE BRD.DELETEDDATE IS NULL
				AND BD.DELETEDDATE IS NULL
				AND I.ITEMID = @ItemID
				AND BD.IsAccepted = 1
				AND BD.ACCEPTEDDATE > @LastCountingDate
				AND BD.ACCEPTEDDATE < @ToDate
				AND ROR.LOCATIONTOMOVESTOCK = @WHId
			GROUP BY CAST(BD.ACCEPTEDDATE AS DATE), 
				CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END
		END
		ELSE
		BEGIN
			--Inserting branch refunds loose items weight in kgs of same item
			INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
			SELECT CAST(BD.ACCEPTEDDATE AS DATE), SUM(BRD.WEIGHTINKGS), 0, 'Branch refund', 
			CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END
			FROM POS_BREFUNDDETAIL BRD
				INNER JOIN POS_BREFUND BD ON BD.BRID = BRD.BRID
				INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
				INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID     
				INNER JOIN REASONFORREFUND ROR ON BRD.REASONID = ROR.REASONID
			WHERE I.ItemID = @ItemID 
				AND BRD.DELETEDDATE IS NULL
				AND BD.DELETEDDATE IS NULL
				AND BD.IsAccepted = 1
				AND BD.UPDATEDDATE > @LastCountingDate
				AND BD.UPDATEDDATE < @ToDate
				AND ROR.LOCATIONTOMOVESTOCK = @WHId
			GROUP BY CAST(BD.ACCEPTEDDATE AS DATE), 
				CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END
		END
	END
	ELSE IF (@BranchID = @DWId)
	BEGIN
		
		IF @ParentItemID = 0
		BEGIN
			INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
			SELECT CAST(BD.ACCEPTEDDATE AS DATE), 
			CASE WHEN I.ISOPENITEM = 0 THEN SUM(BRD.QUANTITY) ELSE SUM(BRD.WEIGHTINKGS) END
			, 0, 'Branch refund', 
				CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END
			FROM POS_BREFUNDDETAIL BRD
				INNER JOIN POS_BREFUND BD ON BRD.BRID = BD.BRID
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN REASONFORREFUND ROR ON BRD.REASONID = ROR.REASONID
			WHERE BRD.DELETEDDATE IS NULL
				AND BD.DELETEDDATE IS NULL
				AND I.ITEMID = @ItemID
				AND BD.IsAccepted = 1
				AND BD.ACCEPTEDDATE > @LastCountingDate
				AND BD.ACCEPTEDDATE < @ToDate
				AND ROR.LOCATIONTOMOVESTOCK = @DWId
			GROUP BY I.ISOPENITEM, CAST(BD.ACCEPTEDDATE AS DATE), CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END
		END
		ELSE IF (@IsOpenItem = 1)
		BEGIN
			INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
			SELECT  
				CAST(BD.ACCEPTEDDATE AS DATE) AS TRANSACTIONDATE,
				SUM(BRD.QUANTITY * U.MULTIPLIER) AS CREDIT,
				0 AS DEBIT,
				'Branch refund' AS TRANSACTIONTYPE,
				CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END AS BRANCHID
			FROM POS_BREFUNDDETAIL BRD
				INNER JOIN POS_BREFUND BD ON BRD.BRID = BD.BRID

				-- Resolve child item
				INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
				INNER JOIN ITEM CHILD ON IC.ITEMID = CHILD.ITEMID

				-- Parent must be the open item
				INNER JOIN ITEM PARENT ON CHILD.PARENTITEMID = PARENT.ITEMID
					AND PARENT.ITEMID = @ItemID
					AND ISNULL(PARENT.ISOPENITEM,0) = 1

				LEFT JOIN UOM U ON CHILD.UOMID = U.UOMID

				INNER JOIN REASONFORREFUND ROR ON BRD.REASONID = ROR.REASONID AND ROR.MERGETOPARENT = 1

			WHERE 
				BRD.DELETEDDATE IS NULL
				AND BD.DELETEDDATE IS NULL
				AND BD.IsAccepted = 1
				AND BD.ACCEPTEDDATE > @LastCountingDate
				AND BD.ACCEPTEDDATE < @ToDate
				AND ROR.LOCATIONTOMOVESTOCK = @DWId
        
			GROUP BY 
				CAST(BD.ACCEPTEDDATE AS DATE),
				CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END
				END

	END
	ELSE IF @IsWarehouse = 0 
	BEGIN
		INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
		SELECT CAST(BD.UPDATEDDATE AS DATE), 0, CASE WHEN @IsOpenItem = 1 THEN SUM(BRD.WEIGHTINKGS) ELSE SUM(BRD.QUANTITY) END
			, CASE WHEN ISNULL(BD.REFID,0) > 0 THEN 'Auto Branch Refund' ELSE 'Manual Branch Refund' END, 
			CASE WHEN @IncludeBranch = 1 THEN @BranchID ELSE NULL END
		FROM
			POS_BREFUNDDETAIL BRD
			INNER JOIN POS_BREFUND BD ON BD.BRID = BRD.BRID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = Ic.ITEMID
		WHERE
			BRD.DELETEDDATE IS NULL
			AND BD.DELETEDDATE IS NULL
			AND IC.ITEMID = @ItemID			
			AND BD.UPDATEDDATE > @LastCountingDate
			AND BD.UPDATEDDATE < @ToDate
			AND BD.BRANCHID = @BranchID
			AND BD.STATUS = 1
			AND BRD.REASONID <> 5
		GROUP BY CAST(BD.UPDATEDDATE AS DATE),BD.REFID
	END

	INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
	SELECT CAST(ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) AS DATE), 0, CASE WHEN @IsOpenItem = 1 THEN SUM(SRD.WEIGHTINKGS) ELSE SUM(SRD.QUANTITY) END
		, 'Supplier refund', CASE WHEN @IncludeBranch = 1 THEN SR.BRANCHID ELSE NULL END
	FROM
		SUPPLIERRETURNSDETAIL SRD
		INNER JOIN SUPPLIERRETURNS SR ON SR.SUPPLIERRETURNSID = SRD.SUPPLIERRETURNSID
		INNER JOIN ITEMCOSTPRICE ICP ON SRD.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	WHERE
		SRD.DELETEDDATE IS NULL
		AND SR.DELETEDDATE IS NULL
		AND IC.ITEMID = @ItemID
		AND SR.BRANCHID = @BranchID
		AND SR.STATUS = 1
		AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) > @LastCountingDate
		AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) < @ToDate
	GROUP BY CAST(ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) AS DATE), CASE WHEN @IncludeBranch = 1 THEN SR.BRANCHID ELSE NULL END
	
	INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
	SELECT 
		TRANSACTIONDATE, CASE WHEN CREDITORDEBIT > 0 THEN CREDITORDEBIT ELSE 0 END
		, CASE WHEN CREDITORDEBIT > 0 THEN 0 ELSE -CREDITORDEBIT END, TRANSACTIONTYPE, BRANCHID
	FROM	
		(	
			SELECT CAST(SA.CREATEDDATE AS DATE) TRANSACTIONDATE
				, CASE WHEN @IsOpenItem = 1 THEN SUM(SA.WEIGHTINKGS - SA.PREVWEIGHTINKGS ) ELSE SUM(SA.QUANTITY - SA.PREVQUANTITY) END CREDITORDEBIT
				, 'Stock adjustment - ' + SAT.STOCKADJUSTMENTTYPE +  CASE WHEN DESCRIPTION IS NOT NULL THEN ' - ' + DESCRIPTION ELSE '' END TRANSACTIONTYPE
				--, CASE WHEN SA.TTYPE = 1 THEN 'Processing Slippage - ' + SA.DESCRIPTION ELSE ISNULL(DESCRIPTION, 'Stock Adjustment') END TRANSACTIONTYPE
				, CASE WHEN @IncludeBranch = 1 THEN SA.BRANCHID ELSE NULL END BRANCHID
			FROM
				STOCKADJUSTMENT SA 
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SA.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN STOCKADJUSTMENTTYPE SAT ON SAT.STOCKADJUSTMENTTYPEID = SA.STOCKADJUSTMENTTYPEID
			WHERE
				IC.ITEMID = @ItemID
				AND SA.CREATEDDATE > @LastCountingDate
				AND SA.CREATEDDATE < @ToDate
				AND SA.BRANCHID = @BranchID
			GROUP BY CAST(SA.CREATEDDATE AS DATE), CASE WHEN @IncludeBranch = 1 THEN SA.BRANCHID ELSE NULL END, SA.TTYPE, SAT.STOCKADJUSTMENTTYPE, SA.DESCRIPTION
		) SADJ

	INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
	SELECT CAST(PB.CREATEDDATE AS DATE), 0, CASE WHEN @IsOpenItem = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END
		, 'Sale', CASE WHEN @IncludeBranch = 1 THEN @BranchID ELSE NULL END
	FROM
		POS_BILLDETAIL PBD
		INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
	WHERE
		BC.BRANCHID = @BranchID
		AND IC.ITEMID = @ItemID
		AND PBD.DELETEDDATE IS NULL
		AND PB.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1
		AND PBD.CREATEDDATE > @LastCountingDate
		AND PBD.CREATEDDATE < @ToDate
	GROUP BY CAST(PB.CREATEDDATE AS DATE)	

	INSERT INTO #StockBalance(TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, BRANCHID)
	SELECT CAST(CRF.CREATEDDATE AS DATE), CASE WHEN @IsOpenItem = 1 THEN SUM(CRF.REFUNDWEIGHTINKGS) ELSE SUM(CRF.REFUNDQUANTITY) END, 0
		, 'Customer refund', CASE WHEN @IncludeBranch = 1 THEN @BranchID ELSE NULL END
	FROM
		POS_CREFUND CRF  
		INNER JOIN POS_BILLDETAIL PBD ON PBD.BILLDETAILID = CRF.BILLDETAILID AND PBD.BRANCHCOUNTERID = CRF.COUNTERID
		INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
	WHERE
		BC.BRANCHID = @BranchID
		AND IC.ITEMID = @ItemID
		AND CRF.DELETEDDATE IS NULL
		AND PBD.DELETEDDATE IS NULL
		AND PB.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1
		AND CRF.CREATEDDATE > @LastCountingDate
		AND CRF.CREATEDDATE < @ToDate
	GROUP BY CAST(CRF.CREATEDDATE AS DATE)

	SELECT 
		TRANSACTIONID, TRANSACTIONDATE, CREDIT, DEBIT, TRANSACTIONTYPE, CASE WHEN @IncludeBranch = 1 THEN BRANCHNAME ELSE NULL END BRANCHNAME
		, SUM(CREDIT - DEBIT) OVER (ORDER BY TRANSACTIONDATE, TRANSACTIONID) RUNNINGBAL ,SKUCODE, ITEMNAME, '' AS ISMATCHED
	FROM 
		#StockBalance SB
		LEFT JOIN BRANCH B ON B.BRANCHID = SB.BRANCHID
	ORDER BY TRANSACTIONDATE, TRANSACTIONID
		
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEMPRICECHANGES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_RPT_ITEMPRICECHANGES]
@BRANCHID INT,
@FROMDATE DATETIME,
@TODATE DATETIME,
@AllItems BIT = 0,
@CatIDs VARCHAR(MAX),
@ClassIDs VARCHAR(MAX)
AS
BEGIN

	SELECT * INTO #CATS FROM dbo.SplitString(@CatIDs,',')
	SELECT * INTO #CLASS FROM dbo.SplitString(@ClassIDs,',')

	IF(@AllItems = 0)
	BEGIN
		SELECT
			I.SKUCODE, IC.ITEMCODE, I.ITEMNAME, 
			CAT.CATEGORYNAME, SCAT.SUBCATEGORYNAME, ICL.CLASSIFICATIONNAME, ISCL.SUBCLASSIFICATIONNAME,
			IPOLD.MRP AS OLDMRP, IPOLD.SALEPRICE OLDSALEPRICE, IPNEW.MRP, IPNEW.SALEPRICE,
			CAST(ISNULL(SM.GOLIVEDATE, SM.CREATEDDATE) AS DATE) AS LIVEDATE, 
			CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS BRANCHSTOCK
		FROM STOCKMOVE SM
			INNER JOIN ITEMPRICE IPOLD ON SM.OLDITEMPRICEID = IPOLD.ITEMPRICEID			
			INNER JOIN ITEMPRICE IPNEW ON SM.NEWITEMPRICEID = IPNEW.ITEMPRICEID
			INNER JOIN STOCKSUMMARY SS ON IPNEW.ITEMPRICEID = SS.ITEMPRICEID AND SS.BRANCHID = @BRANCHID
			INNER JOIN ITEMCODE IC ON IPOLD.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
			INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
			LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
			INNER JOIN ITEMCLASSIFICATION ICL ON I.CLASSIFICATIONID = ICL.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION ISCL ON I.SUBCLASSIFICATIONID = ISCL.SUBCLASSIFICATIONID
			INNER JOIN #CATS CATS ON CAT.CATEGORYID = CATS.Item
			INNER JOIN #CLASS CLS ON ICL.CLASSIFICATIONID = CLS.Item
		WHERE 
			(SS.QUANTITY <> 0 OR SS.WEIGHTINKGS <> 0)
			AND CAST(ISNULL(SM.GOLIVEDATE, SM.CREATEDDATE) AS DATE) >= CAST(@FROMDATE AS DATE) 
			AND CAST(ISNULL(SM.GOLIVEDATE, SM.CREATEDDATE) AS DATE) <= CAST(@TODATE AS DATE)
	END
	ELSE
	BEGIN
		SELECT
			I.SKUCODE, IC.ITEMCODE, I.ITEMNAME, IP.MRP, IP.SALEPRICE, 
			CAT.CATEGORYNAME, SCAT.SUBCATEGORYNAME, ICL.CLASSIFICATIONNAME, ISCL.SUBCLASSIFICATIONNAME,
			CASE WHEN I.ISOPENITEM = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS BRANCHSTOCK
		FROM ITEM I 
			INNER JOIN ITEMCODE IC ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEMPRICE IP ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN STOCKSUMMARY SS ON IP.ITEMPRICEID = SS.ITEMPRICEID AND SS.BRANCHID = @BRANCHID
			INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
			LEFT JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
			INNER JOIN ITEMCLASSIFICATION ICL ON I.CLASSIFICATIONID = ICL.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION ISCL ON I.SUBCLASSIFICATIONID = ISCL.SUBCLASSIFICATIONID
			INNER JOIN #CATS CATS ON CAT.CATEGORYID = CATS.Item
			INNER JOIN #CLASS CLS ON ICL.CLASSIFICATIONID = CLS.Item
		WHERE I.DELETEDDATE IS NULL 
			AND IC.DELETEDDATE IS NULL 
			AND IP.DELETEDDATE IS NULL 
			AND (SS.QUANTITY <> 0 OR SS.WEIGHTINKGS <> 0)
	END

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEMSUMMARY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
