CREATE PROC [dbo].[USP_RPT_ITEMSUMMARY]
(
	@BranchID VARCHAR(500)
	, @FromDate DATE = NULL
	, @ToDate DATE = NULL
	, @ItemID INT 
	, @IncludeBillNumber BIT = 0
)
AS
BEGIN
	IF @ToDate IS NOT NULL
	BEGIN
		SET @ToDate =  DATEADD(D, 1, @ToDate)
	END

	DECLARE @IsOpenItem BIT, @ParentItemID INT
	SELECT	@IsOpenItem = ISOPENITEM, @ParentItemID = ITEMID FROM ITEM WHERE ITEMID = @ItemID

	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')
	
	CREATE TABLE #ItemSummary
	(
		BRANCHID INT
		, BRANCHNAME VARCHAR(100)
		, BRANCHCODE VARCHAR(20)
		, BRANCHSTOCK DECIMAL(11, 2)
		, DISPATCHQUANTITY DECIMAL(11, 2)
		, SALEQUANTITY DECIMAL(11, 2)
		, BREFUNDQUANTITY DECIMAL(11, 2)
		, CREFUNDQUANTITY DECIMAL(11, 2)
	)

	IF @IsOpenItem = 1 
	BEGIN
		
		INSERT INTO #ItemSummary(BRANCHID, BRANCHCODE, BRANCHNAME)
		SELECT BRANCHID, BRANCHCODE, BRANCHNAME FROM BRANCH B
			INNER JOIN #BRANCH BINNER ON B.BRANCHID = BINNER.ITEM
		WHERE DELETEDDATE IS NULL
		
		UPDATE ISUM SET ISUM.BRANCHSTOCK = SS.WEIGHTINKGS
		FROM #ItemSummary ISUM
			INNER JOIN
			(
				SELECT SSOUTER.BRANCHID, SUM(SSOUTER.WEIGHTINKGS) AS WEIGHTINKGS FROM 
				(
					SELECT 
						SSINNER.BRANCHID
						, CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN SUM(SSINNER.WEIGHTINKGS)
							ELSE SUM(SSINNER.QUANTITY * U.MULTIPLIER) END AS WEIGHTINKGS
					FROM STOCKSUMMARY SSINNER WITH(NOLOCK) 
						INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
						INNER JOIN ITEMCODE IC   ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
						INNER JOIN UOM U ON I.UOMID = U.UOMID
						INNER JOIN #BRANCH BINNER ON SSINNER.BRANCHID = BINNER.ITEM
					WHERE CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN I.ITEMID ELSE I.PARENTITEMID END = @ItemID
					GROUP BY SSINNER.BRANCHID, I.ISOPENITEM
				) AS SSOUTER GROUP BY SSOUTER.BRANCHID
			) SS ON ISUM.BRANCHID = SS.BRANCHID

		UPDATE ISUM SET ISUM.DISPATCHQUANTITY = SD.DISPATCHQUANTITY
		FROM #ItemSummary ISUM
			INNER JOIN
			(	
				SELECT SDOUTER.BRANCHID, SUM(SDOUTER.DISPATCHQUANTITY) DISPATCHQUANTITY FROM 
				(
					SELECT 
						SD.TOBRANCHID AS BRANCHID
						, CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN SUM(SED.WEIGHTINKGS) 
							ELSE SUM(SED.DISPATCHQUANTITY * U.MULTIPLIER) END AS DISPATCHQUANTITY
					FROM
						STOCKDISPATCHDETAIL SED WITH(NOLOCK) 
						INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SED.STOCKDISPATCHID
						INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SED.ITEMPRICEID
						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
						INNER JOIN UOM U ON I.UOMID = U.UOMID
						INNER JOIN #BRANCH BINNER ON SD.TOBRANCHID = BINNER.ITEM
					WHERE 
						CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN I.ITEMID ELSE I.PARENTITEMID END = @ItemID
						AND SD.CREATEDDATE > @FromDate
						AND SD.CREATEDDATE < @ToDate
						AND SED.DELETEDDATE IS NULL AND SD.DELETEDDATE IS NULL
					GROUP BY SD.TOBRANCHID,I.ISOPENITEM
				) SDOUTER GROUP BY SDOUTER.BRANCHID
			) SD ON ISUM.BRANCHID = SD.BRANCHID

		UPDATE ISUM SET ISUM.SALEQUANTITY = ITEMSALE.SALEQUANTITY
		FROM #ItemSummary ISUM
			INNER JOIN
				(
					SELECT BSOUTER.BRANCHID, SUM(BSOUTER.SALEQUANTITY) AS SALEQUANTITY FROM 
					(
						SELECT BC.BRANCHID
								, CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN SUM(PBD.WEIGHTINKGS) 
									ELSE SUM(PBD.QUANTITY * U.MULTIPLIER) END AS SALEQUANTITY
						FROM
							POS_BILLDETAIL PBD WITH(NOLOCK)
							INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
							INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
							INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
							INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
							INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
							INNER JOIN UOM U ON U.UOMID = I.UOMID
							INNER JOIN #BRANCH BINNER ON BC.BRANCHID = BINNER.ITEM
						WHERE CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN I.ITEMID ELSE I.PARENTITEMID END = @ItemID
							AND PB.CREATEDDATE > @FromDate
							AND PB.CREATEDDATE < @ToDate
							AND PBD.DELETEDDATE IS NULL AND PB.DELETEDDATE IS NULL
							AND PB.DAYCLOSUREID IS NOT NULL
						GROUP BY BC.BRANCHID,I.ISOPENITEM	
					) BSOUTER GROUP BY BSOUTER.BRANCHID
				) ITEMSALE ON ITEMSALE.BRANCHID = ISUM.BRANCHID

		UPDATE ISUM SET ISUM.BREFUNDQUANTITY = BREFUND.BREFUNDQUANTITY
		FROM
			#ItemSummary ISUM
			LEFT JOIN 
				(
					SELECT BROUTER.BRANCHID, SUM(BROUTER.BREFUNDQUANTITY) AS BREFUNDQUANTITY FROM 
					(
						SELECT PBR.BRANCHID
						, CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN SUM(PBRD.WEIGHTINKGS)
								ELSE SUM(PBRD.QUANTITY * U.MULTIPLIER) END AS BREFUNDQUANTITY
						FROM
							POS_BREFUNDDETAIL PBRD WITH(NOLOCK) 
							INNER JOIN POS_BREFUND PBR WITH(NOLOCK) ON PBR.BRID = PBRD.BRID
							INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBRD.ITEMPRICEID
							INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
							INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
							INNER JOIN UOM U ON U.UOMID = I.UOMID 
							INNER JOIN #BRANCH BINNER ON PBR.BRANCHID = BINNER.ITEM
						WHERE CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN I.ITEMID ELSE I.PARENTITEMID END = @ItemID
							AND PBR.CREATEDATE > @FromDate
							AND PBR.CREATEDATE < @ToDate
							AND PBRD.DELETEDDATE IS NULL 
							AND PBR.DELETEDDATE IS NULL
							AND PBR.IsAccepted = 1
						GROUP BY PBR.BRANCHID,I.ISOPENITEM
					) BROUTER GROUP BY BROUTER.BRANCHID
				) BREFUND ON BREFUND.BRANCHID = ISUM.BRANCHID

		UPDATE ISUM SET ISUM.CREFUNDQUANTITY = CREFUND.CREFUNDQUANTITY
		FROM
			#ItemSummary ISUM
			LEFT JOIN
				(
					SELECT CROUTER.BRANCHID, SUM(CROUTER.CREFUNDQUANTITY) AS CREFUNDQUANTITY FROM 
					(
						SELECT BC.BRANCHID
							, CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN SUM(PCR.REFUNDWEIGHTINKGS)
								ELSE SUM(PCR.REFUNDQUANTITY * U.MULTIPLIER) END AS CREFUNDQUANTITY
						FROM
							POS_CREFUND PCR WITH(NOLOCK)
							INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = PCR.BILLDETAILID AND PBD.BRANCHCOUNTERID = PCR.COUNTERID
							INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
							INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PCR.COUNTERID
							INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
							INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
							INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
							INNER JOIN UOM U ON U.UOMID = I.UOMID 
							INNER JOIN #BRANCH BINNER ON BC.BRANCHID = BINNER.ITEM
						WHERE CASE WHEN ISNULL(I.ISOPENITEM,0) = 1 THEN I.ITEMID ELSE I.PARENTITEMID END = @ItemID
							AND PCR.CREATEDDATE > @FromDate
							AND PCR.CREATEDDATE < @ToDate
							AND PCR.DELETEDDATE IS NULL
							AND I.PARENTITEMID = @ParentItemID
						GROUP BY BC.BRANCHID,I.ISOPENITEM
					) CROUTER GROUP BY CROUTER.BRANCHID
				) CREFUND ON CREFUND.BRANCHID = ISUM.BRANCHID

		SELECT BRANCHID, BRANCHNAME, BRANCHCODE, BRANCHSTOCK, ISNULL(DISPATCHQUANTITY, 0) DISPATCHQUANTITY, ISNULL(SALEQUANTITY, 0) SALEQUANTITY
			, ISNULL(BREFUNDQUANTITY, 0) BREFUNDQUANTITY, ISNULL(CREFUNDQUANTITY, 0) CREFUNDQUANTITY FROM #ItemSummary ORDER BY BRANCHCODE

		SELECT 
			SED.STOCKENTRYDETAILID, SED.STOCKENTRYID, DLR.DEALERNAME, SE.SUPPLIERINVOICENO, SE.CREATEDDATE
			, IP.MRP, IP.SALEPRICE, ICP.COSTPRICEWOT, ICP.COSTPRICEWT, SED.QUANTITY, SED.WEIGHTINKGS
		FROM
			STOCKENTRYDETAIL SED WITH(NOLOCK) 
			INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
			INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN TBLDEALER DLR WITH(NOLOCK) ON DLR.DEALERID = SE.SUPPLIERID
		WHERE
			IC.ITEMID = @ItemID
			AND (@FromDate IS NULL OR SE.CREATEDDATE > @FromDate)
			AND (@ToDate IS NULL OR SE.CREATEDDATE < @ToDate)
			AND SED.DELETEDDATE IS NULL AND SE.DELETEDDATE IS NULL
	END
	ELSE 
	BEGIN

		INSERT INTO #ItemSummary(BRANCHID, BRANCHCODE, BRANCHNAME)
		SELECT BRANCHID, BRANCHCODE, BRANCHNAME FROM BRANCH B
			INNER JOIN #BRANCH BINNER ON B.BRANCHID = BINNER.ITEM
		WHERE DELETEDDATE IS NULL

		UPDATE ISUM SET ISUM.BRANCHSTOCK = SS.QUANTITY
		FROM #ItemSummary ISUM
			INNER JOIN 
			(
				SELECT 
					SSINNER.BRANCHID, 
					SUM(SSINNER.QUANTITY) AS QUANTITY 
				FROM STOCKSUMMARY SSINNER WITH(NOLOCK) 
					INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
					INNER JOIN #BRANCH BINNER ON SSINNER.BRANCHID = BINNER.ITEM
				WHERE IC.ITEMID = @ITEMID GROUP BY SSINNER.BRANCHID
			) SS ON SS.BRANCHID = ISUM.BRANCHID

		SELECT SD.TOBRANCHID AS BRANCHID, SED.DISPATCHQUANTITY
		INTO #DispatchStock
		FROM
			STOCKDISPATCHDETAIL SED WITH(NOLOCK) 
			INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SED.STOCKDISPATCHID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SED.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN #BRANCH BINNER ON SD.TOBRANCHID = BINNER.ITEM
		WHERE
			IC.ITEMID = @ItemID
			AND SD.CREATEDDATE > @FromDate
			AND SD.CREATEDDATE < @ToDate
			AND SED.DELETEDDATE IS NULL AND SD.DELETEDDATE IS NULL


		UPDATE ISUM SET ISUM.DISPATCHQUANTITY = SD.DISPATCHQUANTITY
		FROM #ItemSummary ISUM
		INNER JOIN 
		(
			SELECT BRANCHID, SUM(DISPATCHQUANTITY) AS DISPATCHQUANTITY FROM #DispatchStock GROUP BY BRANCHID
		) SD ON ISUM.BRANCHID = SD.BRANCHID

		SELECT BC.BRANCHID, PBD.QUANTITY AS SALEQUANTITY
		INTO #SaleStock
		FROM POS_BILLDETAIL PBD WITH(NOLOCK)
			INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN #BRANCH BINNER ON BC.BRANCHID = BINNER.ITEM
		WHERE
			IC.ITEMID = @ItemID
			AND PB.CREATEDDATE > @FromDate
			AND PB.CREATEDDATE < @ToDate
			AND PBD.DELETEDDATE IS NULL AND PB.DELETEDDATE IS NULL
			AND PB.BILLSTATUS = 1
			AND PB.DAYCLOSUREID IS NOT NULL


		UPDATE ISUM SET ISUM.SALEQUANTITY = BS.SALEQUANTITY
		FROM #ItemSummary ISUM
		INNER JOIN 
		(
			SELECT BRANCHID, SUM(SALEQUANTITY) AS SALEQUANTITY FROM #SaleStock GROUP BY BRANCHID
		) BS ON ISUM.BRANCHID = BS.BRANCHID

		SELECT PBR.BRANCHID, PBRD.ACCEPTEDQUANTITY AS BREFUNDQUANTITY
		INTO #BRStock
		FROM POS_BREFUNDDETAIL PBRD WITH(NOLOCK) 
			INNER JOIN POS_BREFUND PBR WITH(NOLOCK) ON PBR.BRID = PBRD.BRID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBRD.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN #BRANCH BINNER ON PBR.BRANCHID = BINNER.ITEM
		WHERE
			IC.ITEMID = @ItemID
			AND PBR.IsAccepted = 1
			AND PBR.CREATEDATE > @FromDate
			AND PBR.CREATEDATE < @ToDate
			AND PBRD.DELETEDDATE IS NULL AND PBR.DELETEDDATE IS NULL	

		UPDATE ISUM SET ISUM.BREFUNDQUANTITY = BR.BREFUNDQUANTITY
		FROM #ItemSummary ISUM
		INNER JOIN 
		(
			SELECT BRANCHID, SUM(BREFUNDQUANTITY) AS BREFUNDQUANTITY FROM #BRStock  GROUP BY BRANCHID
		) BR ON ISUM.BRANCHID = BR.BRANCHID


		SELECT BC.BRANCHID, PCR.REFUNDQUANTITY AS CREFUNDQUANTITY
		INTO #CRStock 
		FROM POS_CREFUND PCR WITH(NOLOCK) 
			INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = PCR.BILLDETAILID AND PBD.BRANCHCOUNTERID = PCR.COUNTERID
			INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PCR.COUNTERID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN #BRANCH BINNER ON BC.BRANCHID = BINNER.ITEM
		WHERE
			IC.ITEMID = @ItemID
			AND PCR.CREATEDDATE > @FromDate
			AND PCR.CREATEDDATE < @ToDate
			AND PCR.DELETEDDATE IS NULL 
			AND PBD.DELETEDDATE IS NULL 
			AND PB.DELETEDDATE IS NULL

		UPDATE ISUM SET ISUM.CREFUNDQUANTITY = CR.CREFUNDQUANTITY
		FROM #ItemSummary ISUM
		INNER JOIN 
		(
			SELECT BRANCHID, SUM(CREFUNDQUANTITY) AS CREFUNDQUANTITY FROM #CRStock GROUP BY BRANCHID
		) CR ON ISUM.BRANCHID = CR.BRANCHID

		SELECT BRANCHID, BRANCHNAME, BRANCHCODE, BRANCHSTOCK, ISNULL(DISPATCHQUANTITY, 0) DISPATCHQUANTITY, ISNULL(SALEQUANTITY, 0) SALEQUANTITY
					, ISNULL(BREFUNDQUANTITY, 0) BREFUNDQUANTITY, ISNULL(CREFUNDQUANTITY, 0) CREFUNDQUANTITY FROM #ItemSummary ORDER BY BRANCHCODE

		SELECT
			SED.STOCKENTRYDETAILID, SED.STOCKENTRYID, DLR.DEALERNAME, SE.SUPPLIERINVOICENO, SE.CREATEDDATE
			, IP.MRP, IP.SALEPRICE, ICP.COSTPRICEWOT, ICP.COSTPRICEWT, SED.QUANTITY, SED.WEIGHTINKGS
		FROM
			STOCKENTRYDETAIL SED WITH(NOLOCK) 
			INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
			INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN TBLDEALER DLR WITH(NOLOCK) ON DLR.DEALERID = SE.SUPPLIERID
		WHERE
			IC.ITEMID = @ItemID
			AND SE.CREATEDDATE > @FromDate
			AND SE.CREATEDDATE < @ToDate
			AND SED.DELETEDDATE IS NULL 
			AND SE.DELETEDDATE IS NULL

		DROP TABLE #BRStock
		DROP TABLE #CRStock
		DROP TABLE #DispatchStock
		DROP TABLE #ItemSummary
		DROP TABLE #SaleStock
	END
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEMSUMMARYDETAILS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_ITEMSUMMARYDETAILS]
(
	@BranchID INT = 0
	, @FromDate DATE = NULL
	, @ToDate DATE = NULL
	, @ItemID INT 
	, @IncludeBillNumber BIT = 0
)
AS
BEGIN
	IF @ToDate IS NOT NULL
	BEGIN
		SET @ToDate =  DATEADD(D, 1, @ToDate)
	END

	DECLARE @IsOpenItem BIT, @ParentItemID INT
	SELECT	@IsOpenItem = ISOPENITEM, @ParentItemID = ITEMID FROM ITEM WHERE ITEMID = @ItemID

	SELECT 
		SD.DISPATCHNUMBER, SD.CREATEDDATE, IP.MRP, IP.SALEPRICE, SED.DISPATCHQUANTITY, SED.WEIGHTINKGS
	FROM
		STOCKDISPATCHDETAIL SED WITH(NOLOCK) 
		INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SED.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SED.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	WHERE IC.ITEMID = @ItemID
		AND SD.TOBRANCHID = @BranchID
		AND (@FromDate IS NULL OR SD.CREATEDDATE > @FromDate)
		AND (@ToDate IS NULL OR SD.CREATEDDATE < @ToDate)
		AND SED.DELETEDDATE IS NULL AND SD.DELETEDDATE IS NULL
	ORDER BY SD.CREATEDDATE

	IF @BranchID = 45
	BEGIN
		SELECT PBR.BREFUNDNUMBER, PBR.CREATEDATE, IP.MRP
		, IP.SALEPRICE, PBRD.QUANTITY, PBRD.WEIGHTINKGS, PBRD.ACCEPTEDQUANTITY, PBRD.ACCEPTEDWEIGHTKGS
		FROM
			POS_BREFUNDDETAIL PBRD WITH(NOLOCK) 
			INNER JOIN POS_BREFUND PBR WITH(NOLOCK) ON PBR.BRID = PBRD.BRID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBRD.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		WHERE
			IC.ITEMID = @ItemID
			AND PBR.IsAccepted = 1
			AND (@FromDate IS NULL OR PBR.CREATEDATE > @FromDate)
			AND (@ToDate IS NULL OR PBR.CREATEDATE < @ToDate)
			AND PBRD.DELETEDDATE IS NULL AND PBR.DELETEDDATE IS NULL
			AND (PBRD.REASONID = 3 OR PBRD.REASONID = 4)
		ORDER BY PBR.CREATEDATE
	END
	ELSE
	BEGIN
		SELECT PBR.BREFUNDNUMBER, PBR.CREATEDATE, IP.MRP
		, IP.SALEPRICE, PBRD.QUANTITY, PBRD.WEIGHTINKGS, PBRD.ACCEPTEDQUANTITY, PBRD.ACCEPTEDWEIGHTKGS
		FROM
			POS_BREFUNDDETAIL PBRD WITH(NOLOCK) 
			INNER JOIN POS_BREFUND PBR WITH(NOLOCK) ON PBR.BRID = PBRD. BRID 
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBRD.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		WHERE
			IC.ITEMID = @ItemID
			AND PBR.BRANCHID = @BranchID
			AND PBR.IsAccepted = 1
			AND (@FromDate IS NULL OR PBR.CREATEDATE > @FromDate)
			AND (@ToDate IS NULL OR PBR.CREATEDATE < @ToDate)
			AND PBRD.DELETEDDATE IS NULL AND PBR.DELETEDDATE IS NULL
		ORDER BY PBR.CREATEDATE
	END

	SELECT 
			CAST(PB.CREATEDDATE AS DATE) AS BILLDATE, CASE WHEN @IncludeBillNumber = 1 THEN PB.BILLNUMBER ELSE NULL END BILLNUMBER
		, IP.MRP, IP.SALEPRICE, SUM(PBD.QUANTITY) AS QUANTITY, SUM(PBD.WEIGHTINKGS) AS WEIGHTINKGS		
	FROM
		POS_BILLDETAIL PBD WITH(NOLOCK)
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	WHERE
		IC.ITEMID = @ItemID
		AND BC.BRANCHID = @BranchID
		AND (@FromDate IS NULL OR PB.CREATEDDATE > @FromDate)
		AND (@ToDate IS NULL OR PB.CREATEDDATE < @ToDate)
		AND PBD.DELETEDDATE IS NULL AND PB.DELETEDDATE IS NULL
		AND PB.DAYCLOSUREID IS NOT NULL
		GROUP BY BC.BRANCHID, CAST(PB.CREATEDDATE AS DATE), IP.MRP, IP.SALEPRICE, CASE WHEN @IncludeBillNumber = 1 THEN PB.BILLNUMBER ELSE NULL END

	SELECT PCR.CREATEDDATE AS REFUNDDATE, PB.BILLNUMBER, IP.MRP, IP.SALEPRICE, PCR.REFUNDQUANTITY, PCR.REFUNDWEIGHTINKGS
	FROM
		POS_CREFUND PCR WITH(NOLOCK) 
		INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = PCR.BILLDETAILID AND PBD.BRANCHCOUNTERID = PCR.COUNTERID
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PCR.COUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	WHERE
		IC.ITEMID = @ItemID
		AND BC.BRANCHID = @BranchID
		AND (@FromDate IS NULL OR PCR.CREATEDDATE > @FromDate)
		AND (@ToDate IS NULL OR PCR.CREATEDDATE < @ToDate)
		AND PCR.DELETEDDATE IS NULL
		AND PCR.DAYCLOSUREID IS NOT NULL
	ORDER BY PCR.CREATEDDATE
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEMWISEBRANCHREFUND]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_ITEMWISEBRANCHREFUND]
(
	@BranchID VARCHAR(500)
	, @FromDate DATE
	, @ToDate DATE
)
AS
BEGIN

	SELECT I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,IP.MRP,IP.SALEPRICE,BRD.QUANTITY,BRD.WEIGHTINKGS,BRD.REASONID,BRD.REASONNAME
	FROM
	(SELECT BRD.ITEMPRICEID,RFR.REASONID,RFR.REASONNAME,SUM(ISNULL(BRD.ACCEPTEDQUANTITY,0)) AS QUANTITY,SUM(ISNULL(BRD.ACCEPTEDWEIGHTKGS,0)) AS WEIGHTINKGS
		FROM POS_BREFUNDDETAIL BRD 
			INNER JOIN POS_BREFUND BR ON BRD.BRID = BR.BRID
			INNER JOIN dbo.SplitString(@BranchID,',') B ON BR.BRANCHID = B.ITEM
			LEFT JOIN REASONFORREFUND RFR ON BRD.REASONID = RFR.REASONID
		WHERE BR.CREATEDATE >= @FromDate
			AND BR.CREATEDATE <= @ToDate
		GROUP BY ITEMPRICEID,RFR.REASONID,RFR.REASONNAME
			) BRD
			INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
			INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ITEMWISESALE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_ITEMWISESALE]      
(      
 @BranchID VARCHAR(500),
 @FromDate Date,
 @ToDate Date,
 @IncludeBillDate BIT = 0,
 @IncludeBillNo Bit = 0,
 @IncludeBranch Bit = 0
)      
AS      
BEGIN      

	SELECT 
	BD.BILLDATE,BD.BILLNUMBER,B.BRANCHNAME,I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME,
	IP.MRP,IP.SALEPRICE,BD.QUANTITY,BD.WEIGHTINKGS,BD.BILLEDAMOUNT
	FROM 
	(
		SELECT 
		BD.ITEMPRICEID, 
		CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END AS BRANCHID,
		CASE WHEN @IncludeBillNo = 1 THEN B.BILLNUMBER ELSE NULL END AS BILLNUMBER,
		CASE WHEN @IncludeBillDate = 1 THEN CAST(B.CREATEDDATE AS DATE) ELSE NULL END AS BILLDATE,
		SUM(BD.QUANTITY) AS QUANTITY, 
		SUM(BD.WEIGHTINKGS) AS WEIGHTINKGS,
		SUM(BD.BILLEDAMOUNT) AS BILLEDAMOUNT

		FROM POS_BILLDETAIL BD 
			INNER JOIN POS_BILL B ON BD.BILLID = B.BILLID AND BD.BRANCHCOUNTERID = B.BRANCHCOUNTERID
			INNER JOIN BRANCHCOUNTER BC ON B.BRANCHCOUNTERID = BC.COUNTERID
			INNER JOIN dbo.SplitString(@BranchID,',') BINNER ON BC.BRANCHID = BINNER.ITEM
		WHERE B.CREATEDDATE BETWEEN @FromDate AND DATEADD(day,1, @ToDate)
			AND BD.DELETEDDATE IS NULL AND B.DELETEDDATE IS NULL
			AND ISNULL(B.BILLSTATUS,0) = 1
		GROUP BY BD.ITEMPRICEID,
			CASE WHEN @IncludeBillNo = 1 THEN B.BILLNUMBER ELSE NULL END,
			CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END,
			CASE WHEN @IncludeBillDate = 1 THEN CAST(B.CREATEDDATE AS DATE) ELSE NULL END
	
	)  BD
		INNER JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE	IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
		INNER JOIN TBLCATEGORY C ON I.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON I.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON BD.BRANCHID = B.BRANCHID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME
      
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_LEFTOVERPRICES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_LEFTOVERPRICES]
(
	@CategoryID VARCHAR(500)
)
AS
BEGIN

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')

	SELECT 
		CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE, IP.CREATEDDATE
		, IP.ITEMPRICEID, CLS.CLASSIFICATIONNAME, SUBCLS.SUBCLASSIFICATIONNAME
	FROM 
		ITEMPRICE IP	
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
	WHERE IP.DELETEDDATE IS NULL 
		AND IP.BRANCHID IS NULL
		AND NOT EXISTS 
			(
				SELECT 1 
				FROM STOCKSUMMARY SS 
				WHERE 				
					SS.ITEMPRICEID = IP.ITEMPRICEID
					AND (CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END <> 0)
			)
	ORDER BY 1, 4, 5, 6

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_NONMOVINGSTOCK]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_NONMOVINGSTOCK]
(
	@BranchID  NVARCHAR(1000)
	, @FromDate DATE
	, @ToDate DATE
	, @ITEMID  INT = 0
	, @CategoryID VARCHAR(500)
	, @CutOff INT = 0
)
AS
BEGIN
	
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID ,',')

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	DECLARE @IsWarehouse BIT, @count int

 	SELECT @count = COUNT(*) FROM 
	(
		SELECT count(ISWAREHOUSE) AS WAREHOUSE FROM #BRANCH BRANCHIDS
			INNER JOIN BRANCH B ON BRANCHIDS.ITEM = B.BRANCHID
		GROUP BY ISWAREHOUSE
	) AS A

	IF(@count > 1)
	BEGIN
		RAISERROR ('Warehouse and outlets cannot be selected at once', 16, 1)
		RETURN
	END

	SELECT TOP(1) @IsWarehouse = ISWAREHOUSE FROM #BRANCH BRANCHIDS
	INNER JOIN BRANCH B ON BRANCHIDS.ITEM = B.BRAnCHID

	DECLARE @CurrentMonthDate DATE 

	SELECT @CurrentMonthDate = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)

	SELECT 
		SSINNER.BRANCHID, IC.ITEMID, IC.ITEMCODEID, IP.MRP
		, CAST(SUM(CASE WHEN ITMINNER.ISOPENITEM <> 1 THEN SSINNER.QUANTITY ELSE SSINNER.WEIGHTINKGS END) AS DECIMAL(18, 2)) AS STOCKQTYORWGHT
		, AVGCP.COSTPRICEWOT, AVGCP.COSTPRICEWT
	INTO #SS
	FROM
		STOCKSUMMARY SSINNER WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID  = SSINNER.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM ITMINNER WITH(NOLOCK) ON ITMINNER.ITEMID = IC.ITEMID
		INNER JOIN #BRANCH BRANCHIDS ON SSINNER.BRANCHID = BRANCHIDS.ITEM
		INNER JOIN #CATEGORY CATINNER ON ITMINNER.CATEGORYID = CATINNER.ITEM
		LEFT JOIN AVGCOSTPRICE AVGCP WITH(NOLOCK) ON AVGCP.ITEMCODEID = IP.ITEMCODEID AND AVGCP.MRP = IP.MRP AND AVGCP.AVGCPDATE = @CurrentMonthDate
	WHERE (ITMINNER.ITEMID = @ITEMID OR @ITEMID = 0) AND ITMINNER.DELETEDDATE IS NULL
	GROUP BY SSINNER.BRANCHID, IC.ITEMID, IC.ITEMCODEID, IP.MRP, AVGCP.COSTPRICEWOT, AVGCP.COSTPRICEWT

	DELETE #SS WHERE STOCKQTYORWGHT = 0

	SELECT 
		SSINNER.ITEMID, SSINNER.BRANCHID, SUM(SSINNER.STOCKQTYORWGHT) STOCKQTYORWGHT
		, CAST(SUM(SSINNER.STOCKQTYORWGHT * SSINNER.COSTPRICEWT) / CASE WHEN SUM(SSINNER.STOCKQTYORWGHT) = 0 THEN 1 ELSE SUM(SSINNER.STOCKQTYORWGHT) END AS DECIMAL(18, 2)) AVGCOSTPRICEWT
		, CAST(SUM(SSINNER.STOCKQTYORWGHT * SSINNER.COSTPRICEWOT) / CASE WHEN SUM(SSINNER.STOCKQTYORWGHT) = 0 THEN 1 ELSE SUM(SSINNER.STOCKQTYORWGHT) END AS DECIMAL(18, 2)) AVGCOSTPRICEWOT
	INTO #SSGROUPED
	FROM #SS SSINNER
	GROUP BY SSINNER.ITEMID, SSINNER.BRANCHID

	IF @IsWarehouse = 0
	BEGIN

		SELECT 
			 B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME
			 , SS.STOCKQTYORWGHT, SALE.SALEQTYORWGHT, SALE.LASTSALEDATE, SD.LASTDISPATCHDATE
			 , CLS.CLASSIFICATIONNAME, SUBCLS.SUBCLASSIFICATIONNAME
			 , TB.BRANDNAME, TM.MANUFACTURERNAME, SS.AVGCOSTPRICEWOT, SS.AVGCOSTPRICEWT
			 , SS.AVGCOSTPRICEWT - SS.AVGCOSTPRICEWOT AVGCOSTPRICETAX
		FROM
			#SSGROUPED SS
			INNER JOIN ITEM I ON I.ITEMID = SS.ITEMID
			INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID		
			LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
			LEFT JOIN ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID		
			LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
			LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
			INNER JOIN BRANCH B ON SS.BRANCHID = B.BRANCHID
			LEFT JOIN
				(
					SELECT 
						IC.ITEMID, BC.BRANCHID, MAX(PBD.CREATEDDATE) LASTSALEDATE
						, SUM(CASE WHEN IINNER.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END) SALEQTYORWGHT
					FROM 
						POS_BILL PB WITH(NOLOCK)
						INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
						INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
						INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID		
						INNER JOIN ITEM IINNER ON IINNER.ITEMID = IC.ITEMID
						INNER JOIN #BRANCH BRANCHIDS ON BC.BRANCHID = BRANCHIDS.ITEM
					WHERE
						PB.BILLSTATUS = 1
						AND PBD.DELETEDDATE IS NULL					
						AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate						
					GROUP BY IC.ITEMID, BC.BRANCHID					
				) SALE ON SALE.ITEMID = SS.ITEMID AND SALE.BRANCHID = SS.BRANCHID
			LEFT JOIN
				(
					SELECT IC.ITEMID, SD.TOBRANCHID BRANCHID, MAX(SD.CREATEDDATE) AS LASTDISPATCHDATE
					FROM 
						STOCKDISPATCH SD WITH(NOLOCK)
						INNER JOIN STOCKDISPATCHDETAIL SDD WITH(NOLOCK) ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID		
						INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN #BRANCH BRANCHIDS ON SD.TOBRANCHID = BRANCHIDS.ITEM
					WHERE
						SD.DELETEDDATE IS NULL
						AND SDD.DELETEDDATE IS NULL					
						AND SD.CREATEDDATE >= @FromDate AND SD.CREATEDDATE < @ToDate
					GROUP BY IC.ITEMID, SD.TOBRANCHID
				) SD ON SD.ITEMID = SS.ITEMID AND SD.BRANCHID = SS.BRANCHID
		WHERE ISNULL(SALE.SALEQTYORWGHT, 0) <= @CutOff --OR @CutOff = 0
		ORDER BY CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.ITEMNAME

	END
	ELSE
	BEGIN
		
		SELECT 
			 B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME
			 , SS.STOCKQTYORWGHT, CLS.CLASSIFICATIONNAME, SUBCLS.SUBCLASSIFICATIONNAME,
			 TB.BRANDNAME, TM.MANUFACTURERNAME, SS.AVGCOSTPRICEWOT, SS.AVGCOSTPRICEWT
			 , SS.AVGCOSTPRICEWT - SS.AVGCOSTPRICEWOT AVGCOSTPRICETAX
		FROM
			#SSGROUPED SS
			INNER JOIN ITEM I ON I.ITEMID = SS.ITEMID
			INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID		
			LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
			LEFT JOIN ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
			LEFT JOIN ITEMSUBCLASSIFICATION SUBCLS ON SUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID		
			LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
			LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
			INNER JOIN BRANCH B ON SS.BRANCHID = B.BRANCHID
		WHERE
			NOT EXISTS
				(
					SELECT 1
					FROM 
						STOCKDISPATCH SD WITH(NOLOCK)
						INNER JOIN STOCKDISPATCHDETAIL SDD WITH(NOLOCK) ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID		
						INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM IINNER ON IINNER.ITEMID = IC.ITEMID
						INNER JOIN #BRANCH BRANCHIDS ON SD.FROMBRANCHID = BRANCHIDS.ITEM
					WHERE
						SD.DELETEDDATE IS NULL
						AND SDD.DELETEDDATE IS NULL					
						AND SD.CREATEDDATE >= @FromDate AND SD.CREATEDDATE < @ToDate
						AND IC.ITEMID = SS.ITEMID
						AND SS.BRANCHID = SD.TOBRANCHID
					GROUP BY IC.ITEMID
					HAVING SUM(CASE WHEN IINNER.ISOPENITEM = 1 THEN SDD.WEIGHTINKGS ELSE SDD.DISPATCHQUANTITY END) <= @CutOff --OR @CutOff = 0
				)
		ORDER BY B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.ITEMNAME

	END	

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_OFFER_STATUS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_OFFER_STATUS]
(
	@OfferSearchTypeID INT
	, @NoOfDays INT = 0
	, @BranchIDs VARCHAR(MAX)
	, @CatIDs VARCHAR(MAX)
	, @ClassIDs VARCHAR(MAX)
)
AS
BEGIN

	/*

		Analysis ID
			0 - All (undeleted)
			1 - Current
			2 - Expiring by N days
			3 - Commencing by N days
			4 - Inactive
	*/

	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')
	SELECT * INTO #CATS FROM dbo.SplitString(@CatIDs,',')
	SELECT * INTO #CLASS FROM dbo.SplitString(@ClassIDs,',')

	DECLARE @Query VARCHAR(MAX) =
		'
			SELECT
				B.BRANCHNAME, ISNULL(BOFR.OFFERNAME, OFR.OFFERNAME) OFFERNAME, ISNULL(BOFR.OFFERCODE, OFR.OFFERCODE) OFFERCODE
				, OFRIM.SKUCODE, OFRIM.ITEMNAME, OFRIM.ITEMCODE
				, OFRIM.CATEGORYNAME, OFRIM.SUBCATEGORYNAME
				, OFRIM.CLASSIFICATIONNAME, OFRIM.SUBCLASSIFICATIONNAME
				, OFRIM.MRP, OFRIM.SALEPRICE
				, ISNULL(BOFR.STARTDATE, OFR.STARTDATE) STARTDATE, ISNULL(BOFR.ENDDATE, OFR.ENDDATE) ENDDATE
				, CASE WHEN OFR.ISACTIVE = 1 THEN ''Active'' ELSE ''Inactive'' END ISACTIVE
				, CASE WHEN OFRT.BASETYPE = 1 THEN ''Offer'' ELSE ''Deal'' END OFFERBASETYPE
				, OFRA.AppliesToName, OFRT.OFFERTYPENAME, OFR.OFFERVALUE
				, CASE 
					WHEN OFRT.OFFERTYPECODE = ''DP'' THEN CAST(OFRIM.MRP * (100 - OFR.OFFERVALUE) / 100.00 AS DECIMAL(18, 2))
					WHEN OFRT.OFFERTYPECODE = ''DF'' THEN OFRIM.MRP - OFR.OFFERVALUE
					WHEN OFRT.OFFERTYPECODE = ''FR'' THEN OFR.OFFERVALUE
					ELSE 0 END AS FINALPRICE
				, OFRT.OFFERTYPEID, OFR.OFFERID, SS.QUANTITY AS BRANCHSTOCK
			FROM
				OFFER OFR
				INNER JOIN OFFERBRANCH OFRB ON OFRB.OFFERID = OFR.OFFERID
				INNER JOIN #BRANCH SB ON SB.ITEM = OFRB.BRANCHID
				INNER JOIN BRANCH B ON B.BRANCHID = OFRB.BRANCHID
				INNER JOIN OFFERTYPE OFRT ON OFRT.OFFERTYPEID = OFR.OFFERTYPEID
				INNER JOIN APPLIESTO OFRA ON OFRA.AppliesToID = OFR.APPLIESTOID
				INNER JOIN
				(
					SELECT I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE,
						ICLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME,
						CAT.CATEGORYNAME, SCAT.SUBCATEGORYNAME, OFRIM.OFFERID, OFRIM.DELETEDDATE,
						IP.ITEMPRICEID
					FROM OFFERITEMMAP OFRIM
						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = OFRIM.ITEMCODEID
						INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
						INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN ITEMCLASSIFICATION ICLS ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
						INNER JOIN ITEMSUBCLASSIFICATION ISUBCLS ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
						INNER JOIN TBLCATEGORY CAT ON I.CATEGORYID = CAT.CATEGORYID
						INNER JOIN SUBCATEGORY SCAT ON I.SUBCATEGORYID = SCAT.SUBCATEGORYID
						INNER JOIN #CATS CATS ON CAT.CATEGORYID = CATS.Item
						INNER JOIN #CLASS CLS ON ICLS.CLASSIFICATIONID = CLS.Item
					WHERE IP.DELETEDDATE IS NULL 
						AND IC.DELETEDDATE IS NULL
				) AS OFRIM ON OFRIM.OFFERID = OFR.OFFERID 
				INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = OFRIM.ITEMPRICEID AND SS.BRANCHID = SB.ITEM
				LEFT JOIN BASEOFFER BOFR ON BOFR.BASEOFFERID = OFR.BASEOFFERID
			WHERE
				(SS.QUANTITY <> 0 OR SS.WEIGHTINKGS <> 0)
				AND OFR.APPLIESTOID <> 3
				AND OFR.DELETEDDATE IS NULL
				AND OFRB.DELETEDDATE IS NULL
				AND BOFR.DELETEDDATE IS NULL				
				{0}
			ORDER BY B.BRANCHNAME 
			{1}
			, ISNULL(BOFR.OFFERNAME, OFR.OFFERNAME), OFRIM.ITEMNAME, OFRIM.ITEMCODE, OFRIM.MRP, OFRIM.SALEPRICE
		'
	
	DECLARE @WhereClause VARCHAR(MAX) = '', @OrderByClause VARCHAR(MAX) = '', @CutOffDate DATE = GETDATE()
	IF(@OfferSearchTypeID = 4)
		SET @CutOffDate = DATEADD(D, -(@NoOfDays + 1), CAST(GETDATE() AS DATE))
	ELSE
		SET @CutOffDate = DATEADD(D, @NoOfDays + 1, CAST(GETDATE() AS DATE))


	IF @OfferSearchTypeID = 1
	BEGIN
		SELECT @WhereClause = 'AND OFRIM.DELETEDDATE IS NULL AND OFR.ISACTIVE = 1 AND ISNULL(BOFR.STARTDATE, OFR.STARTDATE) <= CAST(GETDATE() AS DATE) AND CAST(GETDATE() AS DATE) <= ISNULL(BOFR.ENDDATE, OFR.ENDDATE) '
	END
	ELSE IF @OfferSearchTypeID = 2
	BEGIN
		SELECT @WhereClause = 'AND OFRIM.DELETEDDATE IS NULL AND ISNULL(BOFR.ENDDATE, OFR.ENDDATE) > CAST(GETDATE() AS DATE) AND ISNULL(BOFR.ENDDATE, OFR.ENDDATE) < ''' + CONVERT(VARCHAR(10), @CutOffDate, 120) + ''''
		SELECT @OrderByClause = ', ISNULL(BOFR.ENDDATE, OFR.ENDDATE) DESC'
	END
	ELSE IF @OfferSearchTypeID = 3
	BEGIN
		SELECT @WhereClause = 'AND OFRIM.DELETEDDATE IS NULL AND ISNULL(BOFR.STARTDATE, OFR.STARTDATE) > CAST(GETDATE() AS DATE) AND ISNULL(BOFR.STARTDATE, OFR.STARTDATE) < ''' + CONVERT(VARCHAR(10), @CutOffDate, 120) + ''''
		SELECT @OrderByClause = ', ISNULL(BOFR.STARTDATE, OFR.STARTDATE)'
	END
	ELSE IF @OfferSearchTypeID = 4
	BEGIN
		SELECT @WhereClause = 'AND (OFRIM.DELETEDDATE > ''' + CONVERT(VARCHAR(10), @CutOffDate, 120) + ''' OR (ISNULL(BOFR.ENDDATE, OFR.ENDDATE) < CAST(GETDATE() AS DATE) AND ISNULL(BOFR.ENDDATE, OFR.ENDDATE) > ''' + CONVERT(VARCHAR(10), @CutOffDate, 120) + '''



))'
		SELECT @OrderByClause = ', ISNULL(BOFR.ENDDATE, OFR.ENDDATE) DESC'
	END

	SELECT @Query = REPLACE(@Query, '{0}', @WhereClause)
	SELECT @Query = REPLACE(@Query, '{1}', @OrderByClause)
	EXEC (@Query)

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_OFFER_THRESHOLD]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_OFFER_THRESHOLD]
AS
BEGIN
	
	
	SELECT DISTINCT OFR.OFFERID,OIM.ITEMCODEID,OIM.NUMBEROFPIECES
	INTO #OFR
	FROM OFFERITEMMAP OIM
		INNER JOIN OFFER OFR ON OFR.OFFERID = OIM.OFFERID
	WHERE OFR.DELETEDDATE IS NULL
		AND OIM.DELETEDDATE IS NULL
		AND OFR.APPLIESTOID = 1

	SELECT OFR.ITEMCODEID,OFR.OFFERID, SUM(PBD.QUANTITY) AS SALEQUANTITY
	INTO #SALES
	FROM #OFR OFR
		INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = OFR.ITEMCODEID
		LEFT JOIN POS_BILLDETAIL PBD ON OFR.OFFERID = ISNULL(PBD.OFFERID,0) AND PBD.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN POS_BILL PB ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID
	WHERE PBD.DELETEDDATE IS NULL
		AND PB.DELETEDDATE IS NULL
		AND ISNULL(PB.BILLSTATUS,0) = 1	
	GROUP BY OFR.ITEMCODEID,OFR.OFFERID
	
	SELECT I.SKUCODE, I.ITEMNAME, IC.ITEMCODE,CAT.CATEGORYNAME, SCAT.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME, 
		CLS.CLASSIFICATIONNAME, SCLS.SUBCLASSIFICATIONNAME, 
		ISNULL(BO.OFFERNAME,OFRINNER.OFFERNAME) AS OFFERNAME, OFRTYPE.OFFERTYPENAME,OFRINNER.OFFERVALUE,
		ISNULL(BO.STARTDATE,OFRINNER.STARTDATE) AS STARTDATE,ISNULL(BO.ENDDATE,OFRINNER.ENDDATE) AS ENDDATE, ISNULL(S.SALEQUANTITY,0) AS SALEQUANTITY, 
		ISNULL(OFR.NUMBEROFPIECES,0) AS OFFERTHRESHOLD,  ISNULL(OFR.NUMBEROFPIECES,0) - ISNULL(S.SALEQUANTITY,0) AS BALANCESALE
	FROM #OFR OFR
		LEFT JOIN #SALES S ON OFR.ITEMCODEID = S.ITEMCODEID AND OFR.OFFERID = S.OFFERID
		INNER JOIN OFFER OFRINNER ON OFR.OFFERID = OFRINNER.OFFERID
		LEFT JOIN BASEOFFER BO ON OFRINNER.BASEOFFERID = BO.BASEOFFERID
		INNER JOIN OFFERTYPE OFRTYPE ON OFRINNER.OFFERTYPEID = OFRTYPE.OFFERTYPEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = OFR.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SCAT ON SCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION SCLS ON SCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID

	DROP TABLE #SALES
	DROP TABLE #OFR

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_PICKLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_PICKLIST]
(
	@CategoryID INT
	, @FromDate DATE
	, @ToDate DATE
	, @IncludeInvoiceDetails BIT = 0
	, @IncludeBranch BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT 
		PL.PICKLISTID, CAT.CATEGORYNAME, LD.LOCATIONDIVISIONNAME, PL.PICKLISTNUMBER, PL.PICKLISTSTATUS
		, ELSTATUS.ENUMVALUE PICKLISTSTATUSTEXT, DLR.DEALERNAME, PLCU.FULLNAME AS CREATEDBY, PL.CREATEDDATE
		, SE.SUPPLIERINVOICENO, SE.INVOICEDATE
		, PLB.PICKLISTBRANCHID, B.BRANCHNAME, ELPLBSTATUS.ENUMVALUE AS PICKLISTBRANCHSTATUS
	FROM
		PICKLIST PL
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = PL.CATEGORYID
		INNER JOIN TBLDEALER DLR ON DLR.DEALERID = PL.SUPPLIERID
		INNER JOIN LOCATIONDIVISION LD ON LD.LOCATIONDIVISIONID = PL.LOCATIONDIVISIONID
		INNER JOIN ENUMLIST ELSTATUS ON ELSTATUS.ENUMID = PL.PICKLISTSTATUS
		LEFT JOIN TBLUSER PLCU ON PLCU.USERID = PL.CREATEDBY
		LEFT JOIN STOCKENTRY SE ON SE.PICKLISTID = PL.PICKLISTID AND @IncludeInvoiceDetails = 1
		LEFT JOIN PICKLISTBRANCH PLB ON PLB.PICKLISTID = PL.PICKLISTID AND @IncludeBranch = 1
		LEFT JOIN BRANCH B ON B.BRANCHID = PLB.BRANCHID
		LEFT JOIN ENUMLIST ELPLBSTATUS ON ELPLBSTATUS.ENUMID = PLB.PICKEDSTATUS
	WHERE 
		PL.DELETEDDATE IS NULL
		AND PL.CREATEDDATE > @FromDate
		AND PL.CREATEDDATE < @ToDate
		AND (PL.CATEGORYID = @CategoryID OR @CategoryID = 0 OR @CategoryID = 13)
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_POS_BILL_PRINT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_POS_BILL_PRINT]
(
	@BillID INT
	, @BranchCounterID INT
)
AS
BEGIN

	DECLARE @BilledAmount DECIMAL(10, 2), @Rounding DECIMAL(3, 2)

	SELECT                                
		@BilledAmount = SUM(BD.BILLEDAMOUNT)       
	FROM                                
		POS_BILLDETAIL BD                                		         
	WHERE 
		BD.BILLID = @BillID AND BD.DELETEDDATE IS NULL          
		AND BD.BRANCHCOUNTERID = @BranchCounterID
	
	SELECT @BilledAmount = @BilledAmount - ISNULL(SUM(BM.MOPVALUE), 0)
	FROM 
		TBLMOP M  
		INNER JOIN POS_BILLMOPDETAIL BM ON M.MOPID = BM.MOPID  
	WHERE BM.BILLID = @BillID AND BM.COUNTERID = @BranchCounterID AND M.MOPNAME <> 'CASH'

	SELECT @Rounding = ROUND(@BilledAmount, 0) - @BilledAmount

	SELECT                                 
		B.BILLID, B.BILLNUMBER, B.BILLSTATUS, B.CREATEDDATE, @Rounding ROUNDING, B.ISDOORDELIVERY,
		--@LastBilledAmount AS LASTBILLEDAMOUNT, @LastBilledQuantity AS LASTBILLEDQUANTITY, @LastBillID AS LASTBILLID
		B.CUSTOMERNAME,B.CUSTOMERNUMBER,B.CUSTOMERGST, B.TENDEREDCASH,B.TENDEREDCHANGE, BRCH.[ADDRESS], BRCH.BRANCHNAME, BC.COUNTERNAME
		, BRCH.PHONENO, USR.FULLNAME AS CREATEDBY, B.ISIGSTBILL, B.BILLCLOSEDDATE
	FROM                                 
		POS_BILL B                                
		--LEFT JOIN POS_BILL LASTBILL ON LASTBILL.BILLID = @LastBillID    
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = B.BRANCHCOUNTERID 
		INNER JOIN BRANCH BRCH ON BRCH.BRANCHID = BC.BRANCHID
		INNER JOIN TBLUSER USR ON USR.USERID = B.CREATEDBY
	WHERE B.BILLID = @BillID AND B.BRANCHCOUNTERID = @BranchCounterID
                                
	SELECT                                
		BD.BILLDETAILID, B.BILLID, IP.ITEMPRICEID,                        
		BD.SNO, I.ITEMNAME, IC.ITEMCODE, ISNULL(IC.HSNCODE,'') AS HSNCODE,IP.MRP                              
		,IP.SALEPRICE, GST.GSTCODE, BD.QUANTITY,                        
		BD.WEIGHTINKGS, BD.BILLEDAMOUNT,                        
		BD.CGST, BD.SGST, BD.IGST, BD.CESS,                        
		BD.GSTVALUE, BD.GSTID,GST.CGST AS CGSTDESC,                        
		GST.SGST AS SGSTDESC,GST.CESS AS CESSDESC,                        
		ISNULL(I.ISOPENITEM,0) AS ISOPENITEM, DISCOUNT, BD.OFFERID, OFRTYP.OFFERTYPECODE            
	FROM                                
		POS_BILLDETAIL BD                                
		INNER JOIN POS_BILL B ON B.BILLID = BD.BILLID AND B.BRANCHCOUNTERID = BD.BRANCHCOUNTERID                             
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BD.ITEMPRICEID                                
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID                                
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID                                
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID                 
		LEFT JOIN OFFER OFR ON OFR.OFFERID = BD.OFFERID            
		LEFT JOIN OFFERTYPE OFRTYP ON OFRTYP.OFFERTYPEID = OFR.OFFERTYPEID            
	WHERE 
		B.BILLID = @BillID AND BD.DELETEDDATE IS NULL          
		AND B.BRANCHCOUNTERID = @BranchCounterID
	ORDER BY BD.SNO         

	SELECT BM.MOPID, M.MOPNAME, BM.MOPVALUE 
	FROM 
		TBLMOP M  
		INNER JOIN POS_BILLMOPDETAIL BM ON M.MOPID = BM.MOPID  
	WHERE BM.BILLID = @BillID AND BM.COUNTERID = @BranchCounterID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_POS_CUSTOMERDETAILS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_POS_CUSTOMERDETAILS]
(
	@BRANCHID VARCHAR(500)
	, @FromDate DATE
	, @ToDate DATE
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT 
		BR.BRANCHID, BR.BRANCHNAME, BR.BRANCHCODE, ISNULL(B.CUSTOMERNAME, '') CUSTOMERNAME, ISNULL(B.CUSTOMERNUMBER, '') CUSTOMERNUMBER, COUNT(1) NOOFBILLS
	FROM 
		POS_BILL B 
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = B.BRANCHCOUNTERID
		INNER JOIN BRANCH BR ON BR.BRANCHID = BC.BRANCHID
		INNER JOIN dbo.SplitString(@BRANCHID,',') BIDS ON BR.BRANCHID = BIDS.ITEM
	WHERE 
		(ISNULL(LTRIM(RTRIM(CUSTOMERNAME)), '') <> '' OR ISNULL(LTRIM(RTRIM(CUSTOMERNUMBER)), '') <> '')
		AND B.CREATEDDATE > @FromDate
		AND B.CREATEDDATE < @ToDate
	GROUP BY BR.BRANCHID, BR.BRANCHNAME, BR.BRANCHCODE, ISNULL(B.CUSTOMERNAME, ''), ISNULL(B.CUSTOMERNUMBER, '')
	ORDER BY BR.BRANCHNAME, COUNT(1) DESC
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_PROCESSING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_PROCESSING]
(
	@FromDate DATE,
	@ToDate DATE,
	@IncludeParentItems BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT 
		CAST(SA.CREATEDDATE AS DATE) CREATEDDATE, CAST(SA.CREATEDDATE AS TIME) AS CREATEDTIME, I.SKUCODE, I.ITEMNAME
		, IC.ITEMCODE, IP.MRP, IP.SALEPRICE, PITEM.ITEMNAME PARENTITEMNAME, PITEM.SKUCODE PARENTSKUCODE
		, CASE WHEN I.ISOPENITEM = 1 THEN SA.WEIGHTINKGS - SA.PREVWEIGHTINKGS ELSE SA.QUANTITY - SA.PREVQUANTITY END AS QTYORWGHTINKGS
		, CU.FULLNAME AS CREATEDBY, SA.ITEMPRICEID
	FROM
		STOCKADJUSTMENT SA
		INNER JOIN STOCKADJUSTMENTTYPE SAD ON SAD.STOCKADJUSTMENTTYPEID = SA.STOCKADJUSTMENTTYPEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SA.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLUSER CU ON CU.USERID = SA.CREATEDBY
		LEFT JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID
	WHERE 
		SA.BRANCHID = 45
		AND SAD.STOCKADJUSTMENTTYPE = 'Processing'
		AND SA.CREATEDDATE >= @FromDate
		AND SA.CREATEDDATE < @ToDate
		AND (I.PARENTITEMID <> I.ITEMID OR @IncludeParentItems = 1)
	ORDER BY 1 DESC, 2 DESC, I.ITEMNAME

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_PROFITABILITY_PERIODICITY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_PROFITABILITY_PERIODICITY]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchIDs VARCHAR(500)
	, @Periodicity VARCHAR(20)
	, @CategoryID VARCHAR(MAX)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0	
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0
	, @IncludeSupplier BIT = 0
	, @IncludeTax BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
		
	DECLARE @DateSuffixInYear VARCHAR(15)

	SELECT @DateSuffixInYear = 
			'-' + CASE 
					WHEN @Periodicity = 'Yearly' THEN '01'
					WHEN @Periodicity = 'Fin. Yearly' THEN '04'
					ELSE NULL END 
			+ '-01 00:00:00'

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, GSTID INT, MRP DECIMAL(7, 2), SALEQUANTITY DECIMAL(11, 2)
		, SALEPRICE DECIMAL(7, 2), ACTUALSALEPRICE DECIMAL(7, 2), ACTUALSALEPRICEWOT DECIMAL(7, 2), ACTUALSALEPRICETAX DECIMAL(7, 2)
		, ITEMCOSTPRICEID INT, AVGCOSTPRICEWOT DECIMAL(11, 2), AVGCOSTPRICETAX DECIMAL(11, 2), AVGCOSTPRICEWT DECIMAL(11, 2)
		, TOTALCOSTPRICEWOT DECIMAL(14, 2), TOTALCOSTPRICETAX DECIMAL(14, 2), TOTALCOSTPRICEWT DECIMAL(14, 2)
		, TOTALSALEPRICEWOT DECIMAL(14, 2), TOTALSALETAX DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2)
		, PERIODICITY DATE, SUPPLIERID INT, BRANDID INT, MANUFACTURERID INT)
	
	SELECT *
	INTO #SALES
	FROM
		(
			SELECT PBD.ITEMPRICEID, BC.BRANCHID, PBD.GSTID, PBD.BILLEDAMOUNT, PBD.GSTVALUE, PBD.QUANTITY, PBD.WEIGHTINKGS, PBD.CREATEDDATE
				, PBD.QUANTITY PBDQUANTITY
			FROM 
				POS_BILLDETAIL PBD WITH(NOLOCK)
				INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN dbo.SplitString(@BranchIDs,',') B ON BC.BRANCHID = B.ITEM
			WHERE
				PBD.CREATEDDATE > (@FromDate)
				AND PBD.CREATEDDATE < @ToDate
				AND PBD.DELETEDDATE IS NULL
				AND PB.BILLSTATUS = 1
				--AND PBD.QUANTITY > 0

			UNION ALL

			SELECT PBD.ITEMPRICEID, BC.BRANCHID, PBD.GSTID, -CR.REFUNDAMOUNT, -PBD.GSTVALUE , -CR.REFUNDQUANTITY, -CR.REFUNDWEIGHTINKGS, CR.CREATEDDATE
				, PBD.QUANTITY PBDQUANTITY
			FROM 
				POS_CREFUND CR WITH(NOLOCK) 
				INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CR.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN dbo.SplitString(@BranchIDs,',') B ON BC.BRANCHID = B.ITEM
			WHERE
				CR.CREATEDDATE > (@FromDate)
				AND CR.CREATEDDATE < @ToDate
				AND PBD.DELETEDDATE IS NULL
				AND PB.BILLSTATUS = 1
				--AND PBD.QUANTITY > 0
		) SALES

	DELETE #SALES WHERE PBDQUANTITY <= 0

	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, MRP, SALEPRICE, ACTUALSALEPRICE, GSTID, TOTALSALEPRICEWT, TOTALSALETAX, SALEQUANTITY, PERIODICITY
		, AVGCOSTPRICEWOT, AVGCOSTPRICEWT) 
	SELECT 
		SALES.ITEMPRICEID, CASE WHEN @IncludeBranch = 1 THEN SALES.BRANCHID ELSE NULL END, IP.MRP, IP.SALEPRICE
		, SALES.ACTUALSALEPRICE, SALES.GSTID, SUM(SALES.BILLEDAMOUNT), SUM(SALES.GSTVALUE)
		, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SUM(SALES.QUANTITY) ELSE SUM(SALES.WEIGHTINKGS) END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN SALES.CREATEDDATE
			WHEN @Periodicity = 'Monthly' THEN FORMAT(SALES.CREATEDDATE, 'yyyy-MM-01')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(SALES.CREATEDDATE, 'yyyy-01-01')
			WHEN @Periodicity = 'Fin. Yearly' THEN CAST((CAST(YEAR(SALES.CREATEDDATE) - CASE WHEN MONTH(SALES.CREATEDDATE) < 4 THEN 1 ELSE 0 END AS VARCHAR(4)) + @DateSuffixInYear) AS DATETIME)
		  END AS DATE) ELSE NULL END
		, SALES.COSTPRICEWOT, SALES.COSTPRICEWT
	FROM 
		(
			SELECT 
				SALESINNER.ITEMPRICEID, SALESINNER.BRANCHID, SALESINNER.GSTID, SALESINNER.BILLEDAMOUNT, SALESINNER.GSTVALUE, SALESINNER.QUANTITY, SALESINNER.WEIGHTINKGS, SALESINNER.CREATEDDATE
				, SALESINNER.BILLEDAMOUNT / NULLIF(CASE WHEN ISNULL(IINNER.ISOPENITEM, 0) = 0 THEN SALESINNER.QUANTITY ELSE SALESINNER.WEIGHTINKGS END, 0)  ACTUALSALEPRICE
				, AICP.COSTPRICEWOT, AICP.COSTPRICEWT
			FROM
				#SALES SALESINNER
				INNER JOIN ITEMPRICE IPINNER WITH(NOLOCK) ON IPINNER.ITEMPRICEID = SALESINNER.ITEMPRICEID
				INNER JOIN ITEMCODE ICINNER WITH(NOLOCK) ON ICINNER.ITEMCODEID = IPINNER.ITEMCODEID
				INNER JOIN ITEM IINNER WITH(NOLOCK) ON IINNER.ITEMID = ICINNER.ITEMID
				INNER JOIN #CATEGORY CATINNER ON IINNER.CATEGORYID = CATINNER.ITEM
				--LEFT JOIN AVGCOSTPRICE AICP  WITH(NOLOCK) ON AICP.ITEMPRICEID = SALESINNER.ITEMPRICEID AND YEAR(AICP.AVGCPDATE) = YEAR(SALESINNER.CREATEDDATE) AND MONTH(AICP.AVGCPDATE) = MONTH(SALESINNER.CREATEDDATE)
				LEFT JOIN AVGCOSTPRICE AICP  WITH(NOLOCK) ON AICP.ITEMCODEID = IPINNER.ITEMCODEID AND AICP.MRP = IPINNER.MRP
					AND YEAR(AICP.AVGCPDATE) = YEAR(SALESINNER.CREATEDDATE) AND MONTH(AICP.AVGCPDATE) = MONTH(SALESINNER.CREATEDDATE)
		) SALES
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SALES.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
	GROUP BY 
		SALES.ITEMPRICEID, CASE WHEN @IncludeBranch = 1 THEN SALES.BRANCHID ELSE NULL END		
		, IP.MRP, IP.SALEPRICE, SALES.ACTUALSALEPRICE, I.ISOPENITEM, SALES.GSTID
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN SALES.CREATEDDATE
			WHEN @Periodicity = 'Monthly' THEN FORMAT(SALES.CREATEDDATE, 'yyyy-MM-01')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(SALES.CREATEDDATE, 'yyyy-01-01')
			WHEN @Periodicity = 'Fin. Yearly' THEN CAST((CAST(YEAR(SALES.CREATEDDATE) - CASE WHEN MONTH(SALES.CREATEDDATE) < 4 THEN 1 ELSE 0 END AS VARCHAR(4)) + @DateSuffixInYear) AS DATETIME)
		  END AS DATE) ELSE NULL END, SALES.COSTPRICEWOT, SALES.COSTPRICEWT 
		  
	UPDATE PT
	SET ACTUALSALEPRICETAX = ROUND(PT.ACTUALSALEPRICE -((PT.ACTUALSALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100), 2)
	FROM 
		#PROFITABILIY PT
		INNER JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID

	UPDATE PT
	SET ACTUALSALEPRICEWOT = ACTUALSALEPRICE - ACTUALSALEPRICETAX
	FROM #PROFITABILIY PT

	UPDATE PT
	SET 
		PT.AVGCOSTPRICETAX = PT.AVGCOSTPRICEWT - PT.AVGCOSTPRICEWOT
		, PT.TOTALCOSTPRICEWT = PT.AVGCOSTPRICEWT * PT.SALEQUANTITY
		, PT.TOTALCOSTPRICEWOT = PT.AVGCOSTPRICEWOT * PT.SALEQUANTITY
		, PT.TOTALCOSTPRICETAX = (PT.AVGCOSTPRICEWT - PT.AVGCOSTPRICEWOT) * PT.SALEQUANTITY
		, PT.TOTALSALEPRICEWOT = PT.TOTALSALEPRICEWT - PT.TOTALSALETAX
	FROM 
		#PROFITABILIY PT
					
	SELECT 
		PTMAIN.PERIODICITY, B.BRANCHNAME, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, IP.MRP, PTMAIN.SALEPRICE, GST.GSTCODE, PTMAIN.ACTUALSALEPRICEWOT, PTMAIN.ACTUALSALEPRICETAX, PTMAIN.ACTUALSALEPRICE
		, PTMAIN.SALEQUANTITY, PTMAIN.AVGCOSTPRICEWOT, PTMAIN.AVGCOSTPRICETAX, PTMAIN.AVGCOSTPRICEWT
		, PTMAIN.TOTALSALEPRICEWOT, PTMAIN.TOTALSALETAX, PTMAIN.TOTALSALEPRICEWT, PTMAIN.TOTALCOSTPRICEWOT, PTMAIN.TOTALCOSTPRICETAX, PTMAIN.TOTALCOSTPRICEWT
		, PTMAIN.PROFITMARGINWOT, PTMAIN.PROFITMARGINPERWOTBYWOT 'Profit Margin % WOT (by WOT)', PTMAIN.PROFITMARGINPERWOTBYWT 'Profit Margin % WOT (by WT)', PTMAIN.PROFITMARGINWT, PTMAIN.PROFITMARGINPERWT
		, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME, DLR.DEALERNAME
	FROM
		(
			SELECT 
				 CASE WHEN @IncludeItem = 1 THEN PT.ITEMPRICEID ELSE NULL END ITEMPRICEID
				, CASE WHEN @IncludeBranch = 1 THEN PT.BRANCHID ELSE NULL END BRANCHID		 		
				, CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END CATEGORYID
				, CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END SUBCATEGORYID
				, CASE WHEN @IncludeDate = 1 THEN PT.PERIODICITY ELSE NULL END PERIODICITY
				, CASE WHEN @IncludeClassification = 1 THEN I.CLASSIFICATIONID ELSE NULL END CLASSIFICATIONID
				, CASE WHEN @IncludeSubClassification = 1 THEN I.SUBCLASSIFICATIONID ELSE NULL END SUBCLASSIFICATIONID
				, CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END ITEMID
				, CASE WHEN @IncludeTax = 1 THEN PT.GSTID ELSE NULL END GSTID
				, CASE WHEN @IncludeItem = 1 THEN PT.SALEPRICE ELSE NULL END SALEPRICE
				, CASE WHEN @IncludeItem = 1 THEN PT.ACTUALSALEPRICEWOT ELSE NULL END ACTUALSALEPRICEWOT
				, CASE WHEN @IncludeItem = 1 THEN PT.ACTUALSALEPRICETAX ELSE NULL END ACTUALSALEPRICETAX
				, CASE WHEN @IncludeItem = 1 THEN PT.ACTUALSALEPRICE ELSE NULL END ACTUALSALEPRICE
				, CASE WHEN @IncludeItem = 1 THEN SUM(PT.SALEQUANTITY) ELSE NULL END SALEQUANTITY
				, CASE WHEN @IncludeItem = 1 THEN PT.AVGCOSTPRICEWOT ELSE NULL END AVGCOSTPRICEWOT
				, CASE WHEN @IncludeItem = 1 THEN PT.AVGCOSTPRICETAX ELSE NULL END AVGCOSTPRICETAX
				, CASE WHEN @IncludeItem = 1 THEN PT.AVGCOSTPRICEWT ELSE NULL END AVGCOSTPRICEWT
				, CASE WHEN @IncludeSupplier = 1 THEN PT.SUPPLIERID ELSE NULL END SUPPLIERID
				, SUM(PT.TOTALCOSTPRICEWOT) TOTALCOSTPRICEWOT, SUM(PT.TOTALCOSTPRICETAX) TOTALCOSTPRICETAX, SUM(PT.TOTALCOSTPRICEWT) TOTALCOSTPRICEWT
				, SUM(PT.TOTALSALEPRICEWOT) TOTALSALEPRICEWOT, SUM(PT.TOTALSALETAX) TOTALSALETAX, SUM(PT.TOTALSALEPRICEWT) TOTALSALEPRICEWT
				, SUM(TOTALSALEPRICEWOT) - ISNULL(SUM(TOTALCOSTPRICEWOT), 0) PROFITMARGINWOT
				, CAST(((SUM(TOTALSALEPRICEWOT) - SUM(TOTALCOSTPRICEWOT)) / CASE WHEN ISNULL(SUM(TOTALSALEPRICEWOT), 0) = 0 THEN 1 ELSE SUM(TOTALSALEPRICEWOT) END) * 100 AS DECIMAL(18, 2)) PROFITMARGINPERWOTBYWOT
				, CAST(((SUM(TOTALSALEPRICEWOT) - SUM(TOTALCOSTPRICEWOT)) / CASE WHEN ISNULL(SUM(TOTALSALEPRICEWT), 0) = 0 THEN 1 ELSE SUM(TOTALSALEPRICEWT) END) * 100 AS DECIMAL(18, 2)) PROFITMARGINPERWOTBYWT
				, SUM(TOTALSALEPRICEWT) - ISNULL(SUM(TOTALCOSTPRICEWT), 0) PROFITMARGINWT
				, CAST(((SUM(TOTALSALEPRICEWT) - SUM(TOTALCOSTPRICEWT)) / CASE WHEN ISNULL(SUM(TOTALSALEPRICEWT), 0) = 0 THEN 1 ELSE SUM(TOTALSALEPRICEWT) END) * 100 AS DECIMAL(18, 2)) PROFITMARGINPERWT
				, CASE WHEN @IncludeBrand = 1 THEN I.BRANDID ELSE NULL END BRANDID
				, CASE WHEN @IncludeManufacturer = 1 THEN I.MANUFACTURERID ELSE NULL END MANUFACTURERID
			FROM 
				#PROFITABILIY PT
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PT.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
				LEFT JOIN BRANCH B ON B.BRANCHID = PT.BRANCHID
			GROUP BY 
				CASE WHEN @IncludeItem = 1 THEN PT.ITEMPRICEID ELSE NULL END
				, CASE WHEN @IncludeBranch = 1 THEN PT.BRANCHID ELSE NULL END				
				, CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END
				, CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END
				, CASE WHEN @IncludeDate = 1 THEN PT.PERIODICITY ELSE NULL END
				, CASE WHEN @IncludeClassification = 1 THEN I.CLASSIFICATIONID ELSE NULL END
				, CASE WHEN @IncludeSubClassification = 1 THEN I.SUBCLASSIFICATIONID ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END
				, CASE WHEN @IncludeTax = 1 THEN PT.GSTID ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN PT.ACTUALSALEPRICEWOT ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN PT.ACTUALSALEPRICETAX ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN PT.ACTUALSALEPRICE ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN PT.SALEPRICE ELSE NULL END
				, CASE WHEN @IncludeSupplier = 1 THEN PT.SUPPLIERID ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN PT.AVGCOSTPRICEWOT ELSE NULL END 
				, CASE WHEN @IncludeItem = 1 THEN PT.AVGCOSTPRICETAX ELSE NULL END 
				, CASE WHEN @IncludeItem = 1 THEN PT.AVGCOSTPRICEWT ELSE NULL END
				, CASE WHEN @IncludeBrand = 1 THEN I.BRANDID ELSE NULL END
				, CASE WHEN @IncludeManufacturer = 1 THEN I.MANUFACTURERID ELSE NULL END
		) PTMAIN
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON PTMAIN.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON PTMAIN.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC WITH(NOLOCK) ON PTMAIN.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON PTMAIN.BRANCHID = B.BRANCHID		
		LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = PTMAIN.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS WITH(NOLOCK) ON ISCLS.SUBCLASSIFICATIONID = PTMAIN.SUBCLASSIFICATIONID
		LEFT JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PTMAIN.GSTID
		LEFT JOIN TBLDEALER DLR WITH(NOLOCK) ON DLR.DEALERID = PTMAIN.SUPPLIERID
		LEFT JOIN TBLBRAND BR ON PTMAIN.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PTMAIN.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4, I.ITEMNAME, IC.ITEMCODE, IP.MRP, LEN(GSTCODE), GSTCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_PROFITABILITY_SKUWISE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_PROFITABILITY_SKUWISE]
(
	@CategoryID VARCHAR(MAX)
	, @FromDate DATE
	, @ToDate DATE
	, @BranchID INT = 0
	, @IncludeBranch BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	
	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, CATEGORYID INT, GSTID INT, MRP DECIMAL(7, 2), SALEQUANTITY DECIMAL(11, 2)
		, SALEPRICE DECIMAL(7, 2), ACTUALSALEPRICE DECIMAL(7, 2), SALEPRICEWOT DECIMAL(7, 2), SALEPRICETAX DECIMAL(7, 2)
		, COSTPRICEWOT DECIMAL(11, 4), COSTPRICETAX DECIMAL(11, 4), COSTPRICEWT DECIMAL(11, 4)
		, TOTALCOSTPRICEWOT DECIMAL(14, 2), TOTALCOSTPRICETAX DECIMAL(14, 2), TOTALCOSTPRICEWT DECIMAL(14, 2)
		, TOTALSALEPRICEWOT DECIMAL(14, 2), TOTALSALETAX DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2)
		, PROFITMARGINWOT DECIMAL(11, 2), PROFITMARGINPERWOT  DECIMAL(11, 2), PROFITMARGINWT DECIMAL(11, 2), PROFITMARGINPERWT  DECIMAL(11, 2))

	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, CATEGORYID, MRP, SALEPRICE, ACTUALSALEPRICE, GSTID, SALEQUANTITY)
	SELECT ITEMPRICEID, BRANCHID, CATEGORYID, MRP, SALEPRICE, ACTUALSALEPRICE, GSTID, SUM(SALEQUANTITY) 
	FROM 
		(
			SELECT 
				IP.ITEMPRICEID, CASE WHEN @BranchID = 0 AND @IncludeBranch = 0 THEN 0 ELSE BC.BRANCHID END BRANCHID, I.CATEGORYID
				, IP.MRP, IP.SALEPRICE, CAST(ROUND(PBD.BILLEDAMOUNT / (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END), 2) AS DECIMAL(14, 2)) ACTUALSALEPRICE
				, PBD.GSTID, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SUM(PBD.QUANTITY) ELSE SUM(PBD.WEIGHTINKGS) END AS SALEQUANTITY
			FROM 
				ITEMPRICE IP 
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
				INNER JOIN POS_BILLDETAIL PBD ON PBD.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
			WHERE
				(BC.BRANCHID = @BranchID OR @BranchID = 0)
				AND PBD.CREATEDDATE > (@FromDate)
				AND PBD.CREATEDDATE < @ToDate
				AND PBD.DELETEDDATE IS NULL
				AND PB.BILLSTATUS = 1
				AND (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END) > 0.00 
			GROUP BY 
				IP.ITEMPRICEID, CASE WHEN @BranchID = 0 AND @IncludeBranch = 0 THEN 0 ELSE BC.BRANCHID END
				, I.CATEGORYID, IP.MRP, IP.SALEPRICE, I.ISOPENITEM, PBD.GSTID, 
				PBD.BILLEDAMOUNT / (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END) 

			UNION ALL

			SELECT IP.ITEMPRICEID, CASE WHEN @BranchID = 0 AND @IncludeBranch = 0 THEN 0 ELSE BC.BRANCHID END
				, I.CATEGORYID, IP.MRP, IP.SALEPRICE, CAST((PBD.BILLEDAMOUNT / (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END)) AS DECIMAL(14, 2))
				, PBD.GSTID, - (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SUM(CR.REFUNDQUANTITY) ELSE SUM(CR.REFUNDWEIGHTINKGS) END) AS SALEQUANTITY
			FROM
				POS_CREFUND CR
				INNER JOIN POS_BILLDETAIL PBD ON PBD.BILLDETAILID = CR.BILLDETAILID AND PBD.BRANCHCOUNTERID = CR.COUNTERID
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
				INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
			WHERE
				(BC.BRANCHID = @BranchID OR @BranchID = 0)
				AND CR.CREATEDDATE > (@FromDate)
				AND CR.CREATEDDATE < @ToDate
				AND CR.DELETEDDATE IS NULL
				AND (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END) > 0.00 
			GROUP BY 
				IP.ITEMPRICEID, CASE WHEN @BranchID = 0 AND @IncludeBranch = 0 THEN 0 ELSE BC.BRANCHID END
				, I.CATEGORYID, IP.MRP, IP.SALEPRICE, I.ISOPENITEM, PBD.GSTID, 
				 PBD.BILLEDAMOUNT / (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END)
		) SALE
	GROUP BY ITEMPRICEID, BRANCHID, CATEGORYID, MRP, SALEPRICE, ACTUALSALEPRICE, GSTID

	
	UPDATE PT
	SET SALEPRICETAX = ROUND(PT.ACTUALSALEPRICE -((PT.ACTUALSALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100), 2)
	FROM 
		#PROFITABILIY PT
		INNER JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID

	UPDATE PT
	SET SALEPRICEWOT = ACTUALSALEPRICE - SALEPRICETAX
	FROM #PROFITABILIY PT

	UPDATE PT
	SET TOTALSALEPRICEWOT = SALEPRICEWOT * SALEQUANTITY
		, TOTALSALEPRICEWT = ACTUALSALEPRICE * SALEQUANTITY
		, TOTALSALETAX = SALEPRICETAX * SALEQUANTITY
	FROM #PROFITABILIY PT

	UPDATE PT
	SET 
		PT.COSTPRICEWT = ICP.COSTPRICEWT
		, PT.COSTPRICEWOT = ICP.COSTPRICEWOT
		, PT.COSTPRICETAX = ICP.COSTPRICEWT - ICP.COSTPRICEWOT
		, PT.TOTALCOSTPRICEWT = ICP.COSTPRICEWT * PT.SALEQUANTITY
		, PT.TOTALCOSTPRICEWOT = ICP.COSTPRICEWOT * PT.SALEQUANTITY
		, PT.TOTALCOSTPRICETAX = (ICP.COSTPRICEWT - ICP.COSTPRICEWOT) * PT.SALEQUANTITY
		, PT.TOTALSALEPRICEWOT = PT.TOTALSALEPRICEWT - PT.TOTALSALETAX
	FROM 
		#PROFITABILIY PT
		INNER JOIN 
			(
				SELECT ICPINNER.ITEMPRICEID, SUM(ICPINNER.COSTPRICEWT * ICPINNER.QUANTITY) / SUM(ICPINNER.QUANTITY) COSTPRICEWT
					, SUM(ICPINNER.COSTPRICEWOT * ICPINNER.QUANTITY) / SUM(ICPINNER.QUANTITY) COSTPRICEWOT
				FROM ITEMCOSTPRICE ICPINNER
				WHERE ICPINNER.CREATEDDATE < @ToDate AND ICPINNER.QUANTITY <> 0
				GROUP BY ICPINNER.ITEMPRICEID
			) ICP ON ICP.ITEMPRICEID = PT.ITEMPRICEID
		--INNER JOIN IPICPView ICP ON ICP.ITEMPRICEID = PT.ITEMPRICEID //RECENT
		--INNER JOIN 
		--	(
		--		SELECT MAX(ICPINNER.ITEMCOSTPRICEID) AS MAXICP, ICPINNER.ITEMPRICEID
		--		FROM ITEMCOSTPRICE ICPINNER GROUP BY ICPINNER.ITEMPRICEID
		--	) ICPMAX ON ICPMAX.ITEMPRICEID = PT.ITEMPRICEID
		--INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = ICPMAX.MAXICP

	UPDATE #PROFITABILIY 
	SET 
		PROFITMARGINWOT = TOTALSALEPRICEWOT - TOTALCOSTPRICEWOT
		, PROFITMARGINWT = TOTALSALEPRICEWT - TOTALCOSTPRICEWT
		

	UPDATE #PROFITABILIY 
	SET PROFITMARGINPERWOT = (PROFITMARGINWOT / CASE WHEN ISNULL(TOTALSALEPRICEWOT, 0) = 0 THEN ABS(ISNULL(PROFITMARGINWOT, 1)) ELSE TOTALSALEPRICEWOT END) * 100
	WHERE PROFITMARGINWOT <> 0

	UPDATE #PROFITABILIY 
	SET PROFITMARGINPERWT = (PROFITMARGINWT / CASE WHEN ISNULL(TOTALSALEPRICEWT, 0) = 0 THEN ABS(ISNULL(PROFITMARGINWT, 1)) ELSE TOTALSALEPRICEWT END) * 100
	WHERE PROFITMARGINWT <> 0
	

	SELECT 
		CASE WHEN @BranchID = 0 AND @IncludeBranch = 0 THEN 'All' ELSE B.BRANCHNAME END AS BranchName
		, CAT.CATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME, IC.ITEMCODE, I.ITEMNAME, I.SKUCODE, GST.GSTCODE, IP.MRP, PT.SALEPRICE, PT.SALEPRICEWOT, PT.SALEPRICETAX, PT.ACTUALSALEPRICE
		, PT.COSTPRICEWOT 'Avg CP w/o Tax', PT.COSTPRICETAX 'Avg CP Tax', PT.COSTPRICEWT 'Avg CP with Tax', PT.SALEQUANTITY
		, PT.TOTALCOSTPRICEWOT, PT.TOTALCOSTPRICETAX, PT.TOTALCOSTPRICEWT
		, PT.TOTALSALEPRICEWOT, PT.TOTALSALETAX, PT.TOTALSALEPRICEWT
		, PT.PROFITMARGINWOT, PT.PROFITMARGINPERWOT, PT.PROFITMARGINWT, PT.PROFITMARGINPERWT
	FROM 
		#PROFITABILIY PT
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PT.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID
		LEFT JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN BRANCH B ON B.BRANCHID = PT.BRANCHID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	WHERE PT.SALEQUANTITY <> 0
	ORDER BY 1, 2, 3
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_PURCHASES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_PURCHASES]
(
	@FromDate DATE
	, @ToDate DATE
	, @DealerID INT = 0
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeSupplier BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeTax BIT = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(MAX)
	, @IncludeDiscount BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')

	CREATE TABLE #PROFITABILIY(ITEMCOSTPRICEID INT, SUPPLIERID INT, PURCHASEQUANTITY DECIMAL(11, 2), COSTPRICEWOT DECIMAL(14, 2)
		, COSTPRICEWT DECIMAL(14, 2), COSTPRICETAX DECIMAL(14, 2), TOTALCPEWOT DECIMAL(14, 2),TOTALCPWT DECIMAL(14, 2), 
		TOTALTAX DECIMAL(14, 2), FINALPRICE DECIMAL(18,2), PERIODOCITY DATETIME, CATEGORYID INT, SUBCATEGORYID INT
		, GSTID INT, SUPPLIERINVOICENO VARCHAR(30), DISCOUNTFLAT DECIMAL(14, 2), DISCOUNTPERCENTAGE DECIMAL(14, 2)
		, SCHEMEPERCENTAGE DECIMAL(14, 2), SCHEMEFLAT DECIMAL(14, 2), BRANDID INT, MANUFACTURERID INT)

	INSERT INTO #PROFITABILIY(ITEMCOSTPRICEID, SUPPLIERID, CATEGORYID,SUBCATEGORYID,PERIODOCITY,
				PURCHASEQUANTITY,COSTPRICEWOT,COSTPRICEWT,COSTPRICETAX,TOTALCPEWOT,TOTALCPWT,TOTALTAX,FINALPRICE, GSTID, SUPPLIERINVOICENO
				, DISCOUNTFLAT, DISCOUNTPERCENTAGE, SCHEMEFLAT, SCHEMEPERCENTAGE, BRANDID, MANUFACTURERID)

	SELECT CASE WHEN @IncludeItem = 1 THEN ITEMCOSTPRICEID ELSE NULL END
			, CASE WHEN @IncludeSupplier = 1 THEN SUPPLIERID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(UPDATEDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(UPDATEDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(UPDATEDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(UPDATEDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END,
		SUM(QUANTITY), 
		AVG(COSTPRICEWOT),
		AVG(COSTPRICEWT),
		AVG(COSTPRICEWT) - AVG(COSTPRICEWOT),
		SUM(TOTALPRICEWOT),
		SUM(TOTALPRICEWT),
		SUM(TOTALPRICEWT) - SUM(TOTALPRICEWOT),
		SUM(FINALPRICE)
		, CASE WHEN @IncludeTax = 1 THEN GSTID ELSE NULL END
		, CASE WHEN @IncludeSupplier = 1 THEN SUPPLIERINVOICENO ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN DISCOUNTFLAT ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN DISCOUNTPERCENTAGE ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN SCHEMEFLAT ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN SCHEMEPERCENTAGE ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	FROM 
		(
			SELECT ICP.ITEMCOSTPRICEID, 
				SE.SUPPLIERID,
				I.CATEGORYID, 
				I.SUBCATEGORYID, 
				I.BRANDID,
				I.MANUFACTURERID,
				CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SED.QUANTITY ELSE SED.WEIGHTINKGS END AS QUANTITY, 
				ICP.COSTPRICEWT,
				ICP.COSTPRICEWOT,
				SED.TOTALPRICEWOT,
				SED.TOTALPRICEWT,
				SED.FINALPRICE,
				SED.APPLIEDDGST, 
				SE.UPDATEDATE
				, ICP.GSTID
				, SE.SUPPLIERINVOICENO
				, SED.DISCOUNTFLAT, SED.DISCOUNTPERCENTAGE, SED.SCHEMEFLAT, SED.SCHEMEPERCENTAGE
			FROM STOCKENTRYDETAIL SED WITH(NOLOCK)
				INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
				INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
				INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = ICP.GSTID
				INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID 
				INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
			WHERE
				(I.ITEMID = @ITEMID OR @ITEMID = 0)
				AND (SE.SUPPLIERID = @DEALERID OR @DEALERID = 0)
				AND SE.UPDATEDATE > @FromDate
				AND SE.UPDATEDATE < @ToDate
				AND SED.DELETEDDATE IS NULL
				AND SE.STATUS = 1
		) AS BD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN ITEMCOSTPRICEID ELSE NULL END
		, CASE WHEN @IncludeSupplier = 1 THEN SUPPLIERID ELSE NULL END
		, CASE WHEN @IncludeSupplier = 1 THEN SUPPLIERINVOICENO ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(UPDATEDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(UPDATEDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(UPDATEDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(UPDATEDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeTax = 1 THEN GSTID ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN DISCOUNTFLAT ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN DISCOUNTPERCENTAGE ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN SCHEMEFLAT ELSE NULL END
		, CASE WHEN @IncludeDiscount = 1 THEN SCHEMEPERCENTAGE ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	SELECT 
		PT.PERIODOCITY, D.DEALERNAME, D.GSTIN, PT.SUPPLIERINVOICENO, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, IP.MRP, GST.GSTCODE, PT.COSTPRICEWOT, PT.COSTPRICEWT, PT.COSTPRICETAX, PT.PURCHASEQUANTITY
		, PT.TOTALCPEWOT, PT.TOTALCPWT, PT.TOTALTAX, pt.FINALPRICE, PT.DISCOUNTFLAT, PT.DISCOUNTPERCENTAGE, PT.SCHEMEFLAT, PT.SCHEMEPERCENTAGE
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMCOSTPRICE ICP ON PT.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		LEFT JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN TBLDEALER D ON PT.SUPPLIERID = D.DEALERID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4, 5, I.ITEMNAME, IC.ITEMCODE, IP.MRP, LEN(GST.GSTCODE), GST.GSTCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_PURCHASES_VS_SALES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_PURCHASES_VS_SALES]
(
	@FromDate DATE
	, @ToDate DATE
	, @DealerID INT = 0
	, @IncludeItem BIT = 0
	, @IncludeItemPriceDetails BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @CategoryID VARCHAR(MAX)
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')

	CREATE TABLE #PROFITABILIY(SUPPLIERID INT, PURCHASEQUANTITY DECIMAL(11, 2), AVGCOSTPRICEWOT DECIMAL(14, 2), AVGCOSTPRICEWT DECIMAL(14, 2)
		, AVGCOSTPRICETAX DECIMAL(14, 2), TOTALCPWOT DECIMAL(14, 2),TOTALCPWT DECIMAL(14, 2), TOTALCOSTPRICETAX DECIMAL(14, 2)
		, TOTALFINALCOSTPRICE DECIMAL(18,2), CATEGORYID INT, SUBCATEGORYID INT, GSTID INT, BRANDID INT, MANUFACTURERID INT, ITEMCODEID INT
		, ITEMID INT, SALEQUANTITY DECIMAL(14, 2), TOTALSALEPRICEWOT DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2), MRP DECIMAL(18, 2))

	CREATE TABLE #SED(ITEMID INT, ITEMCODEID INT, MRP DECIMAL(18, 2), SUPPLIERID INT, PURCHASEQUANTITY DECIMAL(18, 2)
		, AVGCOSTPRICEWT DECIMAL(18, 2), AVGCOSTPRICEWOT DECIMAL(18, 2), TOTALCOSTPRICEWOT DECIMAL(18, 2)
		, TOTALCOSTPRICEWT DECIMAL(18, 2), TOTALFINALCOSTPRICE DECIMAL(18, 2), APPLIEDDGST DECIMAL(18, 2), TRANSACTIONDATE DATETIME
		, GSTID INT, SALEQUANTITY DECIMAL(18, 2), TOTALSALEPRICEWOT DECIMAL(18, 2), TOTALSALEPRICEWT DECIMAL(18, 2))

	INSERT INTO #SED(ITEMID, ITEMCODEID, MRP, SUPPLIERID, PURCHASEQUANTITY, AVGCOSTPRICEWT, AVGCOSTPRICEWOT, TOTALCOSTPRICEWOT
		, TOTALCOSTPRICEWT, TOTALFINALCOSTPRICE, APPLIEDDGST, GSTID, SALEQUANTITY, TOTALSALEPRICEWOT, TOTALSALEPRICEWT)
	SELECT 
		I.ITEMID, IC.ITEMCODEID, IP.MRP, SE.SUPPLIERID, SUM(CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SED.QUANTITY ELSE SED.WEIGHTINKGS END), 
		SUM(ICP.COSTPRICEWT * (CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END))
			/ SUM(CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END)
		, SUM(ICP.COSTPRICEWOT * (CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END))
			/ SUM(CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END)
		, SUM(SED.TOTALPRICEWOT), SUM(SED.TOTALPRICEWT), SUM(SED.FINALPRICE), SUM(SED.APPLIEDDGST)
		, ICP.GSTID, 0, 0, 0
	FROM STOCKENTRYDETAIL SED
		INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = ICP.GSTID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
	WHERE
		(SE.SUPPLIERID = @DEALERID OR @DEALERID = 0)
		AND SE.CREATEDDATE > @FromDate
		AND SE.CREATEDDATE < @ToDate
		AND SED.DELETEDDATE IS NULL
		AND SE.STATUS = 1
	GROUP BY I.ITEMID, IC.ITEMCODEID, IP.MRP, SUPPLIERID, ICP.GSTID, I.ISOPENITEM

	INSERT INTO #SED(ITEMID, ITEMCODEID, MRP, SUPPLIERID, PURCHASEQUANTITY, AVGCOSTPRICEWT, AVGCOSTPRICEWOT, TOTALCOSTPRICEWOT
		, TOTALCOSTPRICEWT, TOTALFINALCOSTPRICE, APPLIEDDGST, GSTID, SALEQUANTITY, TOTALSALEPRICEWOT, TOTALSALEPRICEWT)
	SELECT I.ITEMID, IC.ITEMCODEID, IP.MRP, ISM.SUPPLIERID, 0, 0, 0, 0, 0, 0, 0, IP.GSTID, 0, 0, 0
	FROM ITEMSUPPLIERMAP ISM WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ISM.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
	WHERE
		(ISM.SUPPLIERID = @DEALERID OR @DEALERID = 0)
		AND NOT EXISTS
			(
				SELECT 1 
				FROM #SED SED
				WHERE
					SED.ITEMID = I.ITEMID
					AND SED.ITEMCODEID = IC.ITEMCODEID
					AND SED.MRP = IP.MRP
					AND SED.SUPPLIERID = ISM.SUPPLIERID
					AND SED.GSTID = IP.GSTID
			)
	GROUP BY I.ITEMID, IC.ITEMCODEID, IP.MRP,  SUPPLIERID, IP.GSTID

	UPDATE SED
	SET SED.SALEQUANTITY = BILL.SALEQUANTITY, SED.TOTALSALEPRICEWT = BILL.BILLEDAMOUNT
		, SED.TOTALSALEPRICEWOT = BILL.BILLEDAMOUNT - BILL.GSTVALUE
	FROM
		#SED SED
		INNER JOIN 
			(
				SELECT I.ITEMID, IC.ITEMCODEID, IP.MRP, SUM(PBD.BILLEDAMOUNT) BILLEDAMOUNT, SUM(PBD.GSTVALUE) GSTVALUE
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END) SALEQUANTITY
				FROM
					POS_BILLDETAIL PBD WITH(NOLOCK)
					INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
					INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
				WHERE
					PBD.DELETEDDATE IS NULL
					AND PB.CREATEDDATE > @FromDate
					AND PB.CREATEDDATE < @ToDate
					AND PB.BILLSTATUS = 1
				GROUP BY I.ITEMID, IC.ITEMCODEID, IP.MRP
			) BILL ON BILL.ITEMID = SED.ITEMID AND BILL.ITEMCODEID = SED.ITEMCODEID AND BILL.MRP = SED.MRP

	UPDATE SED
	SET SED.SALEQUANTITY = SED.SALEQUANTITY - BILL.REFUNDQUANTITY
		, SED.TOTALSALEPRICEWT = SED.TOTALSALEPRICEWT  - BILL.REFUNDAMOUNT
		, SED.TOTALSALEPRICEWOT = SED.TOTALSALEPRICEWOT - BILL.REFUNDGSTVALUE
	FROM
		#SED SED
		INNER JOIN 
			(
				SELECT I.ITEMID, IC.ITEMCODEID, IP.MRP, SUM(CREF.REFUNDAMOUNT) REFUNDAMOUNT
					, SUM((PBD.GSTVALUE / (CASE WHEN I.ISOPENITEM = 1 THEN PBD.WEIGHTINKGS ELSE PBD.QUANTITY END)) * 
						(CASE WHEN I.ISOPENITEM = 1 THEN CREF.REFUNDWEIGHTINKGS ELSE CREF.REFUNDQUANTITY END)) REFUNDGSTVALUE
					, SUM(CASE WHEN I.ISOPENITEM = 1 THEN CREF.REFUNDWEIGHTINKGS ELSE CREF.REFUNDQUANTITY END) REFUNDQUANTITY
				FROM
					POS_CREFUND CREF WITH(NOLOCK)
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREF.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREF.COUNTERID
					INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
					INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
				WHERE
					PBD.DELETEDDATE IS NULL
					AND CREF.CREATEDDATE > @FromDate
					AND CREF.CREATEDDATE < @ToDate
				GROUP BY I.ITEMID, IC.ITEMCODEID, IP.MRP, I.ISOPENITEM
			) BILL ON BILL.ITEMID = SED.ITEMID AND BILL.ITEMCODEID = SED.ITEMCODEID AND BILL.MRP = SED.MRP

	DELETE SED FROM #SED SED WHERE PURCHASEQUANTITY = 0 AND SALEQUANTITY = 0

	INSERT INTO #PROFITABILIY(ITEMID, MRP, ITEMCODEID, CATEGORYID, SUBCATEGORYID, BRANDID, MANUFACTURERID, SUPPLIERID
		, PURCHASEQUANTITY, AVGCOSTPRICEWOT, AVGCOSTPRICEWT, AVGCOSTPRICETAX, TOTALCPWOT, TOTALCPWT, TOTALCOSTPRICETAX
		, TOTALFINALCOSTPRICE, SALEQUANTITY, TOTALSALEPRICEWOT, TOTALSALEPRICEWT)
	SELECT 
		CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END
		, CASE WHEN @IncludeItemPriceDetails = 1 THEN MRP ELSE NULL END
		, CASE WHEN @IncludeItemPriceDetails = 1 THEN ITEMCODEID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
		, BD.SUPPLIERID, SUM(PURCHASEQUANTITY), SUM(AVGCOSTPRICEWOT), SUM(AVGCOSTPRICEWT), SUM(AVGCOSTPRICEWT - AVGCOSTPRICEWOT)
		, SUM(TOTALCOSTPRICEWOT), SUM(TOTALCOSTPRICEWT), SUM(TOTALCOSTPRICEWT - TOTALCOSTPRICEWOT), SUM(TOTALFINALCOSTPRICE)
		, SUM(SALEQUANTITY), SUM(TOTALSALEPRICEWOT), SUM(TOTALSALEPRICEWT)
	FROM 
		(
			SELECT 
				SED.SUPPLIERID, I.CATEGORYID, I.SUBCATEGORYID, I.BRANDID, I.MANUFACTURERID, SED.PURCHASEQUANTITY, 
				SED.AVGCOSTPRICEWT, SED.AVGCOSTPRICEWOT, SED.TOTALCOSTPRICEWOT, SED.TOTALCOSTPRICEWT, SED.TOTALFINALCOSTPRICE,
				SED.APPLIEDDGST, SED.GSTID, SED.SALEQUANTITY, SED.TOTALSALEPRICEWOT, SED.TOTALSALEPRICEWT, I.ITEMID, SED.MRP
				, SED.ITEMCODEID
			FROM 
				#SED SED
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SED.ITEMID				
		) AS BD
	GROUP BY 
		 CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END
		 , CASE WHEN @IncludeItemPriceDetails = 1 THEN MRP ELSE NULL END
		 , CASE WHEN @IncludeItemPriceDetails = 1 THEN ITEMCODEID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
		, BD.SUPPLIERID

	SELECT 
		D.DEALERNAME, D.GSTIN, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, PT.MRP, PT.AVGCOSTPRICEWOT, PT.AVGCOSTPRICETAX, PT.AVGCOSTPRICEWT, PT.PURCHASEQUANTITY, PT.TOTALCPWOT, PT.TOTALCOSTPRICETAX
		, PT.TOTALCPWT, PT.TOTALFINALCOSTPRICE, PT.SALEQUANTITY, PT.TOTALSALEPRICEWOT, PT.TOTALSALEPRICEWT
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = PT.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = PT.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN TBLDEALER D ON PT.SUPPLIERID = D.DEALERID
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 3, 4, 5, 6, I.ITEMNAME, IC.ITEMCODE, PT.MRP
	
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_RUNNINGSALE]    Script Date: 17-10-2026 13:04:47 ******/
