CREATE PROCEDURE [dbo].[USP_RPT_RUNNINGSALE]  
@BranchID VARCHAR(500)
,@IncludeBranch bit = 0
,@IncludeCounter bit = 0
,@IncludeBillNo bit = 0
,@IncludeCategory bit = 0
,@IncludeItem bit = 0
AS  
BEGIN  

  SELECT 
  B.BRANCHNAME
  ,BC.COUNTERNAME
  ,BD.BILLNUMBER
  ,I.SKUCODE
  ,IC.ITEMCODE
  ,I.ITEMNAME
  ,C.CATEGORYNAME
  ,IP.MRP,
  IP.SALEPRICE
  ,BD.QUANTITY
  ,BD.WEIGHTINKGS
  ,BD.BILLEDAMOUNT
  FROM 
  (
SELECT 
CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END AS BRANCHID, 
CASE WHEN @IncludeCounter = 1 THEN BC.COUNTERID ELSE NULL END AS COUNTERID, 
CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END AS CATEGORYID, 
CASE WHEN @IncludeBillNo = 1 THEN PB.BILLNUMBER ELSE NULL END AS BILLNUMBER,
CASE WHEN @IncludeItem = 1 THEN BD.ITEMPRICEID ELSE NULL END AS ITEMPRICEID,
CASE WHEN @IncludeItem = 1 THEN SUM(BD.QUANTITY) ELSE NULL END AS QUANTITY,
CASE WHEN @IncludeItem = 1 THEN SUM(BD.WEIGHTINKGS) ELSE NULL END  AS WEIGHTINKGS, 
SUM(BD.BILLEDAMOUNT) AS BILLEDAMOUNT
 FROM  
  POS_BILL PB  
	INNER JOIN POS_BILLDETAIL BD ON BD.BILLID = PB.BILLID AND PB.BRANCHCOUNTERID = BD.BRANCHCOUNTERID  
	INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BD.ITEMPRICEID  
	INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID  
	INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID  
	INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
	INNER JOIN dbo.SplitString(@BranchID,',') B ON BC.BRANCHID = B.ITEM
 WHERE PB.DAYCLOSUREID IS NULL AND PB.DELETEDDATE IS NULL AND BD.DELETEDDATE IS NULL
 AND PB.BILLSTATUS = 1
 GROUP BY 
	CASE WHEN @IncludeBranch = 1 THEN BC.BRANCHID ELSE NULL END,
	CASE WHEN @IncludeCounter = 1 THEN BC.COUNTERID ELSE NULL END,
	CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END,
	CASE WHEN @IncludeItem = 1 THEN BD.ITEMPRICEID ELSE NULL END,
	CASE WHEN @IncludeBillNo = 1 THEN PB.BILLNUMBER ELSE NULL END
) BD
	LEFT JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BD.ITEMPRICEID  
	LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID  
	LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID  
	LEFT JOIN TBLCATEGORY C ON BD.CATEGORYID = C.CATEGORYID
	LEFT JOIN BRANCHCOUNTER BC ON BC.COUNTERID = BD.COUNTERID
	LEFT JOIN BRANCH B ON B.BRANCHID = BD.BRANCHID  
 
 
 --SELECT 
	--B.BRANCHNAME, BC.COUNTERNAME, PB.BILLNUMBER, BD.SNO
	----, B.BRANCHCODE, BD.WEIGHTINKGS, GST.GSTCODE, BD.GSTVALUE, BD.DISCOUNT	
	----CASE WHEN PB.BILLSTATUS = 0 THEN 'Open' WHEN PB.BILLSTATUS = 1 THEN 'Closed' WHEN PB.BILLSTATUS = 2 
	----THEN 'Draft' ELSE 'Unknown' END AS BILLSTATUS,  I.SKUCODE
	--, IC.ITEMCODE, I.ITEMNAME, IP.MRP, IP.SALEPRICE, BD.QUANTITY, BD.BILLEDAMOUNT  
 --FROM  
 -- POS_BILL PB  
 -- INNER JOIN POS_BILLDETAIL BD ON BD.BILLID = PB.BILLID AND PB.BRANCHCOUNTERID = BD.BRANCHCOUNTERID  
 -- INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BD.ITEMPRICEID  
 -- INNER JOIN GSTDETAIL GST ON GST.GSTID = BD.GSTID  
 -- INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID  
 -- INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID  
 -- INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID  
 -- INNER JOIN BRANCH B ON B.BRANCHID = BC.BRANCHID  
 --WHERE PB.DAYCLOSUREID IS NULL AND BD.DAYCLOSUREID IS NULL AND PB.DELETEDDATE IS NULL AND BD.DELETEDDATE IS NULL  
 --AND (B.BRANCHID = @BranchID OR @BranchID = 0)  and PB.BILLSTATUS = 1
 --ORDER BY B.BRANCHNAME, B.BRANCHCODE, BC.COUNTERNAME, PB.BILLNUMBER, BD.SNO  
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SALE_HOURWISE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SALE_HOURWISE]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID INT = 0
	, @CategoryID INT = 0
)
AS
BEGIN
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT 
		FORMAT(PBD.CREATEDDATE, 'HH:00') [TIME], SUM(PBD.BILLEDAMOUNT) - SUM(PBD.GSTVALUE) AS SALEPRICEWOT
		, SUM(PBD.GSTVALUE) AS SALETAX, SUM(PBD.BILLEDAMOUNT) AS SALEPRICEWT
		, CASE WHEN @CategoryID = 0 OR @CategoryID = 13 THEN 'All' ELSE CAT.CATEGORYNAME END AS CATEGORYNAME
		, CASE WHEN @CategoryID = 0 OR @CategoryID = 13 THEN 'All' ELSE SUBCAT.SUBCATEGORYNAME END AS SUBCATEGORYNAME
		,BR.BRANDNAME, MAN.MANUFACTURERNAME
		, CASE WHEN @BranchID = 0 THEN 'All' ELSE B.BRANCHNAME END AS BRANCHNAME
	FROM
		POS_BILLDETAIL PBD 
		INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCH B ON B.BRANCHID = BC.BRANCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN TBLBRAND BR ON I.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON I.MANUFACTURERID = MAN.MANUFACTURERID
	WHERE
		(BC.BRANCHID = @BranchID OR @BranchID = 0)
		AND (I.CATEGORYID = @CategoryID OR @CategoryID = 0 OR @CategoryID = 13)
		AND PBD.CREATEDDATE > (@FromDate)
		AND PBD.CREATEDDATE < @ToDate
		AND PBD.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1
	GROUP BY 
		FORMAT(PBD.CREATEDDATE, 'HH:00')
		, CASE WHEN @CategoryID = 0 OR @CategoryID = 13 THEN 'All' ELSE CAT.CATEGORYNAME END
		, CASE WHEN @CategoryID = 0 OR @CategoryID = 13 THEN 'All' ELSE SUBCAT.SUBCATEGORYNAME END
		, CASE WHEN @BranchID = 0 THEN 'All' ELSE B.BRANCHNAME END
		,BR.BRANDNAME, MAN.MANUFACTURERNAME
		 
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SALE_PERIODICITY_ITEMWISE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SALE_PERIODICITY_ITEMWISE]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID INT = 0
	, @Periodicity VARCHAR(20)
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, GSTID INT, MRP DECIMAL(7, 2), SALEQUANTITY DECIMAL(11, 2)
		, SALEPRICE DECIMAL(7, 2), SALEPRICEWOT DECIMAL(7, 2), SALEPRICETAX DECIMAL(7, 2), PERIODOCITY DATETIME, TOTALSALEPRICEWOT DECIMAL(14, 2), TOTALSALETAX DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2))

	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, MRP, SALEPRICE, GSTID, TOTALSALEPRICEWT, TOTALSALETAX, SALEQUANTITY, PERIODOCITY)
	SELECT 
		IP.ITEMPRICEID, CASE WHEN @BranchID = 0 THEN 0 ELSE BC.BRANCHID END
		, IP.MRP, IP.SALEPRICE, PBD.GSTID, SUM(PBD.BILLEDAMOUNT), SUM(PBD.GSTVALUE)
		, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SUM(PBD.QUANTITY) ELSE SUM(PBD.WEIGHTINKGS) END
		, CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(PBD.CREATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(PBD.CREATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(PBD.CREATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(PBD.CREATEDDATE, '1900-01-01 HH:00')
		  END AS DATETIME)
	FROM 
		ITEMPRICE IP 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN POS_BILLDETAIL PBD ON PBD.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
	WHERE
		(BC.BRANCHID = @BranchID OR @BranchID = 0)
		AND PBD.CREATEDDATE > (@FromDate)
		AND PBD.CREATEDDATE < @ToDate
		AND PBD.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1
	GROUP BY 
		IP.ITEMPRICEID, CASE WHEN @BranchID = 0 THEN 0 ELSE BC.BRANCHID END
		, IP.MRP, IP.SALEPRICE, I.ISOPENITEM, PBD.GSTID
		, CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(PBD.CREATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(PBD.CREATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(PBD.CREATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(PBD.CREATEDDATE, '1900-01-01 HH:00')
		  END AS DATETIME)

	UPDATE PT
	SET SALEPRICETAX = ROUND(PT.SALEPRICE -((PT.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100), 2)
	FROM 
		#PROFITABILIY PT
		INNER JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID

	UPDATE PT
	SET 
		SALEPRICEWOT = SALEPRICE - SALEPRICETAX
		, PT.TOTALSALEPRICEWOT = PT.TOTALSALEPRICEWT - PT.TOTALSALETAX
	FROM #PROFITABILIY PT

	SELECT 
		PT.PERIODOCITY
		, CASE WHEN @BranchID = 0 THEN 'All' ELSE B.BRANCHNAME END AS BRANCHNAME
		, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, PT.MRP, PT.SALEPRICEWOT, PT.SALEPRICETAX, PT.SALEPRICE, PT.SALEQUANTITY
		, SUM(PT.TOTALSALEPRICEWOT) TOTALSALEPRICEWOT, SUM(PT.TOTALSALETAX) TOTALSALETAX, SUM(PT.TOTALSALEPRICEWT) TOTALSALEPRICEWT		
	FROM 
		#PROFITABILIY PT
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PT.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN BRANCH B ON B.BRANCHID = PT.BRANCHID
	GROUP BY PT.PERIODOCITY
		, CASE WHEN @BranchID = 0 THEN 'All' ELSE B.BRANCHNAME END
		, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, PT.MRP, PT.SALEPRICEWOT, PT.SALEPRICETAX, PT.SALEPRICE, PT.SALEQUANTITY
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SALES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
