CREATE PROC [dbo].[USP_RPT_SALES]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(500)
	, @Periodicity VARCHAR(20)
	, @UnmaskCustomerPhone BIT = 0
	, @IncludeItem BIT = 0
	, @IncludeItemPrice BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCounter BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0
	, @IncludeStock BIT = 0
	, @IncludeOffer BIT = 0
	, @IncludeTax BIT = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(500) 
	, @IncludeBillDetails BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN

	--;THROW 50001, 'Sales report is temporarily disabled', 16;
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	DECLARE @DateSuffixInYear VARCHAR(15)

	SELECT @DateSuffixInYear = 
			'-' + CASE 
					WHEN @Periodicity = 'Yearly' THEN '01'
					WHEN @Periodicity = 'Fin. Yearly' THEN '04'
					ELSE NULL END 
			+ '-01 00:00:00'

	IF @IncludeStock = 1
	BEGIN
		SET @IncludeItem = 1
		--SET @IncludeBranch = 1
	END

	CREATE TABLE #BD(ITEMPRICEID INT, BRANCHID INT, COUNTERID INT, CATEGORYID INT, SUBCATEGORYID INT, BRANDID INT, MANUFACTURERID INT, BILLEDAMOUNT DECIMAL(14, 2), GSTVALUE DECIMAL(14, 2)
		, QUANTITY DECIMAL(14, 2), CREATEDDATE DATETIME, CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT, ITEMID INT, GSTID INT, ISOFFER BIT
		, OFFERID INT, CREATEDBY INT, BILLNUMBER VARCHAR(30), ISDOORDELIVERY BIT, CUSTOMERNAME VARCHAR(100), CUSTOMERNUMBER VARCHAR(10), CUSTOMERGST VARCHAR(100), ISIGSTBILL BIT DEFAULT 0)

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, COUNTERID INT, SALEQUANTITY DECIMAL(11, 2), SALEPRICE DECIMAL(14, 2)
		, SALEPRICEWOT DECIMAL(14, 2), SALEPRICETAX DECIMAL(14, 2), PERIODOCITY DATETIME, TOTALSALEPRICEWOT DECIMAL(14, 2)
		, TOTALSALETAX DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2), CATEGORYID INT, SUBCATEGORYID INT, BRANDID INT, MANUFACTURERID INT, BILLNUMBER VARCHAR(30)
		, CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT, ITEMID INT, ISOFFER BIT, WHSTOCK INT, BRANCHSTOCK INT, GSTID INT, OFFERID INT
		, CREATEDBY INT, CREATEDTIME TIME, ISDOORDELIVERY VARCHAR(5), CUSTOMERNAME VARCHAR(100), CUSTOMERNUMBER VARCHAR(10), CUSTOMERGST VARCHAR(100), ISIGSTBILL BIT DEFAULT 0)
	
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	
	INSERT INTO #BD
	SELECT IP.ITEMPRICEID, 
		BC.BRANCHID, 
		BC.COUNTERID,
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		I.BRANDID,
		I.MANUFACTURERID,
		PBD.BILLEDAMOUNT, 
		PBD.GSTVALUE, 
		CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END AS QUANTITY, 
		PBD.CREATEDDATE, I.CLASSIFICATIONID, I.SUBCLASSIFICATIONID, I.ITEMID, PBD.GSTID
		, CASE WHEN PBD.OFFERID IS NOT NULL THEN 1 ELSE 0 END ISOFFER, PBD.OFFERID, PB.CREATEDBY, PB.BILLNUMBER
		, PB.ISDOORDELIVERY, PB.CUSTOMERNAME, PB.CUSTOMERNUMBER, PB.CUSTOMERGST, PB.ISIGSTBILL
	FROM POS_BILLDETAIL PBD WITH(NOLOCK)
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		--AND (I.CATEGORYID = @CategoryID OR @CategoryID = 13)
		AND PBD.CREATEDDATE > (@FromDate)
		AND PBD.CREATEDDATE < @ToDate
		AND PBD.DELETEDDATE IS NULL
		AND PB.BILLSTATUS = 1

	INSERT INTO #BD
	SELECT IP.ITEMPRICEID
		, BC.BRANCHID
		, BC.COUNTERID
		, I.CATEGORYID
		, I.SUBCATEGORYID
		, I.BRANDID
		, I.MANUFACTURERID
		, - CR.REFUNDAMOUNT
		, - PBD.GSTVALUE
		, - CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS QUANTITY
		, CR.CREATEDDATE, I.CLASSIFICATIONID, I.SUBCLASSIFICATIONID, I.ITEMID, PBD.GSTID
		, 0, NULL, CR.CREATEDBY, PB.BILLNUMBER, PB.ISDOORDELIVERY, PB.CUSTOMERNAME, PB.CUSTOMERNUMBER, PB.CUSTOMERGST, PB.ISIGSTBILL
	FROM POS_CREFUND CR WITH(NOLOCK) 
		INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON CR.BILLDETAILID = PBD.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON PBD.ITEMPRICEID = IP.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		--AND (I.CATEGORYID = @CategoryID OR @CategoryID = 13)
		AND CR.CREATEDDATE > (@FromDate)
		AND CR.CREATEDDATE < @ToDate

	INSERT INTO #PROFITABILIY(
		ITEMPRICEID, BRANCHID, COUNTERID, CATEGORYID, SUBCATEGORYID, PERIODOCITY, SALEQUANTITY, TOTALSALEPRICEWT, TOTALSALETAX
		, CLASSIFICATIONID, SUBCLASSIFICATIONID, ITEMID, GSTID, ISOFFER, OFFERID, CREATEDBY, BILLNUMBER, CREATEDTIME
		, ISDOORDELIVERY, CUSTOMERNAME, CUSTOMERNUMBER, CUSTOMERGST, ISIGSTBILL, BRANDID, MANUFACTURERID)
	SELECT CASE WHEN @IncludeItemPrice = 1 THEN ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCounter = 1 THEN COUNTERID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
				WHEN @Periodicity = 'Fin. Yearly' THEN CAST((CAST(YEAR(CREATEDDATE) - CASE WHEN MONTH(CREATEDDATE) < 4 THEN 1 ELSE 0 END AS VARCHAR(4)) + @DateSuffixInYear) AS DATETIME)
				END AS DATETIME) ELSE NULL END		
			, SUM(QUANTITY) AS QUANTITY 
			, SUM(BILLEDAMOUNT) AS BILLEDAMOUNT
			, SUM(GSTVALUE) AS GSTVALUE
			, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END
			, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END
			, CASE WHEN @IncludeTax = 1 THEN GSTID ELSE NULL END
			, CASE WHEN @IncludeOffer = 1 THEN ISOFFER ELSE NULL END
			, CASE WHEN @IncludeOffer = 1 THEN OFFERID ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CREATEDBY ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN BILLNUMBER ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CAST(CREATEDDATE AS TIME) ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN (CASE WHEN ISDOORDELIVERY = 1 THEN 'Yes' ELSE 'No' END) ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNAME ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNUMBER ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERGST ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN ISIGSTBILL ELSE NULL END
			, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	FROM #BD BD
	GROUP BY 
		CASE WHEN @IncludeItemPrice = 1 THEN ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCounter = 1 THEN COUNTERID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(CREATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(CREATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(CREATEDDATE, '1900-01-01 HH:00')
			WHEN @Periodicity = 'Fin. Yearly' THEN CAST((CAST(YEAR(CREATEDDATE) - CASE WHEN MONTH(CREATEDDATE) < 4 THEN 1 ELSE 0 END AS VARCHAR(4)) + @DateSuffixInYear) AS DATETIME)
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END
		, CASE WHEN @IncludeTax = 1 THEN GSTID ELSE NULL END
		, CASE WHEN @IncludeOffer = 1 THEN ISOFFER ELSE NULL END
		, CASE WHEN @IncludeOffer = 1 THEN OFFERID ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CREATEDBY ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN BILLNUMBER ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CAST(CREATEDDATE AS TIME) ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN (CASE WHEN ISDOORDELIVERY = 1 THEN 'Yes' ELSE 'No' END) ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNAME ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNUMBER ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERGST ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN ISIGSTBILL ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	UPDATE PT
	SET SALEPRICETAX = ROUND(IP.SALEPRICE -((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100), 2)
		, SALEPRICE = IP.SALEPRICE
	FROM 
		#PROFITABILIY PT
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PT.ITEMPRICEID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID

	UPDATE PT
	SET 
		SALEPRICEWOT = SALEPRICE - SALEPRICETAX
		, PT.TOTALSALEPRICEWOT = PT.TOTALSALEPRICEWT - PT.TOTALSALETAX
	FROM #PROFITABILIY PT

	IF @IncludeStock = 1
	BEGIN
		
		UPDATE PT
		SET PT.WHSTOCK = SSWH.WHQUANTITY, PT.BRANCHSTOCK = SSB.BQUANTITY
		FROM 
			#PROFITABILIY PT			
			LEFT JOIN
				(
					SELECT I.ITEMID, CASE WHEN I.ISOPENITEM = 1 THEN CAST(SUM(SSWH.WEIGHTINKGS) AS INT) ELSE SUM(SSWH.QUANTITY) END WHQUANTITY
					FROM 
						ITEMPRICE IP WITH(NOLOCK) 
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
						INNER JOIN STOCKSUMMARY SSWH WITH(NOLOCK) ON SSWH.ITEMPRICEID = IP.ITEMPRICEID AND SSWH.BRANCHID = 45
						--INNER JOIN STOCKSUMMARY SSBWH WITH(NOLOCK) ON SSBWH.ITEMPRICEID = IP.ITEMPRICEID AND SSBWH.BRANCHID = 97									
					GROUP BY I.ITEMID, I.ISOPENITEM
				) SSWH ON PT.ITEMID = SSWH.ITEMID
			LEFT JOIN 
				(
					SELECT I.ITEMID, CASE WHEN @IncludeBranch = 1 THEN SSBINNER.BRANCHID ELSE NULL END BRANCHID, SUM(SSBINNER.QUANTITY) BQUANTITY
					FROM 
						ITEMPRICE IP WITH(NOLOCK) 
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
						INNER JOIN STOCKSUMMARY SSBINNER WITH(NOLOCK) ON SSBINNER.ITEMPRICEID = IP.ITEMPRICEID 
						INNER JOIN #BRANCH B ON B.Item = SSBINNER.BRANCHID
					WHERE SSBINNER.BRANCHID <> 45
					GROUP BY I.ITEMID, CASE WHEN @IncludeBranch = 1 THEN SSBINNER.BRANCHID ELSE NULL END				
				) SSB ON PT.ITEMID = SSB.ITEMID AND ISNULL(PT.BRANCHID, 0) = CASE WHEN @IncludeBranch = 1 THEN SSB.BRANCHID ELSE ISNULL(PT.BRANCHID, 0) END

		--UPDATE PT 
		--SET PT.ISOFFER = 1
		--FROM #PROFITABILIY PT
		--WHERE EXISTS
		--	(
		--		SELECT 1 
		--		FROM 
		--			POS_BILLDETAIL PBD WITH(NOLOCK) 
		--			INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		--			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		--			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID					
		--			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID
		--		WHERE 
		--			IC.ITEMID = PT.ITEMID 
		--			AND BC.BRANCHID = PT.BRANCHID 
		--			AND PB.BILLSTATUS = 1 
		--			AND PBD.DELETEDDATE IS NULL
		--			AND PB.CREATEDDATE >= @FromDate
		--			AND PB.CREATEDDATE <= @ToDate
		--			AND PBD.OFFERID IS NOT NULL
		--	)			

	END

	UPDATE #PROFITABILIY
	SET CUSTOMERNUMBER = 'XXXXXX' + RIGHT(CUSTOMERNUMBER, 4)
	WHERE CUSTOMERNUMBER IS NOT NULL AND @UnmaskCustomerPhone = 0

	SELECT 
		PT.PERIODOCITY, B.BRANCHNAME, BC.COUNTERNAME, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME, BR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.VENDORSKUCODE, I.ITEMNAME, IC.ITEMCODE, IC.HSNCODE
		, IP.MRP, GST.GSTCODE, UQC.UQCCODE, PT.SALEPRICEWOT, PT.SALEPRICETAX, PT.SALEPRICE, PT.SALEQUANTITY
		, PT.TOTALSALEPRICEWOT, PT.TOTALSALETAX, PT.TOTALSALEPRICEWT, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME
		, CASE WHEN PT.ISOFFER = 1 THEN 'Yes' ELSE 'No' END AS ISOFFER
		, OFR.OFFERCODE, BOFR.OFFERCODE BASEOFFERCODE, PT.WHSTOCK, PT.BRANCHSTOCK
		, USR.FULLNAME BILLCREATEDBY, PT.BILLNUMBER, PT.CREATEDTIME, PT.ISDOORDELIVERY, PT.CUSTOMERNAME, PT.CUSTOMERNUMBER, PT.CUSTOMERGST
		, CASE WHEN PT.ISIGSTBILL = 1 THEN 'Yes' ELSE 'No' END IsIGSTBill
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = PT.ITEMID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC WITH(NOLOCK) ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON PT.COUNTERID = BC.COUNTERID
		LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = PT.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS WITH(NOLOCK) ON ISCLS.SUBCLASSIFICATIONID = PT.SUBCLASSIFICATIONID
		LEFT JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PT.GSTID
		LEFT JOIN OFFER OFR WITH(NOLOCK) ON OFR.OFFERID = PT.OFFERID
		LEFT JOIN BASEOFFER BOFR WITH(NOLOCK) ON BOFR.BASEOFFERID = OFR.BASEOFFERID
		LEFT JOIN TBLUSER USR WITH(NOLOCK) ON USR.USERID = PT.CREATEDBY
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
		LEFT JOIN UQCDATA UQC ON UQC.UQCID = I.UQCID
	ORDER BY 1, 2, 3, 4, I.ITEMNAME, IC.ITEMCODE, IP.MRP, LEN(GSTCODE), GSTCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SALES_COMPARISION]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SALES_COMPARISION]
(
	@FromDate DATETIME
	, @ToDate DATETIME
	, @BranchID VARCHAR(500)	
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCounter BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0	
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(ss, -1, DATEADD(d, 1, @ToDate))

	CREATE TABLE #SALES(ITEMPRICEID INT, BRANCHID INT, COUNTERID INT, SALEQUANTITY DECIMAL(11, 2), SALEPRICE DECIMAL(14, 2)
		, SALEPRICEWOT DECIMAL(14, 2), SALEPRICETAX DECIMAL(14, 2), PERIODOCITY DATETIME, TOTALSALEPRICEWOT DECIMAL(14, 2)
		, TOTALSALETAX DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2), CATEGORYID INT, SUBCATEGORYID INT, BILLNUMBER VARCHAR(30)
		, CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT, ITEMID INT, ISOFFER BIT, WHSTOCK INT, BRANCHSTOCK INT, GSTID INT)

	INSERT INTO #SALES(ITEMPRICEID, BRANCHID, COUNTERID, CATEGORYID, SUBCATEGORYID, PERIODOCITY, SALEQUANTITY, TOTALSALEPRICEWT, TOTALSALETAX
		, CLASSIFICATIONID, SUBCLASSIFICATIONID, ITEMID)
	SELECT CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCounter = 1 THEN COUNTERID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00') ELSE NULL END		
			, SUM(QUANTITY) AS QUANTITY 
			, SUM(BILLEDAMOUNT) AS BILLEDAMOUNT
			, SUM(GSTVALUE) AS GSTVALUE
			, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END
			, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END

	FROM 
		(
			SELECT IP.ITEMPRICEID, 
				BC.BRANCHID, 
				BC.COUNTERID,
				I.CATEGORYID, 
				I.SUBCATEGORYID, 
				PBD.BILLEDAMOUNT, 
				PBD.GSTVALUE, 
				CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END AS QUANTITY, 
				PBD.CREATEDDATE, I.CLASSIFICATIONID, I.SUBCLASSIFICATIONID, I.ITEMID, PBD.GSTID

			FROM POS_BILLDETAIL PBD 
				INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN dbo.SplitString(@BranchID,',') B ON BC.BRANCHID = B.ITEM
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			WHERE PBD.CREATEDDATE > (@FromDate)
				AND PBD.CREATEDDATE < @ToDate
				AND PBD.DELETEDDATE IS NULL
				AND PB.BILLSTATUS = 1

			UNION ALL

			SELECT IP.ITEMPRICEID
				, BC.BRANCHID
				, BC.COUNTERID
				, I.CATEGORYID
				, I.SUBCATEGORYID
				, - CR.REFUNDAMOUNT
				, - PBD.GSTVALUE
				, - CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS QUANTITY
				, CR.CREATEDDATE, I.CLASSIFICATIONID, I.SUBCLASSIFICATIONID, I.ITEMID, PBD.GSTID

			FROM POS_CREFUND CR 
				INNER JOIN POS_BILLDETAIL PBD ON CR.BILLDETAILID = PBD.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
				INNER JOIN dbo.SplitString(@BranchID,',') B ON BC.BRANCHID = B.ITEM
				INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID 
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			WHERE CR.CREATEDDATE > (@FromDate)
				AND CR.CREATEDDATE < @ToDate
		) AS BD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCounter = 1 THEN COUNTERID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN FORMAT(CREATEDDATE, 'yyyy-MM-dd 00:00:00') ELSE NULL END
		, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END		

	UPDATE PT
	SET SALEPRICETAX = ROUND(IP.SALEPRICE -((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100), 2)
		, SALEPRICE = IP.SALEPRICE
	FROM 
		#SALES PT
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PT.ITEMPRICEID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID

	UPDATE PT
	SET 
		SALEPRICEWOT = SALEPRICE - SALEPRICETAX
		, PT.TOTALSALEPRICEWOT = PT.TOTALSALEPRICEWT - PT.TOTALSALETAX
	FROM #SALES PT
	
	SELECT 
		PT.PERIODOCITY, B.BRANCHNAME, BC.COUNTERNAME, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, IP.MRP, GST.GSTCODE, PT.SALEPRICEWOT, PT.SALEPRICETAX, PT.SALEPRICE, PT.SALEQUANTITY
		, PT.TOTALSALEPRICEWOT, PT.TOTALSALETAX, PT.TOTALSALEPRICEWT, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME
		, CASE WHEN PT.ISOFFER = 1 THEN 'Yes' ELSE 'No' END AS ISOFFER, PT.WHSTOCK, PT.BRANCHSTOCK
	FROM 
		#SALES PT
		LEFT JOIN ITEMPRICE IP ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN BRANCHCOUNTER BC ON PT.COUNTERID = BC.COUNTERID
		LEFT JOIN ITEMCLASSIFICATION ICLS ON ICLS.CLASSIFICATIONID = PT.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS ON ISCLS.SUBCLASSIFICATIONID = PT.SUBCLASSIFICATIONID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID
	ORDER BY 1, 2, 3, 4, I.ITEMNAME, IC.ITEMCODE, IP.MRP, LEN(GSTCODE), GSTCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SALES1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_SALES1]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(500)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCounter BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0
	, @IncludeStock BIT = 0
	, @IncludeTax BIT = 0
	, @ITEMID INT = 0
	, @CategoryID INT = 13	
	, @IncludeBillDetails BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	IF @IncludeStock = 1
	BEGIN
		SET @IncludeItem = 1
		SET @IncludeBranch = 1
	END

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, COUNTERID INT, SALEQUANTITY DECIMAL(11, 2), SALEPRICE DECIMAL(14, 2)
		, SALEPRICEWOT DECIMAL(14, 2), SALEPRICETAX DECIMAL(14, 2), PERIODOCITY DATETIME, TOTALSALEPRICEWOT DECIMAL(14, 2)
		, TOTALSALETAX DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2), CATEGORYID INT, SUBCATEGORYID INT, BILLNUMBER VARCHAR(30)
		, CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT, ITEMID INT, ISOFFER BIT, WHSTOCK INT, BRANCHSTOCK INT, GSTID INT, OFFERID INT
		, CREATEDBY INT, CREATEDTIME TIME, ISDOORDELIVERY VARCHAR(5), CUSTOMERNAME VARCHAR(100), CUSTOMERNUMBER VARCHAR(10), CUSTOMERGST VARCHAR(100))
	
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #BD(ITEMPRICEID INT, BRANCHID INT, COUNTERID INT, CATEGORYID INT, SUBCATEGORYID INT, BILLEDAMOUNT DECIMAL(18, 2), GSTVALUE DECIMAL(18, 2)
		, QUANTITY DECIMAL(18, 2), CREATEDDATE DATETIME, CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT, ITEMID INT, GSTID INT, ISOFFER INT, OFFERID INT
		, CREATEDBY INT, BILLNUMBER VARCHAR(50), ISDOORDELIVERY VARCHAR(5), CUSTOMERNAME VARCHAR(100), CUSTOMERNUMBER VARCHAR(100), CUSTOMERGST VARCHAR(100) 
		, CREATEDTIME TIME)
	
	DECLARE @InsertColumns NVARCHAR(MAX) = 'BILLEDAMOUNT, GSTVALUE, QUANTITY', @SelectColumns NVARCHAR(MAX) = 'BILLEDAMOUNT, GSTVALUE, QUANTITY', @FullQuery NVARCHAR(MAX)

	IF @IncludeItem = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', ITEMPRICEID, ITEMID'
		SET @SelectColumns = @SelectColumns + ', ITEMPRICEID, ITEMID'
	END

	IF @IncludeBranch = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', BRANCHID'
		SET @SelectColumns = @SelectColumns + ', BRANCHID'
	END

	IF @IncludeCounter = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', COUNTERID'
		SET @SelectColumns = @SelectColumns + ', COUNTERID'
	END

	IF @IncludeCategory = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', CATEGORYID'
		SET @SelectColumns = @SelectColumns + ', CATEGORYID'
	END

	IF @IncludeSubCategory = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', SUBCATEGORYID'
		SET @SelectColumns = @SelectColumns + ', SUBCATEGORYID'
	END

	IF @IncludeDate = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', CREATEDDATE'
		SET @SelectColumns = @SelectColumns + ', CAST(CASE 
				WHEN ''@Periodicity'' = ''Daily'' THEN FORMAT(CREATEDDATE, ''yyyy-MM-dd 00:00:00'')
				WHEN ''@Periodicity'' = ''Monthly'' THEN FORMAT(CREATEDDATE, ''yyyy-MM-01 00:00:00'')
				WHEN ''@Periodicity'' = ''Yearly'' THEN FORMAT(CREATEDDATE, ''yyyy-01-01 00:00:00'')
				WHEN ''@Periodicity'' = ''Hourly'' THEN FORMAT(CREATEDDATE, ''1900-01-01 HH:00'')
				END AS DATETIME)'
	END

	IF @IncludeClassification = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', CLASSIFICATIONID'
		SET @SelectColumns = @SelectColumns + ', CLASSIFICATIONID'
	END

	IF @IncludeSubClassification = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', SUBCLASSIFICATIONID'
		SET @SelectColumns = @SelectColumns + ', SUBCLASSIFICATIONID'
	END

	IF @IncludeTax = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', GSTID'
		SET @SelectColumns = @SelectColumns + ', GSTID'
	END

	IF @IncludeStock = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', ISOFFER, OFFERID'
		SET @SelectColumns = @SelectColumns + ', ISOFFER, OFFERID'
	END

	IF @IncludeBillDetails = 1 
	BEGIN 
		SET @InsertColumns = @InsertColumns + ', CREATEDBY, BILLNUMBER, CUSTOMERNAME, CUSTOMERNUMBER, CUSTOMERGST'
		SET @SelectColumns = @SelectColumns + ', CREATEDBY, BILLNUMBER, CUSTOMERNAME, CUSTOMERNUMBER, CUSTOMERGST'

		SET @InsertColumns = @InsertColumns + ', CREATEDTIME, ISDOORDELIVERY'
		SET @SelectColumns = @SelectColumns + ', CAST(CREATEDDATE AS TIME), CASE WHEN ISDOORDELIVERY = 1 THEN ''Yes'' ELSE ''No'' END'
	END
			
	SELECT @FullQuery =  ('
			INSERT INTO #BD(' + @InsertColumns + ') 
			SELECT ' + @SelectColumns + '
			FROM
				(
					SELECT IP.ITEMPRICEID, 
						BC.BRANCHID, 
						BC.COUNTERID,
						I.CATEGORYID, 
						I.SUBCATEGORYID, 
						PBD.BILLEDAMOUNT, 
						PBD.GSTVALUE, 
						CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END AS QUANTITY, 
						PBD.CREATEDDATE, I.CLASSIFICATIONID, I.SUBCLASSIFICATIONID, I.ITEMID, PBD.GSTID
						, CASE WHEN PBD.OFFERID IS NOT NULL THEN 1 ELSE 0 END ISOFFER, PBD.OFFERID, PB.CREATEDBY, PB.BILLNUMBER
						, PB.ISDOORDELIVERY, PB.CUSTOMERNAME, PB.CUSTOMERNUMBER, PB.CUSTOMERGST
					FROM POS_BILLDETAIL PBD WITH(NOLOCK)
						INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
						INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
						INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
						INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
					WHERE 
						(I.ITEMID = @ITEMID OR @ITEMID = 0)
						AND (I.CATEGORYID = @CategoryID OR @CategoryID = 13)
						AND PBD.CREATEDDATE > (''@FromDate'')
						AND PBD.CREATEDDATE < ''@ToDate''
						AND PBD.DELETEDDATE IS NULL
						AND PB.BILLSTATUS = 1

					UNION ALL

					SELECT IP.ITEMPRICEID
						, BC.BRANCHID
						, BC.COUNTERID
						, I.CATEGORYID
						, I.SUBCATEGORYID
						, - CR.REFUNDAMOUNT
						, - PBD.GSTVALUE
						, - CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS QUANTITY
						, CR.CREATEDDATE, I.CLASSIFICATIONID, I.SUBCLASSIFICATIONID, I.ITEMID, PBD.GSTID
						, 0, NULL, CR.CREATEDBY, PB.BILLNUMBER, PB.ISDOORDELIVERY, PB.CUSTOMERNAME, PB.CUSTOMERNUMBER, PB.CUSTOMERGST
					FROM POS_CREFUND CR WITH(NOLOCK) 
						INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON CR.BILLDETAILID = PBD.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
						INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
						INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
						INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
						INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON PBD.ITEMPRICEID = IP.ITEMPRICEID 
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
					WHERE 
						(I.ITEMID = @ITEMID OR @ITEMID = 0)
						AND (I.CATEGORYID = @CategoryID OR @CategoryID = 13)
						AND CR.CREATEDDATE > (''@FromDate'')
						AND CR.CREATEDDATE < ''@ToDate''
				) BDTEMP
		')

	SELECT @FullQuery = REPLACE(@FullQuery, '@ITEMID', @ITEMID)
	SELECT @FullQuery = REPLACE(@FullQuery, '@CategoryID', @CategoryID)
	SELECT @FullQuery = REPLACE(@FullQuery, '@Periodicity', @Periodicity)
	SELECT @FullQuery = REPLACE(@FullQuery, '@FromDate', @FromDate)
	SELECT @FullQuery = REPLACE(@FullQuery, '@ToDate', @ToDate)

	EXEC SP_EXECUTESQL  @FullQuery

	SELECT COUNT(1) FROM #BD

	INSERT INTO #PROFITABILIY(
		ITEMPRICEID, BRANCHID, COUNTERID, CATEGORYID, SUBCATEGORYID, PERIODOCITY, SALEQUANTITY, TOTALSALEPRICEWT, TOTALSALETAX
		, CLASSIFICATIONID, SUBCLASSIFICATIONID, ITEMID, GSTID, ISOFFER, OFFERID, CREATEDBY, BILLNUMBER, CREATEDTIME
		, ISDOORDELIVERY, CUSTOMERNAME, CUSTOMERNUMBER, CUSTOMERGST)
	SELECT ITEMPRICEID, BRANCHID, COUNTERID, CATEGORYID, SUBCATEGORYID, CREATEDDATE	
			, SUM(QUANTITY) AS QUANTITY, SUM(BILLEDAMOUNT) AS BILLEDAMOUNT, SUM(GSTVALUE) AS GSTVALUE
			, CLASSIFICATIONID, SUBCLASSIFICATIONID, ITEMID, GSTID, ISOFFER, OFFERID, CREATEDBY, BILLNUMBER, CREATEDDATE
			, ISDOORDELIVERY, CUSTOMERNAME, CUSTOMERNUMBER, CUSTOMERGST
	FROM #BD BD
	GROUP BY ITEMPRICEID, BRANCHID, COUNTERID, CATEGORYID, SUBCATEGORYID, CREATEDDATE	
			, CLASSIFICATIONID, SUBCLASSIFICATIONID, ITEMID, GSTID, ISOFFER, OFFERID, CREATEDBY, BILLNUMBER, CREATEDDATE
			, ISDOORDELIVERY, CUSTOMERNAME, CUSTOMERNUMBER, CUSTOMERGST

	UPDATE PT
	SET SALEPRICETAX = ROUND(IP.SALEPRICE -((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100), 2)
		, SALEPRICE = IP.SALEPRICE
	FROM 
		#PROFITABILIY PT
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PT.ITEMPRICEID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID

	UPDATE PT
	SET 
		SALEPRICEWOT = SALEPRICE - SALEPRICETAX
		, PT.TOTALSALEPRICEWOT = PT.TOTALSALEPRICEWT - PT.TOTALSALETAX
	FROM #PROFITABILIY PT

	IF @IncludeStock = 1
	BEGIN
		
		UPDATE PT
		SET PT.WHSTOCK = SSWH.WHQUANTITY, PT.BRANCHSTOCK = SSB.BQUANTITY
		FROM 
			#PROFITABILIY PT			
			INNER JOIN
				(
					SELECT I.ITEMID, CASE WHEN I.ISOPENITEM = 1 THEN CAST(SUM(SSBWH.WEIGHTINKGS) AS INT) ELSE SUM(SSWH.QUANTITY) END WHQUANTITY
					FROM 
						ITEMPRICE IP WITH(NOLOCK) 
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
						INNER JOIN STOCKSUMMARY SSWH WITH(NOLOCK) ON SSWH.ITEMPRICEID = IP.ITEMPRICEID AND SSWH.BRANCHID = 45
						INNER JOIN STOCKSUMMARY SSBWH WITH(NOLOCK) ON SSBWH.ITEMPRICEID = IP.ITEMPRICEID AND SSBWH.BRANCHID = 97									
					GROUP BY I.ITEMID, I.ISOPENITEM
				) SSWH ON PT.ITEMID = SSWH.ITEMID
			INNER JOIN 
				(
					SELECT I.ITEMID, SSBINNER.BRANCHID, SUM(SSBINNER.QUANTITY) BQUANTITY
					FROM 
						ITEMPRICE IP WITH(NOLOCK) 
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
						INNER JOIN STOCKSUMMARY SSBINNER WITH(NOLOCK) ON SSBINNER.ITEMPRICEID = IP.ITEMPRICEID 
					GROUP BY I.ITEMID, SSBINNER.BRANCHID				
				) SSB ON PT.ITEMID = SSB.ITEMID AND PT.BRANCHID = SSB.BRANCHID

		--UPDATE PT 
		--SET PT.ISOFFER = 1
		--FROM #PROFITABILIY PT
		--WHERE EXISTS
		--	(
		--		SELECT 1 
		--		FROM 
		--			POS_BILLDETAIL PBD WITH(NOLOCK) 
		--			INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		--			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		--			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID					
		--			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID
		--		WHERE 
		--			IC.ITEMID = PT.ITEMID 
		--			AND BC.BRANCHID = PT.BRANCHID 
		--			AND PB.BILLSTATUS = 1 
		--			AND PBD.DELETEDDATE IS NULL
		--			AND PB.CREATEDDATE >= @FromDate
		--			AND PB.CREATEDDATE <= @ToDate
		--			AND PBD.OFFERID IS NOT NULL
		--	)			

	END

	SELECT 
		PT.PERIODOCITY, B.BRANCHNAME, BC.COUNTERNAME, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE
		, IP.MRP, GST.GSTCODE, PT.SALEPRICEWOT, PT.SALEPRICETAX, PT.SALEPRICE, PT.SALEQUANTITY
		, PT.TOTALSALEPRICEWOT, PT.TOTALSALETAX, PT.TOTALSALEPRICEWT, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME
		, CASE WHEN PT.ISOFFER = 1 THEN 'Yes' ELSE 'No' END AS ISOFFER, OFR.OFFERCODE, BOFR.OFFERCODE BASEOFFERCODE, PT.WHSTOCK, PT.BRANCHSTOCK
		, USR.FULLNAME BILLCREATEDBY, PT.BILLNUMBER, PT.CREATEDTIME, PT.ISDOORDELIVERY, PT.CUSTOMERNAME, PT.CUSTOMERNUMBER, PT.CUSTOMERGST
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC WITH(NOLOCK) ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON PT.COUNTERID = BC.COUNTERID
		LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = PT.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS WITH(NOLOCK) ON ISCLS.SUBCLASSIFICATIONID = PT.SUBCLASSIFICATIONID
		LEFT JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PT.GSTID
		LEFT JOIN OFFER OFR WITH(NOLOCK) ON OFR.OFFERID = PT.OFFERID
		LEFT JOIN BASEOFFER BOFR WITH(NOLOCK) ON BOFR.BASEOFFERID = OFR.BASEOFFERID
		LEFT JOIN TBLUSER USR WITH(NOLOCK) ON USR.USERID = PT.CREATEDBY
	ORDER BY 1, 2, 3, 4, I.ITEMNAME, IC.ITEMCODE, IP.MRP, LEN(GSTCODE), GSTCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_AND_SALES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCK_AND_SALES]
(
	@BranchIDs VARCHAR(1000)
	, @FromDate DATE
	, @ToDate DATE
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeGST BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	CREATE TABLE #STOCKANDSALES(BRANCHID INT, ITEMPRICEID INT, ISOPENITEM BIT, OPENINGQTYORWGHT DECIMAL(20, 2), DISPATCHQTYORWGHT DECIMAL(20, 2)
		, BRQTYORWGHT DECIMAL(20, 2), SALEQTYORWGHT DECIMAL(20, 2), CLOSINGQTYORWGHT DECIMAL(20, 2), ITEMCOSTPRICEID INT)
	
	SELECT B.ITEM, SCMAX.COUNTINGDATE
	INTO #BRANCH
	FROM 
		dbo.SplitString(@BranchIDs,',') B
		INNER JOIN 
			(
				SELECT SC.BRANCHID, CAST(MAX(SC.STOCKACCEPTEDDATE) AS DATE) AS COUNTINGDATE
				FROM STOCKCOUNTING SC
				WHERE CAST(SC.STOCKACCEPTEDDATE AS DATE) <= @FromDate AND SC.DELETEDDATE IS NULL
				GROUP BY SC.BRANCHID
			) SCMAX ON SCMAX.BRANCHID = B.ITEM

	 INSERT INTO #STOCKANDSALES 
	 SELECT 
		SC.BRANCHID, SCD.ITEMPRICEID, I.ISOPENITEM, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SCD.WEIGHTINKGS ELSE SCD.QUANTITY END) OPENINGQTYORWGHT
		, 0.0000 AS DISPATCHQTYORWGHT, 0.0000 AS BRQTYORWGHT, 0.0000 AS SALEQTYORWGHT, 0.0000 AS CLOSINGQTYORWGHT
		, NULL AS ITEMCOSTPRICEID
	 FROM 
		#BRANCH B
		INNER JOIN STOCKCOUNTING SC ON SC.BRANCHID = B.Item AND CAST(SC.STOCKACCEPTEDDATE AS DATE) = B.COUNTINGDATE
		INNER JOIN STOCKCOUNTINGDETAIL SCD ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SCD.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE
		SC.DELETEDDATE IS NULL
		AND SCD.DELETEDDATE IS NULL
	GROUP BY SC.BRANCHID, SCD.ITEMPRICEID, I.ISOPENITEM

	INSERT INTO #STOCKANDSALES
	SELECT
		B.ITEM, IP.ITEMPRICEID, I.ISOPENITEM, 0.00 OPENINGQTYORWGHT, 0.00 AS DISPATCHQTYORWGHT
		, 0.00 AS BRQTYORWGHT, 0.00 AS SALEQTYORWGHT, 0.00 AS CLOSINGQTYORWGHT, NULL AS ITEMCOSTPRICEID
	FROM
		#BRANCH B
		CROSS APPLY ITEMPRICE IP 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE NOT EXISTS (SELECT 1 FROM #STOCKANDSALES SAS WHERE SAS.BRANCHID = B.ITEM AND SAS.ITEMPRICEID = IP.ITEMPRICEID)

	UPDATE SAS
	SET SAS.ITEMCOSTPRICEID = ICPMAX.MAXITEMCOSTPRICEID
	FROM 
		#STOCKANDSALES SAS
		INNER JOIN
			(
				SELECT ICP.ITEMPRICEID, MAX(ICP.ITEMCOSTPRICEID) AS MAXITEMCOSTPRICEID
				FROM ITEMCOSTPRICE ICP
				WHERE 
					ICP.DELETEDDATE IS NULL
					AND ICP.CREATEDDATE < @ToDate
				GROUP BY ICP.ITEMPRICEID
			) ICPMAX ON ICPMAX.ITEMPRICEID = SAS.ITEMPRICEID

	----------------------------------    Add Stock Dispatches     ----------------------------------------------------------------------

	UPDATE SAS
	SET SAS.OPENINGQTYORWGHT = SAS.OPENINGQTYORWGHT + (CASE WHEN SAS.ISOPENITEM = 1 THEN STKDSPTCH.WEIGHTINKGS ELSE STKDSPTCH.QUANTITY END)
	FROM 
		#STOCKANDSALES SAS
		INNER JOIN 
			(
				SELECT SD.TOBRANCHID, SDD.ITEMPRICEID, SUM(SDD.DISPATCHQUANTITY) QUANTITY, SUM(SDD.WEIGHTINKGS) WEIGHTINKGS
				FROM
					STOCKDISPATCH SD
					INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
					INNER JOIN #BRANCH B ON B.ITEM = SD.TOBRANCHID
				WHERE 
					SDD.DELETEDDATE IS NULL
					AND SD.DELETEDDATE IS NULL
					AND ISNULL(SD.STATUS, 0) <> 0
					AND SD.CREATEDDATE < @FromDate	
					AND SD.CREATEDDATE > B.COUNTINGDATE
				GROUP BY SD.TOBRANCHID, SDD.ITEMPRICEID
			) STKDSPTCH ON STKDSPTCH.TOBRANCHID = SAS.BRANCHID AND STKDSPTCH.ITEMPRICEID = SAS.ITEMPRICEID

	UPDATE SAS
	SET SAS.DISPATCHQTYORWGHT = (CASE WHEN SAS.ISOPENITEM = 1 THEN STKDSPTCH.WEIGHTINKGS ELSE STKDSPTCH.QUANTITY END)
	FROM 
		#STOCKANDSALES SAS
		INNER JOIN 
			(
				SELECT SD.TOBRANCHID, SDD.ITEMPRICEID, SUM(SDD.DISPATCHQUANTITY) QUANTITY, SUM(SDD.WEIGHTINKGS) WEIGHTINKGS
				FROM
					STOCKDISPATCH SD
					INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
					INNER JOIN #BRANCH B ON B.ITEM = SD.TOBRANCHID
				WHERE 
					SDD.DELETEDDATE IS NULL
					AND SD.DELETEDDATE IS NULL
					AND ISNULL(SD.STATUS, 0) <> 0
					AND SD.CREATEDDATE > @FromDate AND SD.CREATEDDATE < @ToDate
				GROUP BY SD.TOBRANCHID, SDD.ITEMPRICEID
			) STKDSPTCH ON STKDSPTCH.TOBRANCHID = SAS.BRANCHID AND STKDSPTCH.ITEMPRICEID = SAS.ITEMPRICEID

	-------------------------------------- Subtract Branch Refunds --------------------------------------------------------------------------

	UPDATE SAS
	SET SAS.OPENINGQTYORWGHT = SAS.OPENINGQTYORWGHT - (CASE WHEN SAS.ISOPENITEM = 1 THEN BREFS.WEIGHTINKGS ELSE BREFS.QUANTITY END)
	FROM
		#STOCKANDSALES SAS		
		INNER JOIN 
			(
				SELECT PBRFD.ITEMPRICEID, PBRF.BRANCHID, SUM(PBRFD.QUANTITY) QUANTITY, SUM(PBRFD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_BREFUNDDETAIL PBRFD 
					INNER JOIN POS_BREFUND PBRF ON PBRF.BRID = PBRFD.BRID
					INNER JOIN #BRANCH B ON B.ITEM = PBRF.BRANCHID
				WHERE 
					PBRF.STATUS = 1
					AND PBRFD.DELETEDDATE IS NULL 
					AND PBRF.UPDATEDDATE < @FromDate 	
					AND PBRF.UPDATEDDATE > B.COUNTINGDATE
				GROUP BY PBRFD.ITEMPRICEID, PBRF.BRANCHID
			) BREFS ON BREFS.BRANCHID = SAS.BRANCHID AND BREFS.ITEMPRICEID = SAS.ITEMPRICEID

	UPDATE SAS
	SET SAS.BRQTYORWGHT = (CASE WHEN SAS.ISOPENITEM = 1 THEN BREFS.WEIGHTINKGS ELSE BREFS.QUANTITY END)
	FROM
		#STOCKANDSALES SAS		
		INNER JOIN 
			(
				SELECT PBRFD.ITEMPRICEID, PBRF.BRANCHID, SUM(PBRFD.QUANTITY) QUANTITY, SUM(PBRFD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_BREFUNDDETAIL PBRFD 
					INNER JOIN POS_BREFUND PBRF ON PBRF.BRID = PBRFD.BRID
					INNER JOIN #BRANCH B ON B.ITEM = PBRF.BRANCHID
				WHERE 
					PBRF.STATUS = 1
					AND PBRFD.DELETEDDATE IS NULL 
					AND PBRF.UPDATEDDATE > @FromDate AND PBRF.UPDATEDDATE < @ToDate
				GROUP BY PBRFD.ITEMPRICEID, PBRF.BRANCHID
			) BREFS ON BREFS.BRANCHID = SAS.BRANCHID AND BREFS.ITEMPRICEID = SAS.ITEMPRICEID
	
	--------------------------------------- Subtract Sale ---------------------------------------------------------------------------------------------

	UPDATE SAS
	SET SAS.OPENINGQTYORWGHT = SAS.OPENINGQTYORWGHT - (CASE WHEN SAS.ISOPENITEM = 1 THEN SALES.WEIGHTINKGS ELSE SALES.QUANTITY END)
	FROM
		#STOCKANDSALES SAS	
		INNER JOIN 
			(
				SELECT PBD.ITEMPRICEID, BC.BRANCHID, SUM(PBD.QUANTITY) QUANTITY, SUM(PBD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN #BRANCH B ON B.ITEM = BC.BRANCHID
				WHERE 
					PB.BILLSTATUS = 1
					AND PBD.DELETEDDATE IS NULL 
					AND PBD.CREATEDDATE < @FromDate 
					AND PBD.CREATEDDATE > B.COUNTINGDATE
					AND PB.CREATEDDATE < @FromDate
					AND PB.CREATEDDATE > B.COUNTINGDATE
				GROUP BY PBD.ITEMPRICEID, BC.BRANCHID
			) SALES ON SALES.BRANCHID = SAS.BRANCHID AND SALES.ITEMPRICEID = SAS.ITEMPRICEID

	UPDATE SAS
	SET SAS.SALEQTYORWGHT = (CASE WHEN SAS.ISOPENITEM = 1 THEN SALES.WEIGHTINKGS ELSE SALES.QUANTITY END)
	FROM
		#STOCKANDSALES SAS	
		INNER JOIN 
			(
				SELECT PBD.ITEMPRICEID, BC.BRANCHID, SUM(PBD.QUANTITY) QUANTITY, SUM(PBD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_BILLDETAIL PBD
					INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN #BRANCH B ON B.ITEM = BC.BRANCHID
				WHERE 
					PB.BILLSTATUS = 1
					AND PBD.DELETEDDATE IS NULL 
					AND PBD.CREATEDDATE > @FromDate AND PBD.CREATEDDATE < @ToDate 
					AND PB.CREATEDDATE > @FromDate AND PB.CREATEDDATE < @ToDate
				GROUP BY PBD.ITEMPRICEID, BC.BRANCHID
			) SALES ON SALES.BRANCHID = SAS.BRANCHID AND SALES.ITEMPRICEID = SAS.ITEMPRICEID

	--------------------------------------------- Add Customer Refunds ----------------------------------------------------------------------------

	UPDATE SAS
	SET SAS.OPENINGQTYORWGHT = SAS.OPENINGQTYORWGHT + (CASE WHEN SAS.ISOPENITEM = 1 THEN SALES.WEIGHTINKGS ELSE SALES.QUANTITY END)
	FROM
		#STOCKANDSALES SAS	
		INNER JOIN 
			(
				SELECT PBD.ITEMPRICEID, BC.BRANCHID, SUM(CRF.REFUNDQUANTITY) QUANTITY, SUM(CRF.REFUNDWEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_CREFUND CRF
					INNER JOIN POS_BILLDETAIL PBD ON PBD.BILLDETAILID = CRF.BILLDETAILID AND PBD.BRANCHCOUNTERID = CRF.COUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN #BRANCH B ON B.ITEM = BC.BRANCHID
				WHERE 
					CRF.DELETEDDATE IS NULL
					AND CRF.CREATEDDATE < @FromDate 
					AND CRF.CREATEDDATE > B.COUNTINGDATE
				GROUP BY PBD.ITEMPRICEID, BC.BRANCHID
			) SALES ON SALES.BRANCHID = SAS.BRANCHID AND SALES.ITEMPRICEID = SAS.ITEMPRICEID

	UPDATE SAS
	SET SAS.SALEQTYORWGHT = SAS.SALEQTYORWGHT - (CASE WHEN SAS.ISOPENITEM = 1 THEN SALES.WEIGHTINKGS ELSE SALES.QUANTITY END)
	FROM
		#STOCKANDSALES SAS	
		INNER JOIN 
			(
				SELECT PBD.ITEMPRICEID, BC.BRANCHID, SUM(PBD.QUANTITY) QUANTITY, SUM(PBD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_CREFUND CRF
					INNER JOIN POS_BILLDETAIL PBD ON PBD.BILLDETAILID = CRF.BILLDETAILID AND PBD.BRANCHCOUNTERID = CRF.COUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN #BRANCH B ON B.ITEM = BC.BRANCHID
				WHERE 
					CRF.DELETEDDATE IS NULL 
					AND CRF.CREATEDDATE > @FromDate AND CRF.CREATEDDATE < @ToDate 
				GROUP BY PBD.ITEMPRICEID, BC.BRANCHID
			) SALES ON SALES.BRANCHID = SAS.BRANCHID AND SALES.ITEMPRICEID = SAS.ITEMPRICEID

	----------------------------------------- Stock Adjustment     ----------------------------------------------------------------------------

	
	UPDATE SAS
	SET SAS.OPENINGQTYORWGHT = SAS.OPENINGQTYORWGHT - (CASE WHEN SAS.ISOPENITEM = 1 THEN (SA.WEIGHTINKGS - SA.PREVWEIGHTINKGS) ELSE (SA.QUANTITY - SA.PREVQUANTITY) END)
	FROM
		#STOCKANDSALES SAS			
		INNER JOIN 
			(
				SELECT SA.ITEMPRICEID, MAX(SA.STOCKADJUSTMENTID) MAXSTOCKADJUSTMENTID
				FROM 
					STOCKADJUSTMENT SA
					INNER JOIN #BRANCH B ON B.ITEM = SA.BRANCHID
				WHERE 
					SA.CREATEDDATE > B.COUNTINGDATE AND SA.CREATEDDATE < @FromDate
				GROUP BY SA.ITEMPRICEID
			) SAMAX ON SAMAX.ITEMPRICEID = SAS.ITEMPRICEID
		INNER JOIN STOCKADJUSTMENT SA ON SA.STOCKADJUSTMENTID = SAMAX.MAXSTOCKADJUSTMENTID


	UPDATE #STOCKANDSALES
	SET CLOSINGQTYORWGHT = OPENINGQTYORWGHT + DISPATCHQTYORWGHT - BRQTYORWGHT - SALEQTYORWGHT 

	SELECT 
		B.BRANCHID, I.ITEMID, IC.ITEMCODEID, IP.ITEMPRICEID, GST.GSTID, CAT.CATEGORYID, SUBCAT.SUBCATEGORYID, ICLS.CLASSIFICATIONID
		, ISCLS.SUBCLASSIFICATIONID, B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME
		, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE, ICP.COSTPRICEWOT, GST.GSTCODE
		, SASMAIN.OPENINGQTYORWGHT, SASMAIN.DISPATCHQTYORWGHT , SASMAIN.BRQTYORWGHT , SASMAIN.SALEQTYORWGHT , SASMAIN.CLOSINGQTYORWGHT
		, SASMAIN.OPENINGCPWOT, SASMAIN.DISPATCHCPWOT, SASMAIN.BRCPWOT, SASMAIN.SALECPWOT, SASMAIN.CLOSINGCPWOT		
	FROM
		(
			SELECT 
				CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END ITEMID
				, CASE WHEN @IncludeItem = 1 THEN IC.ITEMCODEID ELSE NULL END ITEMCODEID
				, CASE WHEN @IncludeItem = 1 THEN IP.ITEMPRICEID ELSE NULL END ITEMPRICEID
				, CASE WHEN @IncludeItem = 1 THEN SAS.ITEMCOSTPRICEID ELSE NULL END ITEMCOSTPRICEID
				, CASE WHEN @IncludeBranch = 1 THEN SAS.BRANCHID ELSE NULL END BRANCHID
				, CASE WHEN @IncludeGST = 1 THEN IP.GSTID ELSE NULL END GSTID
				, CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END CATEGORYID
				, CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END SUBCATEGORYID
				, CASE WHEN @IncludeClassification = 1 THEN I.CLASSIFICATIONID ELSE NULL END CLASSIFICATIONID
				, CASE WHEN @IncludeSubClassification = 1 THEN I.SUBCLASSIFICATIONID ELSE NULL END SUBCLASSIFICATIONID
				, SUM(SAS.OPENINGQTYORWGHT) OPENINGQTYORWGHT, SUM(SAS.DISPATCHQTYORWGHT) DISPATCHQTYORWGHT
				, SUM(SAS.BRQTYORWGHT) BRQTYORWGHT, SUM(SAS.SALEQTYORWGHT) SALEQTYORWGHT, SUM(SAS.CLOSINGQTYORWGHT) CLOSINGQTYORWGHT
				, SUM(SAS.OPENINGQTYORWGHT * ICP.COSTPRICEWOT) OPENINGCPWOT, SUM(SAS.DISPATCHQTYORWGHT * ICP.COSTPRICEWOT) DISPATCHCPWOT
				, SUM(SAS.BRQTYORWGHT * ICP.COSTPRICEWOT) BRCPWOT, SUM(SAS.SALEQTYORWGHT * ICP.COSTPRICEWOT) SALECPWOT
				, SUM(SAS.CLOSINGQTYORWGHT * ICP.COSTPRICEWOT) CLOSINGCPWOT	
				, CASE WHEN @IncludeBrand = 1 THEN I.BRANDID ELSE NULL END as BRANDID
				, CASE WHEN @IncludeManufacturer = 1 THEN I.MANUFACTURERID ELSE NULL END as MANUFACTURERID
			FROM 
				#STOCKANDSALES SAS 
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SAS.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SAS.ITEMCOSTPRICEID
			WHERE SAS.CLOSINGQTYORWGHT <> 0
			GROUP BY 
				CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN IC.ITEMCODEID ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN IP.ITEMPRICEID ELSE NULL END
				, CASE WHEN @IncludeItem = 1 THEN SAS.ITEMCOSTPRICEID ELSE NULL END
				, CASE WHEN @IncludeBranch = 1 THEN SAS.BRANCHID ELSE NULL END
				, CASE WHEN @IncludeGST = 1 THEN IP.GSTID ELSE NULL END
				, CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END
				, CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END
				, CASE WHEN @IncludeClassification = 1 THEN I.CLASSIFICATIONID ELSE NULL END
				, CASE WHEN @IncludeSubClassification = 1 THEN I.SUBCLASSIFICATIONID ELSE NULL END
				, CASE WHEN @IncludeBrand = 1 THEN I.BRANDID ELSE NULL END
				, CASE WHEN @IncludeManufacturer = 1 THEN I.MANUFACTURERID ELSE NULL END
		) SASMAIN
		LEFT JOIN BRANCH B ON B.BRANCHID = SASMAIN.BRANCHID
		LEFT JOIN ITEM I ON I.ITEMID = SASMAIN.ITEMID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = SASMAIN.ITEMCODEID
		LEFT JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SASMAIN.ITEMPRICEID
		LEFT JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = SASMAIN.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = SASMAIN.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION ICLS ON ICLS.CLASSIFICATIONID = SASMAIN.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS ON ISCLS.SUBCLASSIFICATIONID = SASMAIN.SUBCLASSIFICATIONID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = SASMAIN.GSTID
		LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SASMAIN.ITEMCOSTPRICEID
		LEFT JOIN TBLBRAND BR ON SASMAIN.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON SASMAIN.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY
		B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME
		, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_ASOFDATE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCK_ASOFDATE]
(
	@AsOnDate DATE,
	@BranchID NVARCHAR(1000),
	@ITEMID INT = 0,
	@CategoryID VARCHAR(500),
	@IncludeLatestCP BIT = 0,
	@IncludeAvgCP BIT = 0,
	@IncludeClassification BIT = 0,
	@IncludeBrand BIT = 0
)
AS 
BEGIN

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	DECLARE @AvgCPDate DATE 

	SELECT @AvgCPDate = DATEFROMPARTS(YEAR(@AsOnDate), MONTH(@AsOnDate), 1)
	SELECT @AsOnDate = DATEADD(d, 1, @AsOnDate)

	CREATE TABLE #ASONDATESTOCK(ITEMPRICEID INT, BRANCHID INT, ISWAREHOUSE BIT, ISOPENITEM BIT, ITEMCOSTPRICEID INT
		, QTYORWGHT DECIMAL(18, 2), SUPPLIERID INT, ITEMID INT)

	INSERT INTO #ASONDATESTOCK
	SELECT IP.ITEMPRICEID, SS.BRANCHID, B.ISWAREHOUSE, I.ISOPENITEM, NULL AS ITEMCOSTPRICEID
		, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS QTYORWGHT
		, NULL SUPPLIERID, I.ITEMID
	FROM
		STOCKSUMMARY SS WITH(NOLOCK)
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN BRANCH B ON B.BRANCHID = SS.BRANCHID
		INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SS.BRANCHID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
	WHERE (I.ITEMID = @ITEMID OR @ITEMID = 0)

	-- Add sales back

	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT + (CASE WHEN AODSS.ISOPENITEM = 1 THEN SALES.WEIGHTINKGS ELSE SALES.QUANTITY END)
	FROM
		#ASONDATESTOCK AODSS
		INNER JOIN 
			(
				SELECT PBD.ITEMPRICEID, BC.BRANCHID, SUM(PBD.QUANTITY) QUANTITY, SUM(PBD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_BILLDETAIL PBD WITH(NOLOCK)
					INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = BC.BRANCHID
				WHERE 
					PB.BILLSTATUS = 1
					AND PBD.DELETEDDATE IS NULL 
					AND PBD.CREATEDDATE > @AsOnDate 
					AND PB.CREATEDDATE > @AsOnDate
					AND PBD.DAYCLOSUREID IS NOT NULL
				GROUP BY PBD.ITEMPRICEID, BC.BRANCHID
			) SALES ON SALES.BRANCHID = AODSS.BRANCHID AND SALES.ITEMPRICEID = AODSS.ITEMPRICEID

	-- SUBTRACT CUSTOMER REFUNDS

	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT - (CASE WHEN AODSS.ISOPENITEM = 1 THEN CREFS.WEIGHTINKGS ELSE CREFS.QUANTITY END)
	FROM
		#ASONDATESTOCK AODSS
		INNER JOIN 
			(
				SELECT PBD.ITEMPRICEID, BC.BRANCHID, SUM(PCRF.REFUNDQUANTITY) QUANTITY, SUM(PCRF.REFUNDWEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_CREFUND PCRF WITH(NOLOCK)
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = PCRF.BILLDETAILID AND PBD.BRANCHCOUNTERID = PCRF.COUNTERID
					INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
					INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
					INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = BC.BRANCHID
				WHERE 
					PB.BILLSTATUS = 1
					AND PCRF.DELETEDDATE IS NULL 
					AND PCRF.CREATEDDATE > @AsOnDate 
					AND PCRF.DAYCLOSUREID IS NOT NULL
				GROUP BY PBD.ITEMPRICEID, BC.BRANCHID
			) CREFS ON CREFS.BRANCHID = AODSS.BRANCHID AND CREFS.ITEMPRICEID = AODSS.ITEMPRICEID


	--------------------------------------------------- BRANCH ONLY LOGIC START

	-- ADD BRANCH REFUNDS

	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT + (CASE WHEN AODSS.ISOPENITEM = 1 THEN BREFS.WEIGHTINKGS ELSE BREFS.QUANTITY END)
	FROM
		#ASONDATESTOCK AODSS		
		INNER JOIN 
			(
				SELECT PBRFD.ITEMPRICEID, PBRF.BRANCHID, SUM(PBRFD.QUANTITY) QUANTITY, SUM(PBRFD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					POS_BREFUNDDETAIL PBRFD WITH(NOLOCK)
					INNER JOIN POS_BREFUND PBRF WITH(NOLOCK) ON PBRF.BRID = PBRFD.BRID
					INNER JOIN #BRANCH BRANCHIDS WITH(NOLOCK) ON BRANCHIDS.ITEM = PBRF.BRANCHID
				WHERE 
					PBRF.STATUS = 1
					AND PBRFD.DELETEDDATE IS NULL 
					AND PBRF.UPDATEDDATE > @AsOnDate 
				GROUP BY PBRFD.ITEMPRICEID, PBRF.BRANCHID
			) BREFS ON BREFS.BRANCHID = AODSS.BRANCHID AND BREFS.ITEMPRICEID = AODSS.ITEMPRICEID
	WHERE AODSS.ISWAREHOUSE <> 1

	-- SUBTRACT STOCKDISPATCH

	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT - (CASE WHEN AODSS.ISOPENITEM = 1 THEN STKDSPTCH.WEIGHTINKGS ELSE STKDSPTCH.QUANTITY END)
	FROM
		#ASONDATESTOCK AODSS		
		INNER JOIN 
			(
				SELECT SDD.ITEMPRICEID, SD.TOBRANCHID, SUM(SDD.DISPATCHQUANTITY) QUANTITY, SUM(SDD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					STOCKDISPATCHDETAIL SDD WITH(NOLOCK)
					INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID 
					INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SD.TOBRANCHID
				WHERE 
					SD.STATUS <> 0
					AND SDD.DELETEDDATE IS NULL 
					AND SD.DELETEDDATE IS NULL
					AND SD.CREATEDDATE > @AsOnDate 
				GROUP BY SDD.ITEMPRICEID, SD.TOBRANCHID
			) STKDSPTCH ON STKDSPTCH.TOBRANCHID = AODSS.BRANCHID AND STKDSPTCH.ITEMPRICEID = AODSS.ITEMPRICEID
	WHERE AODSS.ISWAREHOUSE <> 1

	-------------- END OF BRANCH ONLY LOGIC

	-------------------------------------------------------------------- warehouse only logic

	-- add stock dispatch
	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT + (CASE WHEN AODSS.ISOPENITEM = 1 THEN STKDSPTCH.WEIGHTINKGS ELSE STKDSPTCH.QUANTITY END)
	FROM
		#ASONDATESTOCK AODSS		
		INNER JOIN 
			(
				SELECT SDD.ITEMPRICEID, SD.FROMBRANCHID, SUM(SDD.DISPATCHQUANTITY) QUANTITY, SUM(SDD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					STOCKDISPATCHDETAIL SDD WITH(NOLOCK)
					INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID 
					INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SD.FROMBRANCHID
				WHERE 
					SD.STATUS <> 0
					AND SDD.DELETEDDATE IS NULL 
					AND SD.DELETEDDATE IS NULL
					AND SD.CREATEDDATE > @AsOnDate 
				GROUP BY SDD.ITEMPRICEID, SD.FROMBRANCHID
			) STKDSPTCH ON STKDSPTCH.FROMBRANCHID = AODSS.BRANCHID AND STKDSPTCH.ITEMPRICEID = AODSS.ITEMPRICEID
	WHERE AODSS.ISWAREHOUSE = 1

	-- SUBTRACT STOCK ENTRY

	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT - 
		(
			CASE 
				WHEN AODSS.ISOPENITEM = 1 AND AODSS.BRANCHID = 97 THEN STKENTRY.WEIGHTINKGS 
				WHEN AODSS.ISOPENITEM = 0 AND AODSS.BRANCHID = 45 THEN STKENTRY.QUANTITY
				ELSE 0 
			END
		)
	FROM
		#ASONDATESTOCK AODSS		
		INNER JOIN 
			(
				SELECT ICP.ITEMPRICEID, SUM(SED.QUANTITY) QUANTITY, SUM(SED.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					STOCKENTRYDETAIL SED WITH(NOLOCK)
					INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID 
					INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
				WHERE 
					SE.STATUS = 1
					AND SED.DELETEDDATE IS NULL 
					AND SE.DELETEDDATE IS NULL
					AND SE.CREATEDDATE > @AsOnDate 					
				GROUP BY ICP.ITEMPRICEID
			) STKENTRY ON STKENTRY.ITEMPRICEID = AODSS.ITEMPRICEID
	WHERE AODSS.ISWAREHOUSE = 1

	-- SUBSTRACT BRANCH REFUNDS ONLY REASON 3 & 4.. THE OTHERS ARE DEALER REFUNDS

	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT - (CASE WHEN AODSS.ISOPENITEM = 1 THEN BREFS.WEIGHTINKGS ELSE BREFS.QUANTITY END)
	FROM
		#ASONDATESTOCK AODSS		
		INNER JOIN 
			(
				SELECT PBRFD.ITEMPRICEID, SUM(PBRFD.ACCEPTEDQUANTITY) QUANTITY, SUM(PBRFD.ACCEPTEDWEIGHTKGS) WEIGHTINKGS
				FROM 
					POS_BREFUNDDETAIL PBRFD WITH(NOLOCK)
					INNER JOIN POS_BREFUND PBRF WITH(NOLOCK) ON PBRF.BRID = PBRFD.BRID
					INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = PBRF.BRANCHID
				WHERE 
					PBRF.STATUS = 1
					AND PBRFD.DELETEDDATE IS NULL 
					AND PBRF.UPDATEDDATE > @AsOnDate 
				GROUP BY PBRFD.ITEMPRICEID
			) BREFS ON BREFS.ITEMPRICEID = AODSS.ITEMPRICEID
	WHERE AODSS.BRANCHID = 45


	------------- END of warehouse only logic

	-- stock adjustment

	UPDATE AODSS
	SET AODSS.QTYORWGHT = AODSS.QTYORWGHT - (CASE WHEN AODSS.ISOPENITEM = 1 THEN (SA.WEIGHTINKGS - SA.PREVWEIGHTINKGS) ELSE (SA.QUANTITY - SA.PREVQUANTITY) END)
	FROM
		#ASONDATESTOCK AODSS		
		INNER JOIN 
			(
				SELECT SA.ITEMPRICEID, MAX(SA.STOCKADJUSTMENTID) MAXSTOCKADJUSTMENTID
				FROM STOCKADJUSTMENT SA WITH(NOLOCK)
				INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SA.BRANCHID
				WHERE SA.CREATEDDATE > @AsOnDate
				GROUP BY SA.ITEMPRICEID
			) SAMAX ON SAMAX.ITEMPRICEID = AODSS.ITEMPRICEID
		INNER JOIN STOCKADJUSTMENT SA ON SA.STOCKADJUSTMENTID = SAMAX.MAXSTOCKADJUSTMENTID

	UPDATE AODSS
	SET 
		AODSS.ITEMCOSTPRICEID = MAXICP.ITEMCOSTPRICEID, 
		AODSS.SUPPLIERID = SE.SUPPLIERID
	FROM
		#ASONDATESTOCK AODSS
		LEFT JOIN
			(
				SELECT ICP.ITEMPRICEID, MAX(ICP.ITEMCOSTPRICEID) ITEMCOSTPRICEID
				FROM ITEMCOSTPRICE ICP
				WHERE ICP.CREATEDDATE < @AsOnDate AND ICP.DELETEDDATE IS NULL
				GROUP BY ICP.ITEMPRICEID
			) MAXICP ON MAXICP.ITEMPRICEID = AODSS.ITEMPRICEID
		LEFT JOIN
			(
				SELECT SED.ITEMCOSTPRICEID, MAX(SE.STOCKENTRYID) STOCKENTRYID
				FROM
					STOCKENTRYDETAIL SED WITH(NOLOCK)
					INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
				WHERE SED.DELETEDDATE IS NULL AND SED.CREATEDDATE < @AsOnDate
				GROUP BY SED.ITEMCOSTPRICEID
			) MAXSE ON MAXSE.ITEMCOSTPRICEID = MAXICP.ITEMCOSTPRICEID
		LEFT JOIN STOCKENTRY SE ON SE.STOCKENTRYID = MAXSE.STOCKENTRYID

	UPDATE AODSS
	SET AODSS.SUPPLIERID = SE.SUPPLIERID
	FROM
		#ASONDATESTOCK AODSS
		INNER JOIN ITEM I ON I.ITEMID = AODSS.ITEMID
		INNER JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID
		INNER JOIN
			(
				SELECT IC.ITEMID, MAX(SE.STOCKENTRYID) STOCKENTRYID
				FROM
					STOCKENTRYDETAIL SED WITH(NOLOCK)
					INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
					INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID					
				WHERE SED.DELETEDDATE IS NULL AND SED.CREATEDDATE < @AsOnDate
				GROUP BY IC.ITEMID			
			) MAXSE ON MAXSE.ITEMID = PITEM.ITEMID
		INNER JOIN STOCKENTRY SE ON SE.STOCKENTRYID = MAXSE.STOCKENTRYID
	WHERE AODSS.SUPPLIERID IS NULL
		


	SELECT B.BRANCHNAME, B.BRANCHCODE, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, TB.BRANDNAME, TM.MANUFACTURERNAME, CLS.CLASSIFICATIONNAME, ISUBCLS.SUBCLASSIFICATIONNAME,
		I.SKUCODE,I.VENDORSKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE, GST.GSTCODE 'GST Code'
		, LICP.COSTPRICEWOT LATESTCOSTPRICEWOT, LICP.COSTPRICEWT - LICP.COSTPRICEWOT AS LATESTCOSTPRICETAX, LICP.COSTPRICEWT LATESTCOSTPRICEWT
		, AICP.COSTPRICEWOT AVGCOSTPRICEWOT, AICP.COSTPRICEWT - AICP.COSTPRICEWOT AS AVGCOSTPRICETAX, AICP.COSTPRICEWT AVGCOSTPRICEWT
		, CAST(AODSS.QTYORWGHT AS DECIMAL(18,2)) QTYORWGHT
		, CAST(AODSS.QTYORWGHT * LICP.COSTPRICEWOT AS DECIMAL(18,2)) AS TOTALLATESTCOSTPRICEWOT, CAST(AODSS.QTYORWGHT * LICP.COSTPRICEWT AS DECIMAL(18,2)) AS TOTALLATESTCOSTPRICEWT
		, CAST(AODSS.QTYORWGHT * AICP.COSTPRICEWOT AS DECIMAL(18,2)) AS TOTALAVGCOSTPRICEWOT, CAST(AODSS.QTYORWGHT * AICP.COSTPRICEWT AS DECIMAL(18,2)) AS TOTALAVGCOSTPRICEWT
		, DLR.DEALERNAME
	FROM
		#ASONDATESTOCK AODSS
		INNER JOIN BRANCH B ON B.BRANCHID = AODSS.BRANCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = AODSS.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID AND @IncludeBrand = 1
		LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID AND @IncludeBrand = 1
		--LEFT JOIN IPICPView ICPVW ON ICPVW.ITEMPRICEID = IP.ITEMPRICEID
		--LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = AODSS.ITEMCOSTPRICEID
		--LEFT JOIN AVGCOSTPRICE ICP ON ICP.ITEMPRICEID = IP.ITEMPRICEID AND ICP.AVGCPDATE = @AvgCPDate
		LEFT JOIN 
			(
				SELECT IC.ITEMCODEID, IP.MRP, MAX(ICPINNER.ITEMCOSTPRICEID) MAXITEMCOSTPRICEID
				FROM
					ITEMCOSTPRICE ICPINNER
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICPINNER.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				WHERE
					IP.DELETEDDATE IS NULL 
					AND ICPINNER.DELETEDDATE IS NULL
				GROUP BY IC.ITEMCODEID, IP.MRP
			) MAXLICP ON MAXLICP.ITEMCODEID = IC.ITEMCODEID AND MAXLICP.MRP = IP.MRP AND @IncludeLatestCP = 1
		LEFT JOIN ITEMCOSTPRICE LICP ON LICP.ITEMCOSTPRICEID = MAXLICP.MAXITEMCOSTPRICEID AND @IncludeLatestCP = 1
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.ITEMPRICEID = IP.ITEMPRICEID AND AICP.AVGCPDATE = @AvgCPDate AND @IncludeAvgCP = 1
		LEFT JOIN TBLDEALER DLR ON DLR.DEALERID = AODSS.SUPPLIERID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		LEFT JOIN ITEMCLASSIFICATION CLS ON CLS.CLASSIFICATIONID = I.CLASSIFICATIONID AND @IncludeClassification = 1
		LEFT JOIN ITEMSUBCLASSIFICATION ISUBCLS ON ISUBCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID AND @IncludeClassification = 1
	WHERE AODSS.QTYORWGHT <> 0
	ORDER BY 1, 3, 4, 5, 6	
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_ASOFDATE_BRANCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
