CREATE PROC [dbo].[USP_RPT_STOCK_ASOFDATE_BRANCH]
(
    @AsOnDate DATE,
    @BranchID NVARCHAR(1000),
    @ITEMID INT = 0,
    @CategoryID VARCHAR(500),
    @IncludeCategory BIT = 0,
    @IncludeClassification BIT = 0,
    @IncludeHSN BIT = 0,
    @IncludeLatestCP BIT = 1,
    @IncludeAvgCP BIT = 1,
    @IncludeBrand BIT = 0,
	@IncludeItemCodeMRP BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    EXEC [dbo].[USP_RPT_STOCK_ASOFDATE_CORE]
        @AsOnDate = @AsOnDate,
        @BranchID = @BranchID,
        @ITEMID = @ITEMID,
        @CategoryID = @CategoryID,
        @IncludeCategory = @IncludeCategory,
        @IncludeClassification = @IncludeClassification,
        @IncludeHSN = @IncludeHSN,
        @IncludeLatestCP = @IncludeLatestCP,
        @IncludeAvgCP = @IncludeAvgCP,
        @IncludeBrand = @IncludeBrand,
		@IncludeItemCodeMRP = @IncludeItemCodeMRP,
        @ReportType = 'B';
END
