/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_ASOFDATE_CORE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCK_ASOFDATE_CORE]
(
    @AsOnDate DATE,
    @BranchID NVARCHAR(1000),
    @ITEMID INT = 0,
    @CategoryID VARCHAR(500),
    @IncludeCategory BIT = 0,
    @IncludeClassification BIT = 0,
    @IncludeHSN BIT = 0,
    @IncludeLatestCP BIT = 1,
    @IncludeAvgCP BIT = 1,
    @IncludeBrand BIT = 0,
    @ReportType CHAR(1),
    @IncludeItemCodeMRP BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @AsOnDateExclusive DATETIME = DATEADD(DAY, 1, CAST(@AsOnDate AS DATETIME)),
        @FinYearStartDate DATE = '2024-04-01',
        @AvgCPDate DATE;

    SELECT @AvgCPDate = DATEFROMPARTS(YEAR(@AsOnDate), MONTH(@AsOnDate), 1);
	
    CREATE TABLE #CATEGORY (CATEGORYID INT NOT NULL PRIMARY KEY);
    CREATE TABLE #BRANCH (BRANCHID INT NOT NULL PRIMARY KEY);

    INSERT INTO #CATEGORY (CATEGORYID)
    SELECT DISTINCT TRY_CONVERT(INT, ITEM)
    FROM dbo.SplitString(@CategoryID, ',')
    WHERE TRY_CONVERT(INT, ITEM) IS NOT NULL;


    IF NOT EXISTS (SELECT 1 FROM #CATEGORY)
    BEGIN
        INSERT INTO #CATEGORY (CATEGORYID)
        SELECT CATEGORYID FROM TBLCATEGORY WHERE DELETEDDATE IS NULL;
    END

    INSERT INTO #BRANCH (BRANCHID)
    SELECT DISTINCT B.BRANCHID
    FROM dbo.SplitString(@BranchID, ',') BR
    INNER JOIN BRANCH B ON B.BRANCHID = TRY_CONVERT(INT, BR.ITEM)
    WHERE B.DELETEDDATE IS NULL
      AND 
	  (
        (@ReportType = 'W' AND B.BRANCHID = 45)
        OR (@ReportType = 'D' AND B.BRANCHID = 100)
		OR (@ReportType = 'B' AND B.BRANCHID NOT IN (45, 91, 92, 97, 100, 103) AND ISNULL(B.ISWAREHOUSE, 0) = 0)
		);

    CREATE TABLE #ReportItem
    (
        ITEMID INT NOT NULL PRIMARY KEY,
        CATEGORYID INT NOT NULL,
        SUBCATEGORYID INT NULL,
        ISOPENITEM BIT NOT NULL
    );

    INSERT INTO #ReportItem (ITEMID, CATEGORYID, SUBCATEGORYID, ISOPENITEM)
    SELECT I.ITEMID, I.CATEGORYID, I.SUBCATEGORYID, ISNULL(I.ISOPENITEM, 0)
    FROM ITEM I
		INNER JOIN #CATEGORY C ON C.CATEGORYID = I.CATEGORYID
    WHERE I.DELETEDDATE IS NULL
		AND (@ITEMID = 0 OR I.ITEMID = @ITEMID);

    CREATE TABLE #ItemCountingDate
    (
        BRANCHID INT NOT NULL,
        ITEMID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, ITEMID)
    );

    INSERT INTO #ItemCountingDate (BRANCHID, ITEMID, COUNTINGDATE)
    SELECT CA.BRANCHID, IC.ITEMID, MAX(CAI.CREATEDDATE)
    FROM COUNTINGAPPROVALITEM CAI
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CAI.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
		INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
    WHERE CAI.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, IC.ITEMID;

    CREATE TABLE #SubCategoryCountingDate
    (
        BRANCHID INT NOT NULL,
        SUBCATEGORYID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, SUBCATEGORYID)
    );

    INSERT INTO #SubCategoryCountingDate (BRANCHID, SUBCATEGORYID, COUNTINGDATE)
    SELECT CA.BRANCHID, CAC.SUBCATEGORYID, MAX(CAC.CREATEDDATE)
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
		INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
    WHERE CAC.SUBCATEGORYID IS NOT NULL
		AND CAC.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, CAC.SUBCATEGORYID;

    CREATE TABLE #CategoryCountingDate
    (
        BRANCHID INT NOT NULL,
        CATEGORYID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, CATEGORYID)
    );

    INSERT INTO #CategoryCountingDate (BRANCHID, CATEGORYID, COUNTINGDATE)
    SELECT CA.BRANCHID, CAC.CATEGORYID, MAX(CAC.CREATEDDATE)
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
		INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
    WHERE CAC.CATEGORYID IS NOT NULL
		AND CAC.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, CAC.CATEGORYID;

    CREATE TABLE #Baseline
    (
        BRANCHID INT NOT NULL,
        ITEMID INT NOT NULL,
        CASCADEDATE DATETIME NULL,
        COUNTINGDATE DATETIME NOT NULL,
        PRIMARY KEY (BRANCHID, ITEMID)
    );

    INSERT INTO #Baseline (BRANCHID, ITEMID, CASCADEDATE, COUNTINGDATE)
    SELECT
        B.BRANCHID,
        RI.ITEMID,
        D.LASTCOUNTINGDATE,
        CASE
            WHEN ISNULL(D.LASTCOUNTINGDATE, '19000101') < @FinYearStartDate
                THEN CAST(@FinYearStartDate AS DATETIME)
            ELSE D.LASTCOUNTINGDATE
        END
    FROM #BRANCH B
		CROSS JOIN #ReportItem RI
		LEFT JOIN #ItemCountingDate ICD ON ICD.BRANCHID = B.BRANCHID AND ICD.ITEMID = RI.ITEMID
		LEFT JOIN #SubCategoryCountingDate SCD ON SCD.BRANCHID = B.BRANCHID AND SCD.SUBCATEGORYID = RI.SUBCATEGORYID
		LEFT JOIN #CategoryCountingDate CCD ON CCD.BRANCHID = B.BRANCHID AND CCD.CATEGORYID = RI.CATEGORYID
		CROSS APPLY
		(
			SELECT CASE
				WHEN SCD.COUNTINGDATE > ISNULL(ICD.COUNTINGDATE, '19000101') THEN SCD.COUNTINGDATE
				WHEN ICD.COUNTINGDATE IS NOT NULL THEN ICD.COUNTINGDATE
				ELSE CCD.COUNTINGDATE
			END AS LASTCOUNTINGDATE
		) D;

    CREATE TABLE #Movement
    (
        BRANCHID INT NOT NULL,
        ITEMPRICEID INT NOT NULL,
        ITEMCODEID INT NOT NULL,
        ITEMID INT NOT NULL,
        CATEGORYID INT NOT NULL,
        ISOPENITEM BIT NOT NULL,
		CASCADEDATE DATETIME NULL,
        COUNTINGDATE DATETIME NOT NULL,
        OPENINGSTOCK DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKENTRY DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKDISPATCHIN DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKDISPATCHOUT DECIMAL(18, 2) NOT NULL DEFAULT 0,
        CUSTOMERREFUND DECIMAL(18, 2) NOT NULL DEFAULT 0,
        BRANCHREFUND DECIMAL(18, 2) NOT NULL DEFAULT 0,
        SUPPLIERRETURNS DECIMAL(18, 2) NOT NULL DEFAULT 0,
        SALE DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKADJUSTMENT DECIMAL(18, 2) NOT NULL DEFAULT 0,
        PRIMARY KEY (BRANCHID, ITEMPRICEID)
    );

    INSERT INTO #Movement (BRANCHID, ITEMPRICEID, ITEMCODEID, ITEMID, CATEGORYID, ISOPENITEM, CASCADEDATE, COUNTINGDATE)
    SELECT
        BL.BRANCHID,
        IP.ITEMPRICEID,
        IC.ITEMCODEID,
        I.ITEMID,
        I.CATEGORYID,
        ISNULL(I.ISOPENITEM, 0),
        BL.CASCADEDATE,
        BL.COUNTINGDATE
    FROM #Baseline BL
		INNER JOIN #ReportItem RI ON RI.ITEMID = BL.ITEMID
		INNER JOIN ITEM I ON I.ITEMID = RI.ITEMID
		INNER JOIN ITEMCODE IC ON IC.ITEMID = RI.ITEMID
		INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
    WHERE IP.ITEMPRICEID IS NOT NULL;

    UPDATE M
    SET M.OPENINGSTOCK = CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SS.FYOPENINGWEIGHTINKGS, 0) ELSE ISNULL(SS.FYOPENINGQUANTITY, 0) END
    FROM #Movement M
		INNER JOIN STOCKSUMMARY SS ON SS.BRANCHID = M.BRANCHID AND SS.ITEMPRICEID = M.ITEMPRICEID
    WHERE ISNULL(M.CASCADEDATE, '1900-01-01') < @FinYearStartDate;

    UPDATE M
    SET M.OPENINGSTOCK = CASE WHEN M.ISOPENITEM = 1 THEN OPN.WEIGHTINKGS ELSE OPN.QUANTITY END
    FROM #Movement M
		INNER JOIN
		(
			SELECT
				SC.BRANCHID,
				SCD.ITEMPRICEID,
				SUM(ISNULL(SCD.QUANTITY, 0)) AS QUANTITY,
				SUM(ISNULL(SCD.WEIGHTINKGS, 0)) AS WEIGHTINKGS
			FROM STOCKCOUNTING SC
				INNER JOIN STOCKCOUNTINGDETAIL SCD ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
				INNER JOIN #Movement MI ON MI.BRANCHID = SC.BRANCHID
					AND MI.ITEMPRICEID = SCD.ITEMPRICEID
					AND CAST(SC.STOCKACCEPTEDDATE AS DATE) >= CAST(MI.CASCADEDATE AS DATE)
			WHERE SC.DELETEDDATE IS NULL
					AND SCD.DELETEDDATE IS NULL
					AND ISNULL(SC.STATUS, 0) IN (2, 3)
					AND SC.STOCKACCEPTEDDATE < @AsOnDateExclusive
					AND MI.CASCADEDATE >= @FinYearStartDate
			GROUP BY SC.BRANCHID, SCD.ITEMPRICEID
    ) OPN ON OPN.BRANCHID = M.BRANCHID AND OPN.ITEMPRICEID = M.ITEMPRICEID;

    CREATE TABLE #Txn
    (
        BRANCHID INT NOT NULL,
        ITEMPRICEID INT NOT NULL,
        TXNDATE DATETIME NOT NULL,
        QTY DECIMAL(18, 2) NOT NULL
    );

    CREATE CLUSTERED INDEX IX_Txn_Branch_ItemPrice_Date
        ON #Txn (BRANCHID, ITEMPRICEID, TXNDATE);

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SE.RECEIVINGBRANCHID,
        ICP.ITEMPRICEID,
        SE.UPDATEDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SED.WEIGHTINKGS, 0) ELSE ISNULL(SED.QUANTITY, 0) END)
    FROM STOCKENTRY SE
		INNER JOIN STOCKENTRYDETAIL SED ON SED.STOCKENTRYID = SE.STOCKENTRYID
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SE.RECEIVINGBRANCHID AND M.ITEMPRICEID = ICP.ITEMPRICEID
    WHERE ISNULL(SE.STATUS, 0) = 1
		AND SE.DELETEDDATE IS NULL
		AND SED.DELETEDDATE IS NULL
		AND SE.UPDATEDATE >= @FinYearStartDate
		AND SE.UPDATEDATE < @AsOnDateExclusive
    GROUP BY SE.RECEIVINGBRANCHID, ICP.ITEMPRICEID, SE.UPDATEDATE;

    UPDATE M
    SET M.STOCKENTRY = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn(BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SD.TOBRANCHID,
        IP.ITEMPRICEID,
        SD.STATUSAPPROVEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SDD.WEIGHTINKGS, 0) ELSE ISNULL(SDD.DISPATCHQUANTITY, 0) END)
    FROM STOCKDISPATCH SD
		INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SD.TOBRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE TRY_CONVERT(INT, SD.STATUS) = 2
		AND ISNULL(SDD.ISACCEPTED, 0) = 1
		AND SD.DELETEDDATE IS NULL
		AND SDD.DELETEDDATE IS NULL
		AND SD.STATUSAPPROVEDDATE >= @FinYearStartDate
		AND SD.STATUSAPPROVEDDATE < @AsOnDateExclusive
    GROUP BY SD.TOBRANCHID, IP.ITEMPRICEID, SD.STATUSAPPROVEDDATE;

    UPDATE M
    SET M.STOCKDISPATCHIN = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
				INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SD.FROMBRANCHID,
        IP.ITEMPRICEID,
        SD.UPDATEDATE,
		SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SDD.WEIGHTINKGS, 0) ELSE ISNULL(SDD.DISPATCHQUANTITY, 0) END)
    FROM STOCKDISPATCH SD
		INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SD.FROMBRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE TRY_CONVERT(INT, SD.STATUS) <> 0
		AND SD.DELETEDDATE IS NULL
		AND SDD.DELETEDDATE IS NULL
		AND SD.UPDATEDATE >= @FinYearStartDate
		AND SD.UPDATEDATE < @AsOnDateExclusive
    GROUP BY SD.FROMBRANCHID, IP.ITEMPRICEID, SD.UPDATEDATE;

    UPDATE M
    SET M.STOCKDISPATCHOUT = TX.QTY
    FROM #Movement M 
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        BC.BRANCHID,
        IP.ITEMPRICEID,
        PBD.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(PBD.WEIGHTINKGS, 0) ELSE ISNULL(PBD.QUANTITY, 0) END)
    FROM POS_BILLDETAIL PBD
		INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = BC.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE PB.BILLSTATUS = 1
		AND PBD.DELETEDDATE IS NULL
		AND PBD.DAYCLOSUREID IS NOT NULL
		AND PBD.CREATEDDATE >= @FinYearStartDate
		AND PBD.CREATEDDATE < @AsOnDateExclusive
    GROUP BY BC.BRANCHID, IP.ITEMPRICEID, PBD.CREATEDDATE;

    UPDATE M
    SET M.SALE = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID,TXNDATE, QTY)
    SELECT
        BC.BRANCHID,
        IP.ITEMPRICEID,
        CR.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(CR.REFUNDWEIGHTINKGS, 0) ELSE ISNULL(CR.REFUNDQUANTITY, 0) END)
    FROM POS_CREFUND CR
		INNER JOIN POS_BILLDETAIL PBD ON PBD.BRANCHCOUNTERID = CR.COUNTERID AND PBD.BILLDETAILID = CR.BILLDETAILID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = CR.COUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = BC.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE CR.DELETEDDATE IS NULL
		AND CR.DAYCLOSUREID IS NOT NULL
		AND CR.CREATEDDATE >= @FinYearStartDate
		AND CR.CREATEDDATE < @AsOnDateExclusive
    GROUP BY BC.BRANCHID, IP.ITEMPRICEID, CR.CREATEDDATE;

    UPDATE M
    SET M.CUSTOMERREFUND = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY 
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    IF @ReportType = 'B'
    BEGIN
        INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
        SELECT
            BR.BRANCHID,
            IP.ITEMPRICEID,
            BR.UPDATEDDATE,
            SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(BRD.WEIGHTINKGS, 0) ELSE ISNULL(BRD.QUANTITY, 0) END)
        FROM POS_BREFUND BR
			INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
			INNER JOIN #Movement M ON M.BRANCHID = BR.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
			AND BRD.REASONID <> 5
			AND BR.DELETEDDATE IS NULL
			AND BRD.DELETEDDATE IS NULL      
			AND BR.UPDATEDDATE >= @FinYearStartDate
			AND BR.UPDATEDDATE < @AsOnDateExclusive
        GROUP BY BR.BRANCHID, IP.ITEMPRICEID, BR.UPDATEDDATE;
    END
    ELSE
    BEGIN
        INSERT INTO #Txn (BRANCHID, ITEMPRICEID,TXNDATE, QTY)
        SELECT
            ROR.LOCATIONTOMOVESTOCK,
            PIP.ITEMPRICEID,
            BR.ACCEPTEDDATE,
            SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(BRD.WEIGHTINKGS, 0) ELSE ISNULL(BRD.QUANTITY, 0) END)
        FROM POS_BREFUND BR
			INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
			INNER JOIN REASONFORREFUND ROR ON ROR.REASONID = BRD.REASONID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
			INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			INNER JOIN #Movement M ON M.BRANCHID = ROR.LOCATIONTOMOVESTOCK AND M.ITEMPRICEID = PIP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
			AND ISNULL(BR.IsAccepted, 0) = 1
			AND BR.DELETEDDATE IS NULL
			AND BRD.DELETEDDATE IS NULL
			AND BRD.REASONID <> 5
			AND (I.PARENTITEMID IS NULL OR ISNULL(I.ISOPENITEM, 0) = 1 OR ISNULL(ROR.MERGETOPARENT, 0) = 0)
			AND BR.ACCEPTEDDATE >= @FinYearStartDate
			AND BR.ACCEPTEDDATE < @AsOnDateExclusive
        GROUP BY ROR.LOCATIONTOMOVESTOCK, PIP.ITEMPRICEID, BR.ACCEPTEDDATE;

        INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
        SELECT
			ROR.LOCATIONTOMOVESTOCK,
			PARENTIP.ITEMPRICEID,
			BR.ACCEPTEDDATE,
			SUM(ISNULL(BRD.QUANTITY, 0) * ISNULL(U.MULTIPLIER, 0))
        FROM POS_BREFUND BR
			INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
			INNER JOIN REASONFORREFUND ROR ON ROR.REASONID = BRD.REASONID AND ISNULL(ROR.MERGETOPARENT, 0) = 1
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID
			INNER JOIN ITEMCODE PIC ON PIC.ITEMID = PITEM.ITEMID
			INNER JOIN ITEMPRICE PARENTIP ON PARENTIP.ITEMCODEID = PIC.ITEMCODEID
				AND PARENTIP.DELETEDDATE IS NULL
				AND ISNULL(PARENTIP.PARENTITEMPRICEID, 0) = 0
			LEFT JOIN UOM U ON U.UOMID = I.UOMID
			INNER JOIN #Movement M ON M.BRANCHID = ROR.LOCATIONTOMOVESTOCK AND M.ITEMPRICEID = PARENTIP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
			AND ISNULL(BR.IsAccepted, 0) = 1
			AND BR.DELETEDDATE IS NULL
			AND BRD.DELETEDDATE IS NULL
			AND BRD.REASONID <> 5
			AND I.PARENTITEMID IS NOT NULL
			AND ISNULL(I.ISOPENITEM, 0) = 0
			AND BR.ACCEPTEDDATE >= @FinYearStartDate
			AND BR.ACCEPTEDDATE < @AsOnDateExclusive
        GROUP BY ROR.LOCATIONTOMOVESTOCK, PARENTIP.ITEMPRICEID, BR.ACCEPTEDDATE;
    END

    UPDATE M
    SET M.BRANCHREFUND = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SR.BRANCHID,
        ICP.ITEMPRICEID,
        SR.CNINITIATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SRD.WEIGHTINKGS, 0) ELSE ISNULL(SRD.QUANTITY, 0) END)
    FROM SUPPLIERRETURNS SR
		INNER JOIN SUPPLIERRETURNSDETAIL SRD ON SRD.SUPPLIERRETURNSID = SR.SUPPLIERRETURNSID
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SR.BRANCHID AND M.ITEMPRICEID = ICP.ITEMPRICEID
    WHERE SR.DELETEDDATE IS NULL
		AND SRD.DELETEDDATE IS NULL
		AND SR.CNINITIATEDDATE >= @FinYearStartDate
		AND SR.CNINITIATEDDATE < @AsOnDateExclusive
    GROUP BY SR.BRANCHID, ICP.ITEMPRICEID, SR.CNINITIATEDDATE;

    UPDATE M
    SET M.SUPPLIERRETURNS = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SA.BRANCHID,
        IP.ITEMPRICEID,
        SA.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SA.WEIGHTINKGS, 0) - ISNULL(SA.PREVWEIGHTINKGS, 0) ELSE ISNULL(SA.QUANTITY, 0) - ISNULL(SA.PREVQUANTITY, 0) END)
    FROM STOCKADJUSTMENT SA
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SA.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SA.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE SA.CREATEDDATE >= @FinYearStartDate
		AND SA.CREATEDDATE < @AsOnDateExclusive
    GROUP BY SA.BRANCHID, IP.ITEMPRICEID, SA.CREATEDDATE;

    UPDATE M
    SET M.STOCKADJUSTMENT = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    -- COSTKEY is ITEMPRICEID for detail mode, otherwise ITEMID.
    CREATE TABLE #LatestItemCost
    (
        COSTKEY INT NOT NULL PRIMARY KEY,
        COSTPRICEWOT DECIMAL(18, 4) NULL,
        COSTPRICEWT DECIMAL(18, 4) NULL
    );

    ;WITH LatestCost AS
    (
        SELECT
            CASE WHEN @IncludeItemCodeMRP = 1 THEN ICP.ITEMPRICEID ELSE IC.ITEMID END AS COSTKEY,
            ICP.COSTPRICEWOT,
            ICP.COSTPRICEWT,
            ROW_NUMBER() OVER
            (
                PARTITION BY CASE WHEN @IncludeItemCodeMRP = 1 THEN ICP.ITEMPRICEID ELSE IC.ITEMID END
                ORDER BY ICP.ITEMCOSTPRICEID DESC
            ) AS RN
        FROM ITEMCOSTPRICE ICP
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
        WHERE ICP.DELETEDDATE IS NULL
			AND @IncludeLatestCP = 1
    )

    INSERT INTO #LatestItemCost (COSTKEY, COSTPRICEWOT, COSTPRICEWT)
    SELECT COSTKEY, COSTPRICEWOT, COSTPRICEWT
    FROM LatestCost
    WHERE RN = 1;

    CREATE TABLE #AverageItemCost
    (
        COSTKEY INT NOT NULL PRIMARY KEY,
        COSTPRICEWOT DECIMAL(18, 4) NULL,
        COSTPRICEWT DECIMAL(18, 4) NULL
    );

    -- Aggregate stored averages before matching them to report rows.
    SELECT
        AICP.ITEMCODEID,
        AICP.MRP,
        CONVERT(DECIMAL(18, 4), AVG(CONVERT(DECIMAL(18, 4), AICP.COSTPRICEWOT))) AS COSTPRICEWOT,
        CONVERT(DECIMAL(18, 4), AVG(CONVERT(DECIMAL(18, 4), AICP.COSTPRICEWT))) AS COSTPRICEWT
    INTO #AverageItemMRPCost
    FROM AVGCOSTPRICE AICP
        INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = AICP.ITEMCODEID
        INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
    WHERE AICP.AVGCPDATE = @AvgCPDate
        AND @IncludeAvgCP = 1
        AND @IncludeItemCodeMRP = 1
    GROUP BY AICP.ITEMCODEID, AICP.MRP;

    IF ISNULL(@IncludeItemCodeMRP, 0) = 0
    BEGIN
        INSERT INTO #AverageItemCost (COSTKEY, COSTPRICEWOT, COSTPRICEWT)
        SELECT
            IC.ITEMID,
            AVG(CONVERT(DECIMAL(18, 4), AICP.COSTPRICEWOT)),
            AVG(CONVERT(DECIMAL(18, 4), AICP.COSTPRICEWT))
        FROM AVGCOSTPRICE AICP
            INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = AICP.ITEMCODEID
            INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
        WHERE AICP.AVGCPDATE = @AvgCPDate
            AND @IncludeAvgCP = 1
        GROUP BY IC.ITEMID;
    END;

    SELECT
        I.SKUCODE,
        IC.ITEMCODE,
        I.ITEMNAME,
        GST.GSTCODE,
        IP.MRP,
        CASE WHEN @IncludeCategory = 1 THEN CAT.CATEGORYNAME ELSE NULL END AS CATEGORYNAME,
        CASE WHEN @IncludeCategory = 1 THEN SC.SUBCATEGORYNAME ELSE NULL END AS SUBCATEGORYNAME,
        CASE WHEN @IncludeClassification = 1 THEN ICL.CLASSIFICATIONNAME ELSE NULL END AS CLASSIFICATIONNAME,
        CASE WHEN @IncludeClassification = 1 THEN ISCL.SUBCLASSIFICATIONNAME ELSE NULL END AS SUBCLASSIFICATIONNAME,
        CASE WHEN @IncludeHSN = 1 THEN I.HSNCODE ELSE NULL END AS HSNCODE,
        CASE WHEN @IncludeLatestCP = 1 THEN LICP.COSTPRICEWOT ELSE NULL END AS LATESTCOSTPRICEWOT,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWT, 0) - ISNULL(LICP.COSTPRICEWOT, 0) ELSE NULL END AS LATESTCOSTPRICETAX,
        CASE WHEN @IncludeLatestCP = 1 THEN LICP.COSTPRICEWT ELSE NULL END AS LATESTCOSTPRICEWT,
        CASE WHEN @IncludeAvgCP = 1 THEN AICP.COSTPRICEWOT ELSE NULL END AS AVGCOSTPRICEWOT,
        CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWT, 0) - ISNULL(AICP.COSTPRICEWOT, 0) ELSE NULL END AS AVGCOSTPRICETAX,
        CASE WHEN @IncludeAvgCP = 1 THEN AICP.COSTPRICEWT ELSE NULL END AS AVGCOSTPRICEWT,
        M.OPENINGSTOCK,
        M.STOCKENTRY,
        M.STOCKDISPATCHIN,
        M.STOCKDISPATCHOUT,
        M.CUSTOMERREFUND,
        M.BRANCHREFUND,
        M.SUPPLIERRETURNS,
        M.SALE,
        M.STOCKADJUSTMENT,
        CS.CURRENTSTOCK,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWOT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWOT,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWT,
        CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWOT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWOT,
        CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWT,
        CASE WHEN @IncludeBrand = 1 THEN BRD.BRANDNAME ELSE NULL END AS BRANDNAME,
        CASE WHEN @IncludeBrand = 1 THEN MFR.MANUFACTURERNAME ELSE NULL END AS MANUFACTURERNAME,
        B.BRANCHNAME,
        M.COUNTINGDATE,
        M.BRANCHID,
        M.ITEMPRICEID,
        M.ITEMCODEID,
        M.ITEMID,
        M.CATEGORYID
    INTO #ResultDetail
    FROM #Movement M
		INNER JOIN BRANCH B ON B.BRANCHID = M.BRANCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = M.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON SC.SUBCATEGORYID = I.SUBCATEGORYID AND SC.DELETEDDATE IS NULL
		LEFT JOIN ITEMCLASSIFICATION ICL ON ICL.CLASSIFICATIONID = I.CLASSIFICATIONID AND ICL.DELETEDDATE IS NULL
		LEFT JOIN ITEMSUBCLASSIFICATION ISCL ON ISCL.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID AND ISCL.DELETEDDATE IS NULL
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = I.GSTID AND GST.DELETEDDATE IS NULL
		LEFT JOIN TBLBRAND BRD ON BRD.BRANDID = I.BRANDID
		LEFT JOIN TBLMANUFACTURER MFR ON MFR.MANUFACTURERID = I.MANUFACTURERID
		LEFT JOIN #LatestItemCost LICP
            ON LICP.COSTKEY = CASE WHEN @IncludeItemCodeMRP = 1 THEN M.ITEMPRICEID ELSE M.ITEMID END
            AND @IncludeLatestCP = 1
		LEFT JOIN #AverageItemCost SKUCP
            ON SKUCP.COSTKEY = M.ITEMID
            AND ISNULL(@IncludeItemCodeMRP, 0) = 0
            AND @IncludeAvgCP = 1
        LEFT JOIN #AverageItemMRPCost MRPCP
            ON MRPCP.ITEMCODEID = M.ITEMCODEID
            AND MRPCP.MRP = IP.MRP
            AND @IncludeItemCodeMRP = 1
            AND @IncludeAvgCP = 1
        CROSS APPLY
        (
            SELECT
                CASE WHEN @IncludeItemCodeMRP = 1 THEN MRPCP.COSTPRICEWOT ELSE SKUCP.COSTPRICEWOT END AS COSTPRICEWOT,
                CASE WHEN @IncludeItemCodeMRP = 1 THEN MRPCP.COSTPRICEWT ELSE SKUCP.COSTPRICEWT END AS COSTPRICEWT
        ) AICP
		CROSS APPLY
		(
			SELECT
				M.OPENINGSTOCK + M.STOCKENTRY + M.STOCKDISPATCHIN + M.CUSTOMERREFUND
				+ M.STOCKADJUSTMENT - M.STOCKDISPATCHOUT - M.SUPPLIERRETURNS - M.SALE
				+ CASE WHEN @ReportType = 'B' THEN -M.BRANCHREFUND ELSE M.BRANCHREFUND END AS CURRENTSTOCK
		) CS
    WHERE M.OPENINGSTOCK <> 0
		OR M.STOCKENTRY <> 0
		OR M.STOCKDISPATCHIN <> 0
		OR M.STOCKDISPATCHOUT <> 0
		OR M.CUSTOMERREFUND <> 0
		OR M.BRANCHREFUND <> 0
		OR M.SUPPLIERRETURNS <> 0
		OR M.SALE <> 0
		OR M.STOCKADJUSTMENT <> 0;

    IF @IncludeItemCodeMRP = 1
    BEGIN
        SELECT *
        FROM #ResultDetail
        ORDER BY BRANCHNAME, SKUCODE, ITEMCODE, MRP, ITEMPRICEID;
    END
    ELSE
    BEGIN
        ;WITH SKUResult AS
        (
            SELECT
                MAX(SKUCODE) AS SKUCODE,
                MAX(ITEMNAME) AS ITEMNAME,
                MAX(GSTCODE) AS GSTCODE,
                MAX(CATEGORYNAME) AS CATEGORYNAME,
                MAX(SUBCATEGORYNAME) AS SUBCATEGORYNAME,
                MAX(CLASSIFICATIONNAME) AS CLASSIFICATIONNAME,
                MAX(SUBCLASSIFICATIONNAME) AS SUBCLASSIFICATIONNAME,
                MAX(HSNCODE) AS HSNCODE,
                MAX(LATESTCOSTPRICEWOT) AS LATESTCOSTPRICEWOT,
                MAX(LATESTCOSTPRICETAX) AS LATESTCOSTPRICETAX,
                MAX(LATESTCOSTPRICEWT) AS LATESTCOSTPRICEWT,
                MAX(AVGCOSTPRICEWOT) AS AVGCOSTPRICEWOT,
                MAX(AVGCOSTPRICETAX) AS AVGCOSTPRICETAX,
                MAX(AVGCOSTPRICEWT) AS AVGCOSTPRICEWT,
                SUM(OPENINGSTOCK) AS OPENINGSTOCK,
                SUM(STOCKENTRY) AS STOCKENTRY,
                SUM(STOCKDISPATCHIN) AS STOCKDISPATCHIN,
                SUM(STOCKDISPATCHOUT) AS STOCKDISPATCHOUT,
                SUM(CUSTOMERREFUND) AS CUSTOMERREFUND,
                SUM(BRANCHREFUND) AS BRANCHREFUND,
                SUM(SUPPLIERRETURNS) AS SUPPLIERRETURNS,
                SUM(SALE) AS SALE,
                SUM(STOCKADJUSTMENT) AS STOCKADJUSTMENT,
                MAX(BRANDNAME) AS BRANDNAME,
                MAX(MANUFACTURERNAME) AS MANUFACTURERNAME,
                MAX(BRANCHNAME) AS BRANCHNAME,
                MAX(COUNTINGDATE) AS COUNTINGDATE,
                BRANCHID,
                ITEMID,
                MAX(CATEGORYID) AS CATEGORYID
            FROM #ResultDetail
            GROUP BY BRANCHID, ITEMID
        ),
        SKUResultWithStock AS
        (
            SELECT S.*,
                S.OPENINGSTOCK + S.STOCKENTRY + S.STOCKDISPATCHIN + S.CUSTOMERREFUND
                + S.STOCKADJUSTMENT - S.STOCKDISPATCHOUT - S.SUPPLIERRETURNS - S.SALE
                + CASE WHEN @ReportType = 'B' THEN -S.BRANCHREFUND ELSE S.BRANCHREFUND END AS CURRENTSTOCK
            FROM SKUResult S
            WHERE S.OPENINGSTOCK <> 0
               OR S.STOCKENTRY <> 0
               OR S.STOCKDISPATCHIN <> 0
               OR S.STOCKDISPATCHOUT <> 0
               OR S.CUSTOMERREFUND <> 0
               OR S.BRANCHREFUND <> 0
               OR S.SUPPLIERRETURNS <> 0
               OR S.SALE <> 0
               OR S.STOCKADJUSTMENT <> 0
        )

        SELECT
            S.SKUCODE,
            CAST(NULL AS VARCHAR(100)) AS ITEMCODE,
            S.ITEMNAME,
            S.GSTCODE,
            CAST(NULL AS DECIMAL(18, 2)) AS MRP,
            S.CATEGORYNAME,
            S.SUBCATEGORYNAME,
            S.CLASSIFICATIONNAME,
            S.SUBCLASSIFICATIONNAME,
            S.HSNCODE,
            S.LATESTCOSTPRICEWOT,
            S.LATESTCOSTPRICETAX,
            S.LATESTCOSTPRICEWT,
            S.AVGCOSTPRICEWOT,
            S.AVGCOSTPRICETAX,
            S.AVGCOSTPRICEWT,
            S.OPENINGSTOCK,
            S.STOCKENTRY,
            S.STOCKDISPATCHIN,
            S.STOCKDISPATCHOUT,
            S.CUSTOMERREFUND,
            S.BRANCHREFUND,
            S.SUPPLIERRETURNS,
            S.SALE,
            S.STOCKADJUSTMENT,
            S.CURRENTSTOCK,
            CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(S.LATESTCOSTPRICEWOT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWOT,
            CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(S.LATESTCOSTPRICEWT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWT,
            CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(S.AVGCOSTPRICEWOT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWOT,
            CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(S.AVGCOSTPRICEWT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWT,
            S.BRANDNAME,
            S.MANUFACTURERNAME,
            S.BRANCHNAME,
            S.COUNTINGDATE,
            S.BRANCHID,
            CAST(NULL AS INT) AS ITEMPRICEID,
            CAST(NULL AS INT) AS ITEMCODEID,
            S.ITEMID,
            S.CATEGORYID
        FROM SKUResultWithStock S
		WHERE S.CURRENTSTOCK <> 0
        ORDER BY S.BRANCHNAME, S.SKUCODE;
    END;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_ASOFDATE_CORE_BYITEMPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCK_ASOFDATE_CORE_BYITEMPRICE]
(
    @AsOnDate DATE,
    @BranchID NVARCHAR(1000),
    @ITEMID INT = 0,
    @CategoryID VARCHAR(500),
    @IncludeCategory BIT = 0,
    @IncludeClassification BIT = 0,
    @IncludeHSN BIT = 0,
    @IncludeLatestCP BIT = 1,
    @IncludeAvgCP BIT = 1,
    @IncludeBrand BIT = 0,
    @ReportType CHAR(1)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @AsOnDateExclusive DATETIME = DATEADD(DAY, 1, CAST(@AsOnDate AS DATETIME)),
        @FinYearStartDate DATE = '2024-04-01',
        @AvgCPDate DATE;

    SELECT @AvgCPDate = DATEFROMPARTS(YEAR(@AsOnDate), MONTH(@AsOnDate), 1);
	
    CREATE TABLE #CATEGORY (CATEGORYID INT NOT NULL PRIMARY KEY);
    CREATE TABLE #BRANCH (BRANCHID INT NOT NULL PRIMARY KEY);

    INSERT INTO #CATEGORY (CATEGORYID)
    SELECT DISTINCT TRY_CONVERT(INT, ITEM)
    FROM dbo.SplitString(@CategoryID, ',')
    WHERE TRY_CONVERT(INT, ITEM) IS NOT NULL;


    IF NOT EXISTS (SELECT 1 FROM #CATEGORY)
    BEGIN
        INSERT INTO #CATEGORY (CATEGORYID)
        SELECT CATEGORYID FROM TBLCATEGORY WHERE DELETEDDATE IS NULL;
    END

    INSERT INTO #BRANCH (BRANCHID)
    SELECT DISTINCT B.BRANCHID
    FROM dbo.SplitString(@BranchID, ',') BR
    INNER JOIN BRANCH B ON B.BRANCHID = TRY_CONVERT(INT, BR.ITEM)
    WHERE B.DELETEDDATE IS NULL
      AND (
            (@ReportType = 'W' AND B.BRANCHID = 45)
            OR (@ReportType = 'D' AND B.BRANCHID = 100)
     

       OR (@ReportType = 'B' AND B.BRANCHID NOT IN (45, 91, 92, 97, 100, 103) AND ISNULL(B.ISWAREHOUSE, 0) = 0)
          );

    CREATE TABLE #ReportItem
    (
        ITEMID INT NOT NULL PRIMARY KEY,
        CATEGORYID INT NOT NULL,
        SUBCATEGORYID INT NULL,
        ISOPENITEM BIT NOT NULL
    );

    INSERT INTO #ReportItem (ITEMID, CATEGORYID, SUBCATEGORYID, ISOPENITEM)
    SELECT I.ITEMID, I.CATEGORYID, I.SUBCATEGORYID, ISNULL(I.ISOPENITEM, 0)
    FROM ITEM I
    INNER JOIN #CATEGORY C ON C.CATEGORYID = I.CATEGORYID
    WHERE I.DELETEDDATE IS NULL
      AND (@ITEMID = 0 OR I.ITEMID = @ITEMID);

    CREATE TABLE #ItemCountingDate
    (
        BRANCHID INT NOT NULL,
        ITEMID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, ITEMID)
    );

    INSERT INTO #ItemCountingDate (BRANCHID, ITEMID, COUNTINGDATE)
    SELECT CA.BRANCHID, IC.ITEMID, MAX(CAI.CREATEDDATE)
    FROM COUNTINGAPPROVALITEM CAI
    INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
    INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CAI.ITEMPRICEID
    INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
    INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
    INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
    WHERE CAI.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, IC.ITEMID;

    CREATE TABLE #SubCategoryCountingDate
    (
        BRANCHID INT NOT NULL,
        SUBCATEGORYID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, SUBCATEGORYID)
    );

    INSERT INTO #SubCategoryCountingDate (BRANCHID, SUBCATEGORYID, COUNTINGDATE)
    SELECT CA.BRANCHID, CAC.SUBCATEGORYID, MAX(CAC.CREATEDDATE)
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
    INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
    INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
    WHERE CAC.SUBCATEGORYID IS NOT NULL
      AND CAC.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, CAC.SUBCATEGORYID;

    CREATE TABLE #CategoryCountingDate
    (
        BRANCHID INT NOT NULL,
        CATEGORYID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, CATEGORYID)
    );

    INSERT INTO #CategoryCountingDate (BRANCHID, CATEGORYID, COUNTINGDATE)
    SELECT CA.BRANCHID, CAC.CATEGORYID, MAX(CAC.CREATEDDATE)
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
    INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
    INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
    WHERE CAC.CATEGORYID IS NOT NULL
      AND CAC.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, CAC.CATEGORYID;

    CREATE TABLE #Baseline
    (
        BRANCHID INT NOT NULL,
        ITEMID INT NOT NULL,
        CASCADEDATE DATETIME NULL,
        COUNTINGDATE DATETIME NOT NULL,
        PRIMARY KEY (BRANCHID, ITEMID)
    );

    INSERT INTO #Baseline (BRANCHID, ITEMID, CASCADEDATE, COUNTINGDATE)
    SELECT
        B.BRANCHID,
        RI.ITEMID,
        D.LASTCOUNTINGDATE,
        CASE
            WHEN ISNULL(D.LASTCOUNTINGDATE, '19000101') < @FinYearStartDate
                THEN CAST(@FinYearStartDate AS DATETIME)
            ELSE D.LASTCOUNTINGDATE
        END
    FROM #BRANCH B
    CROSS JOIN #ReportItem RI
    LEFT JOIN #ItemCountingDate ICD ON ICD.BRANCHID = B.BRANCHID AND ICD.ITEMID = RI.ITEMID
    LEFT JOIN #SubCategoryCountingDate SCD ON SCD.BRANCHID = B.BRANCHID AND SCD.SUBCATEGORYID = RI.SUBCATEGORYID
    LEFT JOIN #CategoryCountingDate CCD ON CCD.BRANCHID = B.BRANCHID AND CCD.CATEGORYID = RI.CATEGORYID
    CROSS APPLY
    (
        SELECT CASE
            WHEN SCD.COUNTINGDATE > ISNULL(ICD.COUNTINGDATE, '19000101') THEN SCD.COUNTINGDATE
            WHEN ICD.COUNTINGDATE IS NOT NULL THEN ICD.COUNTINGDATE
            ELSE CCD.COUNTINGDATE
        END AS LASTCOUNTINGDATE
    ) D;

    CREATE TABLE #Movement
    (
        BRANCHID INT NOT NULL,
        ITEMPRICEID INT NOT NULL,
        ITEMCODEID INT NOT NULL,
        ITEMID INT NOT NULL,
        CATEGORYID INT NOT NULL,
        ISOPENITEM BIT NOT NULL,
		CASCADEDATE DATETIME NULL,
        COUNTINGDATE DATETIME NOT NULL,
        OPENINGSTOCK DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKENTRY DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKDISPATCHIN DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKDISPATCHOUT DECIMAL(18, 2) NOT NULL DEFAULT 0,
        CUSTOMERREFUND DECIMAL(18, 2) NOT NULL DEFAULT 0,
        BRANCHREFUND DECIMAL(18, 2) NOT NULL DEFAULT 0,
        SUPPLIERRETURNS DECIMAL(18, 2) NOT NULL DEFAULT 0,
        SALE DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKADJUSTMENT DECIMAL(18, 2) NOT NULL DEFAULT 0,
        PRIMARY KEY (BRANCHID, ITEMPRICEID)
    );

    INSERT INTO #Movement (BRANCHID, ITEMPRICEID, ITEMCODEID, ITEMID, CATEGORYID, ISOPENITEM, CASCADEDATE, COUNTINGDATE)
    SELECT
        BL.BRANCHID,
        IP.ITEMPRICEID,
        IC.ITEMCODEID,
        I.ITEMID,
        I.CATEGORYID,
        ISNULL(I.ISOPENITEM, 0),
        BL.CASCADEDATE,
        BL.COUNTINGDATE
    FROM #Baseline BL
    INNER JOIN #ReportItem RI ON RI.ITEMID = BL.ITEMID
    INNER JOIN ITEM I ON I.ITEMID = RI.ITEMID
    INNER JOIN ITEMCODE IC ON IC.ITEMID = RI.ITEMID
    INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
    WHERE IP.ITEMPRICEID IS NOT NULL;

    UPDATE M
    SET M.OPENINGSTOCK = CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SS.FYOPENINGWEIGHTINKGS, 0) ELSE ISNULL(SS.FYOPENINGQUANTITY, 0) END
    FROM #Movement M
	INNER JOIN STOCKSUMMARY SS ON SS.BRANCHID = M.BRANCHID AND SS.ITEMPRICEID = M.ITEMPRICEID
    WHERE ISNULL(M.CASCADEDATE, '1900-01-01') < @FinYearStartDate;

    UPDATE M
    SET M.OPENINGSTOCK = CASE WHEN M.ISOPENITEM = 1 THEN OPN.WEIGHTINKGS ELSE OPN.QUANTITY END
    FROM #Movement M
    INNER JOIN
    (
        SELECT
            SC.BRANCHID,
            SCD.ITEMPRICEID,
            SUM(ISNULL(SCD.QUANTITY, 0)) AS QUANTITY,
            SUM(ISNULL(SCD.WEIGHTINKGS, 0
	)) AS WEIGHTINKGS
        FROM STOCKCOUNTING SC
        INNER JOIN STOCKCOUNTINGDETAIL SCD ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
        INNER JOIN #Movement MI ON MI.BRANCHID = SC.BRANCHID
            AND MI.ITEMPRICEID = SCD.ITEMPRICEID
            AND CAST(SC.STOCKACCEPTEDDATE AS DATE) >= CAST(MI.CASCADEDATE AS DATE)
        WHERE SC.DELETEDDATE IS NULL
          AND SCD.DELETEDDATE IS NULL
          AND ISNULL(SC.STATUS, 0) IN (2, 3)
          AND SC.STOCKACCEPTEDDATE < @AsOnDateExclusive
          AND MI.CASCADEDATE >= @FinYearStartDate
        GROUP BY SC.BRANCHID, SCD.ITEMPRICEID
    ) OPN ON OPN.BRANCHID = M.BRANCHID AND OPN.ITEMPRICEID = M.ITEMPRICEID;

    CREATE TABLE #Txn
    (
        BRANCHID INT NOT NULL,
        ITEMPRICEID INT NOT NULL,
        TXNDATE DATETIME NOT NULL,
        QTY DECIMAL(18, 2) NOT NULL
    );

    CREATE CLUSTERED INDEX IX_Txn_Branch_ItemPrice_Date
        ON #Txn (BRANCHID, ITEMPRICEID, TXNDATE);

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SE.RECEIVINGBRANCHID,
        ICP.ITEMPRICEID,
        SE.UPDATEDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SED.WEIGHTINKGS, 0) ELSE ISNULL(SED.QUANTITY, 0) END)
    FROM STOCKENTRY SE
    INNER JOIN STOCKENTRYDETAIL SED ON SED.STOCKENTRYID = SE.STOCKENTRYID
    INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
    INNER JOIN #Movement M ON M.BRANCHID = SE.RECEIVINGBRANCHID AND M.ITEMPRICEID = ICP.ITEMPRICEID
    WHERE ISNULL(SE.STATUS, 0) = 1
      AND SE.DELETEDDATE IS NULL
      AND SED.DELETEDDATE IS NULL
      AND SE.UPDATEDATE >= @FinYearStartDate
      AND SE.UPDATEDATE < @AsOnDateExclusive
    GROUP BY SE.RECEIVINGBRANCHID, ICP.ITEMPRICEID, SE.UPDATEDATE;

    UPDATE M
    SET M.STOCKENTRY = TX.QTY
    FROM #Movement M
    INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
        FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn(BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SD.TOBRANCHID,
        IP.ITEMPRICEID,
        SD.STATUSAPPROVEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SDD.WEIGHTINKGS, 0) ELSE ISNULL(SDD.DISPATCHQUANTITY, 0) END)
    FROM STOCKDISPATCH SD
    INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
    INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
    INNER JOIN #Movement M ON M.BRANCHID = SD.TOBRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE TRY_CONVERT(INT, SD.STATUS) = 2
      AND ISNULL(SDD.ISACCEPTED, 0) = 1
      AND SD.DELETEDDATE IS NULL
      AND SDD.DELETEDDATE IS NULL
      AND SD.STATUSAPPROVEDDATE >= @FinYearStartDate
	AND SD.STATUSAPPROVEDDATE < @AsOnDateExclusive
    GROUP BY SD.TOBRANCHID, IP.ITEMPRICEID, SD.STATUSAPPROVEDDATE;

    UPDATE M
    SET M.STOCKDISPATCHIN = TX.QTY
    FROM #Movement M
    INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
        FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SD.FROMBRANCHID,
        IP.ITEMPRICEID,
        SD.UPDATEDATE,
	   SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SDD.WEIGHTINKGS, 0) ELSE ISNULL(SDD.DISPATCHQUANTITY, 0) END)
	FROM STOCKDISPATCH SD
		INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SD.FROMBRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE TRY_CONVERT(INT, SD.STATUS) <> 0
      AND SD.DELETEDDATE IS NULL
      AND SDD.DELETEDDATE IS NULL
      AND SD.UPDATEDATE >= @FinYearStartDate
      AND SD.UPDATEDATE < @AsOnDateExclusive
    GROUP BY SD.FROMBRANCHID, IP.ITEMPRICEID, SD.UPDATEDATE;

    UPDATE M
    SET M.STOCKDISPATCHOUT = TX.QTY
    FROM #Movement M 
	INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
        FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        BC.BRANCHID,
        IP.ITEMPRICEID,
        PBD.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(PBD.WEIGHTINKGS, 0) ELSE ISNULL(PBD.QUANTITY, 0) END)
    FROM POS_BILLDETAIL PBD
    INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
    INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
    INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
    INNER JOIN #Movement M ON M.BRANCHID = BC.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID


    WHERE PB.BILLSTATUS = 1
      AND PBD.DELETEDDATE IS NULL
      AND PBD.DAYCLOSUREID IS NOT NULL
      AND PBD.CREATEDDATE >= @FinYearStartDate
      AND PBD.CREATEDDATE < @AsOnDateExclusive
    GROUP BY BC.BRANCHID, IP.ITEMPRICEID, PBD.CREATEDDATE;

    UPDATE M
    SET M.SALE = TX.QTY
    FROM #Movement M
    INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
        FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID,TXNDATE, QTY)
    SELECT
        BC.BRANCHID,
        IP.ITEMPRICEID,
        CR.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(CR.REFUNDWEIGHTINKGS, 0) ELSE ISNULL(CR.REFUNDQUANTITY, 0) END)
    FROM POS_CREFUND CR
    INNER JOIN POS_BILLDETAIL PBD ON PBD.BRANCHCOUNTERID = CR.COUNTERID AND PBD.BILLDETAILID = CR.BILLDETAILID
    INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = CR.COUNTERID
    INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
    INNER JOIN #Movement M ON M.BRANCHID = BC.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE CR.DELETEDDATE IS NULL
      AND CR.DAYCLOSUREID IS NOT NULL
      AND CR.CREATEDDATE >= @FinYearStartDate
      AND CR.CREATEDDATE < @AsOnDateExclusive
    GROUP BY BC.BRANCHID, IP.ITEMPRICEID, CR.CREATEDDATE;

    UPDATE M
    SET M.CUSTOMERREFUND = TX.QTY
    FROM #Movement M
    INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY 
		FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    IF @ReportType = 'B'
    BEGIN
        INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
        SELECT
            BR.BRANCHID,
            IP.ITEMPRICEID,
            BR.UPDATEDDATE,

            SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(BRD.WEIGHTINKGS, 0) ELSE ISNULL(BRD.QUANTITY, 0) END)
        FROM POS_BREFUND BR
        INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
        INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
        INNER JOIN #Movement M ON M.BRANCHID = BR.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
			AND BRD.REASONID <> 5
          AND BR.DELETEDDATE IS NULL
          AND BRD.DELETEDDATE IS NULL      
			AND BR.UPDATEDDATE >= @FinYearStartDate
          AND BR.UPDATEDDATE < @AsOnDateExclusive
        GROUP BY BR.BRANCHID, IP.ITEMPRICEID, BR.UPDATEDDATE;
    END
    ELSE
    BEGIN
        INSERT INTO #Txn (BRANCHID, ITEMPRICEID,TXNDATE, QTY)
        SELECT
            ROR.LOCATIONTOMOVESTOCK,
            PIP.ITEMPRICEID,
            BR.ACCEPTEDDATE,
            SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(BRD.WEIGHTINKGS, 0) ELSE ISNULL(BRD.QUANTITY, 0) END)
        FROM POS_BREFUND BR
        INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
        INNER JOIN REASONFORREFUND ROR ON ROR.REASONID = BRD.REASONID
        INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
        INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
        INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
        INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
        INNER JOIN #Movement M ON M.BRANCHID = ROR.LOCATIONTOMOVESTOCK AND M.ITEMPRICEID = PIP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
          AND ISNULL(BR.IsAccepted, 0) = 1
          AND BR.DELETEDDATE IS NULL
          AND BRD.DELETEDDATE IS NULL
          AND BRD.REASONID <> 5
          AND (I.PARENTITEMID IS NULL OR ISNULL(I.ISOPENITEM, 0) = 1 OR ISNULL(ROR.MERGETOPARENT, 0) = 0)
          AND BR.ACCEPTEDDATE >= @FinYearStartDate
          AND BR.ACCEPTEDDATE < @AsOnDateExclusive
        GROUP BY ROR.LOCATIONTOMOVESTOCK, PIP.ITEMPRICEID, BR.ACCEPTEDDATE;

        INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
        SELECT
           ROR.LOCATIONTOMOVESTOCK,
            PARENTIP.ITEMPRICEID,
            BR.ACCEPTEDDATE,
            SUM(ISNULL(BRD.QUANTITY, 0) * ISNULL(U.MULTIPLIER, 0))
        FROM POS_BREFUND BR
        INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
        INNER JOIN REASONFORREFUND ROR ON ROR.REASONID = BRD.REASONID AND ISNULL(ROR.MERGETOPARENT, 0) = 1
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
        INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
        INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
        INNER JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID
        INNER JOIN ITEMCODE PIC ON PIC.ITEMID = PITEM.ITEMID
        INNER JOIN ITEMPRICE PARENTIP ON PARENTIP.ITEMCODEID = PIC.ITEMCODEID
            AND PARENTIP.DELETEDDATE IS NULL
            AND ISNULL(PARENTIP.PARENTITEMPRICEID, 0) = 0
        LEFT JOIN UOM U ON U.UOMID = I.UOMID
        INNER JOIN #Movement M ON M.BRANCHID = ROR.LOCATIONTOMOVESTOCK AND M.ITEMPRICEID = PARENTIP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
          AND ISNULL(BR.IsAccepted, 0) = 1
          AND BR.DELETEDDATE IS NULL
          AND BRD.DELETEDDATE IS NULL
          AND BRD.REASONID <> 5
          AND I.PARENTITEMID IS NOT NULL
          AND ISNULL(I.ISOPENITEM, 0) = 0
          AND BR.ACCEPTEDDATE >= @FinYearStartDate
          AND BR.ACCEPTEDDATE < @AsOnDateExclusive
        GROUP BY ROR.LOCATIONTOMOVESTOCK, PARENTIP.ITEMPRICEID, BR.ACCEPTEDDATE;
    END

    UPDATE M
    SET M.BRANCHREFUND = TX.QTY
    FROM #Movement M
    INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
        FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SR.BRANCHID,
        ICP.ITEMPRICEID,
        SR.CNINITIATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SRD.WEIGHTINKGS, 0) ELSE ISNULL(SRD.QUANTITY, 0) END)
    FROM SUPPLIERRETURNS SR
    INNER JOIN SUPPLIERRETURNSDETAIL SRD ON SRD.SUPPLIERRETURNSID = SR.SUPPLIERRETURNSID
    INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
    INNER JOIN #Movement M ON M.BRANCHID = SR.BRANCHID AND M.ITEMPRICEID = ICP.ITEMPRICEID
    WHERE SR.DELETEDDATE IS NULL
      AND SRD.DELETEDDATE IS NULL
      AND SR.CNINITIATEDDATE >= @FinYearStartDate
      AND SR.CNINITIATEDDATE < @AsOnDateExclusive
    GROUP BY SR.BRANCHID, ICP.ITEMPRICEID, SR.CNINITIATEDDATE;

    UPDATE M
    SET M.SUPPLIERRETURNS = TX.QTY
    FROM #Movement M
    INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
        FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SA.BRANCHID,
        IP.ITEMPRICEID,
        SA.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SA.WEIGHTINKGS, 0) - ISNULL(SA.PREVWEIGHTINKGS, 0) ELSE ISNULL(SA.QUANTITY, 0) - ISNULL(SA.PREVQUANTITY, 0) END)
    FROM STOCKADJUSTMENT SA
    INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SA.ITEMPRICEID
    INNER JOIN #Movement M ON M.BRANCHID = SA.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE SA.CREATEDDATE >= @FinYearStartDate
      AND SA.CREATEDDATE < @AsOnDateExclusive
    GROUP BY SA.BRANCHID, IP.ITEMPRICEID, SA.CREATEDDATE;

    UPDATE M
    SET M.STOCKADJUSTMENT = TX.QTY
    FROM #Movement M
    INNER JOIN
    (
        SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
        FROM #Txn T
        INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
        WHERE T.TXNDATE > MI.COUNTINGDATE
        GROUP BY T.BRANCHID, T.ITEMPRICEID
    ) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    SELECT
        I.SKUCODE,
        IC.ITEMCODE,
        I.ITEMNAME,
		GST.GSTCODE,
        IP.MRP,
        CASE WHEN @IncludeCategory = 1 THEN CAT.CATEGORYNAME ELSE NULL END AS CATEGORYNAME,
        CASE WHEN @IncludeCategory = 1 THEN SC.SUBCATEGORYNAME ELSE NULL END AS SUBCATEGORYNAME,
        CASE WHEN @IncludeClassification = 1 THEN ICL.CLASSIFICATIONNAME ELSE NULL END AS CLASSIFICATIONNAME,
        CASE WHEN @IncludeClassification = 1 THEN ISCL.SUBCLASSIFICATIONNAME ELSE NULL END AS SUBCLASSIFICATIONNAME,
        CASE WHEN @IncludeHSN = 1 THEN I.HSNCODE ELSE NULL END AS HSNCODE,
        CASE WHEN @IncludeLatestCP = 1 THEN LICP.COSTPRICEWOT ELSE NULL END AS LATESTCOSTPRICEWOT,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWT, 0) - ISNULL(LICP.COSTPRICEWOT, 0) ELSE NULL END AS LATESTCOSTPRICETAX,
        CASE WHEN @IncludeLatestCP = 1 THEN LICP.COSTPRICEWT ELSE NULL END AS LATESTCOSTPRICEWT,
        CASE WHEN @IncludeAvgCP = 1 THEN AICP.COSTPRICEWOT ELSE NULL END AS AVGCOSTPRICEWOT,
        CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWT, 0) - ISNULL (AICP.COSTPRICEWOT, 0) ELSE NULL END AS AVGCOSTPRICETAX,
        CASE WHEN @IncludeAvgCP = 1 THEN AICP.COSTPRICEWT ELSE NULL END AS AVGCOSTPRICEWT,
        M.OPENINGSTOCK,
        M.STOCKENTRY,
        M.STOCKDISPATCHIN,
        M.STOCKDISPATCHOUT,
		M.CUSTOMERREFUND,
        M.BRANCHREFUND,
        M.SUPPLIERRETURNS,
        M.SALE,
        M.STOCKADJUSTMENT,
        M.OPENINGSTOCK + M.STOCKENTRY + M.STOCKDISPATCHIN + M.CUSTOMERREFUND + M.STOCKADJUSTMENT- M.STOCKDISPATCHOUT - M.SUPPLIERRETURNS - M.SALE
            + CASE WHEN @ReportType = 'B' THEN -M.BRANCHREFUND ELSE M.BRANCHREFUND END AS CURRENTSTOCK,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWOT, 0) * (M.OPENINGSTOCK + M.STOCKENTRY + M.STOCKDISPATCHIN + M.CUSTOMERREFUND
			+ M.STOCKADJUSTMENT - M.STOCKDISPATCHOUT - M.SUPPLIERRETURNS - M.SALE + CASE WHEN @ReportType = 'B' THEN -M.BRANCHREFUND ELSE M.BRANCHREFUND END) 
		ELSE NULL END AS TOTALLATESTCOSTPRICEWOT,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWT, 0) * (M.OPENINGSTOCK + M.STOCKENTRY + M.STOCKDISPATCHIN + M.CUSTOMERREFUND + M.STOCKADJUSTMENT - 
		M.STOCKDISPATCHOUT - M.SUPPLIERRETURNS - M.SALE + 
		CASE WHEN @ReportType = 'B' THEN -M.BRANCHREFUND ELSE M.BRANCHREFUND END) ELSE NULL END AS TOTALLATESTCOSTPRICEWT,
 
       CASE WHEN @IncludeAvgCP = 1 
	   THEN ISNULL(AICP.COSTPRICEWOT, 0) * (M.OPENINGSTOCK + M.STOCKENTRY + M.STOCKDISPATCHIN + M.CUSTOMERREFUND + M.STOCKADJUSTMENT - M.STOCKDISPATCHOUT - M.SUPPLIERRETURNS - M.SALE + 
	   CASE WHEN @ReportType = 'B' THEN -M.BRANCHREFUND ELSE M.BRANCHREFUND END) ELSE NULL END AS TOTALAVGCOSTPRICEWOT,
       CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWT, 0) * (M.OPENINGSTOCK + M.STOCKENTRY + M.STOCKDISPATCHIN + M.CUSTOMERREFUND + M.STOCKADJUSTMENT - 
		M.STOCKDISPATCHOUT - M.SUPPLIERRETURNS - M.SALE + CASE WHEN @ReportType = 'B' THEN -M.BRANCHREFUND ELSE M.BRANCHREFUND END) 
		ELSE NULL END AS TOTALAVGCOSTPRICEWT,
        CASE WHEN @IncludeBrand = 1 THEN BRD.BRANDNAME ELSE NULL END AS BRANDNAME,
		CASE WHEN @IncludeBrand = 1 THEN MFR.MANUFACTURERNAME ELSE NULL END AS MANUFACTURERNAME,
        B.BRANCHNAME,
        M.COUNTINGDATE,
        M.BRANCHID,
        M.ITEMPRICEID,
        M.ITEMCODEID,
        M.ITEMID,
		M.CATEGORYID
    FROM #Movement M
    INNER JOIN BRANCH B ON B.BRANCHID = M.BRANCHID
    INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = M.ITEMPRICEID
    INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
    INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
    LEFT JOIN SUBCATEGORY SC ON SC.SUBCATEGORYID = I.SUBCATEGORYID AND SC.DELETEDDATE IS NULL
    LEFT JOIN ITEMCLASSIFICATION ICL ON ICL.CLASSIFICATIONID = I.CLASSIFICATIONID AND ICL.DELETEDDATE IS NULL
    LEFT JOIN ITEMSUBCLASSIFICATION ISCL ON ISCL.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID AND ISCL.DELETEDDATE IS NULL
    LEFT JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID AND GST.DELETEDDATE IS NULL
    LEFT JOIN TBLBRAND BRD ON BRD.BRANDID = I.BRANDID
    LEFT JOIN TBLMANUFACTURER MFR ON MFR.MANUFACTURERID = I.MANUFACTURERID
    LEFT JOIN
    (
        SELECT IC2.ITEMCODEID, IP2.MRP, MAX(ICP.ITEMCOSTPRICEID) AS ITEMCOSTPRICEID
		FROM ITEMCOSTPRICE ICP
			INNER JOIN ITEMPRICE IP2 ON IP2.ITEMPRICEID = ICP.ITEMPRICEID
			INNER JOIN ITEMCODE IC2 ON IC2.ITEMCODEID = IP2.ITEMCODEID
        WHERE IP2.DELETEDDATE IS NULL
          AND ICP.DELETEDDATE IS NULL
        GROUP BY IC2.ITEMCODEID, IP2.MRP
    ) MAXLICP ON MAXLICP.ITEMCODEID = IC.ITEMCODEID AND MAXLICP.MRP = IP.MRP AND @IncludeLatestCP = 1
    LEFT JOIN ITEMCOSTPRICE LICP ON LICP.ITEMCOSTPRICEID = MAXLICP.ITEMCOSTPRICEID
    LEFT JOIN AVGCOSTPRICE AICP ON AICP.ITEMCODEID = IC.ITEMCODEID
        AND AICP.MRP = IP.MRP
        AND AICP.AVGCPDATE = @AvgCPDate
        AND @IncludeAvgCP = 1
    WHERE M.OPENINGSTOCK <> 0
       OR M.STOCKENTRY <> 0
       OR M.STOCKDISPATCHIN <> 0
       OR M.STOCKDISPATCHOUT <> 0
       OR M.CUSTOMERREFUND <> 0
       OR M.BRANCHREFUND <> 0
       OR M.SUPPLIERRETURNS <> 0
       OR M.SALE <> 0
       OR M.STOCKADJUSTMENT <> 0
    ORDER BY B.BRANCHNAME, I.SKUCODE, IC.ITEMCODE, IP.MRP;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_ASOFDATE_CORE_old]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCK_ASOFDATE_CORE_old]
(
    @AsOnDate DATE,
    @BranchID NVARCHAR(1000),
    @ITEMID INT = 0,
    @CategoryID VARCHAR(500),
    @IncludeCategory BIT = 0,
    @IncludeClassification BIT = 0,
    @IncludeHSN BIT = 0,
    @IncludeLatestCP BIT = 1,
    @IncludeAvgCP BIT = 1,
    @IncludeBrand BIT = 0,
    @ReportType CHAR(1),
    @IncludeItemCodeMRP BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @AsOnDateExclusive DATETIME = DATEADD(DAY, 1, CAST(@AsOnDate AS DATETIME)),
        @FinYearStartDate DATE = '2024-04-01',
        @AvgCPDate DATE;

    SELECT @AvgCPDate = DATEFROMPARTS(YEAR(@AsOnDate), MONTH(@AsOnDate), 1);
	
    CREATE TABLE #CATEGORY (CATEGORYID INT NOT NULL PRIMARY KEY);
    CREATE TABLE #BRANCH (BRANCHID INT NOT NULL PRIMARY KEY);

    INSERT INTO #CATEGORY (CATEGORYID)
    SELECT DISTINCT TRY_CONVERT(INT, ITEM)
    FROM dbo.SplitString(@CategoryID, ',')
    WHERE TRY_CONVERT(INT, ITEM) IS NOT NULL;


    IF NOT EXISTS (SELECT 1 FROM #CATEGORY)
    BEGIN
        INSERT INTO #CATEGORY (CATEGORYID)
        SELECT CATEGORYID FROM TBLCATEGORY WHERE DELETEDDATE IS NULL;
    END

    INSERT INTO #BRANCH (BRANCHID)
    SELECT DISTINCT B.BRANCHID
    FROM dbo.SplitString(@BranchID, ',') BR
    INNER JOIN BRANCH B ON B.BRANCHID = TRY_CONVERT(INT, BR.ITEM)
    WHERE B.DELETEDDATE IS NULL
      AND 
	  (
        (@ReportType = 'W' AND B.BRANCHID = 45)
        OR (@ReportType = 'D' AND B.BRANCHID = 100)
		OR (@ReportType = 'B' AND B.BRANCHID NOT IN (45, 91, 92, 97, 100, 103) AND ISNULL(B.ISWAREHOUSE, 0) = 0)
		);

    CREATE TABLE #ReportItem
    (
        ITEMID INT NOT NULL PRIMARY KEY,
        CATEGORYID INT NOT NULL,
        SUBCATEGORYID INT NULL,
        ISOPENITEM BIT NOT NULL
    );

    INSERT INTO #ReportItem (ITEMID, CATEGORYID, SUBCATEGORYID, ISOPENITEM)
    SELECT I.ITEMID, I.CATEGORYID, I.SUBCATEGORYID, ISNULL(I.ISOPENITEM, 0)
    FROM ITEM I
		INNER JOIN #CATEGORY C ON C.CATEGORYID = I.CATEGORYID
    WHERE I.DELETEDDATE IS NULL
		AND (@ITEMID = 0 OR I.ITEMID = @ITEMID);

    CREATE TABLE #ItemCountingDate
    (
        BRANCHID INT NOT NULL,
        ITEMID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, ITEMID)
    );

    INSERT INTO #ItemCountingDate (BRANCHID, ITEMID, COUNTINGDATE)
    SELECT CA.BRANCHID, IC.ITEMID, MAX(CAI.CREATEDDATE)
    FROM COUNTINGAPPROVALITEM CAI
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAI.COUNTINGAPPROVALID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = CAI.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
		INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
    WHERE CAI.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, IC.ITEMID;

    CREATE TABLE #SubCategoryCountingDate
    (
        BRANCHID INT NOT NULL,
        SUBCATEGORYID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, SUBCATEGORYID)
    );

    INSERT INTO #SubCategoryCountingDate (BRANCHID, SUBCATEGORYID, COUNTINGDATE)
    SELECT CA.BRANCHID, CAC.SUBCATEGORYID, MAX(CAC.CREATEDDATE)
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
		INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
    WHERE CAC.SUBCATEGORYID IS NOT NULL
		AND CAC.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, CAC.SUBCATEGORYID;

    CREATE TABLE #CategoryCountingDate
    (
        BRANCHID INT NOT NULL,
        CATEGORYID INT NOT NULL,
        COUNTINGDATE DATETIME NULL,
        PRIMARY KEY (BRANCHID, CATEGORYID)
    );

    INSERT INTO #CategoryCountingDate (BRANCHID, CATEGORYID, COUNTINGDATE)
    SELECT CA.BRANCHID, CAC.CATEGORYID, MAX(CAC.CREATEDDATE)
    FROM COUNTINGAPPROVALCATEGORYMAP CAC
		INNER JOIN COUNTINGAPPROVAL CA ON CA.COUNTINGAPPROVALID = CAC.COUNTINGAPPROVALID
		INNER JOIN #BRANCH B ON B.BRANCHID = CA.BRANCHID
    WHERE CAC.CATEGORYID IS NOT NULL
		AND CAC.CREATEDDATE < @AsOnDateExclusive
    GROUP BY CA.BRANCHID, CAC.CATEGORYID;

    CREATE TABLE #Baseline
    (
        BRANCHID INT NOT NULL,
        ITEMID INT NOT NULL,
        CASCADEDATE DATETIME NULL,
        COUNTINGDATE DATETIME NOT NULL,
        PRIMARY KEY (BRANCHID, ITEMID)
    );

    INSERT INTO #Baseline (BRANCHID, ITEMID, CASCADEDATE, COUNTINGDATE)
    SELECT
        B.BRANCHID,
        RI.ITEMID,
        D.LASTCOUNTINGDATE,
        CASE
            WHEN ISNULL(D.LASTCOUNTINGDATE, '19000101') < @FinYearStartDate
                THEN CAST(@FinYearStartDate AS DATETIME)
            ELSE D.LASTCOUNTINGDATE
        END
    FROM #BRANCH B
		CROSS JOIN #ReportItem RI
		LEFT JOIN #ItemCountingDate ICD ON ICD.BRANCHID = B.BRANCHID AND ICD.ITEMID = RI.ITEMID
		LEFT JOIN #SubCategoryCountingDate SCD ON SCD.BRANCHID = B.BRANCHID AND SCD.SUBCATEGORYID = RI.SUBCATEGORYID
		LEFT JOIN #CategoryCountingDate CCD ON CCD.BRANCHID = B.BRANCHID AND CCD.CATEGORYID = RI.CATEGORYID
		CROSS APPLY
		(
			SELECT CASE
				WHEN SCD.COUNTINGDATE > ISNULL(ICD.COUNTINGDATE, '19000101') THEN SCD.COUNTINGDATE
				WHEN ICD.COUNTINGDATE IS NOT NULL THEN ICD.COUNTINGDATE
				ELSE CCD.COUNTINGDATE
			END AS LASTCOUNTINGDATE
		) D;

    CREATE TABLE #Movement
    (
        BRANCHID INT NOT NULL,
        ITEMPRICEID INT NOT NULL,
        ITEMCODEID INT NOT NULL,
        ITEMID INT NOT NULL,
        CATEGORYID INT NOT NULL,
        ISOPENITEM BIT NOT NULL,
		CASCADEDATE DATETIME NULL,
        COUNTINGDATE DATETIME NOT NULL,
        OPENINGSTOCK DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKENTRY DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKDISPATCHIN DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKDISPATCHOUT DECIMAL(18, 2) NOT NULL DEFAULT 0,
        CUSTOMERREFUND DECIMAL(18, 2) NOT NULL DEFAULT 0,
        BRANCHREFUND DECIMAL(18, 2) NOT NULL DEFAULT 0,
        SUPPLIERRETURNS DECIMAL(18, 2) NOT NULL DEFAULT 0,
        SALE DECIMAL(18, 2) NOT NULL DEFAULT 0,
        STOCKADJUSTMENT DECIMAL(18, 2) NOT NULL DEFAULT 0,
        PRIMARY KEY (BRANCHID, ITEMPRICEID)
    );

    INSERT INTO #Movement (BRANCHID, ITEMPRICEID, ITEMCODEID, ITEMID, CATEGORYID, ISOPENITEM, CASCADEDATE, COUNTINGDATE)
    SELECT
        BL.BRANCHID,
        IP.ITEMPRICEID,
        IC.ITEMCODEID,
        I.ITEMID,
        I.CATEGORYID,
        ISNULL(I.ISOPENITEM, 0),
        BL.CASCADEDATE,
        BL.COUNTINGDATE
    FROM #Baseline BL
		INNER JOIN #ReportItem RI ON RI.ITEMID = BL.ITEMID
		INNER JOIN ITEM I ON I.ITEMID = RI.ITEMID
		INNER JOIN ITEMCODE IC ON IC.ITEMID = RI.ITEMID
		INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = IC.ITEMCODEID
    WHERE IP.ITEMPRICEID IS NOT NULL;

    UPDATE M
    SET M.OPENINGSTOCK = CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SS.FYOPENINGWEIGHTINKGS, 0) ELSE ISNULL(SS.FYOPENINGQUANTITY, 0) END
    FROM #Movement M
		INNER JOIN STOCKSUMMARY SS ON SS.BRANCHID = M.BRANCHID AND SS.ITEMPRICEID = M.ITEMPRICEID
    WHERE ISNULL(M.CASCADEDATE, '1900-01-01') < @FinYearStartDate;

    UPDATE M
    SET M.OPENINGSTOCK = CASE WHEN M.ISOPENITEM = 1 THEN OPN.WEIGHTINKGS ELSE OPN.QUANTITY END
    FROM #Movement M
		INNER JOIN
		(
			SELECT
				SC.BRANCHID,
				SCD.ITEMPRICEID,
				SUM(ISNULL(SCD.QUANTITY, 0)) AS QUANTITY,
				SUM(ISNULL(SCD.WEIGHTINKGS, 0)) AS WEIGHTINKGS
			FROM STOCKCOUNTING SC
				INNER JOIN STOCKCOUNTINGDETAIL SCD ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
				INNER JOIN #Movement MI ON MI.BRANCHID = SC.BRANCHID
					AND MI.ITEMPRICEID = SCD.ITEMPRICEID
					AND CAST(SC.STOCKACCEPTEDDATE AS DATE) >= CAST(MI.CASCADEDATE AS DATE)
			WHERE SC.DELETEDDATE IS NULL
					AND SCD.DELETEDDATE IS NULL
					AND ISNULL(SC.STATUS, 0) IN (2, 3)
					AND SC.STOCKACCEPTEDDATE < @AsOnDateExclusive
					AND MI.CASCADEDATE >= @FinYearStartDate
			GROUP BY SC.BRANCHID, SCD.ITEMPRICEID
    ) OPN ON OPN.BRANCHID = M.BRANCHID AND OPN.ITEMPRICEID = M.ITEMPRICEID;

    CREATE TABLE #Txn
    (
        BRANCHID INT NOT NULL,
        ITEMPRICEID INT NOT NULL,
        TXNDATE DATETIME NOT NULL,
        QTY DECIMAL(18, 2) NOT NULL
    );

    CREATE CLUSTERED INDEX IX_Txn_Branch_ItemPrice_Date
        ON #Txn (BRANCHID, ITEMPRICEID, TXNDATE);

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SE.RECEIVINGBRANCHID,
        ICP.ITEMPRICEID,
        SE.UPDATEDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SED.WEIGHTINKGS, 0) ELSE ISNULL(SED.QUANTITY, 0) END)
    FROM STOCKENTRY SE
		INNER JOIN STOCKENTRYDETAIL SED ON SED.STOCKENTRYID = SE.STOCKENTRYID
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SE.RECEIVINGBRANCHID AND M.ITEMPRICEID = ICP.ITEMPRICEID
    WHERE ISNULL(SE.STATUS, 0) = 1
		AND SE.DELETEDDATE IS NULL
		AND SED.DELETEDDATE IS NULL
		AND SE.UPDATEDATE >= @FinYearStartDate
		AND SE.UPDATEDATE < @AsOnDateExclusive
    GROUP BY SE.RECEIVINGBRANCHID, ICP.ITEMPRICEID, SE.UPDATEDATE;

    UPDATE M
    SET M.STOCKENTRY = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn(BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SD.TOBRANCHID,
        IP.ITEMPRICEID,
        SD.STATUSAPPROVEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SDD.WEIGHTINKGS, 0) ELSE ISNULL(SDD.DISPATCHQUANTITY, 0) END)
    FROM STOCKDISPATCH SD
		INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SD.TOBRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE TRY_CONVERT(INT, SD.STATUS) = 2
		AND ISNULL(SDD.ISACCEPTED, 0) = 1
		AND SD.DELETEDDATE IS NULL
		AND SDD.DELETEDDATE IS NULL
		AND SD.STATUSAPPROVEDDATE >= @FinYearStartDate
		AND SD.STATUSAPPROVEDDATE < @AsOnDateExclusive
    GROUP BY SD.TOBRANCHID, IP.ITEMPRICEID, SD.STATUSAPPROVEDDATE;

    UPDATE M
    SET M.STOCKDISPATCHIN = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
				INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SD.FROMBRANCHID,
        IP.ITEMPRICEID,
        SD.UPDATEDATE,
		SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SDD.WEIGHTINKGS, 0) ELSE ISNULL(SDD.DISPATCHQUANTITY, 0) END)
    FROM STOCKDISPATCH SD
		INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SD.FROMBRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE TRY_CONVERT(INT, SD.STATUS) <> 0
		AND SD.DELETEDDATE IS NULL
		AND SDD.DELETEDDATE IS NULL
		AND SD.UPDATEDATE >= @FinYearStartDate
		AND SD.UPDATEDATE < @AsOnDateExclusive
    GROUP BY SD.FROMBRANCHID, IP.ITEMPRICEID, SD.UPDATEDATE;

    UPDATE M
    SET M.STOCKDISPATCHOUT = TX.QTY
    FROM #Movement M 
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        BC.BRANCHID,
        IP.ITEMPRICEID,
        PBD.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(PBD.WEIGHTINKGS, 0) ELSE ISNULL(PBD.QUANTITY, 0) END)
    FROM POS_BILLDETAIL PBD
		INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PB.BRANCHCOUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = BC.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE PB.BILLSTATUS = 1
		AND PBD.DELETEDDATE IS NULL
		AND PBD.DAYCLOSUREID IS NOT NULL
		AND PBD.CREATEDDATE >= @FinYearStartDate
		AND PBD.CREATEDDATE < @AsOnDateExclusive
    GROUP BY BC.BRANCHID, IP.ITEMPRICEID, PBD.CREATEDDATE;

    UPDATE M
    SET M.SALE = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID,TXNDATE, QTY)
    SELECT
        BC.BRANCHID,
        IP.ITEMPRICEID,
        CR.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(CR.REFUNDWEIGHTINKGS, 0) ELSE ISNULL(CR.REFUNDQUANTITY, 0) END)
    FROM POS_CREFUND CR
		INNER JOIN POS_BILLDETAIL PBD ON PBD.BRANCHCOUNTERID = CR.COUNTERID AND PBD.BILLDETAILID = CR.BILLDETAILID
		INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = CR.COUNTERID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = BC.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE CR.DELETEDDATE IS NULL
		AND CR.DAYCLOSUREID IS NOT NULL
		AND CR.CREATEDDATE >= @FinYearStartDate
		AND CR.CREATEDDATE < @AsOnDateExclusive
    GROUP BY BC.BRANCHID, IP.ITEMPRICEID, CR.CREATEDDATE;

    UPDATE M
    SET M.CUSTOMERREFUND = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY 
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    IF @ReportType = 'B'
    BEGIN
        INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
        SELECT
            BR.BRANCHID,
            IP.ITEMPRICEID,
            BR.UPDATEDDATE,
            SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(BRD.WEIGHTINKGS, 0) ELSE ISNULL(BRD.QUANTITY, 0) END)
        FROM POS_BREFUND BR
			INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
			INNER JOIN #Movement M ON M.BRANCHID = BR.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
			AND BRD.REASONID <> 5
			AND BR.DELETEDDATE IS NULL
			AND BRD.DELETEDDATE IS NULL      
			AND BR.UPDATEDDATE >= @FinYearStartDate
			AND BR.UPDATEDDATE < @AsOnDateExclusive
        GROUP BY BR.BRANCHID, IP.ITEMPRICEID, BR.UPDATEDDATE;
    END
    ELSE
    BEGIN
        INSERT INTO #Txn (BRANCHID, ITEMPRICEID,TXNDATE, QTY)
        SELECT
            ROR.LOCATIONTOMOVESTOCK,
            PIP.ITEMPRICEID,
            BR.ACCEPTEDDATE,
            SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(BRD.WEIGHTINKGS, 0) ELSE ISNULL(BRD.QUANTITY, 0) END)
        FROM POS_BREFUND BR
			INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
			INNER JOIN REASONFORREFUND ROR ON ROR.REASONID = BRD.REASONID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
			INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			INNER JOIN #Movement M ON M.BRANCHID = ROR.LOCATIONTOMOVESTOCK AND M.ITEMPRICEID = PIP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
			AND ISNULL(BR.IsAccepted, 0) = 1
			AND BR.DELETEDDATE IS NULL
			AND BRD.DELETEDDATE IS NULL
			AND BRD.REASONID <> 5
			AND (I.PARENTITEMID IS NULL OR ISNULL(I.ISOPENITEM, 0) = 1 OR ISNULL(ROR.MERGETOPARENT, 0) = 0)
			AND BR.ACCEPTEDDATE >= @FinYearStartDate
			AND BR.ACCEPTEDDATE < @AsOnDateExclusive
        GROUP BY ROR.LOCATIONTOMOVESTOCK, PIP.ITEMPRICEID, BR.ACCEPTEDDATE;

        INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
        SELECT
			ROR.LOCATIONTOMOVESTOCK,
			PARENTIP.ITEMPRICEID,
			BR.ACCEPTEDDATE,
			SUM(ISNULL(BRD.QUANTITY, 0) * ISNULL(U.MULTIPLIER, 0))
        FROM POS_BREFUND BR
			INNER JOIN POS_BREFUNDDETAIL BRD ON BRD.BRID = BR.BRID
			INNER JOIN REASONFORREFUND ROR ON ROR.REASONID = BRD.REASONID AND ISNULL(ROR.MERGETOPARENT, 0) = 1
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEM PITEM ON PITEM.ITEMID = I.PARENTITEMID
			INNER JOIN ITEMCODE PIC ON PIC.ITEMID = PITEM.ITEMID
			INNER JOIN ITEMPRICE PARENTIP ON PARENTIP.ITEMCODEID = PIC.ITEMCODEID
				AND PARENTIP.DELETEDDATE IS NULL
				AND ISNULL(PARENTIP.PARENTITEMPRICEID, 0) = 0
			LEFT JOIN UOM U ON U.UOMID = I.UOMID
			INNER JOIN #Movement M ON M.BRANCHID = ROR.LOCATIONTOMOVESTOCK AND M.ITEMPRICEID = PARENTIP.ITEMPRICEID
        WHERE ISNULL(BR.STATUS, 0) = 1
			AND ISNULL(BR.IsAccepted, 0) = 1
			AND BR.DELETEDDATE IS NULL
			AND BRD.DELETEDDATE IS NULL
			AND BRD.REASONID <> 5
			AND I.PARENTITEMID IS NOT NULL
			AND ISNULL(I.ISOPENITEM, 0) = 0
			AND BR.ACCEPTEDDATE >= @FinYearStartDate
			AND BR.ACCEPTEDDATE < @AsOnDateExclusive
        GROUP BY ROR.LOCATIONTOMOVESTOCK, PARENTIP.ITEMPRICEID, BR.ACCEPTEDDATE;
    END

    UPDATE M
    SET M.BRANCHREFUND = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SR.BRANCHID,
        ICP.ITEMPRICEID,
        SR.CNINITIATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SRD.WEIGHTINKGS, 0) ELSE ISNULL(SRD.QUANTITY, 0) END)
    FROM SUPPLIERRETURNS SR
		INNER JOIN SUPPLIERRETURNSDETAIL SRD ON SRD.SUPPLIERRETURNSID = SR.SUPPLIERRETURNSID
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SR.BRANCHID AND M.ITEMPRICEID = ICP.ITEMPRICEID
    WHERE SR.DELETEDDATE IS NULL
		AND SRD.DELETEDDATE IS NULL
		AND SR.CNINITIATEDDATE >= @FinYearStartDate
		AND SR.CNINITIATEDDATE < @AsOnDateExclusive
    GROUP BY SR.BRANCHID, ICP.ITEMPRICEID, SR.CNINITIATEDDATE;

    UPDATE M
    SET M.SUPPLIERRETURNS = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    TRUNCATE TABLE #Txn;

    INSERT INTO #Txn (BRANCHID, ITEMPRICEID, TXNDATE, QTY)
    SELECT
        SA.BRANCHID,
        IP.ITEMPRICEID,
        SA.CREATEDDATE,
        SUM(CASE WHEN M.ISOPENITEM = 1 THEN ISNULL(SA.WEIGHTINKGS, 0) - ISNULL(SA.PREVWEIGHTINKGS, 0) ELSE ISNULL(SA.QUANTITY, 0) - ISNULL(SA.PREVQUANTITY, 0) END)
    FROM STOCKADJUSTMENT SA
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SA.ITEMPRICEID
		INNER JOIN #Movement M ON M.BRANCHID = SA.BRANCHID AND M.ITEMPRICEID = IP.ITEMPRICEID
    WHERE SA.CREATEDDATE >= @FinYearStartDate
		AND SA.CREATEDDATE < @AsOnDateExclusive
    GROUP BY SA.BRANCHID, IP.ITEMPRICEID, SA.CREATEDDATE;

    UPDATE M
    SET M.STOCKADJUSTMENT = TX.QTY
    FROM #Movement M
		INNER JOIN
		(
			SELECT T.BRANCHID, T.ITEMPRICEID, SUM(T.QTY) AS QTY
			FROM #Txn T
			INNER JOIN #Movement MI ON MI.BRANCHID = T.BRANCHID AND MI.ITEMPRICEID = T.ITEMPRICEID
			WHERE T.TXNDATE > MI.COUNTINGDATE
			GROUP BY T.BRANCHID, T.ITEMPRICEID
		) TX ON TX.BRANCHID = M.BRANCHID AND TX.ITEMPRICEID = M.ITEMPRICEID;

    CREATE TABLE #LatestItemCost
    (
        ITEMID INT NOT NULL PRIMARY KEY,
        COSTPRICEWOT DECIMAL(18, 4) NULL,
        COSTPRICEWT DECIMAL(18, 4) NULL
    );

    ;WITH LatestCost AS
    (
        SELECT
            IC.ITEMID,
            ICP.COSTPRICEWOT,
            ICP.COSTPRICEWT,
            ROW_NUMBER() OVER
            (
                PARTITION BY IC.ITEMID
                ORDER BY ICP.ITEMCOSTPRICEID DESC
            ) AS RN
        FROM ITEMCOSTPRICE ICP
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
        WHERE ICP.DELETEDDATE IS NULL
			AND @IncludeLatestCP = 1
    )

    INSERT INTO #LatestItemCost (ITEMID, COSTPRICEWOT, COSTPRICEWT)
    SELECT ITEMID, COSTPRICEWOT, COSTPRICEWT
    FROM LatestCost
    WHERE RN = 1;

    CREATE TABLE #AverageItemCost
    (
        ITEMID INT NOT NULL PRIMARY KEY,
        COSTPRICEWOT DECIMAL(18, 4) NULL,
        COSTPRICEWT DECIMAL(18, 4) NULL
    );

    INSERT INTO #AverageItemCost (ITEMID, COSTPRICEWOT, COSTPRICEWT)
    SELECT
        IC.ITEMID,
        AVG(CONVERT(DECIMAL(18, 4), AICP.COSTPRICEWOT)),
        AVG(CONVERT(DECIMAL(18, 4), AICP.COSTPRICEWT))
    FROM AVGCOSTPRICE AICP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = AICP.ITEMCODEID
		INNER JOIN #ReportItem RI ON RI.ITEMID = IC.ITEMID
    WHERE AICP.AVGCPDATE = @AvgCPDate
		AND @IncludeAvgCP = 1
    GROUP BY IC.ITEMID;

    SELECT
        I.SKUCODE,
        IC.ITEMCODE,
        I.ITEMNAME,
        GST.GSTCODE,
        IP.MRP,
        CASE WHEN @IncludeCategory = 1 THEN CAT.CATEGORYNAME ELSE NULL END AS CATEGORYNAME,
        CASE WHEN @IncludeCategory = 1 THEN SC.SUBCATEGORYNAME ELSE NULL END AS SUBCATEGORYNAME,
        CASE WHEN @IncludeClassification = 1 THEN ICL.CLASSIFICATIONNAME ELSE NULL END AS CLASSIFICATIONNAME,
        CASE WHEN @IncludeClassification = 1 THEN ISCL.SUBCLASSIFICATIONNAME ELSE NULL END AS SUBCLASSIFICATIONNAME,
        CASE WHEN @IncludeHSN = 1 THEN I.HSNCODE ELSE NULL END AS HSNCODE,
        CASE WHEN @IncludeLatestCP = 1 THEN LICP.COSTPRICEWOT ELSE NULL END AS LATESTCOSTPRICEWOT,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWT, 0) - ISNULL(LICP.COSTPRICEWOT, 0) ELSE NULL END AS LATESTCOSTPRICETAX,
        CASE WHEN @IncludeLatestCP = 1 THEN LICP.COSTPRICEWT ELSE NULL END AS LATESTCOSTPRICEWT,
        CASE WHEN @IncludeAvgCP = 1 THEN AICP.COSTPRICEWOT ELSE NULL END AS AVGCOSTPRICEWOT,
        CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWT, 0) - ISNULL(AICP.COSTPRICEWOT, 0) ELSE NULL END AS AVGCOSTPRICETAX,
        CASE WHEN @IncludeAvgCP = 1 THEN AICP.COSTPRICEWT ELSE NULL END AS AVGCOSTPRICEWT,
        M.OPENINGSTOCK,
        M.STOCKENTRY,
        M.STOCKDISPATCHIN,
        M.STOCKDISPATCHOUT,
        M.CUSTOMERREFUND,
        M.BRANCHREFUND,
        M.SUPPLIERRETURNS,
        M.SALE,
        M.STOCKADJUSTMENT,
        CS.CURRENTSTOCK,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWOT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWOT,
        CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(LICP.COSTPRICEWT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWT,
        CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWOT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWOT,
        CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(AICP.COSTPRICEWT, 0) * CS.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWT,
        CASE WHEN @IncludeBrand = 1 THEN BRD.BRANDNAME ELSE NULL END AS BRANDNAME,
        CASE WHEN @IncludeBrand = 1 THEN MFR.MANUFACTURERNAME ELSE NULL END AS MANUFACTURERNAME,
        B.BRANCHNAME,
        M.COUNTINGDATE,
        M.BRANCHID,
        M.ITEMPRICEID,
        M.ITEMCODEID,
        M.ITEMID,
        M.CATEGORYID
    INTO #ResultDetail
    FROM #Movement M
		INNER JOIN BRANCH B ON B.BRANCHID = M.BRANCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = M.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON SC.SUBCATEGORYID = I.SUBCATEGORYID AND SC.DELETEDDATE IS NULL
		LEFT JOIN ITEMCLASSIFICATION ICL ON ICL.CLASSIFICATIONID = I.CLASSIFICATIONID AND ICL.DELETEDDATE IS NULL
		LEFT JOIN ITEMSUBCLASSIFICATION ISCL ON ISCL.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID AND ISCL.DELETEDDATE IS NULL
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = I.GSTID AND GST.DELETEDDATE IS NULL
		LEFT JOIN TBLBRAND BRD ON BRD.BRANDID = I.BRANDID
		LEFT JOIN TBLMANUFACTURER MFR ON MFR.MANUFACTURERID = I.MANUFACTURERID
		LEFT JOIN #LatestItemCost LICP ON LICP.ITEMID = M.ITEMID AND @IncludeLatestCP = 1
		LEFT JOIN #AverageItemCost AICP ON AICP.ITEMID = M.ITEMID AND @IncludeAvgCP = 1
		CROSS APPLY
		(
			SELECT
				M.OPENINGSTOCK + M.STOCKENTRY + M.STOCKDISPATCHIN + M.CUSTOMERREFUND
				+ M.STOCKADJUSTMENT - M.STOCKDISPATCHOUT - M.SUPPLIERRETURNS - M.SALE
				+ CASE WHEN @ReportType = 'B' THEN -M.BRANCHREFUND ELSE M.BRANCHREFUND END AS CURRENTSTOCK
		) CS
    WHERE M.OPENINGSTOCK <> 0
		OR M.STOCKENTRY <> 0
		OR M.STOCKDISPATCHIN <> 0
		OR M.STOCKDISPATCHOUT <> 0
		OR M.CUSTOMERREFUND <> 0
		OR M.BRANCHREFUND <> 0
		OR M.SUPPLIERRETURNS <> 0
		OR M.SALE <> 0
		OR M.STOCKADJUSTMENT <> 0;

    IF @IncludeItemCodeMRP = 1
    BEGIN
        SELECT *
        FROM #ResultDetail
        ORDER BY BRANCHNAME, SKUCODE, ITEMCODE, MRP, ITEMPRICEID;
    END
    ELSE
    BEGIN
        ;WITH SKUResult AS
        (
            SELECT
                MAX(SKUCODE) AS SKUCODE,
                MAX(ITEMNAME) AS ITEMNAME,
                MAX(GSTCODE) AS GSTCODE,
                MAX(CATEGORYNAME) AS CATEGORYNAME,
                MAX(SUBCATEGORYNAME) AS SUBCATEGORYNAME,
                MAX(CLASSIFICATIONNAME) AS CLASSIFICATIONNAME,
                MAX(SUBCLASSIFICATIONNAME) AS SUBCLASSIFICATIONNAME,
                MAX(HSNCODE) AS HSNCODE,
                MAX(LATESTCOSTPRICEWOT) AS LATESTCOSTPRICEWOT,
                MAX(LATESTCOSTPRICETAX) AS LATESTCOSTPRICETAX,
                MAX(LATESTCOSTPRICEWT) AS LATESTCOSTPRICEWT,
                MAX(AVGCOSTPRICEWOT) AS AVGCOSTPRICEWOT,
                MAX(AVGCOSTPRICETAX) AS AVGCOSTPRICETAX,
                MAX(AVGCOSTPRICEWT) AS AVGCOSTPRICEWT,
                SUM(OPENINGSTOCK) AS OPENINGSTOCK,
                SUM(STOCKENTRY) AS STOCKENTRY,
                SUM(STOCKDISPATCHIN) AS STOCKDISPATCHIN,
                SUM(STOCKDISPATCHOUT) AS STOCKDISPATCHOUT,
                SUM(CUSTOMERREFUND) AS CUSTOMERREFUND,
                SUM(BRANCHREFUND) AS BRANCHREFUND,
                SUM(SUPPLIERRETURNS) AS SUPPLIERRETURNS,
                SUM(SALE) AS SALE,
                SUM(STOCKADJUSTMENT) AS STOCKADJUSTMENT,
                MAX(BRANDNAME) AS BRANDNAME,
                MAX(MANUFACTURERNAME) AS MANUFACTURERNAME,
                MAX(BRANCHNAME) AS BRANCHNAME,
                MAX(COUNTINGDATE) AS COUNTINGDATE,
                BRANCHID,
                ITEMID,
                MAX(CATEGORYID) AS CATEGORYID
            FROM #ResultDetail
            GROUP BY BRANCHID, ITEMID
        ),
        SKUResultWithStock AS
        (
            SELECT S.*,
                S.OPENINGSTOCK + S.STOCKENTRY + S.STOCKDISPATCHIN + S.CUSTOMERREFUND
                + S.STOCKADJUSTMENT - S.STOCKDISPATCHOUT - S.SUPPLIERRETURNS - S.SALE
                + CASE WHEN @ReportType = 'B' THEN -S.BRANCHREFUND ELSE S.BRANCHREFUND END AS CURRENTSTOCK
            FROM SKUResult S
            WHERE S.OPENINGSTOCK <> 0
               OR S.STOCKENTRY <> 0
               OR S.STOCKDISPATCHIN <> 0
               OR S.STOCKDISPATCHOUT <> 0
               OR S.CUSTOMERREFUND <> 0
               OR S.BRANCHREFUND <> 0
               OR S.SUPPLIERRETURNS <> 0
               OR S.SALE <> 0
               OR S.STOCKADJUSTMENT <> 0
        )

        SELECT
            S.SKUCODE,
            CAST(NULL AS VARCHAR(100)) AS ITEMCODE,
            S.ITEMNAME,
            S.GSTCODE,
            CAST(NULL AS DECIMAL(18, 2)) AS MRP,
            S.CATEGORYNAME,
            S.SUBCATEGORYNAME,
            S.CLASSIFICATIONNAME,
            S.SUBCLASSIFICATIONNAME,
            S.HSNCODE,
            S.LATESTCOSTPRICEWOT,
            S.LATESTCOSTPRICETAX,
            S.LATESTCOSTPRICEWT,
            S.AVGCOSTPRICEWOT,
            S.AVGCOSTPRICETAX,
            S.AVGCOSTPRICEWT,
            S.OPENINGSTOCK,
            S.STOCKENTRY,
            S.STOCKDISPATCHIN,
            S.STOCKDISPATCHOUT,
            S.CUSTOMERREFUND,
            S.BRANCHREFUND,
            S.SUPPLIERRETURNS,
            S.SALE,
            S.STOCKADJUSTMENT,
            S.CURRENTSTOCK,
            CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(S.LATESTCOSTPRICEWOT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWOT,
            CASE WHEN @IncludeLatestCP = 1 THEN ISNULL(S.LATESTCOSTPRICEWT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALLATESTCOSTPRICEWT,
            CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(S.AVGCOSTPRICEWOT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWOT,
            CASE WHEN @IncludeAvgCP = 1 THEN ISNULL(S.AVGCOSTPRICEWT, 0) * S.CURRENTSTOCK ELSE NULL END AS TOTALAVGCOSTPRICEWT,
            S.BRANDNAME,
            S.MANUFACTURERNAME,
            S.BRANCHNAME,
            S.COUNTINGDATE,
            S.BRANCHID,
            CAST(NULL AS INT) AS ITEMPRICEID,
            CAST(NULL AS INT) AS ITEMCODEID,
            S.ITEMID,
            S.CATEGORYID
        FROM SKUResultWithStock S
		WHERE S.CURRENTSTOCK <> 0
        ORDER BY S.BRANCHNAME, S.SKUCODE;
    END;
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_ASOFDATE_DW]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCK_ASOFDATE_DW]
(
    @AsOnDate DATE,
    @BranchID NVARCHAR(1000),
    @ITEMID INT = 0,
    @CategoryID VARCHAR(500),
    @IncludeCategory BIT = 0,
    @IncludeClassification BIT = 0,
    @IncludeHSN BIT = 0,
    @IncludeLatestCP BIT = 1,
    @IncludeAvgCP BIT = 1,
    @IncludeBrand BIT = 0,
	@IncludeItemCodeMRP BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    EXEC [dbo].[USP_RPT_STOCK_ASOFDATE_CORE]
        @AsOnDate = @AsOnDate,
        @BranchID = @BranchID,
        @ITEMID = @ITEMID,
        @CategoryID = @CategoryID,
        @IncludeCategory = @IncludeCategory,
        @IncludeClassification = @IncludeClassification,
        @IncludeHSN = @IncludeHSN,
        @IncludeLatestCP = @IncludeLatestCP,
        @IncludeAvgCP = @IncludeAvgCP,
        @IncludeBrand = @IncludeBrand,
		@IncludeItemCodeMRP = @IncludeItemCodeMRP,
        @ReportType = 'D';
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCK_ASOFDATE_WH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCK_ASOFDATE_WH]
(
    @AsOnDate DATE,
    @BranchID NVARCHAR(1000),
    @ITEMID INT = 0,
    @CategoryID VARCHAR(500),
    @IncludeCategory BIT = 0,
    @IncludeClassification BIT = 0,
    @IncludeHSN BIT = 0,
    @IncludeLatestCP BIT = 1,
    @IncludeAvgCP BIT = 1,
    @IncludeBrand BIT = 0,
	@IncludeItemCodeMRP BIT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    EXEC [dbo].[USP_RPT_STOCK_ASOFDATE_CORE]
        @AsOnDate = @AsOnDate,
        @BranchID = @BranchID,
        @ITEMID = @ITEMID,
        @CategoryID = @CategoryID,
        @IncludeCategory = @IncludeCategory,
        @IncludeClassification = @IncludeClassification,
        @IncludeHSN = @IncludeHSN,
        @IncludeLatestCP = @IncludeLatestCP,
        @IncludeAvgCP = @IncludeAvgCP,
        @IncludeBrand = @IncludeBrand,
		@IncludeItemCodeMRP = @IncludeItemCodeMRP,
        @ReportType = 'W';
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCKADJUSTMENT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCKADJUSTMENT]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(500)
	, @CategoryID VARCHAR(500) 
	, @ItemCodeID INT = 0
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeTime BIT = 0
	, @IncludeCreatedBy BIT = 0
	, @IncludeDescription BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0

)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')

	CREATE TABLE #STOCKADJUSTMENTS(ITEMPRICEID INT, BRANCHID INT
		, PREVQUANTITY DECIMAL(11, 2), ADJQUANTITY DECIMAL(11, 2), AFTERQUANTITY DECIMAL(11, 2),
		AVGCOSTPRICEWOT DECIMAL(14, 2), AVGCOSTPRICEWT DECIMAL(14, 2), AVGCOSTPRICETAX DECIMAL(14, 2), 
		SALEPRICEWOT DECIMAL(14, 2), SALEPRICEWT DECIMAL(14, 2), SALEPRICETAX DECIMAL(14, 2), 
		TOTALCPEWOT DECIMAL(14, 2), TOTALCPWT DECIMAL(14, 2), TOTALCPTAX DECIMAL(14, 2), 
		TOTALSPWOT DECIMAL(14, 2), TOTALSPWT DECIMAL(14, 2), TOTALSPTAX DECIMAL(14, 2),
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT, CREATETIME TIME, CREATEDBY INT, STOCKADUSTMENTTYPEID INT, DESCRIPTION VARCHAR(MAX)
		, BRANDID INT, MANUFACTURERID INT)

	INSERT INTO #STOCKADJUSTMENTS(ITEMPRICEID, BRANCHID, CATEGORYID, SUBCATEGORYID, PERIODOCITY, CREATETIME, CREATEDBY, PREVQUANTITY, ADJQUANTITY, AFTERQUANTITY,
		AVGCOSTPRICEWOT, AVGCOSTPRICEWT, AVGCOSTPRICETAX, SALEPRICEWT, SALEPRICEWOT, SALEPRICETAX, TOTALCPEWOT, TOTALCPWT, TOTALCPTAX, TOTALSPWT, TOTALSPWOT, TOTALSPTAX
		, STOCKADUSTMENTTYPEID, DESCRIPTION, BRANDID, MANUFACTURERID)
	SELECT CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END 
			, CASE WHEN @IncludeTime = 1 THEN CAST(CREATEDDATE AS TIME) ELSE NULL END
			, CASE WHEN @IncludeCreatedBy = 1 THEN CREATEDBY ELSE NULL END,
		SUM(PREVQUANTITY) AS PREVQUANTITY,
		SUM(AFTERQUANTITY) - SUM(PREVQUANTITY) AS ADJQUANTITY,
		SUM(AFTERQUANTITY) AS AFTERQUANTITY,
		MAX(AVGCOSTPRICEWOT) AS AVGCOSTPRICEWOT,
		MAX(AVGCOSTPRICEWT) AS AVGCOSTPRICEWT,
		MAX(AVGCOSTPRICETAX) AS AVGCOSTPRICETAX,
		MAX(SALEPRICE) AS SALEPRICEWT,
		MAX(SALEPRICEWOT) AS SALEPRICEWOT,
		MAX(SALEPRICETAX) AS SALEPRICETAX,
		SUM((AFTERQUANTITY - PREVQUANTITY) * AVGCOSTPRICEWOT) AS TOTALCPWOT,
		SUM((AFTERQUANTITY - PREVQUANTITY) * AVGCOSTPRICEWT) AS TOTALCPWT,
		SUM((AFTERQUANTITY - PREVQUANTITY) * AVGCOSTPRICETAX) AS TOTALCPTAX,
		SUM((AFTERQUANTITY - PREVQUANTITY) * SALEPRICE) AS TOTALSPWT,
		SUM((AFTERQUANTITY - PREVQUANTITY) * SALEPRICEWOT) AS TOTALSPWOT,
		SUM((AFTERQUANTITY - PREVQUANTITY) * SALEPRICETAX) AS TOTALSPTAX
		, CASE WHEN @IncludeDescription = 1 THEN STOCKADJUSTMENTTYPEID ELSE NULL END
		, CASE WHEN @IncludeDescription = 1 THEN DESCRIPTION ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	FROM (
			SELECT IP.ITEMPRICEID,
				SA.BRANCHID,
				I.CATEGORYID, 
				I.SUBCATEGORYID,
				I.BRANDID,
				I.MANUFACTURERID,
				CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SA.QUANTITY ELSE SA.WEIGHTINKGS END AS AFTERQUANTITY, 
				CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SA.PREVQUANTITY ELSE SA.PREVWEIGHTINKGS END AS PREVQUANTITY, 
				ISNULL(AVGCP.COSTPRICEWOT,0) AS AVGCOSTPRICEWOT,
				ISNULL(AVGCP.COSTPRICEWT,0) AS AVGCOSTPRICEWT,
				AVGCP.COSTPRICEWT - AVGCP.COSTPRICEWOT AS AVGCOSTPRICETAX,
				IP.SALEPRICE,
				(IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100 AS SALEPRICEWOT,
				IP.SALEPRICE - ((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100) AS SALEPRICETAX,
				SA.CREATEDDATE, SA.CREATEDBY, SA.STOCKADJUSTMENTTYPEID, SA.DESCRIPTION 
			FROM STOCKADJUSTMENT SA WITH(NOLOCK)
				INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SA.ITEMPRICEID 
				LEFT JOIN AVGCOSTPRICE AVGCP WITH(NOLOCK) ON AVGCP.ITEMCODEID = IP.ITEMCODEID 
					AND AVGCP.MRP = IP.MRP AND AVGCP.AVGCPDATE = DATEFROMPARTS(YEAR(SA.CREATEDDATE), MONTH(SA.CREATEDDATE), 1)
				INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = IP.GSTID
				INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON SA.BRANCHID = BIDS.ITEM
				INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
			WHERE (IP.ITEMCODEID = @ItemCodeID  OR @ItemCodeID = 0)
				AND SA.CREATEDDATE > (@FromDate)
				AND SA.CREATEDDATE < @ToDate
		) AS BD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END
		, CASE WHEN @IncludeTime = 1 THEN CAST(CREATEDDATE AS TIME) ELSE NULL END
		, CASE WHEN @IncludeCreatedBy = 1 THEN CREATEDBY ELSE NULL END
		, CASE WHEN @IncludeDescription = 1 THEN STOCKADJUSTMENTTYPEID ELSE NULL END
		, CASE WHEN @IncludeDescription = 1 THEN DESCRIPTION ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	SELECT 
		PT.PERIODOCITY, PT.CREATETIME, B.BRANCHNAME, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, 
		IP.MRP, IP.SALEPRICE, IPGST.GSTCODE, PT.AVGCOSTPRICEWOT, PT.AVGCOSTPRICEWT, PT.AVGCOSTPRICETAX, PT.PREVQUANTITY, PT.ADJQUANTITY, PT.AFTERQUANTITY
		, CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SS.QUANTITY ELSE SS.WEIGHTINKGS END AS CURQUANTITY
		, PT.TOTALCPEWOT, PT.TOTALCPWT, PT.TOTALCPTAX, CU.FULLNAME CREATEDBY, SAT.STOCKADJUSTMENTTYPE, PT.DESCRIPTION
	FROM 
		#STOCKADJUSTMENTS PT WITH(NOLOCK)
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC WITH(NOLOCK) ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN TBLUSER CU WITH(NOLOCK) ON CU.USERID = PT.CREATEDBY
		LEFT JOIN STOCKSUMMARY SS WITH(NOLOCK) ON SS.ITEMPRICEID = PT.ITEMPRICEID AND SS.BRANCHID = PT.BRANCHID
		LEFT JOIN STOCKADJUSTMENTTYPE SAT WITH(NOLOCK) ON SAT.STOCKADJUSTMENTTYPEID = PT.STOCKADUSTMENTTYPEID
		LEFT JOIN GSTDETAIL IPGST WITH(NOLOCK) ON IPGST.GSTID = IP.GSTID
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCKCOUNTING_CONSOLIDATED]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCKCOUNTING_CONSOLIDATED]
(	
	@BranchID INT
	, @CountingDate DATE
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(500)
	, @IncludeUser BIT = 0
)
AS
BEGIN

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')

	SELECT 
		USR.USERNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.SKUCODE, IC.ITEMID, IC.ITEMCODEID, I.ITEMNAME, IC.ITEMCODE
		, IP.MRP, IP.SALEPRICE, ICP.COSTPRICEWOT, ICP.COSTPRICEWT - ICP.COSTPRICEWOT AS COSTPRICETAX, ICP.COSTPRICEWT
		, CASE WHEN I.ISOPENITEM = 0 THEN SCC.QUANTITY ELSE SCC.WEIGHTINKGS END AS QTYORWGHT
		, (CASE WHEN I.ISOPENITEM = 0 THEN SCC.QUANTITY ELSE SCC.WEIGHTINKGS END) * ICP.COSTPRICEWOT AS TOTALCOSTPRICEWOT
		, (CASE WHEN I.ISOPENITEM = 0 THEN SCC.QUANTITY ELSE SCC.WEIGHTINKGS END) * ICP.COSTPRICEWT AS TOTALCOSTPRICEWT
	FROM
		(
			SELECT SCD.ITEMPRICEID, SUM(SCD.QUANTITY) * 1.00 QUANTITY, SUM(SCD.WEIGHTINKGS) WEIGHTINKGS
				, CASE WHEN @IncludeUser = 1 THEN USR.USERID ELSE NULL END USERID
			FROM
				STOCKCOUNTINGDETAIL SCD
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SCD.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
				INNER JOIN STOCKCOUNTING SC ON SC.STOCKCOUNTINGID = SCD.STOCKCOUNTINGID
				INNER JOIN TBLUSER USR ON USR.USERID = SC.CREATEDBY
			WHERE
				SCD.DELETEDDATE IS NULL
				AND CAST(ISNULL(SC.STOCKACCEPTEDDATE, SC.CREATEDDATE) AS DATE) = @CountingDate
				AND SC.BRANCHID = @BranchID
				AND (I.ITEMID = @ITEMID OR @ITEMID = 0)
			GROUP BY SCD.ITEMPRICEID, CASE WHEN @IncludeUser = 1 THEN USR.USERID ELSE NULL END
		) SCC
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SCC.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN 
			(
				SELECT ICP.ITEMPRICEID, MAX(ICP.ITEMCOSTPRICEID) ITEMCOSTPRICEID
				FROM ITEMCOSTPRICE ICP 
				WHERE 
					ICP.DELETEDDATE IS NULL
					AND ICP.CREATEDDATE < @CountingDate
				GROUP BY ICP.ITEMPRICEID
			) MAXICP ON MAXICP.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = MAXICP.ITEMCOSTPRICEID
		LEFT JOIN TBLUSER USR ON USR.USERID = SCC.USERID
	ORDER BY CAT.CATEGORYNAME, I.ITEMNAME

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCKSLIPPAGE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCKSLIPPAGE]
(
	@FromDate DATE
	, @ToDate DATE
	, @ItemID INT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT
		I.ITEMID, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE
		, SA.PREVWEIGHTINKGS - SA.WEIGHTINKGS AS SLIPPAGEWEIGHT, SA.DESCRIPTION
		, CU.USERNAME AS CREATEDBY, SA.CREATEDDATE, CAST(SA.CREATEDDATE AS TIME) CREATEDTIME
	FROM
		STOCKADJUSTMENT SA
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SA.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN TBLUSER CU ON CU.USERID = SA.CREATEDBY
	WHERE
		SA.STOCKADJUSTMENTTYPEID = 4
		AND SA.CREATEDDATE >= @FromDate
		AND SA.CREATEDDATE < @ToDate
		AND (I.ITEMID = @ItemID OR @ItemID = 0)

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STOCKSUMMARY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STOCKSUMMARY]
(
	@BranchIDs VARCHAR(MAX)
	, @CategoryID VARCHAR(MAX)
	, @ItemID INT = 0
	, @IncludePositives BIT = 0
	, @IncludeZeros BIT = 0
	, @IncludeNegatives BIT = 0
	, @IncludeItemCode BIT = 0
	, @IncludeMRP BIT = 0
	, @IncludeLatestCP BIT = 0
	, @IncludeAvgCP BIT = 0
)
AS
BEGIN
	
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')

	DECLARE @CurMonthDATE DATE
	SELECT @CurMonthDATE = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1)

	SELECT 
		I.ITEMID, SS.BRANCHID, I.ISOPENITEM, IC.ITEMCODEID, IP.ITEMPRICEID, IP.MRP
		, CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END QTYORWGHT
		, CAST(0.00 AS DECIMAL(18, 2)) INTRANSITQTYORWGHT
		, CAST(0.00 AS DECIMAL(18, 2)) LATESTCPWT, CAST(0.00 AS DECIMAL(18, 2)) LATESTCPWOT, CAST(0.00 AS DECIMAL(18, 2)) LATESTCPTAX
		, CAST(0.00 AS DECIMAL(18, 2)) AVGCPWT, CAST(0.00 AS DECIMAL(18, 2)) AVGCPWOT, CAST(0.00 AS DECIMAL(18, 2)) AVGCPTAX
	INTO #SSBYPRICE
	FROM
		STOCKSUMMARY SS WITH(NOLOCK)
		INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SS.BRANCHID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID	
	WHERE
		1 = 1
		AND IC.DELETEDDATE IS NULL
		AND IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL
		AND (@ItemID = 0 OR I.ITEMID = @ItemID)

	UPDATE SSBYPRICE
	SET INTRANSITQTYORWGHT = CASE WHEN ISOPENITEM = 1 THEN SDMAIN.WEIGHTINKGS ELSE SDMAIN.QUANTITY END
	FROM
		#SSBYPRICE SSBYPRICE
		INNER JOIN 
			(
				SELECT SD.TOBRANCHID, SDD.ITEMPRICEID, SUM(SDD.DISPATCHQUANTITY) QUANTITY, SUM(SDD.WEIGHTINKGS) WEIGHTINKGS
				FROM 
					STOCKDISPATCH SD WITH(NOLOCK) 
					INNER JOIN STOCKDISPATCHDETAIL SDD WITH(NOLOCK) ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
				WHERE
					SD.DELETEDDATE IS NULL
					AND SDD.DELETEDDATE IS NULL
					AND SD.STATUS = 1
				GROUP BY SD.TOBRANCHID, SDD.ITEMPRICEID
			) SDMAIN ON SDMAIN.TOBRANCHID = SSBYPRICE.BRANCHID AND SDMAIN.ITEMPRICEID = SSBYPRICE.ITEMPRICEID

	UPDATE SS 
	SET SS.AVGCPWT = AVGFCP.COSTPRICEWT, SS.AVGCPWOT = AVGFCP.COSTPRICEWOT, AVGCPTAX = AVGFCP.COSTPRICEWT - AVGFCP.COSTPRICEWOT
	FROM
		#SSBYPRICE SS
		INNER JOIN AVGCOSTPRICE AVGFCP WITH(NOLOCK) ON AVGFCP.ITEMCODEID = SS.ITEMCODEID AND AVGFCP.MRP = SS.MRP AND AVGFCP.AVGCPDATE = @CurMonthDATE
	WHERE @IncludeAvgCP = 1

	UPDATE SS 
	SET SS.LATESTCPWT = ICP.COSTPRICEWT, SS.LATESTCPWOT = ICP.COSTPRICEWOT, SS.LATESTCPTAX = ICP.COSTPRICEWT - ICP.COSTPRICEWOT
	FROM
		#SSBYPRICE SS
		INNER JOIN 
			(
				SELECT SSINNER.ITEMCODEID, SSINNER.MRP, MAX(SED.STOCKENTRYDETAILID) MAXSTOCKENTRYDETAILID
				FROM
					STOCKENTRYDETAIL SED WITH(NOLOCK)
					INNER JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
					INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
					INNER JOIN ITEMPRICE IPINNER WITH(NOLOCK) ON IPINNER.ITEMPRICEID = ICP.ITEMPRICEID
					INNER JOIN #SSBYPRICE SSINNER ON SSINNER.ITEMCODEID = IPINNER.ITEMCODEID AND SSINNER.MRP = IPINNER.MRP
				WHERE
					SE.DELETEDDATE IS NULL
					AND SED.DELETEDDATE IS NULL
					AND SE.STATUS = 1
					AND SED.CPWITHTAX <> 0
				GROUP BY SSINNER.ITEMCODEID, SSINNER.MRP
			) MAXSED ON MAXSED.ITEMCODEID = SS.ITEMCODEID AND MAXSED.MRP = SS.MRP
		INNER JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SED.STOCKENTRYDETAILID = MAXSED.MAXSTOCKENTRYDETAILID
		INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
	WHERE @IncludeLatestCP = 1

	SELECT 
		SSBYPRICE.ITEMID, SSBYPRICE.BRANCHID
		, CASE WHEN @IncludeItemCode = 1 THEN SSBYPRICE.ITEMCODEID ELSE NULL END ITEMCODEID
		, CASE WHEN @IncludeMRP = 1 THEN SSBYPRICE.ITEMPRICEID ELSE NULL END ITEMPRICEID
		, SUM(SSBYPRICE.QTYORWGHT) QTYORWGHT, SUM(SSBYPRICE.INTRANSITQTYORWGHT) INTRANSITQTYORWGHT
		, CAST(0 AS BIT) ISNEGATIVE, CAST(0 AS BIT) ISZERO, CAST(0 AS BIT) ISPOSITIVE
		, CAST(CASE WHEN @IncludeAvgCP = 1 THEN SUM(AVGCPWT * SSBYPRICE.QTYORWGHT) / CASE WHEN SUM(SSBYPRICE.QTYORWGHT) = 0 THEN 1 ELSE SUM(SSBYPRICE.QTYORWGHT) END ELSE NULL END AS DECIMAL(18, 2)) AVGCPWT
		, CAST(CASE WHEN @IncludeAvgCP = 1 THEN SUM(AVGCPWOT * SSBYPRICE.QTYORWGHT) / CASE WHEN SUM(SSBYPRICE.QTYORWGHT) = 0 THEN 1 ELSE SUM(SSBYPRICE.QTYORWGHT) END ELSE NULL END AS DECIMAL(18, 2)) AVGCPWOT
		, CAST(CASE WHEN @IncludeAvgCP = 1 THEN SUM(AVGCPWT * SSBYPRICE.QTYORWGHT) ELSE NULL END AS DECIMAL(18, 2)) TAVGCPWT
		, CAST(CASE WHEN @IncludeAvgCP = 1 THEN SUM(AVGCPWOT * SSBYPRICE.QTYORWGHT) ELSE NULL END AS DECIMAL(18, 2)) TAVGCPWOT
		, CAST(CASE WHEN @IncludeLatestCP = 1 THEN SUM(LATESTCPWT * SSBYPRICE.QTYORWGHT) / CASE WHEN SUM(SSBYPRICE.QTYORWGHT) = 0 THEN 1 ELSE SUM(SSBYPRICE.QTYORWGHT) END ELSE NULL END AS DECIMAL(18, 2)) LATESTCPWT
		, CAST(CASE WHEN @IncludeLatestCP = 1 THEN SUM(LATESTCPWOT * SSBYPRICE.QTYORWGHT) / CASE WHEN SUM(SSBYPRICE.QTYORWGHT) = 0 THEN 1 ELSE SUM(SSBYPRICE.QTYORWGHT) END ELSE NULL END AS DECIMAL(18, 2)) LATESTCPWOT
		, CAST(CASE WHEN @IncludeLatestCP = 1 THEN SUM(LATESTCPWT * SSBYPRICE.QTYORWGHT) ELSE NULL END AS DECIMAL(18, 2)) TLATESTCPWT
		, CAST(CASE WHEN @IncludeLatestCP = 1 THEN SUM(LATESTCPWOT * SSBYPRICE.QTYORWGHT) ELSE NULL END AS DECIMAL(18, 2)) TLATESTCPWOT
	INTO #SSGROUPED
	FROM #SSBYPRICE SSBYPRICE	
	GROUP BY
		SSBYPRICE.ITEMID, SSBYPRICE.BRANCHID
		, CASE WHEN @IncludeItemCode = 1 THEN SSBYPRICE.ITEMCODEID ELSE NULL END
		, CASE WHEN @IncludeMRP = 1 THEN SSBYPRICE.ITEMPRICEID ELSE NULL END

	UPDATE #SSGROUPED
	SET ISNEGATIVE = CASE WHEN QTYORWGHT < 0 THEN 1 ELSE 0 END
		, ISZERO = CASE WHEN QTYORWGHT = 0 THEN 1 ELSE 0 END
		, ISPOSITIVE = CASE WHEN QTYORWGHT > 0 THEN 1 ELSE 0 END
		, TAVGCPWT = CASE WHEN QTYORWGHT <= 0 THEN 0 ELSE TAVGCPWT END
		, TAVGCPWOT = CASE WHEN QTYORWGHT <= 0 THEN 0 ELSE TAVGCPWOT END 
		, TLATESTCPWOT = CASE WHEN QTYORWGHT <= 0 THEN 0 ELSE TLATESTCPWOT END 
		, TLATESTCPWT = CASE WHEN QTYORWGHT <= 0 THEN 0 ELSE TLATESTCPWT END 
		

	DELETE #SSGROUPED
	WHERE 
		(@IncludeNegatives = 0 AND ISNEGATIVE = 1)
		OR (@IncludeZeros = 0 AND ISZERO = 1)
		OR (@IncludePositives = 0 AND ISPOSITIVE = 1)
	

	SELECT BRANCHNAME, CATEGORYNAME, SUBCATEGORYNAME, CLASSIFICATIONNAME, SUBCLASSIFICATIONNAME,BRANDNAME, MANUFACTURERNAME, SKUCODE
		, ITEMNAME, ITEMCODE, MRP, SALEPRICE, QTYORWGHT, INTRANSITQTYORWGHT		
		, ISNULL(THRESHOLD, 0) IndentThreshold, ISNULL(DESIREDQUANTITY, 0) IndentDesiredQuantity
		, SS.AVGCPWOT, SS.AVGCPWT, SS.AVGCPWT - SS.AVGCPWOT AVGCPTAX
		, SS.TAVGCPWOT, SS.TAVGCPWT, SS.TAVGCPWT - SS.TAVGCPWOT TAVGCPTAX
		, SS.LATESTCPWOT, SS.LATESTCPWT, SS.LATESTCPWT - SS.LATESTCPWOT LATESTCPTAX
		, SS.TLATESTCPWOT, SS.TLATESTCPWT, SS.TLATESTCPWT - SS.TLATESTCPWOT TLATESTCPTAX
	FROM
		#SSGROUPED SS
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SS.ITEMID
		INNER JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = I.CATEGORYID
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = SS.ITEMCODEID
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS WITH(NOLOCK) ON ISCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		LEFT JOIN TBLBRAND TB WITH(NOLOCK) ON I.BRANDID = TB.BRANDID
		LEFT JOIN TBLMANUFACTURER TM WITH(NOLOCK) ON I.MANUFACTURERID = TM.MANUFACTURERID		
		LEFT JOIN INDENTLIMIT IL WITH(NOLOCK) ON IL.BRANCHID = B.BRANCHID AND IL.ITEMID = I.ITEMID
	ORDER BY B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.ITEMNAME, SS.QTYORWGHT DESC

	/* 
	version 2

	SELECT ITEMID, ITEMCODEID, ITEMPRICEID, BRANCHID, CAST(QTYORWGHT AS decimal(18, 2)) QTYORWGHT
		, CAST(INTRANSITQTYORWGHT AS decimal(18, 2)) INTRANSITQTYORWGHT
	INTO #SS
	FROM
		(
			SELECT *
				, CASE WHEN (QTYORWGHT > 0) THEN 1 ELSE 0 END AS ISPOSITIVE
				, CASE WHEN (QTYORWGHT = 0) THEN 1 ELSE 0 END AS ISZERO
				, CASE WHEN (QTYORWGHT < 0) THEN 1 ELSE 0 END AS ISNEGATIVE
			FROM
				(
					SELECT 
						I.ITEMID, SS.BRANCHID
						, CASE WHEN @IncludeItemCode = 1 THEN IC.ITEMCODEID ELSE NULL END ITEMCODEID
						, CASE WHEN @IncludeMRP = 1 THEN IP.ITEMPRICEID ELSE NULL END ITEMPRICEID
						, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) QTYORWGHT
						, SUM(CASE WHEN I.ISOPENITEM = 1 THEN SD.WEIGHTINKGS ELSE SD.QUANTITY END) INTRANSITQTYORWGHT				
					FROM
						STOCKSUMMARY SS WITH(NOLOCK)
						INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SS.BRANCHID
						INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
						INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
						INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
						INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
						INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = SS.BRANCHID	
						LEFT JOIN 
							(
								SELECT SD.TOBRANCHID, SDD.ITEMPRICEID, SUM(SDD.DISPATCHQUANTITY) QUANTITY, SUM(SDD.WEIGHTINKGS) WEIGHTINKGS
								FROM 
									STOCKDISPATCH SD WITH(NOLOCK)
									INNER JOIN STOCKDISPATCHDETAIL SDD WITH(NOLOCK) ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
									INNER JOIN #BRANCH BRANCHIDSINNER ON BRANCHIDSINNER.ITEM = SD.TOBRANCHID
								WHERE
									SD.DELETEDDATE IS NULL
									AND SDD.DELETEDDATE IS NULL
									AND SD.STATUS = 1
								GROUP BY SD.TOBRANCHID, SDD.ITEMPRICEID
							) SD ON SD.TOBRANCHID = SS.BRANCHID AND SD.ITEMPRICEID = SS.ITEMPRICEID
					WHERE
						1 = 1
						AND IC.DELETEDDATE IS NULL
						AND IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL
						AND (@ItemID = 0 OR I.ITEMID = @ItemID)
					GROUP BY 
						I.ITEMID, SS.BRANCHID
						, CASE WHEN @IncludeItemCode = 1 THEN IC.ITEMCODEID ELSE NULL END
						, CASE WHEN @IncludeMRP = 1 THEN IP.ITEMPRICEID ELSE NULL END
				) SSINNER				
		) SSMAIN
	WHERE 
		(@IncludePositives = 1 AND ISPOSITIVE = 1)
		OR (@IncludeZeros = 1 AND ISZERO = 1)
		OR (@IncludeNegatives = 1 AND ISNEGATIVE = 1)
	
	SELECT BRANCHNAME, CATEGORYNAME, SUBCATEGORYNAME, CLASSIFICATIONNAME, SUBCLASSIFICATIONNAME,BRANDNAME, MANUFACTURERNAME, SKUCODE
		, ITEMNAME, ITEMCODE, MRP, SALEPRICE, QTYORWGHT, INTRANSITQTYORWGHT		
		, THRESHOLD IndentThreshold, DESIREDQUANTITY IndentDesiredQuantity
	FROM
		#SS SS
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SS.ITEMID
		INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
		INNER JOIN BRANCH B ON B.BRANCHID = SS.BRANCHID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = SS.ITEMCODEID
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = SS.ITEMPRICEID
		LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
		LEFT JOIN ITEMCLASSIFICATION ICLS ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS ON ISCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
		LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
		LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID		
		LEFT JOIN INDENTLIMIT IL ON IL.BRANCHID = B.BRANCHID AND IL.ITEMID = I.ITEMID
	ORDER BY B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.ITEMNAME, SS.QTYORWGHT DESC
	*/

	/*
	version 1

	SELECT BRANCHNAME, CATEGORYNAME, SUBCATEGORYNAME, CLASSIFICATIONNAME, SUBCLASSIFICATIONNAME,BRANDNAME, MANUFACTURERNAME, SKUCODE
		, ITEMNAME, ITEMCODE, MRP, SALEPRICE, QTYORWGHT, INTRANSITQTYORWGHT, THRESHOLD IndentThreshold, DESIREDQUANTITY IndentDesiredQuantity
	FROM
		(
			SELECT 
				B.BRANCHNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME,TB.BRANDNAME, TM.MANUFACTURERNAME
				, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IP.MRP, IP.SALEPRICE
				, (CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) QTYORWGHT
				, (CASE WHEN I.ISOPENITEM = 1 THEN SD.WEIGHTINKGS ELSE SD.QUANTITY END) INTRANSITQTYORWGHT
				, CASE WHEN ((CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) > 0) THEN 1 ELSE 0 END AS ISPOSITIVE
				, CASE WHEN ((CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) = 0) THEN 1 ELSE 0 END AS ISZERO
				, CASE WHEN ((CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) < 0) THEN 1 ELSE 0 END AS ISNEGATIVE
				, IL.THRESHOLD, IL.DESIREDQUANTITY
			FROM
				STOCKSUMMARY SS
				INNER JOIN #BRANCH BRANCHIDS ON BRANCHIDS.ITEM = SS.BRANCHID
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SS.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
				INNER JOIN BRANCH B ON B.BRANCHID = SS.BRANCHID
				INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID
				LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID
				LEFT JOIN ITEMCLASSIFICATION ICLS ON ICLS.CLASSIFICATIONID = I.CLASSIFICATIONID
				LEFT JOIN ITEMSUBCLASSIFICATION ISCLS ON ISCLS.SUBCLASSIFICATIONID = I.SUBCLASSIFICATIONID
				LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
				LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
				LEFT JOIN 
					(
						SELECT SD.TOBRANCHID, SDD.ITEMPRICEID, SUM(SDD.DISPATCHQUANTITY) QUANTITY, SUM(SDD.WEIGHTINKGS) WEIGHTINKGS
						FROM 
							STOCKDISPATCH SD 
							INNER JOIN STOCKDISPATCHDETAIL SDD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
							INNER JOIN #BRANCH BRANCHIDSINNER ON BRANCHIDSINNER.ITEM = SD.TOBRANCHID
						WHERE
							SD.DELETEDDATE IS NULL
							AND SDD.DELETEDDATE IS NULL
							AND SD.STATUS = 1
						GROUP BY SD.TOBRANCHID, SDD.ITEMPRICEID
					) SD ON SD.TOBRANCHID = SS.BRANCHID AND SD.ITEMPRICEID = SS.ITEMPRICEID
				LEFT JOIN INDENTLIMIT IL ON IL.BRANCHID = B.BRANCHID AND IL.ITEMID = I.ITEMID
			WHERE
				1 = 1
				AND IC.DELETEDDATE IS NULL
				AND (@ItemID = 0 OR I.ITEMID = @ItemID)
		) SSMAIN
	WHERE 
		(@IncludePositives = 1 AND ISPOSITIVE = 1)
		OR (@IncludeZeros = 1 AND ISZERO = 1)
		OR (@IncludeNegatives = 1 AND ISNEGATIVE = 1)
	ORDER BY SSMAIN.BRANCHNAME, SSMAIN.CATEGORYNAME, SSMAIN.ITEMNAME, SSMAIN.MRP

	*/

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_STORE_BREFUND_REGISTER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_STORE_BREFUND_REGISTER]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(MAX)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeReason BIT = 0
	, @IncludeRefundNumber BIT = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(MAX)
	, @IncludeTrayNumber BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, QUANTITY DECIMAL(18, 2),
		COSTPRICEWOT DECIMAL(18, 2), COSTPRICEWT DECIMAL(18, 2), COSTPRICETAX DECIMAL(18, 2), 
		TOTALCPWOT DECIMAL(18, 2), TOTALCPWT DECIMAL(18, 2), TOTALCPTAX DECIMAL(18, 2), 
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT,
		REASONID INT,BRID INT,REFUNDSTATUS BIT,APPROVEDBY INT, APPROVEDDATE DATETIME, AVGCOSTPRICEID INT, 
		TRAYNUMBER INT, BRANDID INT, MANUFACTURERID INT, DESTINATIONBRANCHID INT)

	-- Extract base branch refund data from store (originating branch)
	-- Use UPDATEDDATE for store transaction date (when stock leaves the store)
	-- Include all refunds regardless of deletion status
	SELECT BRD.ITEMPRICEID, 
		BR.BRANCHID AS BRANCHID,
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		I.BRANDID,
		I.MANUFACTURERID,
		CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN ISNULL(BRD.ACCEPTEDQUANTITY, BRD.QUANTITY) ELSE ISNULL(BRD.ACCEPTEDWEIGHTKGS, BRD.WEIGHTINKGS) END AS QUANTITY,
		BR.UPDATEDDATE,
		BRD.REASONID,
		BR.BRID,
		ISNULL(BR.IsAccepted,0) AS IsAccepted,
		CASE WHEN ISNULL(BR.IsAccepted,0) = 1 THEN BR.UPDATEDBY ELSE NULL END AS APPROVEDBY,
		CASE WHEN ISNULL(BR.IsAccepted,0) = 1 THEN BR.UPDATEDDATE ELSE NULL END AS APPROVEDDATE, 
		AICP.AVGCOSTPRICEID, 
		BRD.TRAYNUMBER,
		ISNULL(ROR.LOCATIONTOMOVESTOCK, 0) AS DESTINATIONBRANCHID
	INTO #BRD
	FROM POS_BREFUNDDETAIL BRD WITH(NOLOCK) 
		INNER JOIN POS_BREFUND BR WITH(NOLOCK) ON BR.BRID = BRD.BRID
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = BRD.ITEMPRICEID 
		LEFT JOIN AVGCOSTPRICE AICP WITH(NOLOCK) ON AICP.ITEMCODEID = IP.ITEMCODEID AND AICP.MRP = IP.MRP AND AICP.AVGCPDATE = DATEFROMPARTS(YEAR(BR.UPDATEDDATE), MONTH(BR.UPDATEDDATE), 1)
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = IP.GSTID
		INNER JOIN #BRANCH B ON BR.BRANCHID = B.ITEM
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
		LEFT JOIN REASONFORREFUND ROR WITH(NOLOCK) ON BRD.REASONID = ROR.REASONID
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND BR.UPDATEDDATE > (@FromDate)
		AND BR.UPDATEDDATE < @ToDate
		AND BR.DELETEDDATE IS NULL
		AND BRD.DELETEDDATE IS NULL

	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, CATEGORYID,SUBCATEGORYID,
		PERIODOCITY,REASONID,BRID,REFUNDSTATUS,APPROVEDBY,APPROVEDDATE,QUANTITY, AVGCOSTPRICEID
		, TOTALCPWOT, TOTALCPTAX, TOTALCPWT, TRAYNUMBER,BRANDID, MANUFACTURERID, DESTINATIONBRANCHID)
	SELECT CASE WHEN @IncludeItem = 1 THEN BRD.ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRD.BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN BRD.CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN BRD.SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(BRD.UPDATEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(BRD.UPDATEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(BRD.UPDATEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(BRD.UPDATEDDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END 
			, CASE WHEN @IncludeReason = 1 THEN BRD.REASONID ELSE NULL END AS REASONID
			, CASE WHEN @IncludeRefundNumber = 1 THEN BRD.BRID ELSE NULL END AS BRID
			, CASE WHEN @IncludeItem = 1 THEN BRD.IsAccepted ELSE NULL END AS IsAccepted
			, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDBY ELSE NULL END AS APPROVEDBY
			, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDDATE ELSE NULL END AS APPROVEDDATE
			, SUM(BRD.QUANTITY) AS QUANTITY
			, CASE WHEN @IncludeItem = 1 THEN BRD.AVGCOSTPRICEID ELSE NULL END
			, SUM(AICP.COSTPRICEWOT * BRD.QUANTITY), SUM((AICP.COSTPRICEWT - AICP.COSTPRICEWOT) * BRD.QUANTITY) , SUM(AICP.COSTPRICEWT * BRD.QUANTITY)
			, CASE WHEN @IncludeTrayNumber = 1 THEN BRD.TRAYNUMBER ELSE NULL END
			, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
			, CASE WHEN @IncludeReason = 1 THEN BRD.DESTINATIONBRANCHID ELSE NULL END
	FROM #BRD BRD
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.AVGCOSTPRICEID = BRD.AVGCOSTPRICEID
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN BRD.ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRD.BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN BRD.CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN BRD.SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(BRD.UPDATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(BRD.UPDATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(BRD.UPDATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(BRD.UPDATEDDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeReason = 1 THEN BRD.REASONID ELSE NULL END
		, CASE WHEN @IncludeRefundNumber = 1 THEN BRD.BRID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.IsAccepted ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDBY ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDDATE ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.AVGCOSTPRICEID ELSE NULL END
		, CASE WHEN @IncludeTrayNumber = 1 THEN BRD.TRAYNUMBER ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
		, CASE WHEN @IncludeReason = 1 THEN BRD.DESTINATIONBRANCHID ELSE NULL END

	SELECT 
		PT.PERIODOCITY
		, B.BRANCHNAME
		, CAT.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, TBR.BRANDNAME
		, MAN.MANUFACTURERNAME
		, I.SKUCODE
		, I.VENDORSKUCODE
		, I.ITEMNAME
		, IC.ITEMCODE
		, IC.HSNCODE
		, IP.MRP
		, GST.GSTCODE
		, PT.QUANTITY
		, AICP.COSTPRICEWOT
		, AICP.COSTPRICEWT - AICP.COSTPRICEWOT COSTPRICETAX
		, AICP.COSTPRICEWT
		, PT.TOTALCPWOT TOTALCPEWOT
		, PT.TOTALCPTAX
		, PT.TOTALCPWT
		, RFR.REASONNAME AS Reason
		, BR.BREFUNDNUMBER
		, CASE WHEN PT.REFUNDSTATUS = 0 THEN 'NOT APPROVED' ELSE 'APPROVED' END AS REFUNDSTATUS
		, AU.FULLNAME AS APPROVEDBY
		, PT.APPROVEDDATE
		, PT.TRAYNUMBER
		, CASE WHEN PT.DESTINATIONBRANCHID = 45 THEN 'Warehouse'
				WHEN PT.DESTINATIONBRANCHID = 100 THEN 'Damage & Wastage'
				ELSE CAST(ISNULL(PT.DESTINATIONBRANCHID, 0) AS VARCHAR(50))
		   END AS DestinationBranch
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC WITH(NOLOCK) ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN REASONFORREFUND RFR WITH(NOLOCK) ON PT.REASONID = RFR.REASONID
		LEFT JOIN POS_BREFUND BR WITH(NOLOCK) ON PT.BRID = BR.BRID
		LEFT JOIN TBLUSER AU WITH(NOLOCK) ON PT.APPROVEDBY = AU.USERID
		LEFT JOIN AVGCOSTPRICE AICP WITH(NOLOCK) ON AICP.AVGCOSTPRICEID = PT.AVGCOSTPRICEID
		LEFT JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = IP.GSTID
		LEFT JOIN TBLBRAND TBR WITH(NOLOCK) ON PT.BRANDID = TBR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN WITH(NOLOCK) ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIER_RETURNS_REGISTER]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SUPPLIER_RETURNS_REGISTER]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(MAX)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeSupplier BIT = 0
	, @IncludeRefundNumber BIT = 0
	, @IncludeUserDetails BIT = 0
	, @ITEMID INT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
	, @ReportMode INT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #PROFITABILIY(ITEMCOSTPRICEID INT, BRANCHID INT, QUANTITY DECIMAL(18, 2),
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT,
		SRID INT, SUPPLIERID INT, CREATEDBY INT, CREATEDDATE DATETIME,
		BRANDID INT, MANUFACTURERID INT, COSTPRICEWOT DECIMAL(18, 2), COSTPRICEWT DECIMAL(18, 2), 
		COSTPRICETAX DECIMAL(18, 2), TOTALCPWOT DECIMAL(18, 2), TOTALCPWT DECIMAL(18, 2), 
		TOTALCPTAX DECIMAL(18, 2))

	-- Extract base supplier returns data
	-- Reports items returned to suppliers from selected source branches
	-- Filter by SOURCE branch only
	-- Transaction date uses CNINITIATEDDATE (debit note date) or CREATEDDATE (fallback)
	-- Status filter (controlled by @IncludeWriteOff):
	--   @IncludeWriteOff = 0 (default): Status IN (1, 2, 3) = Normal returns (Open, Partially Closed, Closed)
	--   @IncludeWriteOff = 1: Status = 4 = Write-off/Nullify returns only
	-- Aligns with USP_RPT_ITEMLEDGER for open/closed item handling
	SELECT SRD.ITEMCOSTPRICEID, 
		SR.BRANCHID,
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		I.BRANDID,
		I.MANUFACTURERID,
		-- Quantity: use weight for open items, quantity for closed items
		CASE 
			WHEN I.ISOPENITEM = 1 THEN ISNULL(SRD.WEIGHTINKGS, SRD.QUANTITY)
			ELSE SRD.QUANTITY
		END AS QUANTITY,
		ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) AS TRANSACTIONDATE,
		SR.SUPPLIERRETURNSID AS SRID,
		SR.SUPPLIERID,
		SR.CNINITIATEDBY AS CREATEDBY,
		ISNULL(ICP.GSTID, 0) AS GSTID,
		ICP.COSTPRICEWOT,
		ICP.COSTPRICEWT,
		ICP.COSTPRICEWT - ICP.COSTPRICEWOT AS COSTPRICETAX
	INTO #SRD
	FROM SUPPLIERRETURNSDETAIL SRD
		INNER JOIN SUPPLIERRETURNS SR ON SR.SUPPLIERRETURNSID = SRD.SUPPLIERRETURNSID
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN #BRANCH B ON SR.BRANCHID = B.ITEM
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) > (@FromDate)
		AND ISNULL(SR.CNINITIATEDDATE, SRD.CREATEDDATE) < @ToDate
		AND SRD.DELETEDDATE IS NULL
		AND SR.DELETEDDATE IS NULL
		AND (
			(ISNULL(@ReportMode, 0) = 0 AND ISNULL(SR.STATUS, 0) IN (1, 2, 3))
			OR (ISNULL(@ReportMode, 0) = 1 AND ISNULL(SR.STATUS, 0) = 4)
		)

	INSERT INTO #PROFITABILIY(ITEMCOSTPRICEID, BRANCHID, CATEGORYID, SUBCATEGORYID,
		PERIODOCITY, SRID, SUPPLIERID, CREATEDBY, CREATEDDATE, QUANTITY, GSTID, BRANDID, MANUFACTURERID,
		COSTPRICEWOT, COSTPRICEWT, COSTPRICETAX, TOTALCPWOT, TOTALCPWT, TOTALCPTAX)
	SELECT CASE WHEN @IncludeItem = 1 THEN SRD.ITEMCOSTPRICEID ELSE NULL END
			, SRD.BRANCHID
			, CASE WHEN @IncludeCategory = 1 THEN SRD.CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SRD.SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(SRD.TRANSACTIONDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(SRD.TRANSACTIONDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(SRD.TRANSACTIONDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(SRD.TRANSACTIONDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END 
			, CASE WHEN @IncludeRefundNumber = 1 THEN SRD.SRID ELSE NULL END AS SRID
			, CASE WHEN @IncludeSupplier = 1 THEN SRD.SUPPLIERID ELSE NULL END
			, CASE WHEN @IncludeUserDetails = 1 THEN SRD.CREATEDBY ELSE NULL END AS CREATEDBY
			, CASE WHEN @IncludeUserDetails = 1 THEN SRD.TRANSACTIONDATE ELSE NULL END AS CREATEDDATE
			, SUM(SRD.QUANTITY) AS QUANTITY
			, CASE WHEN @IncludeItem = 1 THEN SRD.GSTID ELSE NULL END
			, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
			, AVG(SRD.COSTPRICEWOT)
			, AVG(SRD.COSTPRICEWT)
			, AVG(SRD.COSTPRICETAX)
			, SUM(SRD.COSTPRICEWOT * SRD.QUANTITY)
			, SUM(SRD.COSTPRICEWT * SRD.QUANTITY)
			, SUM(SRD.COSTPRICETAX * SRD.QUANTITY)
	FROM #SRD SRD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN SRD.ITEMCOSTPRICEID ELSE NULL END
		, SRD.BRANCHID
		, CASE WHEN @IncludeCategory = 1 THEN SRD.CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SRD.SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(SRD.TRANSACTIONDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(SRD.TRANSACTIONDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(SRD.TRANSACTIONDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(SRD.TRANSACTIONDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeRefundNumber = 1 THEN SRD.SRID ELSE NULL END
		, CASE WHEN @IncludeSupplier = 1 THEN SRD.SUPPLIERID ELSE NULL END
		, CASE WHEN @IncludeUserDetails = 1 THEN SRD.CREATEDBY ELSE NULL END
		, CASE WHEN @IncludeUserDetails = 1 THEN SRD.TRANSACTIONDATE ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.GSTID ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN SRD.BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN SRD.MANUFACTURERID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.COSTPRICEWOT ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.COSTPRICEWT ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.COSTPRICETAX ELSE NULL END

	SELECT 
		PT.PERIODOCITY
		, SOURCEB.BRANCHNAME AS SourceBranch
		, CASE WHEN @IncludeSupplier = 1 THEN SUPPLIER.DEALERNAME ELSE NULL END AS SupplierName
		, CAT.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, BR.BRANDNAME
		, MAN.MANUFACTURERNAME
		, I.SKUCODE
		, I.VENDORSKUCODE
		, I.ITEMNAME
		, IC.ITEMCODE
		, IC.HSNCODE
		, IP.MRP
		, GST.GSTCODE
		, PT.QUANTITY
		, PT.COSTPRICEWOT
		, PT.COSTPRICETAX
		, PT.COSTPRICEWT
		, PT.TOTALCPWOT
		, PT.TOTALCPTAX
		, PT.TOTALCPWT
		, CASE WHEN @IncludeUserDetails = 1 THEN AU.FULLNAME ELSE NULL END AS CreatedBy
		, CASE WHEN @IncludeUserDetails = 1 THEN PT.CREATEDDATE ELSE NULL END AS CreatedDate
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMCOSTPRICE ICP ON PT.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		LEFT JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH SOURCEB ON PT.BRANCHID = SOURCEB.BRANCHID
		LEFT JOIN TBLDEALER SUPPLIER ON PT.SUPPLIERID = SUPPLIER.DEALERID
		LEFT JOIN TBLUSER AU ON PT.CREATEDBY = AU.USERID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = PT.GSTID
		LEFT JOIN TBLBRAND BR ON PT.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY PT.PERIODOCITY, SOURCEB.BRANCHNAME, SUPPLIER.DEALERNAME, I.ITEMNAME

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIERINDENTVSSTOCKENTRY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_RPT_SUPPLIERINDENTVSSTOCKENTRY]
(
	@FromDate DATE,
	@ToDate DATE,
	@CategoryIDs VARCHAR(500),
	@SupplierID INT,
	@IncludeDate BIT = 0,
	@IncludeSupplier BIT = 0,
	@IncludeCategory BIT = 0,
	@IncludeSubCategory BIT = 0,
	@IncludeItem BIT = 0,
	@IncludeIndentNo BIT = 0,
	@IncludeInvoiceNo BIT = 0,
	@IncludeZeroIndents BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #CATEGORY FROM DBO.SplitString(@CategoryIDs, ',')

	SELECT 
		CASE WHEN @IncludeDate = 1 THEN CAST(SI.CREATEDDATE AS DATE) ELSE NULL END IndentDate
		, CASE WHEN @IncludeSupplier = 1 THEN SI.SUPPLIERID ELSE NULL END SUPPLIERID
		, CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END CATEGORYID
		, CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END SUBCATEGORYID
		, CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END ITEMID
		, CASE WHEN @IncludeIndentNo = 1 THEN SI.SUPPLIERINDENTID ELSE NULL END SUPPLIERINDENTID
		, CASE WHEN @IncludeInvoiceNo = 1 THEN SEDGROUPED.STOCKENTRYID ELSE NULL END STOCKENTRYID
		, CAST(SUM(SID.REQUIREDITEMINDENT) AS INT) IndentQty , SUM(SID.DESIREDINDENT) AdjustedQty, SUM(SEDGROUPED.SEQUANTITY) ReceivedQty
		, CAST(ROUND((SUM(SEDGROUPED.SEQUANTITY) * 100.00 / SUM(SID.DESIREDINDENT)), 2) AS DECIMAL(18, 2)) FillRatioPerc
	INTO #INDENT_VS_ENTRY
	FROM 
		SUPPLIERINDENT SI WITH(NOLOCK)
		INNER JOIN SUPPLIERINDENTDETAIL SID WITH(NOLOCK) ON SID.SUPPLIERINDENTID = SI.SUPPLIERINDENTID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = SID.ITEMID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
		LEFT JOIN 
			(
				SELECT CASE WHEN @IncludeInvoiceNo = 1 THEN SED.STOCKENTRYID ELSE NULL END STOCKENTRYID, I.ITEMID
					   , CAST(ROUND(SUM(CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END), 0) AS INT) SEQUANTITY
					   , SE.SUPPLIERINDENTID
				FROM 
					STOCKENTRY SE WITH(NOLOCK) 
					INNER JOIN STOCKENTRYDETAIL SED WITH(NOLOCK) ON SE.STOCKENTRYID = SED.STOCKENTRYID
					INNER JOIN ITEMCOSTPRICE ICP WITH(NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
					INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
					INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
				WHERE 
					SE.DELETEDDATE IS NULL
					AND SED.DELETEDDATE IS NULL
				GROUP BY CASE WHEN @IncludeInvoiceNo = 1 THEN SED.STOCKENTRYID ELSE NULL END, I.ITEMID, SE.SUPPLIERINDENTID
			) SEDGROUPED ON SEDGROUPED.ITEMID = SID.ITEMID AND SEDGROUPED.SUPPLIERINDENTID = SI.SUPPLIERINDENTID
	WHERE
		SI.CREATEDDATE >= @FromDate
		AND SI.CREATEDDATE < @ToDate
		AND SI.DELETEDDATE IS NULL
		AND SID.DELETEDDATE IS NULL
		AND (SI.SUPPLIERID = @SupplierID OR @SupplierID = 0)
		AND (SI.ISINTERNAL = 0 OR @IncludeZeroIndents = 1)
	GROUP BY
		CASE WHEN @IncludeDate = 1 THEN CAST(SI.CREATEDDATE AS DATE) ELSE NULL END 
		, CASE WHEN @IncludeSupplier = 1 THEN SI.SUPPLIERID ELSE NULL END 
		, CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END 
		, CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END 
		, CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END 
		, CASE WHEN @IncludeIndentNo = 1 THEN SI.SUPPLIERINDENTID ELSE NULL END 
		, CASE WHEN @IncludeInvoiceNo = 1 THEN SEDGROUPED.STOCKENTRYID ELSE NULL END

	
	/* Add stock entries that have no supplier indent */
	INSERT INTO #INDENT_VS_ENTRY (IndentDate, SUPPLIERID, CATEGORYID, SUBCATEGORYID, ITEMID, SUPPLIERINDENTID,
		STOCKENTRYID, IndentQty, AdjustedQty, ReceivedQty, FillRatioPerc)
	SELECT
		CASE WHEN @IncludeDate = 1 THEN CAST(SE.INVOICEDATE AS DATE) ELSE NULL END AS IndentDate,
		CASE WHEN @IncludeSupplier = 1 THEN SE.SUPPLIERID ELSE NULL END AS SUPPLIERID, 
		CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END AS CATEGORYID,
		CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END AS SUBCATEGORYID,
		CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END AS ITEMID,
		CAST(NULL AS INT) AS SUPPLIERINDENTID,
		CASE WHEN @IncludeInvoiceNo = 1 THEN SE.STOCKENTRYID ELSE NULL END AS STOCKENTRYID,
		0 AS IndentQty,
		0 AS AdjustedQty,
		CAST(ROUND(SUM(CASE WHEN I.ISOPENITEM = 1 THEN SED.WEIGHTINKGS ELSE SED.QUANTITY END ), 0) AS INT) AS ReceivedQty,
		CAST(NULL AS DECIMAL(18, 2)) AS FillRatioPerc
	FROM STOCKENTRY SE WITH (NOLOCK)
		INNER JOIN STOCKENTRYDETAIL SED WITH (NOLOCK) ON SED.STOCKENTRYID = SE.STOCKENTRYID
		INNER JOIN ITEMCOSTPRICE ICP WITH (NOLOCK) ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP WITH (NOLOCK) ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN ITEMCODE IC WITH (NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH (NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
	WHERE
		SE.SUPPLIERINDENTID IS NULL
		AND SE.DELETEDDATE IS NULL
		AND SED.DELETEDDATE IS NULL
		-- Date range for direct receipts
		AND SE.INVOICEDATE >= @FromDate
		AND SE.INVOICEDATE < @ToDate
		-- Supplier filter
		AND (SE.SUPPLIERID = @SupplierID OR @SupplierID = 0)
	GROUP BY
		CASE WHEN @IncludeDate = 1 THEN CAST(SE.INVOICEDATE AS DATE) ELSE NULL END,
		CASE WHEN @IncludeSupplier = 1 THEN SE.SUPPLIERID ELSE NULL END,
		CASE WHEN @IncludeCategory = 1 THEN I.CATEGORYID ELSE NULL END,
		CASE WHEN @IncludeSubCategory = 1 THEN I.SUBCATEGORYID ELSE NULL END,
		CASE WHEN @IncludeItem = 1 THEN I.ITEMID ELSE NULL END,
		CASE WHEN @IncludeInvoiceNo = 1 THEN SE.STOCKENTRYID ELSE NULL END

			
	SELECT 
		IndentDate, SI.SUPPLIERINDENTNO 'Indent #', DLR.DEALERNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME
		, I.SKUCODE, I.ITEMNAME
		, CASE 
			WHEN @IncludeItem <> 1 THEN NULL
			WHEN IVE.SUPPLIERINDENTID IS NULL THEN 'Manual Stock entry'
			WHEN IVE.IndentQty = 0 THEN 'Added'
			WHEN IVE.AdjustedQty - IVE.IndentQty  <> 0 THEN 'Modified'
			ELSE 'Generated' END AS IndentItem			
		, SE.SUPPLIERINVOICENO 'Invoice #', SE.INVOICEDATE 'Invoice Date'
		, IVE.IndentQty, IVE.AdjustedQty, IVE.AdjustedQty - IVE.IndentQty IndentVariance, IVE.ReceivedQty, IVE.FillRatioPerc 'Fill Ratio %'
	FROM
		#INDENT_VS_ENTRY IVE
		LEFT JOIN TBLDEALER DLR WITH(NOLOCK) ON DLR.DEALERID = IVE.SUPPLIERID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON CAT.CATEGORYID = IVE.CATEGORYID
		LEFT JOIN SUBCATEGORY SUBCAT WITH(NOLOCK) ON SUBCAT.SUBCATEGORYID = IVE.SUBCATEGORYID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IVE.ITEMID
		LEFT JOIN SUPPLIERINDENT SI WITH(NOLOCK) ON SI.SUPPLIERINDENTID = IVE.SUPPLIERINDENTID
		LEFT JOIN STOCKENTRY SE WITH(NOLOCK) ON SE.STOCKENTRYID = IVE.STOCKENTRYID
	ORDER BY IndentDate, DLR.DEALERNAME, CAT.CATEGORYNAME, SUBCAT.SUBCATEGORYNAME, I.ITEMNAME

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIERREFUNDS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SUPPLIERREFUNDS]
(
	@FromDate DATE
	, @ToDate DATE
	, @Periodicity VARCHAR(20)
	, @IncludeDate BIT = 0
	, @IncludeItem BIT = 1
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeReason Bit = 0
	, @IncludeBRefundNumber Bit = 0
	, @IncludeSRefundNumber Bit = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(MAX)
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')

	CREATE TABLE #REPORTDATA(ITEMCOSTPRICEID INT, ITEMPRICEID INT, QUANTITY DECIMAL(18, 2),
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT,
		REASONID INT,BRDID INT,SRID INT,CREATEDBY INT, CREATEDDATE DATETIME, RETURNSTATUS INT, BRANDID INT, MANUFACTURERID INT)

	SELECT SRD.ITEMCOSTPRICEID, 
		ICP.ITEMPRICEID, 
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		I.BRANDID,
		I.MANUFACTURERID,
		SRD.QUANTITY,
		SRD.REASONID,
		SRD.BRDID,
		SRD.SUPPLIERRETURNSID,
		ISNULL(SRD.RETURNSTATUS,0) AS RETURNSTATUS,
		SR.CREATEDBY,
		SRD.CREATEDDATE
	INTO #SRD
	FROM SUPPLIERRETURNSDETAIL SRD
		INNER JOIN SUPPLIERRETURNS SR ON SR.SUPPLIERRETURNSID = SRD.SUPPLIERRETURNSID
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND SRD.CREATEDDATE > @FromDate
		AND SRD.CREATEDDATE < @ToDate
		AND SRD.DELETEDDATE IS NULL

	INSERT INTO #REPORTDATA(ITEMCOSTPRICEID, ITEMPRICEID, CATEGORYID, SUBCATEGORYID,
		PERIODOCITY, REASONID, BRDID, SRID, RETURNSTATUS, CREATEDBY, CREATEDDATE, QUANTITY, BRANDID, MANUFACTURERID)
	SELECT 
			CASE WHEN @IncludeItem = 1 THEN SRD.ITEMCOSTPRICEID ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN SRD.ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN SRD.CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SRD.SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT( SRD.CREATEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(SRD.CREATEDDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END 
			,CASE WHEN @IncludeReason = 1 THEN SRD.REASONID ELSE NULL END AS REASONID
			,CASE WHEN @IncludeBRefundNumber = 1 THEN SRD.BRDID ELSE NULL END AS BRID
			,CASE WHEN @IncludeSRefundNumber = 1 THEN SRD.SUPPLIERRETURNSID ELSE NULL END AS SRID
			,CASE WHEN @IncludeItem = 1 THEN SRD.RETURNSTATUS ELSE NULL END AS RETURNSTATUS
			,CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDBY ELSE NULL END AS CREATEDBY
			,CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDDATE ELSE NULL END AS CREATEDDATE
			,SUM(SRD.QUANTITY) AS QUANTITY
			, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	FROM #SRD SRD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN SRD.ITEMCOSTPRICEID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN SRD.CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SRD.SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(SRD.CREATEDDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeReason = 1 THEN SRD.REASONID ELSE NULL END
		, CASE WHEN @IncludeBRefundNumber = 1 THEN SRD.BRDID ELSE NULL END
		, CASE WHEN @IncludeSRefundNumber = 1 THEN SRD.SUPPLIERRETURNSID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.RETURNSTATUS ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDBY ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDDATE ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	SELECT 
		RD.PERIODOCITY, CAT.CATEGORYNAME,SC.SUBCATEGORYNAME,tBR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.VENDORSKUCODE, I.ITEMNAME, IC.ITEMCODE, IC.HSNCODE
		, IP.MRP, RD.QUANTITY,RFR.REASONNAME AS Reason, RD.BRDID, BR.BREFUNDNUMBER, RD.SRID AS [Supplier Returns #] 
		, SR.SUPPLIERID, DEALER.DEALERNAME AS [Supplier Name]
		--, CASE WHEN ISNULL(RD.RETURNSTATUS,1) = 2 THEN 'Rejected' ELSE'Accepted' END AS RETURNSTATUS
		, AU.FULLNAME AS CREATEDBY, RD.CREATEDDATE
	FROM 
		#REPORTDATA RD
		LEFT JOIN POS_BREFUNDDETAIL BRD ON RD.BRDID = BRD.BRDID
		LEFT JOIN POS_BREFUND BR ON BR.BRID = BRD.BRID
		LEFT JOIN SUPPLIERRETURNS SR ON RD.SRID = SR.SUPPLIERRETURNSID
		LEFT JOIN REASONFORREFUND RFR ON ISNULL(RD.REASONID, BRD.REASONID) = RFR.REASONID
		LEFT JOIN ITEMCOSTPRICE ICP ON RD.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		LEFT JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON RD.CATEGORYID = CAT.CATEGORYID 
		LEFT JOIN SUBCATEGORY SC ON RD.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN TBLDEALER DEALER ON SR.SUPPLIERID = DEALER.DEALERID
		LEFT JOIN TBLUSER AU ON RD.CREATEDBY = AU.USERID
		LEFT JOIN TBLBRAND tBR ON RD.BRANDID = tBR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON RD.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIERREFUNDS_v1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SUPPLIERREFUNDS_v1]
(
	@FromDate DATE
	, @ToDate DATE
	, @Periodicity VARCHAR(20)
	, @IncludeDate BIT = 0
	, @IncludeItem BIT = 1
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeSRefundNumber Bit = 0
	, @ITEMID INT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
	, @CategoryID VARCHAR(MAX)
	, @BranchID VARCHAR(MAX)
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #REPORTDATA
	(
		ITEMCOSTPRICEID INT, 
		ITEMPRICEID INT, 
		QUANTITY DECIMAL(18, 2),
		CATEGORYID INT, 
		SUBCATEGORYID INT, 
		PERIODOCITY DATETIME, 
		GSTID INT,
		SRID INT,
		CREATEDBY INT, 
		CREATEDDATE DATETIME, 
		RETURNSTATUS INT, 
		BRANDID INT, 
		MANUFACTURERID INT
	)

	SELECT SRD.ITEMCOSTPRICEID, 
		ICP.ITEMPRICEID, 
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		I.BRANDID,
		I.MANUFACTURERID,
		SRD.QUANTITY,
		SRD.REASONID,
		SRD.BRDID,
		SRD.SUPPLIERRETURNSID,
		ISNULL(SRD.RETURNSTATUS,0) AS RETURNSTATUS,
		SR.CREATEDBY,
		SRD.CREATEDDATE
	INTO #SRD
	FROM SUPPLIERRETURNSDETAIL SRD
		INNER JOIN SUPPLIERRETURNS SR ON SR.SUPPLIERRETURNSID = SRD.SUPPLIERRETURNSID
		INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID 
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND SRD.CREATEDDATE > @FromDate
		AND SRD.CREATEDDATE < @ToDate
		AND SRD.DELETEDDATE IS NULL

	INSERT INTO #REPORTDATA(ITEMCOSTPRICEID, ITEMPRICEID, CATEGORYID, SUBCATEGORYID,
		PERIODOCITY, SRID, RETURNSTATUS, CREATEDBY, CREATEDDATE, QUANTITY, BRANDID, MANUFACTURERID)
	SELECT 
			CASE WHEN @IncludeItem = 1 THEN SRD.ITEMCOSTPRICEID ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN SRD.ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN SRD.CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SRD.SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT( SRD.CREATEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(SRD.CREATEDDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END 
			,CASE WHEN @IncludeSRefundNumber = 1 THEN SRD.SUPPLIERRETURNSID ELSE NULL END AS SRID
			,CASE WHEN @IncludeItem = 1 THEN SRD.RETURNSTATUS ELSE NULL END AS RETURNSTATUS
			,CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDBY ELSE NULL END AS CREATEDBY
			,CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDDATE ELSE NULL END AS CREATEDDATE
			,SUM(SRD.QUANTITY) AS QUANTITY
			, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	FROM #SRD SRD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN SRD.ITEMCOSTPRICEID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN SRD.CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SRD.SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(SRD.CREATEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(SRD.CREATEDDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeSRefundNumber = 1 THEN SRD.SUPPLIERRETURNSID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.RETURNSTATUS ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDBY ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN SRD.CREATEDDATE ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END

	SELECT 
		RD.PERIODOCITY, 
		CAT.CATEGORYNAME,SC.SUBCATEGORYNAME,tBR.BRANDNAME, MAN.MANUFACTURERNAME, I.SKUCODE, I.VENDORSKUCODE, I.ITEMNAME, IC.ITEMCODE, IC.HSNCODE
		, IP.MRP, RD.QUANTITY, RD.SRID AS [Supplier Returns #], SR.SUPPLIERID, DEALER.DEALERNAME AS [Supplier Name], AU.FULLNAME AS CREATEDBY, RD.CREATEDDATE
	FROM 
		#REPORTDATA RD
		LEFT JOIN SUPPLIERRETURNS SR ON RD.SRID = SR.SUPPLIERRETURNSID
		LEFT JOIN ITEMCOSTPRICE ICP ON RD.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		LEFT JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON RD.CATEGORYID = CAT.CATEGORYID 
		LEFT JOIN SUBCATEGORY SC ON RD.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN TBLDEALER DEALER ON SR.SUPPLIERID = DEALER.DEALERID
		LEFT JOIN TBLUSER AU ON RD.CREATEDBY = AU.USERID
		LEFT JOIN TBLBRAND tBR ON RD.BRANDID = tBR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON RD.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIERWISEBREFUNDS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SUPPLIERWISEBREFUNDS]
(      
 @DealerID INT = 0,
 @BranchID VARCHAR(500),
 @FromDate Date,
 @ToDate Date,
 @IncludeDate BIT = 0,
 @IncludeItem Bit = 0,
 @IncludeBranch Bit = 0,
 @IncludeCategory Bit = 0,
 @IncludeSubCategory Bit = 0,
 @IncludeReason Bit = 0,
 @IncludeRefundNumber Bit = 0
 , @IncludeBrand BIT = 0
, @IncludeManufacturer BIT = 0
)      
AS      
BEGIN      

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT 
		BD.BILLDATE,B.BRANCHNAME,I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME,tBR.BRANDNAME, MAN.MANUFACTURERNAME,
		IP.MRP,BD.QUANTITY,COSTPRICEWOT,COSTPRICEWT,COSTPRICETAX,TOTALCPWOT,TOTALCPWT,TOTALCPTAX,REASONNAME as Reason,BR.BREFUNDNUMBER
	FROM (

	SELECT CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END AS BRANCHID,
		CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END AS CATEGORYID,
		CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END AS SUBCATEGORYID,
		CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END as BRANDID, 
		CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END as MANUFACTURERID,
		CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END AS BILLDATE,
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END AS ITEMPRICEID,
		CASE WHEN @IncludeReason = 1 THEN REASONID ELSE NULL END AS REASONID,
		CASE WHEN @IncludeRefundNumber = 1 THEN BRID ELSE NULL END AS BRID,
		SUM(QUANTITY) AS QUANTITY,
		MAX(COSTPRICEWOT) AS COSTPRICEWOT,
		MAX(COSTPRICEWT) AS COSTPRICEWT,
		MAX(COSTPRICETAX) AS COSTPRICETAX,
		MAX(SALEPRICE) AS SALEPRICEWT,
		MAX(SALEPRICEWOT) AS SALEPRICEWOT,
		MAX(SALEPRICETAX) AS SALEPRICETAX,
		CAST(ROUND(SUM(QUANTITY * COSTPRICEWOT),2) AS decimal(18,2)) AS TOTALCPWOT,
		CAST(ROUND(SUM(QUANTITY * COSTPRICEWT) ,2) AS decimal(18,2)) AS TOTALCPWT,
		CAST(ROUND(SUM(QUANTITY * COSTPRICETAX) ,2) AS decimal(18,2)) AS TOTALCPTAX,
		CAST(ROUND(SUM(QUANTITY * SALEPRICE) ,2) AS decimal(18,2)) AS TOTALSPWT,
		CAST(ROUND(SUM(QUANTITY * SALEPRICEWOT) ,2) AS decimal(18,2)) AS TOTALSPWOT,
		CAST(ROUND(SUM(QUANTITY * SALEPRICETAX) ,2) AS decimal(18,2)) AS TOTALSPTAX
	FROM ( 
			SELECT IP.ITEMPRICEID,
				BR.BRANCHID,
				I.CATEGORYID, 
				I.SUBCATEGORYID, 
				I.BRANDID,
				I.MANUFACTURERID,
				CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN BRD.ACCEPTEDQUANTITY ELSE BRD.ACCEPTEDWEIGHTKGS END AS QUANTITY, 
				BRD.CREATEDDATE,
				ISNULL(IPICP.COSTPRICEWOT,0) AS COSTPRICEWOT,
				ISNULL(IPICP.COSTPRICEWT,0) AS COSTPRICEWT,
				IPICP.COSTPRICEWT - IPICP.COSTPRICEWOT AS COSTPRICETAX,
				IP.SALEPRICE,
				(IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100 AS SALEPRICEWOT,
				IP.SALEPRICE - ((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100) AS SALEPRICETAX,
				BRD.REASONID,
				BR.BRID
			FROM POS_BREFUNDDETAIL BRD
				INNER JOIN POS_BREFUND BR ON BR.BRID = BRD.BRID
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID 
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = I.ITEMID
				INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
				INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON BR.BRANCHID = BIDS.ITEM
				LEFT JOIN IPICPView IPICP ON IP.ITEMPRICEID = IPICP.ITEMPRICEID
			WHERE ISM.SUPPLIERID = @DealerID
				AND	BRD.CREATEDDATE > (@FromDate)
				AND BRD.CREATEDDATE < @ToDate
				AND BRD.DELETEDDATE IS NULL
				AND BR.IsAccepted = 1
		) AS BD
	GROUP BY CASE WHEN @IncludeBranch = 1 THEN BD.BRANCHID ELSE NULL END,
		CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END,
		CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END,
		CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END,
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END,
		CASE WHEN @IncludeReason = 1 THEN REASONID ELSE NULL END,
		CASE WHEN @IncludeRefundNumber = 1 THEN BRID ELSE NULL END, 
		CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END, 
		CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
		) AS BD
		
		LEFT JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE	IC ON IP.ITEMCODEID = IC.ITEMCODEID
		LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN TBLCATEGORY C ON BD.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON BD.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON BD.BRANCHID = B.BRANCHID
		LEFT JOIN REASONFORREFUND RR ON BD.REASONID = RR.REASONID
		LEFT JOIN POS_BREFUND BR ON BD.BRID = BR.BRID
		LEFT JOIN TBLBRAND tBR ON BD.BRANDID = tBR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON BD.MANUFACTURERID = MAN.MANUFACTURERID

	ORDER BY I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME
      
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIERWISECREFUNDS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SUPPLIERWISECREFUNDS]
(      
 @DealerID INT = 0,
 @BranchID VARCHAR(500),
 @FromDate Date,
 @ToDate Date,
 @IncludeDate BIT = 0,
 @IncludeItem Bit = 0,
 @IncludeBranch Bit = 0,
 @IncludeCategory Bit = 0,
 @IncludeSubCategory Bit = 0
 , @IncludeBrand BIT = 0
, @IncludeManufacturer BIT = 0
)      
AS      
BEGIN      

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT 
		BD.BILLDATE,B.BRANCHNAME,I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME
		,BR.BRANDNAME, MAN.MANUFACTURERNAME,
		IP.MRP,IP.SALEPRICE,BD.QUANTITY,COSTPRICEWOT,COSTPRICEWT,COSTPRICETAX,SALEPRICEWT,SALEPRICEWOT,SALEPRICETAX,TOTALCPWOT,TOTALCPWT,TOTALCPTAX,
		TOTALSPWT,TOTALSPWOT,TOTALSPTAX
	FROM (

	SELECT CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END AS BRANCHID,
		CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END AS CATEGORYID,
		CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END AS SUBCATEGORYID,
		CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END AS BILLDATE,
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END AS ITEMPRICEID, 
		CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END AS BRANDID, 
		CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END AS MANUFACTURERID,
		SUM(QUANTITY) AS QUANTITY,
		MAX(COSTPRICEWOT) AS COSTPRICEWOT,
		MAX(COSTPRICEWT) AS COSTPRICEWT,
		MAX(COSTPRICETAX) AS COSTPRICETAX,
		MAX(SALEPRICE) AS SALEPRICEWT,
		MAX(SALEPRICEWOT) AS SALEPRICEWOT,
		MAX(SALEPRICETAX) AS SALEPRICETAX,
		CAST(ROUND(SUM(QUANTITY * COSTPRICEWOT) ,2) AS DECIMAL(18,2)) AS TOTALCPWOT,
		CAST(ROUND(SUM(QUANTITY * COSTPRICEWT) ,2) AS DECIMAL(18,2)) AS TOTALCPWT,
		CAST(ROUND(SUM(QUANTITY * COSTPRICETAX) ,2) AS DECIMAL(18,2)) AS TOTALCPTAX,
		CAST(ROUND(SUM(QUANTITY * SALEPRICE) ,2) AS DECIMAL(18,2)) AS TOTALSPWT,
		CAST(ROUND(SUM(QUANTITY * SALEPRICEWOT) ,2) AS DECIMAL(18,2)) AS TOTALSPWOT,
		CAST(ROUND(SUM(QUANTITY * SALEPRICETAX) ,2) AS DECIMAL(18,2)) AS TOTALSPTAX
	FROM 
	( 
		SELECT IP.ITEMPRICEID,
			BC.BRANCHID,
			I.CATEGORYID, 
			I.SUBCATEGORYID, 
			I.BRANDID,
			I.MANUFACTURERID,
			CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS QUANTITY, 
			CR.CREATEDDATE,
			ISNULL(IPICP.COSTPRICEWOT,0) AS COSTPRICEWOT,
			ISNULL(IPICP.COSTPRICEWT,0) AS COSTPRICEWT,
			IPICP.COSTPRICEWT - IPICP.COSTPRICEWOT AS COSTPRICETAX,
			IP.SALEPRICE,
			(IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100 AS SALEPRICEWOT,
			IP.SALEPRICE - ((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100) AS SALEPRICETAX
		FROM POS_CREFUND CR
			INNER JOIN POS_BILLDETAIL BD ON CR.BILLDETAILID = BD.BILLDETAILID AND CR.COUNTERID = BD.BRANCHCOUNTERID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BD.ITEMPRICEID 
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = I.ITEMID
			INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
			INNER JOIN BRANCHCOUNTER BC ON BD.BRANCHCOUNTERID = BC.COUNTERID
			INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON BC.BRANCHID = BIDS.ITEM
			LEFT JOIN IPICPView IPICP ON IP.ITEMPRICEID = IPICP.ITEMPRICEID
		WHERE CR.CREATEDDATE > @FromDate
			AND CR.CREATEDDATE < @ToDate
			AND ISM.SUPPLIERID = @DealerID
	) AS BD
	GROUP BY CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END,
		CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END,
		CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END,
		CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END,
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END,
		CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END, 
		CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END) AS BD
		
		LEFT JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE	IC ON IP.ITEMCODEID = IC.ITEMCODEID
		LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN TBLCATEGORY C ON BD.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON BD.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON BD.BRANCHID = B.BRANCHID
		LEFT JOIN TBLBRAND BR ON BD.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON BD.MANUFACTURERID = MAN.MANUFACTURERID

	ORDER BY I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME
      
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIERWISEDISPATCHES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SUPPLIERWISEDISPATCHES]
(      
 @DealerID INT = 0,
 @BranchID VARCHAR(500),
 @FromDate Date,
 @ToDate Date,
 @IncludeDate BIT = 0,
 @IncludeItem Bit = 0,
 @IncludeBranch Bit = 0,
 @IncludeCategory Bit = 0,
 @IncludeSubCategory Bit = 0
 , @IncludeBrand BIT = 0
 , @IncludeManufacturer BIT = 0
)      
AS      
BEGIN      

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT 
		BD.BILLDATE,B.BRANCHNAME,I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME,
		IP.MRP,IP.SALEPRICE,BD.QUANTITY,COSTPRICEWOT,COSTPRICEWT,COSTPRICETAX,SALEPRICEWT,SALEPRICEWOT,SALEPRICETAX,TOTALCPWOT,TOTALCPWT,TOTALCPTAX,
		TOTALSPWT,TOTALSPWOT,TOTALSPTAX
	FROM 
	(

		SELECT CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END AS BRANCHID,
			CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END AS CATEGORYID,
			CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END AS SUBCATEGORYID,
			CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END AS BRANDID, 
			CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END AS MANUFACTURERID,
			CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END AS BILLDATE,
			CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END AS ITEMPRICEID,
			SUM(QUANTITY) AS QUANTITY,
			MAX(COSTPRICEWOT) AS COSTPRICEWOT,
			MAX(COSTPRICEWT) AS COSTPRICEWT,
			MAX(COSTPRICETAX) AS COSTPRICETAX,
			MAX(SALEPRICE) AS SALEPRICEWT,
			MAX(SALEPRICEWOT) AS SALEPRICEWOT,
			MAX(SALEPRICETAX) AS SALEPRICETAX,
			CAST(ROUND(SUM(QUANTITY * COSTPRICEWOT),2) AS decimal(18,2)) AS TOTALCPWOT,
			CAST(ROUND(SUM(QUANTITY * COSTPRICEWT),2)  AS decimal(18,2)) AS TOTALCPWT,
			CAST(ROUND(SUM(QUANTITY * COSTPRICETAX),2)  AS decimal(18,2)) AS TOTALCPTAX,
			CAST(ROUND(SUM(QUANTITY * SALEPRICE),2)  AS decimal(18,2)) AS TOTALSPWT,
			CAST(ROUND(SUM(QUANTITY * SALEPRICEWOT),2)  AS decimal(18,2)) AS TOTALSPWOT,
			CAST(ROUND(SUM(QUANTITY * SALEPRICETAX),2)  AS decimal(18,2)) AS TOTALSPTAX
		FROM ( 
					SELECT 
					IP.ITEMPRICEID,
					SD.TOBRANCHID AS BRANCHID,
					I.CATEGORYID, 
					I.SUBCATEGORYID, 
					I.BRANDID,
					I.MANUFACTURERID,
					CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN SDD.DISPATCHQUANTITY ELSE SDD.WEIGHTINKGS END AS QUANTITY, 
					SD.CREATEDDATE,
					ISNULL(IPICP.COSTPRICEWOT,0) AS COSTPRICEWOT,
					ISNULL(IPICP.COSTPRICEWT,0) AS COSTPRICEWT,
					IPICP.COSTPRICEWT - IPICP.COSTPRICEWOT AS COSTPRICETAX,
					IP.SALEPRICE,
					(IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100 AS SALEPRICEWOT,
					IP.SALEPRICE - ((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100) AS SALEPRICETAX
				FROM STOCKDISPATCHDETAIL SDD
					INNER JOIN STOCKDISPATCH SD ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID 
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
					INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = I.ITEMID
					INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
					INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON SD.TOBRANCHID = BIDS.ITEM
					LEFT JOIN IPICPView IPICP ON IP.ITEMPRICEID = IPICP.ITEMPRICEID
				WHERE ISM.SUPPLIERID = @DealerID
					AND	SD.CREATEDDATE > (@FromDate)
					AND SD.CREATEDDATE < @ToDate
					AND SDD.DELETEDDATE IS NULL
					AND SD.STATUS <> 0
			) AS BD
		GROUP BY CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END,
			CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END,
			CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END,
			CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END,
			CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	) AS BD
		
		LEFT JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE	IC ON IP.ITEMCODEID = IC.ITEMCODEID
		LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN TBLCATEGORY C ON BD.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON BD.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON BD.BRANCHID = B.BRANCHID
		LEFT JOIN TBLBRAND BR ON BD.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON BD.MANUFACTURERID = MAN.MANUFACTURERID

	ORDER BY I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME
      
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_SUPPLIERWISESALES]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_SUPPLIERWISESALES]      
(      
 @DealerID INT = 0,
 @BranchID VARCHAR(500),
 @FromDate Date,
 @ToDate Date,
 @IncludeDate BIT = 0,
 @IncludeItem Bit = 0,
 @IncludeBranch Bit = 0,
 @IncludeCategory Bit = 0,
 @IncludeSubCategory Bit = 0
 , @IncludeBrand BIT = 0
, @IncludeManufacturer BIT = 0
)      
AS      
BEGIN      

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT *
	INTO #BD
	FROM
	(
		SELECT IP.ITEMPRICEID, 
			BC.BRANCHID, 
			I.CATEGORYID, 
			I.SUBCATEGORYID, 
			I.BRANDID,
			I.MANUFACTURERID,
			PBD.BILLEDAMOUNT, 
			PBD.GSTVALUE, 
			CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END AS QUANTITY, 
			PBD.CREATEDDATE
		FROM POS_BILLDETAIL PBD 
			INNER JOIN POS_BILL PB ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = I.ITEMID
			INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON BC.BRANCHID = BIDS.ITEM
		WHERE ISM.SUPPLIERID = @DealerID
			AND	PBD.CREATEDDATE > (@FromDate)
			AND PBD.CREATEDDATE < @ToDate
			AND PBD.DELETEDDATE IS NULL		
			AND PB.BILLSTATUS = 1

		UNION ALL

		SELECT IP.ITEMPRICEID
			, BC.BRANCHID
			, I.CATEGORYID
			, I.SUBCATEGORYID
			, I.BRANDID
			, I.MANUFACTURERID
			, - CAST((PBD.BILLEDAMOUNT / (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END)) AS DECIMAL(14, 2)) 
				* CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END
			, - CAST((PBD.GSTVALUE / (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END)) AS DECIMAL(14, 2))
				* CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END
			, - CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN CR.REFUNDQUANTITY ELSE CR.REFUNDWEIGHTINKGS END AS QUANTITY
			, CR.CREATEDDATE

		FROM POS_CREFUND CR 
			INNER JOIN POS_BILLDETAIL PBD ON CR.BILLDETAILID = PBD.BILLDETAILID AND CR.COUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN ITEMPRICE IP ON PBD.ITEMPRICEID = IP.ITEMPRICEID 
			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			INNER JOIN ITEMSUPPLIERMAP ISM ON ISM.ITEMID = I.ITEMID
			INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = PBD.BRANCHCOUNTERID
			INNER JOIN dbo.SplitString(@BranchID,',') BIDS ON BC.BRANCHID = BIDS.ITEM
		WHERE ISM.SUPPLIERID = @DealerID
			AND	CR.CREATEDDATE > (@FromDate)
			AND CR.CREATEDDATE < @ToDate
			AND (CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END) > 0.00 
	) BD

	SELECT BD.BILLDATE,B.BRANCHNAME,I.SKUCODE,IC.ITEMCODE,I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME,BR.BRANDNAME, MAN.MANUFACTURERNAME,
	IP.MRP,IP.SALEPRICE AS SALEPRICEWT,BD.QUANTITY,BD.BILLEDAMOUNT FROM 
	(
		SELECT CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END AS BRANCHID,
			CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END AS CATEGORYID,
			CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END AS SUBCATEGORYID,
			CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END AS BILLDATE,
			CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END AS ITEMPRICEID,
			CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END AS BRANDID,
			CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END AS MANUFACTURERID,
				SUM(QUANTITY) AS QUANTITY, 
				SUM(BILLEDAMOUNT) AS BILLEDAMOUNT,
				SUM(GSTVALUE) AS TAXVALUE
		FROM #BD BD
		GROUP BY CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END,
			CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END,
			CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END,
			CASE WHEN @IncludeDate = 1 THEN CAST(CREATEDDATE AS DATE) ELSE NULL END,
			CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END,
			CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END,
			CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
	) AS BD
		
		LEFT JOIN ITEMPRICE IP ON BD.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE	IC ON IP.ITEMCODEID = IC.ITEMCODEID
		LEFT JOIN ITEM I ON IC.ITEMID = I.ITEMID
		LEFT JOIN TBLCATEGORY C ON BD.CATEGORYID = C.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON BD.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B ON BD.BRANCHID = B.BRANCHID
		LEFT JOIN TBLBRAND BR ON BD.BRANDID = BR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON BD.MANUFACTURERID = MAN.MANUFACTURERID

	ORDER BY I.ITEMNAME,C.CATEGORYNAME,SC.SUBCATEGORYNAME
      
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_TAXBREAKUP_DAYWISE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
