CREATE   PROC [dbo].[USP_RPT_TAXBREAKUP_DAYWISE]
(
	@FromDate DATE
	, @ToDate DATE
)
AS 
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	CREATE TABLE #TAXBREAKUP
	(
		DAYSEQ DATE
		, BRANCHID INT
		, TOTALBILLEDAMOUNTWT DECIMAL(18, 2)
		, TOTALBILLEDAMOUNTWOT DECIMAL(18, 2)
		, GST0AMOUNT DECIMAL(18, 2)
		, GST0AMOUNTCGST DECIMAL(18, 2)
		, GST0AMOUNTSGST DECIMAL(18, 2)
		, GST0AMOUNTCESS DECIMAL(18, 2)
		, GST0AMOUNTTAX DECIMAL(18, 2)
		, GST3AMOUNT DECIMAL(18, 2)
		, GST3AMOUNTCGST DECIMAL(18, 2)
		, GST3AMOUNTSGST DECIMAL(18, 2)
		, GST3AMOUNTCESS DECIMAL(18, 2)
		, GST3AMOUNTTAX DECIMAL(18, 2)
		, GST5AMOUNT DECIMAL(18, 2)
		, GST5AMOUNTCGST DECIMAL(18, 2)
		, GST5AMOUNTSGST DECIMAL(18, 2)
		, GST5AMOUNTCESS DECIMAL(18, 2)
		, GST5AMOUNTTAX DECIMAL(18, 2)
		, GST12AMOUNT DECIMAL(18, 2)
		, GST12AMOUNTCGST DECIMAL(18, 2)
		, GST12AMOUNTSGST DECIMAL(18, 2)
		, GST12AMOUNTCESS DECIMAL(18, 2)
		, GST12AMOUNTTAX DECIMAL(18, 2)
		, GST18AMOUNT DECIMAL(18, 2)
		, GST18AMOUNTCGST DECIMAL(18, 2)
		, GST18AMOUNTSGST DECIMAL(18, 2)
		, GST18AMOUNTCESS DECIMAL(18, 2)
		, GST18AMOUNTTAX DECIMAL(18, 2)
		, GST28AMOUNT DECIMAL(18, 2)
		, GST28AMOUNTCGST DECIMAL(18, 2)
		, GST28AMOUNTSGST DECIMAL(18, 2)
		, GST28AMOUNTCESS DECIMAL(18, 2)
		, GST28AMOUNTTAX DECIMAL(18, 2)
		, GST33AMOUNT DECIMAL(18, 2)
		, GST33AMOUNTCGST DECIMAL(18, 2)
		, GST33AMOUNTSGST DECIMAL(18, 2)
		, GST33AMOUNTCESS DECIMAL(18, 2)
		, GST33AMOUNTTAX DECIMAL(18, 2)
		, GST28G12CAMOUNT DECIMAL(18, 2)
		, GST28G12CAMOUNTCGST DECIMAL(18, 2)
		, GST28G12CAMOUNTSGST DECIMAL(18, 2)
		, GST28G12CAMOUNTCESS DECIMAL(18, 2)
		, GST28G12CAMOUNTTAX DECIMAL(18, 2)
		, GST40AMOUNT DECIMAL(18, 2)
		, GST40AMOUNTCGST DECIMAL(18, 2)
		, GST40AMOUNTSGST DECIMAL(18, 2)
		, GST40AMOUNTCESS DECIMAL(18, 2)
		, GST40AMOUNTTAX DECIMAL(18, 2)
		, GST64AMOUNT DECIMAL(18, 2)
		, GST64AMOUNTCGST DECIMAL(18, 2)
		, GST64AMOUNTSGST DECIMAL(18, 2)
		, GST64AMOUNTCESS DECIMAL(18, 2)
		, GST64AMOUNTTAX DECIMAL(18, 2)
		, TOTALTAX DECIMAL(18, 2)
	)


	INSERT INTO #TAXBREAKUP(DAYSEQ, BRANCHID)
	SELECT DISTINCT(CONVERT(DATE, CLOSUREDATE)) DAYSEQ, BRANCHID
	FROM 
		POS_DAYCLOSURE 
		CROSS APPLY BRANCH
	WHERE CLOSUREDATE > @FromDate AND CLOSUREDATE < @ToDate AND BRANCHID NOT IN (92)



	UPDATE TBMAIN
	SET 
		  GST0AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
		, GST0AMOUNTCGST = 0.00
		, GST0AMOUNTSGST = 0.00
		, GST0AMOUNTCESS = 0.00
		, GST0AMOUNTTAX = 0.00
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN 
			(
				SELECT SUM(PBD.BILLEDAMOUNT) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB	WITH(NOLOCK)				
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID					
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 0 %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 0 %'	AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate			
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID
		
	UPDATE TBMAIN
	SET 
		  GST3AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 103) * 100
		, GST3AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 103) * 100) * 1.5 / 100
		, GST3AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 103) * 100) * 1.5 / 100
		, GST3AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 103) * 100) * 0 / 100
		, GST3AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 103) * 100) * 3 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB WITH(NOLOCK)					
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST ON GST.GSTID = PBD.GSTID					
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 3 %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 3 %'	AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate				
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID
		
	UPDATE TBMAIN
	SET 
		  GST5AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 105) * 100
		, GST5AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 105) * 100) * 2.5 / 100
		, GST5AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 105) * 100) * 2.5 / 100
		, GST5AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 105) * 100) * 0 / 100
		, GST5AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 105) * 100) * 5 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB	WITH(NOLOCK)				
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID					
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 5 %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 5 %'		AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate			
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID
				
	UPDATE TBMAIN
	SET 
		  GST12AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 112) * 100
		, GST12AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 112) * 100) * 6 / 100
		, GST12AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 112) * 100) * 6 / 100
		, GST12AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 112) * 100) * 0 / 100
		, GST12AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 112) * 100) * 12 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB	WITH(NOLOCK)				
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID					
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 12 %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 12 %'	AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate				
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID
		

	UPDATE TBMAIN
	SET 
		  GST18AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 118) * 100
		, GST18AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 118) * 100) * 9 / 100
		, GST18AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 118) * 100) * 9 / 100
		, GST18AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 118) * 100) * 0 / 100
		, GST18AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 118) * 100) * 18 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB WITH(NOLOCK)					
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 18 %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 18 %'	AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate				
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID
		
	UPDATE TBMAIN
	SET 
		  GST28AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 128) * 100
		, GST28AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 128) * 100) * 14 / 100
		, GST28AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 128) * 100) * 14 / 100
		, GST28AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 128) * 100) * 0 / 100
		, GST28AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 128) * 100) * 28 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB WITH(NOLOCK)					
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 %'	AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate				
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID


	UPDATE TBMAIN
	SET 
		  GST33AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 133) * 100
		, GST33AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 133) * 100) * 14 / 100
		, GST33AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 133) * 100) * 14 / 100
		, GST33AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 133) * 100) * 5 / 100
		, GST33AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 133) * 100) * 33 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB	WITH(NOLOCK)				
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 + 5C %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 + 5C %'	AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate				
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID

	UPDATE TBMAIN
	SET 
		  GST28G12CAMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100
		, GST28G12CAMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 14 / 100
		, GST28G12CAMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 14 / 100
		, GST28G12CAMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 12 / 100
		, GST28G12CAMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 40 / 100
	FROM
		#TAXBREAKUP TBMAIN
