					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID					
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 + 12C %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK) 
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 + 12C %'		AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate			
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID

	UPDATE TBMAIN
	SET 
		  GST40AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100
		, GST40AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 14 / 100
		, GST40AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 14 / 100
		, GST40AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 12 / 100
		, GST40AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 140) * 100) * 40 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB WITH(NOLOCK)
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID					
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 40 %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK)
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 40 %'		AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate			
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID


	UPDATE TBMAIN
	SET 
		  GST64AMOUNT = ((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 164) * 100
		, GST64AMOUNTCGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 164) * 100) * 14 / 100
		, GST64AMOUNTSGST = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 164) * 100) * 14 / 100
		, GST64AMOUNTCESS = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 164) * 100) * 36 / 100
		, GST64AMOUNTTAX = (((BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0)) / 164) * 100) * 64 / 100
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB	WITH(NOLOCK)				
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 + 36C %' AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_CREFUND CREFINNER WITH(NOLOCK)
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND GST.GSTCODE = 'GST 28 + 36C %'		AND CREFINNER.CREATEDDATE >= @FromDate AND CREFINNER.CREATEDDATE < @ToDate			
				GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID
			) CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID



	UPDATE TBMAIN
	SET 
		  TOTALBILLEDAMOUNTWOT = BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0) - 
				((ISNULL(GST0AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST5AMOUNTTAX, 0) + ISNULL(GST12AMOUNTTAX, 0) 
				+ ISNULL(GST18AMOUNTTAX, 0) + ISNULL(GST28AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST28G12CAMOUNTTAX, 0)
				+ ISNULL(GST40AMOUNTTAX, 0)+ ISNULL(GST64AMOUNTTAX, 0)))
		  , TOTALBILLEDAMOUNTWT = BILLEDAMOUNT - ISNULL(REFUNDAMOUNT, 0) 
		  , TOTALTAX = 
				(ISNULL(GST0AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST5AMOUNTTAX, 0) + ISNULL(GST12AMOUNTTAX, 0) 
				+ ISNULL(GST18AMOUNTTAX, 0) + ISNULL(GST28AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST28G12CAMOUNTTAX, 0)
				+ ISNULL(GST40AMOUNTTAX, 0) + ISNULL(GST64AMOUNTTAX, 0))
	FROM
		#TAXBREAKUP TBMAIN
		INNER JOIN
			(
				SELECT ISNULL(SUM(PBD.BILLEDAMOUNT), 0) AS BILLEDAMOUNT, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ
				FROM
					POS_BILL PB WITH(NOLOCK)					
					INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
					INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID		
					INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
				WHERE
					PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
					AND PBD.CREATEDDATE >= @FromDate AND PBD.CREATEDDATE < @ToDate
				GROUP BY CAST(PBD.CREATEDDATE AS DATE), BC.BRANCHID
			) CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		LEFT JOIN
			(
				SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
				FROM
