		, GST64AMOUNTCESS DECIMAL(18, 2)
		, GST64AMOUNTTAX DECIMAL(18, 2)
		, TOTALTAX DECIMAL(18, 2)
	)


	INSERT INTO #TAXBREAKUP(DAYSEQ, BRANCHID)
	SELECT DISTINCT(CONVERT(DATE, CLOSUREDATE)) DAYSEQ, BRANCHID
	FROM 
		POS_DAYCLOSURE WITH(NOLOCK)
		CROSS APPLY BRANCH WITH(NOLOCK)
	WHERE CLOSUREDATE > @FromDate AND CLOSUREDATE < @ToDate AND BRANCHID NOT IN (92)

	DECLARE @CurDate DATE

	SELECT @CurDate = @FromDate

	CREATE TABLE #BILLDETAILFULL(BILLEDAMOUNT DECIMAL(18, 2), GSTID INT, BRANCHID INT, DAYSEQ DATE, 
		CGST DECIMAL(18, 2), SGST  DECIMAL(18, 2), IGST  DECIMAL(18, 2), CESS  DECIMAL(18, 2))

	CREATE TABLE #BILLDETAILDAYWISE(BILLEDAMOUNT DECIMAL(18, 2), GSTID INT, BRANCHID INT, DAYSEQ DATE, 
		CGST DECIMAL(18, 2), SGST  DECIMAL(18, 2), IGST  DECIMAL(18, 2), CESS  DECIMAL(18, 2))

	CREATE TABLE #REFUNDDAYWISE(REFUNDAMOUNT DECIMAL(18, 2), GSTID INT, BRANCHID INT, DAYSEQ DATE, 
		CGST DECIMAL(18, 2), SGST  DECIMAL(18, 2), IGST  DECIMAL(18, 2), CESS  DECIMAL(18, 2))

	WHILE @CurDate < @ToDate
	BEGIN

		DELETE FROM #BILLDETAILFULL

		INSERT INTO #BILLDETAILFULL
		SELECT PBD.BILLEDAMOUNT, PBD.GSTID, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ, PBD.CGST, PBD.SGST, ISNULL(PBD.IGST, 0) IGST, PBD.CESS
		FROM
			POS_BILL PB	WITH(NOLOCK)				
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
			INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID	
			INNER JOIN #TAXBREAKUP TB ON TB.BRANCHID = BC.BRANCHID AND TB.DAYSEQ = CAST(PBD.CREATEDDATE AS DATE)
		WHERE
			PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
			AND CAST(PBD.CREATEDDATE AS DATE) = @CurDate
			
		INSERT INTO #BILLDETAILDAYWISE
		SELECT SUM(BILLEDAMOUNT) AS BILLEDAMOUNT, GSTID, BRANCHID, DAYSEQ, SUM(CGST) CGST, SUM(SGST) SGST, SUM(IGST) IGST, SUM(CESS) CESS
		FROM #BILLDETAILFULL	
		GROUP BY DAYSEQ, BRANCHID, GSTID

		INSERT INTO #REFUNDDAYWISE
		SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, PBD.GSTID, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
			, SUM(ISNULL(CASE WHEN PB.ISIGSTBILL = 1 THEN 0 ELSE CREFINNER.REFUNDAMOUNT * GST.CGST / 100 END, 0)) AS CGST
			, SUM(ISNULL(CASE WHEN PB.ISIGSTBILL = 1 THEN 0 ELSE CREFINNER.REFUNDAMOUNT * GST.SGST / 100 END, 0)) AS SGST
			, SUM(ISNULL(CASE WHEN PB.ISIGSTBILL = 0 THEN 0 ELSE CREFINNER.REFUNDAMOUNT * GST.IGST / 100 END, 0)) AS IGST
			, SUM(ISNULL(CREFINNER.REFUNDAMOUNT * GST.CESS / 100, 0)) AS CESS		
		FROM
			POS_CREFUND CREFINNER WITH(NOLOCK) 
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
			INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
			INNER JOIN POS_BILL PB	WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID	
			INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
			INNER JOIN #TAXBREAKUP TB ON TB.BRANCHID = BC.BRANCHID AND TB.DAYSEQ = CAST(CREFINNER.CREATEDDATE AS DATE)
		WHERE
			CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL 
			AND CAST(CREFINNER.CREATEDDATE AS DATE) = @CurDate		
		GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID, PBD.GSTID
			
		SELECT @CurDate = DATEADD(d, 1, @CurDate)

	END
		
	UPDATE TBMAIN
	SET 
		  GST0AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
		, GST0AMOUNTCGST = 0.00
		, GST0AMOUNTSGST = 0.00
		, GST0AMOUNTIGST = 0.00
		, GST0AMOUNTCESS = 0.00
		, GST0AMOUNTTAX = 0.00
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 0 %'

	UPDATE TBMAIN
	SET 
		  GST3AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0) 
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST3AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST3AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST3AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST3AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST3AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 3 %'

	UPDATE TBMAIN
	SET 
		  GST5AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST5AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST5AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST5AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST5AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST5AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 5 %'

	UPDATE TBMAIN
	SET 
		  GST12AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST12AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST12AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST12AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST12AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST12AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 12 %'

	UPDATE TBMAIN
	SET 
		  GST18AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST18AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST18AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST18AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST18AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST18AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 18 %'

	UPDATE TBMAIN
	SET 
		  GST28AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST28AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST28AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST28AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST28AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST28AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 %'

	UPDATE TBMAIN
	SET 
		  GST33AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST33AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST33AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST33AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST33AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST33AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 + 5C %'

	UPDATE TBMAIN
	SET 
		  GST28G12CAMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST28G12CAMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST28G12CAMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST28G12CAMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST28G12CAMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST28G12CAMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 + 12C %'

	UPDATE TBMAIN
	SET 
		  GST40AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST40AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST40AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST40AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST40AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST40AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 40 %'

	UPDATE TBMAIN
	SET 
		  GST64AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST64AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST64AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST64AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST64AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST64AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 + 36C %'

	UPDATE TBMAIN
	SET 
		  TOTALBILLEDAMOUNTWOT = ISNULL(GST0AMOUNT, 0) + ISNULL(GST33AMOUNT, 0) + ISNULL(GST5AMOUNT, 0) + ISNULL(GST12AMOUNT, 0) 
				+ ISNULL(GST18AMOUNT, 0) + ISNULL(GST28AMOUNT, 0) + ISNULL(GST33AMOUNT, 0) + ISNULL(GST28G12CAMOUNT, 0)
				+ ISNULL(GST40AMOUNT, 0)+ ISNULL(GST64AMOUNT, 0)		  
		  , TOTALTAX = 
				ISNULL(GST0AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST5AMOUNTTAX, 0) + ISNULL(GST12AMOUNTTAX, 0) 
				+ ISNULL(GST18AMOUNTTAX, 0) + ISNULL(GST28AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST28G12CAMOUNTTAX, 0)
				+ ISNULL(GST40AMOUNTTAX, 0) + ISNULL(GST64AMOUNTTAX, 0)
	FROM
		#TAXBREAKUP TBMAIN

	UPDATE TBMAIN
	SET TOTALBILLEDAMOUNTWT = TOTALBILLEDAMOUNTWOT + TOTALTAX
	FROM #TAXBREAKUP TBMAIN
			


	SELECT DAYSEQ, B.BRANCHNAME
	, ISNULL(GST0AMOUNT, 0)  AS 'GST 0% AMT'
	, ISNULL(GST0AMOUNTCGST, 0) 'GST 0% CGST' 
	, ISNULL(GST0AMOUNTSGST, 0) 'GST 0% SGST' 
	, ISNULL(GST0AMOUNTIGST, 0) 'GST 0% IGST' 
	, ISNULL(GST0AMOUNTCESS, 0) 'GST 0% CESS' 
	, ISNULL(GST0AMOUNTTAX , 0) 'GST 0% TAX' 
	, ISNULL(GST3AMOUNT , 0)	 'GST 3% AMT'
