	, ISNULL(GST40AMOUNTCESS , 0)  'GST 40% CESS' 
	, ISNULL(GST40AMOUNTTAX , 0)   'GST 40% TAX' 
	, ISNULL(GST64AMOUNT , 0)		 'GST 64% AMT'
	, ISNULL(GST64AMOUNTCGST , 0)	 'GST 64% CGST' 
	, ISNULL(GST64AMOUNTSGST , 0)	 'GST 64% SGST' 
	, ISNULL(GST64AMOUNTIGST , 0)	 'GST 64% IGST' 
	, ISNULL(GST64AMOUNTCESS , 0)	 'GST 64% CESS' 
	, ISNULL(GST64AMOUNTTAX , 0)	 'GST 64% TAX' 
	, TOTALBILLEDAMOUNTWOT
	, TOTALTAX 
	, TOTALBILLEDAMOUNTWT
	FROM 
		#TAXBREAKUP TB
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = TB.BRANCHID
	ORDER BY 2 , 1


	DROP TABLE #TAXBREAKUP

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_TAXBREAKUP_DAYWISE_V3]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create     PROC [dbo].[USP_RPT_TAXBREAKUP_DAYWISE_V3]
(
	@FromDate DATE
	, @ToDate DATE
)
AS 
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	CREATE TABLE #TAXBREAKUP
	(
		DAYSEQ DATE
		, BRANCHID INT
		, TOTALBILLEDAMOUNTWT DECIMAL(18, 2)
		, TOTALBILLEDAMOUNTWOT DECIMAL(18, 2)
		, GST0AMOUNT DECIMAL(18, 2)
		, GST0AMOUNTCGST DECIMAL(18, 2)
		, GST0AMOUNTSGST DECIMAL(18, 2)
		, GST0AMOUNTIGST DECIMAL(18, 2)
		, GST0AMOUNTCESS DECIMAL(18, 2)
		, GST0AMOUNTTAX DECIMAL(18, 2)
		, GST3AMOUNT DECIMAL(18, 2)
		, GST3AMOUNTCGST DECIMAL(18, 2)
		, GST3AMOUNTSGST DECIMAL(18, 2)
		, GST3AMOUNTIGST DECIMAL(18, 2)
		, GST3AMOUNTCESS DECIMAL(18, 2)
		, GST3AMOUNTTAX DECIMAL(18, 2)
		, GST5AMOUNT DECIMAL(18, 2)
		, GST5AMOUNTCGST DECIMAL(18, 2)
		, GST5AMOUNTSGST DECIMAL(18, 2)
		, GST5AMOUNTIGST DECIMAL(18, 2)
		, GST5AMOUNTCESS DECIMAL(18, 2)
		, GST5AMOUNTTAX DECIMAL(18, 2)
		, GST12AMOUNT DECIMAL(18, 2)
		, GST12AMOUNTCGST DECIMAL(18, 2)
		, GST12AMOUNTSGST DECIMAL(18, 2)
		, GST12AMOUNTIGST DECIMAL(18, 2)
		, GST12AMOUNTCESS DECIMAL(18, 2)
		, GST12AMOUNTTAX DECIMAL(18, 2)
		, GST18AMOUNT DECIMAL(18, 2)
		, GST18AMOUNTCGST DECIMAL(18, 2)
		, GST18AMOUNTSGST DECIMAL(18, 2)
		, GST18AMOUNTIGST DECIMAL(18, 2)
		, GST18AMOUNTCESS DECIMAL(18, 2)
		, GST18AMOUNTTAX DECIMAL(18, 2)
		, GST28AMOUNT DECIMAL(18, 2)
		, GST28AMOUNTCGST DECIMAL(18, 2)
		, GST28AMOUNTSGST DECIMAL(18, 2)
		, GST28AMOUNTIGST DECIMAL(18, 2)
		, GST28AMOUNTCESS DECIMAL(18, 2)
		, GST28AMOUNTTAX DECIMAL(18, 2)
		, GST33AMOUNT DECIMAL(18, 2)
		, GST33AMOUNTCGST DECIMAL(18, 2)
		, GST33AMOUNTSGST DECIMAL(18, 2)
		, GST33AMOUNTIGST DECIMAL(18, 2)
		, GST33AMOUNTCESS DECIMAL(18, 2)
		, GST33AMOUNTTAX DECIMAL(18, 2)
		, GST28G12CAMOUNT DECIMAL(18, 2)
		, GST28G12CAMOUNTCGST DECIMAL(18, 2)
		, GST28G12CAMOUNTSGST DECIMAL(18, 2)
		, GST28G12CAMOUNTIGST DECIMAL(18, 2)
		, GST28G12CAMOUNTCESS DECIMAL(18, 2)
		, GST28G12CAMOUNTTAX DECIMAL(18, 2)
		, GST40AMOUNT DECIMAL(18, 2)
		, GST40AMOUNTCGST DECIMAL(18, 2)
		, GST40AMOUNTSGST DECIMAL(18, 2)
		, GST40AMOUNTIGST DECIMAL(18, 2)
		, GST40AMOUNTCESS DECIMAL(18, 2)
		, GST40AMOUNTTAX DECIMAL(18, 2)
		, GST64AMOUNT DECIMAL(18, 2)
		, GST64AMOUNTCGST DECIMAL(18, 2)
		, GST64AMOUNTSGST DECIMAL(18, 2)
		, GST64AMOUNTIGST DECIMAL(18, 2)
		, GST64AMOUNTCESS DECIMAL(18, 2)
		, GST64AMOUNTTAX DECIMAL(18, 2)
		, TOTALTAX DECIMAL(18, 2)
	)


	INSERT INTO #TAXBREAKUP(DAYSEQ, BRANCHID)
	SELECT DISTINCT(CONVERT(DATE, CLOSUREDATE)) DAYSEQ, BRANCHID
	FROM 
		POS_DAYCLOSURE WITH(NOLOCK)
		CROSS APPLY BRANCH WITH(NOLOCK)
	WHERE CLOSUREDATE > @FromDate AND CLOSUREDATE < @ToDate AND BRANCHID NOT IN (92)

	DECLARE @CurDate DATE

	SELECT @CurDate = @FromDate

	CREATE TABLE #BILLDETAILFULL(BILLEDAMOUNT DECIMAL(18, 2), GSTID INT, BRANCHID INT, DAYSEQ DATE, 
		CGST DECIMAL(18, 2), SGST  DECIMAL(18, 2), IGST  DECIMAL(18, 2), CESS  DECIMAL(18, 2))

	CREATE TABLE #BILLDETAILDAYWISE(BILLEDAMOUNT DECIMAL(18, 2), GSTID INT, BRANCHID INT, DAYSEQ DATE, 
		CGST DECIMAL(18, 2), SGST  DECIMAL(18, 2), IGST  DECIMAL(18, 2), CESS  DECIMAL(18, 2))

	CREATE TABLE #REFUNDDAYWISE(REFUNDAMOUNT DECIMAL(18, 2), GSTID INT, BRANCHID INT, DAYSEQ DATE, 
		CGST DECIMAL(18, 2), SGST  DECIMAL(18, 2), IGST  DECIMAL(18, 2), CESS  DECIMAL(18, 2))

	WHILE @CurDate < @ToDate
	BEGIN

		DELETE FROM #BILLDETAILFULL

		INSERT INTO #BILLDETAILFULL
		SELECT PBD.BILLEDAMOUNT, PBD.GSTID, BC.BRANCHID, CAST(PBD.CREATEDDATE AS DATE) DAYSEQ, PBD.CGST, PBD.SGST, ISNULL(PBD.IGST, 0) IGST, PBD.CESS
		FROM
			POS_BILL PB	WITH(NOLOCK)				
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PB.BRANCHCOUNTERID 					
			INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID	
			INNER JOIN #TAXBREAKUP TB ON TB.BRANCHID = BC.BRANCHID AND TB.DAYSEQ = CAST(PBD.CREATEDDATE AS DATE)
		WHERE
			PB.BILLSTATUS = 1 AND PB.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL
			AND CAST(PBD.CREATEDDATE AS DATE) = @CurDate
			
		INSERT INTO #BILLDETAILDAYWISE
		SELECT SUM(BILLEDAMOUNT) AS BILLEDAMOUNT, GSTID, BRANCHID, DAYSEQ, SUM(CGST) CGST, SUM(SGST) SGST, SUM(IGST) IGST, SUM(CESS) CESS
		FROM #BILLDETAILFULL	
		GROUP BY DAYSEQ, BRANCHID, GSTID

		INSERT INTO #REFUNDDAYWISE
		SELECT SUM(CREFINNER.REFUNDAMOUNT) AS REFUNDAMOUNT, PBD.GSTID, BC.BRANCHID, CAST(CREFINNER.CREATEDDATE AS DATE) DAYSEQ
			, SUM(ISNULL(CASE WHEN PB.ISIGSTBILL = 1 THEN 0 ELSE CREFINNER.REFUNDAMOUNT * GST.CGST / 100 END, 0)) AS CGST
			, SUM(ISNULL(CASE WHEN PB.ISIGSTBILL = 1 THEN 0 ELSE CREFINNER.REFUNDAMOUNT * GST.SGST / 100 END, 0)) AS SGST
			, SUM(ISNULL(CASE WHEN PB.ISIGSTBILL = 0 THEN 0 ELSE CREFINNER.REFUNDAMOUNT * GST.IGST / 100 END, 0)) AS IGST
			, SUM(ISNULL(CREFINNER.REFUNDAMOUNT * GST.CESS / 100, 0)) AS CESS		
		FROM
			POS_CREFUND CREFINNER WITH(NOLOCK) 
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = CREFINNER.COUNTERID 						
			INNER JOIN POS_BILLDETAIL PBD WITH(NOLOCK) ON PBD.BILLDETAILID = CREFINNER.BILLDETAILID AND PBD.BRANCHCOUNTERID = CREFINNER.COUNTERID
			INNER JOIN POS_BILL PB	WITH(NOLOCK) ON PBD.BILLID = PB.BILLID AND PBD.BRANCHCOUNTERID = PB.BRANCHCOUNTERID	
			INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = PBD.GSTID
			INNER JOIN #TAXBREAKUP TB ON TB.BRANCHID = BC.BRANCHID AND TB.DAYSEQ = CAST(CREFINNER.CREATEDDATE AS DATE)
		WHERE
			CREFINNER.DELETEDDATE IS NULL AND PBD.DELETEDDATE IS NULL 
			AND CAST(CREFINNER.CREATEDDATE AS DATE) = @CurDate		
		GROUP BY CAST(CREFINNER.CREATEDDATE AS DATE), BC.BRANCHID, PBD.GSTID
			
		SELECT @CurDate = DATEADD(d, 1, @CurDate)

	END
		
	UPDATE TBMAIN
	SET 
		  GST0AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
		, GST0AMOUNTCGST = 0.00
		, GST0AMOUNTSGST = 0.00
		, GST0AMOUNTIGST = 0.00
		, GST0AMOUNTCESS = 0.00
		, GST0AMOUNTTAX = 0.00
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 0 %'

	UPDATE TBMAIN
	SET 
		  GST3AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0) 
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST3AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST3AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST3AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST3AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST3AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 3 %'

	UPDATE TBMAIN
	SET 
		  GST5AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST5AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST5AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST5AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST5AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST5AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 5 %'

	UPDATE TBMAIN
	SET 
		  GST12AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST12AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST12AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST12AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST12AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST12AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 12 %'

	UPDATE TBMAIN
	SET 
		  GST18AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST18AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST18AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST18AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST18AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST18AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 18 %'

	UPDATE TBMAIN
	SET 
		  GST28AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST28AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST28AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST28AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST28AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST28AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 %'

	UPDATE TBMAIN
	SET 
		  GST33AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST33AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST33AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST33AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST33AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST33AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 + 5C %'

	UPDATE TBMAIN
	SET 
		  GST28G12CAMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST28G12CAMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST28G12CAMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST28G12CAMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST28G12CAMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST28G12CAMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 + 12C %'

	UPDATE TBMAIN
	SET 
		  GST40AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST40AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST40AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST40AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST40AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST40AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 40 %'

	UPDATE TBMAIN
	SET 
		  GST64AMOUNT = CALVAL.BILLEDAMOUNT - ISNULL(CALREF.REFUNDAMOUNT, 0)
			- (CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0))
		, GST64AMOUNTCGST = CALVAL.CGST - ISNULL(CALREF.CGST, 0)
		, GST64AMOUNTSGST = CALVAL.SGST - ISNULL(CALREF.SGST, 0)
		, GST64AMOUNTIGST = CALVAL.IGST - ISNULL(CALREF.IGST, 0)
		, GST64AMOUNTCESS = CALVAL.CESS - ISNULL(CALREF.CESS, 0)
		, GST64AMOUNTTAX = CALVAL.CGST + CALVAL.SGST + CALVAL.IGST + CALVAL.CESS - ISNULL(CALREF.CGST, 0) - ISNULL(CALREF.SGST, 0) - ISNULL(CALREF.IGST, 0) - ISNULL(CALREF.CESS, 0)
	FROM
		#TAXBREAKUP TBMAIN 
		INNER JOIN #BILLDETAILDAYWISE CALVAL ON DATEPART(DAYOFYEAR, CALVAL.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALVAL.BRANCHID = TBMAIN.BRANCHID
		INNER JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = CALVAL.GSTID
		LEFT JOIN #REFUNDDAYWISE CALREF ON DATEPART(DAYOFYEAR, CALREF.DAYSEQ) = DATEPART(DAYOFYEAR, TBMAIN.DAYSEQ) AND CALREF.BRANCHID = TBMAIN.BRANCHID AND CALREF.GSTID = CALVAL.GSTID
	WHERE 
		GST.GSTCODE = 'GST 28 + 36C %'

	UPDATE TBMAIN
	SET 
		  TOTALBILLEDAMOUNTWOT = ISNULL(GST0AMOUNT, 0) + ISNULL(GST33AMOUNT, 0) + ISNULL(GST5AMOUNT, 0) + ISNULL(GST12AMOUNT, 0) 
				+ ISNULL(GST18AMOUNT, 0) + ISNULL(GST28AMOUNT, 0) + ISNULL(GST33AMOUNT, 0) + ISNULL(GST28G12CAMOUNT, 0)
				+ ISNULL(GST40AMOUNT, 0)+ ISNULL(GST64AMOUNT, 0)		  
		  , TOTALTAX = 
				ISNULL(GST0AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST5AMOUNTTAX, 0) + ISNULL(GST12AMOUNTTAX, 0) 
				+ ISNULL(GST18AMOUNTTAX, 0) + ISNULL(GST28AMOUNTTAX, 0) + ISNULL(GST33AMOUNTTAX, 0) + ISNULL(GST28G12CAMOUNTTAX, 0)
				+ ISNULL(GST40AMOUNTTAX, 0) + ISNULL(GST64AMOUNTTAX, 0)
	FROM
		#TAXBREAKUP TBMAIN

	UPDATE TBMAIN
	SET TOTALBILLEDAMOUNTWT = TOTALBILLEDAMOUNTWOT + TOTALTAX
	FROM #TAXBREAKUP TBMAIN
			


	SELECT DAYSEQ, B.BRANCHNAME
	, ISNULL(GST0AMOUNT, 0)  AS 'GST 0% AMT'
	, ISNULL(GST0AMOUNTCGST, 0) 'GST 0% CGST' 
	, ISNULL(GST0AMOUNTSGST, 0) 'GST 0% SGST' 
	, ISNULL(GST0AMOUNTIGST, 0) 'GST 0% IGST' 
	, ISNULL(GST0AMOUNTCESS, 0) 'GST 0% CESS' 
	, ISNULL(GST0AMOUNTTAX , 0) 'GST 0% TAX' 
	, ISNULL(GST3AMOUNT , 0)	 'GST 3% AMT'
	, ISNULL(GST3AMOUNTCGST , 0) 'GST 3% CGST' 
	, ISNULL(GST3AMOUNTSGST , 0) 'GST 3% SGST' 
	, ISNULL(GST3AMOUNTIGST , 0) 'GST 3% IGST' 
	, ISNULL(GST3AMOUNTCESS , 0) 'GST 3% CESS' 
	, ISNULL(GST3AMOUNTTAX , 0)	 'GST 3% TAX' 
	, ISNULL(GST5AMOUNT , 0)	  'GST 5% AMT'
	, ISNULL(GST5AMOUNTCGST , 0)  'GST 5% CGST' 
	, ISNULL(GST5AMOUNTSGST , 0)  'GST 5% SGST' 
	, ISNULL(GST5AMOUNTIGST , 0)  'GST 5% IGST' 
	, ISNULL(GST5AMOUNTCESS , 0)  'GST 5% CESS' 
	, ISNULL(GST5AMOUNTTAX , 0)	  'GST 5% TAX' 
	, ISNULL(GST12AMOUNT , 0)		 'GST 12% AMT'
	, ISNULL(GST12AMOUNTCGST , 0)	 'GST 12% CGST' 
	, ISNULL(GST12AMOUNTSGST , 0)	 'GST 12% SGST' 
	, ISNULL(GST12AMOUNTIGST , 0)	 'GST 12% IGST' 
	, ISNULL(GST12AMOUNTCESS , 0)	 'GST 12% CESS' 
	, ISNULL(GST12AMOUNTTAX , 0)	 'GST 12% TAX' 
	, ISNULL(GST18AMOUNT , 0)		 'GST 18% AMT'
	, ISNULL(GST18AMOUNTCGST , 0)	 'GST 18% CGST' 
	, ISNULL(GST18AMOUNTSGST , 0)	 'GST 18% SGST' 
	, ISNULL(GST18AMOUNTIGST , 0)	 'GST 18% IGST' 
	, ISNULL(GST18AMOUNTCESS , 0)	 'GST 18% CESS' 
	, ISNULL(GST18AMOUNTTAX , 0)	 'GST 18% TAX' 
	, ISNULL(GST28AMOUNT , 0)		  'GST 28% AMT'
	, ISNULL(GST28AMOUNTCGST , 0)	  'GST 28% CGST' 
	, ISNULL(GST28AMOUNTSGST , 0)	  'GST 28% SGST' 
	, ISNULL(GST28AMOUNTIGST , 0)	  'GST 28% IGST' 
	, ISNULL(GST28AMOUNTCESS , 0)	  'GST 28% CESS' 
	, ISNULL(GST28AMOUNTTAX , 0)	  'GST 28% TAX' 
	, ISNULL(GST33AMOUNT , 0)			'GST 33% AMT'
	, ISNULL(GST33AMOUNTCGST , 0)		'GST 33% CGST' 
	, ISNULL(GST33AMOUNTSGST , 0)		'GST 33% SGST' 
	, ISNULL(GST33AMOUNTIGST , 0)		'GST 33% IGST' 
	, ISNULL(GST33AMOUNTCESS , 0)		'GST 33% CESS' 
	, ISNULL(GST33AMOUNTTAX , 0)		'GST 33% TAX' 
	, ISNULL(GST28G12CAMOUNT , 0)	   'GST 28+12% AMT'
	, ISNULL(GST28G12CAMOUNTCGST , 0)  'GST 28+12% CGST' 
	, ISNULL(GST28G12CAMOUNTSGST , 0)  'GST 28+12% SGST' 
	, ISNULL(GST28G12CAMOUNTIGST , 0)  'GST 28+12% IGST' 
	, ISNULL(GST28G12CAMOUNTCESS , 0)  'GST 28+12% CESS' 
	, ISNULL(GST28G12CAMOUNTTAX , 0)   'GST 28+12% TAX' 
	, ISNULL(GST40AMOUNT , 0)	   'GST 40% AMT'
	, ISNULL(GST40AMOUNTCGST , 0)  'GST 40% CGST' 
	, ISNULL(GST40AMOUNTSGST , 0)  'GST 40% SGST' 
	, ISNULL(GST40AMOUNTIGST , 0)  'GST 40% IGST' 
	, ISNULL(GST40AMOUNTCESS , 0)  'GST 40% CESS' 
	, ISNULL(GST40AMOUNTTAX , 0)   'GST 40% TAX' 
	, ISNULL(GST64AMOUNT , 0)		 'GST 64% AMT'
	, ISNULL(GST64AMOUNTCGST , 0)	 'GST 64% CGST' 
	, ISNULL(GST64AMOUNTSGST , 0)	 'GST 64% SGST' 
	, ISNULL(GST64AMOUNTIGST , 0)	 'GST 64% IGST' 
	, ISNULL(GST64AMOUNTCESS , 0)	 'GST 64% CESS' 
	, ISNULL(GST64AMOUNTTAX , 0)	 'GST 64% TAX' 
	, TOTALBILLEDAMOUNTWOT
	, TOTALTAX 
	, TOTALBILLEDAMOUNTWT
	FROM 
		#TAXBREAKUP TB
		INNER JOIN BRANCH B WITH(NOLOCK) ON B.BRANCHID = TB.BRANCHID
	ORDER BY 2 , 1


	DROP TABLE #TAXBREAKUP

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_VOIDDATAANALYSIS_Bills]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_VOIDDATAANALYSIS_Bills]
	
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(500)
	, @UnmaskCustomerPhone BIT = 0
AS
BEGIN

	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	SELECT 
		PBD.BILLID,
		PBD.BRANCHCOUNTERID,
		PBD.DELETEDDATE,
		PBD.BILLEDAMOUNT
	INTO #BILLDETAIL
	FROM POS_BILLDETAIL PBD 
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN #BRANCH BINNER ON BC.BRANCHID = BINNER.ITEM
	WHERE 
		PBD.CREATEDDATE > (@FromDate)
		AND PBD.CREATEDDATE < @ToDate


	SELECT 
		PB.BILLID,
		PB.BRANCHCOUNTERID,
		0 AS BILLEDITEMCOUNT,
		0 AS VOIDITEMCOUNT,
		CAST(0.00 AS DECIMAL(18,2)) AS BILLEDITEMVALUE,
		CAST(0.00 AS DECIMAL(18,2)) AS VOIDITEMVALUE
	INTO #BILLS
	FROM POS_BILL PB WITH(NOLOCK)
	WHERE EXISTS
	(
		SELECT 1 FROM #BILLDETAIL PBD 
		WHERE PB.BILLID = PBD.BILLID
			AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
			AND PBD.DELETEDDATE IS NOT NULL
	)
	
	UPDATE  BINNER
	SET 
		BINNER.VOIDITEMCOUNT = PBD.VOIDITEMCOUNT, 
		BINNER.VOIDITEMVALUE = PBD.VOIDITEMVALUE,
		BINNER.BILLEDITEMCOUNT = PBD.BILLEDITEMCOUNT, 
		BINNER.BILLEDITEMVALUE = PBD.BILLEDITEMVALUE
	FROM #BILLS BINNER
		INNER JOIN 
		(
			SELECT 
				PBD.BILLID,
				PBD.BRANCHCOUNTERID,
				SUM(CASE WHEN PBD.DELETEDDATE IS NULL THEN 1 ELSE 0 END) AS BILLEDITEMCOUNT,
				SUM(CASE WHEN PBD.DELETEDDATE IS NOT NULL THEN 1 ELSE 0 END) AS VOIDITEMCOUNT,
				SUM(CASE WHEN PBD.DELETEDDATE IS NULL THEN PBD.BILLEDAMOUNT ELSE 0.00 END) AS BILLEDITEMVALUE,
				SUM(CASE WHEN PBD.DELETEDDATE IS NOT NULL THEN PBD.BILLEDAMOUNT ELSE 0.00 END) AS VOIDITEMVALUE
			FROM #BILLDETAIL PBD 
			GROUP BY PBD.BILLID, PBD.BRANCHCOUNTERID
		) PBD ON BINNER.BILLID = PBD.BILLID AND BINNER.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID

	SELECT 
		PB.BILLID,
		BC.BRANCHID, 
		BC.COUNTERID,
		B.BRANCHNAME,
		BC.COUNTERNAME,
		PB.BILLNUMBER,
		CU.FULLNAME AS BILLEDBY,
		CAST(PB.CREATEDDATE AS TIME) AS CREATEDDATE ,
		CAST(PB.BILLCLOSEDDATE AS TIME) AS BILLCLOSEDDATE,
		VOIDITEMCOUNT,
		VOIDITEMVALUE,
		BILLEDITEMCOUNT,
		BILLEDITEMVALUE,
		CASE WHEN PB.BILLSTATUS = 0 THEN 'Open Bill' WHEN PB.BILLSTATUS = 1 THEN 'Closed Bill' ELSE 'Draft Bill' END BILLSTATUS,
		PB.CUSTOMERNAME, 
		CASE WHEN PB.CUSTOMERNUMBER IS NOT NULL AND @UnmaskCustomerPhone = 0 THEN 'XXXXXX' + RIGHT(PB.CUSTOMERNUMBER, 4) ELSE PB.CUSTOMERNUMBER END CUSTOMERNUMBER,
		PB.CUSTOMERGST, CASE WHEN PB.ISIGSTBILL = 1 THEN 'Yes' ELSE 'No' END IsIGSTBill,
		CASE WHEN ISNULL(PB.ISDOORDELIVERY,0) = 0 THEN 'No' ELSE 'Yes' END AS ISDOORDELIVERY
	FROM #BILLS PBTEMP WITH(NOLOCK)
		INNER JOIN  POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBTEMP.BILLID AND PB.BRANCHCOUNTERID = PBTEMP.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBTEMP.BRANCHCOUNTERID
		INNER JOIN BRANCH B ON BC.BRANCHID = B.BRANCHID
		INNER JOIN #BRANCH BINNER ON BC.BRANCHID = BINNER.ITEM
		INNER JOIN TBLUSER CU ON PB.CREATEDBY = CU.USERID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_VOIDITEMS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_VOIDITEMS]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(500)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCounter BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeClassification BIT = 0
	, @IncludeSubClassification BIT = 0	
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(500) 
	, @IncludeBillDetails BIT = 0
	, @IncludeUser BIT = 0
	, @UnmaskCustomerPhone BIT = 0
)
AS
BEGIN

	SELECT @ToDate = DATEADD(d, 1, @ToDate)
	
	CREATE TABLE #BD(ITEMPRICEID INT, BRANCHID INT, COUNTERID INT, CATEGORYID INT, SUBCATEGORYID INT, BILLEDAMOUNT DECIMAL(14, 2), GSTVALUE DECIMAL(14, 2)
		, QUANTITY DECIMAL(14, 2), DELETEDDATE DATETIME, CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT, ITEMID INT, GSTID INT, ISOFFER BIT
		, OFFERID INT, CREATEDBY INT, BILLNUMBER VARCHAR(30), ISDOORDELIVERY BIT, CUSTOMERNAME VARCHAR(100)
		, CUSTOMERNUMBER VARCHAR(10), CUSTOMERGST VARCHAR(100),CREATEDDATE DATETIME)

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, COUNTERID INT, SALEQUANTITY DECIMAL(11, 2), SALEPRICE DECIMAL(14, 2)
		, SALEPRICEWOT DECIMAL(14, 2), SALEPRICETAX DECIMAL(14, 2), PERIODOCITY DATETIME, TOTALSALEPRICEWOT DECIMAL(14, 2)
		, TOTALSALETAX DECIMAL(14, 2), TOTALSALEPRICEWT DECIMAL(14, 2), CATEGORYID INT, SUBCATEGORYID INT, BILLNUMBER VARCHAR(30)
		, CLASSIFICATIONID INT, SUBCLASSIFICATIONID INT, ITEMID INT, ISOFFER BIT, GSTID INT, OFFERID INT
		, CREATEDBY INT, DELETEDTIME TIME, ISDOORDELIVERY VARCHAR(5), CUSTOMERNAME VARCHAR(100), CUSTOMERNUMBER VARCHAR(10), CUSTOMERGST VARCHAR(100),CREATEDTIME TIME)
	
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')
	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	
	INSERT INTO #BD
	SELECT IP.ITEMPRICEID, 
		BC.BRANCHID, 
		BC.COUNTERID,
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		PBD.BILLEDAMOUNT, 
		PBD.GSTVALUE, 
		CASE WHEN ISNULL(I.ISOPENITEM, 0) = 0 THEN PBD.QUANTITY ELSE PBD.WEIGHTINKGS END AS QUANTITY, 
		PBD.DELETEDDATE, I.CLASSIFICATIONID, I.SUBCLASSIFICATIONID, I.ITEMID, PBD.GSTID
		, CASE WHEN PBD.OFFERID IS NOT NULL THEN 1 ELSE 0 END ISOFFER, PBD.OFFERID, PB.CREATEDBY, PB.BILLNUMBER
		, PB.ISDOORDELIVERY, PB.CUSTOMERNAME, PB.CUSTOMERNUMBER, PB.CUSTOMERGST, PBD.CREATEDDATE
	FROM POS_BILLDETAIL PBD WITH(NOLOCK)
		INNER JOIN POS_BILL PB WITH(NOLOCK) ON PB.BILLID = PBD.BILLID AND PB.BRANCHCOUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID
		INNER JOIN #BRANCH B ON BC.BRANCHID = B.ITEM
		INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = PBD.ITEMPRICEID 
		INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		INNER JOIN #CATEGORY CAT ON CAT.Item = I.CATEGORYID
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		--AND (I.CATEGORYID = @CategoryID OR @CategoryID = 13)
		AND PBD.CREATEDDATE > (@FromDate)
		AND PBD.CREATEDDATE < @ToDate
		AND PBD.DELETEDDATE IS NOT NULL
		--AND PB.BILLSTATUS = 1
		
	INSERT INTO #PROFITABILIY(
		ITEMPRICEID, BRANCHID, COUNTERID, CATEGORYID, SUBCATEGORYID, PERIODOCITY, SALEQUANTITY, TOTALSALEPRICEWT, TOTALSALETAX
		, CLASSIFICATIONID, SUBCLASSIFICATIONID, ITEMID, CREATEDBY, BILLNUMBER, ISDOORDELIVERY, CUSTOMERNAME
		, CUSTOMERNUMBER, CUSTOMERGST, ISOFFER, OFFERID, CREATEDTIME, DELETEDTIME)
	SELECT CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
			, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
			, CASE WHEN @IncludeCounter = 1 THEN COUNTERID ELSE NULL END
			, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(DELETEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(DELETEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(DELETEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(DELETEDDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END		
			, SUM(QUANTITY) AS QUANTITY 
			, SUM(BILLEDAMOUNT) AS BILLEDAMOUNT
			, SUM(GSTVALUE) AS GSTVALUE
			, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END
			, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END
			, CASE WHEN @IncludeUser = 1 THEN CREATEDBY ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN BILLNUMBER ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN (CASE WHEN ISDOORDELIVERY = 1 THEN 'Yes' ELSE 'No' END) ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNAME ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNUMBER ELSE NULL END
			, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERGST ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN ISOFFER ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN OFFERID ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN CAST(CREATEDDATE AS TIME) ELSE NULL END
			, CASE WHEN @IncludeItem = 1 THEN CAST(DELETEDDATE AS TIME) ELSE NULL END
	FROM #BD BD
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN ITEMPRICEID ELSE NULL END
		, CASE WHEN @IncludeBranch = 1 THEN BRANCHID ELSE NULL END
		, CASE WHEN @IncludeCounter = 1 THEN COUNTERID ELSE NULL END
		, CASE WHEN @IncludeCategory = 1 THEN CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(DELETEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(DELETEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(DELETEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(DELETEDDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeClassification = 1 THEN CLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeSubClassification = 1 THEN SUBCLASSIFICATIONID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN ITEMID ELSE NULL END
		, CASE WHEN @IncludeUser = 1 THEN CREATEDBY ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN BILLNUMBER ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN (CASE WHEN ISDOORDELIVERY = 1 THEN 'Yes' ELSE 'No' END) ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNAME ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERNUMBER ELSE NULL END
		, CASE WHEN @IncludeBillDetails = 1 THEN CUSTOMERGST ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN ISOFFER ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN OFFERID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN CAST(CREATEDDATE AS TIME) ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN CAST(DELETEDDATE AS TIME) ELSE NULL END
	UPDATE PT
	SET SALEPRICETAX = ROUND(IP.SALEPRICE -((IP.SALEPRICE / (100 + GST.CGST + GST.SGST + GST.CESS)) * 100), 2)
		, SALEPRICE = IP.SALEPRICE
	FROM 
		#PROFITABILIY PT
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = PT.ITEMPRICEID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID

	UPDATE PT
	SET 
		SALEPRICEWOT = SALEPRICE - SALEPRICETAX
		, PT.TOTALSALEPRICEWOT = PT.TOTALSALEPRICEWT - PT.TOTALSALETAX
	FROM #PROFITABILIY PT

	UPDATE #PROFITABILIY
	SET CUSTOMERNUMBER = CASE WHEN CUSTOMERNUMBER IS NOT NULL AND @UnmaskCustomerPhone = 0 THEN 'XXXXXX' + RIGHT(CUSTOMERNUMBER, 4) ELSE CUSTOMERNUMBER END
		
	SELECT 
		PT.PERIODOCITY, B.BRANCHNAME, BC.COUNTERNAME, CAT.CATEGORYNAME, SC.SUBCATEGORYNAME, I.SKUCODE, I.ITEMNAME, IC.ITEMCODE, IC.HSNCODE
		, IP.MRP, GST.GSTCODE, PT.SALEPRICEWOT, PT.SALEPRICETAX, PT.SALEPRICE, PT.SALEQUANTITY
		, PT.TOTALSALEPRICEWOT, PT.TOTALSALETAX, PT.TOTALSALEPRICEWT, ICLS.CLASSIFICATIONNAME, ISCLS.SUBCLASSIFICATIONNAME
		, CASE WHEN PT.ISOFFER = 1 THEN 'Yes' ELSE 'No' END AS ISOFFER, OFR.OFFERCODE, BOFR.OFFERCODE BASEOFFERCODE
		, USR.FULLNAME BILLCREATEDBY, PT.BILLNUMBER, PT.ISDOORDELIVERY, PT.CUSTOMERNAME, PT.CUSTOMERNUMBER, PT.CUSTOMERGST, PT.CREATEDTIME, PT.DELETEDTIME
		, DATEDIFF(MINUTE, PT.CREATEDTIME, PT.DELETEDTIME) VOIDDIFFERENCETIME
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP WITH(NOLOCK) ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT WITH(NOLOCK) ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC WITH(NOLOCK) ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH B WITH(NOLOCK) ON PT.BRANCHID = B.BRANCHID
		LEFT JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON PT.COUNTERID = BC.COUNTERID
		LEFT JOIN ITEMCLASSIFICATION ICLS WITH(NOLOCK) ON ICLS.CLASSIFICATIONID = PT.CLASSIFICATIONID
		LEFT JOIN ITEMSUBCLASSIFICATION ISCLS WITH(NOLOCK) ON ISCLS.SUBCLASSIFICATIONID = PT.SUBCLASSIFICATIONID
		LEFT JOIN GSTDETAIL GST WITH(NOLOCK) ON GST.GSTID = IP.GSTID
		LEFT JOIN OFFER OFR WITH(NOLOCK) ON OFR.OFFERID = PT.OFFERID
		LEFT JOIN BASEOFFER BOFR WITH(NOLOCK) ON BOFR.BASEOFFERID = OFR.BASEOFFERID
		LEFT JOIN TBLUSER USR WITH(NOLOCK) ON USR.USERID = PT.CREATEDBY
	ORDER BY 1, 2, 3, 4, I.ITEMNAME, IC.ITEMCODE, IP.MRP, LEN(GSTCODE), GSTCODE

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_WAREHOUSE_BREFUND_RECEIPT]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_WAREHOUSE_BREFUND_RECEIPT]
(
	@FromDate DATE
	, @ToDate DATE
	, @BranchID VARCHAR(MAX)
	, @Periodicity VARCHAR(20)
	, @IncludeItem BIT = 0
	, @IncludeBranch BIT = 0
	, @IncludeCategory BIT = 0
	, @IncludeSubCategory BIT = 0
	, @IncludeDate BIT = 0
	, @IncludeReason BIT = 0
	, @IncludeRefundNumber BIT = 0
	, @ITEMID INT = 0
	, @CategoryID VARCHAR(MAX)
	, @IncludeTrayNumber BIT = 0
	, @IncludeBrand BIT = 0
	, @IncludeManufacturer BIT = 0
)
AS
BEGIN
	
	SELECT @ToDate = DATEADD(d, 1, @ToDate)

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchID,',')

	CREATE TABLE #PROFITABILIY(ITEMPRICEID INT, BRANCHID INT, QUANTITY DECIMAL(18, 2),
		COSTPRICEWOT DECIMAL(18, 2), COSTPRICEWT DECIMAL(18, 2), COSTPRICETAX DECIMAL(18, 2), 
		TOTALCPWOT DECIMAL(18, 2), TOTALCPWT DECIMAL(18, 2), TOTALCPTAX DECIMAL(18, 2), 
		CATEGORYID INT, SUBCATEGORYID INT, PERIODOCITY DATETIME, GSTID INT,
		REASONID INT,BRID INT,APPROVEDBY INT, APPROVEDDATE DATETIME, AVGCOSTPRICEID INT, 
		TRAYNUMBER INT, BRANDID INT, MANUFACTURERID INT, DESTINATIONBRANCHID INT, SOURCEBRANCHID INT)

	-- Extract base branch refund receipt data
	-- Reports items received into destination branches through accepted Branch Refunds
	-- Filter by SOURCE branch only; ALL destination branches will appear
	-- Receipt date uses ACCEPTEDDATE (when warehouse actually received stock)
	-- Receives exactly what exists in POS_BREFUNDDETAIL without transformation
	SELECT BRD.ITEMPRICEID, 
		ISNULL(ROR.LOCATIONTOMOVESTOCK, 0) AS DESTINATIONBRANCHID,
		BR.BRANCHID AS SOURCEBRANCHID,
		I.CATEGORYID, 
		I.SUBCATEGORYID, 
		I.BRANDID,
		I.MANUFACTURERID,
		-- Quantity: use accepted quantity/weight exactly as stored
		CASE 
			WHEN I.ISOPENITEM = 0 THEN ISNULL(BRD.ACCEPTEDQUANTITY, BRD.QUANTITY)
			ELSE ISNULL(BRD.ACCEPTEDWEIGHTKGS, BRD.WEIGHTINKGS)
		END AS QUANTITY,
		BR.ACCEPTEDDATE,
		BRD.REASONID,
		BR.BRID,
		CASE WHEN ISNULL(BR.IsAccepted,0) = 1 THEN BR.ACCEPTEDBY ELSE NULL END AS APPROVEDBY,
		CASE WHEN ISNULL(BR.IsAccepted,0) = 1 THEN BR.ACCEPTEDDATE ELSE NULL END AS APPROVEDDATE, 
		AICP.AVGCOSTPRICEID, 
		BRD.TRAYNUMBER
	INTO #BRD
	FROM POS_BREFUNDDETAIL BRD
		INNER JOIN POS_BREFUND BR ON BR.BRID = BRD.BRID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID 
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.ITEMCODEID = IP.ITEMCODEID AND AICP.MRP = IP.MRP AND AICP.AVGCPDATE = DATEFROMPARTS(YEAR(BR.ACCEPTEDDATE), MONTH(BR.ACCEPTEDDATE), 1)
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		INNER JOIN #BRANCH B ON BR.BRANCHID = B.ITEM
		INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
		INNER JOIN REASONFORREFUND ROR ON BRD.REASONID = ROR.REASONID
		INNER JOIN BRANCH DESTB ON DESTB.BRANCHID = ROR.LOCATIONTOMOVESTOCK
	WHERE 
		(I.ITEMID = @ITEMID OR @ITEMID = 0)
		AND BR.ACCEPTEDDATE > (@FromDate)
		AND BR.ACCEPTEDDATE < @ToDate
		AND BR.DELETEDDATE IS NULL
		AND BRD.DELETEDDATE IS NULL
		AND BR.IsAccepted = 1
		AND ISNULL(ROR.LOCATIONTOMOVESTOCK, 0) > 0

	-- Aggregate received refund items
	INSERT INTO #PROFITABILIY(ITEMPRICEID, BRANCHID, CATEGORYID,SUBCATEGORYID,
		PERIODOCITY,REASONID,BRID,APPROVEDBY,APPROVEDDATE,QUANTITY, AVGCOSTPRICEID
		, TOTALCPWOT, TOTALCPTAX, TOTALCPWT, TRAYNUMBER,BRANDID, MANUFACTURERID, DESTINATIONBRANCHID, SOURCEBRANCHID)
	SELECT CASE WHEN @IncludeItem = 1 THEN BRD.ITEMPRICEID ELSE NULL END
			, BRD.DESTINATIONBRANCHID
			, CASE WHEN @IncludeCategory = 1 THEN BRD.CATEGORYID ELSE NULL END
			, CASE WHEN @IncludeSubCategory = 1 THEN BRD.SUBCATEGORYID ELSE NULL END
			, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
				WHEN @Periodicity = 'Daily' THEN FORMAT(BRD.ACCEPTEDDATE, 'yyyy-MM-dd 00:00:00')
				WHEN @Periodicity = 'Monthly' THEN FORMAT(BRD.ACCEPTEDDATE, 'yyyy-MM-01 00:00:00')
				WHEN @Periodicity = 'Yearly' THEN FORMAT(BRD.ACCEPTEDDATE, 'yyyy-01-01 00:00:00')
				WHEN @Periodicity = 'Hourly' THEN FORMAT(BRD.ACCEPTEDDATE, '1900-01-01 HH:00')
				END AS DATETIME) ELSE NULL END 
			, CASE WHEN @IncludeReason = 1 THEN BRD.REASONID ELSE NULL END AS REASONID
			, CASE WHEN @IncludeRefundNumber = 1 THEN BRD.BRID ELSE NULL END AS BRID
			, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDBY ELSE NULL END AS APPROVEDBY
			, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDDATE ELSE NULL END AS APPROVEDDATE
			, SUM(BRD.QUANTITY) AS QUANTITY
			, CASE WHEN @IncludeItem = 1 THEN BRD.AVGCOSTPRICEID ELSE NULL END
			, SUM(AICP.COSTPRICEWOT * BRD.QUANTITY), SUM((AICP.COSTPRICEWT - AICP.COSTPRICEWOT) * BRD.QUANTITY) , SUM(AICP.COSTPRICEWT * BRD.QUANTITY)
			, CASE WHEN @IncludeTrayNumber = 1 THEN BRD.TRAYNUMBER ELSE NULL END
			, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
			, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
			, BRD.DESTINATIONBRANCHID
			, CASE WHEN @IncludeBranch = 1 THEN BRD.SOURCEBRANCHID ELSE NULL END
	FROM #BRD BRD
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.AVGCOSTPRICEID = BRD.AVGCOSTPRICEID
	GROUP BY 
		CASE WHEN @IncludeItem = 1 THEN BRD.ITEMPRICEID ELSE NULL END
		, BRD.DESTINATIONBRANCHID
		, CASE WHEN @IncludeCategory = 1 THEN BRD.CATEGORYID ELSE NULL END
		, CASE WHEN @IncludeSubCategory = 1 THEN BRD.SUBCATEGORYID ELSE NULL END
		, CASE WHEN @IncludeDate = 1 THEN CAST(CASE 
			WHEN @Periodicity = 'Daily' THEN FORMAT(BRD.ACCEPTEDDATE, 'yyyy-MM-dd 00:00:00')
			WHEN @Periodicity = 'Monthly' THEN FORMAT(BRD.ACCEPTEDDATE, 'yyyy-MM-01 00:00:00')
			WHEN @Periodicity = 'Yearly' THEN FORMAT(BRD.ACCEPTEDDATE, 'yyyy-01-01 00:00:00')
			WHEN @Periodicity = 'Hourly' THEN FORMAT(BRD.ACCEPTEDDATE, '1900-01-01 HH:00')
			END AS DATETIME) ELSE NULL END
		, CASE WHEN @IncludeReason = 1 THEN BRD.REASONID ELSE NULL END
		, CASE WHEN @IncludeRefundNumber = 1 THEN BRD.BRID ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDBY ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.APPROVEDDATE ELSE NULL END
		, CASE WHEN @IncludeItem = 1 THEN BRD.AVGCOSTPRICEID ELSE NULL END
		, CASE WHEN @IncludeTrayNumber = 1 THEN BRD.TRAYNUMBER ELSE NULL END
		, CASE WHEN @IncludeBrand = 1 THEN BRANDID ELSE NULL END
		, CASE WHEN @IncludeManufacturer = 1 THEN MANUFACTURERID ELSE NULL END
		, BRD.DESTINATIONBRANCHID
		, CASE WHEN @IncludeBranch = 1 THEN BRD.SOURCEBRANCHID ELSE NULL END

	SELECT 
		PT.PERIODOCITY
		, DESTB.BRANCHNAME AS ReceivingBranch
		, SOURCEB.BRANCHNAME AS SourceBranch
		, CAT.CATEGORYNAME
		, SC.SUBCATEGORYNAME
		, TBR.BRANDNAME
		, MAN.MANUFACTURERNAME
		, I.SKUCODE
		, I.VENDORSKUCODE
		, I.ITEMNAME
		, IC.ITEMCODE
		, IC.HSNCODE
		, IP.MRP
		, GST.GSTCODE
		, PT.QUANTITY
		, AICP.COSTPRICEWOT
		, AICP.COSTPRICEWT - AICP.COSTPRICEWOT COSTPRICETAX
		, AICP.COSTPRICEWT
		, PT.TOTALCPWOT TOTALCPEWOT
		, PT.TOTALCPTAX
		, PT.TOTALCPWT
		, RFR.REASONNAME AS Reason
		, BR.BREFUNDNUMBER
		, AU.FULLNAME AS APPROVEDBY
		, PT.APPROVEDDATE
		, PT.TRAYNUMBER
	FROM 
		#PROFITABILIY PT
		LEFT JOIN ITEMPRICE IP ON PT.ITEMPRICEID = IP.ITEMPRICEID
		LEFT JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		LEFT JOIN ITEM I ON I.ITEMID = IC.ITEMID
		LEFT JOIN TBLCATEGORY CAT ON PT.CATEGORYID = CAT.CATEGORYID
		LEFT JOIN SUBCATEGORY SC ON PT.SUBCATEGORYID = SC.SUBCATEGORYID
		LEFT JOIN BRANCH DESTB ON PT.DESTINATIONBRANCHID = DESTB.BRANCHID
		LEFT JOIN BRANCH SOURCEB ON PT.SOURCEBRANCHID = SOURCEB.BRANCHID
		LEFT JOIN REASONFORREFUND RFR ON PT.REASONID = RFR.REASONID
		LEFT JOIN POS_BREFUND BR ON PT.BRID = BR.BRID
		LEFT JOIN TBLUSER AU ON PT.APPROVEDBY = AU.USERID
		LEFT JOIN AVGCOSTPRICE AICP ON AICP.AVGCOSTPRICEID = PT.AVGCOSTPRICEID
		LEFT JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
		LEFT JOIN TBLBRAND TBR ON PT.BRANDID = TBR.BRANDID
		LEFT JOIN TBLMANUFACTURER MAN ON PT.MANUFACTURERID = MAN.MANUFACTURERID
	ORDER BY 1, 2, 3, 4

END
GO
/****** Object:  StoredProcedure [dbo].[USP_RPT_ZEROSTOCK]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_RPT_ZEROSTOCK]  
(  
@BranchIDs VARCHAR(MAX),
@CategoryID VARCHAR(MAX),
@ThresholdValue int = 0
)  
AS  
BEGIN  
  
	DECLARE @WareHouseID INT = 45  

	SELECT * INTO #CATEGORY FROM dbo.SplitString(@CategoryID,',')
	SELECT * INTO #BRANCH FROM dbo.SplitString(@BranchIDs,',')
	/*
	SELECT
			B.BRANCHNAME, I.SKUCODE, I.ITEMNAME,CAT.CATEGORYNAME, SUBCATEGORYNAME, TB.BRANDNAME, TM.MANUFACTURERNAME
			, CAST(STOCK.BRANCHSTOCK AS DECIMAL(18, 2)) BRANCHSTOCK
			, CAST(STOCK.WAREHOUSESTOCK AS DECIMAL(18, 2)) WAREHOUSESTOCK
		FROM
			(
				SELECT   
					I.ITEMID, SS.BRANCHID, 
					SUM(CASE WHEN PARENTITEMCODE.ITEMID IS NULL THEN CAST(SSWAREHOUSE.QUANTITY AS decimal(18, 2)) ELSE ISNULL(PARENTWHSTOCK.WEIGHTINKGS, 0.00) END) AS WAREHOUSESTOCK, 
					SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE CAST(SS.QUANTITY AS decimal(18, 2)) END) AS BRANCHSTOCK
				FROM 
					(
						SELECT IP.ITEMCODEID, SUM(QUANTITY) AS QUANTITY, SUM(WEIGHTINKGS) AS WEIGHTINKGS, SSINNER.BRANCHID
						FROM 
							STOCKSUMMARY  SSINNER
							INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
							INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
							INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
							INNER JOIN #BRANCH BIDS ON BIDS.ITEM = SSINNER.BRANCHID
							INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
						WHERE 
							IP.DELETEDBY IS NULL
						GROUP BY IP.ITEMCODEID, SSINNER.BRANCHID
					) SS  
					INNER JOIN 
					(
						SELECT IP.ITEMCODEID, SUM(SSINNER.QUANTITY) AS QUANTITY, SUM(SSINNER.WEIGHTINKGS) AS WEIGHTINKGS
						FROM 
							STOCKSUMMARY SSINNER
							INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
						WHERE
							SSINNER.BRANCHID = @WareHouseID  
							AND IP.DELETEDBY IS NULL
						GROUP BY IP.ITEMCODEID
					) SSWAREHOUSE ON SSWAREHOUSE.ITEMCODEID = SS.ITEMCODEID 
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = SS.ITEMCODEID  
					INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
					LEFT JOIN ITEMCODE PARENTITEMCODE ON PARENTITEMCODE.ITEMID = CASE WHEN I.ISOPENITEM = 1 THEN I.ITEMID ELSE I.PARENTITEMID END
					LEFT JOIN 
					(
						SELECT IP.ITEMCODEID, SUM(SSINNER.QUANTITY) AS QUANTITY, SUM(SSINNER.WEIGHTINKGS) AS WEIGHTINKGS
						FROM 
							STOCKSUMMARY SSINNER
							INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
						WHERE 
							SSINNER.BRANCHID = @WareHouseID  
							AND IP.DELETEDBY IS NULL
						GROUP BY IP.ITEMCODEID
					)
					PARENTWHSTOCK ON PARENTWHSTOCK.ITEMCODEID = PARENTITEMCODE.ITEMCODEID
				GROUP BY I.ITEMID, SS.BRANCHID
				HAVING 
					SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) >= 0
					AND SUM(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) <= @ThresholdValue
					AND SUM(CASE WHEN PARENTITEMCODE.ITEMID IS NULL THEN SSWAREHOUSE.QUANTITY ELSE PARENTWHSTOCK.WEIGHTINKGS END) <> 0
			) STOCK
			INNER JOIN BRANCH B ON B.BRANCHID = STOCK.BRANCHID  
			INNER JOIN ITEM I ON I.ITEMID = STOCK.ITEMID
			INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID  
			LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID  
			LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
			LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
		ORDER BY LEN(SUBCAT.SUBCATEGORYNAME), SUBCAT.SUBCATEGORYNAME, I.ITEMNAME

		*/

		SELECT B.BRANCHNAME, I.SKUCODE, I.ITEMNAME,CAT.CATEGORYNAME, SUBCATEGORYNAME, TB.BRANDNAME, TM.MANUFACTURERNAME
			, CAST(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END AS DECIMAL(18, 2)) BRANCHSTOCK
			, CAST(CASE WHEN PARENTITEMCODE.ITEMID IS NULL THEN SSWAREHOUSE.QUANTITY ELSE ISNULL(PARENTWHSTOCK.WEIGHTINKGS, 0.00) END AS DECIMAL(18, 2)) WAREHOUSESTOCK
		FROM
			(
				SELECT I.ITEMID, SUM(QUANTITY) AS QUANTITY, SUM(WEIGHTINKGS) AS WEIGHTINKGS, SSINNER.BRANCHID
				FROM 
					STOCKSUMMARY  SSINNER WITH(NOLOCK)
					INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
					INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
					INNER JOIN #BRANCH BIDS ON BIDS.ITEM = SSINNER.BRANCHID
					INNER JOIN #CATEGORY CATINNER ON I.CATEGORYID = CATINNER.ITEM
				WHERE 
					IP.DELETEDBY IS NULL
					AND I.DELETEDDATE IS NULL
				GROUP BY I.ITEMID, SSINNER.BRANCHID
			) SS  
			INNER JOIN 
				(
					SELECT I.ITEMID, SUM(SSINNER.QUANTITY) AS QUANTITY, SUM(SSINNER.WEIGHTINKGS) AS WEIGHTINKGS
					FROM 
						STOCKSUMMARY SSINNER WITH(NOLOCK)
						INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
						INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
						INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
					WHERE
						SSINNER.BRANCHID = @WareHouseID  
						AND IP.DELETEDBY IS NULL
					GROUP BY I.ITEMID
				) SSWAREHOUSE ON SSWAREHOUSE.ITEMID = SS.ITEMID
			INNER JOIN ITEM I ON I.ITEMID = SS.ITEMID
			LEFT JOIN ITEMCODE PARENTITEMCODE ON PARENTITEMCODE.ITEMID = CASE WHEN I.ISOPENITEM = 1 THEN I.ITEMID ELSE I.PARENTITEMID END
			LEFT JOIN 
				(
					SELECT IP.ITEMCODEID, SUM(SSINNER.QUANTITY) AS QUANTITY, SUM(SSINNER.WEIGHTINKGS) AS WEIGHTINKGS
					FROM 
						STOCKSUMMARY SSINNER
						INNER JOIN ITEMPRICE IP ON SSINNER.ITEMPRICEID = IP.ITEMPRICEID
					WHERE 
						SSINNER.BRANCHID = @WareHouseID  
						AND IP.DELETEDBY IS NULL
					GROUP BY IP.ITEMCODEID
				) PARENTWHSTOCK ON PARENTWHSTOCK.ITEMCODEID = PARENTITEMCODE.ITEMCODEID
			INNER JOIN TBLCATEGORY CAT ON CAT.CATEGORYID = I.CATEGORYID  
			INNER JOIN BRANCH B ON B.BRANCHID = SS.BRANCHID  
			LEFT JOIN SUBCATEGORY SUBCAT ON SUBCAT.SUBCATEGORYID = I.SUBCATEGORYID  
			LEFT JOIN TBLBRAND TB ON I.BRANDID = TB.BRANDID
			LEFT JOIN TBLMANUFACTURER TM ON I.MANUFACTURERID = TM.MANUFACTURERID
		WHERE 
			(CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) >= 0
			AND (CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END) <= @ThresholdValue
			AND (CASE WHEN PARENTITEMCODE.ITEMID IS NULL THEN SSWAREHOUSE.QUANTITY ELSE PARENTWHSTOCK.WEIGHTINKGS END) <> 0
			AND EXISTS
				(
					SELECT 1
					FROM
						STOCKDISPATCHDETAIL SDD WITH(NOLOCK)
						INNER JOIN STOCKDISPATCH SD WITH(NOLOCK) ON SD.STOCKDISPATCHID = SDD.STOCKDISPATCHID
						INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
						INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					WHERE
						SDD.DELETEDDATE IS NULL
						AND IC.ITEMID = SS.ITEMID
						AND SD.TOBRANCHID = SS.BRANCHID
						AND SD.STATUS <> 0						
				)
		ORDER BY LEN(SUBCAT.SUBCATEGORYNAME), SUBCAT.SUBCATEGORYNAME, I.ITEMNAME
			

END
GO
/****** Object:  StoredProcedure [dbo].[USP_SAVE_SUPPLIERINDENT_BATCHWISE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_SAVE_SUPPLIERINDENT_BATCHWISE]
(
	@SupplierID INT 
	, @CategoryID INT
	, @ManufacturerID INT = NULL
	, @SafetyDays INT
	, @IndentItemSelectionType INT
	, @BranchID INT = NULL
	, @UserID INT
	, @SUPPLIERINDENTDETAIL GEN_SUPPLIERINDENTDETAIL READONLY
	, @ITEMSTOCKDATA GEN_SUPPLIERINDENT_FTDETAIL READONLY
)
AS    
BEGIN    

	SET @BranchID = ISNULL(@BranchID, 45);

	DECLARE @BranchCode VARCHAR(MAX);
	SELECT @BranchCode = LTRIM(RTRIM(BRANCHCODE))
	FROM BRANCH
	WHERE BRANCHID = @BranchID;

	SELECT ROW_NUMBER() OVER (ORDER BY DESIREDITEMINDENT DESC, ITEMID) AS ID, * INTO #SUPPLIERINDENTDETAIL FROM @SUPPLIERINDENTDETAIL

	DECLARE @SupplierItemIndentType VARCHAR(100), @TargetBranchID INT, @SIDRowCount INT, @IndentCounter INT	= 0
	DECLARE @FINYEAR INT, @FINYEARSTARTDATE DATE, @SUPPLIERINDENTNO VARCHAR(30), @IndentTypeID INT
		, @SUPPLIERINDENTID INT, @SI_GROUPINGID INT

	
	SELECT @FINYEAR = YEAR(GETDATE()) - CASE WHEN MONTH(GETDATE()) < 4 THEN 1 ELSE 0 END
	SELECT @FINYEARSTARTDATE = DATEFROMPARTS(@FINYEAR, 04, 01)
	
	SELECT @SupplierItemIndentType = ENUMVALUE FROM ENUMLIST WHERE ENUMID = @IndentItemSelectionType
		
	SELECT @IndentTypeID = ENUMID FROM ENUMLIST WHERE ENUMTYPE = 'Supplier Indent Type' AND ENUMVALUE = 'Indent By MBQ'

	SELECT @SIDRowCount = COUNT(1) FROM #SUPPLIERINDENTDETAIL WHERE DESIREDITEMINDENT > 0

	SELECT @SI_GROUPINGID = MAX(GROUPINGID) FROM SUPPLIERINDENT
	SELECT @SI_GROUPINGID  = ISNULL(@SI_GROUPINGID, 0) + 1
	
	WHILE @SIDRowCount > 0
	BEGIN

		SELECT @SUPPLIERINDENTNO = @BranchCode + '-' + CAT.CATEGORYNAME + '-' + RIGHT(CAST(@FINYEAR AS VARCHAR(4)), 2) + '-' + RIGHT('000000' + CAST(COUNT(1) + 1 AS VARCHAR(10)), 7)
		FROM 
			TBLCATEGORY CAT
			LEFT JOIN SUPPLIERINDENT SI ON CAT.CATEGORYID = SI.CATEGORYID AND SI.CREATEDDATE > @FINYEARSTARTDATE
		WHERE 
			CAT.CATEGORYID = @CategoryID	
		GROUP BY CAT.CATEGORYNAME

		PRINT 'Creating indent - ' + @SUPPLIERINDENTNO

		INSERT INTO SUPPLIERINDENT(SUPPLIERID, INDENTDAYS, SAFETYDAYS, CATEGORYID, CREATEDBY, CREATEDDATE, STATUS, SUPPLIERINDENTNO, MOBILENO
			, SUPPLIERINDENTTYPEID, BRANCHID, GROUPINGID, SUPPLIERITEMINDENTTYPEID, MANUFACTURERID, ISINTERNAL)  
		SELECT @SUPPLIERID, 14, @SafetyDays, @CATEGORYID, @USERID, GETDATE(), 14, @SUPPLIERINDENTNO, CNUMBER, @IndentTypeID, @BranchID 
			, @SI_GROUPINGID, @IndentItemSelectionType, @ManufacturerID, 0
		FROM TBLUSER WHERE USERID = @USERID

		SET @SUPPLIERINDENTID = SCOPE_IDENTITY()  
		
		INSERT INTO SUPPLIERINDENTDETAIL(SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, CALCULATEDITEMINDENT, REQUIREDITEMINDENT, DESIREDINDENT, CREATEDBY, CREATEDDATE, MRP, COSTPRICEWT)  
		SELECT TOP 30 @SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, CALCULATEDITEMINDENT, REQUIREDITEMINDENT, DESIREDITEMINDENT, @USERID, GETDATE(), MRP, COSTPRICEWT
		FROM #SUPPLIERINDENTDETAIL
		WHERE DESIREDITEMINDENT > 0	
		ORDER BY DESIREDITEMINDENT DESC, ITEMID

		IF @SupplierItemIndentType = 'Flow Through'
		BEGIN
			
			INSERT INTO SID_FT_DETAIL(SUPPLIERINDENTDETAILID, BRANCHID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT)
			SELECT SID.SUPPLIERINDENTDETAILID, ISD.BRANCHID, ISD.BRANCHQUANTITY, ISD.REQUIREDBRANCHSTOCK, ISD.REQUIREDITEMINDENT 
			FROM 
				(
					SELECT TOP 30 *
					FROM #SUPPLIERINDENTDETAIL SIDINNER
					WHERE DESIREDITEMINDENT > 0
					ORDER BY DESIREDITEMINDENT DESC, ITEMID
				) SIDTEMP
				INNER JOIN SUPPLIERINDENTDETAIL SID ON SID.ITEMID = SIDTEMP.ITEMID
				INNER JOIN @ITEMSTOCKDATA ISD ON ISD.ITEMID = SID.ITEMID
			WHERE SID.SUPPLIERINDENTID = @SUPPLIERINDENTID

		END

		DELETE SID
		FROM #SUPPLIERINDENTDETAIL SID
		WHERE SID.ID IN 
			(
				SELECT TOP 30 ID
				FROM #SUPPLIERINDENTDETAIL
				WHERE DESIREDITEMINDENT > 0
				ORDER BY DESIREDITEMINDENT DESC, ITEMID
			)
			
		SELECT @SIDRowCount = COUNT(1) FROM #SUPPLIERINDENTDETAIL WHERE DESIREDITEMINDENT > 0

		SELECT @IndentCounter = @IndentCounter + 1

	END

	SELECT @SIDRowCount = COUNT(1) FROM #SUPPLIERINDENTDETAIL WHERE DESIREDITEMINDENT <= 0

	IF @SIDRowCount > 0
	BEGIN
			
		SELECT @SUPPLIERINDENTNO = @BranchCode + '-' + CAT.CATEGORYNAME + '-' + RIGHT(CAST(@FINYEAR AS VARCHAR(4)), 2) + '-' + RIGHT('000000' + CAST(COUNT(1) + 1 AS VARCHAR(10)), 7) + ' - Zero'
		FROM 
			TBLCATEGORY CAT
			LEFT JOIN SUPPLIERINDENT SI ON CAT.CATEGORYID = SI.CATEGORYID AND SI.CREATEDDATE > @FINYEARSTARTDATE
		WHERE 
			CAT.CATEGORYID = @CategoryID	
		GROUP BY CAT.CATEGORYNAME

		PRINT 'Creating zero indent - ' + @SUPPLIERINDENTNO

		INSERT INTO SUPPLIERINDENT(SUPPLIERID, INDENTDAYS, SAFETYDAYS, CATEGORYID, CREATEDBY, CREATEDDATE, STATUS, SUPPLIERINDENTNO, MOBILENO
			, SUPPLIERINDENTTYPEID, BRANCHID, GROUPINGID, SUPPLIERITEMINDENTTYPEID, MANUFACTURERID, ISINTERNAL)  
		SELECT @SUPPLIERID, 14, @SafetyDays, @CATEGORYID, @USERID, GETDATE(), 14, @SUPPLIERINDENTNO, CNUMBER, @IndentTypeID, @BranchID 
			, @SI_GROUPINGID, @IndentItemSelectionType, @ManufacturerID, 1
		FROM TBLUSER WHERE USERID = @USERID

		SET @SUPPLIERINDENTID = SCOPE_IDENTITY()  
		
		INSERT INTO SUPPLIERINDENTDETAIL(SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, CALCULATEDITEMINDENT, REQUIREDITEMINDENT, DESIREDINDENT, CREATEDBY, CREATEDDATE, MRP, COSTPRICEWT)  
		SELECT @SUPPLIERINDENTID, ITEMID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, CALCULATEDITEMINDENT, REQUIREDITEMINDENT, DESIREDITEMINDENT, @USERID, GETDATE(), MRP, COSTPRICEWT
		FROM #SUPPLIERINDENTDETAIL
		WHERE DESIREDITEMINDENT <= 0		

		IF @SupplierItemIndentType = 'Flow Through'
		BEGIN
			
			INSERT INTO SID_FT_DETAIL(SUPPLIERINDENTDETAILID, BRANCHID, BRANCHQUANTITY, REQUIREDBRANCHSTOCK, REQUIREDITEMINDENT)
			SELECT SID.SUPPLIERINDENTDETAILID, ISD.BRANCHID, ISD.BRANCHQUANTITY, ISD.REQUIREDBRANCHSTOCK, ISD.REQUIREDITEMINDENT 
			FROM 
				#SUPPLIERINDENTDETAIL SIDTEMP				
				INNER JOIN SUPPLIERINDENTDETAIL SID ON SID.ITEMID = SIDTEMP.ITEMID
				INNER JOIN @ITEMSTOCKDATA ISD ON ISD.ITEMID = SID.ITEMID
			WHERE 
				SID.SUPPLIERINDENTID = @SUPPLIERINDENTID
				AND SIDTEMP.DESIREDITEMINDENT <= 0

		END
		
		SELECT @IndentCounter = @IndentCounter + 1


	END
	
	PRINT 'Total # of supplier indents created - ' + CAST(@IndentCounter AS VARCHAR(10))

END
GO
