CREATE PROC [dbo].[USP_SYNC_CU_STOCKCOUNTING]
(  
@StockCounting STOCKCOUNTINGTYPE READONLY  
)  
AS  
BEGIN  
	UPDATE SC
	SET  
		SC.BRANCHID =SCN.BRANCHID
		,SC.CREATEDBY = SCN.CREATEDBY
		,SC.CREATEDDATE = SCN.CREATEDDATE
		,SC.UPDATEDBY = SCN.UPDATEDBY
		,SC.UPDATEDDATE = SCN.UPDATEDDATE
		,SC.DELETEDBY = SCN.DELETEDBY
		,SC.DELETEDDATE = SCN.DELETEDDATE
		,SC.STATUS = SCN.STATUS
		,SC.STOCKLOCATIONID = SCN.STOCKLOCATIONID

	FROM STOCKCOUNTING SC
		INNER JOIN @StockCounting SCN 
	ON SCN.STOCKCOUNTINGID = SC.STOCKCOUNTINGID
	WHERE ISNULL(SC.STATUS, 0) <> 2
  
	INSERT INTO STOCKCOUNTING
	(
		STOCKCOUNTINGID
		,BRANCHID
		,CREATEDBY
		,CREATEDDATE
		,UPDATEDBY
		,UPDATEDDATE
		,DELETEDBY
		,DELETEDDATE
		,STATUS
		,STOCKLOCATIONID
	)  
	SELECT 
		STOCKCOUNTINGID
		,BRANCHID
		,CREATEDBY
		,CREATEDDATE
		,UPDATEDBY
		,UPDATEDDATE
		,DELETEDBY
		,DELETEDDATE
		,STATUS
		,STOCKLOCATIONID
	FROM @StockCounting SC
	WHERE NOT EXISTS  
	(  
		SELECT 1 FROM STOCKCOUNTING SCINNER 
		WHERE SCINNER.STOCKCOUNTINGID = SC.STOCKCOUNTINGID 
	)  
END
GO
