/****** Object:  StoredProcedure [dbo].[USP_TMP_IP]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[USP_TMP_IP]

AS
BEGIN

	SELECT I.ITEMID, I.SKUCODE, I.ITEMNAME, I.ISOPENITEM, IC.ITEMCODE, IC.HSNCODE, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, GST.*, IP.CREATEDDATE, IP.DELETEDDATE 
	FROM 
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
	WHERE 
		IP.BRANCHID IS NULL AND (IP.DELETEDDATE IS NULL OR IP.DELETEDDATE > '2025-04-01')
		AND IP.ITEMCODEID NOT IN (111913, 111914, 8959, 111912) AND MRP < 1000
		
	SELECT I.ITEMID, I.SKUCODE, I.ITEMNAME, I.ISOPENITEM, IC.ITEMCODE, IC.HSNCODE, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, GST.*, IP.CREATEDDATE, IP.DELETEDDATE 
	FROM 
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
	WHERE 
		IP.BRANCHID IS NULL AND (IP.DELETEDDATE IS NULL OR IP.DELETEDDATE > '2025-04-01')
		AND IP.ITEMPRICEID IN (202216, 202217, 202218)

	SELECT I.ITEMID, I.SKUCODE, I.ITEMNAME, I.ISOPENITEM, IC.ITEMCODE, IC.HSNCODE, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, GST.*, IP.CREATEDDATE, IP.DELETEDDATE 
	FROM 
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
	WHERE 
		IP.BRANCHID IS NULL AND (IP.DELETEDDATE IS NULL OR IP.DELETEDDATE > '2025-04-01')
		AND IP.ITEMPRICEID IN (174710, 191851)

	SELECT I.ITEMID, I.SKUCODE, I.ITEMNAME, I.ISOPENITEM, IC.ITEMCODE, IC.HSNCODE, IP.ITEMPRICEID, IP.MRP, IP.SALEPRICE, GST.*, IP.CREATEDDATE, IP.DELETEDDATE 
	FROM 
		ITEMPRICE IP
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN GSTDETAIL GST ON GST.GSTID = IP.GSTID
	WHERE 
		IP.BRANCHID IS NULL AND (IP.DELETEDDATE IS NULL OR IP.DELETEDDATE > '2025-04-01')
		AND I.ITEMNAME LIKE '%MILLET%'

	SELECT USERID, USERNAME, FULLNAME, BRANCHID, CREATEDDATE, DELETEDDATE
	FROM TBLUSER
	--WHERE CREATEDDATE < '2026-04-01' AND (DELETEDDATE IS NULL OR DELETEDDATE > '2025-04-01')
		
END

