/****** Object:  StoredProcedure [dbo].[USP_U_ADDBULKPROCESSSING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_U_ADDBULKPROCESSSING]
(
	@ADDBULKPROCESSINGID INT
	, @UserID INT
)
AS
BEGIN

	IF EXISTS ( SELECT 1 FROM ADDBULKPROCESSING WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID AND STATUS = 1 )
	BEGIN
		SELECT 'Bulk processing is already submitted, Operation has been cancelled!!'
		RETURN
	END

	IF EXISTS ( SELECT 1 FROM ADDBULKPROCESSING WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID AND DELETEDDATE IS NOT NULL )
	BEGIN
		SELECT 'Bulk processing is already deleted, Operation has been cancelled!!'
		RETURN
	END

	DECLARE @WarehouseID INT = 45, @StockAdjustmentTypeID INT

	SELECT @StockAdjustmentTypeID = STOCKADJUSTMENTTYPEID FROM STOCKADJUSTMENTTYPE WHERE STOCKADJUSTMENTTYPE = 'Processing'

	--SELECT ITEMPRICEID, SUM(QUANTITY) QUANTITY, SUM(WEIGHTINKGS) WEIGHTINKGS, SUM(PREVQUANTITY) PREVQUANTITY
	--	, SUM(PREVWEIGHTINKGS) PREVWEIGHTINKGS, ISPARENTITEM
	--INTO #ADJS
	--FROM
	--	(
	--		SELECT ABPD.ITEMPRICEID, SS.QUANTITY + (CASE WHEN I.ISOPENITEM = 1 THEN 0 ELSE ABPD.QUANTITY END) AS QUANTITY
	--			, SS.WEIGHTINKGS + (CASE WHEN I.ISOPENITEM = 1 THEN ABPD.WEIGHTINKGS ELSE 0 END) AS WEIGHTINKGS
	--			, SS.QUANTITY PREVQUANTITY, SS.WEIGHTINKGS PREVWEIGHTINKGS, 0 AS ISPARENTITEM
	--		FROM 
	--			ADDBULKPROCESSINGDETAIL ABPD
	--			INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = ABPD.ITEMPRICEID AND SS.BRANCHID = @WarehouseID
	--			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ABPD.ITEMPRICEID
	--			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	--			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	--		WHERE ABPD.DELETEDDATE IS NULL AND ABPD.ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID

	--		UNION ALL

	--		SELECT PIC.MAXITEMPRICEID, SS.QUANTITY
	--			, SS.WEIGHTINKGS - ((CASE WHEN I.ISOPENITEM = 1 THEN ABPD.WEIGHTINKGS ELSE ABPD.QUANTITY END) * UOM.MULTIPLIER)
	--			, SS.QUANTITY, SS.WEIGHTINKGS, 1
	--		FROM 
	--			ADDBULKPROCESSINGDETAIL ABPD
	--			INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ABPD.ITEMPRICEID
	--			INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
	--			INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	--			INNER JOIN UOM UOM ON UOM.UOMID = I.UOMID
	--			INNER JOIN
	--				(
	--					SELECT PIC.ITEMID, MAX(PIP.ITEMPRICEID) MAXITEMPRICEID
	--					FROM 
	--						ITEMCODE PIC 
	--						INNER JOIN ITEMPRICE PIP ON PIP.ITEMCODEID = PIC.ITEMCODEID AND PIP.DELETEDDATE IS NULL
	--					GROUP BY PIC.ITEMID
	--				) PIC ON PIC.ITEMID = I.PARENTITEMID
	--			INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = PIC.MAXITEMPRICEID AND SS.BRANCHID = @WarehouseID
	--		WHERE ABPD.DELETEDDATE IS NULL AND ABPD.ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID
	--	) ADJS
	--GROUP BY ITEMPRICEID, ISPARENTITEM


	SELECT SS.ITEMPRICEID
		, SS.QUANTITY + (SUM(ADJS.QUANTITY) * (CASE WHEN ISPARENTITEM = 0 THEN 1 ELSE -1 END)) QUANTITY
		, SS.WEIGHTINKGS + (SUM(ADJS.WEIGHTINKGS) * (CASE WHEN ISPARENTITEM = 0 THEN 1 ELSE -1 END)) WEIGHTINKGS
		, SS.QUANTITY PREVQUANTITY, SS.WEIGHTINKGS PREVWEIGHTINKGS, ISPARENTITEM
	INTO #ADJS
	FROM
		(
			SELECT ABPD.ITEMPRICEID, 0 AS ISPARENTITEM
				, (CASE WHEN I.ISOPENITEM = 1 THEN 0 ELSE ABPD.QUANTITY END) AS QUANTITY
				, (CASE WHEN I.ISOPENITEM = 1 THEN ABPD.WEIGHTINKGS ELSE 0 END) AS WEIGHTINKGS				
			FROM 
				ADDBULKPROCESSINGDETAIL ABPD
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ABPD.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
			WHERE ABPD.DELETEDDATE IS NULL AND ABPD.ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID

			UNION ALL

			SELECT PIC.MAXITEMPRICEID, 1, 0 AS QUANTITY
				, (CASE WHEN I.ISOPENITEM = 1 THEN ABPD.WEIGHTINKGS ELSE ABPD.QUANTITY END) * UOM.MULTIPLIER				
			FROM 
				ADDBULKPROCESSINGDETAIL ABPD
				INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ABPD.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
				INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
				INNER JOIN UOM UOM ON UOM.UOMID = I.UOMID
				INNER JOIN
					(
						SELECT PIC.ITEMID, MAX(PIP.ITEMPRICEID) MAXITEMPRICEID
						FROM 
							ITEMCODE PIC 
							INNER JOIN ITEMPRICE PIP ON PIP.ITEMCODEID = PIC.ITEMCODEID 
						WHERE PIP.BRANCHID IS NULL AND PIP.DELETEDDATE IS NULL
						GROUP BY PIC.ITEMID
					) PIC ON PIC.ITEMID = I.PARENTITEMID
			WHERE ABPD.DELETEDDATE IS NULL AND ABPD.ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID
		) ADJS
		INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = ADJS.ITEMPRICEID AND SS.BRANCHID = @WarehouseID
	GROUP BY SS.ITEMPRICEID, ISPARENTITEM, SS.QUANTITY, SS.WEIGHTINKGS

	INSERT INTO STOCKADJUSTMENT(ITEMPRICEID, BRANCHID, QUANTITY, WEIGHTINKGS, CREATEDBY, CREATEDDATE, PREVQUANTITY, PREVWEIGHTINKGS, STOCKADJUSTMENTTYPEID)
	SELECT ITEMPRICEID, @WarehouseID, QUANTITY, WEIGHTINKGS, @UserID, GETDATE(), PREVQUANTITY, PREVWEIGHTINKGS, @StockAdjustmentTypeID
	FROM #ADJS

	UPDATE SS
	SET SS.QUANTITY = ABPD.QUANTITY, SS.WEIGHTINKGS = ABPD.WEIGHTINKGS, SS.TTYPE = 'SA', SS.MODIFIEDDATE = GETDATE()
	FROM
		#ADJS ABPD
		INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = ABPD.ITEMPRICEID AND SS.BRANCHID = @WarehouseID
	WHERE ABPD.ISPARENTITEM = 0

	UPDATE SS
	SET SS.WEIGHTINKGS = ABPD.WEIGHTINKGS, SS.TTYPE = 'SA', SS.MODIFIEDDATE = GETDATE()
	FROM 
			#ADJS ABPD			
			INNER JOIN STOCKSUMMARY SS ON SS.ITEMPRICEID = ABPD.ITEMPRICEID AND SS.BRANCHID = @WarehouseID
	WHERE ABPD.ISPARENTITEM = 1

	UPDATE ADDBULKPROCESSING SET STATUS = 1, UPDATEDBY = @UserID, UPDATEDDATE = GETDATE() WHERE ADDBULKPROCESSINGID = @ADDBULKPROCESSINGID

	SELECT @ADDBULKPROCESSINGID

END
GO
