/****** Object:  StoredProcedure [dbo].[USP_U_BREFUND_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_BREFUND_1]            
@dtbrd POS_BRDTYPE_1 readonly,        
@BRID INT,        
@USERID INT        
          
AS            
BEGIN

	IF EXISTS
	(
		SELECT 1 FROM POS_BREFUND SD 			
		WHERE BRID = @BRID
			AND ISNULL(SD.STATUS, 0) = 0
			AND DELETEDDATE IS NULL
	)
	BEGIN
		RAISERROR('Branch refund not yet submitted', 16, 1)
		RETURN
	END

	IF EXISTS
	(
		SELECT 1 FROM POS_BREFUND SD 			
		WHERE SD.BRID = @BRID
			AND ISNULL(SD.IsAccepted, 0) = 1 
			AND DELETEDDATE IS NULL
	)
	BEGIN
		RAISERROR('Branch refund already accepted', 16, 1)
		RETURN
	END

	DECLARE @BRANCHID INT, @SUBMITDATE DATETIME = GETDATE()
	SELECT @BRANCHID = BRANCHID FROM POS_BREFUND WHERE BRID = @BRID

		--Change BRefund status to accepted      
		UPDATE POS_BREFUND SET         
			IsAccepted = 1,        
			ACCEPTEDBY = @USERID,        
			ACCEPTEDDATE = @SUBMITDATE
		WHERE BRID = @BRID
			AND DELETEDDATE IS NULL

		-- Add rejected item quantity to base branch
		UPDATE SS 
		SET 
			SS.QUANTITY = SS.QUANTITY + UBRD.REFUNDQUANTITY,    
			SS.WEIGHTINKGS = SS.WEIGHTINKGS + UBRD.REFUNDWEIGHTINKGS,
			SS.TTYPE =  'BR', SS.MODIFIEDDATE = GETDATE()
		FROM STOCKSUMMARY SS 
			INNER JOIN 
			(
				SELECT ISNULL(PIP.STOCKMOVETOID, PIP.ITEMPRICEID) AS ITEMPRICEID
					, SUM(BRD.QUANTITY) AS REFUNDQUANTITY
					, SUM(BRD.WEIGHTINKGS) AS REFUNDWEIGHTINKGS
				FROM 
					POS_BREFUNDDETAIL BRD 
					INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = BRD.ITEMPRICEID
					INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
				WHERE BRD.BRID = @BRID
					AND BRD.DELETEDDATE IS NULL
					AND BRD.REASONID = 5
				GROUP BY ISNULL(PIP.STOCKMOVETOID, PIP.ITEMPRICEID)
			) UBRD ON SS.ITEMPRICEID = UBRD.ITEMPRICEID
		WHERE SS.BRANCHID = @BRANCHID


		--Adding items Quantity and Weight in Kgs to D & E branch of Damaged and Expired items for all categories except child items
		UPDATE SS 
		SET 
			SS.QUANTITY = ISNULL(SS.QUANTITY, 0) + BRD.QUANTITY,
			SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS, 0) + BRD.WEIGHTINKGS,
			SS.TTYPE =  'BR',
			MODIFIEDDATE = @SUBMITDATE
		FROM STOCKSUMMARY SS 
			INNER JOIN          
			(
				SELECT 
					ISNULL(PIP.STOCKMOVETOID, PIP.ITEMPRICEID) AS ITEMPRICEID
					, SUM(QUANTITY) AS QUANTITY
					, SUM(WEIGHTINKGS) AS WEIGHTINKGS
					, ROR.LOCATIONTOMOVESTOCK
				FROM @dtbrd BRD     
					INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID          
					INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
					INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID          
					INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID     
					INNER JOIN REASONFORREFUND ROR ON BRD.REASONID = ROR.REASONID
				WHERE (I.PARENTITEMID IS NULL OR ISOPENITEM = 1 OR ROR.MERGETOPARENT = 0)
					AND BRD.REASONID <> 5
				GROUP BY ROR.LOCATIONTOMOVESTOCK, ISNULL(PIP.STOCKMOVETOID, PIP.ITEMPRICEID)
			) BRD ON SS.BRANCHID = BRD.LOCATIONTOMOVESTOCK AND SS.ITEMPRICEID = BRD.ITEMPRICEID

		--Adding child items weight in kgs to parent in case of damege and expired 
		SELECT BRD.QUANTITY * U.MULTIPLIER AS WEIGHTINKGS, PIP.ITEMPRICEID AS PARENTITEMPRICEID, BRD.LOCATIONTOMOVESTOCK
		INTO #BRD 
		FROM 
			(
				SELECT A.PARENTITEMID ,SUM(A.QUANTITY) AS QUANTITY, A.UOMID, A.LOCATIONTOMOVESTOCK FROM 
				(
					SELECT 
						ISNULL(PIP.STOCKMOVETOID, PIP.ITEMPRICEID) AS ITEMPRICEID , 
						QUANTITY AS QUANTITY, 
						I.PARENTITEMID, 
						I.UOMID,
						ROR.LOCATIONTOMOVESTOCK
					FROM @dtbrd BRD     
						INNER JOIN ITEMPRICE IP ON BRD.ITEMPRICEID = IP.ITEMPRICEID          
						INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID          
						INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID 
						INNER JOIN ITEMPRICE PIP ON PIP.ITEMPRICEID = ISNULL(IP.PARENTITEMPRICEID, IP.ITEMPRICEID)
						INNER JOIN REASONFORREFUND ROR ON BRD.REASONID = ROR.REASONID AND ROR.MERGETOPARENT = 1
					WHERE I.PARENTITEMID IS NOT NULL AND ISNULL(I.ISOPENITEM, 0) = 0 AND BRD.REASONID <> 5
				) AS A 
				GROUP BY A.PARENTITEMID,A.UOMID, A.LOCATIONTOMOVESTOCK
			) BRD 
			INNER JOIN ITEM PITEM ON BRD.PARENTITEMID = PITEM.ITEMID        
			INNER JOIN ITEMCODE PIC ON PITEM.ITEMID = PIC.ITEMID
			INNER JOIN 
			(
				SELECT IC.ITEMCODEID,MAX(ISNULL(IP.STOCKMOVETOID,IP.ITEMPRICEID)) AS ITEMPRICEID 
				FROM ITEMPRICE IP
					INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
					INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
				WHERE IP.DELETEDDATE IS NULL 
					AND ISNULL(I.ISOPENITEM,0) = 1
					AND ISNULL(PARENTITEMPRICEID, 0) = 0
				GROUP BY IC.ITEMCODEID
			) PIP ON PIC.ITEMCODEID = PIP.ITEMCODEID
			LEFT JOIN UOM U ON BRD.UOMID = U.UOMID

		UPDATE SS      
		SET 
			SS.QUANTITY = SS.QUANTITY,
			SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS,0) + ISNULL(BRD.WEIGHTINKGS, 0),
			SS.TTYPE = 'BR', SS.MODIFIEDDATE = @SUBMITDATE
		FROM 
			STOCKSUMMARY SS    
			INNER JOIN  #BRD BRD ON SS.BRANCHID = BRD.LOCATIONTOMOVESTOCK AND SS.ITEMPRICEID = BRD.PARENTITEMPRICEID

		SELECT @BRID
END
GO
