/****** Object:  StoredProcedure [dbo].[USP_U_FREEZESUPPLIERRETURNS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_FREEZESUPPLIERRETURNS]
@SUPPLIERRETURNSID INT,
@USERID INT
AS
BEGIN

	BEGIN TRY                                          
	BEGIN TRAN                                          

		UPDATE SS        
		SET 
			SS.QUANTITY = ISNULL(SS.QUANTITY, 0) - SDD.QUANTITY,        
			SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS, 0) - SDD.WEIGHTINKGS,
			SS.TTYPE = 'SR', SS.MODIFIEDDATE = GETDATE()
		FROM 
			STOCKSUMMARY SS        
			INNER JOIN          
				(
					SELECT           
						ICP.ITEMPRICEID, SUM(SRD.QUANTITY) AS QUANTITY, SUM(SRD.WEIGHTINKGS) AS WEIGHTINKGS
					FROM
						SUPPLIERRETURNSDETAIL SRD
						INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
					WHERE 
						SRD.SUPPLIERRETURNSID = @SupplierReturnsID 
						AND ISNULL(BRDID, 0) = 0 
						AND ISNULL(Isfreezed, 0) = 0
						AND SRD.DELETEDDATE IS NULL
					GROUP BY ICP.ITEMPRICEID
				) SDD ON SS.ITEMPRICEID = SDD.ITEMPRICEID
		WHERE SS.BRANCHID = 100

		UPDATE SUPPLIERRETURNS 
		SET 
			STATUS = 2, 
			CNINITIATEDBY = @USERID, 
			CNINITIATEDDATE = GETDATE()
		WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID

		SELECT @SUPPLIERRETURNSID

		COMMIT TRAN                                          
		 END TRY                                          
		 BEGIN CATCH                                          
		 SELECT ERROR_MESSAGE() AS ErrorMessage                                           
				IF(@@TRANCOUNT > 0)                                          
		   ROLLBACK TRAN                                          
		 END CATCH                                         
END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_GENERATEDEBITNOTE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_GENERATEDEBITNOTE]
@SUPPLIERRETURNSID INT,
@USERID INT
AS
BEGIN

	IF NOT EXISTS (SELECT 1 FROM SUPPLIERRETURNS WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID AND ISNULL(STATUS,0) = 0)
	BEGIN
		SELECT 'Cannot initiate credit note which is already generated.'
		return;
	END

	DECLARE @BRANCHID INT
	SELECT @BRANCHID = BRANCHID FROM SUPPLIERRETURNS WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID

	BEGIN TRY                                          
	BEGIN TRAN                                          

		UPDATE SS        
		SET 
			SS.QUANTITY = ISNULL(SS.QUANTITY, 0) - SDD.QUANTITY,        
			SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS, 0) - SDD.WEIGHTINKGS,
			SS.TTYPE = 'SR', SS.MODIFIEDDATE = GETDATE()
		FROM 
			STOCKSUMMARY SS        
			INNER JOIN          
				(
					SELECT           
						ICP.ITEMPRICEID, SUM(SRD.QUANTITY) AS QUANTITY, SUM(SRD.WEIGHTINKGS) AS WEIGHTINKGS
					FROM
						SUPPLIERRETURNSDETAIL SRD
						INNER JOIN ITEMCOSTPRICE ICP ON ICP.ITEMCOSTPRICEID = SRD.ITEMCOSTPRICEID
					WHERE 
						SRD.SUPPLIERRETURNSID = @SupplierReturnsID 
						AND SRD.DELETEDDATE IS NULL
					GROUP BY ICP.ITEMPRICEID
				) SDD ON SS.ITEMPRICEID = SDD.ITEMPRICEID
		WHERE SS.BRANCHID = @BRANCHID

		UPDATE SUPPLIERRETURNS 
		SET 
			STATUS = 1, 
			CNINITIATEDBY = @USERID, 
			CNINITIATEDDATE = GETDATE()
		WHERE SUPPLIERRETURNSID = @SUPPLIERRETURNSID

		EXEC USP_R_SUPPLIERDEBITNOTE @SUPPLIERRETURNSID

		COMMIT TRAN                                          
		 END TRY                                          
		 BEGIN CATCH                                          
		 SELECT ERROR_MESSAGE() AS ErrorMessage                                           
				IF(@@TRANCOUNT > 0)                                          
		   ROLLBACK TRAN                                          
		 END CATCH                                         
END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_INITIATESTOCKCOUNTING]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_INITIATESTOCKCOUNTING]
@BRANCHID INT,
@USERID INT
AS
BEGIN

	IF EXISTS(SELECT 1 FROM STOCKCOUNTING WHERE (ISNULL(STATUS,0) = 0 OR ISNULL(STATUS,0) = 1) AND BRANCHID = @BRANCHID AND DELETEDDATE IS NULL)
	BEGIN
		SELECT 'There are few sheets which are in draft and submit state, Please discard or accept the same.'
		return;
	END

	IF EXISTS ( SELECT 1 FROM POS_BREFUND BR WHERE BR.BRANCHID = @BRANCHID AND BR.DELETEDDATE IS NULL AND ISNULL(BR.IsAccepted, 0) <> 1 )
	BEGIN
		SELECT 'There are few branch refund sheets which are in draft and submit state, Please discard or accept the same.'
		return;
	END

	UPDATE STOCKCOUNTING SET STATUS = 3,ArchivedDate = GETDATE(), ArchivedBy = @USERID WHERE BRANCHID = @BRANCHID AND ISNULL(STATUS,0) = 2
	UPDATE BRANCH SET ENABLESTOCKCOUNTING = 1, UPDATEDBY = @USERID, UPDATEDATE = GETDATE() WHERE BRANCHID = @BRANCHID

	select @BRANCHID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_ITEM_ADDITIONAL_FIELDS]    Script Date: 17-10-2026 13:04:47 ******/
