CREATE PROC [dbo].[USP_U_ITEM_ADDITIONAL_FIELDS]
(
    @ItemID INT,
    @SupplietIndentItemTypeID INT = NULL,
    @InnerCaseQty INT = NULL,
    @OuterCaseQty INT = NULL,
    @ProductRank DECIMAL(18, 2) = NULL,
    @BrandID INT = NULL,
    @ManufacturerID INT = NULL,
    @RefundPathID INT = NULL,
    @UserID INT
)
AS
BEGIN
    UPDATE I
    SET 
        I.SUPPLIERINDENTITEMTYPEID = @SupplietIndentItemTypeID,
        I.INNERCASEQTY = @InnerCaseQty,
        I.OUTERCASEQTY = @OuterCaseQty,
        I.PRODUCTRANK = @ProductRank,
        I.BRANDID = ISNULL(@BrandID, I.BRANDID),
		I.MANUFACTURERID = ISNULL(@ManufacturerID, I.MANUFACTURERID),
		I.REFUNDPATHID = ISNULL(@RefundPathID, I.REFUNDPATHID),
        I.UPDATEDBY = @UserID,
        I.UPDATEDATE = GETDATE()
    FROM ITEM I 
    WHERE I.ITEMID = @ItemID
END
