/****** Object:  StoredProcedure [dbo].[USP_U_LIQUIDATION]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_U_LIQUIDATION]
(
	@LiquidationID INT
	, @Status INT
	, @LiquidationSalePrice DECIMAL(18, 2)
	, @StatusDescription VARCHAR(MAX) = ''	
	, @UserID INT
)
AS
BEGIN

	IF @LiquidationID <= 0
	BEGIN
		PRINT 'error - Invalid liquidation ID'
		RETURN
	END

	IF NOT EXISTS( SELECT 1 FROM LIQUIDATION WHERE LIQUIDATIONID = @LiquidationID AND STATUS = 0 AND DELETEDDATE IS NULL)
	BEGIN
		
		PRINT 'error - liquidation not found, it could be either deleted, approved or rejected'
		RETURN

	END

	IF @Status = 0
	BEGIN

		UPDATE LIQUIDATION
		SET
			LIQUIDATIONSALEPRICE = @LiquidationSalePrice			
			, UPDATEDBY = @UserID
			, UPDATEDDATE = GETDATE()
		WHERE LIQUIDATIONID = @LiquidationID

		PRINT 'info - Liquidation Sale Price updated sucessfully'
		RETURN
	END

	IF @Status = 2
	BEGIN
		
		UPDATE LIQUIDATION
		SET
			STATUS = @Status
			, STATUSDESCRIPTION = @StatusDescription
			, STATUSCHANGEDBY = @UserID
			, STATUSCHANGEDDATE = GETDATE()
		WHERE LIQUIDATIONID = @LiquidationID

		PRINT 'info - Rejected sucessfully'
		RETURN

	END

	IF @Status = 1
	BEGIN

		IF ISNULL(@LiquidationSalePrice, 0) = 0
		BEGIN
			
			PRINT 'error - Liquidation sale price is empty'
			RETURN

		END

		DECLARE @ItemID INT, @SKUCode VARCHAR(20), @ItemPriceID INT, @BranchQtyOrQghtInKGs DECIMAL(18, 2)
			, @LiquidationQtyOrQghtInKGs DECIMAL(18, 2), @RunningSaleQtyOrQghtInKGs DECIMAL(18, 2)
			, @IsOpenItem BIT, @BranchID INT, @DiscountedEANCode VARCHAR(20), @HSNCode VARCHAR(10)
			, @DiscountedItemCodeID INT, @MRP DECIMAL(18, 2), @NewItemPriceID INT, @GSTID INT, @StockMoveToID INT

		SELECT 
			@ItemID = I.ITEMID, @SKUCode = I.SKUCODE, @ItemPriceID = ISNULL(IP.STOCKMOVETOID, LQ.ITEMPRICEID)
			, @BranchQtyOrQghtInKGs = CASE WHEN I.ISOPENITEM = 1 THEN SS.WEIGHTINKGS ELSE SS.QUANTITY END
			, @LiquidationQtyOrQghtInKGs = LQ.QTYORWGHTINKGS, @IsOpenItem = I.ISOPENITEM, @BranchID = LQ.BRANCHID
			, @HSNCode = IC.HSNCODE, @MRP = IP.MRP, @GSTID = IP.GSTID
		FROM
			LIQUIDATION LQ WITH(NOLOCK)
			INNER JOIN ITEMPRICE IP WITH(NOLOCK) ON IP.ITEMPRICEID = LQ.ITEMPRICEID
			INNER JOIN ITEMCODE IC WITH(NOLOCK) ON IC.ITEMCODEID = IP.ITEMCODEID
			INNER JOIN ITEM I WITH(NOLOCK) ON I.ITEMID = IC.ITEMID
			INNER JOIN STOCKSUMMARY SS WITH(NOLOCK) ON SS.ITEMPRICEID = ISNULL(IP.STOCKMOVETOID, LQ.ITEMPRICEID) 
				AND SS.BRANCHID = LQ.BRANCHID
		WHERE LQ.LIQUIDATIONID = @LiquidationID

		IF @LiquidationQtyOrQghtInKGs > @BranchQtyOrQghtInKGs
		BEGIN
			
			PRINT 'error - Branch stock is less than given liquidation stock'
			RETURN

		END

		SELECT @RunningSaleQtyOrQghtInKGs = CASE WHEN @IsOpenItem = 1 THEN SUM(PBD.WEIGHTINKGS) ELSE SUM(PBD.QUANTITY) END
		FROM 
			POS_BILLDETAIL PBD WITH(NOLOCK)
			INNER JOIN BRANCHCOUNTER BC WITH(NOLOCK) ON BC.COUNTERID = PBD.BRANCHCOUNTERID			
		WHERE
			BC.BRANCHID = @BranchID
			AND PBD.ITEMPRICEID = @ItemPriceID
			AND PBD.DELETEDDATE IS NULL
			AND PBD.DAYCLOSUREID IS NULL

		IF @LiquidationQtyOrQghtInKGs > @BranchQtyOrQghtInKGs - ISNULL(@RunningSaleQtyOrQghtInKGs, 0)
		BEGIN
			
			PRINT 'error - Branch stock after running sale qty is less than given liquidation stock'
			RETURN

		END

		PRINT 'info - building discount EAN code'

		SELECT @DiscountedEANCode = 'V' + I.SKUCODE + '_' + CAST(@LiquidationSalePrice AS VARCHAR(20))
		FROM ITEM I 
		WHERE I.ITEMID = @ItemID
		
		PRINT 'info - discount EAN code : ' + @DiscountedEANCode

		IF NOT EXISTS (SELECT 1 FROM ITEMCODE IC WHERE IC.ITEMCODE = @DiscountedEANCode)
		BEGIN

			PRINT 'info - discounted EAN code does not exists, creating EAN code : ' + @DiscountedEANCode
			INSERT INTO ITEMCODE(ITEMID, ITEMCODE, ISEAN, HSNCODE, CREATEDBY, CREATEDDATE, IsDSCode)
			SELECT @ItemID, @DiscountedEANCode, 1, @HSNCode, @UserID, GETDATE(), 1 
			
			PRINT 'info - created EAN code : ' + @DiscountedEANCode

		END

		SELECT @DiscountedItemCodeID = IC.ITEMCODEID FROM ITEMCODE IC WHERE IC.ITEMCODE = @DiscountedEANCode

		IF NOT EXISTS (SELECT 1 FROM ITEMPRICE IP WHERE IP.ITEMCODEID = @DiscountedItemCodeID AND IP.MRP = @MRP AND DELETEDDATE IS NULL AND BRANCHID IS NULL)
		BEGIN

			PRINT 'info - discounted EAN code does not have given MRP, creating MRP : ' + CAST(@MRP AS VARCHAR(20))
			INSERT INTO ITEMPRICE(ITEMCODEID, MRP, SALEPRICE, GSTID, CREATEDBY, CREATEDDATE)
			SELECT @DiscountedItemCodeID, @MRP, @LiquidationSalePrice, @GSTID, @UserID, GETDATE()
			
			PRINT 'info - created Item price: ' + CAST(@MRP AS VARCHAR(20))

		END

		SELECT @NewItemPriceID = IP.ITEMPRICEID FROM ITEMPRICE IP WHERE IP.ITEMCODEID = @DiscountedItemCodeID AND IP.MRP = @MRP AND DELETEDDATE IS NULL AND BRANCHID IS NULL

		PRINT 'info - creating cost prices'

		INSERT INTO ITEMCOSTPRICE(ITEMPRICEID, COSTPRICEWT, COSTPRICEWOT, QUANTITY, GSTID, CREATEDBY, CREATEDDATE, GROSSCOSTPRICEWT, GROSSCOSTPRICEWOT)
		SELECT TOP 1 @NewItemPriceID, ICP.COSTPRICEWT, ICP.COSTPRICEWOT, @LiquidationQtyOrQghtInKGs, @GSTID, @UserID, GETDATE(), ICP.GROSSCOSTPRICEWT, ICP.GROSSCOSTPRICEWOT
		FROM ITEMCOSTPRICE ICP
		WHERE 
			ICP.ITEMPRICEID = @ItemPriceID
			AND ICP.DELETEDDATE IS NULL			
		ORDER BY ICP.ITEMCOSTPRICEID DESC

		PRINT 'info - creating stock move'

		DECLARE @STOCKMOVEIDTable TABLE (NewID INT);

		INSERT INTO STOCKMOVE(OLDITEMPRICEID, NEWITEMPRICEID, STOCKADJUSTMENTTYPEID, CREATEDBY, CREATEDDATE, BRANCHID, DEDUCTEDQUANTITY, ADDEDQUANTITY, DEDUCTEDWEIGHTINKGS, ADDEDWEIGHTINKGS)
		OUTPUT inserted.STOCKMOVEID INTO @STOCKMOVEIDTable  -- <--- This captures the REAL ID
		SELECT @ItemPriceID, @NewItemPriceID, 7, @UserID, GETDATE(), @BranchID
			, CASE WHEN @IsOpenItem = 1 THEN NULL ELSE @LiquidationQtyOrQghtInKGs END
			, CASE WHEN @IsOpenItem = 1 THEN NULL ELSE @LiquidationQtyOrQghtInKGs END
			, CASE WHEN @IsOpenItem = 1 THEN @LiquidationQtyOrQghtInKGs ELSE NULL END
			, CASE WHEN @IsOpenItem = 1 THEN @LiquidationQtyOrQghtInKGs ELSE NULL END

		SELECT TOP 1 @StockMoveToID = NewID FROM @STOCKMOVEIDTable;
		
		UPDATE LIQUIDATION
		SET
			STATUS = @Status
			, STATUSDESCRIPTION = @StatusDescription
			, STATUSCHANGEDBY = @UserID
			, STATUSCHANGEDDATE = GETDATE()
			, NEWITEMPRICEID = @NewItemPriceID
			, LIQUIDATIONSALEPRICE = @LiquidationSalePrice
			, STOCKMOVEID = @StockMoveToID
		WHERE LIQUIDATIONID = @LiquidationID
				
		PRINT 'info - Approved successfully'

	END


END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_MARK_PICKLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_U_MARK_PICKLIST]
(
	@PickListID INT,
	@PickListBranchID INT = NULL,
	@UserID INT
)
AS
BEGIN

	DECLARE @GeneratedStatus INT, @SeggregatedStatus INT

	SELECT @GeneratedStatus = EL.ENUMID
	FROM ENUMLIST EL
	WHERE EL.ENUMTYPE = 'Picklist Status' AND EL.ENUMVALUE = 'Generated'

	SELECT @SeggregatedStatus = EL.ENUMID
	FROM ENUMLIST EL
	WHERE EL.ENUMTYPE = 'Picklist Status' AND EL.ENUMVALUE = 'Seggregated'

	IF EXISTS 
	(
		SELECT 1
		FROM PICKLIST PL
		WHERE PL.PICKLISTID = @PickListID AND PL.PICKLISTSTATUS <> @GeneratedStatus
	)
	BEGIN
		SELECT 'Picklist status is not generated, seggregation might have been already completed'
		RETURN
	END

	IF @PickListBranchID IS NOT NULL
	BEGIN

		IF NOT EXISTS
		(	
			SELECT 1 FROM PICKLISTBRANCH PLB
			WHERE PLB.PICKLISTBRANCHID = @PickListBranchID AND PLB.PICKEDSTATUS = @GeneratedStatus
		)
		BEGIN
			SELECT 'Picklist Branch status is not generated, seggregation might have been already completed'
			RETURN
		END

		UPDATE PLB
		SET PLB.PICKEDSTATUS = @SeggregatedStatus, UPDATEDBY = @UserID, UPDATEDDATE = GETDATE()
		FROM PICKLISTBRANCH PLB
		WHERE PLB.PICKLISTBRANCHID = @PickListBranchID

		-- verify if no other branches are in generated state after current branch is updated
		-- then safely move pick list to seggregated state as well
		IF EXISTS 
		(
			SELECT 1 
			FROM
				PICKLIST PL 
			WHERE 
				PL.PICKLISTSTATUS = @GeneratedStatus
				AND PL.PICKLISTID = @PickListID
				AND NOT EXISTS 
				(
					SELECT 1
					FROM PICKLISTBRANCH PLB
					WHERE PLB.PICKLISTID = PL.PICKLISTID AND PLB.PICKEDSTATUS = @GeneratedStatus
				)
		)
		BEGIN
			
			UPDATE PL
			SET PL.PICKLISTSTATUS = @SeggregatedStatus
			FROM PICKLIST PL
			WHERE PL.PICKLISTID = @PickListID

		END
	END
	ELSE
	BEGIN

		UPDATE PL
		SET PL.PICKLISTSTATUS = @SeggregatedStatus, UPDATEDBY = @UserID, UPDATEDDATE = GETDATE()
		FROM PICKLIST PL
		WHERE PL.PICKLISTID = @PickListID

		UPDATE PLB
		SET PLB.PICKEDSTATUS = @SeggregatedStatus, UPDATEDBY = @UserID, UPDATEDDATE = GETDATE()
		FROM PICKLISTBRANCH PLB
		WHERE PLB.PICKLISTID = @PickListID
			AND PLB.PICKEDSTATUS = @GeneratedStatus -- Only update generated status to seggregated,
			-- if any branch is already seggregated or even dispatched, then ignore it

	END

	SELECT ISNULL(@PickListBranchID, @PickListID) ID
END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_MOVESUPPLIERRETURNS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_MOVESUPPLIERRETURNS]
@SUPPLIERID INT,
@USERID INT,
@dt dtInts readonly
AS
BEGIN

	INSERT INTO SUPPLIERRETURNS(SUPPLIERID,CREATEDBY,CREATEDDATE,STATUS,CATEGORYID)
	select DISTINCT @SUPPLIERID,@USERID,GETDATE(),0, I.CATEGORYID FROM SUPPLIERRETURNSDETAIL SRD
		INNER JOIN @dt USRD ON SRD.SUPPLIERRETURNSDETAILID = USRD.ID
		INNER JOIN ITEMCOSTPRICE ICP ON SRD.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
	WHERE NOT EXISTS (SELECT 1 FROM SUPPLIERRETURNS SRINNER WHERE I.CATEGORYID = SRINNER.CATEGORYID AND SRINNER.SUPPLIERID = @SUPPLIERID AND ISNULL(STATUS,0) = 0)

	UPDATE SRD SET SRD.SUPPLIERRETURNSID = SR.SUPPLIERRETURNSID
	FROM SUPPLIERRETURNSDETAIL SRD
		INNER JOIN @dt USRD ON SRD.SUPPLIERRETURNSDETAILID = USRD.ID
		INNER JOIN ITEMCOSTPRICE ICP ON SRD.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = ICP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IC.ITEMCODEID = IP.ITEMCODEID
		INNER JOIN ITEM I ON I.ITEMID = IC.ITEMID
		INNER JOIN SUPPLIERRETURNS SR ON I.CATEGORYID = SR.CATEGORYID AND SR.SUPPLIERID = @SUPPLIERID AND ISNULL(SR.STATUS,0) = 0

	select @SUPPLIERID
END

GO
