CREATE PROCEDURE [dbo].[USP_U_PASSWORD]
@USERID INT,    
@PASSWORDSTRING nvarchar(500)    
as    
begin    
    
update TBLUSER set PASSWORDSTRING = @PASSWORDSTRING,  
ISOTP = 0  
where USERID = @USERID
    
SELECT                                
U.USERID,                                
U.USERNAME,                                
U.FULLNAME,                                
U.PASSWORDSTRING
FROM TBLUSER U           
WHERE U.USERID= @USERID
    
end
