/****** Object:  StoredProcedure [dbo].[USP_U_PICKLIST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_U_PICKLIST]
(
	@PickListID INT,
	@UserID INT
)
AS
BEGIN

	IF NOT EXISTS 
		(
			SELECT 1 FROM PICKLIST
			WHERE 
				PICKLISTID = @PickListID
				AND DELETEDDATE IS NULL
				AND PICKEDSTATUS = 0
		)
	BEGIN

		THROW 50001, 'Picklist already submitted, the operation is cancelled', 1
		RETURN
	END

	IF EXISTS
		(
			SELECT 1
			FROM PICKLISTITEM PLI
			WHERE
				PLI.PICKLISTID = @PickListID
				AND PLI.QUANTITY <> PLI.PICKEDQUANTITY
				AND PLI.DELETEDDATE IS NULL
		)
	BEGIN

		THROW 50001, 'One or more items quantity is not picked\arranged into trays, the operation is cancelled', 1
		RETURN

	END

	UPDATE PL
	SET PL.PICKEDSTATUS = 1, PL.UPDATEDBY = @UserID, PL.UPDATEDDATE = GETDATE()
	FROM PICKLIST PL
	WHERE PL.PICKLISTID = @PickListID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_PICKLISTDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROC [dbo].[USP_U_PICKLISTDISPATCH]
(
	@PicklistDispatchID INT
)
AS
BEGIN

	IF NOT EXISTS 
	(
		SELECT 1
		FROM PICKLISTDISPATCH PLD
		WHERE 
			PLD.PICKLISTDISPATCHID = @PicklistDispatchID
			AND PLD.DELETEDDATE IS NULL
			AND PLD.STOCKDISPATCHID IS NULL
	)
	BEGIN
		SELECT 'Picklist dispatch not found\already dispatched or deleted'
		RETURN
	END

	IF NOT EXISTS
	(
		SELECT 1
		FROM
			PICKLISTDISPATCHDETAIL PLDD
		WHERE
			PLDD.DELETEDDATE IS NULL
			AND PLDD.PICKLISTDISPATCHID = @PicklistDispatchID
	)
	BEGIN
		SELECT 'No items to dispatch'
		RETURN
	END

	DECLARE @CategoryID INT, @SubCategoryID INT, @StockDispatchID INT, @BranchID INT, @UserID INT, @LocationDiviosnID INT

	SELECT 
		TOP 1 @CategoryID = PL.CATEGORYID
		, @SubCategoryID = CASE WHEN PL.CATEGORYID = 3 THEN 129 WHEN PL.CATEGORYID = 4 THEN 132 ELSE NULL END
		, @BranchID = PLD.BRANCHID, @UserID = PLD.CREATEDBY
		, @LocationDiviosnID = PLD.LOCATIONDIVISIONID
	FROM 
		PICKLIST PL
		INNER JOIN PICKLISTDISPATCH PLD ON PLD.LOCATIONDIVISIONID = PL.LOCATIONDIVISIONID
	WHERE 
		PLD.PICKLISTDISPATCHID = @PicklistDispatchID
		AND PL.PICKLISTSTATUS = 19 --Seggregated

	INSERT INTO STOCKDISPATCH(FROMBRANCHID, TOBRANCHID, STATUS, CREATEDBY, CREATEDDATE, CATEGORYID, SUBCATEGORYID)
	SELECT 45, @BranchID, 0, @UserID, GETDATE(), @CategoryID, @SubCategoryID

	SELECT @StockDispatchID = SCOPE_IDENTITY()

	INSERT INTO TRAYINFO(STOCKDISPATCHID, TRAYNUMBER, ISACCEPTED, CREATEDBY, CREATEDATE)
	SELECT DISTINCT @StockDispatchID, PLDD.TRAYNUMBER, 0, @UserID, GETDATE()
	FROM PICKLISTDISPATCHDETAIL PLDD
	WHERE
		PLDD.DELETEDDATE IS NULL
		AND PLDD.PICKLISTDISPATCHID = @PicklistDispatchID
		
	INSERT INTO STOCKDISPATCHDETAIL(STOCKDISPATCHID, ITEMPRICEID, TRAYNUMBER, DISPATCHQUANTITY, RECEIVEDQUANTITY, WEIGHTINKGS, CREATEDDATE, TRAYINFOID, ISVERIFIED, ISTRAYVERIFIED)
	SELECT @StockDispatchID, IP.ITEMPRICEID, PLDD.TRAYNUMBER, PLDD.QUANTITY, PLDD.QUANTITY, 0.00, GETDATE(), TI.TRAYINFOID, 0, 0
	FROM
		PICKLISTDISPATCHDETAIL PLDD
		INNER JOIN ITEMPRICE IP ON IP.ITEMCODEID = PLDD.ITEMCODEID AND IP.MRP = PLDD.MRP
		INNER JOIN TRAYINFO TI ON TI.TRAYNUMBER = PLDD.TRAYNUMBER AND TI.STOCKDISPATCHID = @StockDispatchID
	WHERE
		PLDD.DELETEDDATE IS NULL
		AND PLDD.PICKLISTDISPATCHID = @PicklistDispatchID
		AND IP.DELETEDDATE IS NULL
		AND IP.BRANCHID IS NULL
		
	EXEC USP_U_STOCKDISPATCH @StockDispatchID, @BranchID

	SELECT PLB.PICKLISTBRANCHID, PLB.PICKLISTID
	INTO #PLB
	FROM 
		PICKLISTBRANCH PLB
		INNER JOIN PICKLIST PL ON PL.PICKLISTID = PLB.PICKLISTID
	WHERE 
		PLB.BRANCHID = @BranchID
		AND PLB.PICKEDSTATUS = 19 --Seggregated
		AND PLB.DELETEDDATE IS NULL
		AND PL.LOCATIONDIVISIONID = @LocationDiviosnID

	DECLARE @EndCount INT

	SELECT @EndCount = COUNT(1) FROM #PLB

	UPDATE PLD
	SET STOCKDISPATCHID = @StockDispatchID, ENDPLCOUNT = @EndCount
	FROM PICKLISTDISPATCH PLD
	WHERE PLD.PICKLISTDISPATCHID = @PicklistDispatchID

	UPDATE PLBMAIN
	SET PICKEDSTATUS = 20 --Dispatched
		, PICKLISTDISPATCHID = @PicklistDispatchID
	FROM 
		PICKLISTBRANCH PLBMAIN
		INNER JOIN #PLB PLB ON PLB.PICKLISTBRANCHID = PLBMAIN.PICKLISTBRANCHID

	UPDATE PL
	SET PICKLISTSTATUS = 20 -- Dispatched
		, UPDATEDDATE = GETDATE()
	FROM
		PICKLIST PL
		INNER JOIN #PLB PLB ON PLB.PICKLISTID = PL.PICKLISTID
	WHERE
		NOT EXISTS
		(
			SELECT 1 
			FROM PICKLIST PLINNER
			WHERE PLINNER.PICKLISTID = PL.PICKLISTID
				AND PLINNER.PICKLISTSTATUS <> 20 
		)

	SELECT @PicklistDispatchID

END
GO
