/****** Object:  StoredProcedure [dbo].[USP_U_SKU_GST]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[USP_U_SKU_GST]
@ITEMID INT,
@GSTID INT,
@USERID  INT,
@Immediate BIT,
@GoLiveDate DATETIME = NULL
AS  
BEGIN  
  
	SELECT IP.*, @GSTID AS NewGSTID, 0 AS NEWITEMPRICEID  
	INTO #IPGSTUpdate
	FROM ITEM I
		INNER JOIN ITEMCODE IC ON I.ITEMID = IC.ITEMID  
		INNER JOIN ITEMPRICE IP ON IC.ITEMCODEID = IP.ITEMCODEID  
	WHERE I.ITEMID = @ITEMID 
		AND IC.DELETEDDATE IS NULL 
		AND IP.DELETEDDATE IS NULL 
		AND IP.BRANCHID IS NULL  
 
	DECLARE @CREATEDATE DATETIME = GETDATE()
 
	INSERT INTO ITEMPRICE(ITEMCODEID, MRP, SALEPRICE, GSTID, CREATEDBY, CREATEDDATE, [IMMEDIATE])  
	SELECT GSTU.ITEMCODEID, GSTU.MRP, GSTU.SALEPRICE, GSTU.NewGSTID, @USERID, @CREATEDATE,@Immediate
	FROM #IPGSTUpdate GSTU  
  
	UPDATE GSTU   
	SET NEWITEMPRICEID = IP.ITEMPRICEID  
	FROM #IPGSTUpdate GSTU
	INNER JOIN ITEMPRICE IP ON GSTU.ITEMCODEID = IP.ITEMCODEID AND GSTU.MRP = IP.MRP AND GSTU.SALEPRICE = IP.SALEPRICE  
	WHERE IP.DELETEDDATE IS NULL AND IP.BRANCHID IS NULL AND IP.CREATEDDATE = @CREATEDATE 
   
	INSERT INTO ITEMCOSTPRICE(ITEMPRICEID,COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,CREATEDBY,CREATEDDATE)  
	SELECT ICPINNER.NEWITEMPRICEID, COSTPRICEWT,COSTPRICEWOT,QUANTITY,WEIGHTINKGS,GSTID,@USERID,@CREATEDATE FROM   
	(  
		SELECT GSTU.ITEMPRICEID, GSTU.NEWITEMPRICEID, MAX(ITEMCOSTPRICEID) AS ITEMCOSTPRICEID  
		FROM #IPGSTUpdate GSTU
			INNER JOIN ITEMCOSTPRICE ICP ON GSTU.ITEMPRICEID = ICP.ITEMPRICEID  
		WHERE ICP.DELETEDDATE IS NULL  
		GROUP BY GSTU.ITEMPRICEID, GSTU.NEWITEMPRICEID  
	) ICPINNER   
	INNER JOIN ITEMCOSTPRICE ICP ON ICPINNER .ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID   

	UPDATE ITEM SET GSTID = @GSTID, UPDATEDBY = @USERID, UPDATEDATE = GETDATE() WHERE ITEMID = @ITEMID
  
	INSERT INTO STOCKMOVE(OLDITEMPRICEID, NEWITEMPRICEID, STOCKADJUSTMENTTYPEID, GOLIVEDATE, CREATEDBY, CREATEDDATE, REASON)  
	SELECT ITEMPRICEID, NEWITEMPRICEID, 6, @GoLiveDate, @USERID, @CREATEDATE, 'GST update by user' FROM #IPGSTUpdate

	SELECT @ITEMID
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_SPLIT_BRQUANTITY]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
