CREATE PROCEDURE [dbo].[USP_U_SPLIT_BRQUANTITY]
@BRDID INT,
@BASEQUANTITY INT,
@BASEREASON INT,
@DEVIDEDQUANTITY INT,
@DEVIDEDREASON INT,
@UserID int,
@SNO INT
AS
BEGIN

	UPDATE POS_BREFUNDDETAIL 
	SET 
		REASONID = @BASEREASON,
		QUANTITY = @BASEQUANTITY,
		UPDATEDBY = @UserID,
		UPDATEDDATE = GETDATE()
	WHERE BRDID = @BRDID

	INSERT INTO POS_BREFUNDDETAIL
	(
		BREFUNDDETAILID,BREFUNDID,ITEMPRICEID,QUANTITY,WEIGHTINKGS,CREATEDDATE,SNO,
		TRAYNUMBER,COUNTERID,REASONID,SUPPLIERID,ITEMCOSTPRICEID
	)
	SELECT 
		BREFUNDDETAILID,BREFUNDID,ITEMPRICEID,@DEVIDEDQUANTITY,WEIGHTINKGS,CREATEDDATE,@SNO,
		TRAYNUMBER,COUNTERID,@DEVIDEDREASON,SUPPLIERID,ITEMCOSTPRICEID
	FROM POS_BREFUNDDETAIL WHERE BRDID = @BRDID

END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_SPLIT_BRQUANTITY_1]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
