GO
CREATE PROCEDURE [dbo].[USP_U_SPLIT_BRQUANTITY_1]
@BRDID INT,
@BASEQUANTITY INT,
@BASEREASON INT,
@DEVIDEDQUANTITY INT,
@DEVIDEDREASON INT,
@UserID int,
@SNO INT
AS
BEGIN

	UPDATE POS_BREFUNDDETAIL 
	SET 
		REASONID = @BASEREASON,
		QUANTITY = @BASEQUANTITY,
		UPDATEDBY = @UserID,
		UPDATEDDATE = GETDATE()
	WHERE BRDID = @BRDID

	INSERT INTO POS_BREFUNDDETAIL(BRID,ITEMPRICEID,QUANTITY,WEIGHTINKGS,CREATEDDATE,SNO,TRAYNUMBER,REASONID,REFUNDDESCRIPTION)
		SELECT BRID,ITEMPRICEID,@DEVIDEDQUANTITY,WEIGHTINKGS,GETDATE(),@SNO,TRAYNUMBER ,@DEVIDEDREASON, REFUNDDESCRIPTION
		FROM POS_BREFUNDDETAIL WHERE BRDID = @BRDID

END
