CREATE PROCEDURE [dbo].[USP_U_STOCKCOUNTING_NEW]  
@BRANCHID INT  , 
@SelectedCategories VARCHAR(MAX),
@UserID int,
@dt ACCEPTCOUNTINGTYPE READONLY
AS  
BEGIN  
	
	IF EXISTS(SELECT 1 FROM STOCKCOUNTING WHERE BRANCHID = @BRANCHID AND ISNULL(STATUS, 0) = 0 AND DELETEDDATE IS NULL)  
	BEGIN  
		SELECT 'Pending sheets exists! The operation is cancelled. Submit all sheets for updating stock summary.'  
		RETURN  
	END  
  
	IF NOT EXISTS(SELECT 1 FROM STOCKCOUNTING WHERE BRANCHID = @BRANCHID AND ISNULL(STATUS, 0) = 1 AND DELETEDDATE IS NULL)  
	BEGIN  
		SELECT 'No Counting sheets exists!'  
		RETURN  
	END  

	IF EXISTS(SELECT 1 FROM POS_DAYCLOSURE DC INNER JOIN BRANCHCOUNTER BC ON BC.COUNTERID = DC.BRANCHCOUNTERID WHERE BRANCHID = @BRANCHID AND ISNULL(DC.ISPROCESSED, 0) = 0)  
	BEGIN  
		SELECT 'Pending day closures exists! The operation is cancelled. Check sync services or manually process day closures to continue.'  
		RETURN  
	END  
  
	SELECT ITEM AS SUBCATEGORYID
	INTO #SubCategories
	FROM dbo.SplitString(@SelectedCategories, ',')

	IF(@BRANCHID <> 45 AND EXISTS   
		(  
			SELECT 1   
			FROM   
				STOCKCOUNTING SC   
				INNER JOIN STOCKCOUNTINGDETAIL SCD ON SCD.STOCKCOUNTINGID = SC.STOCKCOUNTINGID  
				INNER JOIN  ITEMPRICE IP ON SCD.ITEMPRICEID = IP.ITEMPRICEID  
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID  
				INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID   
				INNER JOIN #SubCategories SCAT ON SCAT.SUBCATEGORYID = I.SUBCATEGORYID
			WHERE  
				SC.BRANCHID = @BRANCHID  
				AND SCD.DELETEDDATE IS NULL  
				AND SC.DELETEDDATE IS NULL  
				AND SC.STATUS = 2     
		))  
	BEGIN  
		SELECT '[Multiple sub categories] One or more sub categories in the counting are already accepted! counting data needs to be corrected. The operation has been cancelled'  
		RETURN  
	END  

	DECLARE @COUNTINGAPPROVALID INT = 0
	INSERT INTO COUNTINGAPPROVAL(BRANCHID, CREATEDBY, CREATEDDATE)
	VALUES(@BRANCHID, @UserID, GETDATE())
	SET @COUNTINGAPPROVALID = SCOPE_IDENTITY()

	UPDATE STOCKCOUNTING SET COUNTINGAPPROVALID = @COUNTINGAPPROVALID
		WHERE BRANCHID = @BRANCHID  
			AND ISNULL(STATUS, 0) = 1  
			AND DELETEDDATE IS NULL  
	
	
	INSERT INTO COUNTINGAPPROVALCATEGORYMAP(COUNTINGAPPROVALID, CATEGORYID, SUBCATEGORYID, CREATEDBY, CREATEDDATE)
	SELECT @COUNTINGAPPROVALID, SCAT.CATEGORYID, SCATTEMP.SUBCATEGORYID, @UserID, GETDATE() FROM #SubCategories SCATTEMP
	INNER JOIN SUBCATEGORY SCAT ON SCATTEMP.SUBCATEGORYID = SCAT.SUBCATEGORYID

	INSERT INTO COUNTINGAPPROVALITEM(COUNTINGAPPROVALID,ITEMPRICEID, PHYSICALQAUNTITY, 
		PHYSICALWEIGHTINKGS, SYSTEMQUANTITY,SYSTEMWEIGHTINKGS, CREATEDBY, CREATEDDATE,
		FIRSTCOUNTINGDATE,LASTCOUNTINGDATE,SALES,CREFUND,BREFUND,DISPATCH,FINALQUANTITY, SALESBETWEEN, CREFUNDBETWEEN)

	SELECT @COUNTINGAPPROVALID, ISNULL(IP.STOCKMOVETOID, IP.ITEMPRICEID), --dt.ITEMPRICEID , 
		CASE WHEN I.ISOPENITEM = 0 THEN COUNTEDQUANTITY ELSE 0 END,
		CASE WHEN I.ISOPENITEM = 1 THEN COUNTEDQUANTITY ELSE 0 END,
		CASE WHEN I.ISOPENITEM = 0 THEN SYSTEMQUANTITY ELSE 0 END,
		CASE WHEN I.ISOPENITEM = 1 THEN SYSTEMQUANTITY ELSE 0 END,
		@UserID, GETDATE(),FIRSTCOUNTINGDATE, LASTCOUNTNGDATE, 
		SALES, CREFUND, BREFUND, DISPATCH, FINALQUANTITY ,SALESBETWEEN, CREFUNDBETWEEN
	FROM @dt dt
		INNER JOIN ITEMPRICE IP ON DT.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	
	UPDATE SS   
	SET   
		SS.QUANTITY = CAI.PHYSICALQAUNTITY,  
		SS.WEIGHTINKGS = CAI.PHYSICALWEIGHTINKGS,  
		SS.TTYPE = 'SC', SS.MODIFIEDDATE = GETDATE()  
	FROM STOCKSUMMARY SS
		INNER JOIN COUNTINGAPPROVALITEM CAI ON SS.ITEMPRICEID = CAI.ITEMPRICEID
	WHERE SS.BRANCHID = @BRANCHID AND CAI.COUNTINGAPPROVALID = @COUNTINGAPPROVALID
   
	UPDATE STOCKCOUNTING   
	SET STATUS = 2, ACCEPTEDBY = @UserID, STOCKACCEPTEDDATE = GETDATE()  
	WHERE BRANCHID = @BRANCHID AND ISNULL(STATUS, 0) = 1  

	UPDATE BRANCH
	SET FILTERMRPBYSTOCK = 1, ENABLESTOCKCOUNTING = 0, UPDATEDATE = GETDATE(), UPDATEDBY = @UserID
	WHERE BRANCHID = @BRANCHID
  
	SELECT @COUNTINGAPPROVALID  

END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_STOCKDISPATCH]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_STOCKDISPATCH]
@STOCKDISPATCHID INT                        ,
@TOBRANCHID INT = 0,
@Notes VARCHAR(MAX) = NULL
AS                        
BEGIN                        

	IF EXISTS  
	(  
		SELECT 1 FROM STOCKDISPATCH SD      
		WHERE ISNULL(SD.STATUS, 0) <> 0 AND SD.STOCKDISPATCHID = @STOCKDISPATCHID  
	)  
	BEGIN  
		SELECT 'Dispatch already completed'
		RETURN
	END  

	IF EXISTS  
	(  
		SELECT 1 FROM STOCKDISPATCH SD      
		WHERE SD.STOCKDISPATCHID = @STOCKDISPATCHID AND SD.DELETEDDATE IS NOT NULL
	)  
	BEGIN  
		SELECT 'Dispatch deleted, cannot proceed!!'
		RETURN
	END  

	IF NOT EXISTS  
	(  
		SELECT 1 FROM STOCKDISPATCHDETAIL SDD
		WHERE SDD.STOCKDISPATCHID = @STOCKDISPATCHID AND SDD.DELETEDDATE IS NULL
	)  
	BEGIN  
		SELECT 'Dispatch cannot be submitted without items!'
		RETURN
	END  

	IF EXISTS 
	(
		SELECT 1 
		FROM 
			STOCKDISPATCH SD 
			INNER JOIN BRANCH B ON B.BRANCHID = SD.TOBRANCHID
		WHERE 
			B.BRANCHID = @TOBRANCHID 
			AND ENABLESTOCKCOUNTING = 1
	)
	BEGIN
		SELECT 'Stock counting initiated for selected branch. Dispatch cannot be submitted'
		RETURN;
	END

	--DECLARE @CATEGORYID INT, @BRANCHID INT
	
	--SELECT @CATEGORYID = CATEGORYID, @BRANCHID = TOBRANCHID 
	--FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID

	--IF EXISTS
	--(
	--	SELECT 1 FROM TRAYINFO TI 
	--	WHERE TI.STOCKDISPATCHID = @STOCKDISPATCHID
	--	AND TI.DELETEDDATE IS NULL
	--	AND NOT EXISTS(
	--					SELECT 1 FROM STOCKDISPATCHDETAIL SDD 
	--						INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID 
	--					WHERE TI.TRAYINFOID = SDD.TRAYINFOID
	--						AND SD.TOBRANCHID = @BRANCHID 
	--						AND SD.CATEGORYID = @CATEGORYID 
	--						AND SD.DELETEDDATE IS NULL 
	--						AND SDD.DELETEDDATE IS NULL
	--						AND SD.STATUS <> 2
	--				)
	--)
	--BEGIN
		
	--	SELECT 'One or more trays don''t have any items, please delete unused trays to proceed!!'
	--	RETURN

	--END
		

	DECLARE @SUBMITDATE DATETIME = GETDATE()

	INSERT INTO STOCKDISPATCHSUBMITLOG(STOCKDISPATCHID, LOGTIME) SELECT @STOCKDISPATCHID, @SUBMITDATE

	EXEC USP_CHK_ENTITYLOCK 'Stock dispatch', @StockDispatchID, 0
  
	--Get branch details        
	DECLARE @FROMBRANCHID INT, @SNO INT, @BRANCHCODE VARCHAR(20)  
   
	SELECT   
		@FROMBRANCHID = FROMBRANCHID,   
		@TOBRANCHID = TOBRANCHID
	FROM STOCKDISPATCH   
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID              
   
	SELECT   
		@BRANCHCODE = BRANCHCODE, 
		@SNO = ISNULL(DISPATCHSNO, 0) + 1  
	FROM BRANCH   
	WHERE BRANCHID = @TOBRANCHID    
   
	--SELECT @SNO = ISNULL(MAX(SNO),0) + 1 FROM STOCKDISPATCH   

	UPDATE B  
	SET B.DISPATCHSNO = @SNO  
	FROM BRANCH B  
	WHERE B.BRANCHID = @TOBRANCHID   
  
	--Update stock stockdispatch status                        
	UPDATE STOCKDISPATCH SET   
		DISPATCHNUMBER = @BRANCHCODE + REPLACE(CONVERT(VARCHAR(10), @SUBMITDATE,111),'/','') +   
		RIGHT('0000000' + CAST(@SNO AS VARCHAR(10)),10),  
		SNO = @SNO,  
		TOBRANCHID = @TOBRANCHID,
		STATUS = 1,  
		CREATEDDATE = @SUBMITDATE,
		UPDATEDATE = @SUBMITDATE,
		NOTES = @Notes
	WHERE STOCKDISPATCHID = @STOCKDISPATCHID                        
  

	SELECT         
		SD.FROMBRANCHID,
		SD.TOBRANCHID,
		ISNULL(IP.STOCKMOVETOID, SDD.ITEMPRICEID) ITEMPRICEID,
		SDD.DISPATCHQUANTITY, 
		SDD.WEIGHTINKGS
	INTO #DISPATCHES
	FROM         
		STOCKDISPATCHDETAIL SDD
		INNER JOIN STOCKDISPATCH SD ON SDD.STOCKDISPATCHID = SD.STOCKDISPATCHID
		INNER JOIN ITEMPRICE IP ON IP.ITEMPRICEID = SDD.ITEMPRICEID
	WHERE SDD.STOCKDISPATCHID = @STOCKDISPATCHID
		AND	SDD.DELETEDDATE IS NULL  
        
	--updating warehosue stock        
	UPDATE SS  
	SET 
		SS.QUANTITY = ISNULL(SS.QUANTITY,0) - SDD.QUANTITY,        
		SS.WEIGHTINKGS = ISNULL(SS.WEIGHTINKGS,0) - SDD.WEIGHTINKGS      ,  
		SS.TTYPE = 'SD', SS.MODIFIEDDATE = @SUBMITDATE
	FROM STOCKSUMMARY SS        
		INNER JOIN          
		(
			SELECT SDD.ITEMPRICEID,  
				SUM(DISPATCHQUANTITY) AS QUANTITY,  
				SUM(WEIGHTINKGS) AS WEIGHTINKGS      
			FROM #DISPATCHES SDD
			GROUP BY SDD.ITEMPRICEID
		)SDD ON SS.ITEMPRICEID = SDD.ITEMPRICEID  
	WHERE SS.BRANCHID = @FROMBRANCHID        

	IF EXISTS(SELECT 1 FROM STOCKDISPATCH WHERE STOCKDISPATCHID = @STOCKDISPATCHID AND STATUS = 1)  
	BEGIN  
		SELECT @STOCKDISPATCHID  
	END  
	ELSE  
	BEGIN  
		SELECT 'Dispatch not saved'  
	END

	EXEC USP_CHK_ENTITYLOCK 'Stock dispatch', @StockDispatchID, 1
  
END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_STOCKDISPATCHDRAFTINFO]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[USP_U_STOCKDISPATCHDRAFTINFO]
    @STOCKDISPATCHID INT,
    @TOBRANCHID INT,
    @NOTES VARCHAR(MAX) = NULL,
    @USERID INT
AS
BEGIN


        DECLARE @STATUS VARCHAR(20);
        DECLARE @DELETEDDATE DATETIME;
        DECLARE @FROMBRANCHID INT;

        SELECT
            @STATUS = SD.STATUS,
            @DELETEDDATE = SD.DELETEDDATE,
            @FROMBRANCHID = SD.FROMBRANCHID
        FROM dbo.STOCKDISPATCH SD
        WHERE SD.STOCKDISPATCHID = @STOCKDISPATCHID;

        IF @FROMBRANCHID IS NULL
        BEGIN
            SELECT 'Dispatch does not exist';
            RETURN;
        END;

        IF @DELETEDDATE IS NOT NULL
        BEGIN
            SELECT 'Dispatch already discarded';
            RETURN;
        END;

        IF ISNULL(@STATUS, '0') <> '0'
        BEGIN
            SELECT 'Dispatch already submitted';
            RETURN;
        END;

        IF @TOBRANCHID IS NULL OR NOT EXISTS
        (
            SELECT 1
            FROM dbo.BRANCH B
            WHERE B.BRANCHID = @TOBRANCHID
        )
        BEGIN
            SELECT 'Invalid destination branch';
            RETURN;
        END;

        IF @FROMBRANCHID = @TOBRANCHID
        BEGIN
            SELECT 'From branch and to branch cannot be the same';
            RETURN;
        END;

        UPDATE dbo.STOCKDISPATCH
        SET TOBRANCHID = @TOBRANCHID,
            NOTES = @NOTES,
            UPDATEDBY = @USERID,
            UPDATEDATE = GETDATE()
        WHERE STOCKDISPATCHID = @STOCKDISPATCHID;

        SELECT @STOCKDISPATCHID;
END;
GO
/****** Object:  StoredProcedure [dbo].[USP_U_STOCKDISPATCHSTATUS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_STOCKDISPATCHSTATUS]
@BRANCHID INT,
@StockDispatchStatus bit,
@USERID INT
AS
BEGIN

	IF EXISTS(SELECT 1 FROM STOCKDISPATCH WHERE TOBRANCHID = @BRANCHID AND DELETEDDATE IS NULL AND ISNULL(STATUS,0) = 0 )
	BEGIN
		SELECT 'There are few dispatches which are in draft, Please discard or submit the same.'
		return;
	END

	UPDATE BRANCH SET ENABLESTOCKDISPATCH = @StockDispatchStatus, UPDATEDBY = @USERID, UPDATEDATE = GETDATE() WHERE BRANCHID = @BRANCHID

	select @BRANCHID

END
GO
