/****** Object:  StoredProcedure [dbo].[USP_U_STOCKENTRY_v2]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_STOCKENTRY_v2]
@STOCKENTRYID INT ,                
@SUPPLIERID INT = NULL,                
@SUPPLIERINVOICENO VARCHAR(30) = NULL,                
@INVOICEDATE DATE = NULL,
@TCS DECIMAL(10,2) = 0,                
@DISCOUNTFLAT DECIMAL(10,2) = 0,                
@EXPENSES DECIMAL(10,2) = 0,                
@TRANSPORT DECIMAL(10,2)= 0,
@PackingCharges DECIMAL(10,2)= 0,
@DispatchBranchId INT = 0,
@CATEGORYID INT = 0,
@USERID INT = 4,
@SupplierIndentID INT = NULL,
@Notes nvarchar(500) = '',
@dtcreditnotes dtInt__decimal_twocols readonly
AS                      
BEGIN                      

	------------------------------------------------------------
	-- Prevent updating an already completed invoice
	------------------------------------------------------------
	IF EXISTS
	(
		SELECT 1 
		FROM STOCKENTRY SE
		WHERE ISNULL(SE.STATUS, 0) = 1 
		AND SE.STOCKENTRYID = @STOCKENTRYID
	)
	BEGIN
		RAISERROR ('Invoice already completed', 16, 1)
		RETURN
	END

	DECLARE @RECEIVINGBRANCHID INT
	SELECT @RECEIVINGBRANCHID = RECEIVINGBRANCHID FROM STOCKENTRY WHERE STOCKENTRYID = @STOCKENTRYID
	
	------------------------------------------------------------
	-- Capture processing time for consistent audit tracking
	------------------------------------------------------------
	DECLARE @PROCCESSTIME DATETIME = GETDATE()

	------------------------------------------------------------
	-- Collect stock entry details with item and GST information
	-- into temporary table for processing
	------------------------------------------------------------
	SELECT 
		STOCKENTRYDETAILID, 
		SED.ITEMCODEID, 
		SED.QUANTITY,
		SED.WEIGHTINKGS,
		MRP, 
		SALEPRICE, 
		CPWITHOUTTAX, 
		CPWITHTAX, 
		INVOICECPWITHOUTTAX, 
		INVOICECPWITHTAX, 
		0 AS ITEMPRICEID, 
		0 AS ITEMCOSTPRICEID,
		SED.GSTID AS PURCHASEGSTID,
		I.GSTID AS SALEGSTID
	INTO #SED
	FROM STOCKENTRYDETAIL SED
		INNER JOIN ITEMCODE IC ON SED.ITEMCODEID = IC.ITEMCODEID
		INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
	WHERE STOCKENTRYID = @STOCKENTRYID
		AND SED.DELETEDDATE IS NULL

	------------------------------------------------------------
	-- Validate that all items have sale GST configured
	------------------------------------------------------------
	IF EXISTS (SELECT 1 FROM #SED WHERE SALEGSTID IS NULL)
	BEGIN
		RAISERROR ('Few SKU codes does not have GST, please check and update before submitting the invoice', 16, 1)
		RETURN;
	END

    ----------------------------------------------------------------
	-- Validate that all items have MRP and SalePrice greater than 0
	----------------------------------------------------------------
    IF EXISTS
    (
        SELECT 1
        FROM #SED
        WHERE ISNULL(MRP, 0) <= 0
        OR ISNULL(SALEPRICE, 0) <= 0
    )
    BEGIN
        RAISERROR('MRP and Sale Price must be greater than 0 for all items before submitting the invoice', 16, 1)
        RETURN;
    END

	
	----------------------------------------------------------------
	-- Validate duplicate MRPs
	----------------------------------------------------------------
	-- 1. Internal batch validation
	IF EXISTS
	(
		SELECT ITEMCODEID, MRP
		FROM #SED
		GROUP BY ITEMCODEID, MRP
		HAVING COUNT(DISTINCT SALEPRICE) > 1
	)
	BEGIN
		RAISERROR ('Multiple sale prices found for same MRP in input data', 16, 1)
		RETURN
	END

	-- 2. Existing SalePrice validation

	DECLARE @DuplicateItems VARCHAR(MAX)

	SELECT @DuplicateItems = STRING_AGG(ItemText, ', ')
	FROM
	(
		SELECT DISTINCT 
			CONCAT(IC.ITEMCODE, '(MRP:', SED.MRP, ')') AS ItemText
		FROM #SED SED
		INNER JOIN ITEMPRICE IP
			ON IP.ITEMCODEID = SED.ITEMCODEID
			AND IP.MRP = SED.MRP
			AND IP.DELETEDDATE IS NULL
			AND IP.BRANCHID IS NULL
		INNER JOIN ITEMCODE IC
			ON IC.ITEMCODEID = SED.ITEMCODEID
		WHERE IP.SALEPRICE <> SED.SALEPRICE
	) A

	IF @DuplicateItems IS NOT NULL
	BEGIN
		RAISERROR (
			'Same MRP already exists with a different sale price for ITEMCODEs: %s',
			16,
			1,
			@DuplicateItems
		)
		RETURN
	END

	-- 3. Existing GST validation
	DECLARE @DuplicateGSTItems VARCHAR(MAX)

	SELECT @DuplicateGSTItems = STUFF((
		SELECT ', ' + IC.ITEMCODE + '(' +
			STUFF((
				SELECT DISTINCT '/' + GD2.GSTCODE
				FROM ITEMPRICE IP2
				INNER JOIN GSTDETAIL GD2 ON GD2.GSTID = IP2.GSTID
				WHERE IP2.ITEMCODEID = IP.ITEMCODEID
				AND IP2.DELETEDDATE IS NULL
				AND IP2.BRANCHID IS NULL
				FOR XML PATH(''), TYPE
			).value('.', 'NVARCHAR(MAX)'), 1, 1, '') + ')'
		FROM #SED SED
		INNER JOIN ITEMPRICE IP
			ON IP.ITEMCODEID = SED.ITEMCODEID
			AND IP.DELETEDDATE IS NULL
			AND IP.BRANCHID IS NULL
		INNER JOIN ITEMCODE IC
			ON IC.ITEMCODEID = SED.ITEMCODEID
		WHERE IP.GSTID <> SED.SALEGSTID
		GROUP BY IC.ITEMCODE, IP.ITEMCODEID
		FOR XML PATH(''), TYPE
	).value('.', 'NVARCHAR(MAX)'), 1, 2, '')

	IF @DuplicateGSTItems IS NOT NULL
	BEGIN
		RAISERROR (
			'GST mismatch with base item for ItemCodes: %s',
			16,
			1,
			@DuplicateGSTItems
		)
		RETURN
	END

	DECLARE @SourceProcedure NVARCHAR(517) =
        QUOTENAME(OBJECT_SCHEMA_NAME(@@PROCID))
        + N'.'
        + QUOTENAME(OBJECT_NAME(@@PROCID));

    EXEC sys.sp_set_session_context
        @key = N'ITEMPRICE_SOURCE_PROC',
        @value = @SourceProcedure;

	------------------------------------------------------------
	-- Insert new sale price records if they do not already exist
	------------------------------------------------------------
	INSERT INTO ITEMPRICE
	(ITEMCODEID, MRP, SALEPRICE, GSTID, IMMEDIATE, CREATEDBY, CREATEDDATE)
	SELECT DISTINCT
		SED.ITEMCODEID, 
		SED.MRP, 
		SED.SALEPRICE, 
		SED.SALEGSTID, 
		1, 
		@USERID, 
		@PROCCESSTIME 
	FROM #SED SED 
	WHERE NOT EXISTS
	(
		SELECT 1 
		FROM ITEMPRICE IP 
		WHERE IP.ITEMCODEID = SED.ITEMCODEID
		AND IP.MRP = SED.MRP
		AND IP.SALEPRICE = SED.SALEPRICE
		AND IP.GSTID = SED.SALEGSTID
		AND IP.DELETEDDATE IS NULL
	)

	------------------------------------------------------------
	-- Update temp table with ITEMPRICEID for each item
	------------------------------------------------------------
	UPDATE SED 
	SET SED.ITEMPRICEID = IP.ITEMPRICEID
	FROM #SED SED
		INNER JOIN ITEMPRICE IP 
			ON SED.ITEMCODEID = IP.ITEMCODEID 
			AND SED.MRP = IP.MRP
			AND SED.SALEPRICE = IP.SALEPRICE
			AND SED.SALEGSTID = IP.GSTID
	WHERE IP.DELETEDDATE IS NULL 
	AND IP.BRANCHID IS NULL

	------------------------------------------------------------
	-- Insert new cost price records if they do not exist
	------------------------------------------------------------
	INSERT INTO ITEMCOSTPRICE
	(
		ITEMPRICEID,
		COSTPRICEWT,
		COSTPRICEWOT,
		QUANTITY,
		WEIGHTINKGS,
		GSTID,
		CREATEDBY,
		CREATEDDATE
	)
	SELECT DISTINCT
		SED.ITEMPRICEID, 
		SED.CPWITHTAX, 
		SED.CPWITHOUTTAX, 
		0, 
		0,
		SED.PURCHASEGSTID, 
		@USERID, 
		@PROCCESSTIME
	FROM #SED SED 
	WHERE NOT EXISTS
	(
		SELECT 1 
		FROM ITEMCOSTPRICE ICP 
		WHERE ICP.ITEMPRICEID = SED.ITEMPRICEID
		AND ICP.COSTPRICEWT = SED.CPWITHTAX
		AND ICP.COSTPRICEWOT = SED.CPWITHOUTTAX
		AND ICP.GSTID = SED.PURCHASEGSTID
		AND ICP.DELETEDDATE IS NULL
	)

	------------------------------------------------------------
	-- Map ITEMCOSTPRICEID back to temporary table
	------------------------------------------------------------
	UPDATE SED 
	SET SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
	FROM #SED SED
		INNER JOIN ITEMCOSTPRICE ICP 
			ON SED.ITEMPRICEID = ICP.ITEMPRICEID
			AND SED.CPWITHTAX = ICP.COSTPRICEWT
			AND SED.CPWITHOUTTAX = ICP.COSTPRICEWOT
			AND SED.PURCHASEGSTID = ICP.GSTID
	WHERE ICP.DELETEDDATE IS NULL

	------------------------------------------------------------
	-- Update stock quantity and weight in ITEMCOSTPRICE
	------------------------------------------------------------
	UPDATE ICP
	SET 
		ICP.GROSSCOSTPRICEWT = SED.INVOICECPWITHTAX,
		ICP.GROSSCOSTPRICEWOT = SED.INVOICECPWITHOUTTAX,
		ICP.QUANTITY = ICP.QUANTITY + SED.QUANTITY,
		ICP.WEIGHTINKGS = ICP.WEIGHTINKGS + SED.WEIGHTINKGS
	FROM ITEMCOSTPRICE ICP
		INNER JOIN #SED SED 
			ON ICP.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID

	------------------------------------------------------------
	-- Update STOCKENTRYDETAIL with ITEMCOSTPRICEID
	------------------------------------------------------------
	UPDATE SED
	SET SED.ITEMCOSTPRICEID = SEDINNER.ITEMCOSTPRICEID
	FROM STOCKENTRYDETAIL SED
		INNER JOIN #SED SEDINNER 
			ON SED.STOCKENTRYDETAILID = SEDINNER.STOCKENTRYDETAILID
	WHERE SED.DELETEDDATE IS NULL

	------------------------------------------------------------
	-- Update main STOCKENTRY record and mark invoice as submitted
	------------------------------------------------------------
	UPDATE STOCKENTRY 
	SET 
		SUPPLIERID = ISNULL(@SUPPLIERID, SUPPLIERID),
		SUPPLIERINVOICENO = ISNULL(@SUPPLIERINVOICENO, SUPPLIERINVOICENO),
		INVOICEDATE = ISNULL(@INVOICEDATE, INVOICEDATE),
		STATUS = 1,                
		TCS = @TCS,                
		DISCOUNT = @DISCOUNTFLAT,                
		EXPENSES = @EXPENSES,                
		TRANSPORT = CASE WHEN LorryFrightMode = 1 THEN @TRANSPORT ELSE -@TRANSPORT END,
		PackingCharges = @PackingCharges,
		UPDATEDBY = @USERID,
		UPDATEDATE = @PROCCESSTIME,
		SUBMITTEDBY = @USERID,
		SUBMITTEDDATE = @PROCCESSTIME,
		SUPPLIERINDENTID = ISNULL(@SupplierIndentID,SUPPLIERINDENTID),
		Notes = @Notes
	WHERE STOCKENTRYID = @STOCKENTRYID  

	------------------------------------------------------------
	-- Prepare supplier-item mapping dataset
	------------------------------------------------------------
	SELECT DISTINCT 
		SE.SUPPLIERID, 
		IC.ITEMID, 
		IC.ITEMCODEID, 
		IP.ITEMPRICEID, 
		SED.ITEMCOSTPRICEID, 
		SE.STOCKENTRYID 
	INTO #SEDTEAIL 
	FROM STOCKENTRY SE
		INNER JOIN STOCKENTRYDETAIL SED ON SE.STOCKENTRYID = SED.STOCKENTRYID
		INNER JOIN ITEMCOSTPRICE ICP ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID
		INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
		INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
	WHERE SE.STOCKENTRYID = @STOCKENTRYID 
		AND SED.DELETEDDATE IS NULL 
		AND ISNULL(SE.STATUS,0) = 1

	------------------------------------------------------------
	-- Update existing supplier-item mappings
	------------------------------------------------------------
	UPDATE ISM 
	SET 
		ISM.ITEMCODEID = SED.ITEMCODEID,
		ISM.ITEMPRICEID = SED.ITEMPRICEID,
		ISM.ITEMCOSTPRICEID = SED.ITEMCOSTPRICEID,
		ISM.STOCKENTRYID = SED.STOCKENTRYID,
		ISM.UPDATEDBY = @USERID,
		ISM.UPDATEDDATE = @PROCCESSTIME
	FROM ITEMSUPPLIERMAP ISM
		INNER JOIN #SEDTEAIL SED 
			ON SED.SUPPLIERID = ISM.SUPPLIERID 
			AND SED.ITEMID = ISM.ITEMID
	WHERE ISM.DELETEDDATE IS NULL

	------------------------------------------------------------
	-- Insert supplier-item mapping if not exists
	------------------------------------------------------------
	INSERT INTO ITEMSUPPLIERMAP
	(
		SUPPLIERID,
		ITEMID,
		ITEMCODEID,
		ITEMPRICEID,
		ITEMCOSTPRICEID,
		STOCKENTRYID,
		CREATEDBY,
		CREATEDDATE,
		LASTRECEIVEDDATE
	)
	SELECT 
		SED.SUPPLIERID,
		SED.ITEMID,
		MAX(SED.ITEMCODEID) AS ITEMCODEID,
		MAX(SED.ITEMPRICEID) AS ITEMPRICEID,
		MAX(SED.ITEMCOSTPRICEID) AS ITEMCOSTPRICEID,
		MAX(SED.STOCKENTRYID) AS STOCKENTRYID,
		@USERID,
		@PROCCESSTIME,
		@INVOICEDATE
	FROM #SEDTEAIL SED
	WHERE NOT EXISTS
	(
		SELECT 1 
		FROM ITEMSUPPLIERMAP ISMINNER
		WHERE ISMINNER.SUPPLIERID = SED.SUPPLIERID
		AND ISMINNER.ITEMID = SED.ITEMID
		AND ISMINNER.DELETEDDATE IS NULL
	)
	GROUP BY 
		SED.SUPPLIERID,
		SED.ITEMID

	INSERT INTO STOCKENTRYCREDITNOTEMAP
	(
		STOCKENTRYID, CREDITNOTEID, CREATEDBY, CREATEDDATE, MappedReturnValue
	)
	SELECT 
		@STOCKENTRYID, ID, @USERID, @PROCCESSTIME, valuecol
	FROM @dtcreditnotes

	------------------------------------------------------------
	-- Update stock summary quantities for branch
	------------------------------------------------------------
	UPDATE SS    
	SET 
		SS.QUANTITY = CASE WHEN SED.ISOPENITEM = 0 THEN SS.QUANTITY + SED.QUANTITY ELSE SS.QUANTITY END,
		SS.WEIGHTINKGS = CASE WHEN SED.ISOPENITEM = 1 THEN SS.WEIGHTINKGS + SED.WEIGHTINKGS ELSE SS.WEIGHTINKGS END,
		SS.TTYPE = 'SE', 
		SS.MODIFIEDDATE = @PROCCESSTIME
	FROM STOCKSUMMARY SS 
		INNER JOIN 
		(
			SELECT 
				ICP.ITEMPRICEID, 
				I.ISOPENITEM,
				SUM(SED.QUANTITY + ISNULL(SED.FREEQUANTITY,0)) AS QUANTITY,
				SUM(SED.WEIGHTINKGS) AS WEIGHTINKGS     
			FROM STOCKENTRYDETAIL SED      
				INNER JOIN ITEMCOSTPRICE ICP ON SED.ITEMCOSTPRICEID = ICP.ITEMCOSTPRICEID    
				INNER JOIN ITEMPRICE IP ON ICP.ITEMPRICEID = IP.ITEMPRICEID
				INNER JOIN ITEMCODE IC ON IP.ITEMCODEID = IC.ITEMCODEID
				INNER JOIN ITEM I ON IC.ITEMID = I.ITEMID
			WHERE STOCKENTRYID = @STOCKENTRYID 
				AND SED.DELETEDDATE IS NULL 
			GROUP BY ICP.ITEMPRICEID, I.ISOPENITEM
		) SED ON SS.ITEMPRICEID = SED.ITEMPRICEID
	WHERE SS.BRANCHID = @RECEIVINGBRANCHID
	
	------------------------------------------------------------
	-- Return processed stock entry ID
	------------------------------------------------------------
	SELECT @STOCKENTRYID

	------------------------------------------------------------
	-- Trigger stock dispatch if @DispatchBranchId exists
	------------------------------------------------------------
	

	IF @ReceivingBranchID = 45
	   AND EXISTS
	   (
		   SELECT 1
		   FROM BRANCH
		   WHERE BRANCHID = @DispatchBranchId
			 AND ISWAREHOUSE = 0
			 AND DELETEDDATE IS NULL
	   )
	BEGIN
		IF(@DispatchBranchId <> 0)
		BEGIN
			EXEC USP_CU_STOCKDISPATCH_BRANCH 
				@STOCKENTRYID, 
				0, 
				45, 
				@DispatchBranchId, 
				@CATEGORYID, 
				@USERID
		END
	END
    
END
GO
/****** Object:  StoredProcedure [dbo].[USP_U_SUPPLIERCOSTPRICE]    Script Date: 17-10-2026 13:04:47 ******/
