CREATE PROCEDURE [dbo].[USP_U_SUPPLIERCOSTPRICE]
@BRDID INT,
@SupplierID int,
@ItemCostPriceID int,
@UserID int
AS
BEGIN

	UPDATE POS_BREFUNDDETAIL 
	SET 
		SUPPLIERID = @SupplierID, 
		ITEMCOSTPRICEID = @ItemCostPriceID,
		UPDATEDBY = @UserID,
		UPDATEDDATE = GETDATE()
	WHERE BRDID = @BRDID

END
