/****** Object:  StoredProcedure [dbo].[USP_U_SUPPLIERRETURNS]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[USP_U_SUPPLIERRETURNS]
(
    @SupplierReturnsID INT,
    @UserID INT,
    @dt dtInts_twocols READONLY,
    @STATUS INT 
)
AS
BEGIN
    SET NOCOUNT ON;

    /* Update detail rows */
    UPDATE SRD
    SET SRD.RETURNSTATUS = DT.valuecol
    FROM SUPPLIERRETURNSDETAIL SRD
    INNER JOIN @dt DT
        ON SRD.SUPPLIERRETURNSDETAILID = DT.ID;

    /* Update header */
    UPDATE SUPPLIERRETURNS
    SET
        STATUS = @STATUS,
        UPDATEDBY = @UserID,
        UPDATEDDATE = GETDATE()
    WHERE SUPPLIERRETURNSID = @SupplierReturnsID;

END;
GO
