CREATE PROC [dbo].[USP_UD_DEALER]
@DEALERID INT,
@USERID INT
AS
BEGIN

	UPDATE TBLDEALER 
	SET 
		DELETEDBY =  NULL,
		DELETEDDATE = NULL
		WHERE DEALERID = @DEALERID AND DELETEDDATE IS NOT NULL

