/****** Object:  StoredProcedure [dbo].[USP_UD_ITEMPRICE]    Script Date: 17-10-2026 13:04:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROC [dbo].[USP_UD_ITEMPRICE]
(
@ITEMPRICEID INT,
@USERID INT
)
AS
BEGIN

	DECLARE @ItemCodeID INT, @MRP DECIMAL(18, 2)

	SELECT @ItemCodeID = ITEMCODEID, @MRP = MRP
	FROM ITEMPRICE
	WHERE ITEMPRICEID = @ITEMPRICEID

	IF EXISTS
		(
			SELECT 1
			FROM ITEMPRICE IP
			WHERE 
				IP.ITEMCODEID = @ItemCodeID 
				AND IP.MRP = @MRP
				AND IP.DELETEDDATE IS NULL
				AND IP.BRANCHID IS NULL
				AND IP.ITEMPRICEID <> @ITEMPRICEID
		)
	BEGIN
		SELECT REPLACE('MRP {0} still active with another sale price, un-delete is not possible', '{0}', @MRP)
		RETURN
	END

	UPDATE ITEMPRICE
	SET DELETEDBY = NULL, DELETEDDATE = NULL, UPDATEDBY = @USERID, UPDATEDATE =  GETDATE()
	WHERE ITEMPRICEID = @ITEMPRICEID

	SELECT @ITEMPRICEID

END
GO
