CREATE TRIGGER [dbo].[INSERTSSIP]
ON [dbo].[ITEMPRICE]
AFTER INSERT
AS 
BEGIN
	
	INSERT INTO STOCKSUMMARY(BRANCHID, ITEMPRICEID, QUANTITY, WEIGHTINKGS, TTYPE, MODIFIEDDATE)  
	SELECT B.BRANCHID, INS.ITEMPRICEID, 0,  0.00, 'IP', GETDATE() FROM BRANCH B
		CROSS APPLY INSERTED INS
	WHERE B.DELETEDDATE IS NULL AND INS.BRANCHID IS NULL
		
END
GO
ALTER TABLE [dbo].[ITEMPRICE] ENABLE TRIGGER [INSERTSSIP]
