CREATE TRIGGER [dbo].[TRG_ITEMPRICE_INSERT_AUDIT]
ON [dbo].[ITEMPRICE]
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @SourceProcedure NVARCHAR(517) =
        TRY_CONVERT(
            NVARCHAR(517),
            SESSION_CONTEXT(N'ITEMPRICE_SOURCE_PROC')
        );

    INSERT INTO dbo.ITEMPRICE_INSERT_AUDIT
    (
        ITEMPRICEID,
        SOURCEPROCEDURE,
        CREATEDBY,
        AUDITDATE
    )
    SELECT
        I.ITEMPRICEID,
        @SourceProcedure,
        I.CREATEDBY,
        GETDATE()
    FROM inserted AS I;
END;
GO
ALTER TABLE [dbo].[ITEMPRICE] ENABLE TRIGGER [TRG_ITEMPRICE_INSERT_AUDIT]
