/****** Object:  Trigger [dbo].[TRG_STOCKDISPATCHDETAIL_LOG]    Script Date: 17-10-2026 13:04:48 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[TRG_STOCKDISPATCHDETAIL_LOG]
ON [dbo].[STOCKDISPATCHDETAIL]
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM deleted)
       AND NOT (UPDATE(DISPATCHQUANTITY) OR UPDATE(WEIGHTINKGS))
       RETURN;

    INSERT INTO dbo.STOCKDISPATCHDETAILLOG
    (
        STOCKDISPATCHDETAILID,
        DISPATCHQUANTITY,
        RECEIVEDQUANTITY,
        WEIGHTINKGS,
        CREATEDDATE,
        UPDATEDATE,
        DELETEDDATE,
        LOGCREATEDDATE
    )
    SELECT
        i.STOCKDISPATCHDETAILID,
        i.DISPATCHQUANTITY,
        i.RECEIVEDQUANTITY,
        i.WEIGHTINKGS,
        i.CREATEDDATE,
        i.UPDATEDATE,
        i.DELETEDDATE,
        GETDATE()
    FROM inserted i
    LEFT JOIN deleted d
        ON d.STOCKDISPATCHDETAILID = i.STOCKDISPATCHDETAILID
    WHERE
        d.STOCKDISPATCHDETAILID IS NULL
        OR ISNULL(i.DISPATCHQUANTITY, 0) <> ISNULL(d.DISPATCHQUANTITY, 0)
        OR ISNULL(i.WEIGHTINKGS, 0) <> ISNULL(d.WEIGHTINKGS, 0);
END;
GO
ALTER TABLE [dbo].[STOCKDISPATCHDETAIL] ENABLE TRIGGER [TRG_STOCKDISPATCHDETAIL_LOG]
GO
