CREATE TRIGGER [dbo].[UPDATESTOCKSUMMARYLOG]
ON [dbo].[STOCKSUMMARY]
AFTER UPDATE
AS 
BEGIN

	INSERT INTO STOCKSUMMARYLOG(STOCKSUMMARYID, QUANTITY, WEIGHTINKGS, CREATEDDATE, TTYPE, OLDQTY, OLDWEIGHT,MODIFIEDDATE)
	SELECT INS.STOCKSUMMARYID,INS.QUANTITY,INS.WEIGHTINKGS,GETDATE(),INS.TTYPE, DLT.QUANTITY, DLT.WEIGHTINKGS,INS.MODIFIEDDATE 
	FROM INSERTED INS
		INNER JOIN deleted DLT ON DLT.STOCKSUMMARYID = INS.STOCKSUMMARYID
		
END
GO
ALTER TABLE [dbo].[STOCKSUMMARY] ENABLE TRIGGER [UPDATESTOCKSUMMARYLOG]
GO
